INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('319287b1-1c29-4758-80be-af97f4ed5b2a'::uuid, '3 Leg Chatarunga Pose', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start in a plank position with your hands shoulder-width apart and feet hip-width apart.\r\n2. Lift your right leg straight back and up, keeping your hips level.\r\n3. Shift your body forward into a plank position while keeping the right leg lifted.\r\n4. Lower your body towards the floor by bending your elbows close to your sides, maintaining a straight line from head to left heel. Return to the plank position and repeat on the left side.', E'1. Engage your core to maintain balance and stability throughout the movement.\r\n2. Keep your elbows close to your body to protect your shoulders.\r\n3. Breathe steadily, inhaling as you lower and exhaling as you push back up.', '{"image_male_start":"images/Yoga/3 Leg Chatarunga Pose_female.jpg","image_female_start":"images/Yoga/3 Leg Chatarunga Pose_female.jpg","image_female_end":"images/Yoga/3 Leg Chatarunga Pose_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e8b8c68e-c90a-4213-9567-ccd42748a411'::uuid, '3 Leg Dog Pose', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start in a downward-facing dog position with your hands shoulder-width apart and feet hip-width apart.\r\n2. Lift your right leg straight back and up, keeping your hips level and ensuring your body forms a straight line from your wrists to your raised foot.\r\n3. Hold the position, keeping your core engaged and your leg extended.\r\n4. Lower your right leg back to the floor and return to the plank position. Repeat with the left leg.', E'1. Engage your core to maintain balance and stability throughout the movement.\r\n2. Keep your hips squared to the floor to ensure proper alignment.\r\n3. Breathe steadily, inhaling as you lift your leg and exhaling as you lower it.', '{"image_male_start":"images/Yoga/3 Leg Dog Pose_female.jpg","image_female_start":"images/Yoga/3 Leg Dog Pose_female.jpg","image_female_end":"images/Yoga/3 Leg Dog Pose_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('08de6fef-b517-4451-8709-4491b2715238'::uuid, '3-4 Sit-up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your knees bent and your feet flat on the floor, hip-width apart.\r\n2. Place your hands behind your head, keeping your elbows wide.\r\n3. Engage your core and lift your upper body towards your knees, coming up about three-quarters of the way.\r\n4. Slowly lower your upper body back to the starting position and repeat.', E'1. Keep your core engaged throughout the exercise to avoid straining your lower back.\r\n2. Avoid pulling on your neck with your hands; use your abdominal muscles to lift your upper body.\r\n3. Breathe steadily, exhaling as you lift and inhaling as you lower.', '{"image_male_start":"images/Abdominals/3-4 Sit-up_female.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a97ab3d3-050a-4353-800e-af5ebde8c8a6'::uuid, '4 Coners Side Step', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, knees slightly bent.\r\n2. Keep your hands close in front of your chest with your fists forming a punch and facing forward.\r\n3. Lift your right foot to the back, straightening it sideways and lightly touching the floor when fully extended. While extending both fists frontwards.\r\n4. Bring your right foot back to starting position and both fists close to your chest at starting position and repeat with alternating legs', E'1. Keep your knees slightly bent. This helps absorb the impact and engages your leg muscles more effectively.\r\n2. Maintain a tight core. Engaging your core muscles will help with balance and stability throughout the movement.\r\n3. Use controlled movements. Avoid rushing; perform each step deliberately to maximize muscle activation and reduce the risk of injury.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1be18f6d-bd7d-4c1e-ba8a-3032fbc4c474'::uuid, '4 Corners Curtsy', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start with feet shoulder-width apart, hands close to your chest.\r\n2. Step your right foot back and to the left, crossing behind your left leg and bending both knees into a curtsy lunge while extending both arms straight to the oposite side in front of yout torso.\r\n3. Return to the starting position by stepping your right foot forward to meet your left foot.\r\n4. Repeat the curtsy lunge the opposite side while straightening both arms on the opposite side.', E'1. Maintain Balance: Keep your core engaged to help maintain balance throughout the movement.\r\n2. Controlled Movements: Perform each step and curtsy with control to maximize muscle activation and reduce the risk of injury.\r\n3. Keep Knees Aligned: Ensure your front knee stays aligned with your front foot to avoid unnecessary strain on your knee joint.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/4 Corners Curtsy_female.jpg","image_female_start":"images/Calisthenics-Cardio-Functional/4 Corners Curtsy_female.jpg","image_female_end":"images/Calisthenics-Cardio-Functional/4 Corners Curtsy_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ec3f4f92-ecab-438a-806d-be81a65c414e'::uuid, '4 Punches Side Squat', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start with feet shoulder-width apart, hands in fists at chest level.\r\n2. Perform four punches in front of you, alternating between left and right hands.\r\n3. Step your right foot out to the side and lower into a squat position, keeping your back straight and knees aligned with your toes.\r\n4. Return to the standing position by stepping your left foot back in, and repeat the exercise.', E'1. Engage Your Core: Keep your core muscles engaged to help with balance and stability during punches and squats.\r\n2. Controlled Movements: Perform punches and squats in a controlled manner to maximize muscle activation and reduce injury risk.\r\n3. Keep Knees Aligned: Ensure your knees stay in line with your toes during the squat to avoid unnecessary strain on your knee joints.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/4 Punches Side Squat_female.jpg","image_female_start":"images/Calisthenics-Cardio-Functional/4 Punches Side Squat_female.jpg","image_female_end":"images/Calisthenics-Cardio-Functional/4 Punches Side Squat_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('00542b07-96cb-4de5-8134-144c2c7e02af'::uuid, '4 Reverse Lunge and 4 Side Taps', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start with feet shoulder-width apart, arms straight in front of your torso.\r\n2. Step your right foot back into a reverse lunge, bending both knees to 90 degrees. Return to the starting position by stepping your right foot forward and repeat 1 time.\r\n3. Return to standing position and perform four side taps by stepping your right foot out to the side and tapping the floor, then bringing it back to the center. Repeat on the other side.\r\n4. Return to starting position and repeat.', E'1. Keep your core muscles engaged to maintain balance and stability during lunges and taps.\r\n2. Perform each lunge and tap with control to maximize muscle activation and minimize injury risk.\r\n3. Ensure your front knee stays aligned with your front foot during lunges to avoid unnecessary strain on your knee joint.', '{"image_male_start":"images/Legs/4 Reverse Lunge and 4 Side Taps_female.jpg","image_female_start":"images/Legs/4 Reverse Lunge and 4 Side Taps_female.jpg","image_female_end":"images/Legs/4 Reverse Lunge and 4 Side Taps_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8db1ace7-da76-443b-a144-a6fc1e3f6c70'::uuid, '45 degree bicycle twist knee to elbow', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c7e89ac2-e6d9-4bbe-affa-981f3abb355c'::uuid, E'1. Align yourself to 45 degrees to the floor by fixing your left foot into the footrest and supporting your thigh against the padded platform.\r\n2. Place your left hand behind your head and your right hand on your waist.\r\n3. Open your upper leg slightly and bend your knee while bringing your opposite elbow towards it.\r\n4. Return to the initial position, and repeat. ', E'1. Keep your hips pressed on the hyperextension bench to engage your core muscles more effectively and protect your spine.\r\n2. Avoid pulling on your neck with your hand; use your core to lift and twist, keeping your neck in a neutral position.\r\n3. Perform the exercise slowly and deliberately to maximize muscle engagement and reduce the risk of strain.', '{"image_male_start":"images/Abdominals/45 degree bicycle twist knee to elbow.jpeg","video_url":"videos/Abdominals/45 degree bicycle twist knee to elbow.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a665ea8e-390e-415b-9b67-a86d0a626d74'::uuid, '45 Degree Bicycle Twisting', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c7e89ac2-e6d9-4bbe-affa-981f3abb355c'::uuid, E'1. Align yourself to 45 degrees to the floor by fixing your left foot into the footrest and supporting your thigh against the padded platform.\r\n2. Place your left hand behind your head and your right hand on your waist.\r\n3. Open your upper leg slightly and bend your knee while bringing your opposite elbow towards it.\r\n4. Return to the initial position, and repeat. ', E'1. Keep your hips pressed on the hyperextension bench to engage your core muscles more effectively and protect your spine.\r\n2. Avoid pulling on your neck with your hand; use your core to lift and twist, keeping your neck in a neutral position.\r\n3. Perform the exercise slowly and deliberately to maximize muscle engagement and reduce the risk of strain.', '{"image_male_start":"images/Abdominals/45 Degree Bicycle Twisting_female.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('32408a07-d252-42f4-9666-dea63189ac7b'::uuid, '45 degree bicycle twisting crunch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c7e89ac2-e6d9-4bbe-affa-981f3abb355c'::uuid, E'1. Align yourself to 45 degrees to the floor by fixing your left foot into the footrest and supporting your thigh against the padded platform.\r\n2. Place your left hand behind your head and your right hand on your waist.\r\n3. Straighten your upper leg wide and bend your knee while twisting your torso and bringing the opposite elbow towards it.\r\n4. Return to the initial position, and repeat. ', E'1. Ensure your feet are securely positioned on the hyperextension bench to maintain stability throughout the exercise.\r\n2. Focus on engaging your core muscles to lift and twist, avoiding pulling on your neck with your hands.\r\n3. Perform the exercise with controlled movements to maximize muscle engagement and reduce the risk of strain.', '{"image_male_start":"images/Abdominals/45 degree Bicycle Twisting Crunch_female.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ec472bf5-77e7-446c-ac55-97ba139871c0'::uuid, '45 degree hyperextension (arms in front of chest)', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c7e89ac2-e6d9-4bbe-affa-981f3abb355c'::uuid, E'1. Fix your feet to the footrests and press your thighs against the padded platform.\r\n2. Place your arms across your chest and lean forward.\r\n3. Raise yourself by leaning backward and forming an upright position.\r\n4. Hold for a while, return to the initial position, and repeat.\r\n', E'1. Keep your movements slow and controlled to maintain proper form and maximize muscle engagement.\r\n2. Avoid hyperextending your back; stop when your body forms a straight line to prevent strain on your lower back.\r\n3. Engage your core muscles throughout the exercise to support your spine and maintain stability.', '{"image_male_start":"images/Back/45 degree hyperextension (arms in front of chest)_female.jpg","image_female_start":"images/Back/45 degree hyperextension (arms in front of chest)_female.jpg","image_female_end":"images/Back/45 degree hyperextension (arms in front of chest)_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('138e52d6-76c5-4190-9f3d-8190c217311c'::uuid, '45 degree hyperextension arms to chest', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c7e89ac2-e6d9-4bbe-affa-981f3abb355c'::uuid, E'1. Fix your feet to the footrests and press your thighs against the padded platform.\r\n2. Place your arms across your chest and lean forward.\r\n3. Raise yourself by leaning backward and forming an upright position.\r\n4. Hold for a while, return to the initial position, and repeat.\r\n', E'1. Keep your movements slow and controlled to maintain proper form and maximize muscle engagement.\r\n2. Avoid hyperextending your back; stop when your body forms a straight line to prevent strain on your lower back.\r\n3. Engage your core muscles throughout the exercise to support your spine and maintain stability.', '{"video_url":"videos/Back/45 degree hyperextension arms to chest.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6b7578aa-a1ef-442f-9dc3-8d8358c6f2ae'::uuid, '45 Degree Side Bend', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c7e89ac2-e6d9-4bbe-affa-981f3abb355c'::uuid, E'1. Place your feet one after the other onto the footrests and support your thigh against the platform.\r\n2. Place your hands behind your head and assume an upright position with a straight back.\r\n3. Crunch your torso toward the platform and then to the other side.\r\n4. Repeat while keeping yourself stable.', E'1. Maintain a steady and controlled pace to ensure proper form and prevent strain.\r\n2. Focus on using your oblique muscles to lift your upper body, avoiding any jerking or sudden movements.\r\n3. Keep your neck in a neutral position to avoid straining it during the exercise.', '{"image_male_end":"images/Abdominals/45 Degree Side Bend_female.jpeg","video_url":"videos/Abdominals/45 degree side bend.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('24ca3356-60ed-4c44-af2f-fe536e2b1861'::uuid, '45 degree twisting hyperextension', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c7e89ac2-e6d9-4bbe-affa-981f3abb355c'::uuid, E'1. Fix your feet to the footrests and press your thighs against the padded platform.\r\n2. Place your hands behind your head and lean forward.\r\n3. Raise yourself by leaning backward and twisting your torso to a side.\r\n4. Hold for a while, return to the initial position, and repeat.', E'1. Perform the twisting motion smoothly and avoid jerking to prevent strain on your back.\r\n2. Engage your core muscles throughout the exercise to maintain stability and support your spine.\r\n3. Breathe steadily, exhaling as you lift and twist, and inhaling as you lower back down.', '{"image_male_start":"images/Abdominals/45 degree twisting hyperextension_female.jpeg","video_url":"videos/Abdominals/45 degree twisting hyperextension.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('febbafce-21d6-4016-bff3-02566fd257c3'::uuid, '45 degrees Step Out', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart keeping them bent to a half squat position.\r\n2. Step your right foot out at a 45-degree angle to the side until your leg is completely straight.\r\n3. Bring your right foot back to the starting position.\r\n4. Repeat the movement with your left foot, continuing to alternate sides.', E'1. Keep your core engaged to maintain balance and stability throughout the movement.\r\n2. Ensure your knees are aligned with your toes when you step out to protect your joints.\r\n3. Perform the exercise with controlled movements to maximize muscle engagement and reduce the risk of injury.', '{"image_male_start":"images/Legs/45 degrees Step Out_female.jpg","image_female_start":"images/Legs/45 degrees Step Out_female.jpg","image_female_end":"images/Legs/45 degrees Step Out_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('47461d85-b446-4a5c-a5e8-6f1d13a794a8'::uuid, '5 Sec Fist Against Chin', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit or stand upright with your feet shoulder-width apart, maintaining good posture. Make a fist with both hands and place them under your chin.\r\n2. Apply gentle upward pressure with your fist against your chin, resisting with your neck muscles. Hold this position for 5 seconds.\r\n3. Keep your neck and head steady, avoiding any movement while maintaining the pressure.\r\n4. Release the pressure after 5 seconds and relax. Repeat the exercise for the desired number of repetitions.', E'1. Keep your jaw relaxed, avoiding clenching your teeth.\r\n2. Focus on the resistance created by your fist and neck muscles rather than the amount of force applied.\r\n3. Breathe normally throughout the exercise, avoiding holding your breath.', '{"image_male_start":"images/Stretching - Mobility/5 Sec Fist Against Chin_female.jpg","image_female_start":"images/Stretching - Mobility/5 Sec Fist Against Chin_female.jpg","image_female_end":"images/Stretching - Mobility/5 Sec Fist Against Chin_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c7c3b0c3-155a-4965-9a27-d9527858e79b'::uuid, '90 degree heel touch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie down on your back with your hips and knees bent to 90 degrees and your arms extended overhead.\r\n2. Raise your upper back and bring your arms forward to touch your heels.\r\n3. Hold for a while, return to the initial position, and repeat.\r\n', E'1. Keep your neck relaxed and avoid straining it by using your core muscles to lift your shoulders.\r\n2. Ensure your lower back stays pressed into the mat to engage your core effectively and protect your spine.\r\n3. Perform the exercise with controlled movements to maximize muscle engagement and reduce the risk of injury.', '{"image_male_start":"images/Abdominals/90 degree heel touch.jpeg","video_url":"videos/Abdominals/90 degree heel touch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('15591840-e1e8-4aaa-ac5d-75645ba225ab'::uuid, '90 Degree Heels Touch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie down on your back with your hips and knees bent to 90 degrees and your arms extended overhead.\r\n2. Raise your upper back and bring your arms forward to touch your heels.\r\n3. Hold for a while, return to the initial position, and repeat.\r\n', E'1. Keep your neck relaxed and avoid straining it by using your core muscles to lift your shoulders.\r\n2. Ensure your lower back stays pressed into the mat to engage your core effectively and protect your spine.\r\n3. Perform the exercise with controlled movements to maximize muscle engagement and reduce the risk of injury.', '{"image_male_start":"images/Abdominals/90 Degree Heels Touch_female.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('15c02bf6-6e2c-486d-8d99-ab2cee1b86de'::uuid, '90 to 90 Stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on the floor with both legs bent at 90 degrees. Position one leg in front of your body with your thigh and shin at a 90-degree angle, and the other leg to the side with your thigh and shin at a 90-degree angle with foot extending backwards.\r\n2. Lean lightly forward keeping your arms on the floor and holding the stretch for a few seconds.\r\n3. Switch the position of your legs to perform the stretch on the opposite side.', E'1. Keep your back straight as you lean forward to maximize the stretch and avoid straining your lower back.\r\n2. Breathe deeply and steadily throughout the stretch to help relax your muscles.\r\n3. Perform the stretch slowly and avoid bouncing or jerking movements to reduce the risk of injury.', '{"image_male_start":"images/Stretching - Mobility/90 to 90 Stretch_female.jpg","image_female_start":"images/Stretching - Mobility/90 to 90 Stretch_female.jpg","image_female_end":"images/Stretching - Mobility/90 to 90 Stretch_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3f361f52-b1d5-4cc3-9cb9-4b5981f62f4e'::uuid, 'Ab Mat Sit-up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on the floor with a yoga mat placed under your lower back, knees bent facing outwards, and feet  on the floor touching together. Hands behind your head.\r\n2. Lean back to lie down, keeping your arms behind your head.\r\n3. Use your core muscles to sit your torso up, return to the starting position and repeat.', E'1. Engage your core muscles throughout the movement to maximize effectiveness and protect your lower back.\r\n2. Avoid using momentum by performing the movement slowly and with control.\r\n3. Keep your feet on the floor and your knees stable to maintain proper form.', '{"image_male_start":"images/Abdominals/Ab Mat Sit-up_female.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8aea1de8-b457-47ac-89d1-06417f1ba7b0'::uuid, 'Ab Tuck', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '2c4e23f7-d7ad-4255-8299-13033b3bc1c8'::uuid, E'1. Start by hanging on a dip station, holding the parallel bars with your arms extended and your body straight.\r\n2. Lift your knees towards your chest while lightly extending your hips backward, engaging your core muscles.\r\n3. Extend your legs back downwards to starting position.\r\n4. Repeat the movement.', E'1. Engage your core muscles throughout the exercise to maintain control and stability.\r\n2. Perform the movement slowly and deliberately to avoid using momentum and maximize muscle engagement.\r\n3. Keep your upper body stable and avoid swinging to ensure proper form.', '{"image_male_start":"images/Abdominals/Ab Tuck_female.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('50da3a91-e53e-4373-89ed-a61b086877ae'::uuid, 'AB Wheel All The Way out', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '9ffbc39a-4891-4f46-b1f7-17bd2c6b7261'::uuid, E'1. Start by kneeling on a mat with the ab wheel placed on the floor in front of you, holding it with both hands. Ensure your arms are extended and your back is straight.\r\n2. Roll the ab wheel forward, extending your body into a straight line while keeping your core engaged and your hips slightly extended backward.\r\n3. Roll the ab wheel back to the starting position, using your core muscles to control the movement and maintain stability.\r\n4. Repeat the movement, extending fully and returning to the starting position each time.', E'1. Keep your core muscles engaged throughout the exercise to protect your lower back and maintain stability.\r\n2. Perform the movement slowly and with control, avoiding using momentum to maximize muscle engagement.\r\n3. Ensure your hips are slightly extended backward when rolling out to maintain proper form and prevent lower back strain.', '{"image_male_start":"images/Abdominals/AB Wheel All The Way out_Female.jpeg","video_url":"videos/Abdominals/AB Wheel All The Way out.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0d3fc75b-068e-4d61-bc93-b4f262a2d31f'::uuid, 'AB Wheel Halfway out', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '9ffbc39a-4891-4f46-b1f7-17bd2c6b7261'::uuid, E'1. Start by kneeling on a mat with the ab wheel placed on the floor in front of you, holding it with both hands. Ensure your arms are extended and your back is straight.\r\n2. Roll the ab wheel forward, extending your body halfway while keeping your core engaged and your hips slightly extended backward.\r\n3. Roll the ab wheel back to the starting position, using your core muscles to control the movement and maintain stability.\r\n4. Repeat the movement, extending halfway and returning to the starting position each time.', E'1. Keep your core muscles engaged throughout the exercise to protect your lower back and maintain stability.\r\n2. Perform the movement slowly and with control, avoiding using momentum to maximize muscle engagement.\r\n3. Ensure your hips are slightly extended backward when rolling out to maintain proper form and prevent lower back strain.', '{"image_male_start":"images/Abdominals/AB Wheel Halfway out_Female.jpeg","video_url":"videos/Abdominals/AB Wheel Halfway out.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('552de7f2-9fb3-4b59-b0a6-f65297944d7c'::uuid, 'AB Wheel Left out', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '9ffbc39a-4891-4f46-b1f7-17bd2c6b7261'::uuid, E'1. Start by kneeling on a mat with the ab wheel placed on the floor in front of you, holding it with both hands. Ensure your arms are extended and your back is straight.\r\n2. Roll the ab wheel forward and to the left, extending your body into a partial straight line while keeping your core engaged and your hips slightly extended backward.\r\n3. Roll the ab wheel back to the starting position, using your core muscles to control the movement and maintain stability.\r\n4. Repeat the movement, rolling out to the left and returning to the starting position each time.', E'1. Avoid overextending and roll out only as far as you can maintain control. Overextending can place unnecessary strain on your lower back and shoulders.\r\n2. Breathe steadily. Inhale as you roll out and exhale as you roll back in. Proper breathing helps maintain core engagement and stability.\r\n3. Ensure your hips are slightly extended backward when rolling out to maintain proper form and prevent lower back strain.', '{"image_male_start":"images/Abdominals/AB Wheel Left out_Female.jpeg","video_url":"videos/Abdominals/AB Wheel Left out.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('40ea0fff-fd1a-4cb1-af51-9b5b69a76414'::uuid, 'Ab Wheel Plank', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '9ffbc39a-4891-4f46-b1f7-17bd2c6b7261'::uuid, E'1. Start by kneeling on a mat with the ab wheel placed on the floor in front of you, holding it with both hands. Ensure your arms are extended and your back is straight.\r\n2. Roll the ab wheel forward until your body is in a plank position, with your arms extended and your body forming a straight line from head to knees.\r\n3. Hold the plank position, keeping your core engaged and your body stable, as long as required.\r\n4. Roll the ab wheel back to the starting position.', E'1. Keep your spine neutral and avoid letting your lower back sag. This helps protect your spine and ensures proper form.\r\n2. Focus on engaging your entire core, including your abdominals, obliques, and lower back, to maintain stability.\r\n3. Roll out and back in with controlled movements to maximize muscle engagement and minimize the risk of injury.', '{"image_male_start":"images/Yoga/Ab Wheel Plank_Female.jpeg","video_url":"videos/Yoga/Ab Wheel Plank.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0ff1d2ff-bf98-4f77-8259-c6fc8622f158'::uuid, 'AB Wheel Pulses', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '9ffbc39a-4891-4f46-b1f7-17bd2c6b7261'::uuid, E'1. Start by lying on the floor with your arms extended overhead, holding the ab wheel with both hands.\r\n2. Engage your core by lifting your upper body off the floor slightly, performing a small crunch while keeping your arms extended and the ab wheel overhead.\r\n3. Perform small pulsing crunches, lifting and lowering your upper body slightly while maintaining tension in your core.\r\n4. Continue the pulsing movement for the desired number of repetitions, keeping your arms extended and the ab wheel steady.', E'1. Keep your movements small and controlled to maintain tension on your core muscles.\r\n2. Focus on maintaining a neutral spine and avoiding any strain on your neck by using your core to lift your upper body.\r\n3. Breathe steadily, exhaling as you lift into the crunch and inhaling as you lower back down.', '{"image_male_start":"images/Abdominals/AB Wheel Pulses_Female.jpeg","video_url":"videos/Abdominals/AB Wheel Pulses.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4bc99251-c87b-499b-bbdb-2e292d8324c6'::uuid, 'AB Wheel Right out', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '9ffbc39a-4891-4f46-b1f7-17bd2c6b7261'::uuid, E'1. Start by kneeling on a mat with the ab wheel placed on the floor in front of you, holding it with both hands. Ensure your arms are extended and your back is straight.\r\n2. Roll the ab wheel forward and to the right, extending your body into a partial straight line while keeping your core engaged and your hips slightly extended backward.\r\n3. Roll the ab wheel back to the starting position, using your core muscles to control the movement and maintain stability.\r\n4. Repeat the movement, rolling out to the right and returning to the starting position each time.', E'1. Avoid overextending and roll out only as far as you can maintain control. Overextending can place unnecessary strain on your lower back and shoulders.\r\n2. Breathe steadily. Inhale as you roll out and exhale as you roll back in. Proper breathing helps maintain core engagement and stability.\r\n3. Ensure your hips are slightly extended backward when rolling out to maintain proper form and prevent lower back strain.', '{"image_male_start":"images/Abdominals/AB Wheel Right out_Female.jpeg","video_url":"videos/Abdominals/AB Wheel Right out.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2701e587-b81a-48f3-95e7-13e303ec85cd'::uuid, 'AB Wheel Take it or Leave It', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '9ffbc39a-4891-4f46-b1f7-17bd2c6b7261'::uuid, E'1. Lie on your back with your legs bent at 90 degrees and your feet off the floor, forming a tabletop position. Hold the AB wheel overhead with both hands, keeping your arms straight.\r\n2. Engage your core and lift your chest towards your knees to perform a crunch, bringing the AB wheel towards your shins.\r\n3. Place the AB wheel gently on your shins and lower your upper body back to the floor, keeping your legs in the tabletop position.\r\n4. Perform another crunch, reaching up to grab the AB wheel from your shins, and then lower your upper body back to the floor. Repeat for the desired number of repetitions.', E'1. Ensure your legs remain bent at 90 degrees and your shins stay parallel to the floor throughout the exercise.\r\n2. Avoid using momentum to lift your upper body; focus on using your abdominal muscles.\r\n3. Perform the exercise on a comfortable, non-slip surface to ensure safety and reduce discomfort.', '{"image_male_start":"images/Abdominals/AB Wheel Take it or Leave It_Female.jpeg","video_url":"videos/Abdominals/AB Wheel Take it or Leave It.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('fd3a746f-9b5f-4bc6-982c-274c6fee8fa1'::uuid, 'Abdominal crunches', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with knees slightly bent, feet placed on the floor and arms raised to the shoulder height.\r\n2. Squeeze your abdominals and lift your upper back off the floor, reaching forward with your arms\r\n3. Hold for few seconds and slowly return to the starting position.', E'1. Keep your neck relaxed and avoid pulling on it with your hands to prevent strain.\r\n2. Focus on engaging your core muscles throughout the movement to maximize effectiveness.\r\n3. Breathe steadily, exhaling as you lift into the crunch and inhaling as you lower back down.', '{"image_male_start":"images/Abdominals/Abdominal Crunches.jpg","image_male_end":"images/Abdominals/Abdominal Crunches1.jpg","image_female_start":"images/Abdominals/Abdominal Crunches_Female.jpg","image_female_end":"images/Abdominals/Abdominal Crunches_Female1.jpg","video_url":"videos/Abdominals/abdominal crunches.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c4b84caf-e426-4aeb-8950-b4d73818254c'::uuid, 'Abdominal Crunches Machine', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Adjust the seat and resistance to your desired settings on the abdominal crunch machine. Sit on the seat and position your feet securely on the footrests.\r\n2. Grab the handles, ensuring your elbows are pointed forward.\r\n3. Engage your core muscles and crunch your abdominals by pulling your upper body forward and curling your chest towards your knees.\r\n4. Hold the crunch for a second, then slowly return to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you crunch forward and inhale as you return to the starting position.\r\n2. Avoid using momentum; focus on engaging your abdominal muscles throughout the exercise.\r\n3. Ensure your lower back remains in contact with the backrest of the machine.', '{"image_male_start":"images/Abdominals/Abdominal Crunches Machine.jpg","image_male_end":"images/Abdominals/Abdominal Crunches Machine1.jpg","image_female_start":"images/Abdominals/Abdominal Crunches Machine_Female.jpg","image_female_end":"images/Abdominals/Abdominal Crunches Machine_Female1.jpg","video_url":"videos/Abdominals/abdominal crunches machine.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('da3e264a-2912-4f97-b7fd-90e36ef98668'::uuid, 'Abdominal crunches with hold', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with knees slightly bent and feet placed on the floor.\r\n2. Inhale and try reaching forward with straight arms while lifting your upper back off the floor.                                                                   3. Hold the end position for few seconds and slowly return to the starting position.', E'1. Keep your neck relaxed and avoid pulling on it with your hands to prevent strain.\r\n2. Focus on engaging your core muscles throughout the movement to maximize effectiveness.\r\n3. Hold the crunch position for a count of two to five seconds to increase muscle activation and endurance.', '{"image_male_start":"images/Abdominals/Abdominal Crunches with Hold.jpg","image_male_end":"images/Abdominals/Abdominal Crunches with Hold1.jpg","image_female_start":"images/Abdominals/Abdominal Crunches With Hold_Female.jpg","image_female_end":"images/Abdominals/Abdominal Crunches With Hold_Female1.jpg","video_url":"videos/Abdominals/abdominal crunches with hold.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('12cd0701-05bd-4d54-985f-01e355a8ed9d'::uuid, 'Abdominal stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on the floor with your knees bent and drawn towards your chest.\r\n2. Wrap your arms around your knees, hugging them tightly.\r\n3. Hold the stretch in this position, allowing your back to round slightly and your head to relax forward.\r\n4. After holding the stretch for the desired amount of time, release your arms and return to a neutral sitting position.', E'1. Keep your shoulders relaxed and avoid hunching them up towards your ears.\r\n2. Breathe deeply and steadily throughout the stretch to help relax your muscles.\r\n3. Perform the stretch slowly and avoid any sudden movements to prevent strain.', '{"image_male_start":"images/Stretching - Mobility/Abdominal stretch.jpg","image_male_end":"images/Stretching - Mobility/Abdominal stretch1.jpg","image_female_start":"images/Stretching - Mobility/Abdominal Stretch_female.jpg","image_female_end":"images/Stretching - Mobility/Abdominal Stretch_female1.jpg","video_url":"videos/Stretching - Mobility/Abdominal stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('09ff8b76-5d3d-4bb8-a1c7-77dcd4c0d759'::uuid, 'Abdominal Stretch ( Version2 )', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on the floor with your knees bent and drawn towards your chest.\r\n2. Place your hands on your knees keeping them set and lean your chest to your knees to stretch.\r\n3. Hold the stretch in this position, allowing your back to round slightly and your head to relax forward.\r\n4. After holding the stretch for the desired amount of time, release your arms and return to a neutral sitting position.', E'1. Keep your shoulders relaxed and avoid hunching them up towards your ears.\r\n2. Breathe deeply and steadily throughout the stretch to help relax your muscles.\r\n3. Perform the stretch slowly and avoid any sudden movements to prevent strain.', '{"image_male_start":"images/Stretching - Mobility/Abdominal Stretch ( Version2 )_female.jpg","image_female_start":"images/Stretching - Mobility/Abdominal Stretch ( Version2 )_female.jpg","image_female_end":"images/Stretching - Mobility/Abdominal Stretch ( Version2 )_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('12867a00-ef7e-46aa-ac9b-68c66cdfbd36'::uuid, 'Above head chest stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your back straight. Raise your arms overhead and clasp your hands together with elbows bent.\r\n2. Keeping your hands clasped, bring your elbows backward to stretch.\r\n3. Hold the stretch in this position, keeping your back straight and core engaged.\r\n4. After holding the stretch for the desired amount of time, return to the starting position.', E'1. Keep your shoulders relaxed and avoid hunching them up towards your ears.\r\n2. Breathe deeply and steadily throughout the stretch to help relax your muscles.\r\n3. Maintain a straight back and engaged core to ensure proper form and maximize the stretch.', '{"image_male_start":"images/Stretching - Mobility/Above head chest stretch.jpg","image_male_end":"images/Stretching - Mobility/Above head chest stretch1.jpg","image_female_start":"images/Stretching - Mobility/Above Head Chest Stretch_female.jpg","image_female_end":"images/Stretching - Mobility/Above Head Chest Stretch_female1.jpg","video_url":"videos/Stretching - Mobility/Above head chest stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e0cb31a3-7508-4dbe-984c-f3a68a8d5414'::uuid, 'Across chest shoulder stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your back straight. Raise one arm to shoulder height and bring it across your chest.\r\n2. Use your opposite hand to grasp your upper arm and gently pull it towards your chest, stretching your shoulder.\r\n3. Hold the stretch in this position.\r\n4. Release your arm and repeat the movement on the other side.', E'1. Keep your shoulders relaxed and avoid hunching them up towards your ears.\r\n2. Breathe deeply and steadily throughout the stretch to help relax your muscles.\r\n3. Maintain a straight back and avoid twisting your torso to ensure proper form.', '{"image_male_start":"images/Stretching - Mobility/Across chest shoulder stretch.jpg","image_male_end":"images/Stretching - Mobility/Across chest shoulder stretch1.jpg","image_female_start":"images/Stretching - Mobility/Across Chest Shoulder Stretch_Female.jpg","image_female_end":"images/Stretching - Mobility/Across Chest Shoulder Stretch_Female1.jpg","video_url":"videos/Stretching - Mobility/Across chest shoulder stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('23d58750-fedb-4221-a103-35ea8a653a9f'::uuid, 'Adductor dynamic stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back on a mat with both legs extended upwards.\r\n2. Open your legs wide apart, stretching your inner thighs.\r\n3. Bring your legs back together to the starting position.\r\n4. Continue the movement in a dynamic manner, opening and closing your legs.', E'1. Keep your core engaged to maintain stability and control throughout the movement.\r\n2. Perform the movement with controlled and smooth transitions to maximize the stretch and prevent injury.\r\n3. Breathe steadily, exhaling as you open your legs and inhaling as you bring them back together.', '{"image_male_start":"images/Stretching - Mobility/Adductor dynamic stretch.jpg","image_male_end":"images/Stretching - Mobility/Adductor dynamic stretch1.jpg","image_female_start":"images/Stretching - Mobility/Adductor Dynamic Stretch_Female.jpg","image_female_end":"images/Stretching - Mobility/Adductor Dynamic Stretch_Female1.jpg","video_url":"videos/Stretching - Mobility/Adductor dynamic stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3d336d88-ad8e-4ba3-a0fb-7e9a35ea0fb1'::uuid, 'adductor stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back on a mat with both legs extended upwards.\r\n2. Open your legs wide apart, stretching your inner thighs.\r\n3. Hold the stretch for 20-30 seconds, or as needed.', E'1. Keep your core engaged to maintain stability and control throughout the stretch.\r\n2. Focus on maintaining a steady breathing pattern, inhaling deeply through your nose and exhaling through your mouth while holding the stretch.\r\n3. Perform the stretch slowly and avoid any sudden movements to prevent strain.', '{"image_male_start":"images/Stretching - Mobility/Adductor stretch.jpg","image_male_end":"images/Stretching - Mobility/Adductor stretch1.jpg","image_female_start":"images/Stretching - Mobility/adductor stretch_female.jpg","image_female_end":"images/Stretching - Mobility/adductor stretch_female1.jpg","video_url":"videos/Stretching - Mobility/Adductor stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b559fe04-474b-43eb-97f9-692cf852ae49'::uuid, 'Adductor stretch side standing', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand tall with your back straight and feet shoulder-width apart while keeping your hands together in front of your chest.\r\n2. Take a step to the left while keeping your right foot in place.\r\n3. Bend the left knee unless your right thigh becomes parallel to the floor.\r\n4. Hold for a few seconds, return to the initial position, and repeat.', E'1. Keep your core engaged to maintain balance and stability throughout the stretch.\r\n2. Ensure your bent knee does not extend past your toes to avoid strain on your knee joint.\r\n3. Perform the stretch slowly and avoid any sudden movements to prevent strain.', '{"image_male_start":"images/Stretching - Mobility/Adductor stretch side standing.jpg","image_male_end":"images/Stretching - Mobility/Adductor stretch side standing1.jpg","image_female_start":"images/Stretching - Mobility/Adductor Stretch Side Standing_Female.jpg","image_female_end":"images/Stretching - Mobility/Adductor Stretch Side Standing_Female1.jpg","video_url":"videos/Stretching - Mobility/Adductor stretch side standing.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c0a2f059-945c-4e92-a7f8-9aa85923e647'::uuid, 'air bike', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your hands behind your head and your knees bent at a 90-degree angle.\r\n2. Lift your back off the floor, engaging your core.\r\n3. Bring your right elbow towards your left knee while extending your right leg slightly.\r\n4. Lower your back to the floor and repeat, bringing your left elbow towards your right knee while extending your left leg lightly.', E'1. Keep your core engaged throughout the exercise to maximize muscle activation and protect your lower back.\r\n2. Perform the movement slowly and with control, avoiding the use of momentum to maximize effectiveness.\r\n3. Breathe steadily, exhaling as you twist and bring your elbow to your knee, and inhaling as you switch sides.', '{"image_male_start":"images/Abdominals/air bike_female.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ccad3106-de49-468b-adbb-fabddbc0c1d4'::uuid, 'Air Bike (VERSION 2)', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your hands behind your head and your knees bent at a 90-degree angle.\r\n2. Lift your shoulders off the floor, engaging your core.\r\n3. Bring your right elbow towards your left knee while extending your right leg straight.\r\n4. Switch sides, bringing your left elbow towards your right knee while extending your left leg straight. Continue alternating sides in a pedaling motion.', E'1. Keep your core engaged throughout the exercise to maximize muscle activation and protect your lower back.\r\n2. Perform the movement slowly and with control, avoiding the use of momentum to maximize effectiveness.\r\n3. Breathe steadily, exhaling as you twist and bring your elbow to your knee, and inhaling as you switch sides.', '{"image_male_start":"images/Abdominals/Air Bike (VERSION 2)_female.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3735e959-5e25-45b0-881f-ed736a217d61'::uuid, 'Air bike crunch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your hands behind your head and your knees bent at a 90-degree angle.\r\n2. Lift your shoulders off the floor, engaging your core.\r\n3. Bring your right elbow towards your left knee while extending your right leg lightly.\r\n4. Switch sides, bringing your left elbow towards your right knee while extending your left leg lightly. Continue alternating sides in a pedaling motion.', E'1. Keep your core engaged throughout the exercise to maximize muscle activation and protect your lower back.\r\n2. Perform the movement slowly and with control, avoiding the use of momentum to maximize effectiveness.\r\n3. Breathe steadily, exhaling as you twist and bring your elbow to your knee, and inhaling as you switch sides.', '{"image_male_start":"images/Abdominals/air bike crunch.jpeg","video_url":"videos/Abdominals/air bike crunch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('16b05db3-5fae-4ece-bd0d-cf0aaceb0fc4'::uuid, 'Air punches march', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand tall with your back straight and feet shoulder-width apart.\r\n2. Make fists of your hands, fold one arm at your side and extend the other arm overhead.\r\n3. Raise one of your thighs while bending your knee, and lower your arm while extending the other arm overhead.\r\n4. Return to the initial position and repeat by raising your other thigh.', E'1. Keep your core engaged to maintain balance and stability throughout the exercise.\r\n2. Perform the movements with controlled, deliberate motions to maximize muscle engagement and prevent injury.\r\n3. Breathe steadily, exhaling as you punch upwards and inhaling as you bring your arm back.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Air punches March.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Air punches March1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Air punches March.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('234556bb-7214-4b14-9e29-ea39f472b5b3'::uuid, 'Air twisting crunch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie down on your back with your knees bent and heels on the floor.\r\n2. Place your hands behind your head.\r\n3. Raise your chest and twist your torso to one side while bringing the opposite knee close.\r\n4. Return to the initial position and repeat by twisting towards the other side.', E'1. Keep your core engaged throughout the exercise to maximize muscle activation and protect your lower back.\r\n2. Perform the movement slowly and with control, avoiding the use of momentum to maximize effectiveness.\r\n3. Breathe steadily, exhaling as you twist and bring your elbow to your knee, and inhaling as you switch sides.', '{"image_male_start":"images/Abdominals/air twisting crunch_female.jpeg","video_url":"videos/Abdominals/air twisting crunch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0316870c-4e09-4874-84a0-9a892b50611e'::uuid, 'All fours quad stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start in an all-fours position on a mat, with your hands directly under your shoulders and your knees under your hips.\r\n2. Reach back with your right hand to grasp the ankle of your right leg.\r\n3. Gently pull your ankle towards your glutes, stretching your quadriceps, and hold the stretch in this position for 20-30 seconds.\r\n4. Release your ankle and switch sides, repeating the stretch.', E'1. Keep your core engaged to maintain balance and stability throughout the stretch.\r\n2. Avoid arching your back; maintain a neutral spine to protect your lower back.\r\n3. Breathe deeply and steadily throughout the stretch to help relax your muscles.', '{"image_male_start":"images/Stretching - Mobility/All fours quad stretch.jpg","image_male_end":"images/Stretching - Mobility/All fours quad stretch1.jpg","image_female_start":"images/Stretching - Mobility/ALL FOURS QUAD STRETCH_female.jpg","image_female_end":"images/Stretching - Mobility/ALL FOURS QUAD STRETCH_female1.jpg","video_url":"videos/Stretching - Mobility/All fours quad stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('90f29531-c08a-4554-a793-6d076cf2b61b'::uuid, 'Alternate arm leg plank', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start in a plank position with your hands directly under your shoulders and your body forming a straight line from head to heels.\r\n2. Lift your right arm and left leg simultaneously, extending them straight out while maintaining balance. Hold briefly, then lower back to the plank position.\r\n3. Lift your left arm and right leg simultaneously, extending them straight out and holding briefly before returning to the plank position.\r\n4. Continue alternating sides, lifting opposite arms and legs.', E'1. Keep your core engaged throughout the exercise to maintain stability and prevent your hips from sagging.\r\n2. Perform the movement slowly and with control to maximize muscle engagement and maintain balance.\r\n3. Breathe steadily, exhaling as you lift your arm and leg and inhaling as you lower them back to the plank position.', '{"image_male_start":"images/Abdominals/Alternate Arm Leg Plank.jpeg","video_url":"videos/Abdominals/Alternate Arm Leg Plank.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('fd3bbe54-c520-4278-887c-784c54c5c544'::uuid, 'Alternate arm leg plank hold', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1.  Start in a plank position with your elbows directly under your shoulders and your body forming a straight line from head to heels.\r\n2. Lift your right arm and left leg simultaneously, extending them straight out while maintaining balance. Hold this position for a brief period of 1-2 seconds.\r\n3. Lower your right arm and left leg back to the plank position.\r\n4. Lift your left arm and right leg simultaneously, extending them straight out and holding for a brief period of 1-2 seconds before returning to the plank position.', E'1. Keep your core engaged throughout the exercise to maintain stability and prevent your hips from sagging.\r\n2. Perform the movement slowly and with control to maximize muscle engagement and maintain balance.\r\n3. Breathe steadily, exhaling as you lift your arm and leg and inhaling as you hold the position.', '{"image_male_start":"images/Abdominals/alternate arm leg plank hold.jpeg","video_url":"videos/Abdominals/alternate arm leg plank hold.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e885ae31-6eea-4b71-87a2-0eb34a5b7a11'::uuid, 'Alternate arm leg plank rest pause', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1.Start in a plank position with your elbows directly under your shoulders and your body forming a straight line from head to heels.\r\n2. Lift your right arm and left leg simultaneously, extending them straight out while maintaining balance. Then lower back to the plank position and pause for a few seconds.\r\n3. Lift your left arm and right leg simultaneously, extending them straight out and return to the plank position and pause for a few seconds.\r\n4. Continue alternating sides, lifting opposite arms and legs with a brief pause in the plank position.', E'1. Keep your core engaged throughout the exercise to maintain stability and prevent your hips from sagging.\r\n2. Perform the movement slowly and with control to maximize muscle engagement and maintain balance.\r\n3. Breathe steadily, exhaling as you lift your arm and leg and inhaling as you pause in the plank position.', '{"image_male_start":"images/Abdominals/alternate arm leg plank rest pause.jpeg","video_url":"videos/Abdominals/alternate arm leg plank rest pause.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('558c6288-8acc-4e3d-b974-9222a9e7c4cb'::uuid, 'Alternate Bicep Curl Resistance Band', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand on the center of a resistance band with your feet shoulder-width apart.\r\n2. Hold the handles of the resistance band with your arms fully extended by your sides, palms facing forward.\r\n3. Raise one of the handles towards your shoulder by bending your arm.\r\n4. As it reaches near the shoulder, return to the initial position and repeat by folding your other arm.', E'1. Adjust the resistance band length to increase or decrease the resistance as needed if possible.\r\n2. Ensure you maintain even tension on the band throughout the entire range of motion.\r\n3. Keep your wrists neutral and avoid bending them during the curls.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('17a79f68-615b-4932-b117-10daa6cc8382'::uuid, 'Alternate bicep curl standing dumbbells', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand upright with your feet shoulder-width apart, holding a dumbbell in each hand with your arms fully extended by your sides. Your palms should face forward (supinated grip).\r\n2. Engage your core and keep your elbows close to your torso. Slowly curl the right dumbbell up towards your shoulder, maintaining the forward-facing position of your palms.\r\n3. Squeeze your bicep at the top of the movement, then slowly lower the dumbbell back to the starting position with control.\r\n4. Repeat the same motion with your left arm, alternating between right and left arms for the desired number of repetitions.', E'1. Ensure your elbows stay close to your torso and avoid swinging your arms to lift the weights.\r\n2. Move your arms slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Focus on fully extending your arms at the bottom of each curl to engage the full range of motion.', '{"image_male_start":"images/Biceps/alternate bicep curl standing dumbbells.jpeg","video_url":"videos/Biceps/alternate bicep curl standing dumbbells.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a1d8747f-9cbd-42af-9b24-39a4b8471ee0'::uuid, 'alternate front kick in place', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet hip-width apart and arms bent by your sides.\r\n2. Jump lightly and lift your right leg and extend it forward in a kicking motion while simultaneously swing your left arm forward.\r\n3. Lower your right leg and left arm back to the starting position.\r\n4. Repeat the movement by alternating front kicks with each leg.', E'1. Lift your leg smoothly and avoid swinging it to maintain better control.\r\n2. Perform the kicks with controlled movements to avoid using momentum and reduce the risk of injury.\r\n3. Maintain an upright posture, avoiding leaning back as you kick.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/alternate front kick in place_female.jpg","image_female_start":"images/Calisthenics-Cardio-Functional/alternate front kick in place_female.jpg","image_female_end":"images/Calisthenics-Cardio-Functional/alternate front kick in place_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('dea1259a-2f47-41ed-8557-2c013463593f'::uuid, 'Alternate hammer curl seated dumbbells', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench with your feet flat on the floor, holding a dumbbell in each hand with your arms fully extended by your sides. Your palms should face each other (neutral grip).\r\n2. Engage your core and keep your elbows close to your torso. Slowly curl the right dumbbell up towards your shoulder, maintaining the neutral grip with your palm facing inward.\r\n3. Squeeze your bicep at the top of the movement, then slowly lower the dumbbell back to the starting position with control.\r\n4. Repeat the same motion with your left arm, alternating between right and left arms for the desired number of repetitions.', E'1. Keep your wrists straight to avoid putting unnecessary strain on them during the curls.\r\n2. Maintain a controlled pace to ensure that you''re using muscle strength rather than momentum.\r\n3. Visualize the bicep contraction to enhance the mind-muscle connection for better results.', '{"image_male_start":"images/Biceps/Alternate hammer curl seated dumbbells.jpg","image_male_end":"images/Biceps/Alternate hammer curl seated dumbbells1.jpg","image_female_start":"images/Biceps/Alternate Hammer Curl Seated Dumbbells_Female.jpg","image_female_end":"images/Biceps/Alternate Hammer Curl Seated Dumbbells_Female1.jpg","video_url":"videos/Biceps/Alternate hammer curl seated dumbbells.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2177eb8c-b301-4550-82eb-f3b1406ee625'::uuid, 'Alternate hammer curl standing dumbbells', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand upright with your feet shoulder-width apart, holding a dumbbell in each hand with your arms fully extended by your sides. Your palms should face each other (neutral grip).\r\n2. Engage your core and keep your elbows close to your torso. Slowly curl the right dumbbell up towards your shoulder, maintaining the neutral grip with your palm facing inward.\r\n3. Squeeze your bicep at the top of the movement, then slowly lower the dumbbell back to the starting position with control.\r\n4. Repeat the same motion with your left arm, alternating between right and left arms for the desired number of repetitions.', E'1. Keep your wrists straight to avoid putting unnecessary strain on them during the curls.\r\n2. Maintain a controlled pace to ensure that you''re using muscle strength rather than momentum.\r\n3. Keep your back straight and shoulders back to maintain proper posture.', '{"image_male_start":"images/Biceps/Alternate hammer curl standing dumbbells.jpg","image_male_end":"images/Biceps/Alternate hammer curl standing dumbbells1.jpg","image_female_start":"images/Biceps/Alternate Hammer Curl Standing Dumbbells_Female.jpg","image_female_end":"images/Biceps/Alternate Hammer Curl Standing Dumbbells_Female1.jpg","video_url":"videos/Biceps/Alternate hammer curl standing dumbbells.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('50d471d8-d42d-4bfb-99be-71f9a9d760ed'::uuid, 'Alternate heel touch side kick squat', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand tall with your back straight, arms by your side, and feet shoulder-width apart.\r\n2. Lower your hips by bending one of your knees while sliding the opposite leg outward on the floor, and touch your heel with your hands.\r\n3. Return to the initial position, and do the same while bending your other knee and sliding the opposite leg. ', E'1. Keep your core engaged to maintain balance and stability throughout the exercise.\r\n2. Ensure your knees do not extend past your toes when squatting to protect your joints.\r\n3. Perform the side leg slides with controlled movements to maintain proper form and avoid injury.', '{"image_male_start":"images/Legs/alternate heel touch side kick squat.jpg","image_male_end":"images/Legs/alternate heel touch side kick squat1.jpg","video_url":"videos/Legs/alternate heel touch side kick squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ca1016bf-eba2-4b14-80ba-f6d0331b930b'::uuid, 'Alternate heel touches', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your knees bent and feet flat on the floor, hip-width apart. Lift your shoulders slightly off the floor, engaging your core.\r\n2. Reach your right hand towards your right heel, then return to the center position.\r\n3. Reach your left hand towards your left heel. Continue alternating sides in this manner.', E'1. Keep your shoulders off the mat and your core engaged throughout the exercise to maximize effectiveness.\r\n2. Focus on using your oblique muscles to reach towards your heels rather than using your arms.\r\n3. Perform the movement slowly and with control to maintain proper form and maximize muscle engagement.', '{"image_male_start":"images/Abdominals/Alternate heel touches.jpeg","video_url":"videos/Abdominals/Alternate heel touches.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0d92bcb0-0187-4dc1-8610-9dc7253837ab'::uuid, 'Alternate Leg Pull', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your legs extended straight just off the floor and your arms extended overhead in line with your torso.\r\n2. Lift your shoulders off the mat, engaging your core, and simultaneously bring your right knee towards your chest while swinging both arms in a circular motion until parallel to the floor.\r\n3. Lower your right leg, arms and shoulders back to the starting position.\r\n4. Repeat the movement with your left leg, bringing it towards your chest between your straight arms. Continue alternating sides in this manner.', E'1. Keep your core engaged throughout the exercise to maximize muscle activation and protect your lower back.\r\n2. Perform the movement slowly and with control to avoid using momentum and ensure proper form.\r\n3. Breathe steadily, exhaling as you crunch and bring your leg towards your chest and inhaling as you lower back down.', '{"image_male_start":"images/Abdominals/Alternate Leg Pull_female.jpeg","video_url":"videos/Abdominals/Alternate leg pull.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3a181163-496d-4726-bf96-7f709f25424b'::uuid, 'Alternate leg raise', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie down on your back with your arms resting on the floor by your side.\r\n2. Raise your legs straight in the air, making a 90-degree angle with your torso.\r\n3. Lower one of your legs and bring it back just before touching the floor.\r\n4. Do the same with your other leg, and repeat.', E'1. Keep your core engaged throughout the exercise to maintain stability and protect your lower back.\r\n2. Perform the movement slowly and with control to maximize muscle activation and prevent injury.\r\n3. Breathe steadily, exhaling as you lift your leg and inhaling as you lower it back down.', '{"image_male_start":"images/Abdominals/Alternate Leg Raise_female.jpeg","video_url":"videos/Abdominals/Alternate leg raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0a91319b-3d00-41fe-8d95-4ed64d38621b'::uuid, 'Alternate Leg Raise from Reverse Plank Position', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie down on your hips with your arms resting on the floor by your side and your legs extended forward.\r\n2. Raise your upper back, bring your elbows under the shoulders, and bear weight on your forearms with your palms down.\r\n3. Alternately raise and lower your legs to your maximum range while keeping them straight.', E'1. Focus on maintaining a straight line with your body, avoiding any sagging or arching of the back.\r\n2. Perform the movement slowly and with control to maximize muscle activation and prevent injury.\r\n3. Breathe steadily, exhaling as you lift your leg and inhaling as you lower it back down.', '{"image_male_start":"images/Abdominals/Alternate Leg Raise from Reverse Plank Position_female.jpeg","video_url":"videos/Abdominals/Alternate leg raise from reverse plank position.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('55b7210d-8339-429b-88ab-3ba1a703a0ff'::uuid, 'Alternate leg raise with head up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie down on your back with your arms resting on the floor by your side.\r\n2. Raise your head and upper back off the floor, and lift your legs straight in the air, making a 90-degree angle with your torso.\r\n3. Lower one of your legs and bring it back just before touching the floor.\r\n4. Do the same with your other leg, and repeat.', E'1. Keep your core engaged throughout the exercise to maintain stability and protect your lower back.\r\n2. Perform the movement slowly and with control to maximize muscle activation and prevent injury.\r\n3. Maintain a steady breathing pattern, exhaling as you lift your leg and inhaling as you lower it back down.', '{"image_male_start":"images/Abdominals/Alternate leg raise with head up.jpeg","video_url":"videos/Abdominals/Alternate leg raise with head up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('00d44923-e92a-4bce-9057-1aeb23f8e28d'::uuid, 'Alternate lying floor leg raise', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your legs extended straight and your arms resting by your sides.\r\n2. Lift both legs, straight towards the ceiling until they go past your hips.\r\n3. Lower your legs halfway down, then lift them back up towards the ceiling.\r\n4. Lower your legs back down to the initial position. Repeat the movement.', E'1. Focus on keeping your upper back pressed into the mat to avoid arching and straining your spine.\r\n2. Use your breath to guide the movement: inhale as you lift your legs and exhale as you lower them.\r\n3. Engage your thigh muscles to assist with the lift and ensure proper form.', '{"image_male_start":"images/Abdominals/Alternate Lying Floor Leg Raise_female.jpeg","video_url":"videos/Abdominals/Alternate lying floor leg raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('46caf49e-6b6c-49ca-a602-c0cd4ac64be6'::uuid, 'Alternate Oblique Crunch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie down on your back and fold your knees while keeping your feet on the floor.\r\n2. Place your right hand behind your head.\r\n3. Raise and twist your chest to your left and bring your right elbow towards the left knee.\r\n3. Return to the starting position and repeat.', E'1. Focus on using your oblique muscles to twist your torso rather than pulling on your neck with your hands.\r\n2. Keep your movements slow and controlled to maximize muscle activation and prevent injury.\r\n3. Ensure your lower back remains pressed into the mat to protect your spine.', '{"image_male_start":"images/Abdominals/Alternate Oblique Crunch_female.jpeg","video_url":"videos/Abdominals/Alternate oblique crunch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('09ee352d-9c2f-4672-8020-3eb3587bc8fa'::uuid, 'Alternate Punching', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your hands held up in a guard position near your chest.\r\n2. Punch forward with your right arm, rotating your upper torso slightly.\r\n3. Return your right hand to the guard position and punch forward with your left arm, again rotating your upper torso slightly.\r\n4. Continue alternating punches in a rhythmic manner.', E'1. Keep your core engaged to maintain balance and stability throughout the exercise.\r\n2. Focus on snapping your punches out quickly and returning your hands to the guard position to maintain proper form.\r\n3. Maintain a slight bend in your knees to absorb the impact and enhance stability.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/alternate punching.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/alternate punching1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/alternate punching.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1e3e34a7-5bd3-4e09-8dba-c1e248d92106'::uuid, 'Alternate Single Leg Raise Plank', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start in a plank position with your hands directly under your shoulders and your body forming a straight line from head to heels.\r\n2. Lift your right leg off the floor, extending it straight back while maintaining the plank position. Hold briefly.\r\n3. Lower your right leg back to the starting position.\r\n4. Lift your left leg off the floor, extending it straight back. Hold briefly before lowering it back to the starting position. Continue alternating sides.', E'1. Keep your core engaged throughout the exercise to maintain stability and prevent your hips from sagging.\r\n2. Perform the movement slowly and with control to maximize muscle activation and prevent injury.\r\n3. Maintain a straight line from head to heels, avoiding any arching or rounding of your back.', '{"image_male_start":"images/Legs/Alternate Single Leg Raise Plank_female.jpg","image_female_start":"images/Legs/Alternate Single Leg Raise Plank_female.jpg","image_female_end":"images/Legs/Alternate Single Leg Raise Plank_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('93f83eee-3dfb-4a3a-9e15-57b24b3e0986'::uuid, 'Alternate single leg raises plank', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start in a plank position with your hands directly under your shoulders and your body forming a straight line from head to heels.\r\n2. Lift your right leg off the floor, extending it straight back while maintaining the plank position. Hold briefly.\r\n3. Lower your right leg back to the starting position.\r\n4. Lift your left leg off the floor, extending it straight back. Hold briefly before lowering it back to the starting position. Continue alternating sides.', E'1. Keep your core engaged throughout the exercise to maintain stability and prevent your hips from sagging.\r\n2. Perform the movement slowly and with control to maximize muscle activation and prevent injury.\r\n3. Maintain a straight line from head to heels, avoiding any arching or rounding of your back.', '{"image_male_start":"images/Abdominals/alternate single leg raises plank.jpeg","video_url":"videos/Abdominals/alternate single leg raises plank.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8a370cc6-48f4-42b9-9836-5cc7c09f3c8e'::uuid, 'Alternate Sprinter Lunge', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet hip-width apart.\r\n2. Lunge back with your right leg, bending both knees to lower your body into a lunge position while reaching your hands towards your left foot.\r\n3. Push off your right foot to return to the starting position.\r\n4. Lunge back with your left leg, reaching your hands towards your right foot. Continue alternating sides.', E'1. Keep your core engaged to maintain balance and stability throughout the exercise.\r\n2. Ensure your front knee does not extend past your toes to avoid strain on your knee joint.\r\n3. Perform the movement slowly and with control to maximize muscle activation and prevent injury.', '{"image_male_start":"images/Yoga/Alternate sprinter lunge.jpg","image_male_end":"images/Yoga/Alternate sprinter lunge1.jpg","image_female_start":"images/Yoga/Alternate Sprinter Lunge_female.jpg","image_female_end":"images/Yoga/Alternate Sprinter Lunge_female1.jpg","video_url":"videos/Yoga/Alternate sprinter lunge.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0688a83f-43e0-43d6-b605-034bd91f4d7d'::uuid, 'Alternate superman', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie face down on a mat with your arms extended straight in front of you and your legs extended straight back.\r\n2. Lift your right arm and left leg simultaneously off the floor, engaging your back muscles. Hold briefly.\r\n3. Lower your right arm and left leg back to the mat.\r\n4. Lift your left arm and right leg simultaneously off the floor, holding briefly before lowering them back to the mat. Continue alternating sides.', E'1. Keep your core engaged throughout the exercise to maintain stability and prevent your lower back from arching excessively.\r\n2. Perform the movement slowly and with control to maximize muscle activation and prevent injury.\r\n3. Focus on lifting your arm and leg to the same height to maintain balance and symmetry.', '{"image_male_start":"images/Back/alternate superman.jpg","image_male_end":"images/Back/alternate superman1.jpg","video_url":"videos/Back/alternate superman.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9d40d317-80fb-436f-bdc6-012410034eed'::uuid, 'Alternate toe tap leg lift', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie down on your back with your knees bent and feet on the floor.\r\n2. Raise your torso off the floor by placing your elbows on the floor and raise one of your knees toward the chest while keeping your knee bent.\r\n3. Lower your foot back to the floor while raising your other knee towards your chest.\r\n4. Keep repeating by alternately moving your knees towards and away from the chest.', E'1. Keep your core engaged throughout the exercise to maintain stability and protect your lower back.\r\n2. Perform the movement slowly and with control to maximize muscle activation and prevent injury.\r\n3. Focus on maintaining the bend in your knees and tapping the floor lightly to ensure proper form.', '{"image_male_start":"images/Abdominals/Alternate Toe Tap Leg Lift_female.jpeg","video_url":"videos/Abdominals/Alternate toe tap leg lift.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('26fe0e10-b495-480e-9b29-8f5be1a88ab1'::uuid, 'Alternating biceps curl seated dumbbells', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench with your feet flat on the floor, holding a dumbbell in each hand with your arms fully extended by your sides. Your palms should face forward (supinated grip).\r\n2. Engage your core and keep your elbows close to your torso. Slowly curl the right dumbbell up towards your shoulder, maintaining the supinated grip with your palm facing upward.\r\n3. Squeeze your bicep at the top of the movement, then slowly lower the dumbbell back to the starting position with control.\r\n4. Repeat the same motion with your left arm, alternating between right and left arms for the desired number of repetitions.', E'1. Visualize the bicep contraction to enhance the mind-muscle connection for better results.\r\n2. Ensure your movements are symmetrical to avoid muscle imbalances; focus equally on both arms.\r\n3. Use a weight that allows you to perform the exercise with proper form and control throughout all repetitions.', '{"image_male_start":"images/Biceps/Alternating biceps curl seated dumbbells.jpg","image_male_end":"images/Biceps/Alternating biceps curl seated dumbbells1.jpg","image_female_start":"images/Biceps/Alternating Biceps Curl Seated Dumbbells_Female.jpg","image_female_end":"images/Biceps/Alternating Biceps Curl Seated Dumbbells_Female1.jpg","video_url":"videos/Biceps/alternating biceps curl seated dumbbells.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ae2951cf-e3c0-4838-9f21-b41c2b56dc09'::uuid, 'alternating biceps hammer curls resistance band', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand upright with your feet shoulder-width apart, standing on the middle of a resistance band. Hold the handles of the band with your palms facing each other (neutral grip) and arms fully extended by your sides.\r\n2. Engage your core and keep your elbows close to your torso. Slowly curl the right handle up towards your shoulder, maintaining the neutral grip with your palm facing inward.\r\n3. Squeeze your bicep at the top of the movement, then slowly lower the handle back to the starting position with control.\r\n4. Repeat the same motion with your left arm, alternating between right and left arms for the desired number of repetitions.', E'1. Keep your back straight and shoulders back to maintain proper posture.\r\n2. Visualize the bicep contraction to enhance the mind-muscle connection for better results.\r\n3. Use a resistance band with appropriate tension to perform the exercise with proper form and control throughout all repetitions.\r\n', '{"image_male_start":"images/Biceps/alternating biceps hammer curls resistance band.jpeg","video_url":"videos/Biceps/alternating biceps hammer curls resistance band.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f2c305e5-e4ae-4991-a559-9f440b4e0122'::uuid, 'Alternating hammer curls seated dumbbells', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench with your feet flat on the floor, holding a dumbbell in each hand with your arms fully extended by your sides. Your palms should face each other (neutral grip).\r\n2. Engage your core and keep your elbows close to your torso. Slowly curl the right dumbbell up towards your shoulder, maintaining the neutral grip with your palm facing inward.\r\n3. Squeeze your bicep at the top of the movement, then slowly lower the dumbbell back to the starting position with control.\r\n4. Repeat the same motion with your left arm, alternating between right and left arms for the desired number of repetitions.', E'1. Avoid swinging your arms to ensure that the movement is controlled and targets the biceps effectively.\r\n2. Keep your movements steady and controlled to maximize muscle engagement and minimize risk of injury.\r\n3. Ensure your elbows stay close to your torso to focus the effort on your biceps.', '{"image_male_start":"images/Biceps/alternating hammer curls seated dumbbells.jpeg","video_url":"videos/Biceps/alternating hammer curls seated dumbbells .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('44e42e75-01a9-4922-9ff4-1d242df1046b'::uuid, 'Alternating hamstring curl with punch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your arms bent at a 90-degree angle with fists close to your chest.\r\n2. Curl your right leg back, bringing your heel towards your glutes while simultaneously punching forward with your left arm.\r\n3. Lower your right leg and return your left arm to the starting position.\r\n4. Curl your left leg back, bringing your heel towards your glutes while punching forward with your right arm. Continue alternating sides.', E'1. Focus on squeezing your hamstrings and glutes as you curl your leg to enhance muscle activation.\r\n2. Keep a steady rhythm to ensure both sides of your body are working evenly.\r\n3. Maintain a strong and upright posture to avoid unnecessary strain on your back.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Alternating hamstring curl with punch.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Alternating hamstring curl with punch1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Alternating hamstring curl with punch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('132e6682-1820-4f56-851b-ac2640fc0f56'::uuid, 'Alternating leg downward dog', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start in a downward dog position with your hands and feet on the mat, hips lifted towards the ceiling, and body forming an inverted V shape.\r\n2. Bend your right knee towards your chest, keeping your foot on the floor and maintaining balance on your left foot and both hands.\r\n3. Straighten your right leg back to the starting position.\r\n4. Bend your left knee towards your chest while maintaining balance. Continue alternating sides. ', E'1. Keep your core engaged to maintain stability and balance throughout the exercise.\r\n2. Focus on keeping your hips squared and aligned with the mat to avoid twisting your body.\r\n3. Perform the movement slowly and with control to maximize muscle activation and prevent injury.', '{"image_male_start":"images/Yoga/Alternating leg downward dog.jpg","image_male_end":"images/Yoga/Alternating leg downward dog1.jpg","image_female_start":"images/Yoga/Alternating Leg Downward Dog_female.jpg","image_female_end":"images/Yoga/Alternating Leg Downward Dog_female1.jpg","video_url":"videos/Yoga/Alternating leg downward dog.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6de0704c-b9ce-4c72-a35b-62f12fd7b190'::uuid, 'Alternating leg lifts', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie down on your back with your legs straight and hands behind your head.\r\n2. Raise one of your legs straight towards the ceiling without bending your knee.\r\n3. Slowly lower your leg back towards the floor and simultaneously raise the other leg.', E'1. Keep your lower back pressed into the mat to maintain proper alignment and avoid strain.\r\n2. Use a controlled breathing pattern: inhale as you lift your leg and exhale as you lower it.\r\n3. Engage your thigh muscles to assist with the lift and maintain straight legs throughout the movement.', '{"image_male_start":"images/Abdominals/Alternating Leg Lifts.jpg","image_male_end":"images/Abdominals/Alternating Leg Lifts1.jpg","image_female_start":"images/Abdominals/Alternating Leg Lifts_Female.jpg","image_female_end":"images/Abdominals/Alternating Leg Lifts_Female1.jpg","video_url":"videos/Abdominals/Alternating Leg Lifts.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5e65b5e0-9cbc-482e-9dbb-5de9c01aa0cb'::uuid, 'Alternating Lunge with Rotation', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start in a plank position with your hands directly under your shoulders and your body forming a straight line from head to heels.\r\n2. Step your right foot forward, placing it outside your right hand, and rotate your torso to the right, extending your right arm towards the ceiling.\r\n3. Return your right hand and foot to the plank position.\r\n4. Step your left foot forward, placing it outside your left hand, and rotate your torso to the left, extending your left arm towards the ceiling. Return to the plank position. Continue alternating sides.', E'1. Keep your core engaged to maintain stability and proper alignment throughout the movement.\r\n2. Ensure your front knee is aligned with your ankle and does not extend past your toes to avoid strain on your knee joint.\r\n3. Perform the movement slowly and with control to maximize muscle activation and prevent injury.', '{"image_male_start":"images/Yoga/Alternating Lunge with Rotation.jpeg","video_url":"videos/Yoga/Alternating Lunge with Rotation.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('873a7e5e-621f-4d2f-9e26-3c680b23f0c5'::uuid, 'Alternating oblique sit ups', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your knees bent and feet flat on the floor. Place your hands lightly behind your head with your elbows pointing outward.\r\n2. Lift your shoulders off the mat and twist your torso to bring your right elbow towards your left knee.\r\n3. Lower your shoulders back to the starting position.\r\n4. Repeat the movement on the opposite side, bringing your left elbow towards your right knee. Continue alternating sides.', E'1. Engage your core throughout the exercise to maximize muscle activation and protect your lower back.\r\n2. Avoid pulling on your neck with your hands to prevent strain; use your core muscles to lift and twist your torso.\r\n3. Perform the movement slowly and with control to ensure proper form and maximize effectiveness.', '{"image_male_start":"images/Abdominals/alternating oblique sit ups.jpeg","video_url":"videos/Abdominals/alternating oblique sit ups .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('be5a6284-45ec-434f-b8b1-07b6d02fe8ca'::uuid, 'Alternating Plank Lunge', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start in a plank position with your hands directly under your shoulders and your body forming a straight line from head to heels.\r\n2. Step your right foot forward outside your right hand, bringing your body into a low lunge position.\r\n3. Return your right foot to the plank position.\r\n4. Step your left foot forward outside your left hand, bringing your body into a low lunge position. Return your left foot to the plank position. Continue alternating sides.', E'1. Keep your core engaged throughout the exercise to maintain stability and proper alignment.\r\n2. Ensure your front knee is aligned with your ankle and does not extend past your toes to avoid strain on your knee joint.\r\n3. Perform the movement slowly and with control to maximize muscle activation and prevent injury.', '{"image_male_start":"images/Abdominals/Alternating Plank Lunge.jpeg","video_url":"videos/Abdominals/Alternating Plank Lunge.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5b37bf5e-d4fe-4c55-ad68-7b6e10f78fe8'::uuid, 'Alternating step out', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand tall with your back straight and your feet shoulder-width apart.\r\n2. Bend your knees slightly and clasp your hands in front of your chest.\r\n3. Lift one of your feet off the floor and step to your side.\r\n4. Return to the initial position and do the same with your other foot. Repeat.', E'1. Focus on keeping your upper body upright and avoid leaning too far forward or backward.\r\n2. Use a steady pace to maintain a rhythm, which will help with coordination and balance.\r\n3. Breathe steadily, exhaling as you step out and inhaling as you return to the starting position.', '{"image_male_start":"images/Legs/Alternating step out.jpg","image_male_end":"images/Legs/Alternating step out1.jpg","image_female_start":"images/Legs/Alternating Step Out_female.jpg","image_female_end":"images/Legs/Alternating Step Out_female1.jpg","video_url":"videos/Legs/Alternating step out.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('84560c82-13e7-49c6-8713-1ea749c5739b'::uuid, 'Alternating Superman', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie face down on a mat with your arms extended straight in front of you and your legs extended straight behind you.\r\n2. Lift your right arm and left leg simultaneously off the floor, engaging your core and back muscles. Hold briefly.\r\n3. Lower your right arm and left leg back to the mat.\r\n4. Lift your left arm and right leg simultaneously off the floor, holding briefly before lowering them back to the mat. Continue alternating sides.', E'1. Engage your core throughout the exercise to maintain stability and protect your lower back.\r\n2. Focus on lifting your arm and leg to the same height to maintain balance and symmetry.\r\n3. Perform the movement slowly and with control to maximize muscle activation and prevent injury.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b37da8f9-b544-43c6-b689-27063b3eb547'::uuid, 'Alternating toe tap', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your legs extended straight on the floor and your arms resting by your sides.\r\n2. Simultaneously lift your right leg and left arm towards the ceiling, trying to touch your toe with your hand.\r\n3. Lower your right leg and left arm back to the starting position.\r\n4. Repeat the movement with your left leg and right arm, lifting them towards the ceiling and trying to touch your toe with your hand. Continue alternating sides.', E'1. Engage your core throughout the exercise to maintain stability and protect your lower back.\r\n2. Perform the movement slowly and with control to maximize muscle activation and prevent injury.\r\n3. Keep your legs straight and avoid bending your knees to ensure proper form.', '{"image_male_start":"images/Abdominals/alternating toe tap.jpeg","video_url":"videos/Abdominals/alternating toe tap .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f3ab07d0-ce5c-4b0f-b6d3-29348bf5bf0b'::uuid, 'Ankle - Dorsal Flexion', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your hands resting on your hips or at your sides for balance.\r\n2. Flex both feet simultaneously, bringing your toes towards your shins, and then return to the starting position.\r\n3. Repeat the movement, flexing and relaxing both feet simultaneously.', E'1. Keep your core engaged to maintain balance and stability throughout the exercise.\r\n2. Perform the movement slowly and with control to maximize muscle activation and prevent injury.\r\n3. Focus on the movement of your ankles and avoid using your leg muscles to assist.', '{"image_male_start":"images/Legs/Ankle - Dorsal Flexion_female.jpg","image_female_start":"images/Legs/Ankle - Dorsal Flexion_female.jpg","image_female_end":"images/Legs/Ankle - Dorsal Flexion_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f0ce3af2-d767-4931-a3c2-05adf5c6b8ac'::uuid, 'Ankle - Plantar Flexion', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your hands resting on your hips or at your sides for balance..\r\n2. Rise onto your toes, lifting your heels off the floor.\r\n3. Lower your heels back to the starting position. Repeat the movement.', E'1. Keep your knees slightly bent to reduce strain on your joints and enhance stability.\r\n2. Use a mirror to check your form and ensure that your ankles are aligned properly.\r\n3. Focus on maintaining a steady breathing pattern, exhaling as you rise and inhaling as you lower.', '{"image_male_start":"images/Legs/Ankle - Plantar Flexion_female.jpg","image_female_start":"images/Legs/Ankle - Plantar Flexion_female.jpg","image_female_end":"images/Legs/Ankle - Plantar Flexion_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('cd29dbb1-ca67-46ed-bbf3-1954485d8291'::uuid, 'Ankle Circles', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, hands at your hips.\r\n2. Lift your right foot off the floor slightly and rotate your ankle in a circular motion, making small controlled circles.\r\n3. After a set number of rotations, switch direction and rotate your ankle in the opposite direction.\r\n4. Repeat the movement with your left ankle, rotating in both directions.', E'1. Keep your core engaged to maintain balance and stability throughout the exercise.\r\n2. Ensure your leg remains still and only your ankle is moving to focus on the targeted muscles.\r\n3. Perform the exercise for an equal amount of time or repetitions in both directions to ensure balanced muscle development.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Ankle circles.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Ankle circles1.jpg","image_female_start":"images/Legs/Ankle Circles_female.jpg","image_female_end":"images/Legs/Ankle Circles_female1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Ankle circles.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('67b5fb3e-640e-4266-b48b-0c1d11635754'::uuid, 'Ankle dorsal flexion', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your hands resting on your hips or at your sides for balance.\r\n2. Flex both feet simultaneously, bringing your toes towards your shins, and then return to the starting position.\r\n3. Repeat the movement, flexing and relaxing both feet simultaneously.', E'1. Keep your core engaged to maintain balance and stability throughout the exercise.\r\n2. Perform the movement slowly and with control to maximize muscle activation and prevent injury.\r\n3. Focus on the movement of your ankles and avoid using your leg muscles to assist.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/ankle dorsal flexion.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/ankle dorsal flexion1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/ankle dorsal flexion.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5ddf11ed-b13c-4458-93fc-b3a4ddffa7c6'::uuid, 'Ankle plantar flexion', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your hands resting on your hips or at your sides for balance..\r\n2. Rise onto your toes, lifting your heels off the floor.\r\n3. Lower your heels back to the starting position. Repeat the movement.', E'1. Keep your knees slightly bent to reduce strain on your joints and enhance stability.\r\n2. Use a mirror to check your form and ensure that your ankles are aligned properly.\r\n3. Focus on maintaining a steady breathing pattern, exhaling as you rise and inhaling as you lower.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/ankle plantar flexion.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/ankle plantar flexion1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/ankle plantar flexion.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8baf8e9f-3e4e-45a6-823e-7f09e7ffa19b'::uuid, 'Archer pull up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '54938b47-43e8-47cd-9efc-18b4424e71e1'::uuid, E'1. Hang from a pull-up bar with your hands positioned wider than shoulder-width apart.\r\n2. Pull yourself up towards the bar while simultaneously shifting your body to the right, bringing your chest closer to your right hand.\r\n3. Lower yourself back to the starting position.\r\n4. Pull yourself up again, this time shifting your body to the left, bringing your chest closer to your left hand. Continue alternating sides.', E'1. Focus on using your back muscles rather than relying solely on your arms for the pull-up.\r\n2. Keep your elbows slightly bent throughout the movement to reduce strain on your joints.\r\n3. Ensure a full range of motion by fully extending your arms at the bottom of each rep and bringing your chest close to the bar at the top.', '{"image_male_start":"images/Back/Archer pull up.jpg","image_male_end":"images/Back/Archer pull up1.jpg","video_url":"videos/Back/Archer pull up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6cfcbecf-8148-48fd-b88d-b39c70d1af49'::uuid, 'Archer push up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start in a push-up position with your hands placed wider than shoulder-width apart and your body forming a straight line from head to heels.\r\n2. Bend your right elbow to lower your chest towards your right hand while keeping your left arm extended straight to the side.\r\n3. Push back up to the starting position.\r\n4. Bend your left elbow to lower your chest towards your left hand while keeping your right arm extended straight to the side. Continue alternating sides.', E'1. Ensure your shoulders and hips stay level to avoid any imbalance during the movement.\r\n2. Use a slow and steady breathing pattern, exhaling as you push up and inhaling as you lower down.\r\n3. Keep your gaze slightly forward to maintain a neutral spine and avoid neck strain.', '{"image_male_start":"images/Chest/Archer push up.jpg","image_male_end":"images/Chest/Archer push up1.jpg","image_female_start":"images/Chest/Archer Push up_female.jpg","image_female_end":"images/Chest/Archer Push up_female1.jpg","video_url":"videos/Chest/Archer push up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8b05c8bf-f6ea-4bdd-bab6-26f7fadf43b9'::uuid, 'Archer step back', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand tall with your back straight and feet shoulder-width apart.\r\n2. Extend your arms forward while keeping your palms inward.\r\n3. Take a step backward by extending your left leg behind you while taking your elbow past your back like an archer.\r\n4. Hold for a while, return to the initial position, and repeat by taking your right leg backward.', E'1. Engage your core to maintain balance and stability throughout the exercise.\r\n2. Ensure your front knee is aligned with your ankle and does not extend past your toes to avoid strain on your knee joint.\r\n3. Perform the movement with controlled motions to maximize muscle activation and prevent injury.', '{"image_male_start":"images/Yoga/Archer step back.jpg","image_male_end":"images/Yoga/Archer step back1.jpg","video_url":"videos/Yoga/Archer step back.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6026c850-8176-4c21-8b2d-c2c7c38a20a2'::uuid, 'Archer Stepback', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand tall with your back straight and feet shoulder-width apart.\r\n2. Extend your arms forward while keeping your palms inward.\r\n3. Take a step backward by extending your left leg behind you while taking your elbow past your back like an archer.\r\n4. Hold for a while, return to the initial position, and repeat by taking your right leg backward.', E'1. Engage your core to maintain balance and stability throughout the exercise.\r\n2. Ensure your front knee is aligned with your ankle and does not extend past your toes to avoid strain on your knee joint.\r\n3. Perform the movement with controlled motions to maximize muscle activation and prevent injury.', '{"image_male_start":"images/Yoga/Archer Stepback_female.jpg","image_female_start":"images/Yoga/Archer Stepback_female.jpg","image_female_end":"images/Yoga/Archer Stepback_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('555c49f1-b096-455e-a95d-7398b2f20a64'::uuid, 'Arm circle', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your arms extended straight to your sides.\r\n2. Begin by making circular motions with your arms, moving them forward in a controlled manner.\r\n3. Repeat for the desired repetitions.', E'1. Engage your core to maintain stability and balance throughout the exercise.\r\n2. Perform the movement slowly and with control to maximize muscle activation and prevent injury.\r\n3. Keep your arms straight and focus on making smooth, controlled circles to ensure proper form.', '{"image_male_start":"images/Shoulders/arm circle.jpg","image_male_end":"images/Shoulders/arm circle1.jpg","video_url":"videos/Shoulders/arm circle.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('fe6c7b79-eed9-4ae8-8d14-44b0e129c1dc'::uuid, 'Arm circles backward', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your arms extended straight to your sides.\r\n2. Begin by making circular motions with your arms, moving them backward in a controlled manner.\r\n3. Repeat for the desired repetitions.', E'1. Engage your core to maintain stability and balance throughout the exercise.\r\n2. Perform the movement slowly and with control to maximize muscle activation and prevent injury.\r\n3. Keep your arms straight and focus on making smooth, controlled circles to ensure proper form.', '{"image_male_start":"images/Shoulders/Arm circles backward.jpg","image_male_end":"images/Shoulders/Arm circles backward1.jpg","video_url":"videos/Shoulders/Arm circles backward.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('fed0d64f-d48c-450f-b160-fa0f8665ff2d'::uuid, 'Arm crossover', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your arms extended straight out to the sides at shoulder height, palms facing the floor.\r\n2. Bring your arms forward and cross them in front of your chest.\r\n3. Return your arms to the starting position, extending them out to the sides.\r\n4. Continue crossing your arms in front of your chest and extending them back out to the sides in a controlled, rhythmic manner.', E'1. Maintain an upright posture to avoid straining your back and neck.\r\n2. Use a consistent pace to help coordinate your movements and keep them fluid.\r\n3. Breathe steadily, exhaling as you cross your arms and inhaling as you extend them back out.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Arm crossover.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Arm crossover1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Arm crossover.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6bf51d18-b6a5-4696-a36b-699b43175a40'::uuid, 'Arm crossover chest out', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your arms extended out to the sides at shoulder height, elbows bent and palms facing the floor.\r\n2. Bring your arms forward while straightening them and cross them in front of your chest twice.\r\n3. Return your arms to the starting position, extending them out to the sides and bringing your chest forward.\r\n4. Continue crossing your arms in front of your chest and extending them back out to the sides in a controlled, rhythmic manner.', E'1. Keep your shoulders relaxed to avoid unnecessary tension in your neck and upper back.\r\n2. Use a mirror to ensure your movements are symmetrical and maintain proper form.\r\n3. Breathe deeply, exhaling as you cross your arms and inhale as you extend them back out.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Arm crossover chest out.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Arm crossover chest out1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Arm crossover chest out.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('95a0eaa0-7751-48dd-8cab-b36d941e6232'::uuid, 'Arm double crossover', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your arms extended out to the sides at shoulder height, elbows bent and palms facing the floor.\r\n2. Bring your arms forward while keeping them bent and cross them in front of your chest twice.\r\n3. Return your arms to the starting position, extending them out to the sides.\r\n4. Continue crossing your arms in front of your chest and extending them back out to the sides in a controlled, rhythmic manner.', E'1. Keep your movements smooth and controlled to maximize muscle activation and prevent injury.\r\n2. Alternate which arm crosses over the other each time to ensure balanced muscle engagement.\r\n3. Maintain an upright posture and engage your core to support your back and maintain balance.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Arm double crossover.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Arm double crossover1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Arm double crossover.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0bd69414-526e-4b85-a26d-0af47baff9ba'::uuid, 'Arm pulses', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand tall with your back straight and feet shoulder-width apart.\r\n2. Bend your arms to make a 90-degree angle with the elbows while keeping your palms facing inward.\r\n3. Tighten your upper arms and move your arms forward and backward in a pulse-like fashion.\r\n4. Keep doing this activity for a suitable time.', E'1. Engage your core to maintain stability and support your back throughout the exercise.\r\n2. Keep your movements small and controlled to maximize muscle activation and prevent injury.\r\n3. Focus on keeping your shoulders relaxed and avoid tensing your neck and upper back.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/arm pulses  .jpg","video_url":"videos/Calisthenics-Cardio-Functional/arm pulses  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('942aee5b-26ac-49a4-9dbc-6d4a47669a64'::uuid, 'Arm pulses cross', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand tall with your back straight and feet shoulder-width apart.\r\n2. Bring your forearms forward with your palms facing the floor and make a 90-degree angle with your upper arms.\r\n3. Tighten your upper arms and move your hands towards each other.\r\n4. As your one hand comes over the other one, return to the initial position and repeat.', E'1. Engage your core to maintain stability and support your back throughout the exercise.\r\n2. Keep your movements small and controlled to maximize muscle activation and prevent injury.\r\n3. Focus on maintaining an even rhythm and alternating the crossover to ensure balanced muscle engagement.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/arm pulses cross  .jpg","video_url":"videos/Calisthenics-Cardio-Functional/arm pulses cross  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7f3ff4ed-e0a8-4cf0-ab05-2dbdc18d0a5e'::uuid, 'Arm pulses palms downwards', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your arms bent at the elbows, with your forearms parallel to the floor and palms facing upwards.\r\n2. Perform small, quick pulses by moving your forearms forward and backward, maintaining the position and height.\r\n3. Continue pulsing in a controlled, rhythmic manner for the desired duration or number of repetitions.\r\n', E'1. Engage your core to maintain stability and support your back throughout the exercise.\r\n2. Keep your shoulders relaxed and avoid tensing your neck and upper back.\r\n3. Focus on maintaining a consistent pace and range of motion to ensure proper form.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/arm pulses palms downwards  .jpg","video_url":"videos/Calisthenics-Cardio-Functional/arm pulses palms downwards  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8e3e22a5-5aa7-4d50-82a0-6a78150a02e5'::uuid, 'Arm pulses palms upwards', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your arms bent at the elbows, with your forearms parallel to the floor and palms facing downwards.\r\n2. Perform small, quick pulses by moving your forearms forward and backward, maintaining the position and height.\r\n3. Continue pulsing in a controlled, rhythmic manner for the desired duration or number of repetitions.\r\n', E'1. Engage your core to maintain stability and support your back throughout the exercise.\r\n2. Keep your shoulders relaxed and avoid tensing your neck and upper back.\r\n3. Focus on maintaining a consistent pace and range of motion to ensure proper form.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/arm pulses palms upwards  .jpg","video_url":"videos/Calisthenics-Cardio-Functional/arm pulses palms upwards  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c8e6fa7b-a32f-4c40-911c-06be1278e271'::uuid, 'Arm rotation knee lift', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand tall with your back straight and feet shoulder-width apart.\r\n2. Fold your arms at your sides and make fists with your hands near your chest.\r\n3. Raise your right knee while rotating your torso to the left side and back to the right side.\r\n4. Return to the initial position and repeat by raising your other knee.', E'1. Focus on lifting your knee high to fully engage your hip flexors.\r\n2. Use your oblique muscles to initiate the twist, enhancing the rotational movement.\r\n3. Maintain an even pace to ensure both sides of your body are working evenly.', '{"image_male_start":"images/Abdominals/Arm rotation knee lift.jpeg","video_url":"videos/Abdominals/Arm rotation knee lift.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('43ab6c9d-af1d-4fcf-943f-5755f4cd2ba7'::uuid, 'Arm swing side to side', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your arms extended straight out to the sides at shoulder level, palms facing forward.\r\n2. Swing your arms forward until they meet and cross together in front of you in a hugging motion.\r\n3. Swing your arms back to the starting position.\r\n4. Continue swinging your arms forward and back in a controlled, rhythmic manner.', E'1. Keep your arms at shoulder level to ensure proper form and muscle activation.\r\n2. Engage your core to maintain stability and control throughout the movement.\r\n3. Focus on smooth, controlled movements to maximize the effectiveness of the exercise and avoid injury.', '{"image_male_start":"images/Shoulders/arm swing side to side .jpg","video_url":"videos/Shoulders/arm swing side to side .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('99d56d3c-ae6c-4f64-9635-0a708c9202c3'::uuid, 'Arm Tuck Side Bend', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet slightly wider than shoulder-width apart, with your right arm extended straight out to the side at shoulder height and palm facing upwards and your left hand resting on your hip.\r\n2. Bend your right arm at the elbow, bringing your hand down towards your lower back.\r\n3. Return your right arm to the extended position.\r\n4. Continue the movement with the same arm for the desired number of repetitions.', E'1. Focus on keeping your shoulder relaxed to avoid tension in your neck and upper back.\r\n2. Maintain a steady rhythm to ensure consistent movement and effective muscle engagement.\r\n3. Use a mirror, if available, to check your form.', '{"image_male_end":"images/Shoulders/Arm Tuck Side Bend_female.jpg","image_female_start":"images/Shoulders/Arm Tuck Side Bend_female.jpg","image_female_end":"images/Shoulders/Arm Tuck Side Bend_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a4a9f340-4343-4710-b627-358e2421cb98'::uuid, 'Armless Prayer Stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin on your knees, spread wide and feet touching, with your elbows on the floor, directly under your shoulders.\r\n2. Place your hands on your shoulders, with your head positioned between your elbows close to the floor.\r\n3. Gently lower your chest towards the floor, keeping your hips over your knees and your back straight.\r\n4. Hold the stretch briefly, then return to the starting position. Repeat the movement.', E'1. Engage your core to maintain stability and support your lower back throughout the exercise.\r\n2. Focus on lowering your chest towards the floor to maximize the stretch in your shoulders and upper back.\r\n3. Keep the stretch at least between 15-20 seconds to make the most out of it.', '{"image_male_start":"images/Stretching - Mobility/Armless Prayer Stretch_female.jpg","image_female_start":"images/Stretching - Mobility/Armless Prayer Stretch_female.jpg","image_female_end":"images/Stretching - Mobility/Armless Prayer Stretch_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d131fac4-d1ce-4bc2-9b62-e169046e1ed5'::uuid, 'Arms behind back shoulder flexor stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Stand upright with your feet shoulder-width apart and arms at your sides.\r\n2. Bring both arms behind your back. Set your forearms parallel to the floor, crossing one over the other to stretch your shoulders.\r\n3. Hold the stretch for 15-30 seconds, feeling the stretch in your shoulders. Return to the starting position and repeat as needed.', E'1. Keep your shoulders down and away from your ears to avoid unnecessary tension in your neck.\r\n2. Use gentle pressure when crossing your arms behind your back to deepen the stretch gradually.\r\n3. Ensure your upper body is relaxed and avoid forcing the stretch to prevent discomfort or injury.\r\n', '{"image_male_start":"images/Shoulders/arms behind back shoulder flexor stretch.jpg","video_url":"videos/Shoulders/arms behind back shoulder flexor stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e387c216-6278-4648-a416-4c048659a192'::uuid, 'Arms up and down', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart. Extend your right arm straight up overhead and your left arm straight down by your side.\r\n2. Simultaneously lower your right arm while raising your left arm, keeping both arms straight, until your right arm is down by your side and your left arm is overhead.\r\n3. Continue alternating the arms in a controlled, rhythmic swinging motion, moving one arm up while the other moves down.', E'1. Keep your movements smooth and rhythmic to enhance coordination and balance.\r\n2. Use a steady breathing pattern, inhaling as you raise an arm and exhaling as you lower it.\r\n3. Focus on extending through your fingertips to fully engage your shoulder and upper back muscles.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Arms up and down.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Arms up and down1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Arms up and down.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('68ac8f0f-6274-4c80-a60d-c477a7bcff31'::uuid, 'Arnold press cable Resistance band standing', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand tall with your back straight, feet shoulder-width apart, in the middle of a resistance band.\r\n2. Hold the band handles with your arms bent close to your chest and palms facing back.\r\n3. Push the handles up, while rotating your arms and hands to look forward, and extending your arms overhead.\r\n4. Return to the initial position by reversing the movement and repeat for the desired repetitions.', E'1. Exhale as you press the band overhead and inhale as you lower it back down.\r\n2. Use a resistance band with appropriate tension to ensure you can perform the exercise with good form.\r\n3. Maintain a neutral wrist position to reduce strain on your joints.', '{"image_male_start":"images/Shoulders/arnold press cable resistance band standing.jpg","image_male_end":"images/Shoulders/arnold press cable resistance band standing1.jpg","video_url":"videos/Shoulders/arnold press cable resistance band standing.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('912d7c81-d0e7-4b71-9fd1-0d66f7f5986d'::uuid, 'Arnold press dumbbell', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench with back support, holding a dumbbell in each hand. Start with your arms bent, palms facing your shoulders, and elbows close to your torso.\r\n2. Press your back against the bench. Begin to press the dumbbells overhead. As you press, rotate your palms so they face forward at the top of the movement.\r\n3. Fully extend your arms at the top, ensuring your biceps are near your ears.\r\n4. Slowly lower the dumbbells back to the starting position by rotating your palms back towards your shoulders. Repeat for the desired number of repetitions.', E'1. Rotate your wrists smoothly during the pressing and lowering phases to avoid strain.\r\n2. Breathe steadily, exhaling as you press the weights up and inhaling as you lower them back down.\r\n3. Keep your feet firmly planted to provide a stable base of support.\r\n4. Focus on the full range of motion to engage all parts of the shoulder muscles effectively.', '{"image_male_start":"images/Shoulders/arnold press dumbbell.jpg","image_male_end":"images/Shoulders/arnold press dumbbell1.jpg","video_url":"videos/Shoulders/arnold press dumbbell.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0f78044b-54e6-41d8-b135-1c1885d708c1'::uuid, 'around the world superman hold', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie face down on a mat with your arms extended straight to your sides and your legs extended straight behind you.\r\n2. Lift your arms, chest, and legs off the floor, holding the Superman position.\r\n3. Move your arms in a circular motion, starting from the initial position, sweeping them around straight forward, and back to the starting position.\r\n4. Continue moving your arms in a controlled, rhythmic manner while maintaining the Superman hold.', E'1. Engage your core and glutes to maintain stability and support your lower back throughout the exercise.\r\n2. Perform the arm movement slowly and with control to maximize muscle activation and prevent injury.\r\n3. Focus on keeping your legs and chest lifted off the floor to maintain the Superman hold.', '{"image_male_start":"images/Back/around the world superman hold.jpg","image_male_end":"images/Back/around the world superman hold1.jpg","video_url":"videos/Back/around the world superman hold.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('aaee053e-6c18-4722-8c9f-e4f1ac55aa29'::uuid, 'Assisted chin up normal width reverse grip', 'Resistance', 'strength', 'weight_reps', 'intermediate', '41ba8c93-2898-4292-8990-ecff221d46bf'::uuid, E'1. Kneel on the platform pad of an assisted chin-up machine and grasp the handles with a reverse grip (palms facing you) at shoulder-width apart.\r\n2. Begin the movement by pulling your body upward until your chin is above the bar.\r\n3. Slowly lower your body back to the starting position with control, fully extending your arms.\r\n4. Repeat the movement for the desired number of repetitions, maintaining proper form throughout the exercise.', E'1. Keep your elbows close to your body and avoid flaring them out.\r\n2. Use an appropriate level of assistance on the machine to ensure you can perform the exercise correctly.\r\n3. Exhale as you pull your body upward and inhale as you lower it back down.', '{"image_male_start":"images/Back/assisted chin up normal width reverse grip .jpg","video_url":"videos/Back/assisted chin up normal width reverse grip .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('445e4443-59e7-428b-9a4a-a32a9f03b0f5'::uuid, 'Assisted chin up reverse close grip', 'Resistance', 'strength', 'weight_reps', 'intermediate', '41ba8c93-2898-4292-8990-ecff221d46bf'::uuid, E'1. Kneel on the platform pad of an assisted chin-up machine and grasp the handles with a reverse grip (palms facing you) positioned close together.\r\n2. Begin the movement by pulling your body upward until your chin is above the bar.\r\n3. Slowly lower your body back to the starting position with control, fully extending your arms.\r\n4. Repeat the movement for the desired number of repetitions, maintaining proper form throughout the exercise.', E'1. Keep your elbows close to your body and avoid flaring them out.\r\n2. Use an appropriate level of assistance on the machine to ensure you can perform the exercise correctly.\r\n3. Exhale as you pull your body upward and inhale as you lower it back down.', '{"image_male_start":"images/Back/assisted chin up reverse close grip .jpg","video_url":"videos/Back/assisted chin up reverse close grip .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('dd6265af-19a1-475a-963c-70769b28220c'::uuid, 'Assisted chin up reverse wide grip', 'Resistance', 'strength', 'weight_reps', 'intermediate', '41ba8c93-2898-4292-8990-ecff221d46bf'::uuid, E'1. Kneel on the platform pad of an assisted chin-up machine and grasp the handles with a reverse grip (palms facing you) positioned wider than shoulder-width apart.\r\n2. Begin the movement by pulling your body upward until your chin is above the bar.\r\n3. Slowly lower your body back to the starting position with control, fully extending your arms.\r\n4. Repeat the movement for the desired number of repetitions, maintaining proper form throughout the exercise.', E'1. Keep your elbows close to your body and avoid flaring them out.\r\n2. Use an appropriate level of assistance on the machine to ensure you can perform the exercise correctly.\r\n3. Exhale as you pull your body upward and inhale as you lower it back down.', '{"image_male_start":"images/Back/assisted chin up reverse wide grip .jpg","video_url":"videos/Back/assisted chin up reverse wide grip .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a9fe9f48-5f5c-4be9-8398-773267eb88d7'::uuid, 'Assisted Chin-up on a bench', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '019acf06-8639-4d82-b2d1-c9065d110fb0'::uuid, E'1. Stand on a bench with your hands gripping a pull-up bar, palms facing towards you (supinated grip).\r\n2. Use your legs to assist in pulling your body up towards the bar until your chin is above the bar.\r\n3. Lower your body back down to the starting position, maintaining control throughout the movement.\r\n4. Continue the movement in a controlled, rhythmic manner, using the bench for assistance.', E'1. Focus on keeping your body aligned and avoid swinging to ensure proper form.\r\n2. Use your legs for assistance, but focus on using your arms and back muscles to perform the pull-up.\r\n3. Breathe steadily, exhaling as you pull up and inhaling as you lower yourself down.', '{"image_male_start":"images/Back/Assisted Chin-up on a bench_female.jpg","image_female_start":"images/Back/Assisted Chin-up on a bench_female.jpg","image_female_end":"images/Back/Assisted Chin-up on a bench_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f5d8897f-cb10-408f-943a-e6e5c74ff923'::uuid, 'Assisted close grip underhand chin up', 'Resistance', 'strength', 'weight_reps', 'intermediate', '41ba8c93-2898-4292-8990-ecff221d46bf'::uuid, E'1. Kneel on the platform pad of an assisted chin-up machine and grasp the handles with a reverse grip (palms facing you) at shoulder-width apart.\r\n2. Begin the movement by pulling your body upward until your chin is above the bar.\r\n3. Slowly lower your body back to the starting position with control, fully extending your arms.\r\n4. Repeat the movement for the desired number of repetitions, maintaining proper form throughout the exercise.', E'1. Keep your elbows close to your body and avoid flaring them out.\r\n2. Use an appropriate level of assistance on the machine to ensure you can perform the exercise correctly.\r\n3. Exhale as you pull your body upward and inhale as you lower it back down.', '{"image_male_start":"images/Back/Assisted close grip underhand chin up.jpg","image_male_end":"images/Back/Assisted close grip underhand chin up1.jpg","video_url":"videos/Back/Assisted close grip underhand chin up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('446cb1f9-92f6-4905-a98f-4eb5ed4119f3'::uuid, 'Assisted Close-grip Underhand Chin-up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Position yourself on the assisted pull-up machine, placing your knees on the pad and gripping the pull-up bar with a close underhand (supinated) grip. \r\n2. Pull your body up towards the bar until your chin is above the bar, using the assistance from the machine.\r\n3. Lower your body back down to the starting position, maintaining control throughout the movement.\r\n4. Continue the movement in a controlled, rhythmic manner.', E'1. Keep your elbows close to your body to maximize bicep and back engagement.\r\n2. Focus on using your arms and back muscles to perform the pull-up, with the machine providing just enough assistance to complete the movement.\r\n3. Maintain a steady breathing pattern, exhaling as you pull up and inhaling as you lower yourself down.', '{"image_male_start":"images/Back/Assisted Close-grip Underhand Chin-up_female.jpg","image_female_start":"images/Back/Assisted Close-grip Underhand Chin-up_female.jpg","image_female_end":"images/Back/Assisted Close-grip Underhand Chin-up_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f62f4478-0d8c-4aca-aac8-5fe86a4cc30b'::uuid, 'Assisted parallel close grip pull up', 'Resistance', 'strength', 'weight_reps', 'intermediate', '41ba8c93-2898-4292-8990-ecff221d46bf'::uuid, E'1. Kneel on the platform pad of an assisted chin-up machine and grasp the handles with a parallel grip (palms facing each other) positioned at shoulder-width apart..\r\n2. Begin the movement by pulling your body upward until your chin is above the bar.\r\n3. Slowly lower your body back to the starting position with control, fully extending your arms.\r\n4. Repeat the movement for the desired number of repetitions, maintaining proper form throughout the exercise.', E'1. Keep your elbows close to your body and avoid flaring them out.\r\n2. Use an appropriate level of assistance on the machine to ensure you can perform the exercise correctly.\r\n3. Exhale as you pull your body upward and inhale as you lower it back down.', '{"video_url":"videos/Back/Assisted parallel close grip pull up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8c08a0c9-345d-4756-8773-d1e2d4239361'::uuid, 'Assisted Parallel Close-Grip Pull-up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Position yourself on the assisted pull-up machine, placing your knees on the pad and gripping the parallel bars with a close grip.\r\n2. Engage your core and pull your body up towards the bars until your chin is above the bars, using the assistance from the machine.\r\n3. Lower your body back down to the starting position, maintaining control throughout the movement.\r\n4. Continue the movement in a controlled, rhythmic manner.', E'1. Keep your elbows close to your body to maximize bicep and back engagement.\r\n2. Focus on using your arms and back muscles to perform the pull-up, with the machine providing just enough assistance to complete the movement.\r\n3. Maintain a steady breathing pattern, exhaling as you pull up and inhaling as you lower yourself down.', '{"image_male_start":"images/Back/Assisted Parallel Close-Grip Pull-up_female.jpg","image_female_start":"images/Back/Assisted Parallel Close-Grip Pull-up_female.jpg","image_female_end":"images/Back/Assisted Parallel Close-Grip Pull-up_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('df01457d-f98d-4ad5-89f8-0e3828a303c5'::uuid, 'Assisted pull up', 'Resistance', 'strength', 'weight_reps', 'intermediate', '41ba8c93-2898-4292-8990-ecff221d46bf'::uuid, E'1. Kneel on the platform pad of an assisted chin-up machine and grasp the handles with an overhand grip (palms facing forward) positioned just wider than shoulder-width apart.\r\n2. Begin the movement by pulling your body upward until your chin is above the bar.\r\n3. Slowly lower your body back to the starting position with control, fully extending your arms.\r\n4. Repeat the movement for the desired number of repetitions, maintaining proper form throughout the exercise.', E'1. Keep your elbows close to your body and avoid flaring them out.\r\n2. Use an appropriate level of assistance on the machine to ensure you can perform the exercise correctly.\r\n3. Exhale as you pull your body upward and inhale as you lower it back down.', '{"image_male_start":"images/Back/Assisted pull up.jpg","image_male_end":"images/Back/Assisted pull up1.jpg","video_url":"videos/Back/Assisted pull up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5d7eef38-366c-452c-a63f-572e895f19ba'::uuid, 'Assisted pull up close grip', 'Resistance', 'strength', 'weight_reps', 'intermediate', '41ba8c93-2898-4292-8990-ecff221d46bf'::uuid, E'1. Kneel on the platform pad of an assisted chin-up machine and grasp the handles with an overhand grip (palms facing away from you) positioned close together.\r\n2. Begin the movement by pulling your body upward until your chin is above the bar.\r\n3. Slowly lower your body back to the starting position with control, fully extending your arms.\r\n4. Repeat the movement for the desired number of repetitions, maintaining proper form throughout the exercise.', E'1. Keep your elbows close to your body and avoid flaring them out.\r\n2. Use an appropriate level of assistance on the machine to ensure you can perform the exercise correctly.\r\n3. Exhale as you pull your body upward and inhale as you lower it back down.', '{"image_male_start":"images/Back/assisted pull up close grip .jpg","video_url":"videos/Back/assisted pull up close grip .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('08bfa6f0-a9e6-43aa-a280-11cd511b0604'::uuid, 'Assisted pull up normal grip', 'Resistance', 'strength', 'weight_reps', 'intermediate', '41ba8c93-2898-4292-8990-ecff221d46bf'::uuid, E'1. Kneel on the platform pad of an assisted chin-up machine and grasp the handles with an overhand grip (palms facing forward) positioned just wider than shoulder-width apart.\r\n2. Begin the movement by pulling your body upward until your chin is above the bar.\r\n3. Slowly lower your body back to the starting position with control, fully extending your arms.\r\n4. Repeat the movement for the desired number of repetitions, maintaining proper form throughout the exercise.', E'1. Keep your elbows close to your body and avoid flaring them out.\r\n2. Use an appropriate level of assistance on the machine to ensure you can perform the exercise correctly.\r\n3. Exhale as you pull your body upward and inhale as you lower it back down.', '{"image_male_start":"images/Back/assisted pull up normal grip .jpg","video_url":"videos/Back/assisted pull up normal grip .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7d0e57fc-60f8-4e90-be34-3efddbdd2e0d'::uuid, 'Assisted pull up wide grip', 'Resistance', 'strength', 'weight_reps', 'intermediate', '41ba8c93-2898-4292-8990-ecff221d46bf'::uuid, E'1. Kneel on the platform pad of an assisted chin-up machine and grasp the handles with an overhand grip (palms facing away from you) positioned wider than shoulder-width apart.\r\n2. Begin the movement by pulling your body upward until your chin is above the bar.\r\n3. Slowly lower your body back to the starting position with control, fully extending your arms.\r\n4. Repeat the movement for the desired number of repetitions, maintaining proper form throughout the exercise.', E'1. Keep your elbows close to your body and avoid flaring them out.\r\n2. Use an appropriate level of assistance on the machine to ensure you can perform the exercise correctly.\r\n3. Exhale as you pull your body upward and inhale as you lower it back down.', '{"image_male_start":"images/Back/assisted pull up wide grip .jpg","video_url":"videos/Back/assisted pull up wide grip .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f5dc1ec0-5b38-4a45-a393-69fca954a3e2'::uuid, 'Assisted Pull-up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Position yourself on the assisted pull-up machine, placing your knees on the pad and gripping the pull-up bar with an overhand (pronated) grip, slightly wider than shoulder-width apart. \r\n2. Engage your core and pull your body up towards the bar until your chin is above the bar, using the assistance from the machine.\r\n3. Lower your body back down to the starting position, maintaining control throughout the movement.\r\n4. Continue the movement in a controlled, rhythmic manner.', E'1. Focus on keeping your body aligned and avoid swinging to ensure proper form.\r\n2. Use your legs for support, but focus on using your arms and back muscles to perform the pull-up.\r\n3. Breathe steadily, exhaling as you pull up and inhaling as you lower yourself down.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8a0034fd-9b83-447c-9d56-81dc1eb5774f'::uuid, 'Assisted sit ups', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back on the floor, with your knees bent and feet flat on the floor, close together. Have your partner hold your feet, holding them securely for stability.\r\n2. Cross your arms over your chest or place your hands behind your head.\r\n3. Engage your core and lift your upper body towards your knees.\r\n4. Slowly lower your upper body back to the starting position with control. Repeat the movement for the desired number of repetitions.', E'1. Exhale as you lift your upper body towards your knees and inhale as you lower it back down.\r\n2. Perform the exercise slowly and with control to maximize muscle engagement and effectiveness.\r\n3. Keep your elbows out to the sides and avoid pulling on your neck with your hands.', '{"image_male_start":"images/Abdominals/Assisted sit ups.jpeg","video_url":"videos/Abdominals/Assisted sit ups.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6bafe90a-4ae1-4965-b08c-b1e3da2f941d'::uuid, 'Assisted Sit-Up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back on a mat with your knees bent and feet secured with a partner holding them down.\r\n2. Place your hands lightly behind your head or cross them over your chest.\r\n3. Engage your core and lift your upper body towards your knees, performing a sit-up.\r\n4. Lower your upper body back down to the starting position, maintaining control throughout the movement.', E'1. Focus on using your abdominal muscles to lift your body, not your momentum.\r\n2. Avoid pulling on your neck with your hands to prevent strain; use your core muscles to lift your body.\r\n3. Keep a steady breathing pattern, exhaling as you lift and inhaling as you lower your body.', '{"image_male_start":"images/Abdominals/Assisted Sit-Up_female.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('90431305-ec8c-4073-b312-f1aed42de79b'::uuid, 'Assisted weighted push up', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Position yourself in a high plank position with your hands placed slightly wider than shoulder-width apart, your feet together, and your body forming a straight line from head to heels. Have your partner place a weight plate on your upper back.\r\n2. Lower your body towards the floor by bending your elbows, until your chest nearly touches the floor.\r\n3. Push through your palms to straighten your arms and return to the starting position, maintaining a controlled and steady movement. Repeat for the desired number of repetitions.', E'1. Maintain a straight line from head to heels to ensure proper form.\r\n2. Exhale as you push up and inhale as you lower your body.\r\n3. Ensure the weight plate is securely placed on your upper back for safety.', '{"image_male_start":"images/Chest/Assisted weighted push up.jpg","image_male_end":"images/Chest/Assisted weighted push up1.jpg","video_url":"videos/Chest/Assisted weighted push up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9bcf30e5-ee88-413f-a6d6-cc7c6af994d9'::uuid, 'Assisted Weighted Push-up', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Position yourself in a high plank position with your hands placed slightly wider than shoulder-width apart, your feet together, and your body forming a straight line from head to heels. Have your partner place a weight plate on your upper back.\r\n2. Lower your body towards the floor by bending your elbows, until your chest nearly touches the floor.\r\n3. Push through your palms to straighten your arms and return to the starting position, maintaining a controlled and steady movement. Repeat for the desired number of repetitions.', E'1. Maintain a straight line from head to heels to ensure proper form.\r\n2. Exhale as you push up and inhale as you lower your body.\r\n3. Ensure the weight plate is securely placed on your upper back for safety.', '{"image_male_start":"images/Chest/Assisted Weighted Push-up_female.jpg","image_female_start":"images/Chest/Assisted Weighted Push-up_female.jpg","image_female_end":"images/Chest/Assisted Weighted Push-up_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0f0a7e0f-16f8-4e22-a6ba-988f234be3fc'::uuid, 'Back and forward leg swings', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and use a nearby support (such as a squat cage, wall or a chair) for balance.\r\n2. Swing your right leg forward and backward in a controlled, rhythmic manner.\r\n3. After completing the desired number of swings with your right leg, switch to your left leg and repeat the movement.\r\n4. Focus on smooth and controlled swings, avoiding excessive momentum.', E'1. Focus on maintaining a steady rhythm to ensure controlled movements.\r\n2. Ensure your upper body remains upright and avoid leaning forward or backward.\r\n3. Keep your supporting leg slightly bent to enhance balance and reduce strain on your joints.', '{"image_male_start":"images/Legs/Back and forward leg swings.jpg","image_male_end":"images/Legs/Back and forward leg swings1.jpg","video_url":"videos/Legs/Back and forward leg swings.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('adcbd79e-5ce9-467c-9bc4-b536569353fc'::uuid, 'back and shoulder stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on a block with your back straight, feet shoulder-width apart and raise your right arm overhead.\r\n2. Bend your right elbow and reach down your back. Use your left hand to gently pull on your right elbow, enhancing the stretch.\r\n3. Hold the stretch for 15-30 seconds.\r\n4. Switch arms and repeat the stretch on the left side.', E'1. Keep your core engaged to maintain balance and proper posture throughout the stretch.\r\n2. Avoid pulling too hard on your elbow; the stretch should be gentle and not cause pain.\r\n3. Breathe deeply and steadily to help relax your muscles and enhance the stretch.', '{"image_male_start":"images/Stretching - Mobility/back and shoulder stretch.jpg","image_male_end":"images/Stretching - Mobility/back and shoulder stretch1.jpg","video_url":"videos/Stretching - Mobility/back and shoulder stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a6c9da6e-37f9-4a5b-b793-bb60b7e0c187'::uuid, 'Back and Shoulders Stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on a block with your back straight, feet shoulder-width apart and raise your right arm overhead.\r\n2. Bend your right elbow and reach down your back. Use your left hand to gently pull on your right elbow, enhancing the stretch.\r\n3. Hold the stretch for 15-30 seconds.\r\n4. Switch arms and repeat the stretch on the left side.', E'1. Keep your core engaged to maintain balance and proper posture throughout the stretch.\r\n2. Avoid pulling too hard on your elbow; the stretch should be gentle and not cause pain.\r\n3. Breathe deeply and steadily to help relax your muscles and enhance the stretch.', '{"image_male_start":"images/Stretching - Mobility/Back and Shoulders Stretch_female.jpg","image_female_start":"images/Stretching - Mobility/Back and Shoulders Stretch_female.jpg","image_female_end":"images/Stretching - Mobility/Back and Shoulders Stretch_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('82cd7398-4227-40b0-b9ca-cd5ffc04b6f0'::uuid, 'Back extension machine', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c7e89ac2-e6d9-4bbe-affa-981f3abb355c'::uuid, E'1. Fix your feet to the footrests and press your thighs against the padded platform.\r\n2. Place your arms across your chest and lean forward.\r\n3. Raise yourself by leaning backward and forming an upright position.\r\n4. Hold for a while, return to the initial position, and repeat.\r\n', E'1. Keep your movements slow and controlled to maintain proper form and maximize muscle engagement.\r\n2. Avoid hyperextending your back; stop when your body forms a straight line to prevent strain on your lower back.\r\n3. Engage your core muscles throughout the exercise to support your spine and maintain stability.', '{"video_url":"videos/Back/back extension machine .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5f500b8b-9cfc-4cb0-ae4a-895aa0c90d32'::uuid, 'Back Extension on Exercise Ball', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '4e9ce883-ea47-492d-be41-fc224e54b4c7'::uuid, E'1. Position your lower abdomen, face down on an exercise ball , with your feet planted firmly on the floor and your legs extended straight.\r\n2. Place your hands lightly behind your head or cross them over your chest.\r\n3. Bend at the waist to lower your upper body over the exercise ball, keeping your back straight.\r\n4. Engage your lower back and glutes to lift your upper body back to the starting position, extending your back fully.\r\n', E'1. Maintain a stable position by keeping your feet firmly planted on the floor.\r\n2. Avoid rounding your back; keep it straight to ensure proper form and prevent injury.\r\n3. Focus on engaging your lower back muscles to lift your torso, not your neck or arms.', '{"image_male_start":"images/Back/Back Extension on Exercise Ball_female.jpg","image_female_start":"images/Back/Back Extension on Exercise Ball_female.jpg","image_female_end":"images/Back/Back Extension on Exercise Ball_female1.jpg","video_url":"videos/Back/Back extension on exercise ball.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d1f78701-3cba-468f-92f5-6932ce8a6151'::uuid, 'Back Forward Leg Swings', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and use a nearby support (such as a squat cage, wall or a chair) for balance.\r\n2. Swing your right leg forward and backward in a controlled, rhythmic manner.\r\n3. After completing the desired number of swings with your right leg, switch to your left leg and repeat the movement.\r\n4. Focus on smooth and controlled swings, avoiding excessive momentum.', E'1. Focus on maintaining a steady rhythm to ensure controlled movements.\r\n2. Ensure your upper body remains upright and avoid leaning forward or backward.\r\n3. Keep your supporting leg slightly bent to enhance balance and reduce strain on your joints.', '{"image_male_start":"images/Legs/Back Forward Leg Swings_female.jpg","image_female_start":"images/Legs/Back Forward Leg Swings_female.jpg","image_female_end":"images/Legs/Back Forward Leg Swings_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0806e97b-a4ce-40a6-a9ea-4f0693419522'::uuid, 'Back lever', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start by hanging on a bar with your arms extended overhead, hands placed shoulder-width apart, and your palms facing forward.\r\n2. Pull yourself up until your head is facing the floor and your legs are overhead.\r\n3. Pass your legs under the bar and align your body in a straight line from head to toe and parallel to the floor.\r\n4. Hold this position for a suitable duration.', E'1. Focus on engaging your core and glutes to maintain a straight line from head to heels.\r\n2. Ensure your grip on the bar is firm and secure to provide stability and prevent slipping.\r\n3. Breathe steadily and evenly to help maintain the hold and reduce tension.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Back lever.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Back lever1.jpg","image_female_start":"images/Calisthenics-Cardio-Functional/Back lever_female.jpg","image_female_end":"images/Calisthenics-Cardio-Functional/Back lever_female1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Back lever.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e9c5550b-8f09-4e95-b3e2-d0b8b991c31f'::uuid, 'Back pec stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and position yourself in front of an incline bench.\r\n2. Lean forward and place your arms over the bench, with your palms facing down and your arms extended straight.\r\n3. Allow your chest to lower towards the bench, feeling the stretch in your pectoral muscles and back.\r\n4. Hold this position for 15-30 seconds, then release and return to the starting position.', E'1. Keep your shoulders relaxed and down to avoid straining your neck.\r\n2. Engage your core to maintain stability and support your lower back during the stretch.\r\n3. Breathe deeply and steadily to help relax your muscles and enhance the stretch.', '{"image_male_start":"images/Stretching - Mobility/back pec stretch.jpg","image_male_end":"images/Stretching - Mobility/back pec stretch1.jpg","video_url":"videos/Stretching - Mobility/back pec stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e26270f4-1314-489f-b6c5-08e8d8d440e2'::uuid, 'Back slaps wrap around stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart.\r\n2. Swing your arms out to the sides, keeping them lightly bent.\r\n3. Cross your arms in front of your body, wrapping them around yourself as if giving yourself a hug.\r\n4. Continue the swinging motion, alternating which arm crosses on top with each repetition.\r\n', E'1. Keep your movements fluid to promote relaxation and prevent stiffness.\r\n2. Focus on extending your arms fully to each side to maximize the stretch in your chest and shoulders.\r\n3. Maintain a steady pace to ensure you are not rushing through the movement and to allow a thorough stretch.', '{"image_male_start":"images/Stretching - Mobility/Back slaps wrap around stretch.jpg","image_male_end":"images/Stretching - Mobility/Back slaps wrap around stretch1.jpg","image_female_start":"images/Stretching - Mobility/Back Slaps Wrap Around Stretch_female.jpg","image_female_end":"images/Stretching - Mobility/Back Slaps Wrap Around Stretch_female1.jpg","video_url":"videos/Stretching - Mobility/Back slaps wrap around stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('246ee0af-aadf-4f4f-8c7a-dc8422654587'::uuid, 'Back Slaps Wrap Arround Stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart.\r\n2. Swing your arms out to the sides, keeping them lightly bent.\r\n3. Cross your arms in front of your body, wrapping them around yourself as if giving yourself a hug.\r\n4. Continue the swinging motion, alternating which arm crosses on top with each repetition.\r\n', E'1. Keep your movements fluid to promote relaxation and prevent stiffness.\r\n2. Focus on extending your arms fully to each side to maximize the stretch in your chest and shoulders.\r\n3. Maintain a steady pace to ensure you are not rushing through the movement and to allow a thorough stretch.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3b91a1dd-1283-4dc6-ba0c-bec1c85d50e2'::uuid, 'Back squeeze', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on a box with your feet flat on the floor and your arms extended straight out in front of you at shoulder height.\r\n2. Pull your elbows back, squeezing your shoulder blades together and opening your chest.\r\n3. Extend your arms back to the starting position in front of you.\r\n4. Continue the movement in a controlled, rhythmic manner, focusing on squeezing your shoulder blades together with each repetition.\r\n', E'1. Keep your core engaged to maintain stability and support your lower back throughout the exercise.\r\n2. Focus on squeezing your shoulder blades together to maximize the activation of your upper back muscles.\r\n3. Maintain an upright posture and avoid leaning forward or backward during the movement.', '{"image_male_start":"images/Back/Back squeeze.jpg","image_male_end":"images/Back/Back squeeze1.jpg","video_url":"videos/Back/Back squeeze.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d51e0e5d-9e09-455f-ab2b-5dce4987d857'::uuid, 'Back stretch dynamic', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and position yourself in front of an incline bench.\r\n2. Lean forward and place your hands on the incline bench, with your arms extended and your back straight parallel to the floor.\r\n3. Push your hips back while keeping your hands on the bench, feeling the stretch in your back and hamstrings.\r\n4. Repeat your hip motion, creating a dynamic stretch.', E'1. Keep your back straight throughout the movement to ensure a proper stretch and prevent strain.\r\n2. Focus on pushing your hips downwards rather than bending at the waist to enhance the stretch in your back.\r\n3. Use controlled movements to avoid jerking or sudden motions that could lead to injury.', '{"image_male_start":"images/Stretching - Mobility/back stretch dynamic  .jpg","video_url":"videos/Stretching - Mobility/back stretch dynamic  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('907c4405-b1a7-4bdf-a8c9-35abe21ef29e'::uuid, 'Back stretch standing with bench', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand tall near an incline bench with your back straight and feet shoulder-width apart.\r\n2. Extend your arms and reach the bench by leaning forward.\r\n3. Hold the bench and extend your back while lowering your chest towards the floor.\r\n4. Hold this position for 15-30 seconds, feeling the stretch in your back.', E'1. Engage your core muscles to maintain stability and support your lower back during the stretch.\r\n2. Keep your shoulders relaxed and down away from your ears to prevent tension.\r\n3. Make sure your feet are firmly planted on the floor to provide a stable base and enhance the stretch.', '{"image_male_start":"images/Stretching - Mobility/back stretch standing with bench.jpg","image_male_end":"images/Stretching - Mobility/back stretch standing with bench1.jpg","video_url":"videos/Stretching - Mobility/back stretch standing with bench.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('bd99afd0-9116-4945-a24f-39c8d158e3b5'::uuid, 'Backhand Raise', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, knees bent and lean forward at the hips until your torso is halfway parallel to the floor. Keep your back straight.\r\n2. Extend your arms straight back parallel to your torso with your palms facing backwards.\r\n3. Raise your arms upwards, keeping them straight, until they are over your back.\r\n4. Lower your arms back to the starting position in a controlled manner.', E'1. Engage your core to maintain stability and support your lower back throughout the exercise.\r\n2. Keep your movements slow and controlled to maximize muscle activation and prevent injury.\r\n3. Focus on squeezing your shoulder blades together at the top of the movement to enhance upper back activation.', '{"image_male_start":"images/Shoulders/Backhand raise.jpg","image_male_end":"images/Shoulders/Backhand raise1.jpg","image_female_start":"images/Shoulders/Backhand Raise_female.jpg","image_female_end":"images/Shoulders/Backhand Raise_female1.jpg","video_url":"videos/Shoulders/Backhand raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('30815e34-30be-4372-aaaa-a6c022f75797'::uuid, 'Backward abdominal stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Get down on your knees with your back straight, thighs extended, and legs resting on the floor.\r\n2. Lean backward and hold your feet by extending your arms to stretch your abdominal muscles.\r\n3. Maintain this stretch for 30-60 seconds.\r\n', E'1. Keep your hips stable to ensure a deep and effective stretch.\r\n2. Avoid overextending your back; only lean as far back as is comfortable and safe for your flexibility.\r\n3. Breathe deeply and steadily to help relax your muscles and enhance the stretch.', '{"image_male_start":"images/Stretching - Mobility/Backward abdominal stretch.jpg","image_male_end":"images/Stretching - Mobility/Backward abdominal stretch1.jpg","video_url":"videos/Stretching - Mobility/Backward abdominal stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('13d760bf-0cae-415b-9354-7256de31d1fe'::uuid, 'Backward Forward Turn to Side Neck Stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your head in a neutral position.\r\n2. Tilt your head backward, stretching the front of your neck.\r\n3. Return to the neutral position, then tilt your head forward to stretch the back of your neck.\r\n4. Turn your head to one side, holding briefly, and then return to the neutral position. Repeat on the other side.\r\n', E'1. Perform the movements slowly and gently to avoid straining your neck muscles.\r\n2. Keep your shoulders relaxed and down to prevent tension in your upper back and shoulders.\r\n3. Breathe deeply and steadily to help relax your muscles and enhance the stretch.', '{"image_male_start":"images/Stretching - Mobility/Backward Forward Turn to Side Neck Stretch.jpg","image_male_end":"images/Stretching - Mobility/Backward Forward Turn to Side Neck Stretch1.jpg","image_female_start":"images/Stretching - Mobility/Backward Forward Turn to Side Neck Stretch_female.jpg","image_female_end":"images/Stretching - Mobility/Backward Forward Turn to Side Neck Stretch_female1.jpg","video_url":"videos/Stretching - Mobility/Backward Forward Turn to Side Neck Stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('cda324a7-8a39-4c47-83e7-69c97424aa3b'::uuid, 'Balance Board (VERSION 2)', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '9ce42536-8425-4171-a8e2-7f720ad5e136'::uuid, E'1. Stand on the balance board with your feet shoulder-width apart.\r\n2. Shift your weight side to side by straightening one leg while lightly bending the other.\r\n3. Shift your weight to the opposite side by bending the extended leg lightly and straightening the other leg.\r\n4. Continue the movement in a controlled, rhythmic manner to improve balance.', E'1. Focus on a point in front of you to help maintain your balance.\r\n2. Start with slow movements and gradually increase the speed as you become more comfortable.\r\n3. Keep your movements controlled to maximize muscle activation and prevent injury.', '{"image_male_start":"images/Legs/Balance Board (VERSION 2)_female.jpg","image_female_start":"images/Legs/Balance Board (VERSION 2)_female.jpg","image_female_end":"images/Legs/Balance Board (VERSION 2)_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c7d3d68c-1e1a-41fa-a943-dbd6b1ffaede'::uuid, 'Balance board lateral squat', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '9ce42536-8425-4171-a8e2-7f720ad5e136'::uuid, E'1. Stand on the balance board with your feet shoulder-width apart.\r\n2. Shift your weight to one side and bend at the knees and hips to perform a squat, keeping your core engaged to maintain balance.\r\n3. Return to the starting position and shift your weight to the other side, performing a squat on the opposite side.\r\n4. Continue alternating sides in a controlled, rhythmic manner.', E'1. Keep your knees aligned with your toes to prevent strain on your joints.\r\n2. Engage your core muscles to maintain stability and support your lower back.\r\n3. Focus on a point in front of you to help maintain balance and control.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Balance board lateral squat.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Balance board lateral squat1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Balance board lateral squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ec5bef4a-85a6-4f9f-91bb-68bc257eeef0'::uuid, 'Ball Sit-up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '4e9ce883-ea47-492d-be41-fc224e54b4c7'::uuid, E'1. Sit on an exercise ball with your feet flat on the floor and knees bent at a 90-degree angle.\r\n2. Lean back, rolling the ball under your lower back, and place your hands behind your head or cross them over your chest.\r\n3. Engage your core and lift your upper body upwards until vertical to the floor.\r\n4. Lower your upper body back down to the starting position, repeat.', E'1. Keep your core engaged throughout the exercise to maintain stability and proper form.\r\n2. Avoid pulling on your neck with your hands to prevent strain; use your core muscles to lift your body.\r\n3. Perform the movement slowly and with control to maximize muscle activation and prevent injury.', '{"image_male_start":"images/Abdominals/Ball Sit-up_female.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('089c2b12-ed9e-453b-9168-24371872a416'::uuid, 'Balloon Drill', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '4b3ab084-5450-45b1-9dbf-057e78d84390'::uuid, E'1. Stand with your feet shoulder-width apart, holding a balloon in front of you.\r\n2. Toss the balloon into the air and tap it lightly to keep it afloat.\r\n3. As the balloon is in the air, perform a squat by bending your knees and lowering your hips until your thighs are parallel to the floor.\r\n4. Stand back up and tap the balloon again as it comes down, repeating the process.', E'1. Start with a shallow squat if you are new to the exercise and gradually increase the depth as you become more comfortable.\r\n2. Focus on keeping your back straight and your knees aligned with your toes during the squat.\r\n3. Perform the movement smoothly and with control to maximize muscle activation and coordination.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Balloon Drill_female.jpg","image_female_start":"images/Calisthenics-Cardio-Functional/Balloon Drill_female.jpg","image_female_end":"images/Calisthenics-Cardio-Functional/Balloon Drill_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4f28d713-f999-4c7c-81a1-d10bdea56480'::uuid, 'Band Assisted Chin Up (From Knee)', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '6ba0eb0a-a2a7-44a6-9e09-9992b5e44a67'::uuid, E'1. Loop a resistance band around a pull-up bar and secure the other end under one knee while keeping the other leg straight.\r\n2. Grip the pull-up bar with an underhand grip (palms facing back), hands shoulder-width apart.\r\n3. Using the assistance of the band, pull yourself up until your chin is above the bar.\r\n4. Lower yourself back down to the starting position in a controlled manner.', E'1. Ensure the resistance band is securely in place under your knee to provide consistent assistance and avoid injury.\r\n2. Avoid using momentum; focus on using your arm and back muscles to perform the pull-up.\r\n3. Breathe steadily, exhaling as you pull up and inhaling as you lower yourself down.', '{"image_male_start":"images/Back/Band Assisted Chin Up (From Knee)_female.jpg","image_female_start":"images/Back/Band Assisted Chin Up (From Knee)_female.jpg","image_female_end":"images/Back/Band Assisted Chin Up (From Knee)_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c3844334-0477-411c-8e36-122a4d68cdc0'::uuid, 'Band Behind Neck Shoulder Press', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and place the resistance band under your feet. Hold one handle of the band in each hand and bring them up to shoulder height with the band extending behind your body.\r\n2. Press the handles upward until your arms are fully extended overhead.\r\n3. Slowly lower the handles back to shoulder height with control, maintaining tension in the band.\r\n4.  Repeat for the desired number of repetitions.', E'1. Ensure the resistance band is securely placed under your feet to avoid slipping.\r\n2. Exhale as you press the band overhead and inhale as you lower it back down.\r\n3. Perform the exercise slowly and with control to maximize muscle engagement.', '{"image_male_start":"images/Shoulders/Band Behind Neck Shoulder Press_female.jpg","image_female_start":"images/Shoulders/Band Behind Neck Shoulder Press_female.jpg","image_female_end":"images/Shoulders/Band Behind Neck Shoulder Press_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('69407b56-61bb-4699-b9e7-8368688aab14'::uuid, 'Band Bench Press', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on a bench with your feet flat on the floor and place a resistance band under the bench, holding one handle in each hand. Bring your hands to shoulder height with your palms facing forward.\r\n2. Press the handles upward until your arms are fully extended, keeping the band aligned with your arms.\r\n3. Slowly lower the handles back to shoulder height with control, maintaining tension in the band.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Ensure the resistance band is securely placed under the bench to avoid slipping.\r\n2. Exhale as you press the band upward and inhale as you lower it back down.\r\n3. Perform the exercise slowly and with control to maximize muscle engagement.', '{"image_male_start":"images/Chest/Band Bench Press_female.jpg","image_female_start":"images/Chest/Band Bench Press_female.jpg","image_female_end":"images/Chest/Band Bench Press_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0f1b924e-938c-4e2f-bac5-d764e952ca37'::uuid, 'Band Bent over One Arm Kickback', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and place one end of the resistance band under your feet. Hold the other end of the band in your right hand and bend your torso forward at the hips, keeping your back straight and your knees bent.\r\n2. Position your right upper arm almost parallel to the floor with your elbow bent at a 90-degree angle, keeping your upper arm close to your body.\r\n3. Extend your right arm straight back, squeezing your triceps at the top of the movement.\r\n4. Slowly return your right arm to the starting position with control. Repeat for the desired number of repetitions, then switch to the left arm.', E'1. Ensure the resistance band is securely placed under your feet to avoid slipping.\r\n2. Exhale as you extend your arm back and inhale as you return to the starting position.\r\n3. Perform the exercise slowly and with control to maximize muscle engagement.', '{"image_male_start":"images/Triceps/Band Bent over One Arm Kickback_female.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d02c6058-e446-46d3-a7d2-9cf44adbc738'::uuid, 'Band Bent-over Hip Extension', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Attach one end of the resistance band low on a sturdy piece of equipment and secure the other end around your right ankle. Stand with your feet shoulder-width apart and lean slightly forward, holding the equipment for support with both hands.\r\n2. Lift your right leg straight back until parallel to the floor, squeezing your glutes at the top of the movement.\r\n3. Slowly return your leg to the starting position with control. Repeat for the desired number of repetitions, then switch to the left leg.', E'1. Ensure the resistance band is securely attached to the equipment and your ankle to avoid slipping.\r\n2. Exhale as you lift your leg back and inhale as you return to the starting position.\r\n3. Maintain a slight bend in your supporting knee to protect your knee joint and lower back.', '{"image_male_start":"images/Legs/Band Bent-over Hip Extension_female.jpg","image_female_start":"images/Legs/Band Bent-over Hip Extension_female.jpg","image_female_end":"images/Legs/Band Bent-over Hip Extension_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4d79765a-ee4f-42a0-bac3-705f86528137'::uuid, 'Band bent-over row', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart and place the resistance band under both feet, ensuring it is secure. Hold one handle of the band in each hand with your palms facing each other, bending your torso forward at the hips while keeping your back straight and your knees slightly bent.\r\n2. Let your arms hang straight down toward the floor, fully extended, with your elbows slightly bent.\r\n3. Pull the handles towards your torso by bending your elbows and squeezing your shoulder blades together.\r\n4. Slowly lower the handles back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Ensure the resistance band is securely placed under your feet to avoid slipping.\r\n2. Exhale as you pull the band towards your torso and inhale as you lower it back down.\r\n3. Perform the exercise slowly and with control to maximize muscle engagement.', '{"image_male_start":"images/Back/Band bent-over row.jpg","image_male_end":"images/Back/Band bent-over row1.jpg","video_url":"videos/Back/Band bent-over row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1a997706-656b-4d1c-87a3-d195ca499b34'::uuid, 'Band bicycle crunch', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Lie on your back on a mat and secure a resistance band around both feet. Place your hands behind your head with your elbows pointing outward, and keep your legs extended straight.\r\n2. Engage your core and lift your upper body off the floor. Bend your right knee towards your chest while simultaneously twisting your torso to bring your left elbow towards your right knee.\r\n3. Switch sides by bending your left knee towards your chest while bringing your right elbow towards your left knee, performing a pedaling motion.\r\n4. Continue alternating sides in a controlled manner for the desired number of repetitions.', E'1. Avoid pulling on your neck with your hands; use your abs to lift and twist your torso.\r\n2. Ensure the resistance band is securely placed around your feet and on the equipment to avoid slipping.\r\n3. Maintain a steady rhythm and focus on controlled movements rather than speed.', '{"image_male_start":"images/Abdominals/Band Bicycle Crunch_female.jpeg","video_url":"videos/Abdominals/Band Bicycle Crunch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('aa2aa258-e480-497f-b141-40ff71dfc55f'::uuid, 'Band Chest Fly', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Secure the middle of the resistance band to a sturdy anchor point at head height. Stand facing away from the anchor point with your feet shoulder-width apart, holding one handle of the band in each hand. \r\n2. Extend your arms out to the sides with a slight bend in your elbows, keeping your palms facing forward. Step forward to create tension in the band, positioning your hands slightly below shoulder height.\r\n3. Move your arms in a wide arc motion, bringing your hands together in front of your chest. Squeeze your chest muscles as your hands meet, keeping a slight bend in your elbows throughout the movement.\r\n4. Slowly return your arms to the starting position with control, maintaining tension in the band. Repeat for the desired number of repetitions.', E'1. Ensure the resistance band is securely anchored to avoid slipping.\r\n2. Exhale as you bring your hands together and inhale as you return to the starting position.\r\n3. Focus on squeezing your chest muscles as you bring your hands together.', '{"image_male_start":"images/Chest/Band Chest Fly_female.jpg","image_female_start":"images/Chest/Band Chest Fly_female.jpg","image_female_end":"images/Chest/Band Chest Fly_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('64483d50-5167-47c3-bc53-06b5ac82a934'::uuid, 'Band Close Grip Row', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Secure the middle of the resistance band to a sturdy anchor point at chest height. Stand with your feet shoulder-width apart, holding one handle of the band in each hand with your palms facing each other and kept close together. Extend your arms in front of your chest, ensuring the band is taut.\r\n2. Pull the handles towards your chest until your hands are close to your chest, bending your elbows and keeping them pointing outward.\r\n3. Slowly extend your arms back to the starting position with control, maintaining tension in the band. Repeat for the desired number of repetitions.', E'1. Ensure the resistance band is securely anchored to avoid slipping.\r\n2. Exhale as you pull the handles towards your chest and inhale as you return to the starting position.\r\n3. Use a resistance band with appropriate tension to ensure you can perform the exercise with good form.', '{"image_male_start":"images/Shoulders/Band Close Grip Row_female.jpg","image_female_start":"images/Shoulders/Band Close Grip Row_female.jpg","image_female_end":"images/Shoulders/Band Close Grip Row_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('03cda948-eecf-44f6-98cd-dd0ad95fdefd'::uuid, 'Band close-grip biceps curl', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand tall with your back straight, feet shoulder-width apart, and a Resistance band under your feet.\r\n2. Hold the ends of the bands in your hands while keeping your arms straight and palms facing forward.\r\n3. Raise the band by folding your arms to a 90° angle while taking your hands close to each other.\r\n4. Slowly lower the handles back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Ensure the resistance band is securely placed under your feet to avoid slipping.\r\n2. Exhale as you curl the band towards your shoulders and inhale as you lower it back down.\r\n3. Keep your elbows close to your body and avoid swinging them forward or backward.', '{"image_male_start":"images/Biceps/Band Close-Grip Biceps Curl_female.jpeg","video_url":"videos/Biceps/Band Close-Grip Biceps Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ad31f525-470b-4512-8e88-6db5a9e14658'::uuid, 'Band Concentration Curl', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Sit on a bench with your feet flat on the floor, placing the middle of the resistance band under your right foot. Hold the handle of the band in your right hand, and rest your elbow against the inside of your thigh, fully extending your arm towards the floor.\r\n2. Curl the handle upward towards your shoulder, squeezing your biceps at the top of the movement until your hand is near shoulder level.\r\n3. Slowly lower the handle back to the starting position with control, fully extending your arm. Repeat for the desired number of repetitions, then switch to the left arm.', E'1. Ensure the resistance band is securely placed under your foot to avoid slipping.\r\n2. Exhale as you curl the band upwards and inhale as you lower it back down.\r\n3. Keep your upper arm stationary and avoid swinging it.', '{"image_male_start":"images/Biceps/Band Concentration Curl_female.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('91bd6529-0ce8-4798-91e6-5118e2c7877d'::uuid, 'Band Cross Abduction', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet hip-width apart and place the resistance band under both feet, crossing the band in front of you. Hold the handles of the band in opposite hands with arms hanging in front of your hips.\r\n2. Keeping your right leg straight, lift it sideways away from your body until your leg is fully extended to the side.\r\n3. Slowly lower your leg back to the starting position with control, keeping tension in the band.\r\n4. Repeat the movement for the desired number of repetitions, then switch to the left leg.', E'1. Ensure the resistance band is securely placed under your feet and properly crossed to avoid slipping.\r\n2. Keep your upper body stationary and avoid leaning to the side.\r\n3. Perform the exercise slowly and with control to maximize muscle engagement.', '{"image_male_start":"images/Legs/Band Cross Abduction.jpg","image_male_end":"images/Legs/Band Cross Abduction1.jpg","image_female_start":"images/Legs/Band Cross Abduction_female.jpg","image_female_end":"images/Legs/Band Cross Abduction_female1.jpg","video_url":"videos/Legs/Band Cross Abduction.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0766116d-fad5-4a23-bffb-b0aac06e166e'::uuid, 'Band Cross Body One Arm Chest Press', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Secure one end of the resistance band to a sturdy anchor point at chest height. Stand with your left side facing the anchor point and hold the handle of the band in your left hand, extending your arm out to the side with your elbow bent at 90 degrees.\r\n2. Press the handle across your body to the right side, keeping your arm bent and in line with your chest until your hand reaches the opposite side of your body.\r\n3. Slowly return your right arm back to the starting position, maintaining control and tension in the band.\r\n4. Repeat the movement for the desired number of repetitions, then switch to the left arm.', E'1. Ensure the resistance band is securely anchored to avoid slipping.\r\n2. Exhale as you press the band across your body and inhale as you return to the starting position.\r\n3. Focus on using your chest muscles to press the band.', '{"image_male_start":"images/Chest/Band Cross Body One Arm Chest Press_female.jpg","image_female_start":"images/Chest/Band Cross Body One Arm Chest Press_female.jpg","image_female_end":"images/Chest/Band Cross Body One Arm Chest Press_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('99496615-3c7b-4a2e-99c3-ac7b320351a2'::uuid, 'Band Cross Chest Biceps Curl', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Secure the middle of the resistance band to a sturdy anchor point at chest height. Stand facing the anchor point with your feet shoulder-width apart, holding the handles of the band with both hands extended straight forward, palms facing each other.\r\n2. Lean slightly back and bend both elbows inward to curl the handles towards your chest, keeping your upper arms stationary.\r\n3. Slowly extend your arms back to the starting position, maintaining control and tension in the band.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Ensure the resistance band is securely anchored to avoid slipping.\r\n2. Exhale as you curl the band towards your chest and inhale as you lower it back down.\r\n3. Keep your upper arms stationary to isolate the biceps.', '{"image_male_start":"images/Biceps/Band Cross Chest Biceps Curl_female.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e8abb585-904d-47bf-ac7f-a9d772858f97'::uuid, 'Band Deadlift', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet hip-width apart and place the resistance band under both feet, holding one handle of the band in each hand with your arms extended straight down, palms facing your hips.\r\n2. Hinge at your hips, keeping your back straight and your knees bent, lowering your torso until it is almost parallel to the floor.\r\n3. Press through your heels and extend your hips and knees to stand back up straight, bringing the handles up along your legs until you are fully upright.\r\n4. Repeat the exercise for the desired number of repetitions.', E'1. Ensure the resistance band is securely placed under your feet to avoid slipping.\r\n2. Exhale as you stand up and inhale as you lower back down.\r\n3. Use a resistance band with appropriate tension to ensure you can perform the exercise with good form.', '{"image_male_start":"images/Back/Band Deadlift.jpg","image_male_end":"images/Back/Band Deadlift1.jpg","image_female_start":"images/Legs/Band Deadlift_female.jpg","image_female_end":"images/Legs/Band Deadlift_female1.jpg","video_url":"videos/Back/Band Deadlift.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ca6e9fa6-686e-4c99-8610-0f8b224df40d'::uuid, 'Band Decline Sit up', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Secure the middle of the resistance band to a sturdy anchor point behind the headrest of a decline bench. Lie on the bench with your feet secured under the foot pads and hold one handle of the band in each hand, positioning the band over your shoulders.\r\n2. Contract your abs and lift your upper body up towards your knees, bringing your chest towards your thighs until you are in a seated position.\r\n3. Slowly lower your upper body down the bench, maintaining control and tension in the band until your back rests on the bench.\r\n4. Repeat for the desired number of repetitions.', E'1. Ensure the resistance band is securely anchored behind the headrest to avoid slipping.\r\n2. Exhale as you lift your upper body and inhale as you lower it back down.\r\n3. Avoid pulling on the band with your arms; focus on using your abs to lift your body.', '{"image_male_start":"images/Abdominals/Band Decline Sit up_female.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('df7df25b-3a6a-4241-9aac-1624426cbb30'::uuid, 'Band Face Pull', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Secure the middle of the resistance band to a sturdy anchor point at head height. Stand facing the anchor point with your feet shoulder-width apart, holding one handle of the band in each hand with your arms extended straight in front of you, palms facing down.\r\n2. Pull the handles towards your face, bending your elbows and flaring them out to the sides until your hands are at your face sides.\r\n3. Squeeze your shoulder blades together at the end of the movement, keeping your upper arms parallel to the floor.\r\n4. Slowly extend your arms back to the starting position with control, maintaining tension in the band. Repeat for the desired number of repetitions.', E'1. Ensure the resistance band is securely anchored to avoid slipping.\r\n2. Exhale as you pull the band towards your face and inhale as you return to the starting position.\r\n3. Maintain a slight bend in your knees for better balance and support.', '{"image_male_start":"images/Shoulders/Band Face Pull_female.jpg","image_female_start":"images/Shoulders/Band Face Pull_female.jpg","image_female_end":"images/Shoulders/Band Face Pull_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1198b49c-c994-459e-8546-21e05e968fbf'::uuid, 'Band Fixed Back Underhand Pulldown', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Secure the middle of the resistance band to a sturdy anchor point over head height. Sit on a box or a bench under the anchor point, holding one handle of the band in each hand with an underhand grip (palms facing back), arms extended overhead.\r\n2. Pull the handles down towards your shoulders, bending your elbows and keeping them close to your body until your hands are near your shoulders.\r\n3. Squeeze your shoulder blades together at the end of the movement, keeping your back straight and your chest up.\r\n4. Slowly extend your arms back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Ensure the resistance band is securely anchored to avoid slipping.\r\n2. Exhale as you pull the band down and inhale as you return to the starting position.\r\n3. Use a resistance band with appropriate tension to ensure you can perform the exercise with good form.', '{"image_male_start":"images/Back/Band Fixed Back Underhand Pulldown_female.jpg","image_female_start":"images/Back/Band Fixed Back Underhand Pulldown_female.jpg","image_female_end":"images/Back/Band Fixed Back Underhand Pulldown_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d43f7c37-007d-4597-b75f-ba4198b3f2b7'::uuid, 'Band front Face Pull', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Secure the middle of the resistance band to a sturdy anchor point at head height. Stand facing the anchor point with your feet shoulder-width apart, holding one handle of the band in each hand with your arms extended straight in front of you, palms facing down.\r\n2. Pull the handles towards your face, bending your elbows and flaring them out to the sides until your hands are in front of your face.\r\n3. Squeeze your shoulder blades together at the end of the movement, keeping your upper arms parallel to the floor.\r\n4. Slowly extend your arms back to the starting position with control, maintaining tension in the band. Repeat for the desired number of repetitions.', E'1. Ensure the resistance band is securely anchored to avoid slipping.\r\n2. Exhale as you pull the band towards your face and inhale as you return to the starting position.\r\n3. Maintain a slight bend in your knees for better balance and support.', '{"image_male_start":"images/Shoulders/Band front Face Pull_female.jpg","image_female_start":"images/Shoulders/Band front Face Pull_female.jpg","image_female_end":"images/Shoulders/Band front Face Pull_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('74f2e062-3c32-44c1-bb33-e35d603004ae'::uuid, 'Band front raise', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and place the resistance band under both feet, holding one handle of the band in each hand with your arms extended straight down, palms facing your thighs.\r\n2. Raise both handles straight in front of you to shoulder height, keeping your arms straight and palms facing down.\r\n3. Slowly lower the handles back to the starting position with control, maintaining tension in the band.\r\n4. Repeat for the desired number of repetitions.', E'1. Ensure the resistance band is securely placed under your feet to avoid slipping.\r\n2. Exhale as you raise the band handles and inhale as you lower them back down.\r\n3. Avoid swinging your arms; use controlled movements.', '{"image_male_start":"images/Shoulders/Band front raise_female.jpg","image_female_start":"images/Shoulders/Band front raise_female.jpg","image_female_end":"images/Shoulders/Band front raise_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1c3c53d7-c29c-4d42-820a-4d2c0748b6f9'::uuid, 'Band high fly', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Secure the middle of the resistance band to a sturdy anchor point above head height. Stand facing away from the anchor point with your feet shoulder-width apart, holding one handle of the band in each hand. \r\n2. Extend your arms out to the sides at shoulder height with a slight bend in your elbows, palms facing forward.\r\n3. Move your arms in a wide arc motion, bringing your hands together in front of your chest. Squeeze your chest muscles as your hands meet, keeping a slight bend in your elbows throughout the movement.\r\n4. Slowly return your arms to the starting position in the same wide arc motion. Repeat for the desired number of repetitions.', E'1. Ensure the resistance band is securely anchored to avoid slipping.\r\n2. Exhale as you bring your hands together and inhale as you return to the starting position.\r\n3. Focus on squeezing your chest muscles as you bring your hands together.', '{"image_male_start":"images/Chest/Band high fly_female.jpg","image_female_start":"images/Chest/Band high fly_female.jpg","image_female_end":"images/Chest/Band high fly_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1973286e-10a7-4f07-814a-abc170aceec7'::uuid, 'Band Incline Alternate Hammer Curl', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on an incline bench with your feet flat on the floor. Place the resistance band under the bench and hold one handle of the band in each hand using a hammer grip (palms facing each other), letting your arms hang straight down.\r\n2. Curl the right handle towards your shoulder, keeping your elbow stationary and close to your body until your hand is near your shoulder.\r\n3. Slowly lower your right hand back to the starting position with control and repeat the movement with your left hand.\r\n4. Continue alternating between right and left arms for the desired number of repetitions.', E'1. Ensure the resistance band is securely placed under the bench to avoid slipping.\r\n2. Exhale as you curl the band handle towards your shoulder and inhale as you lower it back down.\r\n3. Focus on squeezing your biceps at the top of the movement.', '{"image_male_start":"images/Biceps/Band Incline Alternate Hammer Curl_female.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2afa85cc-25dc-47db-a144-fe6a183da058'::uuid, 'Band Incline Bench Press', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Adjust an incline bench to a 45-degree angle. Lie back on the bench with your feet on the floor, holding the band handles at shoulder height with your palms facing forward.\r\n2. Press the handles upward until your arms are fully extended, keeping the band aligned over your chest.\r\n3. Slowly lower the handles back to shoulder height with control, maintaining tension in the band.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Ensure the resistance band is securely anchored under the bench to avoid slipping.\r\n2. Exhale as you press the band handles upward and inhale as you lower them back down.\r\n3. Perform the exercise slowly and with control to maximize muscle engagement.', '{"image_male_start":"images/Chest/Band Incline Bench Press_female.jpg","image_female_start":"images/Chest/Band Incline Bench Press_female.jpg","image_female_end":"images/Chest/Band Incline Bench Press_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('cca15c7c-72be-4663-ab85-cc478dba92b9'::uuid, 'Band Incline Biceps Curl', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Adjust an incline bench to a 45-degree angle. Sit back on the bench with your feet on the floor. Place the resistance band under the bench and hold one handle of the band in each hand with your arms hanging straight down and palms facing forward.\r\n2. Curl the handles upward towards your shoulders, keeping your elbows stationary and close to your body until your hands are near shoulder level.\r\n3. Slowly lower the handles back to the starting position with control, fully extending your arms.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Ensure the resistance band is securely anchored under the bench to avoid slipping.\r\n2. Keep your elbows close to your body to isolate the biceps.\r\n3. Focus on squeezing your biceps at the top of the movement.', '{"image_male_start":"images/Biceps/Band Incline Biceps Curl_female.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0ff77929-364a-4628-b351-e1e0a93dc9d3'::uuid, 'Band Incline Fly', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Adjust an incline bench to a 45-degree angle. Sit back on the bench with your feet flat on the floor. Place the resistance band under the bench and hold one handle of the band in each hand, extending your arms out to the sides with a slight bend in your elbows, palms facing up.\r\n2. Engage your chest and bring the handles up in an arc motion towards each other until your hands meet above your chest.\r\n3. Slowly return your arms to the starting position with control, maintaining the slight bend in your elbows.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Ensure the resistance band is securely anchored under the bench to avoid slipping.\r\n2. Exhale as you bring the handles together and inhale as you return to the starting position.\r\n3. Use a resistance band with appropriate tension to ensure you can perform the exercise with good form.', '{"image_male_start":"images/Chest/Band Incline Fly_female.jpg","image_female_start":"images/Chest/Band Incline Fly_female.jpg","image_female_end":"images/Chest/Band Incline Fly_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1f873bac-f606-43e1-9ce5-c4af5473cb60'::uuid, 'Band Incline Hammer Curl', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on an incline bench set at a 45-degree angle. Place the resistance band under the bench and hold one handle of the band in each hand using a hammer grip (palms facing each other), letting your arms hang straight down.\r\n2. Curl the handles upward towards your shoulders, keeping your elbows stationary and close to your body until your hands are near shoulder level.\r\n3. Slowly lower the handles back to the starting position with control, fully extending your arms.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Ensure the resistance band is securely anchored under the bench to avoid slipping.\r\n2. Keep your elbows close to your body to isolate the biceps.\r\n3. Focus on squeezing your biceps at the top of the movement.', '{"image_male_start":"images/Biceps/Band Incline Hammer Curl_female.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e4c4426b-67e6-4c75-a34e-8f1f6241b2b7'::uuid, 'Band Incline Hammer Press', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on an incline bench set at a 45-degree angle. Place the resistance band under the bench and hold one handle of the band in each hand with your palms facing each other, positioning your hands at chest height.\r\n2. Press the handles upward until your arms are fully extended, keeping the band aligned over your chest.\r\n3. Slowly lower the handles back to shoulder height with control, maintaining tension in the band.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Ensure the resistance band is securely anchored under the bench to avoid slipping.\r\n2. Exhale as you press the band handles upward and inhale as you lower them back down.\r\n3. Avoid letting your elbows flare out excessively to protect your shoulder joints.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e6f4bd14-5d73-461a-85d9-1c1b4cf2b1cf'::uuid, 'Band Incline Palms Back Press', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on an incline bench set at a 45-degree angle with feet on the floor, holding one handle of the resistance band in each hand with your palms facing your chest, positioned at shoulder height.\r\n2. Press the handles upward until your arms are fully extended, squeezing your chest muscles at the top of the movement.\r\n3. Slowly lower the handles back to shoulder height with control.\r\n4. Repeat for the desired repetitions.', E'1. Ensure the resistance band is securely anchored under the bench to avoid slipping.\r\n2. Use a resistance band with appropriate tension to ensure you can perform the exercise with good form.\r\n3. Maintain a slight bend in your elbows at the top of the movement.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('456aa272-648e-4864-98e3-252c2a20bc07'::uuid, 'Band Incline Row', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie chest-first on an incline bench set at a 45-degree angle, holding one handle of the resistance band in each hand with your arms fully extended down, palms facing back. Your feet should be firm on the floor, and the resistance band should be secured under the bench.\r\n2. Pull the handles towards your chest, bending your elbows and keeping them away from your body until your hands are near by your chest sides.\r\n3. Squeeze your shoulder blades together at the top of the movement, then slowly lower the handles back to the starting position with control.\r\n4. Repeat the rowing motion for the desired number of repetitions.', E'1. Ensure the resistance band is secure to prevent any sudden slips.\r\n2. Focus on squeezing your back muscles at the peak of the movement.\r\n3. Perform each rep with controlled, deliberate movements for maximum benefit.', '{"image_male_start":"images/Shoulders/Band Incline Row_female.jpg","image_female_start":"images/Shoulders/Band Incline Row_female.jpg","image_female_end":"images/Shoulders/Band Incline Row_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7228737a-300c-4561-be6f-ec44e8bce858'::uuid, 'Band Incline T Raise', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie chest-first on an incline bench set at a 45-degree angle, holding one handle of the resistance band in each hand with your arms fully extended down, palms facing forward. Keep your feet firm on the floor and the resistance band secured under the bench.\r\n2. Lift your arms out to the sides until they reach shoulder height, forming a "T" shape with your body.\r\n3. Pause briefly at the top of the movement, ensuring your arms are parallel and your torso is stable against the bench.\r\n4. Lower your arms back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you lift your arms and inhale as you lower them back down.\r\n2. Perform the exercise slowly and with control to maximize muscle engagement.\r\n3. Keep your neck in a neutral position by looking at the bench, not forward or down.', '{"image_male_start":"images/Shoulders/Band Incline T Raise_female.jpg","image_female_start":"images/Shoulders/Band Incline T Raise_female.jpg","image_female_end":"images/Shoulders/Band Incline T Raise_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e065e12a-3125-40a4-9fbd-6f04a1e4c557'::uuid, 'Band Incline Triceps Extension', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Lie on an incline bench set at a 45-degree angle. Place the resistance band under the bench and hold one handle of the band in each hand with your arms extended straight above your head, palms facing forward.\r\n2. Lower the handles behind your head by bending your elbows, keeping your upper arms stationary.\r\n3. Pause briefly at the bottom of the movement, ensuring your forearms are parallel to the floor and your upper arms remain still.\r\n4. Extend your arms back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Ensure the resistance band is securely anchored under the bench to avoid slipping.\r\n2. Maintain a neutral wrist position to reduce strain on your joints.\r\n3 .Focus on squeezing your triceps at the top of the movement.', '{"image_male_start":"images/Triceps/Band Incline Triceps Extension_female.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('18e12dd2-fb69-4b34-94bf-0b020f177f9c'::uuid, 'Band Incline Y Raise', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie chest-first on an incline bench set at a 45-degree angle, holding one handle of the resistance band in each hand with your arms hanging down and palms facing back. Ensure the resistance band is secured under the bench.\r\n2. Lift your arms diagonally in a "Y" shape until they are in line with your body, keeping a slight bend in your elbows.\r\n3. Lower your arms back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you lift your arms and inhale as you lower them back down.\r\n2. Use a resistance band with appropriate tension to ensure you can perform the exercise with good form.\r\n3. Maintain a slight bend in your elbows to protect your shoulder joints.', '{"image_male_start":"images/Shoulders/Band Incline Y Raise_female.jpg","image_female_start":"images/Shoulders/Band Incline Y Raise_female.jpg","image_female_end":"images/Shoulders/Band Incline Y Raise_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('82c4f84a-d754-4be5-bfd3-eea4e7e5ca23'::uuid, 'band kneeling crunch', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Secure the middle of the resistance band to a sturdy anchor point above head height. Kneel on the floor facing away of the anchor point, holding one handle of the band in each hand with your hands positioned at the sides of your head.\r\n2. Engage your core and bend at the waist, bringing your elbows towards your knees in a controlled crunch motion.\r\n3. Pause briefly at the bottom of the movement, ensuring a full contraction of your abdominal muscles.\r\n4. Slowly return to the starting position with control. Repeat for the desired number of repetitions.', E'1. Focus on using your abs to pull your torso down rather than your arms.\r\n2. Ensure the resistance band is securely anchored to avoid slipping.\r\n3. Exhale as you crunch down and inhale as you return to the starting position.', '{"image_male_start":"images/Abdominals/band kneeling crunch_female.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('703f4f4b-209a-45d3-86aa-c2217306b7e5'::uuid, 'band kneeling lat pulldown', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Secure the middle of the resistance band to a sturdy anchor point above head height. Kneel on the floor facing the anchor point, holding one handle of the band in each hand with your arms extended overhead and palms facing forward.\r\n2. Pull the handles down towards your shoulders, bending your elbows and keeping them close to your body until your hands are near shoulder height.\r\n3. Squeeze your shoulder blades together at the bottom of the movement, ensuring a full contraction of your back muscles.\r\n4. Slowly extend your arms back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you pull the band handles down and inhale as you return to the starting position.\r\n2. Perform the exercise slowly and with control to maximize muscle engagement.\r\n3. Focus on squeezing your back muscles at the bottom of the movement.', '{"image_male_start":"images/Back/band kneeling lat pulldown_female.jpg","image_female_start":"images/Back/band kneeling lat pulldown_female.jpg","image_female_end":"images/Back/band kneeling lat pulldown_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d4615769-a607-477d-a0da-d37bbb23c396'::uuid, 'band kneeling preacher curl', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Secure the middle of the resistance band to a sturdy anchor point low to the floor. Squat fully on the floor facing the anchor point, holding one handle of the band in each hand with your arms extended in front of you, resting on your knees, and palms facing up.\r\n2. Curl the handles towards your shoulders, keeping your upper arms stationary until your hands are near shoulder level.\r\n3. Squeeze your biceps at the top of the movement, ensuring a full contraction.\r\n4. Slowly lower the handles back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Ensure the resistance band is securely anchored to avoid slipping.\r\n2. Exhale as you curl the band handles upward and inhale as you lower them back down.\r\n3. Keep your upper arms stationary to isolate the biceps.', '{"image_male_start":"images/Biceps/band kneeling preacher curl_female.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c81c04bc-78ed-44fd-bfd1-f5a9604791e4'::uuid, 'band kneeling rear kick', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Kneel on all fours, on your knees and elbows, with your hands holding the handles of the band and the band looped around your right foot.\r\n2. Extend your right leg straight back, keeping your foot flexed and your leg in level with your body.\r\n3. Squeeze your glutes at the top of the movement, ensuring a full contraction.\r\n4. Slowly return your right leg to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you extend your leg back and inhale as you return to the starting position.\r\n2. Maintain a neutral spine to avoid strain on your lower back.\r\n3. Avoid rotating your hips outward; maintain square hips to the floor.', '{"image_male_start":"images/Legs/band kneeling rear kick_female.jpg","image_female_start":"images/Legs/band kneeling rear kick_female.jpg","image_female_end":"images/Legs/band kneeling rear kick_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('bca5d8ce-334d-43ba-af23-45a096ea7ca5'::uuid, 'band low alternate chest press', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Secure the middle of the resistance band to a sturdy anchor point above head height. Step one foot in front and the other back, with both knees slightly bent, facing away of the anchor point, holding one handle of the band in each hand with your palms facing down, positioning your hands near to your shoulders.\r\n2. Press the right handle forward until your arm is fully extended, keeping your left hand stationary.\r\n3. Squeeze your chest muscles at the top of the movement, then slowly return the right handle to the starting position with control.\r\n4. Repeat the pressing motion with your left hand, alternating between right and left arms for the desired number of repetitions.', E'1. Exhale as you press the band handle forward and inhale as you return it back.\r\n2. Perform the exercise slowly and with control to maximize muscle engagement.\r\n3. Avoid rotating your torso; keep your movements focused and controlled.', '{"image_male_start":"images/Chest/band low alternate chest press_female.jpg","image_female_start":"images/Chest/band low alternate chest press_female.jpg","image_female_end":"images/Chest/band low alternate chest press_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4a226114-23a3-44e1-90ed-0f7fd645e694'::uuid, 'band low chest fly', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Secure the middle of the resistance band to a high anchor point above you. Step one foot in front and the other back, with both knees slightly bent, facing away from the anchor point, holding one handle of the band in each hand with your arms extended at your sides at shoulder level, palms facing forward.\r\n2. Bring your arms down in a wide arc motion until your hands meet opposite your chest, keeping a slight bend in your elbows.\r\n3. Squeeze your chest muscles at the top of the movement, then slowly raise your arms back to the starting position with control.\r\n4. Repeat the fly motion for the desired number of repetitions.', E'1. Keep a slight bend in your elbows to protect your shoulder joints.\r\n2. Focus on squeezing your chest muscles as you bring your hands together.\r\n3. Use a resistance band with appropriate tension to ensure you can perform the exercise with good form.', '{"image_male_start":"images/Chest/band low chest fly_female.jpg","image_female_start":"images/Chest/band low chest fly_female.jpg","image_female_end":"images/Chest/band low chest fly_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('71099582-2a3a-4b73-8572-33238e76126d'::uuid, 'band low chest press', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Secure the middle of the resistance band to a sturdy anchor point above head height. Step one foot in front and the other back, with both knees slightly bent, facing away of the anchor point, holding one handle of the band in each hand with your palms facing down, positioning your hands near to your shoulders.\r\n2. Press both handles forward until your arm is fully extended. Squeeze your chest muscles at the top of the movement, then slowly return the handles to the starting position with control.\r\n3. Repeat the pressing motion for the desired number of repetitions.', E'1. Exhale as you press the band handles forward and inhale as you return it back.\r\n2. Perform the exercise slowly and with control to maximize muscle engagement.\r\n3. Focus on using your chest muscles to press the band handles.', '{"image_male_start":"images/Chest/band low chest press_female.jpg","image_female_start":"images/Chest/band low chest press_female.jpg","image_female_end":"images/Chest/band low chest press_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('797aae72-ffdf-4289-9caa-1d24d9785d3b'::uuid, 'Band Lying Reverse Grip Pressdown', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Lie on your back with your feet flat on the floor, knees bent, and a resistance band anchored behind your head. Hold the ends of the band with your palms facing forward with your elbows bent and forearms parallel to the floor.\r\n2. Extend your arms straight up to the ceiling, keeping your elbows stationary.\r\n3. Slowly return your hands to the starting position, controlling the resistance.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Use a controlled motion to extend and return your arms, preventing any jerking movements.\r\n2. Use an appropriate resistance band that challenges you without compromising your form.\r\n3. Perform the exercise slowly and with control to increase muscle activation and reduce the risk of injury.', '{"image_male_start":"images/Triceps/Band Lying Reverse Grip Pressdown_female.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ca79ae9f-ff5e-4c88-88f4-4c84f9788dd1'::uuid, 'Band Lying Reverse Grip Row', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie chest-first on an incline bench, with your feet firmly planted on the floor for stability. Hold the handles of a resistance band anchored below the bench with a reverse grip (palms forward) and allow them to hang down.\r\n2. Pull the handles of the band upwards towards your torso by bending your elbows, keeping them close to your body, and squeezing your shoulder blades together at the top of the movement.\r\n3. Slowly return to the starting position, extending your arms back down towards the floor. \r\n4. Repeat the movement for the desired number of repetitions.', E'1. Maintain a neutral spine throughout the exercise to avoid straining your lower back.\r\n2. Breathe steadily, exhaling as you pull the band and inhaling as you return to the starting position.\r\n3. Keep your elbows close to your body to maximize back engagement and minimize shoulder involvement.', '{"image_male_start":"images/Back/Band Lying Reverse Grip Row_female.jpg","image_female_start":"images/Back/Band Lying Reverse Grip Row_female.jpg","image_female_end":"images/Back/Band Lying Reverse Grip Row_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('dfd4062d-1441-452c-b59b-71cbe401e45e'::uuid, 'Band Prone Incline Curl', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie chest-first on an incline bench, with your feet firmly planted on the floor for stability. Hold the handles of a resistance band anchored below the bench, with your arms fully extended down and palms facing forward.\r\n2. Curl the handles of the band upwards towards your shoulders by bending your elbows, keeping your upper arms stationary and squeezing your biceps at the top of the movement.\r\n3. Slowly return to the starting position, extending your arms back down towards the floor.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Keep your elbows stationary and close to your body to maximize biceps engagement.\r\n2. Squeeze your biceps at the top of the movement to enhance muscle activation.\r\n3. Use an appropriate resistance band that challenges you without compromising your form.', '{"image_male_start":"images/Biceps/Band Prone Incline Curl_female.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('90726a10-b7c7-420e-acfb-d3b4e2b8a79c'::uuid, 'Band Prone Incline Hammer Curl', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie chest-first on an incline bench, with your feet firmly planted on the floor for stability. Hold the handles of a resistance band anchored below the bench, with your arms fully extended down and palms facing each other (neutral grip).\r\n2. Curl the handles of the band upwards towards your shoulders by bending your elbows, keeping your upper arms stationary and your palms facing each other throughout the movement.\r\n3. Slowly return to the starting position, extending your arms back down towards the floor.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Keep your elbows stationary and close to your body to maximize biceps engagement.\r\n2. Squeeze your biceps at the top of the movement to enhance muscle activation.\r\n3. Use an appropriate resistance band that challenges you without compromising your form.', '{"image_male_start":"images/Biceps/Band Prone Incline Hammer Curl_female.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f799bcce-b938-4e29-9f5b-3d7b138eb198'::uuid, 'Band Push-up', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a plank position with the resistance band crossed around your upper back and each end secured under your hands, which should be placed slightly wider than shoulder-width apart. Your feet should be together.\r\n2. Engage your core and ensure your body forms a straight line from your head to your heels.\r\n3. Lower your chest towards the floor by bending your elbows, keeping them at about a 45-degree angle to your body.\r\n4. Push through your hands to return to the starting position, straightening your arms. Repeat the movement for the desired number of repetitions.', E'1. Keep your core engaged throughout the exercise to maintain a straight body line and avoid sagging your hips.\r\n2. Breathe steadily throughout the exercise, exhaling as you push up and inhaling as you lower down.\r\n3. Perform the movement with control to maximize muscle activation and prevent injury.', '{"image_male_start":"images/Chest/Band Push-up_female.jpg","image_female_start":"images/Chest/Band Push-up_female.jpg","image_female_end":"images/Chest/Band Push-up_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e64a0183-ac2e-4266-90a8-bc7c429d840c'::uuid, 'Band Reverse Fly', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie chest-first on an incline bench, with your feet firmly planted on the floor. Hold the ends of a resistance band anchored below the bench with your arms extended downward and slightly bent at the elbows, palms facing each other.\r\n2. Raise your arms out to the sides in a wide arc motion until they are in line with your shoulders, squeezing your shoulder blades together at the top of the movement.\r\n3. Slowly return to the starting position, controlling the resistance band as you lower your arms.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Keep your elbows slightly bent to avoid joint strain and focus on squeezing your shoulder blades together.\r\n2. Ensure the bench is stable and at an appropriate incline angle to effectively target the upper back muscles.\r\n3. Breathe steadily, exhaling as you raise the band and inhaling as you return to the starting position.', '{"image_male_start":"images/Shoulders/Band Reverse Fly_female.jpg","image_female_start":"images/Shoulders/Band Reverse Fly_female.jpg","image_female_end":"images/Shoulders/Band Reverse Fly_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('cfa77b1d-4e9e-4613-be81-929ab54f2664'::uuid, 'Band Reverse Spider Curl', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie chest-first on an incline bench, with your feet firmly planted on the floor. Hold the ends of a resistance band anchored below the bench, with your arms extended downward and palms facing back (pronated grip).\r\n2. Curl the handles of the band upwards towards your shoulders by bending your elbows, keeping your upper arms stationary and squeezing your biceps at the top of the movement.\r\n3. Slowly return to the starting position, extending your arms back down towards the floor.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Keep your elbows stationary to maximize biceps engagement.\r\n2. Squeeze your biceps at the top of the movement to enhance muscle activation.\r\n3. Use an appropriate resistance band that challenges you without compromising your form.', '{"image_male_start":"images/Biceps/Band Reverse Spider Curl_female.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e651166b-bd49-41fd-8939-581263f470a6'::uuid, 'Band Rotating Hammer Grip Incline Bench Row', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Adjust an incline bench to a 45-degree angle and lie face down on the bench with your forefeet firmly on the floor. Place the resistance band under the bench and hold one handle of the band in each hand using an underhand grip (palms facing up), letting your arms hang straight down.\r\n2. Pull the handles towards your torso by bending your elbows, rotating them to a hammer grip (palms facing you), and keeping them close to your body until your hands are near your sides.\r\n3. Extend your arms back to the starting position with control. \r\n4. Repeat for the desired repetitions.', E'1. Ensure the resistance band is securely placed under the bench to avoid slipping.\r\n2. Exhale as you pull the band handles towards your torso and inhale as you return to the starting position.\r\n3. Use a resistance band with appropriate tension to ensure you can perform the exercise with good form.', '{"image_male_start":"images/Back/Band Rotating Hammer Grip Incline Bench Row_female.jpg","image_female_start":"images/Back/Band Rotating Hammer Grip Incline Bench Row_female.jpg","image_female_end":"images/Back/Band Rotating Hammer Grip Incline Bench Row_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('83d92ede-7b3c-4dea-bf90-6c684bea3e20'::uuid, 'Band Seated Lateral Raise', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on a bench with your feet flat on the floor, holding the ends of a resistance band anchored under the bench with your arms hanging at your sides, palms facing inward, and a slight bend in your elbows.\r\n2. Raise your arms out to the sides until they are parallel to the floor, keeping your elbows slightly bent and leading with your elbows.\r\n3. Slowly return to the starting position, controlling the resistance band as you lower your arms.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Use an appropriate resistance band that challenges you without compromising your form.\r\n2. Ensure the band is securely anchored under the bench to prevent slipping.\r\n3. Keep your elbows slightly bent to avoid joint strain and focus on lifting with your shoulders.', '{"image_male_start":"images/Shoulders/Band Seated Lateral Raise_female.jpg","image_female_start":"images/Shoulders/Band Seated Lateral Raise_female.jpg","image_female_end":"images/Shoulders/Band Seated Lateral Raise_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5ef46710-f2c2-463d-90cd-a63eb9cfbf2c'::uuid, 'Band Seated Neutral Grip Shoulders Press', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on a bench with your feet flat on the floor, holding the ends of a resistance band anchored under the bench, with your arms bent, hands at shoulder level, and palms facing each other (neutral grip).\r\n2. Press the handles of the band upwards until your arms are fully extended above your head, keeping your palms facing each other.\r\n3. Slowly lower your hands back to shoulder level, controlling the resistance band as you lower your arms.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Perform the exercise slowly and with control to maximize muscle activation and reduce the risk of injury.\r\n2. Use an appropriate resistance band that challenges you without compromising your form.\r\n3. Ensure the band is securely anchored under the bench to prevent slipping.', '{"image_male_start":"images/Shoulders/Band Seated Neutral Grip Shoulders Press_female.jpg","image_female_start":"images/Shoulders/Band Seated Neutral Grip Shoulders Press_female.jpg","image_female_end":"images/Shoulders/Band Seated Neutral Grip Shoulders Press_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4f397532-1f83-4994-8dfa-260cc9540282'::uuid, 'Band Seated Shoulder Press', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on a bench with your feet flat on the floor, holding the ends of a resistance band anchored under the bench, with your arms bent, hands at shoulder level, and palms facing forward.\r\n2. Press the handles of the band upwards until your arms are fully extended above your head, keeping your palms facing forward.\r\n3. Slowly lower your hands back to shoulder level, controlling the resistance band as you lower your arms.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Perform the exercise slowly and with control to maximize muscle activation and reduce the risk of injury.\r\n2. Use an appropriate resistance band that challenges you without compromising your form.\r\n3. Ensure the band is securely anchored under the bench to prevent slipping.', '{"image_male_start":"images/Shoulders/Band Seated Shoulder Press_female.jpg","image_female_start":"images/Shoulders/Band Seated Shoulder Press_female.jpg","image_female_end":"images/Shoulders/Band Seated Shoulder Press_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5f338d79-f396-4979-bd2c-543da783e906'::uuid, 'Band side bend', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Anchor one end of the band at a low point of the equipment. Stand with your feet shoulder-width apart, your right side leaning to the anchor point, holding the other end of the resistance band in your right hand. Allow your left hand to hang by your side for counterbalance.\r\n2. Contract your left obliques to bend at the waist to your left side until you are upright.\r\n3. Return to the starting position with control.\r\n4. Repeat the movement for the desired repetitions, then switch sides.', E'1. Engage your core to help stabilize your body and prevent unnecessary movement.\r\n2. Avoid bending forward or backward; focus on bending directly to the side.\r\n3. Breathe steadily, exhaling as you bend to the side and inhaling as you return to the upright position.', '{"image_male_end":"images/Abdominals/Band side bend_female.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f5eaf8a4-34bd-4e0a-94d6-93c702299162'::uuid, 'Band single leg split squat', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, holding the ends of a resistance band anchored under your front foot. Place your back foot on a bench behind you.\r\n2. Lower your body by bending your front knee until your front thigh is parallel to the floor.\r\n3. Push through the heel of your front foot to return to the starting position, straightening your front leg.\r\n4. Repeat the movement for the desired number of repetitions, then switch legs to work the other side.', E'1. Maintain an upright torso throughout the exercise to avoid leaning forward.\r\n2. Ensure your front knee stays in line with your toes to avoid putting stress on the knee joint.\r\n3. Keep your weight evenly distributed on your front leg during the exercise.', '{"image_male_start":"images/Legs/Band single leg split squat_female.jpg","image_female_start":"images/Legs/Band single leg split squat_female.jpg","image_female_end":"images/Legs/Band single leg split squat_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('076a56c4-245d-4571-94f9-40cf0f4ba709'::uuid, 'Band Standing Leg Curl', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, holding to a weight cage for balance. Attach a resistance band to a low anchor point and loop the other end around your right ankle. Shift your weight onto your left leg.\r\n2. Curl your right leg by bending your knee, bringing your heel towards your glutes while keeping your upper leg stationary.\r\n3. Slowly return to the starting position, straightening your leg and controlling the resistance band.\r\n4. Repeat the movement for the desired number of repetitions, then switch legs.', E'1. Focus on squeezing your hamstrings at the top of the movement to enhance muscle activation.\r\n2. Maintain an upright posture throughout the exercise; avoid leaning forward or backward.\r\n3. Keep your supporting knee slightly bent to maintain balance.', '{"image_male_start":"images/Legs/Band Standing Leg Curl_female.jpg","image_female_start":"images/Legs/Band Standing Leg Curl_female.jpg","image_female_end":"images/Legs/Band Standing Leg Curl_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('895338a4-b10d-4253-9c1f-d13dc00b69c2'::uuid, 'Band standing rear delt row', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, holding the ends of a resistance band anchored at head height in front of you. Keep your arms extended straight forward just higher than shoulder height with palms facing down.\r\n2. Pull the band towards your chin by bending your elbows out to the sides, focusing on squeezing your shoulder blades together.\r\n3. Slowly return to the starting position, extending your arms back to shoulder height.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Breathe steadily, exhaling as you pull the band towards your chin and inhaling as you return to the starting position.\r\n2. Focus on squeezing your shoulder blades together at the top of the movement to maximize rear delt engagement.\r\n3. Adjust the band’s resistance by stepping on it closer to or farther from the anchor point.', '{"image_male_start":"images/Shoulders/Band standing rear delt row_female.jpg","image_female_start":"images/Shoulders/Band standing rear delt row_female.jpg","image_female_end":"images/Shoulders/Band standing rear delt row_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0deea0ca-1e1d-43b4-8f54-9640029e6f33'::uuid, 'Band Two Legs Calf Raise - (Band under both legs) VERSION 2', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet hip-width apart on the resistance band, holding the ends in each hand with the band securely anchored under both feet.\r\n2. Rise up onto your forefeet, lifting your heels as high as possible while keeping the tension in the band.\r\n3. Slowly lower your heels back to the floor, maintaining control throughout the movement.\r\n4.  Repeat the movement for the desired number of repetitions.', E'1. Breathe steadily, exhaling as you rise up and inhaling as you lower down.\r\n2. Keep your knees slightly bent to avoid locking them out during the movement.\r\n3. Focus on squeezing your calves at the top of the movement to enhance muscle activation.', '{"image_male_start":"images/Legs/Band Two Legs Calf Raise - (Band under both legs) VERSION 2_female.jpg","image_female_start":"images/Legs/Band Two Legs Calf Raise - (Band under both legs) VERSION 2_female.jpg","image_female_end":"images/Legs/Band Two Legs Calf Raise - (Band under both legs) VERSION 2_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('826e819a-7523-4214-8639-99c45c44432f'::uuid, 'Band Warm up Shoulder Stretch', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, holding the resistance band with both hands in front of you. Your arms should be straight, and hands shoulder-width apart.\r\n2. Slowly lift the band overhead while slightly spreading your hands to stretch the band.\r\n3. Hold this position for a few seconds and slowly return to the starting position with the band in front of you.\r\n4.  Repeat the movement for the desired number of repetitions.', E'1. Keep your arms straight but not locked to avoid joint strain.\r\n2. Ensure the resistance band has appropriate tension to provide an effective stretch without causing discomfort.\r\n3. Perform the stretch slowly and with control to maximize muscle activation and reduce the risk of injury.', '{"image_male_start":"images/Stretching - Mobility/Band Warm up Shoulder Stretch_female.jpg","image_female_start":"images/Stretching - Mobility/Band Warm up Shoulder Stretch_female.jpg","image_female_end":"images/Stretching - Mobility/Band Warm up Shoulder Stretch_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('bf297d44-8316-49d4-b977-93296a2ee471'::uuid, 'Band Wrist Curl', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on a bench with your feet flat on the floor, holding the end of a resistance band, with your right hand, anchored under your right foot. Rest your forearm on your thigh with your palm facing up.\r\n2. Start with your wrist extended down towards the floor, keeping your forearm stationary.\r\n3. Curl your wrist upward, bringing your knuckles towards your forearm, squeezing your forearm muscles at the top of the movement.\r\n4. Slowly return to the starting position, extending your wrist downwards. Repeat the movement for the desired number of repetitions.', E'1. Keep your forearm stationary on your thighs to isolate the wrist movement.\r\n2. Focus on squeezing your forearm muscles at the top of the movement to enhance muscle activation.\r\n3. Breathe steadily, exhaling as you curl your wrists and inhaling as you return to the starting position.', '{"image_male_start":"images/Forearms/Band Wrist Curl_female.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('86919245-4cc8-457f-a0d8-f11023353cba'::uuid, 'Band Y Raise', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, holding the ends of two crossed resistance bands anchored at a low point on a sturdy equipment. Start with your arms hanging in front of your torso, palms facing your hips.\r\n2. Raise your arms upward and outward to form a "Y" shape until your arms are in line with your shoulders.\r\n3. Slowly return to the starting position, controlling the resistance band as you lower your arms.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Breathe steadily, exhaling as you raise your arms and inhaling as you return to the starting position.\r\n2. Keep your elbows slightly bent to avoid joint strain and focus on lifting with your shoulders.\r\n3. Use an appropriate resistance band that challenges you without compromising your form.', '{"image_male_start":"images/Shoulders/Band Y Raise_female.jpg","image_female_start":"images/Shoulders/Band Y Raise_female.jpg","image_female_end":"images/Shoulders/Band Y Raise_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('797158aa-daa0-42cd-acc9-9da2fefd9c6f'::uuid, 'Barbell  squat back POV', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Position yourself under a barbell resting on a squat rack. Place the barbell across your upper back and grip the bar with your hands slightly wider than shoulder-width apart. \r\n2. Lift the bar off the rack and take a step back, standing with your feet shoulder-width apart.\r\n3. Keep your chest up, and maintain a neutral spine. Begin the squat by pushing your hips back and bending your knees, lowering your body until your thighs are parallel to the floor or slightly below.\r\n4. Push through your heels to return to the starting position, extending your hips and knees until you are fully upright. Repeat for the desired number of repetitions.', E'1. Ensure your knees track over your toes to prevent knee injuries and ensure proper form.\r\n2. Maintain a neutral spine by keeping your chest up and eyes forward.\r\n3. Distribute your weight evenly across your feet to ensure balance and stability.', '{"image_male_start":"images/Legs/Barbell squat back POV.jpg","video_url":"videos/Legs/Barbell squat back POV.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('cdd88d38-2b14-40b3-82f3-bb11210e404c'::uuid, 'Barbell Alternate Biceps Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand upright with your feet shoulder-width apart, holding a barbell with one hand, your palm facing forward (supinated grip). Keep your arm fully extended by your side.\r\n2. Keep your elbow close to your torso. Slowly curl the barbell up towards your shoulder, maintaining the supinated grip with your palm facing upward.\r\n3. Squeeze your bicep at the top of the movement, ensuring your elbow stays stationary and close to your body.\r\n4. Slowly lower the barbell back to the starting position with control. Repeat for the desired number of repetitions, then switch to the other arm.', E'1. Keep your back straight and shoulders back to maintain proper posture.\r\n2. Visualize the bicep contraction to enhance the mind-muscle connection for better results.\r\n3. Ensure your movements are symmetrical to avoid muscle imbalances; focus equally on both arms.', '{"image_male_start":"images/Biceps/Barbell Alternate Biceps Curl_female.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('78861e90-8706-4200-afb4-84533f28fba9'::uuid, 'Barbell Back Wide Shrug', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand upright with your feet shoulder-width apart, holding a barbell with both hands behind your back. Your palms should face away from your body with a wide grip.\r\n2. Keep your shoulders back and chest up. Slowly lift your shoulders towards your ears in a shrugging motion.\r\n3. Squeeze your shoulder blades together at the top of the movement, holding the contraction for a moment.\r\n4. Slowly lower your shoulders back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Avoid rotating your shoulders; lift them straight up and down to prevent strain.\r\n2. Breathe steadily, exhaling as you lift your shoulders and inhaling as you lower them.\r\n3. Keep your arms straight throughout the exercise to focus the movement on your shoulders.', '{"image_male_start":"images/Shoulders/Barbell Back Wide Shrug_female.jpg","image_female_start":"images/Shoulders/Barbell Back Wide Shrug_female.jpg","image_female_end":"images/Shoulders/Barbell Back Wide Shrug_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c20302c0-9205-4fa3-9d9d-1e936e0c81c8'::uuid, 'Barbell back wide shrugs', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand upright with your feet shoulder-width apart, holding a barbell with both hands behind your back. Your palms should face away from your body with a wide grip.\r\n2. Keep your shoulders back and chest up. Slowly lift your shoulders towards your ears in a shrugging motion.\r\n3. Squeeze your shoulder blades together at the top of the movement, holding the contraction for a moment.\r\n4. Slowly lower your shoulders back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Avoid rotating your shoulders; lift them straight up and down to prevent strain.\r\n2. Breathe steadily, exhaling as you lift your shoulders and inhaling as you lower them.\r\n3. Keep your arms straight throughout the exercise to focus the movement on your shoulders.', '{"image_male_start":"images/Shoulders/Barbell back wide shrugs.jpg","image_male_end":"images/Shoulders/Barbell back wide shrugs1.jpg","video_url":"videos/Shoulders/Barbell back wide shrugs.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6b1e8bc2-1134-4bc4-b858-9c400e031af1'::uuid, 'Barbell behind neck military press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on a bench without back support, holding a barbell with both hands. Your hands should be slightly wider than shoulder-width apart, and the barbell should rest on your upper back and shoulders.\r\n2. Sit up straight. Start with your elbows bent and the barbell behind your neck.\r\n3. Press the barbell overhead until your arms are fully extended, keeping the bar slightly behind your head.\r\n4. Slowly lower the barbell back to the starting position behind your neck with control. Repeat for the desired number of repetitions.', E'1. Maintain an upright posture without leaning back.\r\n2. Breathe steadily, exhaling as you press the barbell up and inhaling as you lower it back down.\r\n3. Ensure your movements are symmetrical to avoid muscle imbalances.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('48e68d62-08bc-433c-9af0-b7496d6d18f3'::uuid, 'Barbell behind neck push press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with both hands behind your neck. Your hands should be slightly wider than shoulder-width apart, with the barbell resting on your upper back and shoulders.\r\n2. Slightly bend your knees, preparing to use your legs to generate power.\r\n3. Push through your heels and extend your knees and hips explosively, pressing the barbell overhead until your arms are fully extended. Keep the bar slightly behind your head at the top of the movement.\r\n4. Slowly lower the barbell back to the starting position behind your neck with control. Repeat for the desired number of repetitions.', E'1. Avoid excessive backward lean by engaging your core and keeping your chest up.\r\n2. Exhale forcefully as you press the barbell overhead and inhale as you bring it back down.\r\n3. Ensure a smooth and controlled descent to maintain proper form and prevent injury.', '{"image_male_start":"images/Shoulders/Barbell behind neck push press.jpg","image_male_end":"images/Shoulders/Barbell behind neck push press1.jpg","video_url":"videos/Shoulders/Barbell behind neck push press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('19a09fe7-f40d-4d97-ba8b-c755a0dbdd7b'::uuid, 'Barbell Behind the Back Push Press Single Arm Balance', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with one hand behind your back. Your hand should be slightly wider than shoulder-width apart, with the barbell resting on your upper back and shoulder.\r\n2. Slightly bend your knees, preparing to use your legs to generate power.\r\n3. Push through your heels and extend your knees and hips explosively, pressing the barbell overhead with one arm until your arm is fully extended. Keep the bar slightly behind your head at the top of the movement.\r\n4. Slowly lower the barbell back to the starting position behind your shoulder with control. Repeat for the desired number of repetitions, then switch to the other arm.', E'1. Maintain balance by focusing on a fixed point in front of you and keeping your core engaged.\r\n2. Exhale forcefully as you press the barbell overhead and inhale as you bring it back down.\r\n3. Ensure a smooth and controlled descent to maintain proper form and prevent injury.', '{"image_male_start":"images/Shoulders/Barbell Behind the Back Push Press Single Arm Balance_female.jpg","image_female_start":"images/Shoulders/Barbell Behind the Back Push Press Single Arm Balance_female.jpg","image_female_end":"images/Shoulders/Barbell Behind the Back Push Press Single Arm Balance_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('bde19b44-4625-491f-add9-f43e63dc6569'::uuid, 'Barbell Bench Lateral Step-up', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '4ec743bc-cfcd-4426-a49b-ad90f93abe76'::uuid, E'1. Stand beside a bench with a barbell across your upper back. Your hands should grip the bar slightly wider than shoulder-width apart.\r\n2. Step laterally onto the bench with your closest foot, pushing through your heel to lift your body up onto the bench.\r\n3. Bring your trailing leg up to meet the stepping leg by the bench, maintaining balance and control.\r\n4. Step down off the bench with your trailing leg first, then the stepping leg. Repeat for the desired number of repetitions, then switch sides.', E'1. Ensure your entire foot is placed on the bench to provide a stable base for the step-up.\r\n2. Move slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Breathe steadily, exhaling as you step up and inhaling as you step down.', '{"image_male_start":"images/Legs/Barbell Bench Lateral Step-up_female.jpg","image_female_start":"images/Legs/Barbell Bench Lateral Step-up_female.jpg","image_female_end":"images/Legs/Barbell Bench Lateral Step-up_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('765e7a54-1bfe-4bb0-b1d3-e029994d81d7'::uuid, 'Barbell Bench Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Lie on a flat bench with your feet flat on the floor. Grip the barbell with your hands slightly wider than shoulder-width apart, and position the bar directly above your chest.\r\n2. Engage your core and unrack the barbell by extending your arms fully. Lower the barbell slowly and with control to your chest, keeping your elbows at a 45-degree angle to your body.\r\n3. Press the barbell back up to the starting position by extending your arms fully, focusing on using your chest muscles.\r\n4. Repeat for the desired number of repetitions, then carefully rack the barbell back onto the bench press rack.', E'1. Keep your feet flat on the floor to maintain stability and support your lower back.\r\n2. Engage your core to maintain a stable and strong torso throughout the movement.\r\n3. Lower the barbell slowly and with control to prevent injury and maximize muscle engagement.', '{"image_male_start":"images/Chest/barbell bench press.jpg","image_male_end":"images/Chest/barbell bench press1.jpg","image_female_start":"images/Chest/Barbell Bench Press_female.jpg","image_female_end":"images/Chest/Barbell Bench Press_female1.jpg","video_url":"videos/Chest/Barbell bench press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8ed1a60b-666e-4e3c-8208-34bcb370ab82'::uuid, 'Barbell bench press decline', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Set a decline bench at a suitable angle and lie down on it with your feet secured under the foot pads. Grip the barbell with your hands slightly wider than shoulder-width apart.\r\n2. Engage your core and unrack the barbell by extending your arms fully. Lower the barbell slowly and with control to your lower chest, keeping your elbows at a 90-degree angle to your body.\r\n3. Press the barbell back up to the starting position by extending your arms fully, focusing on using your chest muscles.\r\n4. Repeat for the desired number of repetitions, then carefully rack the barbell back onto the bench press rack.', E'1. Keep your feet secured under the foot pads to maintain stability and prevent sliding.\r\n2. Engage your core to maintain a stable and strong torso throughout the movement.\r\n3. Lower the barbell slowly and with control to prevent injury and maximize muscle engagement.', '{"image_male_start":"images/Chest/barbell bench press decline.jpg","image_male_end":"images/Chest/barbell bench press decline1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5586f847-9d22-45d9-a8f2-6d832d4af38f'::uuid, 'Barbell bench press incline', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Set an incline bench to a 45 degree angle and lie down on it with your feet flat on the floor. Grip the barbell with your hands slightly wider than shoulder-width apart.\r\n2. Engage your core and unrack the barbell by extending your arms fully. Lower the barbell slowly and with control to your upper chest, keeping your elbows at a 45-degree angle to your body.\r\n3. Press the barbell back up to the starting position by extending your arms fully, focusing on using your chest muscles.\r\n4. Repeat for the desired number of repetitions, then carefully rack the barbell back onto the bench press rack.', E'1. Keep your feet flat on the floor to maintain stability and support your lower back.\r\n2. Engage your core to maintain a stable and strong torso throughout the movement.\r\n3. Lower the barbell slowly and with control to prevent injury and maximize muscle engagement.', '{"image_male_start":"images/Chest/barbell bench press incline.jpg","image_male_end":"images/Chest/barbell bench press incline1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('12060eb5-bc25-4d10-909f-b576cb855e86'::uuid, 'Barbell Bench Squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, back facing a bench, holding a barbell across your upper back. Your hands should grip the bar slightly wider than shoulder-width apart.\r\n2. Keep your chest up. Begin the squat by pushing your hips back and bending your knees, lowering your body until you sit down on the bench.\r\n3. Push through your heels to stand back up to the starting position, extending your hips and knees fully. Repeat for the desired number of repetitions.', E'1. Ensure your knees track over your toes to prevent knee injuries and ensure proper form.\r\n2. Keep your chest up and back straight throughout the movement to maintain proper alignment.\r\n3. Breathe steadily, exhaling as you push up and inhaling as you lower down.\r\n', '{"image_male_start":"images/Legs/Barbell Bench Squat_female.jpg","image_female_start":"images/Legs/Barbell Bench Squat_female.jpg","image_female_end":"images/Legs/Barbell Bench Squat_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ca83e6c3-2741-4f84-9920-8235272f4dc2'::uuid, 'Barbell bench squats', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, back facing a bench, holding a barbell across your upper back. Your hands should grip the bar slightly wider than shoulder-width apart.\r\n2. Keep your chest up. Begin the squat by pushing your hips back and bending your knees, lowering your body until you sit down on the bench.\r\n3. Push through your heels to stand back up to the starting position, extending your hips and knees fully. Repeat for the desired number of repetitions.', E'1. Ensure your knees track over your toes to prevent knee injuries and ensure proper form.\r\n2. Keep your chest up and back straight throughout the movement to maintain proper alignment.\r\n3. Breathe steadily, exhaling as you push up and inhaling as you lower down.\r\n', '{"image_male_start":"images/Legs/Barbell bench squats.jpg","image_male_end":"images/Legs/Barbell bench squats1.jpg","video_url":"videos/Legs/Barbell bench squats.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6fa1b10e-67aa-4292-bed8-2e7f35577abf'::uuid, 'Barbell bent over row pronated grip', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with both hands in a pronated grip (palms facing backward), and your hands slightly wider than shoulder-width apart.\r\n2. Slightly bend your knees, and hinge at your hips to lower your torso until it is almost parallel to the floor. Keep your back straight and your gaze forward.\r\n3. Pull the barbell towards your abdomen, squeezing your shoulder blades together at the top of the movement. Keeping your elbows close to your body.\r\n4. Slowly lower the barbell back to the starting position with control, extending your arms fully. Repeat for the desired number of repetitions.', E'1. Avoid rounding your back by keeping your chest up and your spine neutral.\r\n2. Move the barbell slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Breathe steadily, exhaling as you pull the barbell up and inhaling as you lower it back down.', '{"image_male_start":"images/Back/Barbell bent over row pronated grip.jpg","image_male_end":"images/Back/Barbell bent over row pronated grip1.jpg","video_url":"videos/Back/Barbell bent over row pronated grip.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a7e3ffe4-6040-41f9-aee4-c218fe2a639c'::uuid, 'Barbell bent over row supinated grip', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with both hands in a supinated grip (palms facing forward), and your hands slightly wider than shoulder-width apart.\r\n2. Slightly bend your knees, and hinge at your hips to lower your torso until it is almost parallel to the floor. Keep your back straight and your gaze forward.\r\n3. Pull the barbell towards your abdomen, squeezing your shoulder blades together at the top of the movement. Keeping your elbows close to your body.\r\n4. Slowly lower the barbell back to the starting position with control, extending your arms fully. Repeat for the desired number of repetitions.', E'1. Avoid rounding your back by keeping your chest up and your spine neutral.\r\n2. Move the barbell slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Breathe steadily, exhaling as you pull the barbell up and inhaling as you lower it back down.', '{"image_male_start":"images/Back/Barbell bent over row supinated grip.jpg","image_male_end":"images/Back/Barbell bent over row supinated grip1.jpg","video_url":"videos/Back/Barbell bent over row supinated grip.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d913f8a4-be12-4238-bd6d-f6e72ab0a81d'::uuid, 'Barbell bicep curl close grip', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand upright with your feet shoulder-width apart, holding a barbell with both hands using a close supinated grip (palms facing foreward). Your hands should be closer than shoulder-width apart.\r\n2. Engage your core and keep your elbows close to your torso. Slowly curl the barbell up towards your shoulders, maintaining the supinated grip with your palms facing upward.\r\n3. Squeeze your biceps at the top of the movement, ensuring your elbows stay stationary and close to your body.\r\n4. Slowly lower the barbell back to the starting position with control, extending your arms fully. Repeat for the desired number of repetitions.', E'1. Maintain a controlled pace to ensure that you''re using muscle strength rather than momentum.\r\n2. Keep your back straight and shoulders back to maintain proper posture.\r\n3. Visualize the bicep contraction to enhance the mind-muscle connection for better results.', '{"image_male_start":"images/Biceps/barbell bicep curl close grip.jpeg","video_url":"videos/Biceps/barbell bicep curl close grip.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7d4a7108-715d-46e0-a796-87c992904c87'::uuid, 'Barbell bicep curl normal grip', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand upright with your feet shoulder-width apart, holding a barbell with both hands using a supinated grip (palms facing forward). Your hands should be about shoulder-width apart.\r\n2. Keep your elbows close to your torso. Slowly curl the barbell up towards your shoulders, maintaining the supinated grip with your palms facing upward.\r\n3. Squeeze your biceps at the top of the movement, ensuring your elbows stay stationary and close to your body.\r\n4. Slowly lower the barbell back to the starting position with control, extending your arms fully. Repeat for the desired number of repetitions.', E'1. Maintain a controlled pace to ensure that you''re using muscle strength rather than momentum.\r\n2. Keep your back straight and shoulders back to maintain proper posture.\r\n3. Visualize the bicep contraction to enhance the mind-muscle connection for better results.', '{"image_male_start":"images/Biceps/barbell bicep curl normal grip.jpeg","video_url":"videos/Biceps/barbell bicep curl normal grip.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3e801578-3c3c-4545-8fd9-f39d12b327f7'::uuid, 'Barbell bicep curl wide grip', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand upright with your feet shoulder-width apart, holding a barbell with both hands using a supinated grip (palms facing forward). Your hands should be about a fist wider than shoulder-width apart.\r\n2. Keep your elbows close to your torso. Slowly curl the barbell up towards your shoulders, maintaining the supinated grip with your palms facing upward.\r\n3. Squeeze your biceps at the top of the movement, ensuring your elbows stay stationary and close to your body.\r\n4. Slowly lower the barbell back to the starting position with control, extending your arms fully. Repeat for the desired number of repetitions.', E'1. Maintain a controlled pace to ensure that you''re using muscle strength rather than momentum.\r\n2. Keep your back straight and shoulders back to maintain proper posture.\r\n3. Visualize the bicep contraction to enhance the mind-muscle connection for better results.', '{"image_male_start":"images/Biceps/barbell bicep curl wide grip.jpeg","video_url":"videos/Biceps/barbell bicep curl wide grip.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('007f40fa-fff5-4af8-ae95-39c50678bc7e'::uuid, 'Barbell biceps curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand upright with your feet shoulder-width apart, holding a barbell with both hands using a supinated grip (palms facing forward). Your hands should be about shoulder-width apart.\r\n2. Keep your elbows close to your torso. Slowly curl the barbell up towards your shoulders, maintaining the supinated grip with your palms facing upward.\r\n3. Squeeze your biceps at the top of the movement, ensuring your elbows stay stationary and close to your body.\r\n4. Slowly lower the barbell back to the starting position with control, extending your arms fully. Repeat for the desired number of repetitions.', E'1. Maintain a controlled pace to ensure that you''re using muscle strength rather than momentum.\r\n2. Keep your back straight and shoulders back to maintain proper posture.\r\n3. Visualize the bicep contraction to enhance the mind-muscle connection for better results.', '{"image_male_start":"images/Biceps/barbell biceps curl.jpeg","video_url":"videos/Biceps/barbell biceps curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d9725cda-6b3a-464e-b7e0-bb33102ad912'::uuid, 'Barbell box squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, back facing a sturdy box. Position a barbell across your upper back, gripping it with both hands, slightly wider than shoulder-width apart.\r\n2. Slowly lower your body into a squat position by bending your knees and pushing your hips back, keeping your back straight.\r\n3. Lower yourself until your glutes lightly touch the box or bench. Ensure your knees track over your toes and do not cave inward.\r\n4. Push through your heels to stand back up to the starting position, extending your hips and knees fully. Repeat for the desired number of repetitions.', E'1. Ensure your knees track over your toes to prevent knee injuries and ensure proper form.\r\n2. Lower your body slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Breathe steadily, exhaling as you push up and inhaling as you lower down.', '{"image_male_start":"images/Legs/Barbell box squat.jpg","image_male_end":"images/Legs/Barbell box squat1.jpg","image_female_start":"images/Legs/Barbell Box Squat_female.jpg","image_female_end":"images/Legs/Barbell Box Squat_female1.jpg","video_url":"videos/Legs/Barbell box squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('111d4013-f373-41c4-b9f2-b582016110d8'::uuid, 'Barbell bulgarian split squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your back turned to a bench, holding a barbell across your upper back. Grip the bar with your hands slightly wider than shoulder-width apart. \r\n2. Place one foot behind you on the bench, ensuring the top of your foot is resting on the bench.\r\n3. Keep your chest up, and maintain a neutral spine. Begin the squat by bending your front knee and lowering your body until your back knee nearly touches the floor.\r\n4. Push through the heel of your front foot to return to the starting position, extending your hip and knee fully. Repeat for the desired number of repetitions, then switch legs.', E'1. Ensure your front knee tracks over your toes to prevent knee injuries and ensure proper form.\r\n2. Lower your body slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Breathe steadily, exhaling as you push up and inhaling as you lower down.', '{"image_male_start":"images/Legs/Barbell bulgarian split squat.jpg","image_male_end":"images/Legs/Barbell bulgarian split squat1.jpg","image_female_start":"images/Legs/Barbell bulgarian split squat_female.jpg","image_female_end":"images/Legs/Barbell bulgarian split squat_female1.jpg","video_url":"videos/Legs/Barbell bulgarian split squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('31506c68-dd20-430d-aded-3c0536862d9e'::uuid, 'Barbell bulgarian split squat left front-back view', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your back turned to a box, holding a barbell across your upper back. Grip the bar with your hands slightly wider than shoulder-width apart. \r\n2. Place one foot behind you on the box, ensuring the top of your foot is resting on the box.\r\n3. Keep your chest up, and maintain a neutral spine. Begin the squat by bending your front knee and lowering your body until your back knee nearly touches the floor.\r\n4. Push through the heel of your front foot to return to the starting position, extending your hip and knee fully. Repeat for the desired number of repetitions, then switch legs.', E'1. Ensure your front knee tracks over your toes to prevent knee injuries and ensure proper form.\r\n2. Lower your body slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Breathe steadily, exhaling as you push up and inhaling as you lower down.', '{"image_male_start":"images/Legs/Barbell bulgarian split squat left front-back view  .jpg","video_url":"videos/Legs/Barbell bulgarian split squat left front-back view  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d85e488c-2e43-4e38-91cb-7c926ccc0758'::uuid, 'Barbell Bulgarian split squat left side view', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your back turned to a box, holding a barbell across your upper back. Grip the bar with your hands slightly wider than shoulder-width apart. \r\n2. Place one foot behind you on the box, ensuring the top of your foot is resting on the box.\r\n3. Keep your chest up, and maintain a neutral spine. Begin the squat by bending your front knee and lowering your body until your back knee nearly touches the floor.\r\n4. Push through the heel of your front foot to return to the starting position, extending your hip and knee fully. Repeat for the desired number of repetitions, then switch legs.', E'1. Ensure your front knee tracks over your toes to prevent knee injuries and ensure proper form.\r\n2. Lower your body slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Breathe steadily, exhaling as you push up and inhaling as you lower down.', '{"image_male_start":"images/Legs/barbell bulgarian split squat left side view  .jpg","video_url":"videos/Legs/barbell bulgarian split squat left side view  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('10866f28-d58f-497b-87cb-c1bb00e37b7c'::uuid, 'Barbell clean and jerk split squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Lean with your feet shoulder-width apart, holding a barbell with an overhand grip. Clean the barbell to your shoulders by explosively lifting it from the floor, shrugging your shoulders, and rotating your wrists so the bar rests on your shoulders with your elbows pointing forward.\r\n2. Engage your core and slightly dip your knees. Explosively push the barbell overhead by extending your legs and arms fully.\r\n3. Step into a split squat position by moving one leg forward and the other leg back, lowering your body until your back knee nearly touches the floor. Ensure your front knee tracks over your toes and your back knee is bent.\r\n4. Push through the heel of your front foot to stand back up, bringing your feet together while keeping the barbell overhead. Carefully lower the barbell back to the starting position. Repeat for the desired number of repetitions, alternating the leg that steps forward for each rep.\r\n', E'1. Move explosively but with control to ensure proper form and maximize muscle engagement.\r\n2. Ensure your knees track over your toes to prevent knee injuries and maintain proper alignment.\r\n3. Keep your chest up and back straight throughout the movement to maintain proper posture.\r\n', '{"image_male_start":"images/Powerlifting/Barbell clean and jerk split squat.jpg","image_male_end":"images/Powerlifting/Barbell clean and jerk split squat1.jpg","video_url":"videos/Powerlifting/Barbell clean and jerk split squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('bcd4f7f7-c1ce-440a-aa15-593682417c66'::uuid, 'Barbell clean and press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Start in a squatted position with your feet shoulder-width apart, holding a barbell with an overhand grip. The barbell should be on the floor in front of you.\r\n2. Explosively lift the barbell by extending your hips and knees, shrugging your shoulders, and rotating your wrists so the bar rests on your shoulders with your elbows pointing forward (clean position).\r\n3. From the clean position, engage your core and press the barbell overhead by extending your arms fully. Keep the bar slightly behind your head at the top of the movement.\r\n4. Slowly lower the barbell back to your shoulders with control, then return the barbell to the floor by reversing the clean movement. Repeat for the desired number of repetitions.', E'1. Focus on leg drive during the clean to generate power from your lower body.\r\n2. Keep your grip firm but not too tight to allow smooth wrist rotation during the clean.\r\n3. Exhale powerfully as you press the bar overhead to stabilize your core.', '{"image_male_start":"images/Powerlifting/Barbell clean and press.jpg","image_male_end":"images/Powerlifting/Barbell clean and press1.jpg","video_url":"videos/Powerlifting/Barbell clean and press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('686261f9-be6a-44ee-a382-16a0ca21293f'::uuid, 'Barbell clean deadlift', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, toes slightly pointed out, with a barbell on the floor in front of you. Bend at your hips and knees to grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.\r\n2. Engage your core, keep your back straight, and your chest up. Begin the lift by pushing through your heels, extending your hips and knees to lift the barbell off the floor.\r\n3. As the barbell passes your knees, explosively extend your hips and knees while shrugging your shoulders to bring the barbell to your upper thighs.\r\n4. Reverse the movement by lowering the barbell back to the floor with control, maintaining a straight back and engaged core. Repeat for the desired number of repetitions.', E'1. Maintain a neutral spine to avoid rounding your back and prevent injury.\r\n2. Use your legs and hips to drive the barbell up, minimizing the strain on your lower back.\r\n3. Keep the bar close to your body throughout the lift to maintain proper form.', '{"image_male_start":"images/Back/Barbell clean deadlift.jpg","image_male_end":"images/Back/Barbell clean deadlift1.jpg","image_female_start":"images/Powerlifting/Barbell Clean Deadlift_female.jpg","image_female_end":"images/Powerlifting/Barbell Clean Deadlift_female1.jpg","video_url":"videos/Back/Barbell clean deadlift.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('48f31910-be7e-4591-8271-7c7892408878'::uuid, 'Barbell clean grip front squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with a clean grip (palms facing up, elbows pointing forward). The barbell should rest on the front of your shoulders, and your fingers should be under the bar to support it.\r\n2. Begin the squat by pushing your hips back and bending your knees, lowering your body until your thighs are parallel to the floor or slightly below.\r\n3. Push through your heels to return to the starting position, extending your hips and knees fully. Repeat for the desired number of repetitions.\r\n', E'1. Ensure your elbows stay high throughout the movement to keep the barbell in place.\r\n2. Lower your body slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Breathe steadily, exhaling as you push up and inhaling as you lower down.', '{"image_male_start":"images/Powerlifting/Barbell clean grip front squat.jpg","image_male_end":"images/Powerlifting/Barbell clean grip front squat1.jpg","video_url":"videos/Powerlifting/Barbell clean grip front squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8b137c69-6d9b-4a43-836e-8f844d2abfbc'::uuid, 'Barbell clean pull', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Start in a squatted position with your feet shoulder-width apart, toes slightly pointed out, holding a barbell with an overhand grip, hands slightly wider than shoulder-width apart. The barbell should be on the floor in front of you.\r\n2. Begin the lift by pushing through your heels, extending your hips and knees to lift the barbell off the floor.\r\n3. As the barbell passes your knees, explosively extend your hips and knees while shrugging your shoulders and pulling the barbell to your midsection and up to chest level.\r\n4. Lower the barbell back to the floor with control, maintaining a straight back and engaged core. Repeat for the desired number of repetitions.', E'1. Focus on leg drive to generate power from your lower body during the lift.\r\n2. Maintain a neutral spine to avoid rounding your back and prevent injury.\r\n3. Use your legs and hips to drive the barbell up, minimizing the strain on your lower back.', '{"image_male_start":"images/Powerlifting/Barbell clean pull.jpg","image_male_end":"images/Powerlifting/Barbell clean pull1.jpg","image_female_start":"images/Powerlifting/Barbell Clean Pull_female.jpg","image_female_end":"images/Powerlifting/Barbell Clean Pull_female1.jpg","video_url":"videos/Powerlifting/Barbell clean pull.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('02583ff8-ed29-408f-b12d-2b010fc21b49'::uuid, 'Barbell close grip bench press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Lie on a flat bench with your feet flat on the floor. Grip the barbell with your hands placed closer than shoulder-width apart.\r\n2. Unrack the barbell by extending your arms fully. Lower the barbell slowly and with control to your lower chest, keeping your elbows facing away from your body.\r\n3. Press the barbell back up to the starting position by extending your arms fully, focusing on using your triceps and chest muscles.\r\n4. Repeat for the desired number of repetitions, then carefully rack the barbell back onto the bench press rack.', E'1. Maintain a controlled pace to ensure that you''re using muscle strength rather than momentum.\r\n2. Keep your feet flat on the floor to maintain stability and support your lower back.\r\n3. Breathe steadily, exhaling as you press the barbell up and inhaling as you lower it back down.', '{"image_male_start":"images/Chest/Barbell close grip bench press.jpg","image_male_end":"images/Chest/Barbell close grip bench press1.jpg","video_url":"videos/Chest/Barbell close grip bench press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7d4952bd-3213-473f-bb26-000805200be3'::uuid, 'Barbell close grip press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1.Lie on a flat bench with your feet flat on the floor, holding a barbell with your hands placed closer than shoulder-width apart, arms straight over your chest.\r\n2. Lower the barbell slowly and with control to your lower chest, keeping your elbows tucked close to your body.\r\n3. Press the barbell back up to the starting position by extending your arms fully, focusing on using your triceps muscles.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep your elbows tucked in close to your body to engage your triceps effectively.\r\n2. Maintain a controlled pace to ensure that you''re using muscle strength rather than momentum.\r\n3. Keep your feet flat on the floor to maintain stability and support your lower back.', '{"image_male_start":"images/Triceps/Barbell close grip press.jpeg","video_url":"videos/Triceps/Barbell close grip press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('01bd6f4f-477b-4dcb-9eca-6bfdd19e548c'::uuid, 'Barbell curtsy lunges', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell across your upper back. Grip the bar with your hands slightly wider than shoulder-width apart.\r\n2. Step your right leg behind and across your left leg, lowering your hips until your left thigh is parallel to the floor, and your right knee nearly touches the floor in a curtsy position.\r\n3. Push through your front heel to return to the starting position. Repeat on the other side by stepping your left leg behind and across your right leg. Continue alternating legs for the desired number of repetitions.', E'1. Ensure your front knee tracks over your toes to prevent knee injuries and ensure proper form.\r\n2. Lower your body slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Keep your chest up and back straight throughout the movement to maintain proper alignment.', '{"image_male_start":"images/Legs/Barbell curtsy lunges.jpg","image_male_end":"images/Legs/Barbell curtsy lunges1.jpg","video_url":"videos/Legs/Barbell curtsy lunges.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c048a6f9-96ae-4178-864c-e8e4e24bc8a8'::uuid, 'Barbell deadlift', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Bend at your hips and knees to grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.\r\n2. Begin the lift by pushing through your heels, extending your hips and knees to lift the barbell off the floor.\r\n3. As the barbell passes your knees, continue to lift by extending your hips until you are standing upright with the barbell in front of your thighs.\r\n4. Lower the barbell back to the floor with control by pushing your hips back and bending your knees, maintaining a straight back and engaged core. Repeat for the desired number of repetitions.', E'1. Keep your head in line with your spine to maintain proper neck alignment and prevent strain.\r\n2. Visualize pulling the barbell back rather than up, to keep it close to your body and use the correct muscle groups.\r\n3. Use a mixed grip (one hand overhand, one hand underhand) for heavier lifts to enhance grip strength.', '{"image_male_start":"images/Powerlifting/Barbell Deadlift_female.jpg","image_female_start":"images/Powerlifting/Barbell Deadlift_female.jpg","image_female_end":"images/Powerlifting/Barbell Deadlift_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3ced9ba4-cfff-4a1a-b635-738d62bbbee0'::uuid, 'Barbell deadlift 360 degrees', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Bend at your hips and knees to grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.\r\n2. Begin the lift by pushing through your heels, extending your hips and knees to lift the barbell off the floor.\r\n3. As the barbell passes your knees, continue to lift by extending your hips until you are standing upright with the barbell in front of your thighs.\r\n4. Lower the barbell back to the floor with control by pushing your hips back and bending your knees, maintaining a straight back and engaged core. Repeat for the desired number of repetitions.', E'1. Keep your head in line with your spine to maintain proper neck alignment and prevent strain.\r\n2. Visualize pulling the barbell back rather than up, to keep it close to your body and use the correct muscle groups.\r\n3. Use a mixed grip (one hand overhand, one hand underhand) for heavier lifts to enhance grip strength.', '{"video_url":"videos/Back/Barbell deadlift 360 degrees.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6dd4641c-0072-4ea4-8266-0cf89f8d369c'::uuid, 'Barbell Deadlift High Pull', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Place a barbell on the floor in front of you. Stand with your feet wider than shoulder-width apart and your toes pointed slightly outward. \r\n2. Hinge at your hips and bend your knees to lower your body, grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.\r\n3. Push through your heels to lift the barbell off the floor, extending your hips and knees simultaneously. As you reach the standing position, pull the barbell upward towards your chin by bending your elbows and keeping them pointed outward.\r\n4. Lower the barbell back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Use a weight that allows you to maintain proper form throughout the exercise.\r\n2. Push through your heels to maximize power and stability.\r\n3. Ensure your knees track over your toes to prevent knee strain.', '{"image_male_start":"images/Back/Barbell Deadlift High Pull.jpg","image_male_end":"images/Back/Barbell Deadlift High Pull1.jpg","video_url":"videos/Back/Barbell Deadlift High Pull.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('af8443ae-7577-407e-81a2-375bceae5c2a'::uuid, 'Barbell drag biceps curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand upright with your feet shoulder-width apart, holding a barbell with both hands using a supinated grip (palms facing up). Your hands should be about shoulder-width apart.\r\n2. Begin by pulling your elbows back and curling the barbell up along your body, dragging it against your torso.\r\n3. Continue to pull the barbell upward until it reaches chest level, keeping your elbows back and close to your body.\r\n4. Slowly lower the barbell back to the starting position, maintaining control and keeping the barbell close to your torso. Repeat for the desired number of repetitions.', E'1. Keep your elbows back to ensure the barbell stays close to your torso throughout the movement.\r\n2. Maintain a controlled pace to ensure that you''re using muscle strength rather than momentum.\r\n3. Keep your back straight and shoulders back to maintain proper posture.', '{"image_male_start":"images/Biceps/barbell drag biceps curl.jpeg","video_url":"videos/Biceps/barbell drag biceps curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('54af2840-776f-4335-ba01-6efb01160004'::uuid, 'Barbell drag curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand upright with your feet shoulder-width apart, holding a barbell with both hands using a supinated grip (palms facing up). Your hands should be about shoulder-width apart.\r\n2. Begin by pulling your elbows back and curling the barbell up along your body, dragging it against your torso.\r\n3. Continue to pull the barbell upward until it reaches chest level, keeping your elbows back and close to your body.\r\n4. Slowly lower the barbell back to the starting position, maintaining control and keeping the barbell close to your torso. Repeat for the desired number of repetitions.', E'1. Keep your elbows back to ensure the barbell stays close to your torso throughout the movement.\r\n2. Maintain a controlled pace to ensure that you''re using muscle strength rather than momentum.\r\n3. Keep your back straight and shoulders back to maintain proper posture.', '{"image_male_start":"images/Biceps/barbell drag curl.jpeg","video_url":"videos/Biceps/barbell drag curl .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6f425570-eac6-4bc3-ab2c-d92ee622bb45'::uuid, 'Barbell floor chest press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Lie on your back on the floor with your feet flat on the floor. Grip a barbell with your hands slightly wider than shoulder-width apart, and hold the barbell directly above your chest with your arms bent, elbows on the floor.\r\n2. Engage your core and slowly press the barbell up until your arms are straight over your chest.\r\n3. Lower the barbell back to the starting position by bending your arms fully, focusing on using your chest muscles.\r\n4. Repeat for the desired number of repetitions.', E'1. Lower the barbell slowly and with control to maximize muscle engagement and prevent injury.\r\n2. Ensure your elbows are at a 45-degree angle to your body to reduce shoulder strain.\r\n3. Breathe steadily, exhaling as you press the barbell up and inhaling as you lower it down.', '{"image_male_start":"images/Chest/Barbell floor chest press.jpg","image_male_end":"images/Chest/Barbell floor chest press1.jpg","image_female_start":"images/Chest/barbell floor chest press_female.jpg","image_female_end":"images/Chest/barbell floor chest press_female1.jpg","video_url":"videos/Chest/Barbell floor chest press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2112af44-aea0-4c21-9361-184d1134ea98'::uuid, 'Barbell front chest bench squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, back facing a bench, holding a barbell across your upper chest. Grip the bar with your hands shoulder-width apart, and keep your elbows pointing forward.\r\n2. Begin the squat by pushing your hips back and bending your knees, lowering your body until you sit down on the bench.\r\n3. Push through your heels to stand back up to the starting position, extending your hips and knees fully. Repeat for the desired number of repetitions.', E'1. Keep your elbows high to maintain the barbell''s position on your chest.\r\n2. Engage your core to support your lower back and maintain proper posture.\r\n3. Lower your body slowly and with control to maximize muscle engagement and prevent injury.', '{"image_male_start":"images/Legs/barbell front chest bench squat.jpg","image_male_end":"images/Legs/barbell front chest bench squat1.jpg","video_url":"videos/Legs/barbell front chest bench squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c7d21d37-b338-4acb-a3a3-f603817fbbab'::uuid, 'Barbell front chest lunges', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell across your upper chest. Grip the bar with your hands shoulder-width apart, and keep your elbows pointing forward.\r\n2. Step forward with your right leg, lowering your body until your right thigh is parallel to the floor and your left knee nearly touches the floor.\r\n3. Push through your front heel to return to the starting position. Repeat the movement with the same leg.', E'1. Keep your elbows high to maintain the barbell''s position on your chest.\r\n2. Engage your core to support your lower back and maintain proper posture.\r\n3. Lower your body slowly and with control to maximize muscle engagement and prevent injury.', '{"image_male_start":"images/Legs/barbell front chest lunges.jpg","image_male_end":"images/Legs/barbell front chest lunges1.jpg","video_url":"videos/Legs/barbell front chest lunges.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('48328845-ddae-4f06-9f5a-2c1a6221f492'::uuid, 'Barbell front chest squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell across your upper chest. Grip the bar with your hands shoulder-width apart, and keep your elbows pointing forward.\r\n2. Begin the squat by pushing your hips back and bending your knees, lowering your body until your thighs are parallel to the floor or slightly below.\r\n3. Push through your heels to return to the starting position, extending your hips and knees fully. Repeat for the desired number of repetitions.', E'1. Lower your body slowly and with control to maximize muscle engagement and prevent injury.\r\n2. Breathe steadily, exhaling as you push up and inhaling as you lower down.\r\n3. Keep your chest up and back straight throughout the movement to maintain proper alignment.', '{"image_male_start":"images/Legs/Barbell front chest squat.jpg","image_male_end":"images/Legs/Barbell front chest squat1.jpg","image_female_start":"images/Legs/barbell front chest squat_female.jpg","image_female_end":"images/Legs/barbell front chest squat_female1.jpg","video_url":"videos/Legs/Barbell front chest squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7e8a53f3-61e4-47cf-9ad2-06aa2f26e2a6'::uuid, 'Barbell front lunges with small pause', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell across your upper back. Grip the bar with your hands shoulder-width apart, and keep your elbows pointing forward.\r\n2. Step forward with your right leg, lowering your body until your right thigh is parallel to the floor and your left knee nearly touches the floor. Pause briefly in this position.\r\n3. Push through your front heel to return to the starting position. Repeat the movement with the same leg.\r\n', E'1. Pause for a second at the bottom of each lunge to enhance muscle activation and stability.\r\n2. Drive through the heel of your front foot to engage your glutes and quadriceps more effectively.\r\n3. Keep your head up and eyes forward to maintain balance and proper form.', '{"image_male_start":"images/Legs/Barbell front lunges with small pause.jpg","image_male_end":"images/Legs/Barbell front lunges with small pause1.jpg","video_url":"videos/Legs/Barbell front lunges with small pause.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1ced5f8a-3082-43ac-849a-cace8bdcebd6'::uuid, 'Barbell front raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with an overhand grip in front of your thighs. Your hands should be shoulder-width apart.\r\n2. Lift the barbell in front of you with straight arms until it reaches shoulder height.\r\n3. Lower the barbell back to the starting position with control, keeping your arms straight. Repeat for the desired number of repetitions.', E'1. Maintain a slight bend in your elbows to reduce strain on the joints.\r\n2. Lift with your shoulders rather than swinging your body to ensure proper muscle engagement.\r\n3. Keep your core tight to support your lower back and maintain proper posture.', '{"image_male_start":"images/Shoulders/Barbell front raise.jpg","image_male_end":"images/Shoulders/Barbell front raise1.jpg","video_url":"videos/Shoulders/Barbell front raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c695379f-cce9-4ac4-8bc4-cd662b09aa1c'::uuid, 'Barbell front squats', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell across your upper chest. Grip the bar with your hands shoulder-width apart, and keep your elbows pointing forward.\r\n2. Begin the squat by pushing your hips back and bending your knees, lowering your body until your thighs are parallel to the floor or slightly below.\r\n3. Push through your heels to return to the starting position, extending your hips and knees fully. Repeat for the desired number of repetitions.', E'1. Lower your body slowly and with control to maximize muscle engagement and prevent injury.\r\n2. Breathe steadily, exhaling as you push up and inhaling as you lower down.\r\n3. Keep your chest up and back straight throughout the movement to maintain proper alignment.', '{"image_male_start":"images/Legs/Barbell front squats.jpg","image_male_end":"images/Legs/Barbell front squats1.jpg","video_url":"videos/Legs/Barbell front squats.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c4be5563-ede1-4c8c-918b-fae58be5e90a'::uuid, 'Barbell full clean', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Bend at your hips and knees to grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.\r\n2. Begin the lift by pushing through your heels, extending your hips and knees to lift the barbell off the floor.\r\n3. As the barbell passes your knees, explosively extend your hips and knees, lightly jumping, while shrugging your shoulders and pulling the barbell up to your chest level. Rotate your elbows under the bar to catch it in a front squat position.\r\n4. Lower your body into a full squat with the barbell resting on your front shoulders, elbows high, and chest up. Push through your heels to stand back up, fully extending your hips and knees. Lower the barbell back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep your elbows high during the catch to maintain the barbell''s position on your shoulders.\r\n2. Engage your core to support your lower back and maintain stability throughout the movement.\r\n3. Use your legs and hips to generate power and drive the barbell up.', '{"image_male_start":"images/Powerlifting/Barbell full clean.jpg","image_male_end":"images/Powerlifting/Barbell full clean1.jpg","image_female_start":"images/Powerlifting/barbell full clean_female.jpg","image_female_end":"images/Powerlifting/barbell full clean_female1.jpg","video_url":"videos/Powerlifting/Barbell full clean.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a96a88ce-7b9c-497f-aff1-a94d063a3fa2'::uuid, 'Barbell full squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell across your upper back. Grip the bar with your hands slightly wider than shoulder-width apart.\r\n2. Begin the squat by pushing your hips back and bending your knees, lowering your body until your thighs are slightly below than parallel to the floor.\r\n3. Push through your heels to return to the starting position, extending your hips and knees fully. Repeat for the desired number of repetitions.', E'1. Keep your chest up and back straight to maintain proper posture and alignment.\r\n2. Focus on driving through your heels to engage your glutes and quadriceps effectively.\r\n3. Breathe steadily, exhaling as you stand up and inhaling as you lower down.', '{"image_male_start":"images/Powerlifting/Barbell full squat.jpg","image_male_end":"images/Powerlifting/Barbell full squat1.jpg","image_female_start":"images/Legs/Barbell Full Squat_female.jpg","image_female_end":"images/Legs/Barbell Full Squat_female1.jpg","video_url":"videos/Powerlifting/Barbell full squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('bd4504bd-4d0d-419a-a3d3-0b68f6530838'::uuid, 'Barbell full squat back POV', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell across your upper back. Grip the bar with your hands slightly wider than shoulder-width apart.\r\n2. Begin the squat by pushing your hips back and bending your knees, lowering your body until your thighs are slightly below than parallel to the floor.\r\n3. Push through your heels to return to the starting position, extending your hips and knees fully. Repeat for the desired number of repetitions.', E'1. Keep your chest up and back straight to maintain proper posture and alignment.\r\n2. Focus on driving through your heels to engage your glutes and quadriceps effectively.\r\n3. Breathe steadily, exhaling as you stand up and inhaling as you lower down.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('70a3d233-e6b6-4d93-bef7-9e51367f3c82'::uuid, 'Barbell full squat side POV', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell across your upper back. Grip the bar with your hands slightly wider than shoulder-width apart.\r\n2. Begin the squat by pushing your hips back and bending your knees, lowering your body until your thighs are slightly below than parallel to the floor.\r\n3. Push through your heels to return to the starting position, extending your hips and knees fully. Repeat for the desired number of repetitions.', E'1. Keep your chest up and back straight to maintain proper posture and alignment.\r\n2. Focus on driving through your heels to engage your glutes and quadriceps effectively.\r\n3. Breathe steadily, exhaling as you stand up and inhaling as you lower down.', '{"image_male_start":"images/Legs/barbell full squat side pov.jpg","image_male_end":"images/Legs/barbell full squat side pov1.jpg","image_female_start":"images/Legs/Barbell Full Squat Side POV_female.jpg","image_female_end":"images/Legs/Barbell Full Squat Side POV_female1.jpg","video_url":"videos/Legs/barbell full squat side pov.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f5fdcfe0-3066-41c8-b148-500edc34c564'::uuid, 'Barbell full zercher squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Position a barbell in a squat rack at about waist height. Stand close to the barbell and hook your arms under it, holding the bar in the crook of your elbows with your hands close in front of your chest.\r\n2. Lift the barbell off the rack by standing up straight. Step back and stand with your feet shoulder-width apart, toes slightly pointed out.\r\n3. Maintain a neutral spine as you begin the squat by pushing your hips back and bending your knees, lowering your body until your thighs are parallel to the floor or slightly below.\r\n4. Push through your heels to return to the starting position, extending your hips and knees until you are fully upright. Repeat for the desired number of repetitions.', E'1. Move slowly and with control to maximize muscle engagement and prevent injury.\r\n2. Breathe steadily, exhaling as you push up and inhaling as you lower down.\r\n3. Distribute your weight evenly across your feet to ensure balance and stability.', '{"image_male_start":"images/Legs/Barbell full zercher squat.jpg","image_male_end":"images/Legs/Barbell full zercher squat1.jpg","image_female_start":"images/Legs/Barbell full Zercher Squat_female.jpg","image_female_end":"images/Legs/Barbell full Zercher Squat_female1.jpg","video_url":"videos/Legs/Barbell full zercher squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('42659206-3312-4caa-8cc9-b5695ce5042c'::uuid, 'Barbell glute bridge', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Lie on your back on the floor with your knees bent and feet flat on the floor, shoulder-width apart. Place a barbell across your hips, holding it securely with both hands.\r\n2. Push through your heels to lift your hips off the floor until your body forms a straight line from your shoulders to your knees.\r\n3. Squeeze your glutes at the top of the movement and hold for a brief moment.\r\n4. Lower your hips back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Drive through your heels to engage your glutes and hamstrings effectively.\r\n2. Ensure your knees stay in line with your toes and do not flare out or cave inward.\r\n3. Breathe steadily, exhaling as you lift your hips and inhaling as you lower them back down.\r\n4. Use a pad or towel on the barbell for added comfort on your hips.', '{"image_male_start":"images/Legs/Barbell glute bridge.jpg","image_male_end":"images/Legs/Barbell glute bridge1.jpg","video_url":"videos/Legs/Barbell glute bridge.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('10d729c6-0479-42a1-aab8-277fb963ef2f'::uuid, 'Barbell good morning', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell across your upper back. Grip the bar with your hands slightly wider than shoulder-width apart.\r\n2. Slightly bend your knees and hinge at your hips to lower your torso forward. Keep your back straight and your head in line with your spine.\r\n3. Continue to lower your torso until it is nearly parallel to the floor, feeling a stretch in your hamstrings and glutes.\r\n4. Engage your glutes and hamstrings to raise your torso back to the starting position, keeping your back straight and core engaged. Repeat for the desired number of repetitions.', E'1. Maintain a neutral spine throughout the movement to prevent lower back strain.\r\n2. Engage your core to support your lower back and maintain stability.\r\n3. Hinge at your hips rather than bending your back to ensure proper form.', '{"image_male_start":"images/Back/Barbell Good Morning.jpg","image_male_end":"images/Back/Barbell Good Morning1.jpg","video_url":"videos/Back/Barbell Good Morning.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b35d8afd-c98c-4fdf-821f-73492dc84570'::uuid, 'Barbell hip thrust', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Sit on the floor with your upper back resting against a bench, knees bent, and feet flat on the floor. Roll a barbell over your hips, holding it securely with both hands.\r\n2. Push through your heels to lift your hips off the floor until your body forms a straight line from your shoulders to your knees.\r\n3. Squeeze your glutes at the top of the movement and hold for a brief moment, ensuring your hips are fully extended.\r\n4. Lower your hips back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Drive through your heels to engage your glutes and hamstrings effectively.\r\n2. Ensure your knees stay in line with your toes and do not flare out or cave inward.\r\n3. Breathe steadily, exhaling as you lift your hips and inhaling as you lower them back down.\r\n4. Use a pad or towel on the barbell for added comfort on your hips.', '{"image_male_start":"images/Legs/Barbell Hip Thrust  .jpg","video_url":"videos/Legs/Barbell Hip Thrust  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5bcabbfe-a7fa-435b-a162-eeb3f6e9df11'::uuid, 'Barbell incline bench press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Lie on an incline bench set at a 45 degree angle. Grip the barbell with your hands slightly wider than shoulder-width apart, and hold the barbell directly above your chest with your arms fully extended.\r\n2. Slowly lower the barbell to your upper chest, keeping your elbows at a 45-degree angle to your body.\r\n3. Press the barbell back up to the starting position by extending your arms fully, focusing on using your chest.\r\n4. Repeat for the desired number of repetitions, then carefully rack the barbell back onto the bench press rack.', E'1. Breathe steadily, exhaling as you press the barbell up and inhaling as you lower it down.\r\n2. Maintain a firm grip on the barbell to ensure control and proper alignment.\r\n3. Use a spotter if lifting heavy weights to ensure safety.', '{"image_male_start":"images/Chest/Barbell incline bench press.jpg","image_male_end":"images/Chest/Barbell incline bench press1.jpg","video_url":"videos/Chest/Barbell incline bench press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('51012365-167b-41cd-bbcc-893ff158921e'::uuid, 'Barbell jefferson split squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with a barbell positioned between your legs, gripping it with both hands. Position your feet in a split position, one foot forward and one back.\r\n2. Lower your hips by bending both knees until your back knee is just above the ground and your front thigh is nearly parallel to the floor.\r\n3. Push through the heel of your front foot to return to the starting position.\r\n4. Repeat for the desired repetitions, switch legs, and repeat.', E'1. Maintain a firm grip on the barbell and ensure it stays centered beneath your body.\r\n2. Keep your torso upright and avoid leaning forward during the descent.\r\n3. Do not allow your front knee to travel excessively past your toes.', '{"image_male_start":"images/Legs/Barbell jefferson split squat.jpg","image_male_end":"images/Legs/Barbell jefferson split squat1.jpg","video_url":"videos/Legs/Barbell jefferson split squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('91185f06-3368-426a-b585-9eb511cc313f'::uuid, 'Barbell jefferson squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, positioning yourself so that the barbell is between your legs. Grip the barbell with one hand in front of you and one hand behind you, using an overhand grip for the front hand and an underhand grip for the back hand.\r\n2. Begin the squat by pushing your hips back and bending your knees, lowering your body until your thighs are parallel to the floor.\r\n3. Push through your heels to return to the starting position, extending your hips and knees fully. Repeat for the desired number of repetitions.', E'1. Focus on even weight distribution between both legs to ensure balanced muscle activation.\r\n2. Use your glutes and hamstrings to power the upward phase of the squat.\r\n3. Keep your grip firm but relaxed to prevent unnecessary tension in your arms and shoulders.', '{"image_male_start":"images/Legs/Barbell jefferson squat.jpg","image_male_end":"images/Legs/Barbell jefferson squat1.jpg","image_female_start":"images/Legs/Barbell Jefferson Squat_female.jpg","image_female_end":"images/Legs/Barbell Jefferson Squat_female1.jpg","video_url":"videos/Legs/Barbell jefferson squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('023cb9e4-d808-40ba-890c-91daa06c4cea'::uuid, 'Barbell JM bench press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Lie on a flat bench with your feet flat on the floor, holding a barbell with your hands shoulder-width apart. Your arms should be fully extended above your chest.\r\n2. Lower the barbell by bending your elbows and bringing it down towards your chest. \r\n3. When the barbell is just above your chest, move it toward your head and stop when the barbell is just overhead and move it back to above the chest. \r\n4. Push it back up to the starting position by extending your elbows, focusing on using your triceps. Repeat for the desired number of repetitions, then carefully rack the barbell back onto the bench press rack.', E'1. Focus on the triceps by keeping your elbows slightly tucked in and not flaring out too much.\r\n2. Lower the barbell slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Maintain a strong grip on the barbell to ensure control and proper alignment.\r\n', '{"image_male_start":"images/Chest/Barbell JM bench press.jpg","image_male_end":"images/Chest/Barbell JM bench press1.jpg","video_url":"videos/Chest/Barbell JM bench press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('cfa111a4-ee64-4835-b7b6-9e116dee1e6b'::uuid, 'Barbell jump squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell across your upper back. Grip the bar with your hands slightly wider than shoulder-width apart.\r\n2. Begin the squat by pushing your hips back and bending your knees, lowering your body until your thighs are parallel to the floor.\r\n3. Explosively push through your heels to jump straight up, extending your hips and knees fully to jump.\r\n4. Land softly on your forefeet, immediately bending your knees and hips to absorb the impact and lower back into the squat position. Repeat for the desired number of repetitions.', E'1. Ensure the barbell remains steady on your back to prevent it from shifting during the exercise.\r\n2. Keep your knees aligned with your toes to avoid knee injuries.\r\n3. Start with a lighter weight to master the form and technique before progressing to heavier loads.', '{"image_male_start":"images/Legs/Barbell jump squat.jpg","image_male_end":"images/Legs/Barbell jump squat1.jpg","image_female_start":"images/Legs/Barbell Jump Squat_female.jpg","image_female_end":"images/Legs/Barbell Jump Squat_female1.jpg","video_url":"videos/Legs/Barbell jump squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('27f2e0db-5497-48b8-9bda-bef6d1850b78'::uuid, 'Barbell KAS glute bridge', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Sit on the floor with your upper back resting against a box, knees bent, and feet flat on the floor. Place a barbell across your hips, holding it securely with both hands.\r\n2. Push through your heels to lift your hips off the floor until your body forms a straight line from your shoulders to your knees. Your upper back should remain on the bench.\r\n3. Squeeze your glutes at the top of the movement and hold for a brief moment, ensuring your hips are fully extended.\r\n4. Lower your hips back to the starting position with control, stopping just before your glutes touch the floor. Repeat for the desired number of repetitions.', E'1. Drive through your heels to engage your glutes and hamstrings effectively.\r\n2. Ensure your knees stay in line with your toes and do not flare out or cave inward.\r\n3. Breathe steadily, exhaling as you lift your hips and inhaling as you lower them back down.\r\n4. Use a pad or towel on the barbell for added comfort on your hips.', '{"image_male_start":"images/Legs/Barbell KAS glute bridge.jpg","image_male_end":"images/Legs/Barbell KAS glute bridge1.jpg","image_female_start":"images/Legs/Barbell KAS Glute Bridge_female.jpg","image_female_end":"images/Legs/Barbell KAS Glute Bridge_female1.jpg","video_url":"videos/Legs/Barbell KAS glute bridge.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a88451ea-574d-4bd8-b271-f1d5303b7234'::uuid, 'Barbell kneeling squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Start by kneeling on a mat with your knees hip-width apart. Hold a barbell across your upper back, gripping it with your hands slightly wider than shoulder-width apart.\r\n2. Sit back onto your heels, lowering your glutes towards your calves.\r\n3. Push your hips forward to return to the starting position, extending your hips fully and squeezing your glutes at the top.\r\n4. Repeat for the desired number of repetitions, maintaining control throughout the movement.', E'1. Move through a full range of motion to maximize muscle engagement and benefit.\r\n2. Control your breathing, exhaling as you push your hips forward and inhaling as you sit back.\r\n3. Use a mat or padding under your knees for added comfort during the exercise.', '{"image_male_start":"images/Legs/barbell kneeling squat.jpg","image_male_end":"images/Legs/barbell kneeling squat1.jpg","video_url":"videos/Legs/barbell kneeling squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('50922124-cd5a-4c06-9641-b42bcc233fc4'::uuid, 'Barbell lap curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Sit on a bench with your feet flat on the floor, holding a barbell with palms facing up, shoulder-width apart. Rest the bar on your thighs, just above your knees.\r\n2. Begin the curl by bending your elbows and lifting the barbell towards your chest, keeping your upper arms stationary against your sides.\r\n3. Squeeze your biceps at the top of the movement, ensuring the barbell reaches close to your chest.\r\n4. Lower the barbell back to your thighs with control. Just before touching your thighs, repeat the curl.', E'1. Keep your elbows fixed on your thighs to isolate your biceps effectively.\r\n2. Avoid using momentum by performing the movement slowly and with control.\r\n3. Use a weight that allows for proper form to prevent strain or injury.', '{"image_male_start":"images/Biceps/barbell lap curl.jpeg","video_url":"videos/Biceps/barbell lap curl .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9c97c4d6-ac4b-42a3-876a-654d6a4e5403'::uuid, 'Barbell Lateral Lunge', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell across your upper back. Grip the bar with your hands slightly wider than shoulder-width apart.\r\n2. Step out to the right with your right foot, lowering your body into a lunge position by bending your right knee and pushing your hips back.\r\n3. Push through your right heel to return to the starting position. Repeat the movement on the left side, continuing to alternate legs for the desired number of repetitions.', E'1. Focus on a controlled descent to maximize muscle engagement and prevent injury.\r\n2. Keep your chest up and back straight throughout the movement to maintain proper posture.\r\n3. Ensure your knee does not extend beyond your toes to avoid placing undue stress on the joint.', '{"image_male_start":"images/Legs/Barbell Lateral Lunge_female.jpg","image_female_start":"images/Legs/Barbell Lateral Lunge_female.jpg","image_female_end":"images/Legs/Barbell Lateral Lunge_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2fa69e19-d68f-41b3-a84e-6f171711d7ea'::uuid, 'Barbell lateral lunges', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell across your upper back. Grip the bar with your hands slightly wider than shoulder-width apart.\r\n2. Step out to the right with your right foot, lowering your body into a lunge position by bending your right knee and pushing your hips back.\r\n3. Push through your right heel to return to the starting position. Repeat the movement on the left side, continuing to alternate legs for the desired number of repetitions.', E'1. Focus on a controlled descent to maximize muscle engagement and prevent injury.\r\n2. Keep your chest up and back straight throughout the movement to maintain proper posture.\r\n3. Ensure your knee does not extend beyond your toes to avoid placing undue stress on the joint.', '{"image_male_start":"images/Legs/Barbell lateral lunges.jpg","image_male_end":"images/Legs/Barbell lateral lunges1.jpg","video_url":"videos/Legs/Barbell lateral lunges.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a2df4983-389c-4708-a873-81b698c01860'::uuid, 'Barbell Long Landmine Row', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Set up a barbell in a landmine attachment or securely place one end of the barbell in a corner. Stand to the side of the barbell with your feet shoulder-width apart, barbell extending behind. Bend at the hips and knees, keeping your back straight, and grip the barbell with your hand.\r\n2. Start with your arm fully extended, allowing the barbell to hang straight down.\r\n3. Pull the barbell towards your side by bending your elbow and squeezing your back at the peak of the movement.\r\n4. Slowly lower the barbell back to the starting position, fully extending your arm. Repeat the movement for the desired repetitions.', E'1. Maintain a neutral spine throughout the exercise to avoid straining your lower back.\r\n2. Engage your core to help stabilize your body and prevent unnecessary movement.\r\n3. Use a controlled motion to lift and lower the barbell, preventing any jerking movements.', '{"image_male_start":"images/Back/Barbell Long Landmine Row.jpg","image_male_end":"images/Back/Barbell Long Landmine Row1.jpg","video_url":"videos/Back/Barbell Long Landmine Row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4c3a4bc0-1cdf-4adc-ba10-8128f19b69ee'::uuid, 'Barbell low bar squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell across your upper back, positioned lower on your traps and rear deltoids. Grip the bar with your hands slightly wider than shoulder-width apart, ensuring a secure hold.\r\n2. Begin the squat by pushing your hips back and bending your knees, lowering your body until your thighs are parallel to the floor.\r\n3. Push through your heels to return to the starting position, extending your hips and knees fully. Repeat for the desired number of repetitions.', E'1. Distribute your weight evenly across your feet to maintain balance and stability.\r\n2. Ensure a tight grip on the barbell to prevent it from shifting during the exercise.\r\n3. Keep your gaze forward to help maintain proper alignment and focus throughout the movement.', '{"image_male_start":"images/Legs/Barbell low bar squat.jpg","image_male_end":"images/Legs/Barbell low bar squat1.jpg","image_female_start":"images/Legs/Barbell Low Bar Squat_female.jpg","image_female_end":"images/Legs/Barbell Low Bar Squat_female1.jpg","video_url":"videos/Legs/Barbell low bar squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('eb615a28-ad20-4a9e-97f1-4e3b266fb04f'::uuid, 'Barbell Lunge', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell across your upper back. Grip the bar with your hands shoulder-width apart, and keep your elbows pointing forward.\r\n2. Step forward with your right leg, lowering your body until your right thigh is parallel to the floor and your left knee nearly touches the floor.\r\n3. Push through your front heel to return to the starting position. Repeat the movement with the same leg.\r\n', E'1. Use a weight that allows for proper form and technique throughout the exercise.\r\n2. Drive through the heel of your front foot to engage your glutes and quadriceps more effectively.\r\n3. Keep your head up and eyes forward to maintain balance and proper form.', '{"image_male_start":"images/Legs/Barbell Lunge_female.jpg","image_female_start":"images/Legs/Barbell Lunge_female.jpg","image_female_end":"images/Legs/Barbell Lunge_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3fd6b59f-89ac-4d6e-b6d2-a5e88201a402'::uuid, 'Barbell lunges', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell across your upper back. Grip the bar with your hands shoulder-width apart, and keep your elbows pointing forward.\r\n2. Step forward with your right leg, lowering your body until your right thigh is parallel to the floor and your left knee nearly touches the floor.\r\n3. Push through your front heel to return to the starting position. Repeat the movement with the same leg.\r\n', E'1. Use a weight that allows for proper form and technique throughout the exercise.\r\n2. Drive through the heel of your front foot to engage your glutes and quadriceps more effectively.\r\n3. Keep your head up and eyes forward to maintain balance and proper form.', '{"image_male_start":"images/Legs/Barbell lunges.jpg","image_male_end":"images/Legs/Barbell lunges1.jpg","video_url":"videos/Legs/Barbell lunges.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('abf1f9c1-ea11-48ca-ae28-eadc8bee3f7f'::uuid, 'Barbell lunges on the spot', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell across your upper back. Grip the bar with your hands shoulder-width apart, and keep your elbows pointing forward.\r\n2. Step forward with your right leg, lowering your body until your right thigh is parallel to the floor and your left knee nearly touches the floor.\r\n3. Push through your front heel to return to the starting position. Repeat the movement with the same leg.\r\n', E'1. Use a weight that allows for proper form and technique throughout the exercise.\r\n2. Drive through the heel of your front foot to engage your glutes and quadriceps more effectively.\r\n3. Keep your head up and eyes forward to maintain balance and proper form.', '{"image_male_start":"images/Legs/barbell lunges on the spot  .jpg","video_url":"videos/Legs/barbell lunges on the spot  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9c772c81-a598-4740-97db-533f05a7e2d0'::uuid, 'Barbell lying row', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Lie face down on a flat bench, holding a barbell with an overhand grip (palms facing down), hands placed shoulder-width apart. Your chest should be supported by the bench, and your feet should be firmly on the floor.\r\n2. Let the barbell hang directly below you with your arms fully extended. Pull the barbell towards your lower chest by bending your elbows and squeezing your shoulder blades together.\r\n3.  Slowly lower the barbell back to the starting position by extending your arms fully. Repeat for the desired number of repetitions.\r\n', E'1. Keep your back flat and avoid rounding your shoulders or lower back.\r\n2. Squeeze your shoulder blades together at the top of the movement to maximize upper back engagement.\r\n3. Use a weight that allows for proper form and control throughout the exercise to prevent injury.', '{"image_male_start":"images/Back/Barbell Lying Row.jpg","image_male_end":"images/Back/Barbell Lying Row1.jpg","video_url":"videos/Back/Barbell Lying Row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4e6a8f63-0c2a-41b4-9df3-5c76db69ec53'::uuid, 'Barbell lying triceps extension', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Lie on a flat bench with your feet flat on the floor, holding a barbell with an overhand grip, hands shoulder-width apart. Your arms should be fully extended above your chest.\r\n2. Slowly lower the barbell by bending your elbows, bringing the barbell towards over your forehead.\r\n3. When the barbell is behind your head, reverse the movement by extending your elbows to return the barbell to the starting position.\r\n4. Repeat for the desired number of repetitions, then carefully rack the barbell back onto the bench press rack.', E'1. Keep your upper arms stationary and only move your forearms to isolate the triceps.\r\n2. Lower the barbell slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Ensure a firm grip on the barbell to maintain control and proper alignment throughout the movement.\r\n', '{"image_male_start":"images/Triceps/Barbell lying triceps extension.jpeg","video_url":"videos/Triceps/Barbell lying triceps extension.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ee3ed478-5bf7-425a-aca5-c52b681286ed'::uuid, 'barbell lying triceps skull crusher', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Lie on a flat bench with your feet flat on the floor, holding a barbell with an overhand grip, hands shoulder-width apart. Your arms should be fully extended above your chest.\r\n2. Slowly lower the barbell by bending your elbows, bringing the barbell towards your forehead.\r\n3. When the barbell is just above your forehead, reverse the movement by extending your elbows to return the barbell to the starting position.\r\n4. Repeat for the desired number of repetitions, then carefully rack the barbell back onto the bench press rack.', E'1. Keep your upper arms stationary and only move your forearms to isolate the triceps.\r\n2. Lower the barbell slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Ensure a firm grip on the barbell to maintain control and proper alignment throughout the movement.\r\n', '{"image_male_start":"images/Triceps/barbell lying triceps skull crusher_female.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('97253a3d-0d73-4a67-ba53-12ab7bb0dd5f'::uuid, 'Barbell lying triceps skull crushers', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Lie on a flat bench with your feet flat on the floor, holding a barbell with an overhand grip, hands shoulder-width apart. Your arms should be fully extended above your chest.\r\n2. Slowly lower the barbell by bending your elbows, bringing the barbell towards your forehead.\r\n3. When the barbell is just above your forehead, reverse the movement by extending your elbows to return the barbell to the starting position.\r\n4. Repeat for the desired number of repetitions, then carefully rack the barbell back onto the bench press rack.', E'1. Keep your upper arms stationary and only move your forearms to isolate the triceps.\r\n2. Lower the barbell slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Ensure a firm grip on the barbell to maintain control and proper alignment throughout the movement.\r\n', '{"image_male_start":"images/Triceps/Barbell lying triceps skull crushers.jpeg","video_url":"videos/Triceps/Barbell lying triceps skull crushers.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e710aaaa-4eed-4275-bcd9-d94ea3489ff8'::uuid, 'Barbell Meadows Row', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Set up a barbell in a landmine attachment or securely place one end of the barbell in a corner. Stand perpendicular to the barbell with your feet shoulder-width apart. Bend at the hips and knees, keeping your back straight, and grip the barbell with your hand.\r\n2. Start with your working arm fully extended, allowing the barbell to hang straight down.\r\n3. Pull the barbell towards your lower ribs by bending your elbow and squeezing your back at the peak of the movement.\r\n4. Slowly lower the barbell back to the starting position, fully extending your arm. Repeat the movement for the desired repetitions.', E'1. Squeeze your shoulder blade at the top of the movement to enhance muscle activation.\r\n2. Adjust the weight on the barbell to challenge your muscles without compromising your form.\r\n3. Ensure the landmine setup is secure to prevent slipping or tipping.', '{"image_male_start":"images/Back/Barbell Meadows Row.jpg","image_male_end":"images/Back/Barbell Meadows Row1.jpg","video_url":"videos/Back/Barbell Meadows Row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a34353ff-5df9-4b3c-923b-6b1f02f33bff'::uuid, 'Barbell muscle clean', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Begin in a squatted position with your feet hip-width apart, holding a barbell with an overhand grip (palms facing your body), hands slightly wider than shoulder-width apart. The barbell should be resting on the floor.\r\n2. Explosively extend your hips and knees while pulling the barbell up towards your chest, keeping it close to your body. As the barbell passes your knees, shrug your shoulders and continue to pull the barbell upward.\r\n3. Quickly rotate your elbows under the bar and catch it in a front rack position with your elbows pointing forward. Stand up straight to complete the lift.\r\n4. Lower the barbell back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep the barbell close to your body to ensure an efficient and powerful lift.\r\n2. Focus on an explosive hip extension to generate the necessary force for the clean.\r\n3. Engage your shoulders and traps during the shrug to assist in lifting the barbell.\r\n4. Use your legs and hips rather than relying solely on your arms to lift the barbell.', '{"image_male_start":"images/Powerlifting/Barbell muscle clean.jpg","image_male_end":"images/Powerlifting/Barbell muscle clean1.jpg","image_female_start":"images/Powerlifting/barbell muscle clean_female.jpg","image_female_end":"images/Powerlifting/barbell muscle clean_female1.jpg","video_url":"videos/Powerlifting/Barbell muscle clean.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7a06fcf7-2b55-458b-b883-bafb79e2698f'::uuid, 'barbell narrow stance full squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet at about hip-width apart, holding a barbell across your upper back with an overhand grip. Keep your elbows pointing downward and your chest up.\r\n2. Engage your core and maintain a neutral spine. Begin the squat by pushing your hips back and bending your knees, lowering your body as if sitting on an invisible chair.\r\n3. Continue lowering until your thighs are parallel to the floor while maintaining good form.\r\n4. Push through your heels to return to the starting position, extending your hips and knees fully. Repeat for the desired number of repetitions.', E'1. Use a weight that provides enough resistance to challenge your muscles without compromising form.\r\n2. Focus on engaging your quadriceps and glutes throughout the movement.\r\n3. Keep your chest up and avoid leaning forward excessively.', '{"image_male_start":"images/Legs/barbell narrow stance full squat_female.jpg","image_female_start":"images/Legs/barbell narrow stance full squat_female.jpg","image_female_end":"images/Legs/barbell narrow stance full squat_female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e6c7551a-fbad-4037-b676-f57f52d5c6c1'::uuid, 'Barbell narrow stance squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet closer than shoulder-width apart, holding a barbell across your upper back. Grip the bar with your hands slightly wider than shoulder-width apart.\r\n2. Begin the squat by pushing your hips back and bending your knees, lowering your body until your thighs are parallel to the floor or slightly below.\r\n3. Push through your heels to return to the starting position, extending your hips and knees fully. Repeat for the desired number of repetitions.', E'1. Lower your body with control to maximize muscle engagement and prevent injury.\r\n2. Focus on driving through your heels to engage your glutes and quadriceps effectively.\r\n3. Keep your chest up and shoulders back to maintain proper posture throughout the movement.', '{"image_male_start":"images/Legs/Barbell narrow stance squat.jpg","image_male_end":"images/Legs/Barbell narrow stance squat1.jpg","video_url":"videos/Legs/Barbell narrow stance squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5eb5914c-3c90-4a74-921f-5ea173dbb81e'::uuid, 'Barbell one arm single deadlift', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet hip-width apart, holding a barbell with one hand using an overhand grip (palms facing your body). The barbell should be placed to the side of your body.\r\n2. Begin the movement by hinging at your hips and slightly bending your knees, lowering the barbell towards the floor while keeping it close to your body.\r\n3. Lower the barbell until before it touches the floor. Push through your heel to return to the starting position, extending your hips and knees fully while keeping your back straight. \r\n4. Repeat for the desired number of repetitions, then switch to the other arm.', E'1. Keep the barbell close to your body to ensure an efficient and powerful lift.\r\n2. Ensure your shoulders remain square to avoid twisting your torso and maintain proper alignment.\r\n3. Use a weight that allows for proper form and control throughout the exercise to prevent strain or injury.', '{"image_male_start":"images/Back/barbell one arm single deadlift.jpg","image_male_end":"images/Back/barbell one arm single deadlift1.jpg","video_url":"videos/Back/barbell one arm single deadlift.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c60be76d-53ad-42b7-b0af-9171d5acffa8'::uuid, 'Barbell one leg hip thrust', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Sit on the floor with your upper back resting against a bench, knees bent, and feet flat on the floor. Place a barbell across your hips, holding it securely with both hands. Lift one leg off the floor, extending it bent out in front of you.\r\n2. Push through the heel of the foot that remains on the floor to lift your hips off the floor until your body forms a straight line from your shoulders to your extended leg.\r\n3. Squeeze your glutes at the top of the movement and hold for a brief moment, ensuring your hips are fully extended.\r\n4. Lower your hips back to the starting position with control, stopping just before your glutes touch the floor. Repeat for the desired number of repetitions, then switch to the other leg.', E'1. Drive through your heel to engage your glutes and hamstrings effectively.\r\n2. Focus on the squeeze at the top to maximize glute activation.\r\n3. Use a pad or towel on the barbell for added comfort on your hips.', '{"image_male_start":"images/Legs/barbell one leg hip thrust.jpg","image_male_end":"images/Legs/barbell one leg hip thrust1.jpg","video_url":"videos/Legs/barbell one leg hip thrust.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f45a41e9-ee95-4779-9693-19508f74f589'::uuid, 'Barbell overhead lunges', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell overhead with both hands, using a grip slightly wider than shoulder-width. Keep your arms fully extended and your core engaged.\r\n2. Step forward with your right foot, lowering your body into a lunge position by bending both knees. Your back knee should hover just above the floor, and your front thigh should be parallel to the floor.\r\n3. Push through your front heel to return to the starting position. Repeat the movement with your left leg, continuing to alternate legs for the desired number of repetitions.', E'1. Keep your arms fully extended and your shoulders engaged to maintain control of the barbell.\r\n2. Focus on a controlled descent to maximize muscle engagement and prevent injury.\r\n3. Ensure your front knee does not extend beyond your toes to avoid placing undue stress on the knee joint.', '{"image_male_start":"images/Legs/Barbell overhead lunges.jpg","image_male_end":"images/Legs/Barbell overhead lunges1.jpg","video_url":"videos/Legs/Barbell overhead lunges.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('037923f0-884d-4654-83d7-07ac62c5bc0e'::uuid, 'Barbell overhead shrug', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell overhead with both hands, using a grip slightly wider than shoulder-width. Keep your arms fully extended and your core engaged.\r\n2. Raise your shoulders towards your ears in a shrugging motion while keeping your arms extended and the barbell stable overhead.\r\n3. Hold the shrugged position briefly, squeezing your trapezius muscles.\r\n4. Lower your shoulders back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep your arms fully extended and your shoulders engaged to maintain control of the barbell.\r\n2. Focus on the upward shrugging motion to maximize trapezius activation.\r\n3. Use a weight that allows for proper form and control throughout the exercise to prevent strain or injury.', '{"image_male_start":"images/Shoulders/Barbell overhead shrug.jpg","image_male_end":"images/Shoulders/Barbell overhead shrug1.jpg","video_url":"videos/Shoulders/Barbell overhead shrug.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('85e3640d-96c1-4a26-9395-7a581787a8df'::uuid, 'Barbell overhead squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell overhead with both hands, using a grip slightly wider than shoulder-width. Keep your arms fully extended and your core engaged.\r\n2. Begin the squat by pushing your hips back and bending your knees, lowering your body until your thighs are parallel to the floor.\r\n3. Push through your heels to return to the starting position, extending your hips and knees fully while keeping the barbell overhead. Repeat for the desired number of repetitions.', E'1. Keep your arms fully extended and your shoulders engaged to maintain control of the barbell.\r\n2. Focus on a controlled descent to maximize muscle engagement and prevent injury.\r\n3. Ensure your knees do not extend beyond your toes to avoid placing undue stress on the knee joints.', '{"image_male_start":"images/Legs/Barbell overhead squat.jpg","image_male_end":"images/Legs/Barbell overhead squat1.jpg","image_female_start":"images/Legs/barbell overhead squat_female.jpg","image_female_end":"images/Legs/barbell overhead squat_female1.jpg","video_url":"videos/Legs/Barbell overhead squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('02d64d79-ff83-466d-81f3-4ff52eebb100'::uuid, 'Barbell pendlay row', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet hip-width apart, holding a barbell with an overhand grip (palms facing down), hands slightly wider than shoulder-width apart. Bend at the hips and knees to lower your torso until it is parallel to the floor.\r\n2. Begin the row by pulling the barbell towards your abdomen, driving your elbows up and back.\r\n3. Squeeze your shoulder blades together at the top of the movement, ensuring the barbell lightly touches your abdomen.\r\n4. Lower the barbell back to the floor with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Keep your back flat and avoid rounding your shoulders to ensure proper form.\r\n2. Focus on squeezing your shoulder blades together at the top of the movement to maximize back muscle activation.\r\n3. Use a weight that allows for proper form and control throughout the exercise to prevent strain or injury.', '{"image_male_start":"images/Back/Barbell pendlay row.jpg","image_male_end":"images/Back/Barbell pendlay row1.jpg","video_url":"videos/Back/Barbell pendlay row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1aa8a15f-8f48-4eb4-bafb-fbadb4e157e9'::uuid, 'Barbell power clean', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Begin in a squatted position with your feet hip-width apart, holding a barbell with an overhand grip (palms facing your body), hands slightly wider than shoulder-width apart. The barbell should be resting on the floor.\r\n2. Explosively extend your hips and knees while pulling the barbell up towards your chest, keeping it close to your body. As the barbell passes your knees, shrug your shoulders and continue to pull the barbell upward.\r\n3. Quickly rotate your elbows under the bar and catch it in a front rack position with your elbows pointing forward. Stand up straight to complete the lift.\r\n4. Lower the barbell back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Focus on an explosive hip extension to generate the necessary force for the clean.\r\n2. Engage your shoulders and traps during the shrug to assist in lifting the barbell.\r\n3. Use your legs and hips rather than relying solely on your arms to lift the barbell.\r\n4. Practice the movement with lighter weights to perfect your form before progressing to heavier loads.', '{"image_male_start":"images/Powerlifting/Barbell power clean.jpg","image_male_end":"images/Powerlifting/Barbell power clean1.jpg","video_url":"videos/Powerlifting/Barbell power clean.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9af55c0f-99da-467b-94a1-d23d5c4c331d'::uuid, 'Barbell power clean from blocks', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Position the barbell on blocks set just below knee height. Stand with your feet hip-width apart, holding the barbell with an overhand grip (palms facing your body), hands slightly wider than shoulder-width apart.\r\n2. Begin the lift by explosively extending your hips and knees while pulling the barbell up towards your chest, keeping it close to your body. As the barbell passes your knees, shrug your shoulders and continue to pull the barbell upward.\r\n3. Quickly rotate your elbows under the bar and catch it in a front rack position with your elbows pointing forward. Stand up straight to complete the lift.\r\n4. Lower the barbell back to the blocks with control. Repeat for the desired number of repetitions.', E'1. Focus on an explosive hip extension to generate the necessary force for the clean.\r\n2. Engage your shoulders and traps during the shrug to assist in lifting the barbell.\r\n3. Use your legs and hips rather than relying solely on your arms to lift the barbell.\r\n4. Practice the movement with lighter weights to perfect your form before progressing to heavier loads.', '{"image_male_start":"images/Powerlifting/Barbell power clean from blocks.jpg","image_male_end":"images/Powerlifting/Barbell power clean from blocks1.jpg","video_url":"videos/Powerlifting/Barbell power clean from blocks.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2cff919d-2718-4cda-b1cd-e62b71c142e6'::uuid, 'Barbell power jerk', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell at shoulder height with an overhand grip, hands slightly wider than shoulder-width apart. The barbell should rest on your front deltoids and clavicles.\r\n2. Slightly bend your knees to dip into a quarter squat position while keeping your chest up and maintaining a neutral spine.\r\n3. Explosively extend your hips, knees, and ankles to drive the barbell overhead.\r\n4. Stand up fully to complete the lift. Lower the barbell back to shoulder height with control. Repeat for the desired number of repetitions.', E'1. Keep your chest up and shoulders engaged to maintain proper posture and control of the barbell.\r\n2. Practice the movement with lighter weights to perfect your form before progressing to heavier loads.\r\n3. Use a slight dip to generate power for the overhead push, ensuring your movement is quick and controlled.', '{"image_male_start":"images/Powerlifting/Barbell power jerk.jpg","image_male_end":"images/Powerlifting/Barbell power jerk1.jpg","video_url":"videos/Powerlifting/Barbell power jerk.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('43b60c7f-bbdf-4748-9c3f-3fdd3458a797'::uuid, 'Barbell power snatch', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Begin in a squatted position with your feet hip-width apart, holding a barbell with a wide grip (palms facing your body), hands wider than shoulder-width apart. The barbell should be resting on the floor.\r\n2. Explosively extend your hips and knees while pulling the barbell up towards your chest, keeping it close to your body. As the barbell passes your knees, shrug your shoulders and continue to pull the barbell upward.\r\n3. Quickly rotate your elbows under the bar and catch it in a wide overhead position with your elbows fully extended and your body in a partial squat. Stand up straight to complete the lift.\r\n4. Lower the barbell back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Focus on an explosive hip extension to generate the necessary force for the snatch.\r\n2. Engage your shoulders and traps during the shrug to assist in lifting the barbell.\r\n3. Use your legs and hips rather than relying solely on your arms to lift the barbell.\r\n', '{"image_male_start":"images/Powerlifting/Barbell power snatch.jpg","image_male_end":"images/Powerlifting/Barbell power snatch1.jpg","video_url":"videos/Powerlifting/Barbell power snatch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('cc20be4c-bd08-4720-becc-c6940891bbf0'::uuid, 'Barbell preacher curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Sit on a preacher bench with your feet flat on the floor. Position your upper arms on the preacher pad, holding a barbell with an underhand grip (palms facing up), hands shoulder-width apart. Your arms should be fully extended.\r\n2. Engage your core and keep your back straight. Curl the barbell upwards towards your shoulders by bending your elbows.\r\n3. Squeeze your biceps at the top of the movement, ensuring the barbell reaches shoulder height.\r\n4. Lower the barbell back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Keep your upper arms stationary on the preacher pad to isolate the biceps.\r\n2. Perform the movement slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Breathe steadily, exhaling as you curl the barbell up and inhaling as you lower it back down.', '{"image_male_start":"images/Biceps/Barbell preacher curl.jpeg","video_url":"videos/Biceps/Barbell preacher curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('fc4d75e6-829e-47a1-b835-d8b4b5076c97'::uuid, 'Barbell pullover to triceps extension', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Lie on a flat bench with your feet flat on the floor. Hold a barbell with an overhand grip (palms facing the barbell), hands slightly wider than shoulder-width apart. Extend your arms so the barbell is directly above your chest.\r\n2. Bend your elbows and lower the barbell in an arc motion behind your head. Lower the barbell until you feel a stretch in your chest and lats.\r\n3. Reverse the motion by pulling the barbell back over your chest, then extend the barbell straight up by extending your arms fully.\r\n4. Repeat for the desired number of repetitions.', E'1. Breathe steadily, inhaling as you lower the barbell and exhaling as you press it back up.\r\n2. Use a weight that allows for proper form and control throughout the exercise to prevent strain or injury.\r\n3. Ensure a firm grip on the barbell to maintain control and proper alignment.', '{"video_url":"videos/Chest/Barbell pullover to triceps extension.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ca1fe691-68fc-407c-8d58-4ce8e50633bf'::uuid, 'Barbell push bent over row', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with palms facing the barbell, hands slightly wider than shoulder-width apart. Bend at the hips and knees to lower your torso until it is nearly parallel to the floor.\r\n2. Pull the barbell towards your abdomen by bending your elbows and squeezing your shoulder blades together. At the peak of the movement, perform a small push of the barbell downwards and pull it up again.\r\n3. Lower the barbell back to the starting position with control, extending your arms fully while keeping your back straight.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep your back flat and avoid rounding your shoulders to ensure proper form.\r\n2. Focus on squeezing your shoulder blades together at the top of the movement to maximize back muscle activation.\r\n3. Use a weight that allows for proper form and control throughout the exercise to prevent strain or injury.', '{"image_male_start":"images/Back/Barbell push bent over row.jpg","image_male_end":"images/Back/Barbell push bent over row1.jpg","video_url":"videos/Back/Barbell push bent over row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1e86de92-68d3-401b-96d0-5c760bcd5fc0'::uuid, 'Barbell quarter squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell across your upper back. Grip the bar with your hands slightly wider than shoulder-width apart.\r\n2. Begin the squat by pushing your hips back and bending your knees, lowering your body into a quarter squat position where your thighs are above parallel to the floor.\r\n3. Push through your heels to return to the starting position, extending your hips and knees fully. Repeat for the desired number of repetitions.', E'1. Keep your knees aligned with your toes to avoid unnecessary strain on your joints.\r\n2. Lower your body with control to maximize muscle engagement and prevent injury.\r\n3. Focus on driving through your heels to engage your glutes and quadriceps effectively.', '{"image_male_start":"images/Legs/Barbell quarter squat.jpg","image_male_end":"images/Legs/Barbell quarter squat1.jpg","video_url":"videos/Legs/Barbell quarter squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('570e747c-0849-419a-8d0d-b798bacfb6ef'::uuid, 'Barbell rack pull', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Position a barbell on a rack set to just below knee height. Stand with your feet hip-width apart, and grip the barbell with an overhand grip (palms facing your body), hands slightly wider than shoulder-width apart.\r\n2. Begin the lift by driving through your heels, extending your hips and knees to lift the barbell.\r\n3. Pull the barbell up your legs until you reach a standing position with your shoulders back and hips fully extended. Keep the barbell close to your body throughout the movement.\r\n4. Lower the barbell back to the rack with control by hinging at your hips and bending your knees. Repeat for the desired number of repetitions.', E'1. Keep the barbell close to your body to ensure an efficient and powerful lift.\r\n2. Focus on engaging your glutes and hamstrings during the hip extension.\r\n3. Use a weight that allows for proper form and control throughout the exercise to prevent strain or injury.', '{"image_male_start":"images/Powerlifting/Barbell rack pull.jpg","image_male_end":"images/Powerlifting/Barbell rack pull1.jpg","video_url":"videos/Powerlifting/Barbell rack pull.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ea69afa2-33c2-4a48-a0b5-1874c9bf2978'::uuid, 'Barbell rear delt raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell behind your glutes with an overhand grip (palms facing back), hands slightly wider than shoulder-width apart. Keep your back straight and your core engaged.\r\n2. Engage your rear deltoids and lift the barbell upward behind your back by raising your elbows.\r\n3. Lower the barbell back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Use a weight that allows for proper form and control throughout the exercise to prevent strain or injury.\r\n2. Breathe steadily, exhaling as you lift the barbell and inhaling as you lower it back down.\r\n3. Perform the movement slowly and with control to maximize muscle engagement and prevent injury.', '{"image_male_start":"images/Shoulders/Barbell rear delt raise.jpg","image_male_end":"images/Shoulders/Barbell rear delt raise1.jpg","video_url":"videos/Shoulders/Barbell rear delt raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('edda1308-9fe3-4344-9103-d382f7f64527'::uuid, 'Barbell rear lunge on box', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand on a sturdy box with your feet shoulder-width apart, holding a barbell across your upper back. Grip the bar with your hands slightly wider than shoulder-width apart.\r\n2. Step one foot backward off the box, lowering your body into a lunge position. Your front knee should be directly over your ankle, and your back knee should hover just above the floor.\r\n3. Push through the heel of your front foot to return to the starting position on the box, bringing your back foot forward to meet your front foot.\r\n4. Repeat the movement with the opposite leg, alternating legs for the desired number of repetitions.', E'1. Keep your front knee aligned with your toes to avoid placing undue stress on your knee joint.\r\n2. Lower your body with control to maximize muscle engagement and prevent injury.\r\n3. Focus on driving through your front heel to engage your glutes and quadriceps effectively.', '{"image_male_start":"images/Legs/Barbell rear lunge on box.jpg","image_male_end":"images/Legs/Barbell rear lunge on box1.jpg","video_url":"videos/Legs/Barbell rear lunge on box.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7db0522e-670c-4014-814a-6550dd7e0394'::uuid, 'Barbell rear lunges', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell across your upper back. Grip the bar with your hands slightly wider than shoulder-width apart.\r\n2. Step one foot backward, lowering your body into a lunge position. Your front knee should be directly over your ankle, and your back knee should hover just above the floor.\r\n3. Push through the heel of your front foot to return to the starting position, bringing your back foot forward to meet your front foot.\r\n4. Repeat the movement with the opposite leg, alternating legs for the desired number of repetitions.', E'1. Keep your front knee aligned with your toes to avoid placing undue stress on your knee joint.\r\n2. Lower your body with control to maximize muscle engagement and prevent injury.\r\n3. Focus on driving through your front heel to engage your glutes and quadriceps effectively.', '{"image_male_start":"images/Legs/Barbell rear lunges.jpg","image_male_end":"images/Legs/Barbell rear lunges1.jpg","video_url":"videos/Legs/Barbell rear lunges.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f3dd1bca-ffc1-44e1-907d-5ca6caa75ece'::uuid, 'Barbell reverse biceps curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with an overhand grip, hands slightly wider than shoulder-width apart. Let the barbell hang at arm''s length in front of your thighs.\r\n2. Curl the barbell upwards towards your shoulders by bending your elbows. \r\n3. Squeeze your forearms and biceps at the top of the movement, ensuring the barbell reaches shoulder height.\r\n4. Lower the barbell back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Keep your elbows close to your body and avoid swinging your arms to ensure proper form.\r\n2. Perform the movement slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Ensure a firm grip on the barbell to maintain control and proper alignment.', '{"image_male_start":"images/Biceps/Barbell reverse biceps curl.jpeg","video_url":"videos/Biceps/Barbell reverse biceps curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ee3cf343-4fb1-413f-a6d2-e73cfeafae1c'::uuid, 'Barbell reverse close grip bench press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Lie on a flat bench with your feet flat on the floor. Hold a barbell with a reverse grip (palms facing back) and hands placed shoulder-width apart. Position the barbell directly above your chest with your arms fully extended.\r\n2. Slowly lower the barbell towards your chest by bending your elbows. Keep your elbows close to your body throughout the movement.\r\n3. Lower the barbell just before touching your chest, then push the barbell back up to the starting position by extending your arms fully.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep your elbows close to your body to ensure proper form and prevent shoulder strain.\r\n2. Perform the movement slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Ensure a firm grip on the barbell to maintain control and proper alignment.', '{"image_male_start":"images/Chest/Barbell reverse close grip bench press.jpg","image_male_end":"images/Chest/Barbell reverse close grip bench press1.jpg","video_url":"videos/Chest/Barbell reverse close grip bench press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('db1cd3b2-3b77-41af-a0a1-3904c712a5e6'::uuid, 'Barbell reverse grip bench press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Lie on a flat bench with your feet flat on the floor. Hold a barbell with a reverse grip (palms facing back) and hands placed slightly wider than shoulder-width apart. Position the barbell directly above your chest with your arms fully extended.\r\n2. Slowly lower the barbell towards your chest by bending your elbows. Keep your elbows close to your body throughout the movement.\r\n3. Allow the barbell to lightly touch your chest, then push the barbell back up to the starting position by extending your arms fully.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep your elbows close to your body to ensure proper form and prevent shoulder strain.\r\n2. Perform the movement slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Ensure a firm grip on the barbell to maintain control and proper alignment.', '{"image_male_start":"images/Chest/Barbell reverse grip bench press.jpg","image_male_end":"images/Chest/Barbell reverse grip bench press1.jpg","video_url":"videos/Chest/Barbell reverse grip bench press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('540e08b4-a37f-4361-ab1f-a7b94619da99'::uuid, 'Barbell reverse grip bent over row', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with a reverse grip (palms facing forward), hands slightly wider than shoulder-width apart. Bend at the hips and knees to lower your torso until it is nearly parallel to the floor, keeping your back straight and core engaged.\r\n2. Pull the barbell towards your abdomen by bending your elbows. \r\n3. Lower the barbell back to the starting position with control, fully extending your arms.\r\n4. Repeat for the desired number of repetitions.', E'1. Focus on squeezing your shoulder blades together at the top of the movement to maximize back muscle activation.\r\n2. Use a weight that allows for proper form and control throughout the exercise to prevent strain or injury.\r\n3. Breathe steadily, exhaling as you pull the barbell up and inhaling as you lower it back down.', '{"image_male_start":"images/Back/Barbell reverse grip bent over row.jpg","image_male_end":"images/Back/Barbell reverse grip bent over row1.jpg","video_url":"videos/Back/Barbell reverse grip bent over row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4efb5c89-264b-4682-8b29-9f840711c13e'::uuid, 'Barbell reverse spider curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Lie face down on an incline bench with your chest and stomach supported. Hold a barbell with a reverse grip (palms facing down), hands shoulder-width apart. Extend your arms fully so the barbell hangs down towards the floor.\r\n2. Curl the barbell upwards towards your shoulders by bending your elbows, focusing on engaging your forearms and biceps.\r\n3. Squeeze your forearms and biceps at the top of the movement, ensuring the barbell reaches shoulder height.\r\n4. Lower the barbell back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Stabilize your body by engaging your core and pressing your chest firmly against the bench.\r\n2. Focus on a smooth and steady motion to avoid jerking or using momentum.\r\n3. Control the lowering phase of the exercise to enhance muscle tension and growth.', '{"image_male_start":"images/Biceps/Barbell reverse spider curl.jpeg","video_url":"videos/Biceps/Barbell reverse spider curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7880542a-fb4f-4f13-91bc-6df4d9a15ca5'::uuid, 'Barbell rollout', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Begin by kneeling on a mat with a barbell placed in front of you. Grip the barbell with an overhand grip (palms facing down), hands shoulder-width apart.\r\n2. Slowly roll the barbell forward, extending your arms and allowing your body to move forward.\r\n3. Roll out as far as you can while maintaining control and a neutral spine. Your arms should be fully extended, and your body should be in a straight line from your head to your knees.\r\n4. Engage your core and use your abdominal muscles to pull the barbell back to the starting position. Repeat for the desired number of repetitions.', E'1. Maintain a strong core throughout the movement to stabilize your spine and prevent injury.\r\n2. Keep your back flat and avoid letting your hips sag to ensure proper form.\r\n3. Control the rolling motion to maximize muscle engagement and prevent strain.', '{"image_male_start":"images/Abdominals/Barbell rollout.jpeg","video_url":"videos/Abdominals/Barbell rollout.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9952a3d8-33a1-4475-8e01-8bac6470b8e3'::uuid, 'Barbell romanian deadlift', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Begin in a squat position with your feet hip-width apart, holding a barbell with an overhand grip (palms facing down), hands slightly wider than shoulder-width apart.\r\n2. Stand up by driving through your heels and extending your hips and knees until you are standing straight with the barbell hanging in front of your thighs.\r\n3. From this standing position, hinge at your hips and push them back, lowering the barbell down the front of your legs while keeping your back straight and knees slightly bent. Lower the barbell until it passes your knees.\r\n4. Drive your hips forward to return to the standing position, lifting the barbell back up while keeping it close to your legs. Repeat for the desired number of repetitions.', E'1. Keep the barbell close to your body to ensure an efficient and safe lift.\r\n2. Focus on hinging at the hips rather than bending at the waist to properly target the hamstrings and glutes.\r\n3. Control the descent of the barbell to maximize muscle engagement and prevent strain.', '{"image_male_start":"images/Back/Barbell romanian deadlift.jpg","image_male_end":"images/Back/Barbell romanian deadlift1.jpg","video_url":"videos/Back/Barbell romanian deadlift.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6032fdff-6c6a-4656-a50b-2b8677644904'::uuid, 'Barbell seated behind neck military press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Sit on a bench with your feet flat on the floor. Hold a barbell with an overhand grip (palms facing forward), hands slightly wider than shoulder-width apart. Position the barbell behind your neck at shoulder height.\r\n2. Press the barbell overhead by extending your elbows until your arms are fully extended.\r\n3. Lower the barbell back down to the starting position behind your neck with control, bending your elbows.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep your head and neck neutral to prevent overextension or strain.\r\n2. Focus on a controlled motion to engage your shoulder muscles effectively.\r\n3. Ensure your grip is secure to maintain stability throughout the exercise.', '{"image_male_start":"images/Shoulders/Barbell seated behind neck military press.jpg","image_male_end":"images/Shoulders/Barbell seated behind neck military press1.jpg","video_url":"videos/Shoulders/Barbell seated behind neck military press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a00325c3-1706-449c-8a9c-9b59d2cb781d'::uuid, 'Barbell seated concentration biceps curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Sit on a bench with your legs spread apart and feet flat on the floor. Hold a barbell with an underhand grip (palms facing up), hands shoulder-width apart. Lean forward slightly and rest your elbows on the inside of your thighs.\r\n2. Curl the barbell upwards towards your shoulders by bending your elbows, focusing on engaging your biceps.\r\n3. Squeeze your biceps at the top of the movement, ensuring the barbell reaches shoulder height.\r\n4. Lower the barbell back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Breathe steadily, exhaling as you curl the barbell up and inhaling as you lower it back down.\r\n2. Keep your elbows stationary and pressed against your thighs to isolate the biceps.\r\n3. Focus on the contraction at the top of the movement to fully engage the biceps.', '{"image_male_start":"images/Biceps/Barbell seated concentration biceps curl.jpeg","video_url":"videos/Biceps/Barbell seated concentration biceps curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('707c99e8-4a82-4ac2-bf00-265c9cb25b79'::uuid, 'Barbell seated good morning', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Sit parallel on a bench with your feet flat on the floor. Hold a barbell across your upper back with an overhand grip, hands slightly wider than shoulder-width apart.\r\n2. Hinge at your hips and lean your torso forward, lowering it towards your thighs while keeping your back straight.\r\n3. Lower your torso until it is nearly parallel to the floor, while keeping your back straight and your elbows slightly bent.\r\n4. Lift your torso back to the starting position. Repeat for the desired number of repetitions.', E'1. Focus on hinging at the hips rather than bending at the waist to properly target the lower back and hamstrings.\r\n2. Control the descent and ascent of your torso to maximize muscle engagement and prevent strain.\r\n3. Breathe steadily, exhaling as you lower your torso and inhaling as you return to the starting position.', '{"image_male_start":"images/Back/Barbell seated good morning.jpg","image_male_end":"images/Back/Barbell seated good morning1.jpg","video_url":"videos/Back/Barbell seated good morning.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('23edc2d4-2018-46df-b605-d01c11ee9adb'::uuid, 'Barbell seated military press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Sit on a bench with feet flat on the floor, back first in front of a rack. Hold a barbell with an overhand grip (palms facing forward), hands slightly wider than shoulder-width apart. Position the barbell in front of your shoulders, just below chin level.\r\n2. Press the barbell overhead by extending your elbows until your arms are fully extended.\r\n3. Lower the barbell back down to the starting position with control by bending your elbows.\r\n4. Repeat for the desired number of repetitions.', E'1. Perform the movement slowly and with control to maximize muscle engagement and prevent injury.\r\n2. Breathe steadily, exhaling as you press the barbell overhead and inhaling as you lower it back down.\r\n3. Use a weight that allows for proper form and control throughout the exercise to prevent strain or injury.', '{"image_male_start":"images/Shoulders/Barbell seated military press.jpg","image_male_end":"images/Shoulders/Barbell seated military press1.jpg","video_url":"videos/Shoulders/Barbell seated military press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f3ab6525-256b-4b15-8160-132d464bcaf7'::uuid, 'Barbell seated on knee calve raises', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Sit on a bench with your feet flat on the floor and a barbell resting across your thighs, just above your knees. Position your feet hip-width apart.\r\n2. Lift your heels off the floor by pressing through your forefeet, raising your knees towards the ceiling.\r\n3. Squeeze your calf muscles at the top of the movement, ensuring your heels are as high as possible.\r\n4. Lower your heels back down to the starting position with control. Repeat for the desired number of repetitions.', E'1. Ensure a secure grip on the barbell to maintain control and proper alignment.\r\n2. Use a weight that allows for proper form and control throughout the exercise to prevent strain or injury.\r\n3. Breathe steadily, exhaling as you lift your heels and inhaling as you lower them.', '{"image_male_start":"images/Legs/barbell seated on knee calve raises.jpg","image_male_end":"images/Legs/barbell seated on knee calve raises1.jpg","video_url":"videos/Legs/barbell seated on knee calve raises.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('656dafe7-b8de-41ce-86f3-62bb414e1d67'::uuid, 'Barbell seated overhead press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Sit on a bench with your feet flat on the floor. Hold a barbell with an overhand grip (palms facing forward), hands slightly wider than shoulder-width apart. Position the barbell at shoulder height in front of you.\r\n2. Press the barbell overhead by extending your elbows until your arms are fully extended.\r\n3. Lower the barbell back down to the starting position with control, bending your elbows.\r\n4. Repeat for the desired number of repetitions.', E'1. Perform the movement slowly and with control to maximize muscle engagement and prevent injury.\r\n2. Breathe steadily, exhaling as you press the barbell overhead and inhaling as you lower it back down.\r\n3. Use a weight that allows for proper form and control throughout the exercise to prevent strain or injury.', '{"image_male_start":"images/Shoulders/Barbell seated overhead press.jpg","image_male_end":"images/Shoulders/Barbell seated overhead press1.jpg","video_url":"videos/Shoulders/Barbell seated overhead press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('74ef22c2-6b7c-4f21-bc82-0ddb425b62cd'::uuid, 'Barbell seated overhead triceps press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Sit on a bench with your feet flat on the floor, maintaining an upright posture. Hold a barbell with a close grip (palms facing up), hands positioned slightly narrower than shoulder-width apart. \r\n2. Position the barbell behind your head with your elbows bent and pointing upwards. Press the barbell overhead by extending your elbows until your arms are fully extended.\r\n3. Lower the barbell back down to the starting position with control, bending your elbows.\r\n4. Repeat for the desired number of repetitions.', E'1. Maintain an upright posture to ensure proper form and avoid leaning forward.\r\n2. Perform the movement slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Ensure your elbows stay pointed upwards to maintain proper alignment and effectively target the triceps.\r\n', '{"image_male_start":"images/Triceps/barbell seated overhead triceps press.jpeg","video_url":"videos/Triceps/barbell seated overhead triceps press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('84e94efb-c75f-48e1-be01-0bf578deeaf0'::uuid, 'Barbell seated twist', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Sit on a bench with your feet flat on the floor, holding a barbell across your upper back with an overhand grip, hands slightly wider than shoulder-width apart. Keep your back straight and your core engaged.\r\n2. Begin by rotating your torso to the right, keeping your hips and lower body stationary. Rotate until you feel a stretch in your obliques.\r\n3. Reverse the movement, rotating your torso to the left, again keeping your hips and lower body stationary.\r\n4. Repeat the rotation to both sides for the desired number of repetitions.', E'1. Engage your core muscles to stabilize your spine and maintain proper form.\r\n2. Maintain an upright posture to avoid straining your lower back.\r\n3. Use a weight that allows for proper form and control throughout the exercise to prevent strain or injury.', '{"image_male_start":"images/Abdominals/Barbell seated twist.jpeg","video_url":"videos/Abdominals/Barbell seated twist.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('857cbc8c-5c66-4526-a414-521b694baddf'::uuid, 'Barbell seated twist on exercise ball', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Sit on an exercise ball with your feet flat on the floor, holding a barbell across your upper back with an overhand grip, hands slightly wider than shoulder-width apart. Keep your back straight and your core engaged.\r\n2. Begin by rotating your torso to the right, keeping your hips and lower body stationary. Rotate until you feel a stretch in your obliques.\r\n3. Reverse the movement, rotating your torso to the left, again keeping your hips and lower body stationary.\r\n4. Repeat the rotation to both sides for the desired number of repetitions.', E'1. Engage your core muscles to stabilize your spine and maintain proper form.\r\n2. Maintain an upright posture to avoid straining your lower back.\r\n3. Use a weight that allows for proper form and control throughout the exercise to prevent strain or injury.', '{"image_male_start":"images/Abdominals/barbell seated twist on exercise ball.jpeg","video_url":"videos/Abdominals/barbell seated twist on exercise ball.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('aaa4ee04-3793-4f9e-ada8-fe9dc7434c90'::uuid, 'Barbell shrugs', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with an overhand grip (palms facing down), hands slightly wider than shoulder-width apart. Let the barbell hang in front of your thighs.\r\n2. Lift your shoulders straight up towards your ears as high as you can, keeping your arms straight.\r\n3. Squeeze your upper back muscles (trapezius) at the top of the movement.\r\n4. Lower your shoulders back down to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep your arms straight throughout the movement to focus on your shoulder muscles.\r\n2. Perform the movement slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Avoid rotating your shoulders as you lift and lower them to prevent strain.', '{"image_male_start":"images/Shoulders/barbell shrugs .jpg","video_url":"videos/Shoulders/barbell shrugs .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('77fa9c65-d066-4d5f-92d4-8b4011bf93a6'::uuid, 'Barbell side bends', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell across your upper back with an overhand grip, hands slightly wider than shoulder-width apart. Keep your back straight and your core engaged.\r\n2. Lean to the right side by bending at the waist, lowering your torso as far as is comfortable.\r\n3. Return to the starting position by engaging your oblique muscles and straightening your torso.\r\n4. Repeat the movement to the left side. Continue alternating sides for the desired number of repetitions.', E'1. Avoid twisting your torso during the movement to focus on the side bend.\r\n2. Breathe steadily, exhaling as you bend to each side and inhaling as you return to the center.\r\n3. Keep your movements slow and controlled to maximize muscle engagement and prevent injury.', '{"image_male_end":"images/Abdominals/Barbell side bends.jpeg","video_url":"videos/Abdominals/Barbell side bends.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b4d7d710-dda0-4575-ac73-f2c229c0a62c'::uuid, 'Barbell side split squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet wider than shoulder-width apart, holding a barbell across your upper back with an overhand grip, hands slightly wider than shoulder-width apart. Keep your back straight and your core engaged.\r\n2. Shift your weight to your right leg and bend your right knee, lowering your body into a side lunge while keeping your left leg straight.\r\n3. Lower your body until your right thigh is parallel to the floor, ensuring your right knee is aligned with your right foot.\r\n4. Push through your right heel to return to the starting position. Repeat the movement on the left side. Continue alternating sides for the desired number of repetitions.', E'1. Focus on hip mobility to ensure a deep and effective squat.\r\n2. Keep your spine neutral to avoid any forward or backward tilt.\r\n3. Drive through your heels to engage your glutes and ensure proper movement mechanics.', '{"image_male_start":"images/Legs/Barbell side split squat.jpg","image_male_end":"images/Legs/Barbell side split squat1.jpg","video_url":"videos/Legs/Barbell side split squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('66eb5e0d-f284-4625-ba14-e7233ba33187'::uuid, 'Barbell single arm biceps curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with one hand using an underhand grip (palm facing up). Let the barbell hang at arm''s length by your side.\r\n2. Curl the barbell upward towards your shoulder by bending your elbow, focusing on engaging your biceps.\r\n3. Squeeze your biceps at the top of the movement, ensuring the barbell reaches shoulder height.\r\n4. Lower the barbell back to the starting position with control, fully extending your arm. Repeat for the desired number of repetitions, then switch to the other arm.', E'1. Keep your upper arm stationary to isolate the biceps effectively.\r\n2. Perform the movement slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Avoid using momentum by swinging your body or arm; focus on controlled movement.', '{"image_male_start":"images/Biceps/Barbell single arm biceps curl.jpeg","video_url":"videos/Biceps/Barbell single arm biceps curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('15b49f18-4d4c-4a87-afa6-ae1867124390'::uuid, 'Barbell single leg deadlift', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet hip-width apart, holding a barbell with both hands using an overhand grip (palms facing down). Keep your back straight and your core engaged.\r\n2. Shift your weight to your right leg and lift your left leg behind you, keeping it straight. Allow the barbell to hang down, keeping your arms straight naturally.\r\n3. Lower the barbell until your torso is almost parallel to the floor and your left leg is extended behind you in a straight line. Keep your right knee slightly bent.\r\n4. Lift your torso back to the starting position. Repeat for the desired repetitions, then switch to the other leg.', E'1. Perform the movement slowly and with control to maximize muscle engagement and prevent injury.\r\n2. Focus on balance by keeping your supporting leg steady and your movements controlled.\r\n3. Breathe steadily, exhaling as you lower the barbell and inhaling as you return to the starting position.', '{"image_male_start":"images/Back/Barbell single leg deadlift.jpg","image_male_end":"images/Back/Barbell single leg deadlift1.jpg","video_url":"videos/Back/Barbell single leg deadlift.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f0fe83df-8bdc-4fb6-b0df-b67fea2ebb07'::uuid, 'Barbell single leg split squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet hip-width apart, holding a barbell across your upper back with an overhand grip, hands slightly wider than shoulder-width apart. Position one foot behind you on a bench, and the other foot firmly planted on the floor.\r\n2. Lower your body by bending your front knee, allowing your back knee to drop towards the floor.\r\n3. Continue lowering until your front thigh is parallel to the floor and your back knee is close to the floor.\r\n4. Push through your front heel to return to the starting position. Repeat for the desired number of repetitions, then switch to the other leg.', E'1. Keep your chest up and avoid leaning forward to maintain an upright posture.\r\n2. Ensure your front knee aligns with your foot to prevent strain on your knee joint.\r\n3. Perform the movement slowly and with control to maximize muscle engagement and prevent injury.', '{"image_male_start":"images/Legs/Barbell single leg split squat.jpg","image_male_end":"images/Legs/Barbell single leg split squat1.jpg","video_url":"videos/Legs/Barbell single leg split squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a97bef6e-f244-4b7d-bbb0-e632e918a7c4'::uuid, 'Barbell Smith Chest Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '132c52b1-6336-4426-a457-c35a314038f2'::uuid, E'1. Lie on a flat bench positioned under the smith machine barbell, with your feet flat on the floor and your back pressed firmly against the bench. Grip the barbell with an overhand grip (palms facing forward), hands slightly wider than shoulder-width apart.\r\n2. Unrack the barbell by extending your arms straight up. Having the barbell over your chest with your elbows slightly bent.\r\n3. Lower the barbell towards your chest by bending your elbows, ensuring the barbell follows a straight path and your elbows are at a 45-degree angle to your torso.\r\n4. Push the barbell back up to the starting position by extending your elbows, fully engaging your chest muscles. Repeat for the desired number of repetitions.', E'1. Keep your movements slow and controlled to maximize muscle engagement and prevent injury.\r\n2. Maintain a 45-degree angle with your elbows to effectively target your chest muscles.\r\n3. Avoid locking out your elbows at the top of the movement to keep tension on your chest.', '{"image_male_start":"images/Chest/Barbell Smith Chest Press_Female.jpg","image_female_start":"images/Chest/Barbell Smith Chest Press_Female.jpg","image_female_end":"images/Chest/Barbell Smith Chest Press_Female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('bc5e5919-7cc6-4d15-8eee-24b0748d6f51'::uuid, 'Barbell snatch', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Start in a squat position with your feet shoulder-width apart, toes pointed slightly outward. Hold the barbell with a wide overhand grip (palms facing down), hands placed wider than shoulder-width apart. The barbell should be on the floor, close to your shins.\r\n2. Explosively extend your hips, knees, and ankles while pulling the barbell upward in one smooth motion. Keeping the barbell close to your body as you lift.\r\n3. As the barbell reaches chest height, quickly drop into a squat position and catch the barbell overhead with your arms fully extended.\r\n4. Stand up by extending your hips and knees, keeping the barbell overhead. Lower the barbell back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Explode through your hips and knees to generate the power needed for the lift.\r\n2. Drop quickly into the squat to catch the barbell overhead in a stable position.\r\n3. Use a weight that allows for proper form and control throughout the exercise to prevent strain or injury.', '{"image_male_start":"images/Powerlifting/Barbell snatch.jpg","image_male_end":"images/Powerlifting/Barbell snatch1.jpg","video_url":"videos/Powerlifting/Barbell snatch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('11f710b4-ef82-4d56-a2bb-cbec2aa98ba7'::uuid, 'Barbell snatch balance', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell across your upper back with an overhand grip, hands placed wider than shoulder-width apart. Your feet should be in a slight squat stance.\r\n2. Dip slightly by bending your knees and hips, then quickly drive upwards, extending your knees and hips.\r\n3. As you extend, use the upward momentum to press the barbell overhead while simultaneously dropping into a deep squat position, catching the barbell with your arms fully extended overhead.\r\n4. Stand up by extending your hips and knees, keeping the barbell overhead. Lower the barbell back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Explode through your hips and knees to generate the power needed for the lift.\r\n2. Drop quickly into the squat to catch the barbell overhead in a stable position.\r\n3. Use a weight that allows for proper form and control throughout the exercise to prevent strain or injury.', '{"image_male_start":"images/Powerlifting/Barbell snatch balance.jpg","image_male_end":"images/Powerlifting/Barbell snatch balance1.jpg","video_url":"videos/Powerlifting/Barbell snatch balance.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b147a7c6-ed58-4184-b703-aef5f4fbfd01'::uuid, 'Barbell snatch deadlift close grip', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Start in a squat position with your feet shoulder-width apart, toes pointed slightly outward. Hold the barbell with an overhand grip (palms facing down), hands placed slightly wider than shoulder-width apart. The barbell should be on the floor, close to your shins.\r\n2. Lift the barbell off the floor by extending your hips and knees simultaneously, keeping the barbell close to your body.\r\n3. Continue lifting until you are standing upright with the barbell at hip level.\r\n4. Lower the barbell back to the starting position with control, bending your hips and knees. Repeat for the desired number of repetitions.', E'1. Keep your back straight and avoid rounding your shoulders to ensure proper form.\r\n2. Keep the barbell close to your body throughout the lift to maximize efficiency and control.\r\n3. Focus on smooth, controlled movements to maximize muscle engagement and prevent injury.', '{"image_male_start":"images/Back/Barbell snatch deadlift close grip.jpg","image_male_end":"images/Back/Barbell snatch deadlift close grip1.jpg","video_url":"videos/Back/Barbell snatch deadlift close grip.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('98a5cfee-3c20-4f2f-9ab1-7f02e13cad0a'::uuid, 'Barbell snatch deadlift wide grip', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Start in a squat position with your feet shoulder-width apart, toes pointed slightly outward. Hold the barbell with an overhand grip (palms facing down), hands placed about 2 fists wider than shoulder-width apart. The barbell should be on the floor, close to your shins.\r\n2. Lift the barbell off the floor by extending your hips and knees simultaneously, keeping the barbell close to your body.\r\n3. Continue lifting until you are standing upright with the barbell at hip level.\r\n4. Lower the barbell back to the starting position with control, bending your hips and knees. Repeat for the desired number of repetitions.', E'1. Keep your back straight and avoid rounding your shoulders to ensure proper form.\r\n2. Keep the barbell close to your body throughout the lift to maximize efficiency and control.\r\n3. Focus on smooth, controlled movements to maximize muscle engagement and prevent injury.', '{"image_male_start":"images/Back/Barbell snatch deadlift wide grip.jpg","image_male_end":"images/Back/Barbell snatch deadlift wide grip1.jpg","video_url":"videos/Back/Barbell snatch deadlift wide grip.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5b1d337c-0711-4961-9000-aeb7c41e2d6b'::uuid, 'Barbell snatch from blocks', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Start in a squat position with your feet shoulder-width apart, toes pointed slightly outward. Place the barbell on blocks positioned at knee height. Hold the barbell with a wide overhand grip (palms facing down), hands placed wider than shoulder-width apart.\r\n2. Lift the barbell off the blocks by extending your hips and knees simultaneously, keeping the barbell close to your body.\r\n3. As the barbell reaches hip level, explosively extend your hips, knees, and ankles while pulling the barbell upward in one smooth motion. Quickly drop into a squat position and catch the barbell overhead with your arms fully extended.\r\n4. Stand up by extending your hips and knees, keeping the barbell overhead. Lower the barbell back to the blocks with control. Repeat for the desired number of repetitions.', E'1. Explode through your hips and knees to generate the power needed for the lift.\r\n2. Drop quickly into the squat to catch the barbell overhead in a stable position.\r\n3. Use a weight that allows for proper form and control throughout the exercise to prevent strain or injury.', '{"image_male_start":"images/Powerlifting/Barbell snatch from blocks.jpg","image_male_end":"images/Powerlifting/Barbell snatch from blocks1.jpg","video_url":"videos/Powerlifting/Barbell snatch from blocks.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('50e6d542-9a08-4fd3-80af-3c52e0768af3'::uuid, 'Barbell snatch pull', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Start in a squat position with your feet shoulder-width apart, toes pointed slightly outward. Hold the barbell with a wide overhand grip (palms facing down), hands placed wider than shoulder-width apart. The barbell should be on the floor, close to your shins.\r\n2. Lift the barbell off the floor by extending your hips and knees simultaneously, keeping the barbell close to your body.\r\n3. As the barbell reaches hip level, explosively extend your hips, knees, and ankles while pulling the barbell upward. Focusing on pulling the barbell up to abdomen height by driving your elbows upward and outward.\r\n4. Lower the barbell back to the starting position with control, bending your hips and knees. Repeat for the desired number of repetitions.', E'1. Keep the barbell close to your body throughout the lift to maximize efficiency and control.\r\n2. Explode through your hips and knees to generate the power needed for the lift.\r\n3. Focus on a strong, controlled pull to ensure proper form and muscle engagement.', '{"image_male_start":"images/Powerlifting/Barbell snatch pull.jpg","image_male_end":"images/Powerlifting/Barbell snatch pull1.jpg","video_url":"videos/Powerlifting/Barbell snatch pull.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('cbb4ffb0-2811-4d4c-b4b6-a95c18fb3ac6'::uuid, 'Barbell split clean', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Start in a squat position with your feet shoulder-width apart, toes pointed slightly outward. Hold the barbell with an overhand grip (palms facing down), hands placed slightly wider than shoulder-width apart. The barbell should be on the floor, close to your shins.\r\n2. Lift the barbell off the floor by extending your hips and knees simultaneously, keeping the barbell close to your body.\r\n3. As the barbell reaches hip level, explosively extend your hips, knees, and ankles while pulling the barbell upward. Quickly drop into a split stance, with one foot forward and the other foot back, catching the barbell at shoulder height with your elbows pointing forward.\r\n4. Stand up by bringing your feet back together, keeping the barbell at shoulder height. Lower the barbell back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep the barbell close to your body throughout the lift to maximize efficiency and control.\r\n2. Explode through your hips and knees to generate the power needed for the lift.\r\n3. Quickly transition into the split stance to catch the barbell in a stable position.', '{"image_male_start":"images/Powerlifting/Barbell split clean.jpg","image_male_end":"images/Powerlifting/Barbell split clean1.jpg","video_url":"videos/Powerlifting/Barbell split clean.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9ad6a52a-2942-4437-bf27-8b6a750ac247'::uuid, 'Barbell split jerk', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Start in a standing position with your feet shoulder-width apart, holding the barbell at shoulder height with an overhand grip (palms facing forward), hands placed slightly wider than shoulder-width apart. Your elbows should be pointing slightly forward, and your chest should be up.\r\n2. Engage your core, dip slightly by bending your knees and hips, then explosively extend your knees and hips to drive the barbell overhead.\r\n3. As you drive the barbell up, quickly split your feet into a lunge position with one foot forward and the other foot back, catching the barbell overhead with your arms fully extended and your torso upright.\r\n4. Stand up by bringing your feet back together, keeping the barbell overhead. Lower the barbell back to shoulder height with control. Repeat for the desired number of repetitions.', E'1. Use your legs to drive the barbell up by explosively extending your hips and knees.\r\n2. Quickly transition into the split stance to catch the barbell in a stable position.\r\n3. Maintain a neutral spine and keep your chest up throughout the movement.', '{"image_male_start":"images/Powerlifting/Barbell split jerk.jpg","image_male_end":"images/Powerlifting/Barbell split jerk1.jpg","video_url":"videos/Powerlifting/Barbell split jerk.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('90228b04-005c-43dd-b269-2d523ec0611a'::uuid, 'Barbell split squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand tall with a barbell placed across your upper back and your feet positioned in a split stance, one foot forward and the other extended behind.\r\n2. Lower your body by bending both knees until your back knee nearly touches the floor and your front thigh is parallel to the floor. Keep your front knee aligned with your front foot.\r\n3. Push through your front heel to return to the starting position, extending both knees fully.\r\n4. Repeat for the desired number of repetitions, then switch to the other leg.', E'1. Ensure your front knee aligns with your foot to prevent strain on your knee joint.\r\n2. Perform the movement slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Breathe steadily, exhaling as you lower into the squat and inhaling as you return to the starting position.', '{"image_male_start":"images/Legs/Barbell split squat.jpg","image_male_end":"images/Legs/Barbell split squat1.jpg","video_url":"videos/Legs/Barbell split squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('22b295d4-c72f-47fa-a717-1214b446baf8'::uuid, 'Barbell squat to grass', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell across your upper back with an overhand grip, hands slightly wider than shoulder-width apart. Your feet should be pointed slightly outward.\r\n2. Begin the squat by pushing your hips back and bending your knees, lowering your body as far down as possible, aiming to get your hips below your knees.\r\n3. Push through your heels to return to the starting position, extending your hips and knees fully. Repeat for the desired number of repetitions.', E'1. Ensure your knees align with your toes to prevent strain on your knee joints.\r\n2. Descend slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Breathe steadily, exhaling as you lower into the squat and inhaling as you return to the starting position.', '{"image_male_start":"images/Legs/Barbell squat to grass.jpg","image_male_end":"images/Legs/Barbell squat to grass1.jpg","video_url":"videos/Legs/Barbell squat to grass.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('19b16da7-186e-4b35-9b66-a87e03148bc2'::uuid, 'Barbell squat with 2 sec hold', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell across your upper back with an overhand grip, hands slightly wider than shoulder-width apart. Your feet should be pointed slightly outward.\r\n2. Begin the squat by pushing your hips back and bending your knees, lowering your body as far down as possible, aiming to get your hips below your knees and pause for 2 seconds.\r\n3. Push through your heels to return to the starting position, extending your hips and knees fully. Repeat for the desired number of repetitions.', E'1. Ensure your knees align with your toes to prevent strain on your knee joints.\r\n2. Descend slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Breathe steadily, exhaling as you lower into the squat and inhaling as you return to the starting position.', '{"image_male_start":"images/Legs/barbell squat with 2 sec hold.jpg","image_male_end":"images/Legs/barbell squat with 2 sec hold1.jpg","video_url":"videos/Legs/barbell squat with 2 sec hold.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('671bea75-6304-4acd-b51d-89120b7363a4'::uuid, 'Barbell standing back wrist curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell behind your back with an overhand grip (palms facing backward), hands slightly wider than shoulder-width apart. Your arms should be fully extended, and the barbell should rest against your glutes.\r\n2. Flex your wrists to curl the barbell upward, bringing the barbell toward your forearms.\r\n3. Hold the contraction at the top for a moment, squeezing your forearm muscles.\r\n4. Slowly lower the barbell back to the starting position by extending your wrists. Repeat for the desired number of repetitions.', E'1. Avoid using your arms or shoulders to lift the barbell; focus on your wrist movement.\r\n2. Breathe steadily, exhaling as you curl the barbell up and inhaling as you lower it back down.\r\n3. Use a weight that allows for proper form and control throughout the exercise to prevent strain or injury.', '{"image_male_start":"images/Forearms/Barbell standing back wrist curl.jpeg","video_url":"videos/Forearms/Barbell standing back wrist curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e3177f33-0075-446f-9369-065d8bbb3866'::uuid, 'Barbell standing close grip curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with an underhand grip (palms facing up), hands placed slightly closer  than shoulder-width apart. Your arms should be fully extended, and the barbell should rest against your thighs.\r\n2. Curl the barbell upward by bending your elbows, bringing the barbell toward your shoulders. Keep your elbows close to your torso throughout the movement.\r\n3. Hold the contraction at the top for a moment, squeezing your biceps.\r\n4. Slowly lower the barbell back to the starting position by extending your arms. Repeat for the desired number of repetitions.', E'1. Keep your elbows stationary and close to your torso throughout the movement to isolate your biceps.\r\n2. Focus on smooth, controlled movements to maximize muscle engagement and prevent injury.\r\n3. Breathe steadily, exhaling as you curl the barbell up and inhaling as you lower it back down.\r\n4. Avoid using momentum or swinging your body to lift the barbell.', '{"image_male_start":"images/Biceps/Barbell standing close grip curl.jpeg","video_url":"videos/Biceps/Barbell standing close grip curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0ffbbb4b-5dd4-4190-8111-6d02ba550107'::uuid, 'Barbell standing close grip military press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with an overhand grip (palms facing forward), hands placed at shoulder-width apart. The barbell should be at chest height.\r\n2. Press the barbell overhead by extending your arms fully, making sure to keep the bar path straight and close to your body.\r\n3. Hold the barbell overhead for a moment and slowly lower the barbell back to the starting position at chest height. Repeat for the desired number of repetitions.', E'1. Avoid arching your back by maintaining a neutral spine throughout the movement.\r\n2. Breathe steadily, exhaling as you press the barbell overhead and inhaling as you lower it back down.\r\n3. Keep your elbows slightly in front of your body at the starting position to avoid shoulder strain.', '{"image_male_start":"images/Shoulders/Barbell standing close grip military press.jpg","image_male_end":"images/Shoulders/Barbell standing close grip military press1.jpg","video_url":"videos/Shoulders/Barbell standing close grip military press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6d1582ef-8d04-49f5-b727-6bb0e528f8b1'::uuid, 'Barbell standing concentration curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with an underhand grip (palms facing up), hands placed about shoulder-width apart. Your arms should be fully extended, and the barbell should rest against your thighs.\r\n2. Engage your core, keep your chest up, and maintain a neutral spine. Slightly bend forward from your hips and allow your elbows to hang close to your knees.\r\n3. Curl the barbell upward by bending your elbows, bringing the barbell toward your shoulders. Keep your elbows stationary against your thighs to isolate your biceps.\r\n4. Hold the contraction at the top for a moment, squeezing your biceps. Slowly lower the barbell back to the starting position by extending your arms. Repeat for the desired number of repetitions.', E'1. Focus on smooth, controlled movements to maximize muscle engagement and prevent injury.\r\n2. Breathe steadily, exhaling as you curl the barbell up and inhaling as you lower it back down.\r\n3. Avoid using momentum or swinging your body to lift the barbell.', '{"image_male_start":"images/Biceps/Barbell standing concentration curl.jpeg","video_url":"videos/Biceps/Barbell standing concentration curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5de413ba-e9db-46c2-8480-432bf4a5dd72'::uuid, 'Barbell standing leg calf raises', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand on a step with your feet shoulder-width apart, holding a barbell across your upper back with an overhand grip, hands slightly wider than shoulder-width apart. Your forefeet should be on the edge of the step, and your heels should hang off.\r\n2. Raise your heels as high as possible by extending your ankles, lifting your body upward.\r\n3. Hold the top position for a moment, feeling the contraction in your calf muscles.\r\n4. Slowly lower your heels back down below the level of the step, stretching your calves. Repeat for the desired number of repetitions.', E'1. Keep your movements slow and controlled to maximize muscle engagement and prevent injury.\r\n2. Focus on using your calf muscles to lift your body, avoiding bouncing or using momentum.\r\n3. Breathe steadily, exhaling as you raise your heels and inhaling as you lower them back down.\r\n4. Ensure your heels drop below the level of the step to achieve a full range of motion and effective stretch.', '{"image_male_start":"images/Legs/Barbell standing leg calf raises.jpg","image_male_end":"images/Legs/Barbell standing leg calf raises1.jpg","video_url":"videos/Legs/Barbell standing leg calf raises.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('18095174-b632-48cb-9544-71c3afa63259'::uuid, 'Barbell standing military press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with an overhand grip (palms facing forward), hands placed slightly wider than shoulder-width apart. The barbell should be at chest height.\r\n2. Press the barbell overhead by extending your arms fully, making sure to keep the bar path straight and close to your body.\r\n3. Hold the barbell overhead for a moment, ensuring your arms are fully extended and your shoulders are engaged.\r\n4. Slowly lower the barbell back to the starting position at chest height. Repeat for the desired number of repetitions.', E'1. Avoid arching your back by maintaining a neutral spine throughout the movement.\r\n2. Breathe steadily, exhaling as you press the barbell overhead and inhaling as you lower it back down.\r\n3. Keep your elbows slightly in front of your body at the starting position to avoid shoulder strain.', '{"image_male_start":"images/Shoulders/Barbell Standing Military Press.jpg","image_male_end":"images/Shoulders/Barbell Standing Military Press1.jpg","video_url":"videos/Shoulders/Barbell Standing Military Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8291bc88-97d2-463a-9633-66a9d89efe2d'::uuid, 'Barbell standing overhead triceps extension', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with an overhand grip (palms facing forward), hands placed closer than shoulder-width apart. Lift the barbell overhead, fully extending your arms. Your elbows should be close to your head.\r\n2. Slowly lower the barbell behind your head by bending your elbows, keeping your upper arms stationary.\r\n3. Lower the barbell until your forearms are parallel to the floor, feeling the stretch in your triceps.\r\n4. Press the barbell back up to the starting position by extending your arms fully. Repeat for the desired number of repetitions.', E'1. Keep your upper arms stationary and close to your head throughout the movement to isolate your triceps.\r\n2. Focus on smooth, controlled movements to maximize muscle engagement and prevent injury.\r\n3. Use a weight that allows for proper form and control throughout the exercise to prevent strain or injury.', '{"image_male_start":"images/Triceps/Barbell standing overhead triceps extension.jpeg","video_url":"videos/Triceps/Barbell standing overhead triceps extension.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('51e9e102-773d-4556-994b-af79e4204044'::uuid, 'Barbell standing shoulder press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with an overhand grip (palms facing forward), hands placed slightly wider than shoulder-width apart. The barbell should be at chest height.\r\n2. Press the barbell overhead by extending your arms fully, keeping your elbows outwards.\r\n3. Hold the barbell overhead for a moment, ensuring your arms are fully extended and your shoulders are engaged.\r\n4. Slowly lower the barbell back to the starting position at chest height. Repeat for the desired number of repetitions.', E'1. Avoid arching your back by maintaining a neutral spine throughout the movement.\r\n2. Breathe steadily, exhaling as you press the barbell overhead and inhaling as you lower it back down.\r\n3. Keep your elbows slightly in front of your body at the starting position to avoid shoulder strain.', '{"image_male_start":"images/Shoulders/Barbell standing shoulder press.jpg","image_male_end":"images/Shoulders/Barbell standing shoulder press1.jpg","video_url":"videos/Shoulders/Barbell standing shoulder press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('60d0c75c-b650-407f-9f4c-9f70cb8f7e36'::uuid, 'Barbell standing twist', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell across your upper back with an overhand grip, hands slightly wider than shoulder-width apart.\r\n2. Rotate your torso to the right, keeping your hips and knees aligned with the movement.\r\n3. Rotate back to the center position with control, then twist your torso to the left.\r\n4. Continue alternating sides, repeating for the desired number of repetitions.', E'1. Rotate your torso, not just your arms, to effectively engage your oblique muscles.\r\n2. Breathe steadily, exhaling as you twist and inhaling as you return to the center position.\r\n3. Use a weight that allows for proper form and control throughout the exercise to prevent strain or injury.', '{"image_male_start":"images/Abdominals/Barbell standing twist.jpeg","video_url":"videos/Abdominals/Barbell standing twist.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('254de9ca-ad26-46e5-b1db-a498bb76d447'::uuid, 'Barbell standing wide grip biceps curls', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with an underhand grip (palms facing up), hands placed wider than shoulder-width apart. Your arms should be fully extended, and the barbell should rest against your thighs.\r\n2. Curl the barbell upward by bending your elbows, bringing the barbell toward your shoulders. Keep your elbows close to your torso throughout the movement.\r\n3. Hold the contraction at the top for a moment, squeezing your biceps.\r\n4. Slowly lower the barbell back to the starting position by extending your arms. Repeat for the desired number of repetitions.', E'1. Keep your elbows stationary and close to your torso throughout the movement to isolate your biceps.\r\n2. Focus on smooth, controlled movements to maximize muscle engagement and prevent injury.\r\n3. Avoid using momentum or swinging your body to lift the barbell.\r\n', '{"image_male_start":"images/Biceps/Barbell standing wide grip biceps curls.jpeg","video_url":"videos/Biceps/Barbell standing wide grip biceps curls.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('12439779-1810-4b98-9950-c89357079334'::uuid, 'Barbell standing wide grip military press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with an overhand grip (palms facing forward), hands placed  2 fists wider than shoulder-width apart. The barbell should be at chest height.\r\n2. Press the barbell overhead by extending your arms fully, making sure to keep the bar path straight and close to your body.\r\n3. Hold the barbell overhead for a moment, ensuring your arms are fully extended and your shoulders are engaged.\r\n4. Slowly lower the barbell back to the starting position at chest height. Repeat for the desired number of repetitions.', E'1. Avoid arching your back by maintaining a neutral spine throughout the movement.\r\n2. Breathe steadily, exhaling as you press the barbell overhead and inhaling as you lower it back down.\r\n3. Keep your elbows slightly in front of your body at the starting position to avoid shoulder strain.', '{"image_male_start":"images/Shoulders/Barbell standing wide grip military press.jpg","image_male_end":"images/Shoulders/Barbell standing wide grip military press1.jpg","video_url":"videos/Shoulders/Barbell standing wide grip military press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6f72a76d-7ac5-4986-a47b-abfb2341dbd5'::uuid, 'Barbell step up on bench', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand facing a bench with your feet shoulder-width apart, holding a barbell across your upper back with an overhand grip, hands slightly wider than shoulder-width apart.\r\n2. Step up onto the bench with your right foot, pressing through your heel to lift your body up.\r\n3. Bring your left foot up to meet your right foot on the bench, standing fully upright.\r\n4. Step back down with your left foot, followed by your right foot, returning to the starting position. Repeat the movement, alternating the leading leg, for the desired number of repetitions.', E'1. Push through your heel of the leading foot to maximize glute and quadriceps activation.\r\n2. Breathe steadily, exhaling as you step up and inhaling as you step down.\r\n3. Use a weight that allows for proper form and control throughout the exercise to prevent strain or injury.\r\n4. Ensure the bench is stable and secure to prevent any movement during the exercise.', '{"image_male_start":"images/Legs/Barbell step up on bench.jpg","image_male_end":"images/Legs/Barbell step up on bench1.jpg","video_url":"videos/Legs/Barbell step up on bench.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('46468b92-bbe3-4eab-ad3d-5e62e218cc1d'::uuid, 'Barbell stiff leg deadlift', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with an overhand grip (palms facing down), hands placed slightly wider than shoulder-width apart. Your arms should be fully extended, and the barbell should rest against your thighs.\r\n2. Slightly bend your knees and hinge at your hips to lower the barbell toward your feet. Keep your legs mostly straight but not locked.\r\n3. Lower the barbell down the front of your legs until you feel a stretch in your hamstrings. Your back should remain straight throughout the movement.\r\n4. Lift the barbell back up to the starting position by extending your hips, squeezing your glutes at the top. Repeat for the desired number of repetitions.', E'1. Keep your back straight throughout the movement to avoid rounding your spine.\r\n2. Focus on hinging at your hips rather than bending your lower back.\r\n3. Ensure your knees are slightly bent to avoid locking them and putting stress on your joints.', '{"image_male_start":"images/Legs/Barbell stiff leg deadlift.jpg","image_male_end":"images/Legs/Barbell stiff leg deadlift1.jpg","video_url":"videos/Legs/Barbell stiff leg deadlift.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6be77402-fabb-43da-b445-28ab2743b90c'::uuid, 'Barbell straight leg deadlift', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with an overhand grip (palms facing down), hands placed slightly wider than shoulder-width apart. Your arms should be fully extended, and the barbell should rest against your thighs.\r\n2. Keep your legs straight but not locked as you hinge at your hips to lower the barbell toward your feet.\r\n3. Lower the barbell down the front of your legs until you feel a stretch in your hamstrings. Your back should remain straight throughout the movement.\r\n4. Lift the barbell back up to the starting position by extending your hips, squeezing your glutes at the top. Repeat for the desired number of repetitions.', E'1. Keep your back straight throughout the movement to avoid rounding your spine.\r\n2. Focus on hinging at your hips rather than bending your lower back.\r\n3. Ensure your knees are slightly bent to avoid locking them and putting stress on your joints.', '{"image_male_start":"images/Legs/Barbell straight leg deadlift.jpg","image_male_end":"images/Legs/Barbell straight leg deadlift1.jpg","video_url":"videos/Legs/Barbell straight leg deadlift.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4dd217fe-d7e3-456c-b906-092bc88fe593'::uuid, 'Barbell sumo deadlift', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet wider than shoulder-width apart and your toes pointing slightly outward. Position a barbell on the floor in front of you, and squat down to grip the barbell with both hands inside your legs, using an overhand grip (palms facing down).\r\n2. Drive through your heels and extend your hips and knees simultaneously to lift the barbell off the floor. Keep the barbell close to your body and your arms straight as you stand up.\r\n3. Once you reach the top position, squeeze your glutes and stand tall. Slowly lower the barbell back to the floor by bending at the hips and knees, maintaining a straight back. Repeat for the desired number of repetitions.\r\n', E'1. Keep your chest up and back straight throughout the movement to avoid rounding your spine.\r\n2. Drive through your heels to lift the barbell and engage your glutes and hamstrings.\r\n3. Breathe steadily, exhaling as you lift the barbell and inhaling as you lower it back down.', '{"image_male_start":"images/Back/Barbell sumo deadlift.jpg","image_male_end":"images/Back/Barbell sumo deadlift1.jpg","video_url":"videos/Back/Barbell sumo deadlift.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('bcd0421c-ca95-4add-8179-2c8e5920b9f4'::uuid, 'Barbell sumo romanian deadlift', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet wider than shoulder-width apart and your toes pointing slightly outward. Hold a barbell with an overhand grip (palms facing down), hands placed inside your legs. Your arms should be fully extended, and the barbell should rest against your thighs.\r\n2. Slightly bend your knees and hinge at your hips to lower the barbell toward your feet. Keep your legs mostly straight but not locked.\r\n3. Lower the barbell down the front of your legs until you feel a stretch in your hamstrings. Your back should remain straight throughout the movement.\r\n4. Lift the barbell back up to the starting position by extending your hips, squeezing your glutes at the top. Repeat for the desired number of repetitions.', E'1. Keep your back straight throughout the movement to avoid rounding your spine.\r\n2. Focus on hinging at your hips rather than bending your lower back.\r\n3. Ensure your knees are slightly bent to avoid locking them and putting stress on your joints.\r\n', '{"image_male_start":"images/Legs/Barbell sumo romanian deadlift.jpg","image_male_end":"images/Legs/Barbell sumo romanian deadlift1.jpg","video_url":"videos/Legs/Barbell sumo romanian deadlift.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4e7856a7-5a6b-4d34-9e52-bf87d2845d68'::uuid, 'Barbell thruster', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with an overhand grip (palms facing forward), hands placed slightly wider than shoulder-width apart. Position the barbell at shoulder height.\r\n2. Lower your body into a squat by bending your knees and hips, ensuring your thighs are just lower than your knees.\r\n3. Push through your heels to extend your legs and return to a standing position. As you rise, simultaneously press the barbell overhead by extending your arms fully.\r\n4. Lower the barbell back to shoulder height and immediately descend into the next squat. Repeat the movement for the desired number of repetitions.', E'1. Drive through your heels during the squat to engage your glutes and quadriceps.\r\n2. Breathe steadily, exhaling as you press the barbell overhead and inhaling as you lower it back down.\r\n3. Ensure a fluid transition from the squat to the overhead press to maximize efficiency.', '{"image_male_start":"images/Powerlifting/Barbell Thruster.jpg","image_male_end":"images/Powerlifting/Barbell Thruster1.jpg","video_url":"videos/Powerlifting/Barbell Thruster.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0d3154f5-e0ac-4df9-84f9-0780f5f813d0'::uuid, 'Barbell underhand bent over row', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with an underhand grip (palms facing up), hands placed slightly wider than shoulder-width apart. \r\n2. Slightly bend your knees and hinge at your hips, keeping your back straight and torso slightly above parallel to the floor. Allow the barbell to hang directly in front of you with your arms fully extended.\r\n3. Pull the barbell toward your lower ribcage by bending your elbows, keeping them close to your body. Squeeze your shoulder blades together at the top of the movement.\r\n4. Slowly lower the barbell back to the starting position by extending your arms fully. Repeat for the desired number of repetitions.', E'1. Keep your back straight throughout the movement to avoid rounding your spine.\r\n2. Focus on squeezing your shoulder blades together at the top of the movement to maximize muscle engagement.\r\n3. Keep your elbows close to your body throughout the movement to effectively target your back muscles.\r\n', '{"image_male_start":"images/Back/Barbell Underhand Bent over Row.jpg","image_male_end":"images/Back/Barbell Underhand Bent over Row1.jpg","video_url":"videos/Back/Barbell Underhand Bent over Row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c150cf2e-af3b-4cce-9bf2-dae6bc4b8224'::uuid, 'Barbell upright row', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with an overhand grip (palms facing down), hands placed shoulder-width apart. Allow the barbell to rest against your thighs with your arms fully extended.\r\n2. Pull the barbell upward along the front of your body by bending your elbows and lifting your upper arms.\r\n3. Continue lifting the barbell until it reaches chest height, keeping your elbows higher than your wrists throughout the movement.\r\n4. Slowly lower the barbell back to the starting position by extending your arms fully. Repeat for the desired number of repetitions.', E'1. Lead with your elbows to ensure proper muscle engagement and avoid wrist strain.\r\n2. Breathe steadily, exhaling as you lift the barbell and inhaling as you lower it back down.\r\n3. Avoid using momentum or swinging your body to lift the barbell.', '{"image_male_start":"images/Back/Barbell Upright Row.jpg","image_male_end":"images/Back/Barbell Upright Row1.jpg","video_url":"videos/Back/Barbell Upright Row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c700d156-5f7c-4074-89ed-0e086a0e9558'::uuid, 'Barbell wide bench press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Lie flat on a bench with your feet firmly planted on the floor. Hold a barbell with an overhand grip (palms facing forward), hands placed wider than shoulder-width apart. Position the barbell directly above your chest with your arms fully extended.\r\n2. Slowly lower the barbell to your chest by bending your elbows, keeping them at a 45-degree angle to your body.\r\n3. Once the barbell lightly touches your chest, push the barbell back up to the starting position by extending your arms fully.\r\n4.  Repeat for the desired number of repetitions.', E'1. Keep your chest up and shoulders retracted throughout the movement to maximize chest engagement.\r\n2. Breathe steadily, exhaling as you press the barbell up and inhaling as you lower it back down.\r\n3. Keep your feet firmly planted on the floor for stability and support.\r\n', '{"image_male_start":"images/Chest/Barbell Wide Bench Press.jpg","image_male_end":"images/Chest/Barbell Wide Bench Press1.jpg","video_url":"videos/Chest/Barbell Wide Bench Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f73644bc-7e43-4b8a-816e-c4967d7aaaaa'::uuid, 'Barbell wide grip biceps curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with an underhand grip (palms facing up), hands placed wider than shoulder-width apart, arms hanging straight.\r\n2. Curl the barbell upward towards your shoulders by bending your elbows. Keeping your upper arms stationary and close to your body.\r\n3. Continue lifting the barbell until your biceps are fully contracted and the bar is at shoulder level.\r\n4. Slowly lower the barbell back to the starting position by extending your arms fully. Repeat for the desired number of repetitions.', E'1. Keep your upper arms stationary to focus the effort on your biceps.\r\n2. Avoid swinging your body or using momentum to lift the barbell.\r\n3. Breathe steadily, exhaling as you curl the barbell up and inhaling as you lower it back down.', '{"image_male_start":"images/Biceps/barbell wide grip biceps curl.jpeg","video_url":"videos/Biceps/barbell wide grip biceps curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('bf665dc1-59cf-41f0-8656-46636d8bdfe9'::uuid, 'Barbell wide grip upright row', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with an overhand grip (palms facing down), hands placed wider than shoulder-width apart. Allow the barbell to rest against your thighs with your arms fully extended.\r\n2. Pull the barbell upward along the front of your body by bending your elbows and lifting your upper arms.\r\n3. Continue lifting the barbell until it reaches chest height, keeping your elbows higher than your wrists throughout the movement.\r\n4. Slowly lower the barbell back to the starting position by extending your arms fully. Repeat for the desired number of repetitions.', E'1. Keep your chest up and back straight throughout the movement to avoid leaning forward.\r\n2. Lead with your elbows to ensure proper muscle engagement and avoid wrist strain.\r\n3. Avoid using momentum or swinging your body to lift the barbell.\r\n', '{"image_male_start":"images/Back/Barbell wide grip Upright Row.jpg","image_male_end":"images/Back/Barbell wide grip Upright Row1.jpg","video_url":"videos/Back/Barbell wide grip Upright Row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4a725c5e-52c9-4a29-8cae-b639f9b4d232'::uuid, 'Barbell wide shrug', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with an overhand grip (palms facing down), hands placed wider than shoulder-width apart. Allow the barbell to rest against your thighs with your arms fully extended.\r\n2. Raise your shoulders towards your ears as high as possible, keeping your arms straight and the barbell close to your body.\r\n3. Hold the contraction at the top for a moment, squeezing your shoulder blades together.\r\n4. Slowly lower your shoulders back to the starting position. Repeat for the desired number of repetitions.', E'1. Keep your arms straight and avoid using your biceps to lift the barbell.\r\n2. Focus on using your trapezius muscles to lift your shoulders, not your arms.\r\n3. Breathe steadily, exhaling as you lift your shoulders and inhaling as you lower them back down.', '{"image_male_start":"images/Shoulders/Barbell Wide Shrug.jpg","image_male_end":"images/Shoulders/Barbell Wide Shrug1.jpg","video_url":"videos/Shoulders/Barbell Wide Shrug.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d0b855c2-2c17-430c-9fb2-170913f6c531'::uuid, 'Barbell wrist curl on knees', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Sit on a bench with your feet flat on the floor, holding a barbell with an underhand grip (palms facing up), hands placed shoulder-width apart. Rest your forearms on your thighs, allowing your wrists to hang over the edge.\r\n2. Start with your wrists extended so the barbell is lowered as much as possible while maintaining control.\r\n3. Curl the barbell upward by flexing your wrists, lifting the barbell as high as possible while keeping your forearms stationary on your thighs.\r\n4. Slowly lower the barbell back to the starting position by extending your wrists. Repeat for the desired number of repetitions.', E'1. Keep your forearms stationary on your thighs to isolate your wrist flexors.\r\n2. Avoid using your elbows to lift the barbell; focus on your wrist movement.\r\n3. Breathe steadily, exhaling as you curl the barbell up and inhaling as you lower it back down.', '{"image_male_start":"images/Forearms/barbell wrist curl on knees.jpeg","video_url":"videos/Forearms/barbell wrist curl on knees.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8da5b0ae-748b-433d-9d4d-31dec49b1be5'::uuid, 'Barbell wrist curl wide legs', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Sit on a bench with your feet spread wide apart, holding a barbell with an underhand grip (palms facing up), hands placed shoulder-width apart. Rest your forearms on the edge of the bench, allowing your wrists to hang over the edge.\r\n2. Start with your wrists extended so the barbell is lowered as much as possible.\r\n3. Curl the barbell upward by flexing your wrists, lifting the barbell as high as possible while keeping your forearms stationary on your thighs.\r\n4. Slowly lower the barbell back to the starting position by extending your wrists. Repeat for the desired number of repetitions.', E'1. Keep your forearms stationary on your thighs to isolate your wrist flexors.\r\n2. Avoid using your elbows to lift the barbell; focus on your wrist movement.\r\n3. Breathe steadily, exhaling as you curl the barbell up and inhaling as you lower it back down.', '{"image_male_start":"images/Forearms/barbell wrist curl wide legs.jpeg","video_url":"videos/Forearms/barbell wrist curl wide legs.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('344e32f2-55a7-4032-8e6a-deb3d19bd6d5'::uuid, 'Barbell wrist extension on knees', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Sit on a bench with your feet flat on the floor, holding a barbell with an overhand grip (palms facing down), hands placed shoulder-width apart. Rest your forearms on your thighs, allowing your wrists to hang over the edge.\r\n2.  Start with your wrists relaxed so the barbell hangs as much as possible.\r\n3. Extend the barbell upward by extending your wrists, raising the barbell as far as possible while keeping your forearms stationary on your thighs.\r\n4. Slowly bring the barbell back to the starting position by relaxing your wrists. Repeat for the desired repetitions.', E'1. Keep your forearms stationary on your thighs to isolate your wrist extensors.\r\n2. Avoid using your elbows to lift the barbell; focus on your wrist movement.\r\n3. Breathe steadily, exhaling as you extend the barbell down and inhaling as you curl it back up.', '{"image_male_start":"images/Forearms/Barbell wrist extension on knees.jpeg","video_url":"videos/Forearms/Barbell wrist extension on knees.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6b5a52ee-6815-4944-a5f5-e33a3df3d682'::uuid, 'Basic toe touch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart.\r\n2. Bend at the hips and reach down towards your toes, keeping your legs as straight as possible.\r\n3. Hold the stretch for a few seconds, feeling the stretch in your hamstrings and lower back.\r\n4. Return to the standing position and repeat the movement.', E'1. Keep your back straight as you bend to avoid straining your lower back.\r\n2. Avoid bouncing or jerking movements; perform the stretch slowly and with control.\r\n3. Breathe deeply and steadily to help relax your muscles and enhance the stretch.', '{"image_male_start":"images/Yoga/Basic Toe Touch.jpg","image_male_end":"images/Yoga/Basic Toe Touch1.jpg","video_url":"videos/Yoga/Basic Toe Touch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('572fe296-ea0c-42a1-8de8-c8da7c8c06dd'::uuid, 'Basketball shot jump', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start in a squat position with your feet shoulder-width apart and your hands mimicking holding a basketball.\r\n2. Thrust upwards explosively from the squat position to jump, extending your legs and arms as if shooting a basketball.\r\n3. Land softly with your feet flat on the floor, bending your knees to absorb the impact.\r\n4. Return to the squat position and repeat the movement.', E'1. Maintain a consistent squat depth to ensure proper form and muscle engagement throughout the exercise.\r\n2. Focus on using your legs to generate power for the jump, not just your arms.\r\n3. Keep your movements controlled to prevent injury and maximize muscle activation.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Basketball Shot Jump.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Basketball Shot Jump1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Basketball Shot Jump.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('99f5bac1-d799-414a-a16c-34c40fe448fc'::uuid, 'Behind neck lat pull down machine', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd8a6a67e-71db-4542-9dd7-a185a3e773af'::uuid, E'1. Sit at a lat pulldown machine with your feet flat on the floor. Grasp the bar with a wide overhand grip (palms facing forward).\r\n2. Lean slightly forward and pull the bar down behind your neck, keeping your elbows pointed down.\r\n3. Squeeze your shoulder blades together as you bring the bar down to the back of your neck.\r\n4. Slowly return the bar to the starting position, extending your arms fully without locking your elbows. Repeat the movement for the desired number of repetitions.', E'1. Maintain a slight forward lean to avoid excessive neck strain.\r\n2. Breathe steadily, exhaling as you pull the bar down and inhaling as you return to the starting position.\r\n3. Ensure the knee pad is securely positioned to prevent your legs from lifting during the movement.', '{"image_male_start":"images/Back/behind neck lat pull down machine .jpg","video_url":"videos/Back/behind neck lat pull down machine .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('be3d7f58-3e23-4ab7-9061-2020a665fab6'::uuid, 'Behind neck press Resistance band cable', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand tall with your back straight, feet shoulder-width apart, and a resistance band under your feet.\r\n2. Hold the ends of the band near your shoulders with your arms folded at the sides.\r\n3. Stretch the band by extending your arms overhead.\r\n4. As your arms become straight, return to the initial position, and repeat.', E'1. Engage your core to help stabilize your body and prevent unnecessary movement.\r\n2. Breathe steadily, exhaling as you press the band upwards and inhaling as you return to the starting position.\r\n3. Keep your elbows slightly bent at the top of the movement to avoid locking them out.', '{"image_male_start":"images/Shoulders/behind neck press resistance band cable .jpg","video_url":"videos/Shoulders/behind neck press resistance band cable .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9b27e800-b2a0-4d3b-ac90-d2ee228a8e10'::uuid, 'Bench alternating step ups', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand in front of a bench with your feet shoulder-width apart.\r\n2. Step up onto the bench with your right foot, then bring your left foot up to meet your right foot, standing fully on the bench.\r\n3. Step down with your left foot, followed by your right foot, and then repeat the movement with your left foot stepping up first.\r\n4. Continue alternating step ups on bench in a controlled, rhythmic manner.', E'1. Ensure the bench is stable and secure before beginning the exercise to avoid slipping or tipping.\r\n2. Maintain an upright posture, keeping your chest lifted and shoulders back to ensure proper form.\r\n3. Focus on driving through your heel as you step up to maximize glute and leg engagement.', '{"image_male_start":"images/Legs/bench alternating step ups  .jpg","video_url":"videos/Legs/bench alternating step ups  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('55375503-52c7-4482-b510-bf0a6562cf3c'::uuid, 'Bench Bulgarian Split Squats', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand a few feet in front of a bench with your back to the bench.\r\n2. Extend one of your legs back and place the top of your foot on the bench.\r\n3. Lower your body into a squat by bending your other knee, keeping your torso upright.\r\n4. Push through your floored heel to return to the starting position, and repeat the movement.', E'1. Focus on keeping your torso upright and avoid leaning forward to ensure proper form.\r\n2. Use a mirror or ask for feedback to ensure your knee stays aligned with your foot and doesn’t cave inward.\r\n3. Keep your movements smooth and controlled, ensuring you lower and lift yourself with even tempo.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8600c00a-3368-489c-89f1-6e46bd42a647'::uuid, 'Bench Bulgarian Split Squats left', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand a few feet in front of a bench with your back to the bench.\r\n2. Extend your left leg back and place the top of your foot on the bench.\r\n3. Lower your body into a squat by bending your right knee, keeping your torso upright.\r\n4. Push through your right heel to return to the starting position, and repeat the movement.', E'1. Focus on keeping your torso upright and avoid leaning forward to ensure proper form.\r\n2. Use a mirror or ask for feedback to ensure your knee stays aligned with your foot and doesn’t cave inward.\r\n3. Keep your movements smooth and controlled, ensuring you lower and lift yourself with even tempo.', '{"image_male_start":"images/Legs/Bench Bulgarian Split Squats left  .jpg","video_url":"videos/Legs/Bench Bulgarian Split Squats left  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4915706f-6689-4a63-ae11-1fd19bbd7928'::uuid, 'Bench Bulgarian Split Squats Right', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand a few feet in front of a bench with your back to the bench.\r\n2. Extend your right leg back and place the top of your foot on the bench.\r\n3. Lower your body into a squat by bending your left knee, keeping your torso upright.\r\n4. Push through your left heel to return to the starting position, and repeat the movement.', E'1. Focus on keeping your torso upright and avoid leaning forward to ensure proper form.\r\n2. Use a mirror or ask for feedback to ensure your knee stays aligned with your foot and doesn’t cave inward.\r\n3. Keep your movements smooth and controlled, ensuring you lower and lift yourself with even tempo.', '{"image_male_start":"images/Legs/Bench Bulgarian Split Squats Right  .jpg","video_url":"videos/Legs/Bench Bulgarian Split Squats Right  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5ec04e32-2f2f-40ac-bc22-56b72b7a4736'::uuid, 'Bench decline ab sit-ups', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on a decline bench with your feet secured under the foot pads.\r\n2. Place your hands behind your head or cross them over your chest.\r\n3. Engage your core and lift your upper body towards your knees, performing a crunch.\r\n4. Lower your upper body back down to the starting position, maintaining control throughout the movement.', E'1. Keep your chin slightly tucked to maintain a neutral spine position and prevent neck strain.\r\n2. Focus on squeezing your abdominal muscles at the top of the crunch to enhance muscle engagement.\r\n3. Breathe out as you lift your body and breathe in as you lower it to maintain a steady rhythm and maximize oxygen flow.', '{"video_url":"videos/Abdominals/bench decline ab sit-ups.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0c7a762b-3d7f-4869-9616-44053a9f8b60'::uuid, 'Bench dip (knees bent)', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on the edge of a bench with your hands placed on the bench beside your hips.\r\n2. Slide your hips off the bench, supporting your body with your hands, and bend your knees at a 90-degree angle with your feet flat on the floor.\r\n3. Lower your body by bending your elbows until your upper arms are parallel to the floor.\r\n4. Push through your palms to raise your body back to the starting position.', E'1. Keep your elbows pointed backward and close to your body to engage your triceps effectively.\r\n2. Avoid locking your elbows at the top of the movement to maintain tension in your triceps.\r\n3. Perform the movement slowly and with control to maximize muscle activation and prevent injury.', '{"image_male_start":"images/Triceps/Bench Dip (knees bent).jpeg","video_url":"videos/Triceps/Bench Dip (knees bent).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1b21185e-9432-479c-a13f-f7f828f393fc'::uuid, 'Bench dip on floor', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on a bench and place your hands on its edge near your hips.\r\n2. Walk your feet out, extend your legs, shift your weight on heels, and take your hips off the bench while holding the bench with straight arms.\r\n3. Lower your hips down by folding your arms and legs.\r\n4. As your arms form a 90-degree angle, raise your hips and repeat.', E'1. Keep your elbows pointed backward and close to your body to engage your triceps effectively.\r\n2. Engage your core and glutes to keep your body stable.\r\n3. Keep your shoulders down and away from your ears to avoid strain and ensure proper alignment.', '{"image_male_start":"images/Triceps/Bench dip on floor.jpeg","video_url":"videos/Triceps/Bench dip on floor.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a6266439-7d7e-4efe-83be-5475572a4d54'::uuid, 'Bench knee tucks', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on the edge of a bench with your hands placed beside your hips for support.\r\n2. Lean back slightly and lift your feet off the floor with your legs extended straight out.\r\n3. Pull your knees towards your chest, tucking them in while engaging your core.\r\n4. Extend your legs back out to the starting position, maintaining control throughout the movement.', E'1. Keep your core engaged throughout the exercise to maintain stability and proper form.\r\n2. Avoid using momentum; focus on using your abdominal muscles to pull your knees in.\r\n3. Breathe steadily, exhaling as you tuck your knees in and inhaling as you extend your legs out.', '{"image_male_start":"images/Abdominals/bench knee tucks.jpeg","video_url":"videos/Abdominals/bench knee tucks .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2c4dfba5-0792-47e9-8308-bcca95beddd9'::uuid, 'Bench pull-ups', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '54938b47-43e8-47cd-9efc-18b4424e71e1'::uuid, E'1. Position yourself under a pull-up bar with one foot placed on a bench for support.\r\n2. Grip the pull-up bar with both hands, using an overhand grip, shoulder-width apart.\r\n3. Pull your chest towards the bar, engaging your back and arm muscles.\r\n4. Lower yourself back down to the starting position in a controlled manner, keeping your core engaged.', E'1. Ensure the bench is stable and your supporting foot is firmly placed to maintain balance.\r\n2. Focus on using your back muscles to pull yourself up rather than relying solely on your arms.\r\n3. Breathe steadily, exhaling as you pull up and inhaling as you lower yourself down.', '{"image_male_start":"images/Back/Bench Pull-ups.jpg","image_male_end":"images/Back/Bench Pull-ups1.jpg","video_url":"videos/Back/Bench Pull-ups.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7fccb0c4-84bf-4912-b7c5-f0c683620918'::uuid, 'Bench Reverse Plank Hold', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Place your feet on a bench with your legs extended and your hands on the floor directly under your shoulders, arms straight.\r\n2. Lift  your hips straight until torso comes parallel to the floor.\r\n3. Hold this position, keeping your core engaged and maintaining a straight line from head to heels.\r\n4. Maintain the hold for the designated period, focusing on stability and muscle engagement.\r\n', E'1. Engage your core and glutes to maintain a straight and stable torso throughout the hold.\r\n2. Keep your elbows slightly bent to avoid locking your joints and ensure muscle engagement.\r\n3. Breathe steadily and avoid holding your breath to maintain control and endurance during the hold.', '{"image_male_start":"images/Yoga/Bench Reverse Plank Hold.jpg","image_male_end":"images/Yoga/Bench Reverse Plank Hold1.jpg","video_url":"videos/Yoga/Bench Reverse Plank Hold.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ab4507a6-d8b4-42c3-9590-55d1af83544a'::uuid, 'Bench triceps dip leg curls', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit down on a bench and place your hands on its edge near your hips.\r\n2. Walk your feet out, extend your legs, and lift your hips off the bench while holding the bench.\r\n3. Lower your hips down by folding your arms and bending your knees.\r\n4. As your arms form a 90-degree angle, raise your hips while extending your legs, and repeat.', E'1. Keep your elbows pointed backward and close to your body to engage your triceps effectively.\r\n2. Maintain a controlled movement for both the dip and the leg curl to maximize muscle activation.\r\n3. Engage your core to maintain stability and proper form throughout the exercise.', '{"image_male_start":"images/Triceps/bench triceps dip leg curls.jpeg","video_url":"videos/Triceps/bench triceps dip leg curls  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8e62d389-be82-4cf5-b951-c15e32c8f9fa'::uuid, 'Bench triceps dip straight legs', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit down on a bench and place your hands on the edge near your hips.\r\n2. Walk your feet out, straighten your legs, and lift your hips off the bench while holding the bench.\r\n3. Lower your hips down by folding your arms.\r\n4. As your arms form a 90-degree angle, raise your hips, and repeat.', E'1. Keep your elbows pointed backward and close to your body to engage your triceps effectively.\r\n2. Maintain a straight line from your hips to your heels to ensure proper form.\r\n3. Perform the movement slowly and with control to maximize muscle activation and prevent injury.', '{"image_male_start":"images/Triceps/bench triceps dip straight legs.jpeg","video_url":"videos/Triceps/bench triceps dip straight legs  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9b2c30bc-b3c4-49c0-be09-65d07f564063'::uuid, 'Bent arm chest stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand beside a wall and place your bent arm (elbow at a 90-degree angle) against the wall, with your forearm and hand flat against the wall.\r\n2. Gently rotate your torso away from the wall to feel a stretch in your chest.\r\n3. Hold this position for 15-30 seconds, then switch sides and repeat.', E'1. Keep your shoulder down and away from your ear to avoid strain and ensure proper alignment.\r\n2. Rotate your torso slowly to control the intensity of the stretch and prevent overstretching.\r\n3. Breathe deeply and steadily to help relax your muscles and enhance the stretch.', '{"image_male_start":"images/Stretching - Mobility/Bent Arm Chest Stretch.jpg","image_male_end":"images/Stretching - Mobility/Bent Arm Chest Stretch1.jpg","video_url":"videos/Stretching - Mobility/Bent Arm Chest Stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('cf4ff0fe-025e-4bc7-9800-b51a0e61bb77'::uuid, 'Bent knee back to side kick', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start on your hands and knees in a tabletop position, with your wrists aligned under your shoulders and your knees under your hips.\r\n2. Lift your right knee off the floor and extend it backward while keeping it bent at a 90-degree angle.\r\n3. Bring your right knee back down to the starting position.\r\n4. Lift your right knee out to the side until it is parallel to the floor, then return it to the starting position. Repeat the movement on the left side after completing the desired number of repetitions.', E'1. Keep your head in a neutral position, looking down at the floor to maintain proper alignment.\r\n2. Focus on squeezing your glutes during the movement to enhance muscle activation.\r\n3. Maintain a steady breathing pattern, exhaling as you lift your leg and inhaling as you lower it.', '{"image_male_start":"images/Legs/Bent Knee Back to Side Kick.jpg","image_male_end":"images/Legs/Bent Knee Back to Side Kick1.jpg","video_url":"videos/Legs/Bent Knee Back to Side Kick.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('79e72ac7-4f3a-4cda-87a8-84c0f65ff18c'::uuid, 'Bent knee lying twist', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your arms extended out to the sides, forming a T shape.\r\n2. Bend your knees and lift your feet off the floor, bringing your upper legs vertical to the floor.\r\n3. Lower your bent knees to one side, keeping your torso and arms flat on the floor.\r\n4. Then bring your knees back to the center and lower them to the opposite side. Repeat the movement for the desired number of repetitions.', E'1. Keep your shoulders flat on the floor to maximize the stretch in your spine and obliques.\r\n2. Move slowly and with control to avoid straining your back.\r\n3. Breathe deeply and steadily, exhaling as you lower your knees to the side and inhaling as you bring them back to the center.', '{"image_male_start":"images/Abdominals/Bent knee Lying Twist.jpeg","video_url":"videos/Abdominals/Bent knee Lying Twist.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7d5b76eb-122c-4fd8-a2c3-dbd5cd8e0d75'::uuid, 'Bent knee lying twist (on stability ball)', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '4e9ce883-ea47-492d-be41-fc224e54b4c7'::uuid, E'1. Lie on your back on the floor with your arms extended out to the sides to form a T shape.\r\n2. Place your bent legs on top of an exercise ball.\r\n3. Lower your bent knees to one side, keeping your torso and arms flat on the floor.\r\n4. Then bring your knees back to the center and lower them to the opposite side. Repeat the movement for the desired number of repetitions.', E'1. Keep your shoulders flat on the floor to maximize the stretch in your spine and obliques.\r\n2. Move slowly and with control to avoid straining your back.\r\n3. Breathe deeply and steadily, exhaling as you lower your knees to the side and inhaling as you bring them back to the center.', '{"image_male_start":"images/Abdominals/Bent knee Lying Twist (On Stability Ball).jpeg","video_url":"videos/Abdominals/Bent knee Lying Twist (On Stability Ball).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('722d4ebe-5ffc-4943-9a4e-e3f582e08a72'::uuid, 'Bent leg side kick (kneeling)', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start on your hands and knees in a tabletop position, with your wrists aligned under your shoulders and your knees under your hips.\r\n2. Lift your right knee off the floor in a swift motion and raise it sideways until it is level with your hip, keeping your leg bent at a 90-degree angle.\r\n3. Lower your right knee back to the starting position.\r\n4. Repeat the movement for the desired number of repetitions, then switch to the left leg.', E'1. Ensure your hands are directly under your shoulders to provide a stable base for the movement.\r\n2. Focus on engaging your glutes as you lift your leg to enhance muscle activation.\r\n3. Avoid leaning to the side; keep your upper body stable during the exercise.', '{"image_male_start":"images/Legs/Bent Leg Side Kick (kneeling).jpg","image_male_end":"images/Legs/Bent Leg Side Kick (kneeling)1.jpg","video_url":"videos/Legs/Bent Leg Side Kick (kneeling).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('13d73aef-ca04-48a5-810d-5e91a6efd3ef'::uuid, 'Bent over barbell row', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with an overhand grip (palms facing down), hands placed shoulder-width apart. Bend your knees slightly and hinge forward at the hips until your torso is almost parallel to the floor.\r\n2. Let the barbell hang directly in front of you with your arms fully extended. Pull the barbell towards your lower chest by bending your elbows and squeezing your shoulder blades together.\r\n3. Slowly lower the barbell back to the starting position by extending your arms fully. Repeat for the desired number of repetitions.\r\n', E'1. Keep your back flat and avoid rounding your shoulders or lower back.\r\n2. Squeeze your shoulder blades together at the top of the movement to maximize upper back engagement.\r\n3. Avoid using momentum or swinging your body to lift the barbell.\r\n', '{"image_male_start":"images/Back/bent over barbell row.jpg","image_male_end":"images/Back/bent over barbell row1.jpg","video_url":"videos/Back/bent over barbell row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('70d9f512-7b56-4288-8669-07c9086fba7d'::uuid, 'Bent over rear delt fly dumbbell', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with a neutral grip (palms facing each other). Bend your knees slightly and hinge forward at the hips until your torso is almost parallel to the floor. Keep your back straight and your core engaged.\r\n2. Let the dumbbells hang directly below you with your arms fully extended. Maintain a neutral spine throughout the movement.\r\n3. Lift the dumbbells out to the sides by raising your arms until they are in line with your shoulders. Keep a slight bend in your elbows and focus on squeezing your shoulder blades together at the top of the movement.\r\n4. Slowly lower the dumbbells back to the starting position by bringing your arms back down. Repeat for the desired number of repetitions.\r\n', E'1. Keep your back flat and avoid rounding your shoulders or lower back.\r\n2. Focus on using your rear deltoids to lift the weights, not your traps or biceps.\r\n3. Avoid using momentum or swinging your body to lift the dumbbells.', '{"image_male_start":"images/Shoulders/bent over rear delt fly dumbbell.jpg","image_male_end":"images/Shoulders/bent over rear delt fly dumbbell1.jpg","video_url":"videos/Shoulders/bent over rear delt fly dumbbell.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('275bd8ad-4990-49a9-ab7e-c68b6099aa7b'::uuid, 'Bent over rear deltoid fly Resistance band', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart, holding the ends of the resistance band anchored under your feet. Hinge at the hips with a slight bend in your knees to bring your torso almost parallel to the floor.\r\n2. Start with your arms hanging down towards the floor, palms facing back, and a slight bend in your elbows.\r\n3. Raise your arms out to the sides, forming a "T" shape, keeping a slight bend in your elbows and leading with your elbows. Squeeze your shoulder blades together at the top of the movement.\r\n4. Slowly return to the starting position. Repeat the movement for the desired number of repetitions.', E'1. Maintain a neutral spine throughout the exercise to avoid straining your lower back.\r\n2. Keep your elbows slightly bent to avoid joint strain and focus on lifting with your shoulders.\r\n3. Use a controlled motion to raise and lower your arms, preventing any jerking movements.', '{"image_male_start":"images/Shoulders/bent over rear deltoid fly resistance band.jpg","image_male_end":"images/Shoulders/bent over rear deltoid fly resistance band1.jpg","video_url":"videos/Shoulders/bent over rear deltoid fly resistance band.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('29343326-aed6-450c-be9d-2c22f7241a5c'::uuid, 'Bent over row Resistance band', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart, holding the handles of a resistance band anchored under your feet. Hinge at the hips with a slight bend in your knees to bring your torso almost parallel to the floor.\r\n2. Start with your arms extended towards the floor, holding the band with your palms facing each other.\r\n3. Pull the handles of the band towards your hips by bending your elbows, keeping them close to your body and squeezing your shoulder blades together at the top of the movement.\r\n4. Slowly return to the starting position, extending your arms back towards the floor. Repeat the movement for the desired number of repetitions.', E'1. Keep your elbows close to your body to maximize back engagement and minimize shoulder involvement.\r\n2. Squeeze your shoulder blades together at the top of the movement to enhance muscle activation.\r\n3. Breathe steadily, exhaling as you pull the band and inhaling as you return to the starting position.', '{"video_url":"videos/Back/bent over row resistance band.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('eaefd380-f934-47f0-9a54-d6894d999791'::uuid, 'Bent over twist', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, holding a straight bar behind your neck with both hands.\r\n2. Bend forward at the hips, keeping your back straight and your knees slightly bent, until your torso is parallel to the floor.\r\n3. Twist your torso to one side, bringing one end of the bar towards the ceiling.\r\n4. Return to the starting position and repeat the movement on the other side.', E'1. Keep your spine neutral to avoid unnecessary strain on your back.\r\n2. Focus on rotating your torso, not just your arms, to ensure you''re engaging your obliques effectively.\r\n3. Maintain even breathing throughout the exercise to help stabilize your core and keep movements fluid.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Bent Over Twist.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Bent Over Twist1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Bent Over Twist.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6ca8bcb7-28fd-4d74-b5a2-92596396bc1b'::uuid, 'Bent-over Row with bar', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'fbd5e391-2fec-4076-b75a-1f90d31b099e'::uuid, E'1. Stand with your feet shoulder-width apart, holding a bar with an underhand grip (palms facing up), hands placed shoulder-width apart. Bend your knees slightly and hinge forward at the hips until your torso is almost parallel to the floor.\r\n2. Let the bar hang directly in front of you with your arms fully extended. Pull the bar towards your abdomen by bending your elbows and squeezing your shoulder blades together.\r\n4. Slowly lower the bar back to the starting position by extending your arms fully. Repeat for the desired number of repetitions.\r\n', E'1. Squeeze your shoulder blades together at the top of the movement to maximize upper back engagement.\r\n2. Breathe steadily, exhaling as you pull the barbell up and inhaling as you lower it back down.\r\n3. Avoid using momentum or swinging your body to lift the barbell.', '{"image_male_start":"images/Back/Bent-over Row with bar.jpg","image_male_end":"images/Back/Bent-over Row with bar1.jpg","video_url":"videos/Back/Bent-over Row with bar.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('000d00d1-ef11-403a-b8d1-9289b66c0483'::uuid, 'Bicep curl low cable machine normal grip', 'Resistance', 'strength', 'weight_reps', 'intermediate', '6bee5d12-b738-4e9c-8561-dc0ca4c133aa'::uuid, E'1. Stand with your feet shoulder-width apart, facing a low cable crossover machine. Hold the handle attached to the low pulley with an underhand grip (palms facing up), hands at shoulder-width apart, arms fully extended and elbows close to your body.\r\n2. Curl the handle upwards towards your shoulders by bending your elbows, keeping your upper arms stationary.\r\n3. Slowly lower the handle back to the starting position, fully extending your arms.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Maintain an upright posture and avoid leaning back during the curl.\r\n2. Focus on squeezing your biceps at the top of the movement to enhance muscle activation.\r\n3. Perform the exercise slowly and with control to maximize muscle activation and reduce the risk of injury.', '{"image_male_start":"images/Biceps/bicep curl low cable machine normal grip.jpeg","video_url":"videos/Biceps/bicep curl low cable machine normal grip .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0d4375f4-3540-41d6-a360-613ee68834cd'::uuid, 'Biceps curl cable', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Stand with your feet shoulder-width apart, facing a low cable pulley. Hold the handle attached to the low pulley with an underhand grip (palms facing up), hands at shoulder-width apart, arms fully extended and elbows close to your body.\r\n2. Curl the handle upwards towards your shoulders by bending your elbows, keeping your upper arms stationary.\r\n3. Slowly lower the handle back to the starting position, fully extending your arms.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Maintain an upright posture and avoid leaning back during the curl.\r\n2. Focus on squeezing your biceps at the top of the movement to enhance muscle activation.\r\n3. Perform the exercise slowly and with control to maximize muscle activation and reduce the risk of injury.', '{"image_male_start":"images/Biceps/biceps curl cable.jpeg","video_url":"videos/Biceps/biceps curl cable .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('97920458-861e-471e-87f4-88d2431313fd'::uuid, 'Biceps curl cable wide grip', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Stand with your feet shoulder-width apart, facing a low cable pulley. Hold the handle attached to the low pulley with an underhand grip (palms facing up), hands just wider than shoulder-width apart, arms fully extended and elbows close to your body.\r\n2. Curl the handle upwards towards your shoulders by bending your elbows, keeping your upper arms stationary.\r\n3. Slowly lower the handle back to the starting position, fully extending your arms.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Maintain an upright posture and avoid leaning back during the curl.\r\n2. Focus on squeezing your biceps at the top of the movement to enhance muscle activation.\r\n3. Perform the exercise slowly and with control to maximize muscle activation and reduce the risk of injury.', '{"image_male_start":"images/Biceps/biceps curl cable wide grip.jpeg","video_url":"videos/Biceps/biceps curl cable wide grip .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c0f56b47-0fb3-4cfe-9941-3b15e9632a67'::uuid, 'Biceps curl cable wide grip crossover machine', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Stand with your feet shoulder-width apart, facing a low cable crossover machine. Hold the handle attached to the low pulley with an underhand grip (palms facing up), hands just wider than shoulder-width apart, arms fully extended and elbows close to your body.\r\n2. Curl the handle upwards towards your shoulders by bending your elbows, keeping your upper arms stationary.\r\n3. Slowly lower the handle back to the starting position, fully extending your arms.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Maintain an upright posture and avoid leaning back during the curl.\r\n2. Focus on squeezing your biceps at the top of the movement to enhance muscle activation.\r\n3. Perform the exercise slowly and with control to maximize muscle activation and reduce the risk of injury.', '{"image_male_start":"images/Biceps/biceps curl cable wide grip crossover machine.jpeg","video_url":"videos/Biceps/biceps curl cable wide grip crossover machine.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('fed60caa-23be-4c9a-8704-1e21ba993542'::uuid, 'Biceps curl front step', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and extend both arms forward parallel to the floor with palms facing upwards.\r\n2. Step forward with your right foot and touch the floor lightly, while performing a biceps curl with both arms bending your elbows to bring your hands towards your shoulders.\r\n3. Bring your right foot back to the starting position while extending both arms and repeat alternating legs.', E'1. Start with a slight bend in your knees to improve stability and balance during the exercise.\r\n2. Ensure your arms remain parallel to the floor during the initial step to maintain proper form.\r\n3. Perform the movement slowly and with control to maximize muscle activation and prevent injury.', '{"image_male_start":"images/Biceps/Biceps Curl Front Step.jpeg","video_url":"videos/Biceps/Biceps Curl Front Step.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b1516d53-3aaa-4751-abcf-2514e6dae5ac'::uuid, 'Biceps curl Resistance band', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart, placing the middle of the resistance band under your feet. Hold the handles of the band with your palms facing forward and arms fully extended down by your sides.\r\n2. Keeping your elbows close to your torso, slowly curl the handles of the band towards your shoulders by bending your elbows.\r\n3. Squeeze your biceps at the top of the curl, holding for a brief moment to maximize contraction.\r\n4. Slowly lower the handles of the band back to the starting position, fully extending your arms. Repeat the movement for the desired number of repetitions.', E'1. Keep your back straight and core engaged throughout the exercise to maintain proper posture and avoid strain.\r\n2. Do not use your shoulders or swing your body to lift the band; focus on isolating the biceps.\r\n3. Perform the movement slowly and with control to maximize muscle activation and reduce the risk of injury.', '{"image_male_start":"images/Biceps/biceps curl resistance band.jpeg","video_url":"videos/Biceps/biceps curl resistance band .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('90fc89b8-2058-479c-9f87-c9f655113c40'::uuid, 'Biceps curl to shoulder press Resistance band', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart, placing the middle of the resistance band under your feet. Hold the handles of the band with your palms facing forward and arms fully extended down by your sides.\r\n2. Perform a biceps curl by bending your elbows and bringing the handles of the band towards your shoulders, keeping your elbows close to your torso.\r\n3. From the biceps curl position, rotate your wrists so that your palms face forward, and press the handles of the band overhead by extending your arms fully. \r\n4. Lower the handles back to the starting position by reversing the steps. Repeat the movement for the desired number of repetitions.', E'1. Perform the movement slowly and with control to maximize muscle activation and reduce the risk of injury.\r\n2. Exhale as you press the band overhead and inhale as you lower it back down to maintain steady breathing.\r\n3. Avoid locking your elbows at the top of the shoulder press to keep tension on the muscles.', '{"image_male_start":"images/Biceps/biceps curl to shoulder press resistance band.jpeg","video_url":"videos/Biceps/biceps curl to shoulder press resistance band .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9ff0453c-0577-47b3-8cab-2f93a9f76f4d'::uuid, 'Biceps leg concentration curl', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on a bench with your legs apart and feet flat on the floor.\r\n2. Lean forward slightly and grab your hamstring with one hand, using your arm to support your leg.\r\n3. Perform a biceps curl by bending your elbow and lifting your leg towards your shoulder, using your biceps to curl your leg.\r\n4. Lower your leg back down to the starting position in a controlled manner. Repeat the movement for the desired number of repetitions, then switch legs.', E'1. Keep your upper arm stationary and close to your body to isolate the biceps muscle effectively.\r\n2. Avoid using momentum; focus on using your biceps to lift your leg.\r\n3. Breathe steadily, exhaling as you lift your leg and inhaling as you lower it.', '{"image_male_start":"images/Biceps/Biceps Leg Concentration Curl.jpeg","video_url":"videos/Biceps/Biceps Leg Concentration Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6c6e66e6-22cc-4569-9c51-6cb5993827e3'::uuid, 'Biceps stretch behind the back', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and clasp your hands together behind your back.\r\n2. Straighten your arms and pull your shoulders back to feel a stretch in your biceps.\r\n3. Keep your arms straight and maintain the stretch.\r\n4. Hold this position for 15-30 seconds, then return to the starting position.', E'1. Keep your back straight and avoid arching to maintain proper form.\r\n2. Ensure your hands are firmly clasped together to maximize the effectiveness of the stretch.\r\n3. Breathe deeply and steadily to help relax your muscles and enhance the stretch.', '{"image_male_start":"images/Stretching - Mobility/biceps stretch behind the back.jpg","image_male_end":"images/Stretching - Mobility/biceps stretch behind the back1.jpg","video_url":"videos/Stretching - Mobility/biceps stretch behind the back.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b09fe088-fbdb-44d2-8f00-dfc5d8091609'::uuid, 'Bicycle air legs', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back and lift your hips off the floor, supporting them with your hands while keeping your elbows on the floor.\r\n2. Perform a bicycle motion with your legs by extending your right leg straight forward while bending your left knee towards the floor.\r\n3. Switch legs by extending your left leg straight forward and bending your right knee towards the floor, continuing the bicycle motion.\r\n4. Maintain a controlled and steady pace throughout the exercise.', E'1. Ensure your hands are firmly supporting your lower back to maintain proper alignment and stability.\r\n2. Focus on engaging your core muscles to control the movement of your legs and prevent lower back strain.\r\n3. Ensure your movements are smooth and controlled to maximize muscle activation and prevent injury.', '{"image_male_start":"images/Yoga/Bicycle air legs.jpeg","video_url":"videos/Yoga/Bicycle air legs.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9af7f187-ad08-47c4-9322-2e9b9dfe6997'::uuid, 'Bicycle twisting crunch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your hands behind your head and your legs raised at 45 degrees off the floor, keeping them straight.\r\n2. Bring your right knee towards your chest while twisting your torso, bringing your left elbow towards your right knee.\r\n3. Alternate sides, bringing your left knee towards your chest and your right elbow towards your left knee, continuing in a controlled, bicycle-like motion.', E'1. Focus on using your abdominal muscles to perform the twist, rather than your neck or shoulders.\r\n2. Ensure your lower back stays pressed against the floor throughout the exercise to prevent strain.\r\n3. Avoid pulling on your neck with your hands; use your core muscles to lift and twist your torso.', '{"image_male_start":"images/Abdominals/bicycle twisting crunch.jpeg","video_url":"videos/Abdominals/bicycle twisting crunch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3b3aa5d3-15b0-4da7-b218-874db681b3f8'::uuid, 'Bicycles', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1.Lie on your back with your legs bent and lifted off the floor, and both arms straight to the floor.\r\n2. Bring your right knee towards your chest while straightening your left leg towards the floor without letting it touch the floor.\r\n3. Alternate sides by bringing your left knee towards your chest and straightening your right leg towards the floor, continuing in a controlled, bicycle-like motion.', E'1. Focus on using your abdominal muscles to control the movement of your legs.\r\n2. Ensure your lower back stays pressed against the floor throughout the exercise to prevent strain.\r\n3. Keep your movements slow and controlled to maximize muscle activation and avoid injury.', '{"image_male_start":"images/Abdominals/bicycles.jpeg","video_url":"videos/Abdominals/bicycles.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('212ade74-db12-47cb-862d-ba6cc18448c0'::uuid, 'Bicycles crunches', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your hands behind your head and your legs lifted off the floor.\r\n2. Bring your right knee towards your chest while extending your left leg out.\r\n3. Simultaneously twist your torso, bringing your left elbow towards your right knee.\r\n4. Alternate sides, bringing your left knee towards your chest and your right elbow towards your left knee, continuing in a controlled, bicycle-like motion.', E'1. Focus on using your abdominal muscles to perform the twist, rather than your neck or shoulders.\r\n2. Ensure your lower back stays pressed against the floor throughout the exercise to prevent strain.\r\n3. Keep your elbows wide and avoid pulling on your head to prevent neck strain.', '{"image_male_start":"images/Abdominals/bicycles crunches.jpeg","video_url":"videos/Abdominals/bicycles crunches .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c00b95ce-b1ec-4135-8272-c5564e979912'::uuid, 'Bird dog', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start in a tabletop position on your hands and knees, with your wrists aligned under your shoulders and your knees under your hips.\r\n2. Extend your left leg backward, toes extended back, and right arm forward simultaneously, keeping your extending arm straight, until both are parallel to the floor.\r\n3. Hold this position briefly, maintaining balance and stability.\r\n4. Return to the starting position and repeat the movement with your left arm and right leg.', E'1. Engage your core to maintain stability and prevent your back from sagging.\r\n2. Keep your movements slow and controlled to maximize muscle activation and improve balance.\r\n3. Focus on keeping your extended arm and leg parallel to the floor to ensure proper form.', '{"image_male_start":"images/Yoga/Bird Dog.jpg","image_male_end":"images/Yoga/Bird Dog1.jpg","video_url":"videos/Yoga/Bird Dog.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('20ee92c7-1111-4ece-86ff-26b8adb6ea2d'::uuid, 'Bird dog (version 2)', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start in a tabletop position on your hands and knees, with your wrists aligned under your shoulders and your knees under your hips.\r\n2. Extend your left leg backward, and right arm forward simultaneously, keeping your extending arm straight, until both are slightly higher than torso level.\r\n3. Hold this position briefly, maintaining balance and stability.\r\n4. Return to the starting position and repeat the movement with your left arm and right leg.', E'1. Engage your core to maintain stability and prevent your back from sagging.\r\n2. Keep your movements slow and controlled to maximize muscle activation and improve balance.\r\n3. Maintain a neutral spine position by looking down at the floor during the exercise.', '{"image_male_start":"images/Yoga/Bird Dog (VERSION 2).jpg","image_male_end":"images/Yoga/Bird Dog (VERSION 2)1.jpg","video_url":"videos/Yoga/Bird Dog (VERSION 2).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('933f224b-2485-483f-9dfe-690f65bb9ebe'::uuid, 'Boat stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on the floor with your legs extended straight in front of you.\r\n2. Bend your knees slightly and lift your legs off the floor, balancing on your buttocks.\r\n3. Extend your arms forward, parallel to the floor, to grab your legs and lean back slightly while keeping your back straight.\r\n4. Hold this position, maintaining balance.', E'1. Engage your core to maintain balance and prevent your lower back from rounding.\r\n2. Keep your chest lifted and shoulders relaxed to ensure proper form.\r\n3. Breathe deeply and steadily to help maintain the stretch and balance.', '{"image_male_start":"images/Stretching - Mobility/Boat Stretch.jpg","image_male_end":"images/Stretching - Mobility/Boat Stretch1.jpg","video_url":"videos/Stretching - Mobility/Boat Stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0a69ab1a-01fd-4009-a353-7b025bd223d1'::uuid, 'Body saw plank', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start in a forearm plank position, with your elbows directly under your shoulders and your body forming a straight line from head to heels.\r\n2. Rock your body back by pushing through your forearms, moving your shoulders behind your elbows level.\r\n3. Rock your body forward by pulling with your forearms, moving your shoulders in front of your elbows level.\r\n4. Repeat this controlled forward and backward motion.', E'1. Focus on keeping your body in a straight line from head to heels to maintain proper form.\r\n2. Ensure your movements are slow and deliberate to enhance control and muscle engagement.\r\n3. Breathe steadily, exhaling as you rock forward and inhaling as you rock back.', '{"image_male_start":"images/Yoga/Body Saw Plank.jpeg","video_url":"videos/Yoga/Body Saw Plank.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8aea8a75-8840-417b-affc-282656058ffd'::uuid, 'Body slide', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet slightly wider than shoulder-width apart and extend your arms straight out at shoulder level.\r\n2. Slide your hips to the left, keeping your upper body and arms steady.\r\n3. Slide your hips to the right, maintaining control and keeping your arms extended.\r\n4. Continue sliding your hips left and right in a controlled motion.', E'1. Engage your core to maintain stability and prevent your upper body from swaying.\r\n2. Keep your movements smooth and controlled to maximize muscle activation and prevent injury.\r\n3. Ensure your knees are slightly bent to allow for greater range of motion in your hips.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Body Slide.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Body Slide1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Body Slide.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ca98da22-de0a-4bac-afe1-f7b225c0e52d'::uuid, 'Body throw', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand tall with your back straight and feet shoulder-width apart, lower your hips to knee level, and extend your arms back at your sides.\r\n2. Push through your feet and raise yourself upright while raising your heels and extending your arms overhead.\r\n3. Return to the starting position and repeat.\r\n', E'1. Engage your core throughout the exercise to maintain balance and proper form.\r\n2. Use the power from your legs and core to drive the movement, ensuring a controlled and explosive upward motion.\r\n3. Breathe out as you extend upwards and breathe in as you return to the squat position.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Body Throw.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Body Throw1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Body Throw.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4c32d86d-18c7-493e-958e-2029b04a8ae8'::uuid, 'Body-up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start in a plank position with your hands placed directly under your shoulders and your body forming a straight line from head to heels.\r\n2. Lower your body towards the floor by bending your elbows, keeping them close to your torso.\r\n3. Push through your palms to lift your body back up to the starting plank position.\r\n4. Repeat the movement for the desired number of repetitions.', 'Triceps (Triceps Brachii), Chest (Pectoralis Major)', '{"image_male_start":"images/Triceps/Body-Up.jpeg","video_url":"videos/Triceps/Body-Up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('48ac7c49-42f7-4929-a3f4-09da17b34511'::uuid, 'Bodyweight bent over rear delt fly', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and bend forward at the hips, keeping your back straight and your knees slightly bent, until your torso is almost parallel to the floor.\r\n2. Allow your arms to hang straight down from your shoulders.\r\n3. Lift your arms out to the sides until they are in line with your shoulders, squeezing your shoulder blades together.\r\n4. Lower your arms back down in a controlled manner and repeat the movement for the desired number of repetitions.\r\n', E'1. Keep your back straight and engage your core to maintain proper form throughout the exercise.\r\n2. Focus on squeezing your shoulder blades together as you lift your arms to maximize muscle activation.\r\n3. Perform the movement slowly and with control to avoid using momentum and to target the rear deltoids effectively.', '{"image_male_start":"images/Shoulders/bodyweight bent over rear delt fly.jpg","image_male_end":"images/Shoulders/bodyweight bent over rear delt fly1.jpg","video_url":"videos/Shoulders/bodyweight bent over rear delt fly.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f81cd106-250b-48a2-a541-1b39c041c658'::uuid, 'Bodyweight calf raises', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your hands on your hips or by your sides for balance.\r\n2. Lift your heels off the floor, rising onto your toes.\r\n3. Hold the top position briefly, squeezing your calf muscles.\r\n4. Lower your heels back to the floor in a controlled manner and repeat the movement for the desired number of repetitions.', E'1. Stand tall with your shoulders back and chest lifted to maintain good posture.\r\n2. Perform the movement slowly and with control to maximize muscle activation and prevent injury.\r\n3. Ensure your weight is evenly distributed on your toes to maintain balance and stability.', '{"image_male_start":"images/Legs/bodyweight calf raises.jpg","image_male_end":"images/Legs/bodyweight calf raises1.jpg","video_url":"videos/Legs/bodyweight calf raises.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3e0e6090-4f2d-467f-97d7-80d348b1cae8'::uuid, 'Bodyweight forward lunge', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your hands on your hips or by your sides.\r\n2. Step forward with your right foot and lower your body by bending both knees, ensuring your front knee is aligned over your ankle and your back knee is close to the floor.\r\n3. Push through your front heel to return to the starting position.\r\n4. Repeat the movement with your left foot stepping forward, alternating legs.', E'1. Keep your core engaged and your torso upright to maintain balance and proper form.\r\n2. Ensure your front knee does not extend past your toes to avoid putting unnecessary strain on your knee.\r\n3. Perform the movement slowly and with control to maximize muscle activation and prevent injury.', '{"image_male_start":"images/Legs/Bodyweight Forward Lunge.jpg","image_male_end":"images/Legs/Bodyweight Forward Lunge1.jpg","video_url":"videos/Legs/Bodyweight Forward Lunge.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2c575565-3a9d-4940-aeb9-d87d99a1fc9b'::uuid, 'Bodyweight front slam', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and extend your hands overhead.\r\n2. Swing your arms down forcefully in front of your body, as if slamming a medicine ball to the floor, while simultaneously bending your knees into a squat position.\r\n3. Return to the starting position with hands extended overhead.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Engage your core to maintain stability and control throughout the exercise.\r\n2. Ensure your back stays straight and avoid rounding your spine when swinging your arms down.\r\n3. Perform the movement explosively but with control to maximize muscle activation and prevent injury.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Bodyweight Front Slam.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Bodyweight Front Slam1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Bodyweight Front Slam.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('cf5128fa-22f3-4159-a191-6bac146b1c1a'::uuid, 'bodyweight full squat with overhead front raise', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start in a squat position with your feet shoulder-width apart, your torso leaning slightly forward, and both arms extended between your thighs.\r\n2. Begin to straighten your legs to rise into a standing position while simultaneously raising both arms straight overhead.\r\n3. Fully extend your legs and arms, standing tall with your arms overhead.\r\n4. Lower your body back into the squat position, bringing your arms back down between your thighs. Repeat the movement for the desired number of repetitions.', E'1. Maintain a neutral spine throughout the movement to protect your back and improve stability.\r\n2. Keep your knees aligned with your toes during the squat to avoid putting strain on your knees.\r\n3. Focus on a controlled descent back into the squat to ensure smooth and effective movement.', '{"image_male_start":"images/Legs/bodyweight full squat with overhead front raise.jpg","image_male_end":"images/Legs/bodyweight full squat with overhead front raise1.jpg","video_url":"videos/Legs/bodyweight full squat with overhead front raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3c188138-bd89-4e75-b4a0-7a309935b3a4'::uuid, 'Bodyweight full squat with overhead front raises', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your arms extended in close to your knees.\r\n2. Lower your body into a squat position until your thighs are parallel to the floor, while simultaneously raising your arms overhead.\r\n3. Stand back up to the starting position, lowering your arms back close to your knees.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Maintain a neutral spine and avoid rounding your back during the exercise to ensure proper form.\r\n2. Ensure your knees are aligned with your toes during the squat to prevent strain on your knees.\r\n3. Move at a controlled pace, especially when lifting and lowering your arms, to avoid unnecessary strain and enhance muscle engagement.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/bodyweight full squat with overhead front raises.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/bodyweight full squat with overhead front raises1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/bodyweight full squat with overhead front raises.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('31ce8397-f6ad-4a93-8be2-b3924ec4391f'::uuid, 'Bodyweight full squat with overhead press', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your arms extended just in front of your knees.\r\n2. Lower your body into a squat position until your thighs are parallel to the floor, keeping your back straight.\r\n3. Stand up from the squat while pressing your hands overhead, extending your arms fully.\r\n4. Lower your hands back down as you descend into the next squat. Repeat the movement for the desired number of repetitions.', E'1. Maintain a neutral spine and avoid rounding your back during the exercise to ensure proper form.\r\n2. Ensure your knees are aligned with your toes during the squat to prevent strain on your knees.\r\n3. Avoid locking your elbows when pressing overhead to keep tension on your muscles and protect your joints.', '{"image_male_start":"images/Legs/Bodyweight full squat with overhead press.jpg","image_male_end":"images/Legs/Bodyweight full squat with overhead press1.jpg","video_url":"videos/Legs/Bodyweight full squat with overhead press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b62ccd7c-4892-4f95-a9fe-38c64942e880'::uuid, 'Bodyweight full squat with overhead press (version 2)', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start in a squat position with your feet shoulder-width apart, your torso leaning slightly forward, and both hands just in front of your knees.\r\n2. Straighten your legs to rise into a standing position while simultaneously pressing your hands upwards until they are extended overhead.\r\n3. Fully extend your legs and arms, standing tall with your arms overhead.\r\n4. Lower your body back into the squat position, bringing your hands back down in front of your knees. Repeat for the desired number of repetitions.', E'1. Maintain a neutral spine throughout the movement to protect your back and improve stability.\r\n2. Keep your knees aligned with your toes during the squat to avoid putting strain on your knees.\r\n3. Focus on a controlled descent back into the squat to ensure smooth and effective movement.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('254bf749-ac31-4c02-b08b-ee8d8fed08ba'::uuid, 'Bodyweight knee thrust', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start in a partial lunge position with your left foot forward and right foot back, hands in front of your hips.\r\n2. Thrust your right knee forward and up to hip level, bringing your hands to meet your knee.\r\n3. Return to the partial lunge position, lowering your right leg back to the starting position.\r\n4. Repeat the movement for the desired number of repetitions, then switch legs.\r\n', E'1. Maintain a steady breathing pattern to support balance and coordination during the movement.\r\n2. Keep your supporting leg slightly bent to absorb impact and provide stability.\r\n3. Focus on a powerful knee thrust while maintaining proper form and balance.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Bodyweight Knee Thrust.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Bodyweight Knee Thrust1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Bodyweight Knee Thrust.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b4374ffd-0384-4c75-b4f6-5032c0e6e265'::uuid, 'Bodyweight kneeling hold to stand', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start by kneeling on the floor with both knees, hands placed on your hips.\r\n2. Lift your right foot and place it flat on the floor in front of you, transitioning into a half-kneeling position.\r\n3. Push through your right foot to stand up fully, bringing your left foot to meet your right.\r\n4. Lower back down into the half-kneeling position, then return to the original kneeling position. Repeat with the other leg.', E'1. Engage your core to maintain balance and stability throughout the exercise.\r\n2. Keep your back straight and avoid leaning forward as you transition from kneeling to standing.\r\n3. Perform the movement slowly and with control to maximize muscle activation and prevent injury.', '{"image_male_start":"images/Legs/Bodyweight kneeling hold to stand.jpg","image_male_end":"images/Legs/Bodyweight kneeling hold to stand1.jpg","video_url":"videos/Legs/Bodyweight kneeling hold to stand.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e938a5f3-1dd5-4bff-a951-28e20685c13a'::uuid, 'Bodyweight kneeling push-up row', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start in a kneeling push-up position with your hands placed slightly wider than shoulder-width apart and your body on the floor.\r\n2. Push up by extending both arms, keeping your knees on the floor. Lift your right hand off the floor, performing a rowing motion by bringing your elbow up towards the ceiling.\r\n3. Return your right hand to the floor and lower your body to the starting position.\r\n4. Repeat alternating sides for the desired number of repetitions.\r\n', E'1. Engage your core to maintain stability and prevent your hips from sagging during the push-up and row.\r\n2. Keep your movements slow and controlled to maximize muscle activation and avoid injury.\r\n3. Focus on a full range of motion in both the push-up and the rowing movement to ensure effectiveness.', '{"image_male_start":"images/Yoga/Bodyweight Kneeling Push-Up Row.jpg","image_male_end":"images/Yoga/Bodyweight Kneeling Push-Up Row1.jpg","video_url":"videos/Yoga/Bodyweight Kneeling Push-Up Row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('22cdd35e-95d3-44f3-8268-52627bd92dec'::uuid, 'Bodyweight kneeling sissy squat', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start in a kneeling position with your knees on the floor and your torso upright.\r\n2. Lean back slowly, keeping your body straight from your knees to your head, engaging your quadriceps.\r\n3. Return to the upright kneeling position, repeat the movement for the desired number of repetitions', E'1. Engage your core to maintain stability and prevent your lower back from arching.\r\n2. Keep your core engaged to stabilize your spine and prevent lower back strain.\r\n3. Focus on a smooth and steady movement to maintain balance and ensure proper form.', '{"image_male_start":"images/Legs/Bodyweight kneeling sissy squat.jpg","image_male_end":"images/Legs/Bodyweight kneeling sissy squat1.jpg","video_url":"videos/Legs/Bodyweight kneeling sissy squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8ec0c0ba-4c97-49fa-9d29-87dd9012ae65'::uuid, 'Bodyweight kneeling to hand tap', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1.Start in a standing position with your feet shoulder-width apart and your hands just in front of your hips.\r\n2. Lift your right knee towards the middle of your hips while lightly rotating your torso to bring your left hand to touch the right knee.\r\n3. Lower your right leg back to the floor and return your hands to the starting position.\r\n4. Repeat the movement with your left knee, alternating sides for the desired number of repetitions.', E'1. Maintain an upright posture throughout the exercise to ensure proper form.\r\n2. Rotate your torso smoothly to engage your oblique muscles effectively.\r\n3. Ensure your knee movement is deliberate and controlled to maximize muscle activation.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('dee30909-e108-4dc3-b7cc-e898c6d009bf'::uuid, 'Bodyweight kneeling triceps extension', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start in a kneeling position with your knees on the floor. Place your hands on the floor in front of you opposite your head, close together, and lean forward.\r\n2. Bend your elbows to lower your forearms and head towards the floor, engaging your triceps.\r\n3. Push through your hands to extend your arms back to the starting position, straightening your elbows.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Keep your body stable by engaging your core throughout the movement.\r\n2. Keep your elbows close to your body to target the triceps more effectively.\r\n3. Control the movement, avoiding any jerking motions, to enhance muscle engagement and prevent injury.', '{"image_male_start":"images/Triceps/Bodyweight kneeling triceps extension.jpeg","video_url":"videos/Triceps/Bodyweight kneeling triceps extension.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d9cb81c7-9050-4a69-aadf-e0828f2caf96'::uuid, 'Bodyweight lying leg curl', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie down on your stomach while curling your arms at your chest and extend your legs on the floor.\r\n2. Bend your knees to lift your lower legs towards your glutes, engaging your hamstrings.\r\n3. Slowly lower your legs back to the starting position.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Keep your hips pressed into the floor to ensure proper form and maximize hamstring engagement.\r\n2. Squeeze your hamstrings at the top of the movement for a brief hold to enhance muscle contraction.\r\n3. Perform the movement slowly and with control to maximize muscle activation and prevent injury.', '{"image_male_start":"images/Legs/bodyweight lying leg curl.jpg","image_male_end":"images/Legs/bodyweight lying leg curl1.jpg","video_url":"videos/Legs/bodyweight lying leg curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6cd7e9d2-4f0d-4d2d-a400-2cec3012f11f'::uuid, 'Bodyweight muscle-up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '54938b47-43e8-47cd-9efc-18b4424e71e1'::uuid, E'1. Start by hanging from a bar with your arms fully extended and your body straight.\r\n2. Pull yourself up explosively, transitioning from a pull-up to a dip position above the bar.\r\n3. Push your body up until your arms are fully extended above the bar.\r\n4. Lower yourself back down to the starting hanging position in a controlled manner. Repeat the movement for the desired number of repetitions.', E'1. Engage your core and maintain a straight body line to ensure proper form.\r\n2. Use an explosive pull-up motion to help transition from below the bar to above the bar.\r\n3. Focus on a controlled descent to avoid straining your muscles and joints.', '{"image_male_start":"images/Back/Bodyweight Muscle-up.jpg","image_male_end":"images/Back/Bodyweight Muscle-up1.jpg","video_url":"videos/Back/Bodyweight Muscle-up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('687f2951-daa1-40fb-aae1-cc77db5b79f4'::uuid, 'Bodyweight overhead squat', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your arms extended overhead.\r\n2. Lower your body into a squat position until your thighs are parallel to the floor, keeping your arms extended overhead.\r\n3. Stand back up to the starting position, maintaining the arm position throughout.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Engage your core to maintain stability and proper alignment throughout the exercise.\r\n2. Keep your chest lifted and your back straight to avoid leaning forward excessively.\r\n3. Ensure your knees are aligned with your toes during the squat to prevent strain on your knees.', '{"image_male_start":"images/Legs/Bodyweight Overhead Squat.jpg","image_male_end":"images/Legs/Bodyweight Overhead Squat1.jpg","video_url":"videos/Legs/Bodyweight Overhead Squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b8102416-6f99-4b0a-a773-0a29cc913fd1'::uuid, 'Bodyweight Overhead Triceps Extension', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your arms extended overhead with hands holding together, elbows slightly bent.\r\n2. Bend your elbows to lower your hands behind your head, engaging your triceps.\r\n3. Extend your arms back to the starting overhead position.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Keep your upper arms stationary and close to your ears throughout the exercise to effectively target the triceps.\r\n2. Engage your core to maintain stability and avoid arching your back.\r\n3. Perform the movement slowly and with control to maximize muscle activation and prevent injury.', '{"image_male_start":"images/Triceps/Bodyweight Overhead Triceps Extension.jpeg","video_url":"videos/Triceps/Bodyweight Overhead Triceps Extension.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('89303db0-9ec1-4c99-a816-9805785fb4c2'::uuid, 'Bodyweight pulse forward lunge', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your hands on your hips or by your sides.\r\n2. Step forward with your right foot and lower your body into a lunge position, ensuring your front knee is aligned over your ankle and your back knee is close to the floor.\r\n3. Perform small pulsing movements by slightly raising and lowering your body in the lunge position.\r\n4. Push through your front heel to return to the starting position. Repeat the movement on the other side.\r\n', E'1. Keep your core engaged and your torso upright to maintain balance and proper form.\r\n2. Ensure your front knee does not extend past your toes to avoid putting unnecessary strain on your knee.\r\n3. Perform the pulsing movements slowly and with control to maximize muscle activation and prevent injury.', '{"image_male_start":"images/Legs/Bodyweight Pulse Forward Lunge.jpg","image_male_end":"images/Legs/Bodyweight Pulse Forward Lunge1.jpg","video_url":"videos/Legs/Bodyweight Pulse Forward Lunge.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0e646c69-0831-415c-bb77-91378ab6bc92'::uuid, 'Bodyweight pulse squat', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your hands on your hips or extended in front of you.\r\n2. Lower your body into a squat position, ensuring your thighs are parallel to the floor and your back is straight.\r\n3. Perform a small pulsing movement by slightly raising and lowering your body in the squat position.\r\n4. Return to the starting position. Repeat the movement for the desired number of repetitions.', E'1. Keep your feet flat on the floor to maintain balance and stability.\r\n2. Keep your chest lifted and your back straight to avoid leaning forward excessively.\r\n3. Perform the pulsing movements slowly and with control to maximize muscle activation and prevent injury.', '{"image_male_start":"images/Legs/Bodyweight Pulse Squat.jpg","image_male_end":"images/Legs/Bodyweight Pulse Squat1.jpg","video_url":"videos/Legs/Bodyweight Pulse Squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b2764f56-369d-442b-8938-9133a5ab8c52'::uuid, 'Bodyweight pulse squat arms to chest', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your hands on crossed at your chest\r\n2. Lower your body into a squat position, ensuring your thighs are parallel to the floor and your back is straight.\r\n3. Perform a small pulsing movement by slightly raising and lowering your body in the squat position.\r\n4. Return to the starting position. Repeat the movement for the desired number of repetitions.', E'1. Keep your feet flat on the floor to maintain balance and stability.\r\n2. Keep your chest lifted and your back straight to avoid leaning forward excessively.\r\n3. Perform the pulsing movements slowly and with control to maximize muscle activation and prevent injury.', '{"image_male_start":"images/Legs/Bodyweight Pulse Squat arms to chest.jpg","image_male_end":"images/Legs/Bodyweight Pulse Squat arms to chest1.jpg","video_url":"videos/Legs/Bodyweight Pulse Squat arms to chest.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('bbf49621-2277-4617-9b26-91d516d3d11a'::uuid, 'Bodyweight rear lunge', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your hands on your hips or by your sides.\r\n2. Step backward with your right foot and lower your body into a lunge position, ensuring your front knee is aligned over your ankle and your back knee is close to the floor.\r\n3. Push through your front heel to return to the starting position.\r\n4. Repeat the movement with your left foot stepping backward, alternating legs.', E'1. Maintain an upright posture throughout the exercise to ensure proper form.\r\n2. Ensure your front knee does not extend past your toes to avoid putting unnecessary strain on your knee.\r\n3. Focus on smooth and controlled movements to enhance muscle engagement and prevent injury.', '{"image_male_start":"images/Legs/Bodyweight Rear Lunge.jpg","image_male_end":"images/Legs/Bodyweight Rear Lunge1.jpg","video_url":"videos/Legs/Bodyweight Rear Lunge.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f4bd63a8-7c45-41af-b39a-2555e78b1008'::uuid, 'Bodyweight rear lunge front raise', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your arms by your sides.\r\n2. Step backward with your right foot and lower your body into a lunge position while simultaneously raising your arms in front of you to shoulder level.\r\n3. Ensure your front knee is aligned over your ankle and your back knee is close to the floor.\r\n4. Push through your front heel to return to the starting position, lowering your arms back to your sides. Repeat the movement with your left foot stepping backward, alternating legs.', E'1. Maintain a steady breathing pattern, inhaling as you lunge down and exhaling as you push back up.\r\n2. Keep your arms straight and parallel to the floor during the front raise to maximize shoulder activation.\r\n3. Avoid locking your knees when returning to the standing position to keep the tension on your muscles and prevent injury.', '{"image_male_start":"images/Legs/Bodyweight Rear Lunge front raise.jpg","image_male_end":"images/Legs/Bodyweight Rear Lunge front raise1.jpg","video_url":"videos/Legs/Bodyweight Rear Lunge front raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('bbc0ffec-529e-48fb-baf5-417b20806cb5'::uuid, 'Bodyweight single leg deadlift', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet together and your hands by your sides or on your hips.\r\n2. Lift your right leg straight back and lean forward at the hips, keeping your back straight, until your torso is parallel to the floor.\r\n3. Return to the starting position by lowering your right leg and raising your torso back to upright.\r\n4. Repeat the movement for the desired number of repetitions, then switch to the left leg', E'1. Maintain an upright posture and look forward to help with balance.\r\n2. Keep a slight bend in your standing knee to avoid locking it and to protect your joints.\r\n3. Focus on keeping your movements smooth and steady to maintain proper form and avoid injury.', '{"image_male_start":"images/Legs/Bodyweight Single Leg Deadlift.jpg","image_male_end":"images/Legs/Bodyweight Single Leg Deadlift1.jpg","video_url":"videos/Legs/Bodyweight Single Leg Deadlift.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b21cc989-6856-4d41-8549-64f3ced7da7d'::uuid, 'Bodyweight squat', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your hands extended in front of you for balance.\r\n2. Lower your body into a squat position until your thighs are parallel to the floor, keeping your back straight.\r\n3. Stand back up to the starting position.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Keep your feet flat on the floor to maintain balance and stability.\r\n2. Ensure your knees are aligned with your toes during the squat to prevent strain on your knees.\r\n3. Perform the movement slowly and with control to maximize muscle activation and prevent injury.', '{"image_male_start":"images/Legs/Bodyweight Squat.jpg","image_male_end":"images/Legs/Bodyweight Squat1.jpg","video_url":"videos/Legs/Bodyweight Squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5a5cb312-b8be-4e4d-93a2-20a4fee2a9cc'::uuid, 'Bodyweight squat to front leg', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your hands extended down by your sides.\r\n2. Lower your body into a squat position until your thighs are parallel to the floor, keeping your back straight.\r\n3. Stand up from the squat and raise your right leg straight in front of you to hip level mimicking a kick, lower it down and immidiately raise your left leg to hip level.\r\n4. Lower your left leg back to the floor and repeat.', E'1. Focus on maintaining an upright posture to ensure proper alignment and form.\r\n2. Ensure your knees are aligned with your toes during the squat to prevent strain on your knees.\r\n3. Move at a controlled pace, particularly when raising and lowering your leg, to avoid unnecessary strain and enhance muscle engagement.', '{"image_male_start":"images/Legs/Bodyweight Squat to Front Leg.jpg","image_male_end":"images/Legs/Bodyweight Squat to Front Leg1.jpg","video_url":"videos/Legs/Bodyweight Squat to Front Leg.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('48ea7bec-7fce-4d61-bb41-f18a669b45bd'::uuid, 'Bodyweight squat to side leg', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your hands extended by your sides.\r\n2. Lower your body into a squat position until your thighs are parallel to the floor, keeping your back straight.\r\n3. Stand up from the squat and raise your right leg as high as possible, kicking it to the side until straight.\r\n4. Lower your right leg back to the floor and immediately transition into the next squat, alternating legs with each repetition.', E'1. Focus on maintaining an upright posture to ensure proper alignment and form.\r\n2. Keep your weight distributed evenly on your feet during the squat to maintain balance.\r\n3. Move at a controlled pace, particularly when raising and lowering your leg, to avoid unnecessary strain and enhance muscle engagement.', '{"image_male_start":"images/Legs/Bodyweight Squat to Side Leg.jpg","image_male_end":"images/Legs/Bodyweight Squat to Side Leg1.jpg","video_url":"videos/Legs/Bodyweight Squat to Side Leg.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6c70eca1-04aa-4502-bceb-eb61f583be4f'::uuid, 'Bodyweight Squat to Side to Front Leg', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your hands at your sides.\r\n2. Lower your body into a squat position until your thighs are parallel to the floor, keeping your back straight.\r\n3. Stand up from the squat and raise your right leg straight to the side, then lower it back to the floor.\r\n4. Perform another squat, then stand up and raise your right leg straight to the front. Lower it back to the floor and repeat the movement, alternating legs with each repetition.', E'1. Focus on engaging your core to maintain stability and balance throughout the exercise.\r\n2. Keep your weight distributed evenly on your feet during the squat to maintain balance.\r\n3. Move at a controlled pace, especially when lifting and lowering your leg, to avoid unnecessary strain and enhance muscle engagement.', '{"image_male_start":"images/Legs/Bodyweight Squat to Side to Front Leg.jpg","image_male_end":"images/Legs/Bodyweight Squat to Side to Front Leg1.jpg","video_url":"videos/Legs/Bodyweight Squat to Side to Front Leg.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('52669c42-5ed5-47d6-ac4d-047067525bb0'::uuid, 'Bodyweight squats hold', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your hands crossed to your chest.\r\n2. Lower your body into a squat position by bending your knees and pushing your hips back.\r\n3. Hold the squat position for the desired duration, maintaining proper form throughout.\r\n4. Stand back up to the starting position by pressing through your heels and straightening your legs.', E'1. Focus on keeping your feet flat on the floor to ensure stability and proper form.\r\n2. Ensure your knees are aligned with your toes during the squat to prevent strain on your knees.\r\n3. Focus on steady breathing to help maintain the hold and prevent fatigue.', '{"image_male_start":"images/Legs/bodyweight squats hold  .jpg","video_url":"videos/Legs/bodyweight squats hold  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3f6c4cf4-5c7c-4402-806d-371294d5a682'::uuid, 'Bodyweight standing around world wall supported', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your back against a wall for support.\r\n2. Extend your arms to the sides of your torso with palms facing forward.\r\n3. Move your arms in a circular motion, bringing them overhead, and back to the starting position.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Keep your back flat against the wall to maintain proper alignment and support.\r\n2. Maintain a slight bend in your elbows to reduce strain on your joints.\r\n3. Perform the arm movements slowly and with control to maximize muscle activation and prevent injury.', '{"image_male_start":"images/Shoulders/Bodyweight Standing Around World Wall Supported.jpg","image_male_end":"images/Shoulders/Bodyweight Standing Around World Wall Supported1.jpg","video_url":"videos/Shoulders/Bodyweight Standing Around World Wall Supported.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6cc72501-bced-44ce-ae1a-30804f9f802d'::uuid, 'Bodyweight standing back stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and bring both arms straight behind your back, holding your hands together.\r\n2. Gently arch your back, pushing your hips forward and looking towards the ceiling.\r\n3. Hold the stretched position for a few seconds, maintaining a gentle and controlled stretch.\r\n4. Return to the starting position and repeat for the desired number of repetitions.', E'1. Keep the movement gentle to avoid straining your lower back.\r\n2. Engage your core to support your lower back during the stretch.\r\n3. Breathe deeply and steadily to enhance the stretch and relaxation.', '{"image_male_start":"images/Stretching - Mobility/Bodyweight Standing Back Stretch.jpg","image_male_end":"images/Stretching - Mobility/Bodyweight Standing Back Stretch1.jpg","video_url":"videos/Stretching - Mobility/Bodyweight Standing Back Stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9b71eed9-5dba-4230-a17a-cbab98c08954'::uuid, 'Bodyweight standing calf raise', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your hands on your hips or by your sides for balance.\r\n2. Rise up onto your toes, lifting your heels off the floor.\r\n3. Repeat the movement for the desired number of repetitions.\r\n4. Lower your heels back to the floor to return to the starting position.\r\n', E'1. Keep your core engaged to maintain balance throughout the exercise.\r\n2. Perform the movement slowly and with control to maximize muscle activation.\r\n3. Ensure your weight is evenly distributed on both feet to prevent imbalance.', '{"image_male_start":"images/Legs/Bodyweight Standing Calf Raise.jpg","image_male_end":"images/Legs/Bodyweight Standing Calf Raise1.jpg","video_url":"videos/Legs/Bodyweight Standing Calf Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0649f3b4-6666-4080-b2e1-c00bc965879d'::uuid, 'Bodyweight standing fly', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your arms extended out to the sides, bent at 90 degrees, elbows at shoulder height.\r\n2. Bring your arms together in front of your body until your forearms meet.\r\n3. Open your arms back out to the sides to return to the starting position.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Ensure your movements are smooth and controlled to maximize muscle engagement and prevent injury.\r\n2. Keep your shoulders down and away from your ears to avoid tension.\r\n3. Focus on squeezing your chest muscles as you bring your arms together to enhance muscle activation.', '{"image_male_start":"images/Chest/Bodyweight Standing Fly.jpg","image_male_end":"images/Chest/Bodyweight Standing Fly1.jpg","video_url":"videos/Chest/Bodyweight Standing Fly.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e59ff485-566a-40d5-8089-b2fe04ed383f'::uuid, 'Bodyweight standing military press', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, upper arms parallel to the floor, and arms bent at 90 degrees, fingers pointing at the ceiling.\r\n2. Press your hands upward, extending your arms fully overhead.\r\n3. Lower your hands back to shoulder level to return to the starting position.\r\n4. Repeat the movement for the desired number of repetitions.\r\n', E'1. Engage your core to maintain stability and avoid arching your back.\r\n2. Perform the movement slowly and with control to maximize muscle activation.\r\n3. Keep your shoulders down and away from your ears throughout the exercise.', '{"image_male_start":"images/Shoulders/Bodyweight Standing Military Press.jpg","image_male_end":"images/Shoulders/Bodyweight Standing Military Press1.jpg","video_url":"videos/Shoulders/Bodyweight Standing Military Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('99876223-52b9-47fc-bd5b-06ab73d1962a'::uuid, 'Bodyweight standing military press wall supported', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your back against a wall for support, upper arms parallel to the floor, and arms bent at 90 degrees, fingers pointing at the ceiling.\r\n2. Press your hands upward, extending your arms fully overhead.\r\n3. Lower your hands back to shoulder level to return to the starting position.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Focus on keeping your back and head in contact with the wall to maintain proper alignment.\r\n2. Ensure a full range of motion by fully extending your arms without locking your elbows.\r\n3. Maintain a steady breathing pattern, exhaling as you press up and inhaling as you lower your arms.', '{"image_male_start":"images/Shoulders/Bodyweight Standing Military Press Wall Supported.jpg","image_male_end":"images/Shoulders/Bodyweight Standing Military Press Wall Supported1.jpg","video_url":"videos/Shoulders/Bodyweight Standing Military Press Wall Supported.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a9fbad56-1c2f-4b6f-9a25-4cfc6a989b77'::uuid, 'Bodyweight standing shrug', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and place your hands on your hips.\r\n2. Raise your shoulders up towards your ears.\r\n3. Lower your shoulders back to the starting position and repeat the movement for the desired number of repetitions.', E'1. Maintain an upright posture to ensure proper form.\r\n2. Avoid rolling your shoulders; focus on lifting them straight up and down.\r\n3. Perform the movement slowly and with control to maximize muscle activation.', '{"image_male_start":"images/Shoulders/Bodyweight Standing Shrug.jpg","image_male_end":"images/Shoulders/Bodyweight Standing Shrug1.jpg","video_url":"videos/Shoulders/Bodyweight Standing Shrug.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('13e29244-d31d-4e1d-a9ad-3e48dfef1ecc'::uuid, 'Bodyweight standing triangle fly', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and place your hands behind your head, forming a triangle with your bent elbows, elbows facing outwards.\r\n2. Close your elbows together in front of you, bringing them towards each other.\r\n3. Open your elbows back out to the sides to return to the starting position.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Maintain an upright posture and avoid arching your back during the exercise.\r\n2. Keep your neck relaxed and avoid pushing your head forward as you bring your elbows together.\r\n3. Focus on squeezing your chest muscles as you bring your elbows together.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Bodyweight Standing Triangle Fly.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Bodyweight Standing Triangle Fly1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Bodyweight Standing Triangle Fly.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2b3783f6-b9e1-4bdb-9029-980f24cc6d3e'::uuid, 'Bodyweight step-up on step box', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart in front of a step box.\r\n2. Step up onto the box with your right foot, then bring your left foot up to meet your right, standing fully on the box.\r\n3. Step back down to the floor with your left foot, followed by your right foot.\r\n4. Repeat the movement for the desired number of repetitions, alternating the lead foot.', E'1. Engage your core to maintain balance and stability throughout the exercise.\r\n2. Ensure your entire foot is placed on the box to prevent slipping.\r\n3. Focus on pushing through your heel when stepping up to activate your glutes and quadriceps.', '{"image_male_start":"images/Legs/Bodyweight Step-up on Step box.jpg","image_male_end":"images/Legs/Bodyweight Step-up on Step box1.jpg","video_url":"videos/Legs/Bodyweight Step-up on Step box.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('bad193ae-802e-428a-803b-1b0957b1c207'::uuid, 'Bodyweight svend press', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your hands pressed together close to your chest, elbows bent.\r\n2. Extend your arms straight out in front of you, keeping your hands pressed together.\r\n3. Bring your hands back to your chest, bending your elbows to return to the starting position.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Maintain a firm press of your hands together to engage your chest muscles throughout the exercise.\r\n2. Keep your core engaged to maintain stability and balance.\r\n3. Perform the movement slowly and with control to maximize muscle activation and prevent injury.', '{"image_male_start":"images/Chest/Bodyweight Svend Press.jpg","image_male_end":"images/Chest/Bodyweight Svend Press1.jpg","video_url":"videos/Chest/Bodyweight Svend Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e412bc5d-ce0b-489f-9972-e92b8ba22057'::uuid, 'Bodyweight triceps extension', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a plank position on your toes and elbows, with your hands positioned at shoulder-width apart, palms on the floor.\r\n2. Push through your palms to extend your arms straight, keeping your palms in place. \r\n3.  Lower your forearms to the floor back to the starting plank position.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Keep your body in a straight line from head to heels to maintain proper form.\r\n2. Engage your core to stabilize your body and prevent your hips from sagging.\r\n3. Focus on your breathing; inhale as you lower your forearms and exhale as you extend your arms back to the plank position.', '{"image_male_start":"images/Triceps/bodyweight triceps extension.jpeg","video_url":"videos/Triceps/bodyweight triceps extension.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('dd470ab2-9f70-4727-8d49-46a5bfbd9a90'::uuid, 'Bodyweight wall squat', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your back against a wall and your feet shoulder-width apart, positioned a few inches away from the wall.\r\n2. Lower your body into a squat position by bending your knees and hips, allowing your buttocks to touch the wall first, then your entire torso.\r\n3. Immediately push through your heels to stand back up, returning to the starting position.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Start the movement by engaging your glutes and core to maintain stability.\r\n2. Ensure your knees are aligned with your toes and do not extend past your toes to prevent strain on your knees.\r\n3. Move smoothly and with control to maximize muscle activation and prevent injury.', '{"image_male_start":"images/Legs/Bodyweight Wall Squat.jpg","image_male_end":"images/Legs/Bodyweight Wall Squat1.jpg","video_url":"videos/Legs/Bodyweight Wall Squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e22afb9a-f985-4176-b350-744338fd9256'::uuid, 'Bodyweight windmill', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet wider than shoulder-width apart and your arms extended straight out to the sides at shoulder height.\r\nBend at the waist, rotating your torso to touch your right hand to your left foot, while keeping your left arm extended upward.\r\nReturn to the starting position and repeat the movement on the opposite side, touching your left hand to your right foot.\r\nRepeat the movement for the desired number of repetitions, alternating sides.', E'1. Keep your core engaged to maintain balance and stability throughout the exercise.\r\n2. Ensure your movements are slow and controlled to maximize muscle activation and prevent injury.\r\n3. Maintain a slight bend in your knees to reduce strain on your lower back and hamstrings.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Bodyweight Windmill.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Bodyweight Windmill1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Bodyweight Windmill.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('74151349-dce1-4985-9c37-572e52f245d8'::uuid, 'Bodyweight windmill cut', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet wider than shoulder-width apart and your arms extended straight out to the sides at shoulder height.\r\n2. Bend at the waist, rotating your torso to touch your right hand to your left foot 3-4 times in a pulsing motion, while keeping your left arm extended upward.\r\n3. Return to the starting position and repeat the movement on the opposite side, touching your left hand to your right foot.\r\n4. Repeat the movement for the desired number of repetitions, alternating sides.', E'1. Keep your core engaged to maintain balance and stability throughout the exercise.\r\n2. Ensure your movements are slow and controlled to maximize muscle activation and prevent injury.\r\n3. Maintain a slight bend in your knees to reduce strain on your lower back and hamstrings.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Bodyweight Windmill Cut.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Bodyweight Windmill Cut1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Bodyweight Windmill Cut.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f3776194-0fd1-4623-862b-cec98bdacaad'::uuid, 'Bottoms-up half rep', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your legs extended just off the floor and your arms resting on the floor by your sides.\r\n2. Bend your knees towards your chest, stopping when your upper legs are vertical to the floor.\r\n3. Lower your legs back down without letting them touch the floor.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Keep your core engaged throughout the exercise to maintain stability and support your lower back.\r\n2. Perform the movement slowly and with control to maximize muscle activation and prevent injury.\r\n3. Focus on using your lower abdominal muscles to lift and lower your legs.', '{"image_male_start":"images/Abdominals/Bottoms-Up half rep.jpeg","video_url":"videos/Abdominals/Bottoms-Up half rep.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3184bd8f-a3b8-4f85-9f09-ff716a9d8f44'::uuid, 'Bouncing circle draw', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, legs slightly bent, and your hands lightly bent in front of your hips.\r\n2. Slowly straighten your legs while simultaneously drawing circles with your hands, moving them outward and upward.\r\n3. Encircle your hands inward, bringing them close together and downward as you bend your knees back to the starting position.\r\n4. Repeat the movement for the desired number of repetitions or duration.', E'1. Maintain a slight bend in your knees throughout the exercise to reduce strain on your joints.\r\n2. Keep your shoulders relaxed to avoid tension and enhance fluidity in your movements.\r\n3. Focus on maintaining a consistent rhythm with both the leg movements and the circular hand motions.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Bouncing Circle Draw.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Bouncing Circle Draw1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Bouncing Circle Draw.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1535e94e-19f2-4313-a83b-d02dcb7857e9'::uuid, 'Bouncing inner thigh tap', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your arms extended by your sides at shoulder level.\r\n2. Rotate your torso to touch the inside of your right thigh with your left hand, slightly bending your knees as you do so.\r\n3. Return to the starting position and repeat the movement on the opposite side, rotating your torso to touch the inside of your left thigh with your right hand, slightly bending your knees.\r\n4. Continue alternating sides for the desired number of repetitions or duration.', E'1. Keep your gaze forward to help maintain balance and proper alignment.\r\n2. Engage your core muscles to support the rotational movement and protect your lower back.\r\n3. Perform the exercise at a controlled pace to ensure proper form and muscle engagement.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Bouncing Inner Thigh Tap.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Bouncing Inner Thigh Tap1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Bouncing Inner Thigh Tap.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6cde323b-55c7-40de-8779-e2326b470963'::uuid, 'Box jump', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart in front of a box.\r\n2. Bend your knees and hips, swinging your arms back to prepare for the jump.\r\n3. Explosively jump onto the box, landing softly with both feet.\r\n4. Stand up fully on the box before stepping or jumping back down to the starting position.', E'1. Focus on landing softly to reduce impact on your joints.\r\n2. Engage your core throughout the jump to maintain stability and control.\r\n3. Use your arms to generate momentum and help propel your body upward.', '{"image_male_start":"images/Legs/box jump  .jpg","video_url":"videos/Legs/box jump  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('97de8d45-3c87-4d81-a5d2-a0d693103880'::uuid, 'Box jump squats', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart in front of a box.\r\n2. Bend your knees and hips, swinging your arms back to prepare for the jump.\r\n3. Explosively jump onto the box, landing softly in a squat position.\r\n4. Jump back down to the floor, returning to the starting position and repeat.\r\n', E'1. Focus on landing softly to reduce impact on your joints.\r\n2. Engage your core throughout the jump to maintain stability and control.\r\n3. Use your arms to generate momentum and help propel your body upward.', '{"image_male_start":"images/Legs/box jump squats.jpg","image_male_end":"images/Legs/box jump squats1.jpg","video_url":"videos/Legs/box jump squats.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('913ccd5a-d7f4-4c5b-8440-4a2425ec15cf'::uuid, 'Boxing jab', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand in a boxing stance with your feet shoulder-width apart, left foot forward, and hands up in a guard position near your chin.\r\n2. Extend your left arm forward in a quick, snapping motion to throw a jab.\r\n3. Quickly retract your left arm back to the guard position.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Keep your non-punching hand up to protect your face and maintain a balanced stance.\r\n2. Engage your core to generate power and maintain stability.\r\n3. Rotate your hips and shoulders slightly to add power to the jab.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/boxing jab.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/boxing jab1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/boxing jab.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9db976a2-2c1c-4506-adba-6f94d344a916'::uuid, 'Boxing left hook', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand in a boxing stance with your feet shoulder-width apart, left foot forward, and hands up in a guard position near your chin.\r\n2. Rotate your hips and shoulders, bringing your left arm in a horizontal arc to throw a hook.\r\n3. Quickly retract your left arm back to the guard position.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Keep your non-punching hand up to protect your face and maintain a balanced stance.\r\n2. Engage your core to generate power and maintain stability.\r\n3. Focus on rotating your hips and shoulders to add power to the hook.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Boxing Left Hook.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Boxing Left Hook1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Boxing Left Hook.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c0650e6e-1322-44ec-af4b-bb0af504bcdc'::uuid, 'Boxing left uppercut', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand in a boxing stance with your feet shoulder-width apart, left foot forward, and hands up in a guard position near your chin.\r\n2. Bend your knees slightly and rotate your hips and shoulders, bringing your left fist upward in a rising arc to throw an uppercut.\r\n3. Quickly retract your left arm back to the guard position.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Keep your non-punching hand up to protect your face and maintain a balanced stance.\r\n2. Engage your core to generate power and maintain stability.\r\n3. Focus on driving the punch from your legs and hips to add power to the uppercut.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Boxing left uppercut.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Boxing left uppercut1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Boxing left uppercut.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('cfed1e97-5099-4d99-bcd3-3da45609e191'::uuid, 'Boxing right cross', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand in a boxing stance with your feet shoulder-width apart, left foot forward, and hands up in a guard position near your chin.\r\n2. Rotate your hips and shoulders, extending your right arm forward in a straight line to throw a cross.\r\n3. Quickly retract your right arm back to the guard position.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Keep your non-punching hand up to protect your face and maintain a balanced stance.\r\n2. Engage your core to generate power and maintain stability.\r\n3. Rotate your back foot and hips to add power to the cross.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Boxing right cross.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Boxing right cross1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Boxing right cross.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b578a0bf-c59f-4475-ac6b-63aa27bb1585'::uuid, 'Boxing right hook', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand in a boxing stance with your feet shoulder-width apart, left foot forward, and hands up in a guard position near your chin.\r\n2. Rotate your hips and shoulders, bringing your right arm in a horizontal arc to throw a hook.\r\n3. Quickly retract your right arm back to the guard position.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Keep your non-punching hand up to protect your face and maintain a balanced stance.\r\n2. Engage your core to generate power and maintain stability.\r\n3. Focus on rotating your hips and shoulders to add power to the hook.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Boxing right hook.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Boxing right hook1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Boxing right hook.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('cd42e5cf-a752-4e50-848d-b4bc83ed119e'::uuid, 'Boxing right uppercut', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand in a boxing stance with your feet shoulder-width apart, left foot forward, and hands up in a guard position near your chin.\r\n2. Bend your knees slightly and rotate your hips and shoulders, bringing your right fist upward in a rising arc to throw an uppercut.\r\n3. Quickly retract your right arm back to the guard position.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Keep your non-punching hand up to protect your face and maintain a balanced stance.\r\n2. Engage your core to generate power and maintain stability.\r\n3. Focus on driving the punch from your legs and hips to add power to the uppercut.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Boxing Right Uppercut.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Boxing Right Uppercut1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Boxing Right Uppercut.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('158b1067-b663-4f93-a3cf-b563dfb34361'::uuid, 'Brazilian crunches', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a plank position on your toes and hands, arms straight in line with shoulders, with your body in a straight line from head to heels.\r\n2. Bend your right knee and bring it towards your left elbow while lightly rotating your hips. Return your leg to starting position.\r\n3. Repeat the movement on the opposite side, bending your left knee and bringing it towards your right elbow while lightly rotating your hips. Continue alternating sides for the desired number of repetitions.', E'1. Keep your movements controlled to ensure each repetition is deliberate and effective.\r\n2. Maintain a steady breathing pattern, exhaling as you bring your knee towards your elbow and inhaling as you return to the plank.\r\n3. Focus on maintaining proper plank form, keeping your body in a straight line from head to heels.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('10f8d0f3-cdbe-4458-9903-778f4263ca1c'::uuid, 'Bridge - Mountain Climber (Cross Body)', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1.Begin in a plank position on your toes and hands, with your body in a straight line from head to heels.\r\n2. Bend your right knee and bring it towards your left elbow while lightly rotating your hips, stop when your knee passes the elbow.\r\n3. Return to the starting plank position, then repeat the movement on the opposite side.\r\n4. Continue alternating sides for the desired number of repetitions.', E'1. Ensure you keep your movements smooth and controlled to maintain form and avoid injury.\r\n2. Maintain a steady breathing pattern, exhaling as you bring your knee towards your elbow and inhaling as you return to the plank position.\r\n3. Keep your shoulders stable and your core engaged throughout the exercise to enhance effectiveness.', '{"image_male_start":"images/Abdominals/Bridge - Mountain Climber (Cross Body).jpeg","video_url":"videos/Abdominals/Bridge - Mountain Climber (Cross Body).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5f1039fd-1cfc-461f-b330-338bb6b4dbcb'::uuid, 'Bridge hip abduction', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by lying on your back with your knees bent, feet flat on the floor at shoulder width, and arms extended by your sides.\r\n2. Lift your hips off the floor to form a straight line from your shoulders to your knees, engaging your glutes and core.\r\n3. While keeping your hips elevated, move your knees outwards in a controlled manner and back.\r\n4. Repeat the movement  for the desired number of repetitions.\r\n', E'1. Keep your core engaged to maintain stability and support your lower back.\r\n2. Ensure your hips remain elevated and level throughout the exercise to maximize glute activation.\r\n3. Perform the leg abductions slowly and with control to avoid any jerky movements and enhance muscle engagement.', '{"image_male_start":"images/Yoga/Bridge Hip Abduction.jpg","image_male_end":"images/Yoga/Bridge Hip Abduction1.jpg","video_url":"videos/Yoga/Bridge Hip Abduction.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('eb1b792a-f659-4c20-8890-2903a12bcd0c'::uuid, 'Bridge pose setu bandhasana', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie down on your back with your knees bent, feet together on the floor, and arms resting at your sides.\r\n2. Raise your hips and straighten your thighs with your back while your knees are closed.\r\n3. Maintain this position, raise your arms and then land them overhead with your palms facing upward.\r\n4. Return to the initial position and repeat.', E'1. Keep your feet hip-width apart and ensure your knees stay aligned with your ankles to maintain proper form.\r\n2. Engage your core and glutes to support your lower back and maintain stability.\r\n3. Breathe deeply and evenly throughout the pose, relaxing your shoulders and neck.', '{"image_male_start":"images/Yoga/bridge pose setu bandhasana.jpg","image_male_end":"images/Yoga/bridge pose setu bandhasana1.jpg","video_url":"videos/Yoga/bridge pose setu bandhasana.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c1e836e0-1b66-4093-82d4-cdc70c448e1e'::uuid, 'Bridge with alternating leg raise', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by lying on your back with your knees bent, feet flat on the floor, and arms resting by your sides.\r\n2. Lift your hips off the floor to form a straight line from your shoulders to your knees, engaging your glutes and core.\r\n3. While keeping your hips elevated, extend your right leg straight keeping it in level with torso, then lower it back to the starting position.\r\n4. Repeat the movement with your left leg, extending it straight keeping it in level with torso, then lowering it back to the starting position. Continue alternating sides for the desired number of repetitions.', E'1. Keep your core engaged to maintain stability and support your lower back.\r\n2. Ensure your hips remain elevated and level throughout the exercise to maximize glute activation.\r\n3. Perform the leg raises slowly and with control to avoid any jerky movements and to enhance muscle engagement.', '{"image_male_start":"images/Yoga/Bridge with Alternating Leg Raise  .jpg","video_url":"videos/Yoga/Bridge with Alternating Leg Raise  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ffccbcea-f380-4806-be21-28b9dacd70c2'::uuid, 'Briskly walking', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand upright with your feet hip-width apart and your arms relaxed by your sides.\r\n2. Begin walking at a brisk pace, ensuring that you take quick, short steps.\r\n3. Swing your arms naturally with each step, allowing them to move opposite to your legs for balance.\r\n4. Maintain this brisk pace for the desired duration or distance.', E'1. Keep your core engaged to maintain good posture and stability.\r\n2. Focus on a heel-to-toe motion with each step to ensure proper walking mechanics.\r\n3. Breathe steadily and rhythmically to support your pace and endurance.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Briskly Walking.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Briskly Walking1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Briskly Walking.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('21666f1a-cfe1-4497-b0b8-c21c72cdbd84'::uuid, 'Briskly Walking (360 degrees)', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand upright with your feet hip-width apart and your arms relaxed by your sides.\r\n2. Begin walking at a brisk pace, ensuring that you take quick, short steps.\r\n3. Swing your arms naturally with each step, allowing them to move opposite to your legs for balance.\r\n4. Maintain this brisk pace for the desired duration or distance.', E'1. Keep your core engaged to maintain good posture and stability.\r\n2. Focus on a heel-to-toe motion with each step to ensure proper walking mechanics.\r\n3. Breathe steadily and rhythmically to support your pace and endurance.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Briskly Walking (360 degrees).jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Briskly Walking (360 degrees)1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Briskly Walking (360 degrees).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e6b98bb7-1491-4d50-91ef-74d4037bd3bb'::uuid, 'Bulgarian split squat', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand a few feet in front of a bench or elevated surface, facing away from it. Place your left foot behind you on the bench, with the top of your foot resting on the surface.\r\n2. Position your right foot firmly on the floor, a comfortable distance in front of the bench.\r\n3. Lower your body by bending your right knee and hip, keeping your torso upright, until your right thigh is parallel to the floor.\r\n4. Push through your right heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs.', E'1. Keep your front knee aligned with your toes to avoid putting unnecessary strain on your knee.\r\n2. Focus on driving through the heel of your front foot to engage your glutes and quadriceps effectively.\r\n3. Maintain a slight forward lean to help with balance and ensure proper form throughout the exercise.', '{"image_male_start":"images/Legs/Bulgarian Split Squat.jpg","image_male_end":"images/Legs/Bulgarian Split Squat1.jpg","video_url":"videos/Legs/Bulgarian Split Squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('32d9343d-454d-403c-8b4e-8f3d85dc2308'::uuid, 'Bulgarian split squat bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand a few feet in front of a bench or elevated surface, facing away from it. Place your left foot behind you on the bench, with the top of your foot resting on the surface.\r\n2. Position your right foot firmly on the floor, a comfortable distance in front of the bench.\r\n3. Lower your body by bending your right knee and hip, keeping your torso upright, until your right thigh is parallel to the floor.\r\n4. Push through your right heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs.', E'1. Keep your front knee aligned with your toes to avoid putting unnecessary strain on your knee.\r\n2. Focus on driving through the heel of your front foot to engage your glutes and quadriceps effectively.\r\n3. Maintain a slight forward lean to help with balance and ensure proper form throughout the exercise.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f2bdb03e-a89a-49c4-9fe8-2ac30859e615'::uuid, 'bulgarian split squat bodyweight left', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand a few feet in front of a bench or elevated surface, facing away from it. Place your right foot behind you on the bench, with the top of your foot resting on the surface.\r\n2. Position your left foot firmly on the floor, a comfortable distance in front of the bench.\r\n3. Lower your body by bending your left knee and hip, keeping your torso upright, until your left thigh is parallel to the floor.\r\n4. Push through your left heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs.', E'1. Keep your front knee aligned with your toes to avoid putting unnecessary strain on your knee.\r\n2. Focus on driving through the heel of your front foot to engage your glutes and quadriceps effectively.\r\n3. Maintain a slight forward lean to help with balance and ensure proper form throughout the exercise.', '{"image_male_start":"images/Legs/bulgarian split squat bodyweight left  .jpg","video_url":"videos/Legs/bulgarian split squat bodyweight left  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('bf47e36f-d57b-4120-a2bf-ffc316bd7188'::uuid, 'bulgarian split squat bodyweight right', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand a few feet in front of a bench or elevated surface, facing away from it. Place your left foot behind you on the bench, with the top of your foot resting on the surface.\r\n2. Position your right foot firmly on the floor, a comfortable distance in front of the bench.\r\n3. Lower your body by bending your right knee and hip, keeping your torso upright, until your right thigh is parallel to the floor.\r\n4. Push through your right heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs.', E'1. Keep your front knee aligned with your toes to avoid putting unnecessary strain on your knee.\r\n2. Focus on driving through the heel of your front foot to engage your glutes and quadriceps effectively.\r\n3. Maintain a slight forward lean to help with balance and ensure proper form throughout the exercise.', '{"image_male_start":"images/Legs/bulgarian split squat bodyweight right  .jpg","video_url":"videos/Legs/bulgarian split squat bodyweight right  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0aeb5cce-7a17-4181-8235-e3ab9b699b34'::uuid, 'Bulgarian split squat cable Resistance band', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Place one foot behind you on a bench or step, with your other foot forward. Secure the resistance band under your front foot.\r\n2. Hold the handles of the resistance band with your palms facing forward, elbows bent, and hands raised near your shoulders. Keep your arms folded by your sides.\r\n3. Lower your body towards the floor by bending the front knee, stopping just before your back knee touches the floor\r\n4. Push through your front heel to return to the starting position. Repeat the movement for the desired number of repetitions before switching legs.', E'1. Maintain an upright posture throughout the exercise to prevent leaning forward or arching your back.\r\n2. Exhale as you push back up to the starting position and inhale as you lower down.\r\n3. Ensure your front knee does not extend past your toes to prevent strain on your knee joint.', '{"image_male_start":"images/Legs/bulgarian split squat cable resistance band  .jpg","video_url":"videos/Legs/bulgarian split squat cable resistance band  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('54be6e7b-677e-489c-8c98-3f6a4c8759f2'::uuid, 'Bulgarian split squat left bodyweight side view', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand a few feet in front of a bench or elevated surface, facing away from it. Place your right foot behind you on the bench, with the top of your foot resting on the surface.\r\n2. Position your left foot firmly on the floor, a comfortable distance in front of the bench.\r\n3. Lower your body by bending your left knee and hip, keeping your torso upright, until your left thigh is parallel to the floor.\r\n4. Push through your left heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs.', E'1. Keep your front knee aligned with your toes to avoid putting unnecessary strain on your knee.\r\n2. Focus on driving through the heel of your front foot to engage your glutes and quadriceps effectively.\r\n3. Maintain a slight forward lean to help with balance and ensure proper form throughout the exercise.', '{"image_male_start":"images/Legs/bulgarian split squat left bodyweight side view  .jpg","video_url":"videos/Legs/bulgarian split squat left bodyweight side view  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('26dd76a2-1ea7-4904-9de7-3102d34c61c7'::uuid, 'bulgarian split squat right bodyweight side view', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand a few feet in front of a bench or elevated surface, facing away from it. Place your left foot behind you on the bench, with the top of your foot resting on the surface.\r\n2. Position your right foot firmly on the floor, a comfortable distance in front of the bench.\r\n3. Lower your body by bending your right knee and hip, keeping your torso upright, until your right thigh is parallel to the floor.\r\n4. Push through your right heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs.', E'1. Keep your front knee aligned with your toes to avoid putting unnecessary strain on your knee.\r\n2. Focus on driving through the heel of your front foot to engage your glutes and quadriceps effectively.\r\n3. Maintain a slight forward lean to help with balance and ensure proper form throughout the exercise.', '{"image_male_start":"images/Legs/bulgarian split squat right bodyweight side view  .jpg","video_url":"videos/Legs/bulgarian split squat right bodyweight side view  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('add4d23f-477f-4278-9bb3-1cd25a18f61b'::uuid, 'Burpee', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by standing with your feet shoulder-width apart and your arms at your sides.\r\n2. Lower your body into a squat position and place your hands on the floor in front of you.\r\n3. Jump your feet back to land in a plank position, keeping your body in a straight line from head to heels.\r\n4. Perform a push-up, then jump your feet back towards your hands.\r\n5. Explode into a jump straight up, reaching your arms overhead. Land softly and immediately lower back into the squat position to begin the next repetition.', E'1. Start with a moderate pace to master the form, then gradually increase your speed as you become more comfortable with the movement.\r\n2. Ensure your movements are fluid and controlled to avoid unnecessary strain on your joints.\r\n3. Focus on landing softly during the jump to reduce impact on your knees and ankles.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Burpee.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Burpee1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Burpee.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('acd67d78-6580-4588-b8ce-77d311239fcc'::uuid, 'Burpee squat', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your arms at your sides, ready to begin the movement.\r\n2. Lower your body into a squat position and place your hands on the floor in front of you.\r\n3. Step your right foot back, then your left foot, to land in a plank position, keeping your body in a straight line from head to heels.\r\n4. Step your right foot forward, then your left foot, to return to the squat position, then stand up and repeat.', E'1. Start with a moderate pace to master the form, then gradually increase your speed as you become more comfortable with the movement.\r\n2. Engage your core to maintain stability and support your lower back throughout the exercise.\r\n3. Focus on keeping your knees aligned with your toes during the squat to prevent unnecessary strain on your joints.', '{"image_male_start":"images/Legs/Burpee Squat.jpg","image_male_end":"images/Legs/Burpee Squat1.jpg","video_url":"videos/Legs/Burpee Squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e5c0ebf4-b44c-47cf-9743-59581f405d3b'::uuid, 'Butt kick with row', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your arms extended in front of you, palms facing down.\r\n2. Bend your right knee to bring your heel towards your buttocks while simultaneously pulling your elbows back to perform a rowing motion.\r\n3. Return to the starting position and repeat the movement with your left leg, bringing your left heel towards your buttocks while pulling your elbows back.\r\n4. Continue alternating sides for the desired number of repetitions or duration.', E'1. Keep your upper body upright to maintain proper form and avoid leaning forward.\r\n2. Perform the rowing motion with controlled movements, squeezing your shoulder blades together as you pull your elbows back.\r\n3. Ensure each butt kick is high enough to effectively engage the hamstrings.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Butt Kick with Row.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Butt Kick with Row1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Butt Kick with Row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('dc70e41a-d876-4a10-be4b-aefa14e0c463'::uuid, 'Butt kicks', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your arms relaxed by your sides.\r\n2. Begin by jogging in place, lifting your heels towards your buttocks with each step. \r\n3. Alternate lifting your right and left heels in a quick, continuous motion, keeping your knees pointing down. Swing your arms naturally with each step, allowing them to move opposite to your legs for balance.\r\n4. Maintain a steady pace for the desired duration or number of repetitions.', E'1. Keep your upper body upright and avoid leaning forward to maintain proper form.\r\n2. Engage your core to support balance and stability throughout the exercise.\r\n3. Focus on a quick, light motion with each heel lift to effectively engage your hamstrings.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Butt Kicks.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Butt Kicks1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Butt Kicks.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('62d13ed3-86ae-4b63-9d94-e214371edcde'::uuid, 'Butt kicks slow', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your arms relaxed by your sides.\r\n2. Begin by jogging in place, lifting your heels towards your buttocks with each step. \r\n3. Alternate lifting your right and left heels in a quick, continuous motion, keeping your knees pointing down. Swing your arms naturally with each step, allowing them to move opposite to your legs for balance.\r\n4. Maintain a steady pace for the desired duration or number of repetitions.', E'1. Keep your upper body upright and avoid leaning forward to maintain proper form.\r\n2. Engage your core to support balance and stability throughout the exercise.\r\n3. Focus on a quick, light motion with each heel lift to effectively engage your hamstrings.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Butt kicks slow  .jpg","video_url":"videos/Calisthenics-Cardio-Functional/Butt kicks slow  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5c0d8a53-162e-47eb-a35e-3f93985f588a'::uuid, 'Butterfly yoga flaps', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on the floor with your legs bent and the soles of your feet pressed together, allowing your knees to fall out to the sides.\r\n2. Hold your feet with both hands and sit up tall, lengthening your spine.\r\n3. Gently flap your knees up and down like the wings of a butterfly, keeping your movements smooth and controlled.\r\n4. Continue the flapping motion for the desired duration or number of repetitions.', E'1. Keep your back straight and avoid slouching to maintain proper posture.\r\n2. Breathe deeply and evenly throughout the exercise to relax your muscles and enhance the stretch.\r\n3. Perform the flapping motion gently to avoid straining your hip joints and inner thighs.', '{"image_male_start":"images/Stretching - Mobility/Butterfly Yoga Flaps.jpg","image_male_end":"images/Stretching - Mobility/Butterfly Yoga Flaps1.jpg","video_url":"videos/Stretching - Mobility/Butterfly Yoga Flaps.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6364569f-493a-42cd-80c8-a95e3639f04d'::uuid, 'Butterfly yoga pose', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on the floor with your legs bent and the soles of your feet pressed together, allowing your knees to fall out to the sides.\r\n2. Hold your feet with both hands and sit up tall, then lean forward slightly towards the floor, creating a gentle arch in your back.\r\n3. Press your knees gently towards the floor to deepen the stretch in your hips.\r\n4. Hold the position for the desired duration, breathing deeply and evenly throughout.', E'1. Maintain a gentle arch in your back while leaning forward to ensure a proper stretch and avoid straining.\r\n2. Inhale deeply and exhale slowly throughout the pose to help relax your muscles and enhance the stretch.\r\n3. Apply gentle pressure to your knees without forcing them down to prevent overstraining your hip joints.', '{"image_male_start":"images/Yoga/Butterfly Yoga Pose.jpg","image_male_end":"images/Yoga/Butterfly Yoga Pose1.jpg","video_url":"videos/Yoga/Butterfly Yoga Pose.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6be14923-c73d-4cd0-8819-dba3aff98568'::uuid, 'Cable alternate triceps extension', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Stand with your back facing the low pulley, holding the handle behind your head with your arm bent, elbow pointing up and palm facing the ceiling. Use your other hand to support the active arm by holding it just above the elbow.\r\n2. Extend your active arm up overhead, straightening your elbow to push the handle upward.\r\n3. Slowly return your arm to the starting position behind your head. Repeat the movement for the desired number of repetitions, then switch arms.', E'1. Keep your upper arm stationary throughout the exercise to isolate the triceps.\r\n2. Avoid using momentum; perform the movement slowly and with control.\r\n3. Exhale as you extend your arm and inhale as you return to the starting position.', '{"image_male_start":"images/Triceps/Cable Alternate Triceps Extension.jpeg","video_url":"videos/Triceps/Cable Alternate Triceps Extension.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0d4d890a-7a6a-4e68-ab56-569c0c945797'::uuid, 'Cable assisted inverse leg curl', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Kneel on the seat of a cable pulldown machine with both legs secured under the thigh pads. Face away from the machine and hold the cable bar behind your neck with both hands.\r\n2. Lean forward to straighten your legs until your torso is almost parallel to the floor.\r\n3. Slowly return to the starting position by bringing your upper body back up, bending at the knees.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Perform the movement slowly and with control to maximize muscle activation and reduce the risk of injury.\r\n2. Avoid using momentum; focus on the controlled contraction of your hamstrings.\r\n3. Exhale as you straighten your legs and inhale as you return to the starting position.', '{"image_male_start":"images/Legs/Cable Assisted Inverse Leg Curl.jpg","image_male_end":"images/Legs/Cable Assisted Inverse Leg Curl1.jpg","video_url":"videos/Legs/Cable Assisted Inverse Leg Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('dad69787-8321-465c-a8af-02691b721894'::uuid, 'Cable bar lateral pulldown', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd8a6a67e-71db-4542-9dd7-a185a3e773af'::uuid, E'1. Sit at a cable pulldown machine with your feet flat on the floor and knees secured under the pads. Grasp the bar with a wide overhand grip, your arms fully extended overhead.\r\n2. Lean back slightly, keeping your back straight and core engaged.\r\n3. Pull the bar down towards your upper chest, bringing your elbows down and back.\r\n4. Slowly return the bar to the starting position with your arms fully extended overhead. Repeat the movement for the desired number of repetitions.', E'1. Avoid using momentum; perform the movement slowly and with control.\r\n2. Exhale as you pull the bar down and inhale as you return to the starting position.\r\n3. Focus on the contraction of your back muscles as you pull the bar down.', '{"image_male_start":"images/Back/Cable Bar Lateral Pulldown.jpg","image_male_end":"images/Back/Cable Bar Lateral Pulldown1.jpg","video_url":"videos/Back/Cable Bar Lateral Pulldown.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2a250a0c-dbfd-4bca-beee-dab14a765925'::uuid, 'Cable bench fly press', 'Resistance', 'strength', 'weight_reps', 'intermediate', '7c8ccea6-1ecd-4abd-a28f-2f05d0d539a5'::uuid, E'1. Lie on a flat bench positioned between two cable machines, with the cables set at a low position. Grasp the handles with your arms bent and hands close to your chest sides.\r\n2. Press the handles upward in an arc motion over your chest, extending your arms upward.\r\n3. Lower the handles back down to the starting position, stopping when your hands are close to your chest sides.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Exhale as you press the handles up and inhale as you lower them back down.\r\n2. Ensure your back remains flat against the bench and avoid arching your spine.\r\n3. Focus on the contraction of your chest muscles as you press the handles up.', '{"image_male_start":"images/Chest/Cable Bench Fly Press.jpg","image_male_end":"images/Chest/Cable Bench Fly Press1.jpg","video_url":"videos/Chest/Cable Bench Fly Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('add4a29d-a71c-49bc-bffc-a69e1747100d'::uuid, 'Cable bench press', 'Resistance', 'strength', 'weight_reps', 'intermediate', '7c8ccea6-1ecd-4abd-a28f-2f05d0d539a5'::uuid, E'1. Lie on a flat bench positioned between two pulley cables, with the cables set at a low position. \r\n2. Grasp the handles with your arms bent and hands close to your chest sides.\r\n3. Press the handles upward in a straight line over your chest, extending your arms fully.\r\n4. Lower the handles back down to the starting position. Repeat the movement for the desired number of repetitions', E'1. Exhale as you press the handles up and inhale as you lower them back down.\r\n2. Ensure your back remains flat against the bench and avoid arching your spine.\r\n3. Focus on the contraction of your chest muscles as you press the handles up.', '{"image_male_start":"images/Chest/Cable Bench Press.jpg","image_male_end":"images/Chest/Cable Bench Press1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('135633a8-d7ee-4905-aa70-5a0514861c67'::uuid, 'Cable bent over one arm lateral raise', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Attach a single handle to a low pulley on a cable machine. Stand to the side of the machine with your right side facing it, and grasp the handle with the left hand, allowing the cable to cross in front of your body.\r\n2. Bend at the hips until your upper body is nearly parallel to the floor, keeping your knees slightly bent and your back flat. Let the arm holding the handle hang straight down.\r\n3. Raise the handle out to the side until your hand is at shoulder level, keeping a slight bend in your elbow.\r\n4. Slowly lower the handle back to the starting position. Repeat the movement for the desired number of repetitions.', E'1. Perform the movement slowly and with control to maximize muscle activation and reduce the risk of injury.\r\n2. Keep a slight bend in your elbow throughout the exercise to reduce strain on your joints.\r\n3. Avoid using momentum or swinging your body; focus on isolating the shoulder muscle.', '{"image_male_start":"images/Shoulders/Cable Bent Over One Arm Lateral Raise.jpg","image_male_end":"images/Shoulders/Cable Bent Over One Arm Lateral Raise1.jpg","video_url":"videos/Shoulders/Cable Bent Over One Arm Lateral Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('010acde6-3efb-49c7-9eb7-8015859c16be'::uuid, 'Cable bent over reverse grip row', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Attach a straight bar to a low pulley on a cable machine. Stand facing the machine and grasp the bar with an underhand grip (palms facing up), hands shoulder-width apart.\r\n2. Bend at the hips to form a 90 degree angle with your upper body, keeping your knees slightly bent. Let your arms extend with the cable, holding the bar.\r\n3. Pull the bar towards your lower abdomen, bringing your elbows backwards.\r\n4. Slowly extend the bar back to the starting position. Repeat the movement for the desired number of repetitions.', E'1. Perform the movement slowly and with control to maximize muscle activation and reduce the risk of injury.\r\n2. Exhale as you pull the bar towards you and inhale as you lower it back down.\r\n3. Avoid using momentum or swinging your body; focus on isolating the back muscles.', '{"image_male_start":"images/Back/Cable Bent Over Reverse Grip Row.jpg","image_male_end":"images/Back/Cable Bent Over Reverse Grip Row1.jpg","video_url":"videos/Back/Cable Bent Over Reverse Grip Row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('87e9be0e-5e96-408d-a488-70c39d709a96'::uuid, 'Cable bent over row', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Attach a straight bar to a low pulley on a cable machine. Stand facing the machine and grasp the bar with an overhand grip (palms facing down), hands shoulder-width apart.\r\n2. Bend at the hips to form a 90 degree angle with your upper body, keeping your knees slightly bent. Let your arms extend with the cable, holding the bar.\r\n3. Pull the bar towards your lower abdomen, bringing your elbows backwards.\r\n4. Slowly extend the bar back to the starting position. Repeat the movement for the desired number of repetitions.', E'1. Perform the movement slowly and with control to maximize muscle activation and reduce the risk of injury.\r\n2. Exhale as you pull the bar towards you and inhale as you lower it back down.\r\n3. Avoid using momentum or swinging your body; focus on isolating the back muscles.', '{"image_male_start":"images/Back/Cable Bent Over Row.jpg","image_male_end":"images/Back/Cable Bent Over Row1.jpg","video_url":"videos/Back/Cable Bent Over Row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4570b905-b488-4630-bf45-790b226f34e7'::uuid, 'Cable biceps curl (EZ bar)', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Stand facing the pulley machine and grasp the EZ-bar with an underhand grip (palms facing up), hands shoulder-width apart.\r\n2. Stand with your feet shoulder-width apart, keeping your back straight and core engaged. Hold the bar extending in front of your thighs.\r\n3. Curl the bar upwards towards your shoulders by bending your elbows. Keeping your upper arms stationary and focusing on contracting your biceps.\r\n4. Slowly lower the bar back to the starting position with your arms fully extended. Repeat the movement for the desired number of repetitions.', E'1. Focus on squeezing your biceps at the top of the movement.\r\n2. Exhale as you curl the bar up and inhale as you lower it back down.\r\n3. Keep your elbows close to your torso throughout the exercise.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e26410c7-cf38-4991-82af-f8d3f3ce5ac4'::uuid, 'Cable close grip curl', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Stand facing the pulley machine and grasp the bar with an underhand grip (palms facing up), hands closer than shoulder-width apart.\r\n2. Stand with your feet shoulder-width apart, keeping your back straight and core engaged. Hold the bar extending in front of your thighs.\r\n3. Curl the bar upwards towards your shoulders by bending your elbows. Keeping your upper arms stationary and focusing on contracting your biceps.\r\n4. Slowly lower the bar back to the starting position with your arms fully extended. Repeat the movement for the desired number of repetitions.', E'1. Start with a lighter weight to ensure proper form and gradually increase the resistance as you build strength.\r\n2. Focus on squeezing your biceps at the top of the movement.\r\n3. Maintain a neutral wrist position to prevent strain.', '{"image_male_start":"images/Biceps/Cable Close Grip Curl.jpeg","video_url":"videos/Biceps/Cable Close Grip Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('16c885e0-240e-4387-be84-1046ae04e49b'::uuid, 'Cable close grip front lat pulldown', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Sit at the lat pulldown machine with your feet flat on the floor and knees secured under the pads. Grasp the bar attached to the machine with your arms fully extended above you, hands closer than shoulder-width and palms facing forward.\r\n2. Pull the bar down towards your upper chest, bringing your elbows down and back while slightly leaning back.\r\n3. Slowly return the handle to the starting position with your arms fully extended overhead.\r\n4. Repeat for the desired number of repetitions.', E'1. Perform the movement slowly and with control.\r\n2. Exhale as you pull the handle down and inhale as you return to the starting position.\r\n3. Ensure your chest stays up and your shoulders down to avoid rounding your back.', '{"image_male_start":"images/Back/Cable Close Grip Front Lat Pulldown.jpg","image_male_end":"images/Back/Cable Close Grip Front Lat Pulldown1.jpg","video_url":"videos/Back/Cable Close Grip Front Lat Pulldown.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('37f10c27-ef4c-401f-9751-da1c4600d90e'::uuid, 'Cable front raises straight bar', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Attach a straight bar to a low pulley on a cable machine. Stand facing away from the machine, with your feet shoulder-width apart and the bar held with an overhand grip, palms facing down.\r\n2. Stand upright with your back straight and core engaged. Let the bar hang down in front of your thighs with your arms fully extended and the cable passing between your legs.\r\n3. Raise the bar in front of you to shoulder height, keeping your arms straight but with a slight bend in the elbows.\r\n4. Slowly lower the bar back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you raise the bar and inhale as you lower it back down.\r\n2. Avoid using momentum; focus on the contraction of your shoulder muscles.\r\n3. Ensure your shoulders stay down and relaxed, not shrugged up towards your ears.', '{"image_male_start":"images/Shoulders/cable front raises straight bar .jpg","video_url":"videos/Shoulders/cable front raises straight bar .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('894e9e1f-4746-4fe8-ac66-23f37c4f2c89'::uuid, 'Cable lateral raises', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand in the middle of a cable machine with the handles attached to the low pulleys on either side, with your feet shoulder-width apart. Hold the left handle with your right hand and the right handle with your left hand, with the cables crossing in front of you. Stand \r\n2. Stand upright with your back straight. Let the handles hang down in front of your thighs with your arms fully extended.\r\n3. Raise the handles out to your sides until your arms are parallel to the floor, keeping a slight bend in your elbows.\r\n4. Slowly lower the handles back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Choose a weight that allows you to complete the exercise with proper form.\r\n2. Exhale as you raise the handles and inhale as you lower them back down.\r\n3. Avoid using momentum; focus on the contraction of your shoulder muscles.', '{"image_male_start":"images/Shoulders/cable lateral raises.jpg","image_male_end":"images/Shoulders/cable lateral raises1.jpg","video_url":"videos/Shoulders/cable lateral raises.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('fba4a42e-36bd-47cf-ac3c-065657825bda'::uuid, 'Cable leaning lateral raise', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Attach a single handle to a low pulley on a cable machine. Stand next to the machine on your left side, holding the handle with your right hand. Lean away from the machine, using your left hand to hold onto the machine for support.\r\n2. Position your feet together, with your outside foot slightly in front for better stability. Let the handle hang down at your side with your arm fully extended.\r\n3. Raise the handle out to the side until your arm is parallel to the floor, keeping a slight bend in your elbow.\r\n4. Slowly lower the handle back to the starting position with control. Repeat for the desired number of repetitions, then switch sides.', E'1. Exhale as you raise the handle and inhale as you lower it back down.\r\n2. Avoid using momentum; focus on the contraction of your shoulder muscles.\r\n3. Lean away from the machine to increase the range of motion and target the shoulder muscles more effectively.', '{"image_male_start":"images/Shoulders/cable leaning lateral raise.jpg","image_male_end":"images/Shoulders/cable leaning lateral raise1.jpg","video_url":"videos/Shoulders/cable leaning lateral raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a1a7a833-4a6e-4221-9724-e48300bd70f5'::uuid, 'Cable low fly', 'Resistance', 'strength', 'weight_reps', 'intermediate', '7c8ccea6-1ecd-4abd-a28f-2f05d0d539a5'::uuid, E'1. Stand in the center of a cable machine with the pulleys set at a low position. Grasp the handles with your palms facing forward and arms extended down out to your sides. Position your feet shoulder-width apart and slightly staggered for stability.\r\n2. Stand upright with your back straight. Bring the handles together in front of your body in a wide arc, keeping a slight bend in your elbows and palms should face upwards.\r\n3. Slowly return the handles to the starting position with control, maintaining the slight bend in your elbows.\r\n4. Repeat for the desired number of repetitions.', E'1. Focus on the contraction of your chest muscles as you bring the handles together.\r\n2. Perform the movement slowly and with control to maximize muscle activation and reduce the risk of injury.\r\n3. Exhale as you bring the handles together and inhale as you return them to the starting position.', '{"image_male_start":"images/Chest/Cable low fly.jpg","image_male_end":"images/Chest/Cable low fly1.jpg","video_url":"videos/Chest/Cable low fly.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('cd0b53b6-aa05-458a-93f0-ec04147bcb00'::uuid, 'Cable low seated row', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Sit on the pulldown machine with your feet placed securely under the knee pads. Grasp the bar with both hands, hands at shoulder-width apart and palms facing down.\r\n2. Sit upright with your back straight and core engaged, extending your arms fully in front of you.\r\n3. Pull the bar towards your lower abdomen, bringing your elbows back and squeezing your shoulder blades together.\r\n4. Slowly extend your arms back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep your back straight throughout the exercise to avoid strain.\r\n2. Engage your core to maintain stability and proper posture.\r\n3. Perform the movement slowly and with control to maximize muscle activation and reduce the risk of injury.', '{"image_male_start":"images/Back/cable low seated row.jpg","image_male_end":"images/Back/cable low seated row1.jpg","video_url":"videos/Back/cable low seated row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b380b705-1618-4be7-be47-57097a8e964a'::uuid, 'cable lying extension pullover (with cables attachment)', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Attach both cable handles to a single low pulley. Lie on a flat bench with your head positioned near the pulley. Grasp the handles with your palms facing up and your arms extended in line with your body.\r\n2. Keep your feet flat on the floor and your back pressed against the bench. Engage your core to maintain stability.\r\n3. Raise the handles in an arc motion over your head, keeping a slight bend in your elbows.\r\n4. Lower the handles back to the starting position. Repeat for the desired number of repetitions.', E'1. Keep a slight bend in your elbows throughout the exercise to reduce strain on your joints.\r\n2. Focus on the contraction of your lats and triceps as you pull the handles up.\r\n3. Exhale as you pull the handles back to the starting position and inhale as you lower them.', '{"image_male_start":"images/Back/cable lying extension pullover (with cables attachment).jpg","image_male_end":"images/Back/cable lying extension pullover (with cables attachment)1.jpg","video_url":"videos/Back/cable lying extension pullover (with cables attachment).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('92ad40b0-f682-4b64-b226-98afa85388e4'::uuid, 'Cable lying fly', 'Resistance', 'strength', 'weight_reps', 'intermediate', '7c8ccea6-1ecd-4abd-a28f-2f05d0d539a5'::uuid, E'1. Lie on a flat bench between a dual crossover machine and your feet flat on the floor. Grasp the handles with your palms facing up and arms extended to the sides at chest level.\r\n2. Raise the handles over your chest in a wide arc motion, keeping a slight bend in your elbows. \r\n3. Return to the starting position by lowering the handles out to your sides in a wide arc motion.\r\n4. Repeat for the desired number of repetitions.', E'1. Focus on the contraction of your chest muscles as you bring the handles together.\r\n2. Start with a lighter weight to ensure proper form and gradually increase the resistance as you build strength.\r\n3. Make sure the bench is stable and positioned securely between the cable machines.', '{"image_male_start":"images/Chest/cable lying fly.jpg","image_male_end":"images/Chest/cable lying fly1.jpg","video_url":"videos/Chest/cable lying fly.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e99c2efc-b897-40b9-a89c-7b5b2f49e0b8'::uuid, 'Cable lying triceps extension', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Attach a straight bar to the middle pulley of a cable machine. Lie on a flat bench with your head positioned near the pulley. Grasp the bar or rope with an overhand grip, your arms extended straight up above your chest.\r\n2. Lower the bar towards your forehead by bending your elbows, keeping your upper arms stationary.\r\n3. Just before touching your forehead, extend your arms back to the starting position, focusing on contracting your triceps.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep your upper arms stationary and only move your forearms to isolate the triceps.\r\n2. Focus on the contraction of your triceps as you extend your arms.\r\n3. Exhale as you extend your arms and inhale as you lower the bar.', '{"image_male_start":"images/Triceps/cable lying triceps extension.jpeg","video_url":"videos/Triceps/cable lying triceps extension.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('849f8895-5e75-4e94-8424-2285735dfdc2'::uuid, 'Cable lying triceps extension (low)', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Attach a straight bar to the low pulley of a cable machine. Lie on a flat bench with your head positioned near the pulley. Grasp the bar or rope with an overhand grip, your arms extended straight up above your chest.\r\n2. Lower the bar towards your forehead by bending your elbows, keeping your upper arms stationary.\r\n3. Just before touching your forehead, extend your arms back to the starting position, focusing on contracting your triceps.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep your upper arms stationary and only move your forearms to isolate the triceps.\r\n2. Focus on the contraction of your triceps as you extend your arms.\r\n3. Exhale as you extend your arms and inhale as you lower the bar.', '{"image_male_start":"images/Triceps/cable lying triceps extension (LOW).jpeg","video_url":"videos/Triceps/cable lying triceps extension (LOW).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('bd693e8e-a8a3-4ab4-a44c-e43bbddce46a'::uuid, 'Cable machine high to low', 'Resistance', 'strength', 'weight_reps', 'intermediate', '7c8ccea6-1ecd-4abd-a28f-2f05d0d539a5'::uuid, E'1. Stand in the center of a cable machine with the pulleys set at a high position. Grasp the handles with your palms facing forward and arms extended down out to your sides. Position your feet shoulder-width apart and slightly staggered for stability.\r\n2. Stand upright with your back straight. Bring the handles together in front of your body in a wide arc, keeping a slight bend in your elbows and palms should face upwards.\r\n3. Slowly return the handles to the starting position with control, maintaining the slight bend in your elbows.\r\n4. Repeat for the desired number of repetitions.', E'1. Focus on the contraction of your chest muscles as you bring the handles together.\r\n2. Perform the movement slowly and with control to maximize muscle activation and reduce the risk of injury.\r\n3. Exhale as you bring the handles together and inhale as you return them to the starting position.', '{"image_male_start":"images/Chest/cable machine high to low.jpg","image_male_end":"images/Chest/cable machine high to low1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('fe3c21d0-5d1b-4f7d-bf4a-9a5cb5cfd947'::uuid, 'Cable middle fly', 'Resistance', 'strength', 'weight_reps', 'intermediate', '7c8ccea6-1ecd-4abd-a28f-2f05d0d539a5'::uuid, E'1. Stand in the center of a cable fly machine with the pulleys set at mid-chest height, with one foot in front of the other and knees slightly bent. Hold the handles with both hands, arms extended out to the sides at shoulder height, palms facing forward.\r\n2. Keep your back straight and maintain a slight bend at the hips and knees for stability.\r\n3. Pull the handles together in front of your chest in a wide arc, keeping your arms slightly bent, until your hands meet in the centerline of your chest.\r\n4. Slowly extend your arms back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep a slight bend in your elbows throughout the exercise to reduce strain on your joints.\r\n2. Perform the movement slowly and with control to maximize muscle activation and reduce the risk of injury.\r\n3. Exhale as you bring the handles together and inhale as you return them to the starting position.', '{"image_male_start":"images/Chest/Cable Middle Fly.jpg","image_male_end":"images/Chest/Cable Middle Fly1.jpg","video_url":"videos/Chest/Cable Middle Fly.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('056e8177-9b5b-4b72-95f1-3f2fd9d3525e'::uuid, 'Cable narrow chair stand-up', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Attach a rope to the low pulley on the machine. Grasp the end of the rope in each hand and bring it close to your chest.Feet close together, flat on the floor, knees bent at a 90-degree angle.\r\n2. Push through your heels and extend your legs to stand up, keeping the handles close to your chest.\r\n3. Slowly lower yourself back down to the seated position, controlling the movement. \r\n4. Repeat for the desired number of repetitions.', E'1. Focus on pushing through your heels to engage your glutes and quads effectively.\r\n2. Exhale as you stand up and inhale as you sit back down.\r\n3. Ensure your back remains straight and avoid rounding your spine.', '{"image_male_start":"images/Legs/Cable Narrow Chair Stand-Up.jpg","image_male_end":"images/Legs/Cable Narrow Chair Stand-Up1.jpg","video_url":"videos/Legs/Cable Narrow Chair Stand-Up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c3ae5cfd-9ed6-4664-9d94-e16f2eb7773e'::uuid, 'Cable neutral grip kickback', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Attach a handle to a middle pulley on a cable machine. Stand facing the machine and grasp the handle with your left hand, using a neutral grip (palm facing your body). Step back to create tension in the cable.\r\n2. Position your feet shoulder-width apart and bend slightly at the hips, keeping your back straight and core engaged. Your upper arm should be parallel to the floor and close to your body with your elbow bent at a 90-degree angle.\r\n3. Extend your left arm straight back by straightening your elbow, keeping your upper arm stationary and focusing on contracting your triceps.\r\n4. Slowly return your arm to the starting position with control. Repeat for the desired number of repetitions, then switch to your right hand.', E'1. Keep your upper arm stationary and only move your forearm to isolate the triceps.\r\n2. Perform the movement slowly and with control to maximize muscle activation and reduce the risk of injury.\r\n3. Exhale as you extend your arm and inhale as you return to the starting position.', '{"image_male_start":"images/Triceps/Cable Neutral Grip Kickback.jpeg","video_url":"videos/Triceps/Cable Neutral Grip Kickback.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('33fbcbe1-f221-4854-ba59-a1ab8d7d3b5b'::uuid, 'Cable one arm bent over row', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Attach a single handle to a low pulley on a cable machine. Stand facing the machine, holding the handle with your left hand. Step back with one foot to create tension in the cable.\r\n2. Bend at the hips slightly to the floor, keeping your knees bent and your back flat. Place your right hand on your right knee for support.\r\n3. Pull the handle towards your lower abdomen, bringing your elbow back. Focus on squeezing your shoulder blade towards your spine.\r\n4. Slowly extend your arm back to the starting position with control. Repeat for the desired number of repetitions, then switch to your right hand.', E'1. Exhale as you pull the handle towards you and inhale as you extend your arm back.\r\n2. Start with a lighter weight to ensure proper form and gradually increase the resistance as you build strength.\r\n3. Focus on the contraction of your back muscles as you pull the handle towards you.', '{"image_male_start":"images/Back/Cable One Arm Bent over Row.jpg","image_male_end":"images/Back/Cable One Arm Bent over Row1.jpg","video_url":"videos/Back/Cable One Arm Bent over Row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('dc1b2294-2c48-4a08-96df-b5584137931d'::uuid, 'Cable One Arm Chest Fly Bent', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand in the center of a cable fly machine with the pulleys set at mid-chest height, with feet just wider than shoulder-width and bend at the hips and knees and lean towards the floor. Place your left hand to your knee for support. \r\n2. Hold the handle with your right hand, arm extended out to the side at shoulder height, palm facing forward. Bring the handle opposite your chest in a wide arc motion, keeping a slight bend in your elbows.\r\n3. Slowly return the handles to the starting position, maintaining control and the bend in your elbow.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep a slight bend in your elbows throughout the exercise to reduce strain on your joints.\r\n2. Start with a lighter weight to ensure proper form and gradually increase the resistance as you build strength.\r\n3. Focus on squeezing your chest muscles as you bring the handles together.', '{"image_male_start":"images/Chest/Cable One Arm Chest Fly Bent.jpg","image_male_end":"images/Chest/Cable One Arm Chest Fly Bent1.jpg","video_url":"videos/Chest/Cable One Arm Chest Fly Bent.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5d4e09dc-ae99-4cd7-a8d2-6bd8e25dfeba'::uuid, 'Cable one arm curl', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Attach a single handle to a low pulley on a cable machine. Stand facing the machine, holding the handle with your right hand, palm facing forward.\r\n2. Stand with your feet shoulder-width apart, keeping your back straight. Let your arm fully extend down by your side.\r\n3. Curl the handle upwards towards your shoulder by bending your elbow, keeping your upper arm stationary and close to your body.\r\n4. Slowly lower the handle back to the starting position with control. Repeat for the desired number of repetitions, then switch to your left hand.', E'1. Keep your elbow close to your torso throughout the exercise.\r\n2. Exhale as you curl the handle up and inhale as you lower it back down.\r\n3. Focus on squeezing your biceps at the top of the movement.', '{"image_male_start":"images/Biceps/Cable One Arm Curl.jpeg","video_url":"videos/Biceps/Cable One Arm Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e3b06b37-9dc8-4b30-ab0a-32bbd2afc7ea'::uuid, 'Cable one arm front raise', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Attach a single handle to a low pulley on a cable machine. Stand facing away from the machine, holding the handle with your right hand, palm facing back. Step forward to create tension in the cable.\r\n2. Stand with your feet shoulder-width apart, keeping your back straight. Let your arm fully extend down by your side.\r\n3. Raise the handle straight in front of you to shoulder height, keeping your arm straight but with a slight bend in the elbow.\r\n4. Slowly lower the handle back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Avoid locking your elbow; keep a slight bend to reduce strain on your joints.\r\n2. Exhale as you raise the handle and inhale as you lower it back down.\r\n3. Avoid locking your elbow; keep a slight bend to reduce strain on your joints.', '{"image_male_start":"images/Shoulders/Cable One Arm Front Raise.jpg","image_male_end":"images/Shoulders/Cable One Arm Front Raise1.jpg","video_url":"videos/Shoulders/Cable One Arm Front Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('273a3695-da5f-4e6c-9be3-eb8d26c5f8c4'::uuid, 'Cable one arm inner biceps curl', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Stand with your feet shoulder-width apart, keeping your back straight, with your right side facing the machine, holding the handle with your right hand, arm extended at shoulder height parallel to the floor, palm facing up.\r\n2. Curl the handle towards your shoulder by bending your elbow, keeping your upper arm stationary and parallel to the floor.\r\n3. Slowly extend your arm back to the starting position with control.\r\n4. Repeat for the desired number of repetitions, then switch to your left hand.', E'1. Focus on squeezing your biceps at the top of the movement.\r\n2. Exhale as you curl the handle up and inhale as you extend it back.\r\n3. Keep your elbow at shoulder height and stationary throughout the exercise.', '{"image_male_start":"images/Biceps/Cable One Arm Inner Biceps Curl.jpeg","video_url":"videos/Biceps/Cable One Arm Inner Biceps Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('eac95ff5-73e3-43d6-a9e3-ddb799ddafdf'::uuid, 'Cable one arm lat pulldown', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Sit at the lat pulldown machine with your feet flat on the floor and knees secured under the pads. Grasp the handle attached to the high pulley with your right hand, arm fully extended above you, palm facing forward.\r\n2. Pull the handle down towards your right shoulder, bringing your elbow down while slightly leaning back.\r\n3. Slowly extend your arm back to the starting position with control.\r\n4. Repeat for the desired number of repetitions, then switch to your left hand.', E'1. Exhale as you pull the handle down and inhale as you extend it back.\r\n2. Focus on squeezing your shoulder blade towards your spine as you pull down.\r\n3. Maintain a neutral wrist position to prevent strain.', '{"image_male_start":"images/Back/Cable one arm lat pulldown.jpg","image_male_end":"images/Back/Cable one arm lat pulldown1.jpg","video_url":"videos/Back/Cable one arm lat pulldown.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b5ee341f-7004-4637-8fa1-555b3ae148f9'::uuid, 'Cable overhead curl', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Stand in the center of a cable machine with the pulleys set at the highest position. Grasp the handles with both hands, palms facing upward. Extend your arms out to the sides at shoulder height, almost parallel to the floor.\r\n2. Stand with your feet shoulder-width apart, keeping your back straight and elbows slightly bent.\r\n3. Curl the handles towards your head by bending your elbows, keeping your upper arms stationary.\r\n4. Slowly extend your arms back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you curl the handles towards your head and inhale as you extend them back.\r\n2. Keep your elbows stationary and at shoulder height throughout the exercise.\r\n3. Focus on squeezing your biceps at the top of the movement.', '{"image_male_start":"images/Biceps/Cable Overhead Curl.jpeg","video_url":"videos/Biceps/Cable Overhead Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ca7b7020-3a67-440c-b8e1-be4b1bf03cf6'::uuid, 'Cable overhead extension rope', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Attach a rope handle to the high pulley on a cable machine. Stand with your feet shoulder-width apart, back to the machine, and grasp the rope handle with both hands, palms facing each other.\r\n2. Step forward to create tension in the cable. Extend your arms straight in level with your torso, keeping your elbows close to your head.\r\n3. Lower the rope behind your head by bending your elbows, keeping your upper arms stationary.\r\n4. Extend your arms back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep your back straight and avoid using momentum.\r\n2. Focus on squeezing your triceps at the top of the movement.\r\n3. Exhale as you extend your arms and inhale as you lower the rope.', '{"image_male_start":"images/Triceps/cable overhead extension rope.jpeg","video_url":"videos/Triceps/cable overhead extension rope  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('23c0dd46-603b-40e3-b72f-2c02101488c6'::uuid, 'Cable palm rotational row', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, facing the cable machine. Attach a single handle to a middle pulley and hold it with your right hand, palm facing downwards.\r\n2. Bend slightly at the hips and knees, keeping your back straight, and extend your right arm forward.\r\n3. Pull the handle towards your body, rotating your palm to face upwards as you bring your elbow back, keeping it close to your torso.\r\n4. Slowly extend your arm back to the starting position, rotating your palm back to face inwards. Repeat for the desired number of repetitions, then switch to your left hand.', E'1. Focus on squeezing your back muscles at the top of the movement.\r\n2. Use a lighter weight to ensure proper form and gradually increase the resistance as you get stronger.\r\n3. Exhale as you pull the handle towards your body and inhale as you extend it back.', '{"image_male_start":"images/Back/cable palm rotational row.jpg","image_male_end":"images/Back/cable palm rotational row1.jpg","video_url":"videos/Back/cable palm rotational row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ceddd80e-c885-461d-90f4-f7c52bb20482'::uuid, 'Cable preacher curl', 'Resistance', 'strength', 'weight_reps', 'intermediate', '31083d5d-8548-4eea-84ef-fa925cdcc95e'::uuid, E'1. Sit on the preacher bench with your feet flat on the floor. Attach a straight bar to the low pulley of a cable machine and grasp the bar with both hands, shoulder-width apart, palms facing upwards.\r\n2. Position your upper arms on the preacher bench pad and extend your arms fully, holding the bar.\r\n3. Curl the bar towards your shoulders by bending your elbows, squeezing your biceps at the top of the movement.\r\n4. Lower the bar back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Exhale as you curl the bar up and inhale as you lower it back down.\r\n2. Maintain a neutral wrist position to prevent strain.\r\n3. Focus on squeezing your biceps at the top of the movement.', '{"image_male_start":"images/Biceps/Cable Preacher Curl.jpeg","video_url":"videos/Biceps/Cable Preacher Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0b6a983e-3fa6-4056-b0f6-c45702118836'::uuid, 'Cable pull through', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Stand in the middle of a cable pulley machine with a rope attached at a low position. Hold the handles between your thighs with your back facing the machine, and the cables extending back.\r\n2. Spread your feet just wider than shoulder-width, lean forward, bending at the hips and knees into a semi-squat position, while keeping your back straight and your arms extended.\r\n3. Extend your hips forward to straighten your body, pushing the handles with your thighs.\r\n4. Return to the starting semi-squat position with control. Repeat for the desired number of repetitions.', E'1. Avoid using your lower back to lift; the movement should come from your hips.\r\n2. Focus on engaging your glutes and hamstrings as you extend your hips.\r\n3. Exhale as you extend your hips forward and inhale as you return to the starting position.', '{"image_male_start":"images/Legs/cable pull through.jpg","image_male_end":"images/Legs/cable pull through1.jpg","image_female_start":"images/Legs/Cable Pull Through_Female.jpg","image_female_end":"images/Legs/Cable Pull Through_Female1.jpg","video_url":"videos/Legs/cable pull through.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('38d9a43e-d605-461f-b7cc-d2f5735857cc'::uuid, 'Cable pulldown', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd8a6a67e-71db-4542-9dd7-a185a3e773af'::uuid, E'1. Sit at the cable pulldown machine with your feet flat on the floor and knees secured under the pads. Grasp the bar attached to the high pulley with an overhand grip, hands placed at shoulder-width, arms fully extended above you.\r\n2. Pull the bar down towards your upper chest, bringing your elbows down and back while keeping them close to your body.\r\n3. Slowly extend your arms back to the starting position with control.\r\n4. Repeat for the desired number of repetitions.', E'1. Exhale as you pull the bar down and inhale as you extend it back.\r\n2. Keep your elbows close to your body and avoid flaring them out.\r\n3. Use a lighter weight to ensure proper form and gradually increase the resistance as you get stronger.', '{"image_male_start":"images/Back/Cable Pulldown.jpg","image_male_end":"images/Back/Cable Pulldown1.jpg","video_url":"videos/Back/Cable Pulldown.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d9b6a46d-10ca-45ef-a60c-e7dca3203f10'::uuid, 'Cable pulldown (pro lat bar)', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd8a6a67e-71db-4542-9dd7-a185a3e773af'::uuid, E'1. Sit at the cable pulldown machine with your feet flat on the floor and knees secured under the pads. Grasp the Pro Lat Bar attached to the high pulley with an overhand grip, hands placed wider than shoulder-width, arms fully extended above you.\r\n2. Pull the bar down towards your upper chest, bringing your elbows down and back while keeping them close to your body.\r\n3. Slowly extend your arms back to the starting position with control.\r\n4. Repeat for the desired number of repetitions.', E'1. Exhale as you pull the bar down and inhale as you extend it back.\r\n2. Keep your elbows close to your body and avoid flaring them out.\r\n3. Use a lighter weight to ensure proper form and gradually increase the resistance as you get stronger.', '{"video_url":"videos/Back/Cable Pulldown (pro lat bar).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f7b45a2f-3861-4570-b8d6-16ade9eeb765'::uuid, 'Cable pushdown', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Stand facing the cable machine with a straight bar attached to the high pulley. Grasp the bar with both hands, palms facing down, and place your hands shoulder-width apart.\r\n2. Stand with your feet shoulder-width apart and lean slightly forward, keeping your back straight and elbows close to your body. Your forearms should be parallel to the floor.\r\n3. Push the bar down towards your thighs by straightening your elbows, keeping your upper arms stationary.\r\n4. Slowly return to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you push the bar down and inhale as you return to the starting position.\r\n2. Stand with a slight bend in your knees for better stability.\r\n3. Focus on squeezing your triceps at the bottom of the movement.', '{"image_male_start":"images/Triceps/Cable Pushdown.jpeg","video_url":"videos/Triceps/Cable Pushdown.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('754535eb-07e8-40ff-b189-afbcd145cc21'::uuid, 'Cable pushdown (straight arm)', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Stand facing the cable machine with a straight bar attached to the high pulley. Grasp the bar with both hands, palms facing down, and place your hands shoulder-width apart.\r\n2. Stand with your feet shoulder-width apart, keeping your back straight and a slight bend in your knees.\r\n3. Push the bar down towards your thighs, keeping your arms slightly bent throughout the movement.\r\n4. Slowly return to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you push the bar down and inhale as you return to the starting position.\r\n2. Stand with a slight bend in your knees for better stability.\r\n3. Focus on engaging your lats during the movement.', '{"image_male_start":"images/Back/Cable Pushdown (straight arm).jpg","image_male_end":"images/Back/Cable Pushdown (straight arm)1.jpg","video_url":"videos/Back/Cable Pushdown (straight arm).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2c0b914b-f863-405f-833f-ec460301346b'::uuid, 'Cable rear delt fly', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand in the center of a cable machine with the pulleys set at chest height. Cross the cable ends and hold the left cable end with your right hand and the right cable end with your left hand, arms extended in front of you.\r\n2. Stand with your feet shoulder-width apart, keeping your back straight and a slight bend in your knees.\r\n3. Pull the handles apart and out to the sides, keeping your arms straight but with a slight bend in the elbows, until your arms are extended out to your sides.\r\n4. Slowly return to the starting position with control, bringing the handles back in front of you. Repeat for the desired number of repetitions.', E'1. Exhale as you pull the handles apart and inhale as you return to the starting position.\r\n2. Use a lighter weight to ensure proper form and gradually increase the resistance as you get stronger.\r\n3. Focus on engaging your rear deltoids and upper back during the movement.', '{"image_male_start":"images/Shoulders/cable rear delt fly .jpg","video_url":"videos/Shoulders/cable rear delt fly .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('139e5a0f-b057-483f-ad32-3a802a4541c9'::uuid, 'Cable rear drive', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand straight with your feet shoulder-width apart, facing the cable machine. Set the pulley at shoulder height and grasp the handle of the cable with your right hand, palm facing down. Set your arm parallel to the floor in front of you and bent at 90 degrees.\r\n2. Drive your elbow sideways while slowly straightening your arm, pulling the cable across your chest.\r\n3. Slowly bring your arm back to the starting position with control. \r\n4. Repeat for the desired number of repetitions, then switch to your left hand.', E'1. Focus on squeezing your upper back muscles at the top of the movement.\r\n2. Maintain a neutral wrist position to prevent strain.\r\n3. Stand with a slight bend in your knees for better stability.', '{"image_male_start":"images/Triceps/Cable Rear Drive.jpeg","video_url":"videos/Triceps/Cable Rear Drive.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ae46ac11-2b5d-49d9-9c61-e89d02981d64'::uuid, 'Cable rear drive bent arm', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand straight with your feet shoulder-width apart, facing the cable machine. Set the pulley at shoulder height and grasp the handle of the cable with your right hand, palm facing down. Set your arm parallel to the floor in front of you and bent at 90 degrees.\r\n2. Drive your elbow sideways, keeping your arm bent at 90 degrees, pulling the cable across your chest.\r\n3. Slowly bring your arm back to the starting position with control. \r\n4. Repeat for the desired number of repetitions, then switch to your left hand.', E'1. Focus on squeezing your upper back muscles at the top of the movement.\r\n2. Maintain a neutral wrist position to prevent strain.\r\n3. Stand with a slight bend in your knees for better stability.', '{"image_male_start":"images/Shoulders/Cable rear drive bent arm.jpg","image_male_end":"images/Shoulders/Cable rear drive bent arm1.jpg","video_url":"videos/Shoulders/Cable rear drive bent arm.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a8b8f2a4-03b3-497d-aea5-725398db2fef'::uuid, 'Cable rear pulldown', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd8a6a67e-71db-4542-9dd7-a185a3e773af'::uuid, E'1. Sit at the cable pulldown machine with your feet flat on the floor and knees secured under the pads. Attach a straight bar to the high pulley and grasp the bar with both hands, palms facing forward, hands wider than shoulder-width apart.\r\n2. Lean your head slightly forward, keeping your back straight and core tight. Extend your arms fully above your head.\r\n3. Pull the bar down behind your neck by bending your elbows and bringing them down to the sides.\r\n4. Slowly extend your arms up to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep your back straight and avoid using momentum.\r\n2. Focus on squeezing your shoulder blades together at the bottom of the movement.\r\n3. Exhale as you pull the bar down and inhale as you extend it back up.', '{"image_male_start":"images/Back/Cable rear Pulldown.jpg","image_male_end":"images/Back/Cable rear Pulldown1.jpg","video_url":"videos/Back/Cable rear Pulldown.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b552e2b8-ba54-4da3-8912-28db265eac7e'::uuid, 'Cable reverse curl', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Stand facing the cable machine with a straight bar attached to the low pulley. Grasp the bar with both hands using an overhand grip (palms facing down), hands shoulder-width apart.\r\n2. Stand with your feet shoulder-width apart, keeping your back straight and arms fully extended down in front of you.\r\n3. Curl the bar upwards towards your shoulders by bending your elbows, keeping your upper arms stationary and close to your body.\r\n4. Slowly lower the bar back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you curl the bar up and inhale as you lower it back down.\r\n2. Use a lighter weight to ensure proper form and gradually increase the resistance as you get stronger.\r\n3. Focus on squeezing your biceps at the top of the movement.', '{"image_male_start":"images/Biceps/cable reverse curl.jpeg","video_url":"videos/Biceps/cable reverse curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ac9773f5-ba84-413a-81b7-c438bb49cd6c'::uuid, 'Cable reverse fly', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand in the center of a cable crossover machine with the pulleys set at shoulder height. Cross the cable ends and hold the left cable end with your right hand and the right cable end with your left hand, arms extended in front of you.\r\n2. Stand with your feet shoulder-width apart, keeping your back straight and a slight bend in your knees.\r\n3. Pull the handles apart and out to the sides, keeping your arms straight but with a slight bend in the elbows, until your arms are extended out to your sides.\r\n4. Slowly return to the starting position with control, bringing the handles back in front of you. Repeat for the desired number of repetitions.', E'1. Exhale as you pull the handles apart and inhale as you return to the starting position.\r\n2. Use a lighter weight to ensure proper form and gradually increase the resistance as you get stronger.\r\n3. Focus on engaging your rear deltoids and upper back during the movement.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('17ae5eec-3406-49a9-8d73-49aebc489ee6'::uuid, 'Cable reverse grip pushdown', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Stand facing the cable machine with a straight bar attached to the high pulley. Grasp the bar with both hands using an underhand grip (palms facing up), hands shoulder-width apart.\r\n2. Stand with your feet shoulder-width apart, keeping your back straight and elbows close to your body. Your forearms should be parallel to the floor.\r\n3. Push the bar down towards your thighs by straightening your elbows, keeping your upper arms stationary.\r\n4. Slowly return to the starting position with control, allowing your forearms to become parallel to the floor again. Repeat for the desired number of repetitions.', E'1. Keep your elbows close to your body and avoid moving your upper arms.\r\n2. Focus on squeezing your triceps at the bottom of the movement.\r\n3. Exhale as you push the bar down and inhale as you return to the starting position.', '{"image_male_start":"images/Triceps/cable reverse grip pushdown.jpeg","video_url":"videos/Triceps/cable reverse grip pushdown.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ce146260-21bd-489a-8e6c-125bc777901c'::uuid, 'Cable reverse grip straight back seated high row', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd8a6a67e-71db-4542-9dd7-a185a3e773af'::uuid, E'1. Sit at the pulldown machine with your feet flat on the floor and knees secured under the pads. Attach a straight bar to the high pulley and grasp the bar with both hands using an underhand grip (palms facing back), hands shoulder-width apart.\r\n2. Sit upright with your back straight and arms fully extended above your head.\r\n3. Pull the bar down towards your upper chest by bending your elbows and bringing them down and back, keeping your upper arms close to your body.\r\n4. Slowly extend your arms back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep your back straight and avoid leaning back or using momentum.\r\n2. Focus on squeezing your shoulder blades together at the bottom of the movement.\r\n3. Exhale as you pull the bar down and inhale as you extend it back up.', '{"image_male_start":"images/Back/cable reverse grip straight back seated high row.jpg","image_male_end":"images/Back/cable reverse grip straight back seated high row1.jpg","video_url":"videos/Back/cable reverse grip straight back seated high row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3899ebde-ddd5-4dcb-bd4c-2f4830b1b1bd'::uuid, 'Cable reverse grip triceps push down straight bar on crossover', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Stand facing the cable machine with a straight bar attached to the high pulley. Grasp the bar with both hands using an underhand grip (palms facing up), hands shoulder-width apart.\r\n2. Stand with your feet shoulder-width apart, keeping your back straight and elbows close to your body. Your forearms should be parallel to the floor.\r\n3. Push the bar down towards your thighs by straightening your elbows, keeping your upper arms stationary.\r\n4. Slowly return to the starting position with control, allowing your forearms to become parallel to the floor again. Repeat for the desired number of repetitions.', E'1. Keep your elbows close to your body and avoid moving your upper arms.\r\n2. Focus on squeezing your triceps at the bottom of the movement.\r\n3. Exhale as you push the bar down and inhale as you return to the starting position.', '{"video_url":"videos/Triceps/Cable reverse grip triceps push down straight bar on crossover.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('450584a7-3e4d-47cd-9265-1b37203d56c9'::uuid, 'Cable reverse grip triceps pushdown (EZ bar)', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Stand facing the cable machine with a straight an EZ bar attached to the high pulley. Grasp the EZ bar with both hands using an underhand grip (palms facing up), hands shoulder-width apart.\r\n2. Stand with your feet shoulder-width apart, keeping your back straight and elbows close to your body. Your forearms should be parallel to the floor.\r\n3. Push the EZ bar down towards your thighs by straightening your elbows, keeping your upper arms stationary.\r\n4. Slowly return to the starting position with control, allowing your forearms to become parallel to the floor again. Repeat for the desired number of repetitions.', E'1. Keep your elbows close to your body and avoid moving your upper arms.\r\n2. Focus on squeezing your triceps at the bottom of the movement.\r\n3. Exhale as you push the bar down and inhale as you return to the starting position.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ee37bfa7-faec-4e60-910f-67edfb8085dc'::uuid, 'Cable reverse grip triceps pushdown back side POV', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Stand facing the cable machine with a straight bar attached to the high pulley. Grasp the bar with both hands using an underhand grip (palms facing up), hands shoulder-width apart.\r\n2. Stand with your feet shoulder-width apart, keeping your back straight and elbows close to your body. Your forearms should be parallel to the floor.\r\n3. Push the bar down towards your thighs by straightening your elbows, keeping your upper arms stationary.\r\n4. Slowly return to the starting position with control, allowing your forearms to become parallel to the floor again. Repeat for the desired number of repetitions.', E'1. Keep your elbows close to your body and avoid moving your upper arms.\r\n2. Focus on squeezing your triceps at the bottom of the movement.\r\n3. Exhale as you push the bar down and inhale as you return to the starting position.', '{"image_male_start":"images/Triceps/cable reverse grip triceps pushdown back side pov.jpeg","video_url":"videos/Triceps/cable reverse grip triceps pushdown back side pov.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a723151e-1c39-40d9-84a1-ea252942bc01'::uuid, 'Cable seated on floor row', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Sit on the floor facing a cable machine with your legs extended straight out in front of you. Attach a straight bar to the low pulley and grasp the bar with both hands shoulder-width apart, palms facing down.\r\n2. Sit upright with your back straight and arms fully extended towards the machine. Bend your knees slightly for comfort.\r\n3. Pull the handle towards your lower abdomen by bending your elbows and bringing them backwards, keeping your upper arms close to your body.\r\n4. Slowly extend your arms back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep your back straight and avoid using momentum.\r\n2. Focus on squeezing your shoulder blades together at the end of the movement.\r\n3. Exhale as you pull the bar towards your body and inhale as you extend it back.', '{"image_male_start":"images/Back/Cable Seated on Floor Row.jpg","image_male_end":"images/Back/Cable Seated on Floor Row1.jpg","video_url":"videos/Back/Cable Seated on Floor Row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b8921f71-f9bc-4788-a47a-02fa8adcce35'::uuid, 'Cable seated one arm alternate row', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Sit on the seated cable row machine with your feet flat on the footrests and knees slightly bent. Attach a single handle to the low pulley and grasp the handle with your right hand, arm fully extended towards the machine.\r\n2. Sit upright with your back straight, keeping your left hand on your left knee for support.\r\n3. Pull the handle towards your lower abdomen by bending your elbow and bringing it back, keeping your upper arm close to your body.\r\n4. Slowly extend your arm back to the starting position with control. Repeat for the desired number of repetitions, then switch to your left hand.', E'1. Keep your back straight and avoid using momentum.\r\n2. Focus on squeezing your shoulder blades together at the end of the movement.\r\n3. Exhale as you pull the handle towards your body and inhale as you extend it back.', '{"image_male_start":"images/Back/Cable Seated One Arm Alternate Row.jpg","image_male_end":"images/Back/Cable Seated One Arm Alternate Row1.jpg","video_url":"videos/Back/Cable Seated One Arm Alternate Row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9efd47cd-399e-4f3a-9d15-bb413fda5fb4'::uuid, 'Cable seated rear lateral raise', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on the edge of a bench in the middle of a cable machine with the pulleys set at the lowest position. Attach single handles to each pulley and grasp the left handle with your right hand and the right handle with your left hand, allowing the cables to cross under your thighs.\r\n2. Bend forward at the hips, keeping your back straight, so your chest is close to your knees.\r\n3. Raise both handles out to the sides until your arms are parallel to the floor, keeping a slight bend in your elbows.\r\n4. Slowly lower the handles back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you raise the handles and inhale as you lower them back down.\r\n2. Ensure your feet are firmly planted on the floor for stability.\r\n3. Focus on engaging your rear deltoids and upper back during the movement.', '{"image_male_start":"images/Shoulders/Cable Seated rear lateral raise.jpg","image_male_end":"images/Shoulders/Cable Seated rear lateral raise1.jpg","video_url":"videos/Shoulders/Cable Seated rear lateral raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f0e85344-a706-4ef4-b256-6eba5b6c81f5'::uuid, 'Cable seated row', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd8a6a67e-71db-4542-9dd7-a185a3e773af'::uuid, E'1. Sit on the seated pulldown machine with your feet flat on the floor. Attach a V-bar handle to the low pulley and grasp the handle with both hands, palms facing each other.\r\n2. Sit upright with your back straight and arms fully extended towards the machine.\r\n3. Pull the handle towards your lower abdomen by bending your elbows and bringing them backwards, keeping your upper arms close to your body.\r\n4. Slowly extend your arms back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you pull the handle towards your body and inhale as you extend it back.\r\n2. Avoid rounding your back; keep your chest lifted throughout the exercise.\r\n3. Focus on squeezing your shoulder blades together at the end of the movement.', '{"image_male_start":"images/Back/Cable seated row.jpg","image_male_end":"images/Back/Cable seated row1.jpg","video_url":"videos/Back/Cable seated row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('da7c5b3f-c956-4bcd-ba4f-cb80b0b09476'::uuid, 'Cable Seated Row With V Bar', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'b7ec08fd-b7eb-4a14-a54d-f3d91be90da6'::uuid, E'1. Sit on the seated cable machine with your feet flat on the floor. Attach a V handle to the pulley and grasp the handle with both hands, arms fully extended towards the machine.\r\n2. Lean slightly forward, keeping your back straight.\r\n3. Pull the handle towards your abdomen by bending your elbows and bringing it back while raising your torso to a seated position, keeping your arms close to your body.\r\n4. Extend your arms back to the starting position with control. Repeat for the desired repetitions', E'1. Exhale as you pull the handle towards your body and inhale as you extend it back.\r\n2. Avoid rounding your back; keep your chest lifted throughout the exercise.\r\n3. Focus on squeezing your shoulder blades together at the end of the movement.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9178a682-6b7f-4564-8b02-d1ccf986d72a'::uuid, 'Cable seated supine grip row', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd8a6a67e-71db-4542-9dd7-a185a3e773af'::uuid, E'1. Sit on the seated pulldown machine with your feet flat on the floor. Attach a straight bar to the middle pulley and grasp the bar with both hands using a supine grip (palms facing up), hands shoulder-width apart.\r\n2. Sit upright with your back straight and arms fully extended towards the machine.\r\n3. Pull the bar towards your lower abdomen by bending your elbows and bringing them back, keeping your upper arms close to your body.\r\n4. Slowly extend your arms back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you pull the bar towards your body and inhale as you extend it back.\r\n2. Avoid rounding your back; keep your chest lifted throughout the exercise.\r\n3. Focus on squeezing your shoulder blades together at the end of the movement.', '{"image_male_start":"images/Back/Cable Seated Supine grip Row.jpg","image_male_end":"images/Back/Cable Seated Supine grip Row1.jpg","video_url":"videos/Back/Cable Seated Supine grip Row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c6861e35-e2e9-4096-883f-fef9896ba83e'::uuid, 'Cable standing up straight crossovers', 'Resistance', 'strength', 'weight_reps', 'intermediate', '7c8ccea6-1ecd-4abd-a28f-2f05d0d539a5'::uuid, E'1. Stand in the center of a cable crossover machine with the pulleys set at the highest point. Grasp the handles with each hand, palms facing forward.\r\n2. Stand with your feet shoulder-width apart with one foot forward and the other back and knees slightly bent. Keep your back straight and arms extended out to your sides.\r\n3. Pull the handles down and forward until they meet in front of your hips. Keep a slight bend in your elbows.\r\n4. Slowly return your arms to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you pull the handles down and infront of your chest and inhale as you return them to the starting position.\r\n2. Use a lighter weight to ensure proper form and gradually increase the resistance as you get stronger.\r\n3. Focus on engaging your chest muscles during the movement.', '{"image_male_start":"images/Chest/Cable Standing Up Straight Crossovers.jpg","image_male_end":"images/Chest/Cable Standing Up Straight Crossovers1.jpg","video_url":"videos/Chest/Cable Standing Up Straight Crossovers.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ddde4317-0ec1-4eac-ac82-9d3fcc306ddc'::uuid, 'Cable straight arm pulldown', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd8a6a67e-71db-4542-9dd7-a185a3e773af'::uuid, E'1. Stand facing the cable machine with a straight bar attached to the high pulley. Grasp the bar with both hands, palms facing down, and place your hands shoulder-width apart.\r\n2. Stand with your feet shoulder-width apart, lean your torso slightly forward and keep your back straight and a slight bend in your knees. Extend your arms fully in front of you at shoulder height.\r\n3. Pull the bar down towards your thighs, keeping your arms straight throughout the movement.\r\n4. Slowly return the bar to the starting position with control, bringing it back to shoulder height. Repeat for the desired number of repetitions.', E'1. Keep your arms straight throughout the exercise to target the middle back muscles.\r\n2. Focus on engaging your lats and core during the movement.\r\n3. Exhale as you pull the bar down and inhale as you return it to the starting position.', '{"image_male_start":"images/Back/Cable Straight Arm Pulldown.jpg","image_male_end":"images/Back/Cable Straight Arm Pulldown1.jpg","video_url":"videos/Back/Cable Straight Arm Pulldown.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('df562f14-f7e2-42d6-93af-6c75be7c9f32'::uuid, 'Cable triceps overhead extension (ez bar)', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Attach an EZ bar to the high pulley of a cable machine. Stand with your back facing the machine, feet shoulder-width apart, and grasp the EZ bar with both hands, palms facing up.\r\n2. Step forward slightly to create tension in the cable and position your feet in a staggered stance for stability. Extend your arms straight up above your head, keeping your elbows close to your ears.\r\n3. Lower the EZ bar behind your head by bending your elbows, keeping your upper arms stationary.\r\n4. Extend your arms back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you extend your arms and inhale as you lower the EZ bar.\r\n2. Keep your elbows close to your ears and stationary throughout the exercise.\r\n3. Focus on squeezing your triceps at the top of the movement.', '{"image_male_start":"images/Triceps/cable triceps overhead extension (ez bar).jpeg","video_url":"videos/Triceps/cable triceps overhead extension (ez bar).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('97622330-4bc6-4c2a-ae05-4f370a0bb4ed'::uuid, 'Cable triceps push down elbow out (v bar)', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Stand facing the cable machine with your feet shoulder-width apart, keeping your back straight, knees slightly bent and lean slightly forward.\r\n2. Grasp the V-bar attached to the high pulley with both hands, palms facing each other, and place your hands shoulder-width apart. Bend your elbows at a 90-degree angle, with your elbows flared out to the sides.\r\n3. Push the V-bar down towards your thighs by straightening your elbows, keeping your upper arms close to your torso.\r\n4. Slowly return to the starting position with control. Repeat for the desired number of repetitions.', E'1. Use a lighter weight to ensure proper form and avoid injury of your elbow joints.\r\n2. Focus on squeezing your triceps at the bottom of the movement.\r\n3. Exhale as you push the V-bar down and inhale as you return to the starting position.', '{"image_male_start":"images/Triceps/cable triceps push down elbow out (v bar).jpeg","video_url":"videos/Triceps/cable triceps push down elbow out (v bar).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9762771e-957b-46c2-9f23-012bcd4688ac'::uuid, 'Cable triceps push down ez bar', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Stand facing the cable machine with your feet shoulder-width apart, keeping your back straight and knees slightly bent.\r\n2. Grasp the EZ bar attached to the high pulley with both hands, palms facing down, and place your hands shoulder-width apart. Bend your elbows at a 90-degree angle, keeping your elbows close to your body.\r\n3. Push the EZ bar down towards your thighs by straightening your elbows, keeping your upper arms stationary.\r\n4. Slowly return to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep your elbows close to your body and avoid moving your upper arms.\r\n2. Focus on squeezing your triceps at the bottom of the movement.\r\n3. Exhale as you push the EZ bar down and inhale as you return to the starting position.', '{"image_male_start":"images/Triceps/cable triceps push down ez bar.jpeg","video_url":"videos/Triceps/cable triceps push down ez bar  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('27d19da8-4973-465d-8b94-9c7220efb5a5'::uuid, 'Cable triceps push down ez bar close grip', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Stand facing the cable machine with your feet shoulder-width apart, keeping your back straight and knees slightly bent.\r\n2. Grasp the EZ bar attached to the high pulley with both hands, palms facing down, and place your hands closer than shoulder-width apart. Bend your elbows at a 90-degree angle, keeping your elbows close to your body.\r\n3. Push the EZ bar down towards your thighs by straightening your elbows, keeping your upper arms stationary.\r\n4. Slowly return to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep your elbows close to your body and avoid moving your upper arms.\r\n2. Focus on squeezing your triceps at the bottom of the movement.\r\n3. Exhale as you push the EZ bar down and inhale as you return to the starting position.', '{"image_male_start":"images/Triceps/cable triceps push down ez bar close grip.jpeg","video_url":"videos/Triceps/cable triceps push down ez bar close grip  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('31ac6f17-7778-4fd8-bab4-cc03cf9bb10e'::uuid, 'Cable triceps push down ez bar wide grip', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Stand facing the cable machine with your feet shoulder-width apart, keeping your back straight and knees slightly bent.\r\n2. Grasp the EZ bar attached to the high pulley with both hands, palms facing down, and place your hands wider than shoulder-width apart. Bend your elbows at a 90-degree angle, keeping your elbows close to your body.\r\n3. Push the EZ bar down towards your thighs by straightening your elbows, keeping your upper arms stationary.\r\n4. Slowly return to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep your elbows close to your body and avoid moving your upper arms.\r\n2. Focus on squeezing your triceps at the bottom of the movement.\r\n3. Exhale as you push the EZ bar down and inhale as you return to the starting position.', '{"image_male_start":"images/Triceps/cable triceps push down ez bar wide grip.jpeg","video_url":"videos/Triceps/cable triceps push down ez bar wide grip  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4cd49c21-6a5f-4552-9ce1-83ffa310d3a5'::uuid, 'Cable triceps push down straight bar', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Stand facing the cable machine with your feet shoulder-width apart, keeping your back straight and knees slightly bent.\r\n2. Grasp the straight bar attached to the high pulley with both hands, palms facing down, and place your hands shoulder-width apart. Bend your elbows at a 90-degree angle, keeping your elbows close to your body.\r\n3. Push the bar down towards your thighs by straightening your elbows, keeping your upper arms stationary.\r\n4. Slowly return to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep your elbows close to your body and avoid moving your upper arms.\r\n2. Focus on squeezing your triceps at the bottom of the movement.\r\n3. Exhale as you push the straight bar down and inhale as you return to the starting position.', '{"image_male_start":"images/Triceps/cable triceps push down straight bar.jpeg","video_url":"videos/Triceps/cable triceps push down straight bar  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3a86cdbe-8c70-429b-8c1c-b55597818523'::uuid, 'Cable triceps push down v bar', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Stand facing the cable machine with your feet shoulder-width apart, keeping your back straight and knees slightly bent.\r\n2. Grasp the v bar attached to the high pulley with both hands, palms facing down, and place your hands wider than shoulder-width apart. Bend your elbows at a 90-degree angle, keeping your elbows close to your body.\r\n3. Push the v bar down towards your thighs by straightening your elbows, keeping your upper arms stationary.\r\n4. Slowly return to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep your elbows close to your body and avoid moving your upper arms.\r\n2. Focus on squeezing your triceps at the bottom of the movement.\r\n3. Exhale as you push the v bar down and inhale as you return to the starting position.', '{"image_male_start":"images/Triceps/cable triceps push down v bar.jpeg","video_url":"videos/Triceps/cable triceps push down v bar  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0584bcba-8d6a-4e00-a797-347e3b0638be'::uuid, 'Cable twin handle parallel grip lat pulldown', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Sit upright on a bench positioned between two cable pulley machines with the pulleys set at a high position. Hold a handle in each hand with an overhand grip (palms facing forward), arms fully extended above you.\r\n2. Pull the handles down towards your shoulders by bending your elbows and bringing them downwards, keeping them close to your body.\r\n3. Slowly extend your arms back to the starting position with control.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep your back straight and avoid using momentum.\r\n2. Focus on squeezing your shoulder blades together at the bottom of the movement.\r\n3. Exhale as you pull the handles down and inhale as you extend them back up.', '{"image_male_start":"images/Back/Cable Twin Handle Parallel Grip Lat Pulldown.jpg","image_male_end":"images/Back/Cable Twin Handle Parallel Grip Lat Pulldown1.jpg","video_url":"videos/Back/Cable Twin Handle Parallel Grip Lat Pulldown.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('59d218c7-d47f-4da1-bf0d-bdfc2cfd2ae3'::uuid, 'Cable twist', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand sideways to the cable machine with your feet shoulder-width apart. Attach a handle to the pulley at shoulder height and grasp it with both hands, arms extended in front of you.\r\n2. Twist your torso away from the machine, pulling the handle across your body while keeping your arms straight.\r\n3. Slowly return to the starting position with control. \r\n4. Repeat for the desired number of repetitions, then switch sides.', E'1. Perform the movement slowly and with control to maximize muscle activation and reduce injury risk.\r\n2. Exhale as you twist away from the machine and inhale as you return to the starting position.\r\n3. Minimize hip twisting to focus on engaging your obliques and core during the twist.', '{"image_male_start":"images/Abdominals/Cable Twist.jpeg","video_url":"videos/Abdominals/Cable Twist.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d493bc32-c055-44e0-8857-17986afd1af7'::uuid, 'Cable twist (up-down)', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand sideways to the cable machine with your feet shoulder-width apart. Attach a handle to the high pulley and grasp it with both hands, arms extended diagonally along the cable.\r\n2. Twist your torso down and across your body, pulling the handle down towards your opposite hip while keeping your arms straight.\r\n3. Slowly return to the starting position with control. \r\n4. Repeat for the desired number of repetitions, then switch sides.', E'1. Perform the movement slowly and with control to maximize muscle activation and reduce injury risk.\r\n2. Exhale as you twist away from the machine and inhale as you return to the starting position.\r\n3. Minimize hip twisting to focus on engaging your obliques and core during the twist.', '{"image_male_start":"images/Abdominals/Cable twist (up-down).jpeg","video_url":"videos/Abdominals/Cable twist (up-down).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9290f6be-bb9c-4fef-aabb-898b8c346ab5'::uuid, 'Cable twisting overhead press', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Stand sideways to the cable machine with your feet slightly wider than shoulder-width apart, knees bent at almost 90 degrees and hips pushed back.\r\n2.  Grasp the handle, attached at hip height, with the hand closest to the machine, keeping it close to your shoulder. Place your other hand on your hip.\r\n3. Twist your torso away from the machine while pushing the handle sideways and straight across your torso, straightening your legs to a standing position as you press the handle.\r\n4. Slowly return to the starting semi-squat position with control, bringing the handle back to your shoulder. Repeat for the desired number of repetitions, then switch sides.', E'1. Use a lighter weight to ensure proper form and gradually increase the resistance as you get stronger.\r\n2. Perform the movement slowly and with control to maximize muscle activation and reduce injury risk.\r\n3. Exhale as you twist and press the handle across your torso, and inhale as you return to the starting position.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Cable twisting overhead press.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Cable twisting overhead press1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Cable twisting overhead press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c4bbc43e-8683-4edc-a976-557cd6ee4a13'::uuid, 'Cable twisting pull', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Stand facing the cable machine with the left foot forward and the right foot back, knees bent. Attach a handle to the low pulley and grasp it with the right hand, palm facing down. Lean forward so your upper body is almost parallel to the floor.\r\n2. Extend your arm fully towards the pulley, keeping your back straight and your core engaged.\r\n3. Pull the handle towards your torso, rotating your wrist as you pull until your palm faces the ceiling.\r\n4. Slowly extend your arm back to the starting position with control. Repeat for the desired number of repetitions, then switch sides.', E'1. Exhale as you pull the handle towards your torso and inhale as you extend it back.\r\n2. Keep your feet firmly planted on the floor for stability.\r\n3. Keep your core tight throughout the exercise to protect your lower back.', '{"image_male_start":"images/Back/Cable Twisting Pull.jpg","image_male_end":"images/Back/Cable Twisting Pull1.jpg","video_url":"videos/Back/Cable Twisting Pull.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('dce5c390-d861-4fe1-ab48-794e54e84f28'::uuid, 'Cable Underhand Pulldown Wide Grips', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Sit at the lat pulldown machine with your feet flat on the floor and knees secured under the pads. Attach a wide grip bar to the high pulley and grasp it with both hands using an underhand grip (palms facing back), hands wider than shoulder-width apart.\r\n2. Pull the bar down towards your upper chest by bending your elbows and bringing them down and back.\r\n3. Slowly extend your arms back to the starting position with control.\r\n4. Repeat for the desired number of repetitions.', E'1. Focus on squeezing your shoulder blades together at the bottom of the movement.\r\n2. Keep your elbows close to your body and avoid flaring them out.\r\n3. Exhale as you pull the bar down and inhale as you extend it back up.', '{"image_male_start":"images/Back/Cable Underhand Pulldown Wide Grips.jpg","image_male_end":"images/Back/Cable Underhand Pulldown Wide Grips1.jpg","video_url":"videos/Back/Cable Underhand Pulldown Wide Grips.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7c18b6e7-34d0-4339-8826-ea214c846dfe'::uuid, 'Cable Upper Chest Crossover', 'Resistance', 'strength', 'weight_reps', 'intermediate', '7c8ccea6-1ecd-4abd-a28f-2f05d0d539a5'::uuid, E'1. Stand in the center of a cable crossover machine with the pulleys set at the lowest point. Grasp the handles with each hand, palms facing forward.\r\n2. Stand with your feet shoulder-width apart and knees slightly bent. \r\n3. Pull the handles up and forward until they meet over your chest.\r\n4. Slowly return your arms to the starting position. Repeat for the desired repetitions.', E'1. Exhale as you pull the handles down and infront of your chest and inhale as you return them to the starting position.\r\n2. Use a lighter weight to ensure proper form and gradually increase the resistance as you get stronger.\r\n3. Focus on engaging your chest muscles during the movement.', '{"image_male_start":"images/Chest/Cable Upper Chest Crossover.jpg","image_male_end":"images/Chest/Cable Upper Chest Crossover1.jpg","video_url":"videos/Chest/Cable Upper Chest Crossover.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d245e9d3-38cf-4613-9caf-54f81fffe239'::uuid, 'Cable upright row with EZ bar', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, facing the cable machine with an EZ bar attached to the low pulley. Grasp the EZ bar with both hands using an overhand grip (palms facing down), hands shoulder-width apart.\r\n2. Pull the EZ bar upwards towards your chin by bending your elbows and raising your upper arms, leading with your elbows, keeping the bar close to your body.\r\n3. Slowly lower the bar back to the starting position with control. \r\n4. Repeat for the desired number of repetitions.', E'1. Keep your back straight and avoid using momentum.\r\n2. Keep your elbows higher than your wrists throughout the movement.\r\n3. Exhale as you pull the EZ bar up and inhale as you lower it back down.', '{"image_male_start":"images/Shoulders/cable upright row with EZ bar .jpg","video_url":"videos/Shoulders/cable upright row with EZ bar .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('cf67a0ab-25d5-4e9e-9b71-fe7c6b5a2715'::uuid, 'Cable upright row with straight bar', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, facing the cable machine with a straight bar attached to the low pulley. Grasp the bar with both hands using an overhand grip (palms facing down), hands shoulder-width apart.\r\n2. Pull the bar upwards towards your chin by bending your elbows and raising your upper arms, leading with your elbows, keeping the bar close to your body.\r\n3. Slowly lower the bar back to the starting position with control. \r\n4. Repeat for the desired number of repetitions.', E'1. Keep your back straight and avoid using momentum.\r\n2. Keep your elbows higher than your wrists throughout the movement.\r\n3. Exhale as you pull the straight bar up and inhale as you lower it back down.', '{"image_male_start":"images/Shoulders/cable upright row with straight bar .jpg","video_url":"videos/Shoulders/cable upright row with straight bar .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7e2b8d5e-0808-420a-848b-5e40ca84fefd'::uuid, 'Cable wrist curl', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Sit on a bench facing the cable machine with a straight bar attached to the low pulley. Grasp the bar with both hands using an underhand grip (palms facing up), hands shoulder-width apart.\r\n2. Rest your forearms on your thighs with your wrists just beyond your knees, allowing the bar to hang down.\r\n3. Curl the bar upwards by flexing your wrists, bringing the bar towards your forearms.\r\n4. Slowly lower the bar back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep your forearms stationary on your thighs throughout the exercise.\r\n2. Focus on squeezing your forearms at the top of the movement.\r\n3. Exhale as you curl the bar up and inhale as you lower it back down.', '{"image_male_start":"images/Forearms/Cable Wrist Curl.jpeg","video_url":"videos/Forearms/Cable Wrist Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1593617a-79ad-4747-b93a-ddfdf7a6e67d'::uuid, 'Cable Y raise', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand facing the cable machine with the pulleys set at the lowest position. Grasp a handle in each hand, holding the left handle with your right hand and the right handle with your left hand, so the cables cross in front of you.\r\n2. Take a step back and stand with your feet shoulder-width apart, keeping your back straight and arms extended down in front of you.\r\n3. Raise the handles up and out to form a "Y" shape, keeping your arms straight but with a slight bend in the elbows. Lift until your arms are overhead.\r\n4. Slowly lower the handles back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep your back straight and avoid using momentum.\r\n2. Use a lighter weight to ensure proper form and gradually increase the resistance as you get stronger.\r\n3. Exhale as you raise the handles and inhale as you lower them back down.', '{"image_male_start":"images/Shoulders/Cable Y raise.jpg","image_male_end":"images/Shoulders/Cable Y raise1.jpg","video_url":"videos/Shoulders/Cable Y raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e6fbd64b-ec1a-4a48-bf50-e5654ee1d559'::uuid, 'Calf push stretch with hands against wall', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Stand facing a wall with your feet shoulder-width apart. Place your hands on the wall at shoulder height and shoulder-width apart.\r\n2. Step your right foot back and keep on your toes, keeping your leg straight and bring your left leg close to the wall, touching it with your forefoot. \r\n3. Press your back heel flat to the floor, pushing with your left forefoot against the wall to deepen the stretch in your calf.\r\n4. Hold the stretch for 20-30 seconds, then switch legs and repeat.', E'1. Maintain a straight back and avoid arching or rounding your spine.\r\n2. Use a lighter push against the wall if you are new to stretching, gradually increasing the pressure as you become more flexible.\r\n3. Breathe deeply and steadily throughout the stretch to help relax your muscles.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f19b79e7-a25e-4d27-9835-0b0b5a0e114f'::uuid, 'Calf raise clap', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your arms extended out to the sides at shoulder level.\r\n2. Lift your heels off the floor as high as possible while simultaneously bringing your arms forward to clap, keeping them straight.\r\n3. Lower your heels back to the floor and return your arms to the starting position.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Keep your head up and eyes forward to maintain proper alignment and balance.\r\n2. Squeeze your calf muscles fully at the top of the movement for maximum benefit.\r\n3. Focus on keeping your arms straight and level with your shoulders throughout the exercise to maintain proper form.', '{"image_male_start":"images/Legs/Calf Raise Clap.jpg","image_male_end":"images/Legs/Calf Raise Clap1.jpg","video_url":"videos/Legs/Calf Raise Clap.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5ebe1ae8-b56e-4a22-8e19-95817dcd3192'::uuid, 'Calf raise from deficit with chair supported', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand on the edge of a raised platform or step, with your heels hanging off the edge, and hold onto a chair for support.\r\n2. Position your feet hip-width apart, ensuring your toes are firmly on the platform.\r\n3. Slowly raise your heels as high as possible, engaging your calf muscles and lifting your body.\r\n4. Lower your heels back down past the edge of the platform to feel a stretch in your calves. Repeat the movement for the desired number of repetitions.', E'1. Use the chair for balance but avoid leaning on it heavily to ensure your legs are doing the work.\r\n2. Perform the movement slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Ensure your heels drop below the platform to achieve a full range of motion and stretch.', '{"image_male_start":"images/Legs/Calf Raise from Deficit with Chair Supported.jpg","image_male_end":"images/Legs/Calf Raise from Deficit with Chair Supported1.jpg","video_url":"videos/Legs/Calf Raise from Deficit with Chair Supported.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a025c541-03c3-4ed9-a36b-5fa5c228ec3b'::uuid, 'Calf raise leg press machine', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on the leg press machine and position your feet shoulder-width apart on the higher portion of the footplate with your toes pointing up.\r\n2. Press the footplate by extending your legs and keeping a slight bend in your knees.\r\n3. Push through your forefeet to raise the footplate as much as possible, squeezing your calf muscles.\r\n4. Slowly lower your forefeet down to the starting position. Repeat for the desired repetitions.', E'1. Keep your legs slightly bent throughout the exercise to avoid placing stress on your knees.\r\n2. Focus on a full range of motion, pushing your forefeet as much as possible for deep muscle activation.\r\n3. Exhale as you raise your heels and inhale as you lower them back down.', '{"image_male_start":"images/Legs/Calf raise leg press machine.jpg","image_male_end":"images/Legs/Calf raise leg press machine1.jpg","image_female_start":"images/Legs/Calf raise leg press machine_Female.jpg","image_female_end":"images/Legs/Calf raise leg press machine_Female1.jpg","video_url":"videos/Legs/Calf raise leg press machine.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1367b9f1-1da8-4fc6-9f00-195da213ab37'::uuid, 'Calf raise on hack squat machine', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand on the hack squat machine with your shoulders under the pads and your feet hips-width apart on the foot platform, with your toes pointing forward and your heels hanging off the edge.\r\n2. Extend your legs to release the safety handles, keeping a slight bend in your knees.\r\n3. Push through your forefeet to raise your heels as high as possible, squeezing your calf muscles at the top of the movement.\r\n4. Slowly lower your heels back down to the starting position. Repeat for the desired number of repetitions.', E'1. Keep your legs slightly bent throughout the exercise to avoid placing stress on your knees.\r\n2. Focus on a full range of motion, lowering your heels as much as possible for a deep muscle activation.\r\n3. Exhale as you raise your heels and inhale as you lower them back down.', '{"image_male_start":"images/Legs/Calf raise on hack squat machine.jpg","image_male_end":"images/Legs/Calf raise on hack squat machine1.jpg","image_female_start":"images/Legs/Calf raise on hack squat machine_Female.jpg","image_female_end":"images/Legs/Calf raise on hack squat machine_Female1.jpg","video_url":"videos/Legs/Calf raise on hack squat machine.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('45b0d361-f1e1-4693-baf2-556a9df88cbb'::uuid, 'Calf raise with wall support', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand facing a wall with your feet hip-width apart. Place your hands on the wall at shoulder height for support.\r\n2. Position your feet flat on the floor, ensuring they are parallel to each other.\r\n3. Slowly raise your heels as high as possible, lifting your body and engaging your calf muscles.\r\n4. Lower your heels back to the floor in a controlled manner. Repeat the movement for the desired number of repetitions.', E'1. Focus on lifting your heels fully and pausing briefly at the top of the movement to maximize muscle activation.\r\n2. Use the wall for balance but ensure your legs are doing the work.\r\n3. Keep your knees slightly bent to reduce strain on your joints.', '{"image_male_start":"images/Legs/Calf Raise with Wall Support.jpg","image_male_end":"images/Legs/Calf Raise with Wall Support1.jpg","video_url":"videos/Legs/Calf Raise with Wall Support.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('df2cf3eb-3e79-4e99-a20a-ac2ba3ef4b96'::uuid, 'Calf stretch with hands against wall', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Stand facing a wall with your feet shoulder-width apart. Place your hands on the wall at shoulder height and shoulder-width apart.\r\n2. Step one foot back, keeping your back leg straight and your front leg slightly bent. Press your back heel into the floor.\r\n3. Lean forward slightly, pushing against the wall to deepen the stretch in your calf.\r\n4. Hold the stretch for 20-30 seconds, then switch legs and repeat.', E'1. Keep your back leg straight and your heel pressed into the floor to maximize the stretch.\r\n2. Stretch both legs equally to maintain balanced flexibility.\r\n3. Breathe deeply and steadily throughout the stretch to help relax your muscles.', '{"image_male_start":"images/Stretching - Mobility/Calf Stretch With Hands Against Wall.jpg","image_male_end":"images/Stretching - Mobility/Calf Stretch With Hands Against Wall1.jpg","video_url":"videos/Stretching - Mobility/Calf Stretch With Hands Against Wall.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('91925a50-6abc-43cb-ac3c-9f19d95fcfe7'::uuid, 'Calf stretch with rope', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Lie on the floor with your legs extended straight on the floor. Pass a rope with handles under your right forefoot, holding the handles with both hands.\r\n2. Keep your back flat against the floor and gently pull the rope towards you, flexing your foot and bringing your toes towards your shin.\r\n3. Straighten your leg fully to deepen the stretch in your calf muscle.\r\n4. Hold the stretch for 20-30 seconds, then release the rope and switch to the other foot, repeating the stretch.', E'1. Breathe deeply and steadily throughout the stretch to help relax your muscles.\r\n2. Use a moderate amount of tension on the rope to ensure a good stretch without causing discomfort or pain.\r\n3. Focus on feeling the stretch in your calf muscle, not your lower back or hamstrings.', '{"image_male_start":"images/Stretching - Mobility/Calf Stretch with Rope.jpg","image_male_end":"images/Stretching - Mobility/Calf Stretch with Rope1.jpg","video_url":"videos/Stretching - Mobility/Calf Stretch with Rope.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('97b748d8-dbc6-463a-971f-ad011c562405'::uuid, 'Calves stretch on stairs', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Stand on a step or stair with one foot on a higher step and the other foot on a lower step, ensuring the lower foot''s heel is hanging off the edge.\r\n2. Hold onto the railing or wall for support to maintain balance.\r\n3. Slowly lower the heel of the lower foot below the level of the step until you feel a stretch in your calf muscle.\r\n4. Hold the stretch for the desired duration, then slowly raise your heel back to the starting position. Repeat as needed for both legs.', E'Maintain an upright posture and engage your core to ensure balance and stability.\r\n1. Perform the movement slowly and with control to avoid straining your calf muscles.\r\n2. Use the railing or wall for support but ensure your legs are performing the stretch.\r\n3. Perform this stretch after a workout or when your muscles are warm to maximize flexibility and prevent injury.', '{"image_male_start":"images/Stretching - Mobility/Calves stretch on stairs.jpg","image_male_end":"images/Stretching - Mobility/Calves stretch on stairs1.jpg","video_url":"videos/Stretching - Mobility/Calves stretch on stairs.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('79737e80-9371-49d4-a202-583bd5581f44'::uuid, 'Captains chair leg raise', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand on the platform of the captain''s chair and place your forearms on the arm pads, gripping the handles for stability. Allow your legs to hang straight down.\r\n2. Engage your core and keep your back pressed against the back pad.\r\n3. Raise your legs, knees first, up in front of you until your thighs are parallel to the floor and your feet are slightly forward.\r\n4. Slowly lower your knees back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you raise your knees and inhale as you lower them back down.\r\n2. Avoid using momentum; the movement should be controlled and deliberate.\r\n3. Focus on engaging your core muscles throughout the movement.', '{"image_male_start":"images/Abdominals/Captains chair leg raise.jpeg","video_url":"videos/Abdominals/Captains chair leg raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('59089bda-4bc7-4ef6-b080-4bd925633841'::uuid, 'Captains chair straight leg raise', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand on the platform of the captain''s chair and place your forearms on the arm pads, gripping the handles for stability. Allow your legs to hang straight down.\r\n2. Engage your core and keep your back pressed against the back pad.\r\n3. Raise your legs straight up in front of you until they are parallel to the floor, keeping them as straight as possible.\r\n4. Slowly lower your legs back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep your back pressed against the back pad to prevent swinging and maintain proper form.\r\n2. Avoid using momentum; the movement should be controlled and deliberate.\r\n3. Exhale as you raise your legs and inhale as you lower them back down.', '{"image_male_start":"images/Abdominals/Captains Chair Straight Leg Raise.jpeg","video_url":"videos/Abdominals/Captains Chair Straight Leg Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c9cfb137-a211-478e-a74d-edea99c70161'::uuid, 'Cardio lunge', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a lunge position with your right leg forward and left leg back, ensuring your right knee is aligned over your ankle and your left knee is just above the floor. Bend both arms at your sides.\r\n2. Explosively push off your left foot, bringing it forward in a small step while pushing  your right leg slightly backwards.\r\n3. Immediately return your left foot back to the starting lunge position.\r\n4. Continue the explosive movement, maintaining a steady, rhythmic pace. Repeat for the desired number of repetitions or duration, then switch legs.', E'1. Ensure your front knee stays aligned with your toes to avoid putting unnecessary strain on your knee.\r\n2. Perform the movement with a controlled pace to maximize cardiovascular benefits and prevent injury.\r\n3. Use your arms to help balance and stabilize your movements.\r\n4. Focus on the explosive movement of the back leg to engage your glutes and hamstrings.\r\n5. Breathe steadily throughout the exercise, inhaling as you bring your leg forward and exhaling as you return to the lunge position.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Cardio Lunge.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Cardio Lunge1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Cardio Lunge.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d303ddab-eabf-4c98-9b02-1963f03694d4'::uuid, 'Cat stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Begin on your hands and knees in a tabletop position, with your wrists aligned under your shoulders and your knees aligned under your hips.\r\n2. Inhale deeply, then slowly arch your back upwards towards the ceiling, tucking your chin towards your chest and drawing your navel in towards your spine.\r\n3. Hold the arched position for a few seconds, feeling the stretch along your spine and back muscles.\r\n4. Exhale and slowly return to the starting tabletop position. Repeat the movement for the desired number of repetitions.', E'1. Focus on your breath, inhaling deeply as you arch your back and exhaling as you return to the starting position.\r\n2. Ensure your wrists and knees remain aligned throughout the exercise to maintain proper form and avoid strain.\r\n3. Relax your neck and avoid straining it as you tuck your chin towards your chest.\r\n4. Perform this stretch as part of a cool-down routine or whenever you need to relieve tension in your back.', '{"image_male_start":"images/Yoga/Cat Stretch.jpg","image_male_end":"images/Yoga/Cat Stretch1.jpg","video_url":"videos/Yoga/Cat Stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ba645b11-e98f-42c5-936d-c3f02514cabe'::uuid, 'Ceiling look stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Begin in a tabletop position on all fours, with your wrists aligned under your shoulders and your knees aligned under your hips.\r\n2. Slowly lift your torso upwards, arching your back gently and leaning backward.\r\n3. Allow your hands to slide down to your legs, supporting your upper body as you look up towards the ceiling.\r\n4. Hold this position for the desired duration and slowly return to the starting tabletop position. Repeat the movement for the desired number of repetitions.', E'1. Breathe deeply and evenly, inhaling as you lift your torso and exhaling as you return to the starting position.\r\n2. Avoid forcing the stretch; only lean back as far as is comfortable without causing pain.\r\n3. Use a mat or cushion under your knees for added comfort and support.\r\n4. Perform this stretch to enhance flexibility in your spine and relieve tension in your chest and neck.', '{"image_male_start":"images/Stretching - Mobility/Ceiling Look Stretch.jpg","image_male_end":"images/Stretching - Mobility/Ceiling Look Stretch1.jpg","video_url":"videos/Stretching - Mobility/Ceiling Look Stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3e4518e5-0cfd-4579-a609-0ca7fb6e9899'::uuid, 'Celebratory hip thrust', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by standing with your feet shoulder-width apart and your arms extended straight up in the air.\r\n2. Simultaneously bend your elbows and thrust your arms downwards to your hips while thrusting your hips forward.\r\n3. Return to the initial position with your arms extended overhead and your hips back in the starting position.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Perform the movement with a controlled pace, focusing on the coordinated motion of your arms and hips.\r\n2. Use the downward thrust of your arms to help generate momentum for the hip thrust.\r\n3. Keep your feet firmly planted on the floor to maintain stability.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Celebratory Hip Thrust.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Celebratory Hip Thrust1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Celebratory Hip Thrust.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a77c2293-1520-4c95-83e0-37baa8bf85f8'::uuid, 'Chair back lunge left Resistance band', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Attach one end of a resistance band to a sturdy chair or similar support and the other end to your left ankle. Stand facing the chair with your right foot firmly planted on the floor.\r\n2. Step back with your left foot, keeping your right foot in place, and lower your body into a lunge position by bending both knees, ensuring your right knee is directly above your right ankle and your left knee is hovering just above the floor.\r\n3. Push through your right heel to return to the starting position.\r\n4. Repeat for the desired number of repetitions, then switch legs.', E'1. Use a lighter resistance band if needed to ensure proper form and gradually increase the resistance as you get stronger.\r\n2. Focus on keeping your front knee aligned over your ankle to avoid putting excess strain on your knee joint.\r\n3. Maintain balance by keeping your hands steady and holding the chair.', '{"image_male_start":"images/Legs/chair back lunge left resistance band  .jpg","video_url":"videos/Legs/chair back lunge left resistance band  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('bc581f82-7513-4a69-9e5a-4edd666dd609'::uuid, 'chair back lunge right Resistance band', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Attach one end of a resistance band to a sturdy chair or similar support and the other end to your right ankle. Stand facing the chair with your left foot firmly planted on the floor.\r\n2. Step back with your right foot, keeping your left foot in place, and lower your body into a lunge position by bending both knees, ensuring your left knee is directly above your left ankle and your right knee is hovering just above the floor.\r\n3. Push through your left heel to return to the starting position.\r\n4. Repeat for the desired number of repetitions, then switch legs.', E'1. Use a lighter resistance band if needed to ensure proper form and gradually increase the resistance as you get stronger.\r\n2. Focus on keeping your front knee aligned over your ankle to avoid putting excess strain on your knee joint.\r\n3. Maintain balance by keeping your hands steady and holding the chair.', '{"image_male_start":"images/Legs/chair back lunge right resistance band  .jpg","video_url":"videos/Legs/chair back lunge right resistance band  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c8675736-d06c-4f55-96df-7f712b00f16a'::uuid, 'Chair Bulgarian split squats bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand a few feet in front of a chair, facing away from it. Place your one foot on the chair behind you, with the top of your foot resting on the seat.\r\n2. Position your other foot firmly on the floor, a comfortable distance in front of the chair.\r\n3. Lower your body by bending your back knee and hip, keeping your torso upright, until your thigh is parallel to the floor and your knee is close to the floor.\r\n4. Push through your floored heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs.', E'1. Keep your front knee aligned with your toes to avoid putting unnecessary strain on your knee.\r\n2. Focus on driving through the heel of your front foot to engage your glutes and quadriceps effectively.\r\n3. Perform the movement slowly and with control to maximize muscle activation and prevent injury.\r\n4. Ensure your back foot remains stable on the chair to maintain proper alignment.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5edaab67-7d08-40b2-aab1-b6da77231fc0'::uuid, 'Chair Bulgarian Split Squats bodyweight left', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand a few feet in front of a chair, facing away from it. Place your left foot on the chair behind you, with the top of your foot resting on the seat.\r\n2. Position your right foot firmly on the floor, a comfortable distance in front of the chair.\r\n3. Lower your body by bending your right knee and hip, keeping your torso upright, until your right thigh is parallel to the floor and your left knee is close to the floor.\r\n4. Push through your right heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs.', E'1. Keep your front knee aligned with your toes to avoid putting unnecessary strain on your knee.\r\n2. Focus on driving through the heel of your front foot to engage your glutes and quadriceps effectively.\r\n3. Perform the movement slowly and with control to maximize muscle activation and prevent injury.\r\n4. Ensure your back foot remains stable on the chair to maintain proper alignment.', '{"image_male_start":"images/Legs/Chair Bulgarian Split Squats bodyweight left.jpg","image_male_end":"images/Legs/Chair Bulgarian Split Squats bodyweight left1.jpg","video_url":"videos/Legs/Chair Bulgarian Split Squats bodyweight left.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e1c03b66-afba-4955-973b-4acfd11888d4'::uuid, 'chair Bulgarian Split Squats bodyweight right', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand a few feet in front of a chair, facing away from it. Place your right foot on the chair behind you, with the top of your foot resting on the seat.\r\n2. Position your left foot firmly on the floor, a comfortable distance in front of the chair.\r\n3. Lower your body by bending your left knee and hip, keeping your torso upright, until your left thigh is parallel to the floor and your right knee is close to the floor.\r\n4. Push through your left heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs.', E'1. Keep your front knee aligned with your toes to avoid putting unnecessary strain on your knee.\r\n2. Focus on driving through the heel of your front foot to engage your glutes and quadriceps effectively.\r\n3. Perform the movement slowly and with control to maximize muscle activation and prevent injury.\r\n4. Ensure your back foot remains stable on the chair to maintain proper alignment.', '{"image_male_start":"images/Legs/chair Bulgarian Split Squats bodyweight right.jpg","image_male_end":"images/Legs/chair Bulgarian Split Squats bodyweight right1.jpg","video_url":"videos/Legs/chair Bulgarian Split Squats bodyweight right.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5e5a4bb2-43f5-463d-80e9-e4c624a5124a'::uuid, 'Chair elevated single leg glute bridge', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '353a86d0-9f31-40d3-bfba-969ae615da15'::uuid, E'1. Lie on your back with your left heel placed on the edge of a chair, your right leg extended bent up towards the ceiling.\r\n2. Position your arms by your sides with your palms facing down for stability.\r\n3. Engage your core and glutes to lift your hips off the floor.\r\n4. Hold the position briefly at the top, squeezing your glutes, then slowly lower your hips back to the floor. Repeat for the desired number of repetitions, then switch legs.', E'1. Ensure your heel remains firmly on the chair to provide a stable base for the movement.\r\n2. Perform the movement slowly and with control to maximize muscle activation and prevent injury.\r\n3. Focus on squeezing your glutes at the top of the movement to enhance muscle engagement.', '{"image_male_start":"images/Legs/Chair Elevated Single Leg Glute Bridge  .jpg","video_url":"videos/Legs/Chair Elevated Single Leg Glute Bridge  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9e3cc963-3ae9-4dde-908b-636b51b8b21d'::uuid, 'Chair feet elevated glute bridge', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '353a86d0-9f31-40d3-bfba-969ae615da15'::uuid, E'1. Lie on your back with both heels placed on the edge of a chair, legs bent at a 90-degree angle.\r\n2. Position your arms by your sides with your palms facing down for stability.\r\n3. Engage your core and glutes, then lift your hips off the floor.\r\n4. Hold the position briefly at the top, squeezing your glutes, then slowly lower your hips back to the floor. Repeat for the desired number of repetitions.', E'1. Ensure your heels remain firmly on the chair to provide a stable base for the movement.\r\n2. Perform the movement slowly and with control to maximize muscle activation and prevent injury.\r\n3. Focus on squeezing your glutes at the top of the movement to enhance muscle engagement.', '{"image_male_start":"images/Legs/chair Feet Elevated Glute Bridge  .jpg","video_url":"videos/Legs/chair Feet Elevated Glute Bridge  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2855b303-15ec-4e61-b8e2-1be9a007358e'::uuid, 'Chair frog feet elevated glute bridge bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '353a86d0-9f31-40d3-bfba-969ae615da15'::uuid, E'1. Lie on your back with your heels placed on the edge of a chair, legs bent, and the soles of your feet touching each other in a frog position.\r\n2. Position your arms by your sides with your palms facing down for stability.\r\n3. Engage your core and glutes to lift your hips off the floor until your body forms a straight line from your shoulders to your knees.\r\n4. Hold the position briefly at the top, squeezing your glutes, then slowly lower your hips back to the floor. Repeat for the desired number of repetitions.', E'1. Ensure your heels remain firmly on the chair to provide a stable base for the movement.\r\n2. Breathe steadily throughout the exercise, exhaling as you lift your hips and inhaling as you lower them.\r\n3. Focus on squeezing your glutes at the top of the movement to enhance muscle engagement.\r\n4. Maintain the frog position with your feet to target the inner thighs and glutes more effectively.\r\n', '{"image_male_start":"images/Legs/chair Frog Feet Elevated Glute Bridge bodyweight  .jpg","video_url":"videos/Legs/chair Frog Feet Elevated Glute Bridge bodyweight  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4850e4b6-11f4-4c11-8a79-b854f6c54c58'::uuid, 'Chair triceps dips', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '353a86d0-9f31-40d3-bfba-969ae615da15'::uuid, E'1. Sit on the edge of a chair with your hands placed next to your hips, gripping the edge of the chair.\r\n2. Extend your legs out in front of you with your heels on the floor and your legs straight.\r\n3. Slide your hips off the chair and lower your body by bending your elbows until they form a 90-degree angle.\r\n4. Push through your palms to extend your elbows and lift your body back up to the starting position. Repeat for the desired number of repetitions.', E'1. Keep your back close to the chair to maintain proper form and avoid straining your shoulders.\r\n2. Avoid locking your elbows at the top of the movement to keep tension on your triceps.\r\n3. Ensure your shoulders remain down and away from your ears to avoid unnecessary strain.', '{"image_male_start":"images/Triceps/chair triceps dips.jpeg","video_url":"videos/Triceps/chair triceps dips  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('08e5a552-f967-48b4-a3e3-43088b0080c1'::uuid, 'Chest bench press correct stance', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie flat on your back on a bench with your feet firmly planted on the floor, positioned so that your eyes are directly under the barbell. Grip the barbell with a slightly wider than shoulder-width grip, palms facing away from you, ensuring your hands are evenly spaced on the bar.\r\n1. Place your feet flat on the floor, slightly wider than shoulder-width apart. Engage your legs and glutes, pushing your feet into the floor to create a strong foundation.\r\n2. Maintain a natural arch in your lower back, keeping your shoulders and glutes in contact with the bench. Retract your shoulder blades and tuck them firmly into the bench for stability.', E'1. Engage your core muscles throughout the exercise to maintain stability and protect your lower back.\r\n2. Ensure your feet are firmly planted on the floor to provide stability and prevent your lower back from arching excessively.\r\n3. Ensure your head remains in contact with the bench, and avoid lifting it during the press.', '{"image_male_start":"images/Chest/Chest Bench Press Correct stance.jpg","image_male_end":"images/Chest/Chest Bench Press Correct stance1.jpg","video_url":"videos/Chest/Chest Bench Press Correct stance.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ac555ce9-0895-4280-8b17-fbc8645a6c46'::uuid, 'Chest dip', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '353a86d0-9f31-40d3-bfba-969ae615da15'::uuid, E'1. Begin by grasping the parallel bars with your palms facing inward and your arms fully extended.\r\n2. Lift your body off the floor and lean slightly forward, crossing your ankles behind you.\r\n3. Lower your body by bending your elbows until your upper arms are parallel to the floor, keeping your chest leaning forward to engage your chest muscles.\r\n4. Push through your palms to extend your elbows and lift your body back to the starting position. Repeat for the desired number of repetitions.', E'1. Focus on leaning forward slightly to emphasize the chest muscles rather than the triceps.\r\n2. Avoid locking your elbows at the top of the movement to keep tension on your muscles.\r\n3. Ensure your shoulders remain down and away from your ears to avoid unnecessary strain.', '{"video_url":"videos/Chest/chest dip.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('03c4932a-67ff-4cab-b166-2836362e7818'::uuid, 'Chest dip (on dip station)', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '4fe96673-7837-4864-8933-5ae471a28857'::uuid, E'1. Begin by grasping the parallel bars of the dip pull-up cage with your palms facing inward and your arms fully extended.\r\n2. Lift your body off the floor and lean slightly forward, crossing your ankles behind you for balance.\r\n3. Lower your body by bending your elbows until your upper arms are parallel to the floor, keeping your chest leaning forward to engage your chest muscles.\r\n4. Push through your palms to extend your elbows and lift your body back to the starting position. Repeat for the desired number of repetitions.', E'1. Focus on leaning forward slightly to emphasize the chest muscles rather than the triceps.\r\n2. Avoid locking your elbows at the top of the movement to keep tension on your muscles.\r\n3. Ensure your shoulders remain down and away from your ears to avoid unnecessary strain.', '{"video_url":"videos/Chest/Chest Dip (on dip station).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e4dcaf0e-3534-42a7-8d9c-62a9d5c88be4'::uuid, 'Chest dip machine', 'Resistance', 'strength', 'weight_reps', 'intermediate', '85c1cd44-00df-4e21-8e60-1305a873b259'::uuid, E'1. Sit down on the seated chest dip machine and firmly grasp the handles with both hands.\r\n2. Position your feet flat on the floor, keeping your chest up and shoulders back.\r\n3. Push the handles downwards by extending your elbows, until your arms are fully extended.\r\n4. Slowly return to the starting position by bending your elbows with control. Repeat for the desired number of repetitions.', E'1. Focus on engaging your chest throughout the exercise.\r\n2. Exhale as you push the handles down and inhale as you return to the starting position.\r\n3. Avoid locking your elbows at the bottom of the movement to keep tension on the muscles.', '{"image_male_start":"images/Chest/chest dip machine.jpg","image_male_end":"images/Chest/chest dip machine1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2c8e5c27-988f-408c-89aa-e4469edac842'::uuid, 'Chest dip on bench', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on the edge of a bench with your hands placed next to your hips, gripping the edge of the bench.\r\n2. Extend your legs out in front of you with your heels on the floor and your legs straight.\r\n3. Slide your hips off the bench and lower your body by bending your elbows until they form a 90-degree angle, leaning your chest slightly forward to engage your chest muscles.\r\n4. Push through your palms to extend your elbows and lift your body back up to the starting position. Repeat for the desired number of repetitions.', E'1. Keep your back close to the bench to maintain proper form and avoid straining your shoulders.\r\n2. Focus on leaning forward slightly to emphasize the chest muscles.\r\n3. Ensure your shoulders remain down and away from your ears to avoid unnecessary strain.', '{"image_male_start":"images/Chest/Chest Dip on Bench.jpg","image_male_end":"images/Chest/Chest Dip on Bench1.jpg","video_url":"videos/Chest/Chest Dip on Bench.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('90cecd2e-819e-4544-a7fe-46086339aae0'::uuid, 'Chest dip weighted', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'febc440b-220a-421e-b13d-520467ea1696'::uuid, E'1. Grip the dip bars firmly with your palms facing inward and your arms fully extended. Position your body slightly forward, with your legs bent and crossed at the ankles, holding weights.\r\n2. Lower your body by bending your elbows, allowing them to flare out slightly to the sides. Lower yourself until your upper arms are parallel to the floor.\r\n3. Push through your palms to extend your elbows and lift your body back to the starting position. Maintain the forward lean throughout the movement to keep the focus on your chest muscles.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Ensure your body remains slightly forward to maximize chest activation and minimize strain on your shoulders.\r\n2. Use a weight that allows you to perform the exercise with proper form and control.\r\n3. Breathe steadily, exhaling as you push up and inhaling as you lower yourself.\r\n4. Avoid locking your elbows at the top of the movement; maintain a slight bend to keep tension on your muscles.\r\n', '{"image_male_start":"images/Chest/chest dip weighted.jpg","image_male_end":"images/Chest/chest dip weighted1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('223e04ce-e277-45ec-a7ad-fc34da43de17'::uuid, 'Chest dip weighted slow', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'febc440b-220a-421e-b13d-520467ea1696'::uuid, E'1. Grip the dip bars firmly with your palms facing inward and your arms fully extended. Position your body slightly forward, with your legs bent and crossed at the ankles, holding weights.\r\n2. Slowly lower your body by bending your elbows, allowing them to flare out slightly to the sides. Lower yourself in a controlled manner until your upper arms are parallel to the floor.\r\n3. Push through your palms to slowly extend your elbows and lift your body back to the starting position. Maintain the forward lean throughout the movement to keep the focus on your chest muscles.\r\n4. Repeat the movement for the desired number of repetitions, maintaining a slow and controlled pace throughout the exercise.', E'1. Ensure your body remains slightly forward to maximize chest activation and minimize strain on your shoulders.\r\n2. Use a weight that allows you to perform the exercise with proper form and control.\r\n3. Perform both the lowering and lifting phases slowly to increase muscle engagement and control.\r\n4. Avoid locking your elbows at the top of the movement; maintain a slight bend to keep tension on your muscles.\r\n', '{"image_male_start":"images/Chest/chest dip weighted slow.jpg","image_male_end":"images/Chest/chest dip weighted slow1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('cf060684-a56f-4742-9ebf-b7aada419812'::uuid, 'Chest dip with pause bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'febc440b-220a-421e-b13d-520467ea1696'::uuid, E'1. Begin by grasping the parallel bars with your palms facing inward and your arms fully extended to lift your body off the floor and lean slightly forward, crossing your ankles behind you for balance.\r\n2. Lower your body by bending your elbows until your upper arms are parallel to the floor, keeping your chest leaning forward to engage your chest muscles.\r\n3. Push through your palms to extend your elbows and lift your body back to the starting position. Pause in the upper position for a few seconds, allowing for a couple seconds of rest. Repeat for the desired number of repetitions. ', E'1. Focus on leaning forward slightly to emphasize the chest muscles rather than the triceps.\r\n2. Avoid locking your elbows at the top of the movement to maintain tension on your muscles.\r\n3. Ensure your shoulders remain down and away from your ears to prevent unnecessary strain.', '{"image_male_start":"images/Chest/chest dip with pause bodyweight.jpg","image_male_end":"images/Chest/chest dip with pause bodyweight1.jpg","video_url":"videos/Chest/chest dip with pause bodyweight.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4fa37177-a6bf-4535-8c70-7100ddab34c7'::uuid, 'Chest fly high to low Resistance band', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Attach the resistance band to a low anchor point behind you. Stand facing away from the anchor point, holding a handle in each hand with your palms facing up.\r\n2.Position one leg forward and the other back, with both knees slightly bent, keeping your back straight and your arms extended down and slightly behind you.\r\n3. Raise the handles up and together in a wide arc, bringing them to meet at head level while keeping a slight bend in your elbows.\r\n4. Slowly lower your arms back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you raise the handles and inhale as you lower them back down.\r\n2. Use a lighter resistance band if needed to ensure proper form and gradually increase the resistance as you get stronger.\r\n3. Focus on squeezing your upper chest muscles at the top of the movement.', '{"image_male_start":"images/Chest/chest fly high to low resistance band.jpg","image_male_end":"images/Chest/chest fly high to low resistance band1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1e371a30-6054-41ab-9c44-03caaec5f518'::uuid, 'Chest fly low to high Resistance band', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Attach the resistance band to a high anchor point behind you. Stand facing away from the anchor point, holding a handle in each hand with your palms facing forward. \r\n2. Position one leg forward and the other back, with both knees slightly bent. Keep your back straight and your arms extended out to the sides at head height.\r\n3. Bring the handles down and together in a wide arc, meeting in front of your lower abdomen while keeping a slight bend in your elbows.\r\n4. Slowly raise your arms back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you raise the handles and inhale as you lower them back down.\r\n2. Use a lighter resistance band if needed to ensure proper form and gradually increase the resistance as you get stronger.\r\n3. Focus on squeezing your upper chest muscles at the top of the movement.', '{"image_male_start":"images/Chest/chest fly low to high resistance band.jpg","image_male_end":"images/Chest/chest fly low to high resistance band1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c82e51f6-adef-4e2a-ae3e-fe9fe463ea2d'::uuid, 'Chest fly side step', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by standing with your feet shoulder-width apart, arms bent at 90 degrees, and your elbows open wide at shoulder height.\r\n2. Step your right foot out to the side, bending your right knee slightly as you bring your elbows together in front of you until they are close together and back.\r\n3. Return to the starting position by stepping your left foot out to the side while repeating the fly motion with your arms.\r\n4. Repeat the movement alternating sides for the desired number of repetitions.', E'1. Perform the movement slowly and with control to maximize muscle activation and prevent injury.\r\n2. Ensure your arms remain bent at the elbows throughout the chest fly motion.\r\n3. Focus on squeezing your chest muscles as you bring your elbows together in front of you.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Chest Fly Side Step.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Chest Fly Side Step1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Chest Fly Side Step.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('82e70a47-0e3a-42ab-86b3-8cf47ea382ec'::uuid, 'Chest lift with rotation', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by lying on your back with your knees bent and feet flat on the floor. Place your hands behind your head with your elbows wide.\r\n2. Engage your core and lift your upper body into a crunch position, holding the contraction at the top.\r\n3. While holding the crunch, rotate your torso to the right. Return to the center.\r\n4. Lower your upper body back to the floor, then repeat the movement, this time rotating to the left. Continue alternating sides for the desired number of repetitions.', E'1. Avoid pulling on your neck with your hands; use your abdominal muscles to lift and rotate your torso.\r\n2. Keep your elbows wide to ensure you are using your core muscles rather than your arms.\r\n3. Make sure your lower back remains pressed against the floor throughout the exercise.', '{"image_male_start":"images/Abdominals/chest lift with rotation.jpeg","video_url":"videos/Abdominals/chest lift with rotation.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('87a908d8-7303-4849-9e8e-b3fd6cc1a429'::uuid, 'Chest out hands behind (hold)', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by standing with your feet shoulder-width apart, keeping your back straight and shoulders relaxed.\r\n2. Interlace your fingers behind your back, extending your arms straight.\r\n3. Lift your arms slightly while pushing your chest out and squeezing your shoulder blades together.\r\n4. Hold this position for the desired duration, maintaining a steady and controlled breath throughout the stretch.', E'1. Focus on squeezing your shoulder blades together to deepen the stretch in your chest and shoulders.\r\n2. Keep your neck relaxed and in a neutral position to avoid tension.\r\n3. Use a mirror to check your form and ensure you are maintaining proper alignment.', '{"image_male_start":"images/Stretching - Mobility/chest out hands behind (hold).jpg","image_male_end":"images/Stretching - Mobility/chest out hands behind (hold)1.jpg","video_url":"videos/Stretching - Mobility/chest out hands behind (hold).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('18a80f98-f317-4415-9239-ac985d5b8cc3'::uuid, 'Chest press front Resistance band', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Attach the resistance band to a sturdy anchor point behind you at chest height. Stand facing away from the anchor point, holding a handle in each hand with your palms facing down.\r\n2. Position one leg forward and the other back, with both knees slightly bent. Start with your elbows bent at 90 degrees, your hands at chest level, and your arms parallel to the floor.\r\n3. Push the handles forward until your arms are fully extended, keeping a slight bend in your elbows.\r\n4. Slowly return to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you push the handles forward and inhale as you return them to the starting position.\r\n2. Maintain a neutral wrist position to prevent strain.\r\n3. Focus on engaging your chest muscles throughout the movement.', '{"image_male_start":"images/Chest/chest press front resistance band.jpg","image_male_end":"images/Chest/chest press front resistance band1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b6bf8ceb-785d-4949-9adb-7eecb9542985'::uuid, 'Chest press high to low cable Resistance band', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Attach the resistance band to a high anchor point behind you. Stand facing away from the anchor point, holding a handle in each hand with your palms facing down.\r\n2. Position one leg forward and the other back, with both knees slightly bent.Start with your elbows bent at 90 degrees and your hands at your chest sides.\r\n3. Push the handles forward and down in a diagonal motion until your arms are fully extended and hands facing your hips.\r\n4. Slowly return to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you push the handles forward and down, and inhale as you return them to the starting position.\r\n2. Keep your back straight and avoid using momentum.\r\n3. Focus on engaging your chest muscles throughout the movement.', '{"image_male_start":"images/Chest/chest press high to low cable resistance band.jpg","image_male_end":"images/Chest/chest press high to low cable resistance band1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('73bbb1b9-a162-43df-8fea-71c85e9dbe65'::uuid, 'Chest press low to high Resistance band', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Attach the resistance band to a low anchor point behind you. Stand facing away from the anchor point, holding a handle in each hand with your palms facing down. \r\n2. Position one leg forward and the other back, with both knees slightly bent. Start with your elbows bent and your hands close to your chest sides.\r\n3. Push the handles forward and up in a diagonal motion until your arms are fully extended.\r\n4. Slowly return to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you push the handles forward and down, and inhale as you return them to the starting position.\r\n2. Keep your back straight and avoid using momentum.\r\n3. Focus on engaging your upper chest muscles throughout the movement.', '{"image_male_start":"images/Chest/chest press low to high resistance band.jpg","image_male_end":"images/Chest/chest press low to high resistance band1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('376ec8b1-a1b6-480f-bfdc-5c5042adc1ab'::uuid, 'Chest Press Machine', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit down on the chest press machine with your feet flat on the floor and your back pressed firmly against the backrest. Grasp the handles with both hands, palms facing forward, and position your elbows at a 90-degree angle.\r\n2. Push the handles forward and extend your arms fully, keeping a slight bend in your elbows to avoid locking them.\r\n3. Slowly return to the starting position by bending your elbows and bringing the handles back towards your chest.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep your back and head flat against the backrest to maintain proper form.\r\n2. Focus on engaging your chest muscles throughout the movement.\r\n3. Exhale as you push the handles forward and inhale as you return to the starting position.', '{"image_male_start":"images/Chest/Chest Press Machine.jpg","image_male_end":"images/Chest/Chest Press Machine1.jpg","image_female_start":"images/Chest/Chest Press Machine_Female.jpg","image_female_end":"images/Chest/Chest Press Machine_Female1.jpg","video_url":"videos/Chest/Chest Press Machine.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('91d07541-566d-4b97-a402-8498604be88f'::uuid, 'Chest pull back', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by standing with your feet shoulder-width apart and leaning slightly forward at the hips. Bend your arms in front of your chest with your palms facing each other, lightly squeezing to activate your chest.\r\n2. Perform a rowing motion with your right arm by pulling it back, bending your elbow, and squeezing your shoulder blade towards your spine.\r\n3. Return your right arm to the starting position, keeping your left arm steady and engaged in front of your chest.\r\n4. Repeat the rowing motion for the desired number of repetitions.', E'1. Focus on squeezing your shoulder blade towards your spine to maximize the engagement of you back muscles.\r\n2. Perform the movement slowly and with control to avoid using momentum and to ensure proper muscle activation.\r\n3. Keep your shoulders down and away from your ears to avoid unnecessary strain.\r\n4. Ensure your chest remains open and engaged by maintaining light tension between your palms.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Chest Pull Back.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Chest Pull Back1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Chest Pull Back.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d89b0946-7630-4451-8a48-d86e2e102021'::uuid, 'Chest raise and rotate', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by standing with your feet shoulder-width apart, arms bent at 90 degrees, with forearms parallel to the floor, elbows squeezed to the sides.\r\n2. Perform a semi-circular motion by rotating your arms upwards and outwards until your forearms are vertical to the floor and your upper arms are at shoulder level.\r\n3. Reverse the motion, bringing your arms back to the starting position with your forearms parallel to the floor.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Focus on maintaining a 90-degree bend in your elbows throughout the exercise to ensure proper form.\r\n2. Breathe steadily throughout the exercise, inhaling as you lift your arms and exhaling as you lower them.\r\n3. Maintain a slight bend in your knees to support your lower back and enhance balance.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Chest raise and rotate.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Chest raise and rotate1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Chest raise and rotate.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('92773902-78c8-4b18-a213-0e67730f7694'::uuid, 'Chest stretch with exercise ball', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '4e9ce883-ea47-492d-be41-fc224e54b4c7'::uuid, E'1. Begin on all fours, with your knees directly under your hips and your hands directly under your shoulders.\r\n2. Place your right forearm on an exercise ball positioned to your side, with your elbow bent at a 90-degree angle.\r\n3. Slowly lower your chest towards the floor to deepen the stretch in your chest.\r\n4. Hold this position for the desired duration, then return to the starting position and switch arms to repeat the stretch on the other side.', E'1. Allow your chest to lower gently towards the floor, but do not force it. Only go as far as is comfortable to avoid straining your shoulder.\r\n2. Perform the movement slowly and with control to maximize the effectiveness of the stretch.\r\n3. Focus on relaxing your chest and shoulder to deepen the stretch.\r\n4. Ensure your hips remain aligned with your knees to maintain a stable base.\r\n5. Use a mirror or partner to check your form and ensure you are maintaining proper alignment.', '{"image_male_start":"images/Stretching - Mobility/chest stretch with exercise ball  .jpg","video_url":"videos/Stretching - Mobility/chest stretch with exercise ball  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('80cd554a-69a6-4b42-a0cc-df23df521627'::uuid, 'Chest tap push up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a plank position with your hands placed slightly wider than shoulder-width apart and your body forming a straight line from head to heels.\r\n2. Lower your body by bending your elbows until your chest is just above the floor, keeping your elbows at a 45-degree angle to your body.\r\n3. Explosively push through your palms to lift your body back up, lifting both hands off the floor at the top of the movement.\r\n4. While in the air, tap your chest with both hands, then quickly place your hands back on the floor and repeat the movement for the desired number of repetitions.', E'1. Perform the movement with control, especially when lowering your body, to prevent injury.\r\n2. Keep your feet slightly wider apart to enhance stability during the explosive push-up and chest tap.\r\n3. Focus on a strong, explosive push to lift your body and hands off the floor for the chest tap.', '{"image_male_start":"images/Chest/Chest Tap Push up.jpg","image_male_end":"images/Chest/Chest Tap Push up1.jpg","video_url":"videos/Chest/Chest Tap Push up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d8b14dbe-1c58-4146-b71c-b01ccac98464'::uuid, 'Child pose', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by kneeling on the floor with your knees together or slightly apart, and your big toes touching.\r\n2. Sit back on your heels, extending your arms forward on the floor, lowering your torso down between your thighs.\r\n3. Rest your forehead on the floor, keeping your arms extended out in front of you with palms facing down.\r\n4. Hold this position for the desired duration, breathing deeply and allowing your body to relax into the stretch.', E'1. Focus on breathing deeply and steadily, inhaling through your nose and exhaling through your mouth.\r\n2. Allow your hips to sink back towards your heels to deepen the stretch in your lower back and hips.\r\n3. If needed, you can place a cushion or folded blanket between your thighs and calves for added comfort.\r\n4. Keep your forehead resting on the floor or on a cushion to maintain a relaxed neck position.\r\n5. Use this pose as a gentle way to release tension and stretch the muscles in your back, hips, and shoulders.', '{"image_male_start":"images/Yoga/Child pose.jpg","image_male_end":"images/Yoga/Child pose1.jpg","video_url":"videos/Yoga/Child pose.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('939e5e1e-28dd-4e32-a1c6-4fe28b0bef02'::uuid, 'Child pose up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin on all fours with your hands directly under your shoulders and your knees under your hips. Keep your elbows bent close to your body with chest close to the floor.\r\n2. Push through your hands to lift your upper body slightly while simultaneously pushing your hips backwards towards your heels. Straighten your arms as you move your hips back.\r\n3. Continue to push your hips back until they are close to your heels, extending your arms fully in front of you on the floor.\r\n4. Hold this position for the desired duration, breathing deeply and allowing your body to relax into the stretch.', E'1. Focus on pushing your hips back towards your heels to deepen the stretch in your lower back and shoulders.\r\n2. Perform the movement slowly and with control to maximize the effectiveness of the stretch.\r\n3. Breathe deeply and steadily, inhaling as you lift your upper body and exhaling as you push your hips back.\r\n4. Use this pose to gently stretch and open up the muscles in your back, shoulders, and hips.', '{"image_male_start":"images/Yoga/child pose up.jpg","image_male_end":"images/Yoga/child pose up1.jpg","video_url":"videos/Yoga/child pose up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6129d7aa-6b58-4369-bbca-b134ad1546bb'::uuid, 'Chin up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '54938b47-43e8-47cd-9efc-18b4424e71e1'::uuid, E'1. Begin by grasping a pull-up bar with an underhand grip (palms facing you) and your hands shoulder-width apart. Hang with your arms fully extended and your legs slightly bent or crossed behind you.\r\n2. Engage your core and pull your shoulder blades down and back to start the movement.\r\n3. Pull your body upward by bending your elbows and contracting your biceps, continuing until your chin is above the bar.\r\n4. Lower yourself back to the starting position with a controlled movement, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Focus on using your biceps and back muscles to lift your body, avoiding excessive momentum.\r\n2. Perform the movement slowly and with control, especially during the lowering phase, to maximize muscle activation and prevent injury.\r\n3. Ensure your shoulders remain down and away from your ears to avoid unnecessary strain.\r\n4. Breathe steadily throughout the exercise, exhaling as you pull up and inhaling as you lower yourself.\r\n5. Use a full range of motion by fully extending your arms at the bottom and bringing your chin above the bar at the top.', '{"image_male_start":"images/Back/chin up.jpg","image_male_end":"images/Back/chin up1.jpg","video_url":"videos/Back/chin up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8604997b-9def-4f1d-b25c-37aef4f95c14'::uuid, 'Chin up (isometric and negative)', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '54938b47-43e8-47cd-9efc-18b4424e71e1'::uuid, E'1. Begin by grasping a pull-up bar with an underhand grip (palms facing you) and your hands shoulder-width apart. Hang with your arms fully extended and your legs slightly bent or crossed behind you.\r\n2. Engage your core and pull your shoulder blades down and back to start the movement.\r\n3. Pull your body upward by bending your elbows and contracting your biceps, continuing until your chin is above the bar. Hold this top position (isometric hold) for a specified duration.\r\n4. After the hold, slowly lower yourself back to the starting position (negative phase), taking about 3-5 seconds to fully extend your arms. Repeat for the desired number of repetitions.', E'1. Focus on using your biceps and upper back muscles to lift your body, avoiding excessive momentum.\r\n2. Perform the isometric hold with control, ensuring your muscles are engaged and you are not simply hanging from the bar.\r\n3. During the negative phase, lower yourself slowly and with control to maximize muscle activation and prevent injury.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5d617f89-d827-4c87-954b-52b4d2dd2054'::uuid, 'Chin up reverse close grip', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '54938b47-43e8-47cd-9efc-18b4424e71e1'::uuid, E'1. Begin by grasping a pull-up bar with a close underhand grip (palms facing you) and your hands placed closer than shoulder-width apart. Hang with your arms fully extended and your legs slightly bent or crossed behind you.\r\n2. Engage your back and start pulling your body upward by bending your elbows and contracting your biceps, continuing until your chin is above the bar.\r\n3. Lower yourself back to the starting position with a controlled movement, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Focus on using your biceps and upper back muscles to lift your body, avoiding excessive momentum.\r\n2. Perform the movement slowly and with control, especially during the lowering phase, to maximize muscle activation and prevent injury.\r\n3. Ensure your shoulders remain down and away from your ears to avoid unnecessary strain.\r\n4. Breathe steadily throughout the exercise, exhaling as you pull up and inhaling as you lower yourself.\r\n5. Use a full range of motion by fully extending your arms at the bottom and bringing your chin above the bar at the top.', '{"image_male_start":"images/Back/chin up reverse close grip .jpg","video_url":"videos/Back/chin up reverse close grip .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c1622415-7664-4af1-9ffe-10966c32e4f6'::uuid, 'Chin up reverse normal grip', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '54938b47-43e8-47cd-9efc-18b4424e71e1'::uuid, E'1. Begin by grasping a pull-up bar with an underhand grip (palms facing you) and your hands shoulder-width apart. Hang with your arms fully extended and your legs slightly bent or crossed behind you.\r\n2. Engage your core and pull your shoulder blades down and back to start the movement.\r\n3. Pull your body upward by bending your elbows and contracting your biceps, continuing until your chin is above the bar.\r\n4. Lower yourself back to the starting position with a controlled movement, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Focus on using your biceps and back muscles to lift your body, avoiding excessive momentum.\r\n2. Perform the movement slowly and with control, especially during the lowering phase, to maximize muscle activation and prevent injury.\r\n3. Ensure your shoulders remain down and away from your ears to avoid unnecessary strain.\r\n4. Breathe steadily throughout the exercise, exhaling as you pull up and inhaling as you lower yourself.\r\n5. Use a full range of motion by fully extending your arms at the bottom and bringing your chin above the bar at the top.', '{"image_male_start":"images/Back/chin up reverse normal grip .jpg","video_url":"videos/Back/chin up reverse normal grip .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e06d98c8-9694-4732-b967-dfc14e67590b'::uuid, 'Chin up reverse wide grip', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '54938b47-43e8-47cd-9efc-18b4424e71e1'::uuid, E'1. Begin by grasping a pull-up bar with an underhand grip (palms facing you) and your hands placed wider than your shoulder-width. Hang with your arms fully extended and your legs slightly bent or crossed behind you.\r\n2. Engage your core and pull your shoulder blades down and back to start the movement.\r\n3. Pull your body upward by bending your elbows and contracting your biceps, continuing until your chin is above the bar.\r\n4. Lower yourself back to the starting position with a controlled movement, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Focus on using your biceps and back muscles to lift your body, avoiding excessive momentum.\r\n2. Perform the movement slowly and with control, especially during the lowering phase, to maximize muscle activation and prevent injury.\r\n3. Ensure your shoulders remain down and away from your ears to avoid unnecessary strain.\r\n4. Breathe steadily throughout the exercise, exhaling as you pull up and inhaling as you lower yourself.\r\n5. Use a full range of motion by fully extending your arms at the bottom and bringing your chin above the bar at the top.', '{"image_male_start":"images/Back/chin up reverse wide grip .jpg","video_url":"videos/Back/chin up reverse wide grip .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('187e2e04-0e3d-4779-9670-e18165d737b3'::uuid, 'Chin ups (narrow parallel grip)', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '54938b47-43e8-47cd-9efc-18b4424e71e1'::uuid, E'1. Begin by grasping a pull-up bar with a narrow parallel grip (palms facing each other) and your hands close together. Hang with your arms fully extended and your legs slightly bent or crossed behind you.\r\n2. Engage your core and start pulling your body upward by bending your elbows and contracting your biceps, continuing until your chin is above the bar.\r\n3. Lower yourself back to the starting position with a controlled movement, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Focus on using your biceps and back muscles to lift your body, avoiding excessive momentum.\r\n2. Perform the movement slowly and with control, especially during the lowering phase, to maximize muscle activation and prevent injury.\r\n3. Ensure your shoulders remain down and away from your ears to avoid unnecessary strain.\r\n4. Breathe steadily throughout the exercise, exhaling as you pull up and inhaling as you lower yourself.\r\n5. Use a full range of motion by fully extending your arms at the bottom and bringing your chin above the bar at the top.', '{"image_male_start":"images/Back/Chin ups (narrow parallel grip).jpg","image_male_end":"images/Back/Chin ups (narrow parallel grip)1.jpg","video_url":"videos/Back/Chin ups (narrow parallel grip).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1ecbcb6d-5211-4854-9d97-25fc544785ad'::uuid, 'Chin-up (isometric and negative)', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '54938b47-43e8-47cd-9efc-18b4424e71e1'::uuid, E'1. Begin by grasping a pull-up bar with an underhand grip (palms facing you) and your hands shoulder-width apart. Hang with your arms fully extended and your legs slightly bent or crossed behind you.\r\n2. Engage your core and pull your shoulder blades down and back to start the movement.\r\n3. Pull your body upward by bending your elbows and contracting your biceps, continuing until your chin is above the bar. Hold this top position (isometric hold) for a specified duration.\r\n4. After the hold, slowly lower yourself back to the starting position (negative phase), taking about 3-5 seconds to fully extend your arms. Repeat for the desired number of repetitions.', E'1. Focus on using your biceps and upper back muscles to lift your body, avoiding excessive momentum.\r\n2. Perform the isometric hold with control, ensuring your muscles are engaged and you are not simply hanging from the bar.\r\n3. During the negative phase, lower yourself slowly and with control to maximize muscle activation and prevent injury.', '{"image_male_start":"images/Back/Chin-up (isometric and negative).jpg","image_male_end":"images/Back/Chin-up (isometric and negative)1.jpg","video_url":"videos/Back/Chin-up (isometric and negative).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('953d7457-4363-448a-a22e-79aef8ce2676'::uuid, 'Circle elbow arm', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by standing with your feet shoulder-width apart. Extend your arms out to the sides at shoulder level, keeping them straight.\r\n2. Bend your arms at the elbows, bringing your fingers to touch your shoulders on the same side, keeping your elbows pointing outwards.\r\n3. Begin to make small circular motions with your elbows, moving them forward, up, back, and down in a controlled manner.\r\n4. Continue circling your elbows for the desired number of repetitions, then reverse the direction of the circles and repeat.', E'1. Focus on making smooth and controlled movements to maximize muscle activation and avoid straining your joints.\r\n2. Perform the movement slowly to maintain control and improve shoulder mobility.\r\n3. Ensure your shoulders remain down and away from your ears to avoid unnecessary strain.\r\n4. Breathe steadily throughout the exercise, maintaining a consistent rhythm.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Circle Elbow Arm.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Circle Elbow Arm1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Circle Elbow Arm.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9aac5515-c049-4d0d-bcde-a941de4f30fb'::uuid, 'Circles knee stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Begin by standing with your feet together and knees slightly bent. Place your hands on your hips for support.\r\n2. Keeping your knees together, bend them together and slowly rotate them in a circular motion to the right, making small controlled circles.\r\n3. Continue circling your knees for the desired number of repetitions, then reverse the direction of the circles and rotate to the left.\r\n4. Maintain a steady pace and keep your upper body relaxed throughout the exercise.\r\n', E'1. Focus on making smooth and controlled movements to avoid straining your knees and joints.\r\n2. Perform the movement slowly to maintain control and improve knee mobility.\r\n3. Ensure your knees remain close together to maximize the effectiveness of the stretch.', '{"image_male_start":"images/Stretching - Mobility/circles knee stretch.jpg","image_male_end":"images/Stretching - Mobility/circles knee stretch1.jpg","video_url":"videos/Stretching - Mobility/circles knee stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d4914d64-5a86-498a-8c10-8ed415c826fc'::uuid, 'Clap curtsy squat', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by standing with your feet shoulder-width apart and your arms extended straight overhead, palms facing each other.\r\n2. Step your right foot behind and across your left leg, bending both knees to lower into a curtsy squat while simultaneously lower your hands in circular motion to your sides.\r\n3. Push through your left heel to return to the starting position, extending your right leg back to shoulder-width apart and bringing your arms back overhead and clap them together.\r\n4. Repeat the movement on the opposite side. Continue alternating sides for the desired number of repetitions.', E'1. Focus on keeping your chest lifted and your back straight to avoid leaning forward.\r\n2. Perform the movement slowly and with control, especially when lowering into the curtsy squat, to maximize muscle activation and prevent injury.\r\n3. Ensure your front knee stays aligned with your front foot and does not extend past your toes.', '{"image_male_start":"images/Legs/Clap Curtsy Squat.jpg","image_male_end":"images/Legs/Clap Curtsy Squat1.jpg","video_url":"videos/Legs/Clap Curtsy Squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0378cdda-856b-4d9d-a989-e818685a205a'::uuid, 'Clap jack', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by standing with your feet together and your arms extended by your sides at shoulder level.\r\n2. Simultaneously jump your feet out to the sides to a wide stance while bringing your arms straight in front of you and clapping your hands together at chest level.\r\n3. Jump your feet back together and bring your arms back to your sides to return to the starting position.\r\n4. Repeat the movement continuously for the desired number of repetitions or duration.', E'1. Ensure your knees are slightly bent during the jumps to absorb impact and protect your joints.\r\n2. Breathe rhythmically throughout the exercise, exhaling as you jump out and clap, and inhaling as you return to the starting position.\r\n3. Focus on maintaining a consistent rhythm and avoiding excessive arm or leg movements to maximize efficiency.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Clap Jack.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Clap Jack1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Clap Jack.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0733fbed-03c1-4f99-9208-c53cbc3a6c4f'::uuid, 'Clap push ups', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a plank position with your hands placed slightly wider than shoulder-width apart and your body forming a straight line from head to heels.\r\n2. Lower your body by bending your elbows until your chest is just above the floor, keeping your elbows at a 45-degree angle to your body.\r\n3. Explosively push through your palms to lift your body off the floor. While in the air, quickly clap your hands together in front of your chest.\r\n4. Place your hands back on the floor to catch yourself and immediately lower into the next push-up. Repeat for the desired number of repetitions.', E'1. Focus on using your chest, shoulders, and triceps to generate the explosive power needed to lift your body off the floor.\r\n2. Perform the movement with control, especially when landing, to avoid jarring your wrists and shoulders.\r\n3. Start with regular push-ups to build strength before progressing to clap push-ups if needed.\r\n4. Breathe steadily throughout the exercise, exhaling as you push up and clap, and inhaling as you lower yourself.', '{"image_male_start":"images/Chest/clap push ups.jpg","image_male_end":"images/Chest/clap push ups1.jpg","video_url":"videos/Chest/clap push ups.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9d130d72-e697-4ab2-9100-7d4b1b358d70'::uuid, 'Climber a padded stool supported', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a plank position on the floor with your hands directly under your shoulders and your body forming a straight line from head to heels. The padded stool should be in front of you.\r\n2. Engage your core and place your right hand on the stool, followed by your left hand, lifting your upper body onto the stool.\r\n3. Reverse the movement by placing your right hand back on the floor, followed by your left hand, lowering your body back into the plank position.\r\n4. Continue climbing up and down the stool, alternating which hand leads the movement for the desired number of repetitions or duration.', E'1. Focus on controlled movements, ensuring you have a stable grip on the stool to avoid slipping.\r\n2. Use a stable stool or bench to support your hands and ensure it is placed on a non-slip surface to prevent movement.\r\n3. Ensure your shoulders remain directly over your hands to avoid unnecessary strain on your wrists and shoulders.', '{"image_male_start":"images/Chest/Climber a padded stool Supported.jpg","image_male_end":"images/Chest/Climber a padded stool Supported1.jpg","video_url":"videos/Chest/Climber a padded stool Supported.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('fd3cbbd0-5777-4782-b39e-80bfddca63f6'::uuid, 'Clock push ups', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a standard push-up position with your hands placed slightly wider than shoulder-width apart and your body forming a straight line from head to heels.\r\n2. Perform a push-up by lowering your body towards the floor by bending your elbows, then push back up to the starting position.\r\n3. Move your right hand and left hand a few inches to the left (clockwise) and perform another push-up.\r\n4. Return both hands to the starting position and perform another push-up. Repeat this sequence, alternating between the starting position and the clockwise position for the desired number of repetitions or duration.\r\n', E'1. Focus on maintaining proper form during each push-up, ensuring your elbows are at a 45-degree angle to your body.\r\n2. Perform the movement with control, especially when moving your hands, to avoid unnecessary strain on your wrists and shoulders.\r\n3. Breathe steadily throughout the exercise, exhaling as you push up and inhaling as you lower yourself.', '{"image_male_start":"images/Chest/Clock push ups.jpg","image_male_end":"images/Chest/Clock push ups1.jpg","video_url":"videos/Chest/Clock push ups.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8712df51-76ef-47a8-802b-daa1ab325cdb'::uuid, 'Close grip barbell bench press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Lie flat on your back on a bench with your feet firmly planted on the floor. Position yourself so that your eyes are directly under the barbell. Grip the barbell with a close grip, placing your hands slightly closer than shoulder-width apart, with palms facing away from you.\r\n2. Lower the barbell slowly to your mid-chest by bending your elbows, keeping them close to your body throughout the movement.\r\n3. Push the barbell back up to the starting position by fully extending your arms without locking your elbows. Repeat for the desired number of repetitions.', E'1. Ensure your wrists remain straight and aligned with your forearms to avoid unnecessary strain.\r\n2. Lower the barbell in a controlled manner to maximize muscle engagement and prevent injury.\r\n3. Keep your elbows close to your body to emphasize triceps activation and reduce shoulder strain.\r\n', '{"image_male_start":"images/Triceps/Close grip barbell bench press.jpeg","video_url":"videos/Triceps/Close grip barbell bench press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('18d1402d-ea80-40e5-bf80-6dfd01df0bf1'::uuid, 'Close grip push up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a plank position with your hands placed under your shoulders, with straight arms. Your body should form a straight line from head to heels.\r\n2. Lower your body towards the floor by bending your elbows, keeping them close to your sides.\r\n3. Push through your palms to lift your body back up to the starting position, fully extending your arms.\r\n4. Repeat for the desired number of repetitions.', E'1. Focus on using your triceps and chest muscles to lift your body, keeping your elbows close to your sides.\r\n2. Perform the movement with control, especially during the lowering phase, to maximize muscle activation and prevent injury.\r\n3. Breathe steadily throughout the exercise, exhaling as you push up and inhaling as you lower yourself.', '{"image_male_start":"images/Chest/Close Grip Push up.jpg","image_male_end":"images/Chest/Close Grip Push up1.jpg","video_url":"videos/Chest/Close Grip Push up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('33918d71-becb-4fca-97fc-3ba2affd999f'::uuid, 'Close-reverse Grip Chin-Up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '54938b47-43e8-47cd-9efc-18b4424e71e1'::uuid, E'1. Begin by grasping a pull-up bar with a close underhand grip (palms facing you) and your hands placed closer than shoulder-width apart. 2. Hang with your arms fully extended and your legs slightly bent or crossed behind you.\r\n3. Engage your back and start pulling your body upward by bending your elbows and contracting your biceps, continuing until your chin is above the bar.\r\n4. Lower yourself back to the starting position with a controlled movement, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Focus on using your biceps and upper back muscles to lift your body, avoiding excessive momentum.\r\n2. Breathe steadily throughout the exercise, exhaling as you pull up and inhaling as you lower yourself.\r\n3. Ensure your shoulders remain down and away from your ears to avoid unnecessary strain.\r\n4. Use a full range of motion by fully extending your arms at the bottom and bringing your chin above the bar at the top.', '{"image_male_start":"images/Back/Close-reverse Grip Chin-Up.jpg","image_male_end":"images/Back/Close-reverse Grip Chin-Up1.jpg","video_url":"videos/Back/Close-reverse Grip Chin-Up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('024e6ff6-5512-4168-ada7-c22bf8468c86'::uuid, 'Cluster', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Begin in a squatted position with your feet shoulder-width apart and a barbell on the floor in front of you. Grip the barbell with an overhand grip, hands slightly wider than shoulder-width apart.\r\n2. Lift the barbell to a front rack position by performing a clean movement, explosively extending your hips and knees, shrugging your shoulders, and then catching the barbell at your shoulders with your elbows pointing forward. As you catch the barbell, simultaneously lower into a squat by bending your knees and hips until your thighs are lower than your knees.\r\n3. From the bottom of the squat, stand up straight by extending your knees.\r\n4. Lower the barbell back to the floor. Repeat the sequence for the desired number of repetitions.', E'1. Use a controlled and explosive movement during the clean phase to effectively lift the barbell.\r\n2. Ensure a controlled descent of the barbell to the floor to prevent injury and maintain form.\r\n3. Maintain a slight bend in your knees when catching the barbell in the front rack position.\r\n', '{"image_male_start":"images/Powerlifting/cluster.jpg","image_male_end":"images/Powerlifting/cluster1.jpg","video_url":"videos/Powerlifting/cluster.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c0711421-8c82-4a6c-8da2-eaab6fe40da6'::uuid, 'Cobra full push up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a plank position with your hands placed under your shoulders, your body forming a straight line from head to heels.\r\n2. Perform a push-up by lowering your body towards the floor by bending your elbows, keeping them close to your sides.\r\n3. As your chest reaches the floor, leave your hips on the floor and press through your palms to lift your chest up, straightening your arms and arching your back into the cobra position.\r\n4. Bend your arms to lower your chest back to the floor, then press through your palms to lift your body back to the starting plank position. Repeat for the desired number of repetitions.', E'1. Focus on using your chest, shoulders, and triceps to push your body up while keeping your elbows close to your sides.\r\n2. Perform the movement with control, especially during the transitions between plank, push-up, and cobra positions to maximize muscle activation and prevent injury.\r\n3. Keep your hips on the floor during the cobra position to maintain proper form and maximize the stretch in your lower back.\r\n4. Breathe steadily throughout the exercise, exhaling as you push up and lift your chest, and inhaling as you lower yourself.\r\n', '{"image_male_start":"images/Yoga/Cobra Full Push up.jpg","image_male_end":"images/Yoga/Cobra Full Push up1.jpg","video_url":"videos/Yoga/Cobra Full Push up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('87034ebf-0e8f-4d79-8ecd-151dd8092add'::uuid, 'Cobra push up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by lying face down on the floor with your legs extended straight behind you and your hands placed at shoulder level, palms flat on the floor and elbows close to your sides.\r\n2. Engage your core and press through your palms to lift your chest off the floor, straightening your arms to come into the cobra position. 3. Keep your hips on the floor. Hold the cobra position for a moment, feeling the stretch in your lower back and abdomen.\r\n4. . Slowly lower your chest back to the floor by bending your elbows, returning to the starting position. Repeat for the desired number of repetitions.', E'1. Focus on using your chest, shoulders, and triceps to push your body up while keeping your elbows close to your sides.\r\n2. Keep your hips on the floor during the cobra position to maintain proper form and maximize the stretch in your lower back.\r\n3. Ensure your shoulders remain down and away from your ears to avoid unnecessary strain.\r\n4. Breathe steadily throughout the exercise, exhaling as you push up and lift your chest, and inhaling as you lower yourself.\r\n', '{"image_male_start":"images/Yoga/cobra push up.jpg","image_male_end":"images/Yoga/cobra push up1.jpg","video_url":"videos/Yoga/cobra push up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7c4ce7fe-dff7-4454-8686-4f7a362c25fc'::uuid, 'Cobra side Ab stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Begin by lying face down on the floor with your legs extended straight behind you and your hands placed at shoulder level, palms flat on the floor.\r\n2. Press through your palms to lift your chest off the floor, straightening your arms to come into the cobra position, keeping your hips on the floor.\r\n3. From the cobra position, slowly rotate your torso to the right, looking over your right shoulder, and hold the stretch for a moment, feeling the stretch along the left side of your abdomen. Return to the center cobra position.\r\n4. Slowly rotate your torso to the left, looking over your left shoulder, and hold the stretch, feeling the stretch along the right side of your abdomen. Return to the center cobra position. Repeat for the desired number of repetitions.', E'1. Focus on using your chest, shoulders, and triceps to push your body up while keeping your elbows close to your sides.\r\n2. Perform the movement with control to maximize muscle activation and prevent injury.\r\n3. Ensure your shoulders remain down and away from your ears to avoid unnecessary strain.\r\n4. Breathe steadily throughout the exercise, exhaling as you push up and lift your chest, and inhaling as you lower yourself and rotate.\r\n5. Keep your hips on the floor during the cobra and side stretches to maintain proper form and maximize the stretch in your lower back and sides.', '{"image_male_start":"images/Yoga/Cobra Side Ab Stretch.jpg","image_male_end":"images/Yoga/Cobra Side Ab Stretch1.jpg","video_url":"videos/Yoga/Cobra Side Ab Stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6ef5d953-d8ff-470a-be07-0cd16ece439b'::uuid, 'Cobra yoga pose hold', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by lying face down on the floor with your legs extended straight behind you and your hands placed at shoulder level, palms flat on the floor.\r\n2. Engage your core and press through your palms to lift your chest off the floor, straightening your arms to come into the cobra position, keeping your hips on the floor.\r\n3. Hold the cobra position, keeping your arms straight and your chest lifted, while breathing steadily.', E'1. Perform the movement with control, ensuring a smooth and steady rise into the cobra position.\r\n2. Ensure your shoulders remain down and away from your ears to avoid unnecessary strain.\r\n3. Breathe deeply and steadily throughout the exercise, inhaling as you lift your chest and exhaling as you hold the position.\r\n4. Keep your hips on the floor during the cobra hold to maintain proper form and maximize the stretch in your lower back and abdomen.', '{"image_male_start":"images/Yoga/cobra yoga pose hold.jpg","image_male_end":"images/Yoga/cobra yoga pose hold1.jpg","video_url":"videos/Yoga/cobra yoga pose hold.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3ed0c446-69c8-48cf-a924-a5d76dc467e7'::uuid, 'Cocoons', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by lying flat on your back with your legs extended straight and your arms extended overhead on the floor.\r\n2. Engage your core and simultaneously lift your legs off the floor while bringing your arms forward to meet your knees, curling your body into a "cocoon" position.\r\n3. Hold the cocoon position for a moment, squeezing your core muscles.\r\n4. Slowly lower your legs and arms back to the starting position, maintaining control. Repeat for the desired number of repetitions.', E'1. Focus on using your abdominal muscles to lift your legs and upper body, avoiding momentum.\r\n2. Use a mat or soft surface to support your back and prevent discomfort during the exercise.\r\n3. Ensure your lower back remains in contact with the floor as you lift and lower your legs to avoid unnecessary strain.\r\n4. Breathe steadily throughout the exercise, exhaling as you curl into the cocoon position and inhaling as you return to the starting position.\r\n', '{"image_male_start":"images/Stretching - Mobility/cocoons.jpg","image_male_end":"images/Stretching - Mobility/cocoons1.jpg","video_url":"videos/Stretching - Mobility/cocoons.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c3049204-8c25-4ce9-aa26-7b82de183fbf'::uuid, 'Commando pull-up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '54938b47-43e8-47cd-9efc-18b4424e71e1'::uuid, E'1. Begin by grasping a pull-up bar with both hands placed close together, palms facing each other in a neutral grip.\r\n2. Hang with your arms fully extended and your body straight. \r\n3. Engage your back and pull your body up towards the bar, leaning your head to one side of the bar as you lift.\r\n4. Lower yourself back to the starting position with a controlled movement. Repeat the pull-up, alternating the side of your head relative to the bar for each repetition.', E'1. Use a full range of motion by fully extending your arms at the bottom and bringing your head above the bar at the top.\r\n2. Perform the movement slowly and with control, especially during the lowering phase, to maximize muscle activation and prevent injury.\r\n3. Ensure your shoulders remain down and away from your ears to avoid unnecessary strain.\r\n4. Breathe steadily throughout the exercise, exhaling as you pull up and inhaling as you lower yourself.\r\n', '{"image_male_start":"images/Back/Commando Pull-up.jpg","image_male_end":"images/Back/Commando Pull-up1.jpg","video_url":"videos/Back/Commando Pull-up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7bc493ea-6335-4f76-b170-a068f9b0470d'::uuid, 'Concentration curls dumbbell', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench with your legs spread apart. Hold a dumbbell in your right hand and rest your right elbow on the inside of your right thigh.\r\n2. Let the dumbbell hang down towards the floor with your arm fully extended.\r\n3. Curl the dumbbell towards your shoulder by contracting your biceps, keeping your elbow stationary and close to your thigh. Squeeze the biceps at the top of the movement.\r\n4. Slowly lower the dumbbell back to the starting position, fully extending your arm. Repeat for the desired number of repetitions, then switch to the left arm.', E'1. Focus on squeezing the biceps at the top of the movement to maximize muscle activation.\r\n2. Ensure your back remains straight and avoid leaning back as you lift the weight.\r\n3. Use a weight that allows you to perform the exercise with proper form and without straining.\r\n', '{"image_male_start":"images/Biceps/concentration curls dumbbell.jpeg","video_url":"videos/Biceps/concentration curls dumbbell .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('37feae22-79b3-4c79-82bf-22c1984efd0e'::uuid, 'Control balance', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie down on your back, raise your legs towards the head, and hold your feet by extending your arms overhead.\r\n2. Release your right leg and take it upward until it becomes vertical to the floor.\r\n3. Place your free hand on your left calf and maintain balance.\r\n4. Hold for a while, return to the starting position, and repeat.', E'1. Perform the movement with control, especially when lifting and lowering your legs, to maximize muscle activation and prevent injury.\r\n2. Ensure your shoulders remain on the floor and avoid straining your neck.\r\n3. Breathe steadily throughout the exercise, exhaling as you lift your leg and inhaling as you lower it.\r\n4. Use a mat or soft surface to support your back and prevent discomfort during the exercise.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Control Balance.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Control Balance1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Control Balance.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a7edad0d-f1c9-4674-b9dc-1adc2e6b1974'::uuid, 'Corner touch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin standing with your body turned to the left side in a semi-lunge position, your left leg bent, and your right leg extended behind you lightly bent. Extend your right arm upward and your left arm downward to your side.\r\n2. Engage your core and rotate your body on your feet, turning to face the opposite side. As you rotate, lower your right arm and raise your left arm, so that your left arm is now upward and your right arm is downward to your side.\r\n3. Repeat the movement, alternating sides, and performing the desired number of repetitions.', E'1. Focus on using a controlled motion when rotating your body to avoid straining your back.\r\n2. Ensure you stay in place as you rotate, using a controlled motion to maintain balance and stability.\r\n3. Ensure your movements are smooth and deliberate to maximize muscle activation and prevent injury.\r\n4. Breathe steadily throughout the exercise, exhaling as you rotate and inhaling as you return to the starting position.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Corner Touch.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Corner Touch1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Corner Touch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('861e1531-5232-444a-a988-695b2a7b02b5'::uuid, 'Corner wall chest stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by standing in front of a corner of a wall with your feet shoulder-width apart. Place your palms flat against the walls at your sides, with your elbows slightly below shoulder height.\r\n2. Lean forward into the corner, keeping your legs in place, to lean into the stretch.\r\n3. Push your chest forward towards the corner, feeling the stretch across your chest and shoulders. Hold this position for the desired duration.\r\n4. Slowly step back to return to the starting position and repeat the stretch as needed.\r\n', E'1. Perform the stretch with control, gradually increasing the intensity as your muscles loosen.\r\n2. Breathe deeply and steadily throughout the stretch, inhaling as you prepare and exhaling as you lean into the stretch.\r\n3. Ensure your palms remain flat against the wall to maximize the stretch across your chest and shoulders.\r\n4. Use a mat or soft surface for your feet if needed to prevent slipping during the stretch.', '{"image_male_start":"images/Stretching - Mobility/Corner Wall Chest Stretch.jpg","image_male_end":"images/Stretching - Mobility/Corner Wall Chest Stretch1.jpg","video_url":"videos/Stretching - Mobility/Corner Wall Chest Stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3177acae-0387-4050-95e5-4a833ae05c87'::uuid, 'Cossack squat', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by standing with your feet wider than shoulder-width apart and your toes pointing slightly outward.\r\n2. Shift your weight to your right leg, bending your right knee while keeping your left leg straight. Lower your hips towards the floor, ensuring your right knee tracks over your right toes.\r\n3. Push through your right heel to return to the starting position, then repeat the movement on the left side by shifting your weight to your left leg and bending your left knee. Alternate sides for the desired number of repetitions.', E'1. Focus on maintaining an upright chest and straight back to ensure proper form and prevent injury.\r\n2. Perform the movement with control, especially when shifting your weight and lowering your hips, to maximize muscle activation.\r\n3. Ensure your knee tracks over your toes during the squat to avoid unnecessary strain on your joints.\r\n4. Breathe steadily throughout the exercise, exhaling as you descend and inhaling as you return to the starting position.', '{"image_male_start":"images/Legs/Cossack Squat.jpg","image_male_end":"images/Legs/Cossack Squat1.jpg","video_url":"videos/Legs/Cossack Squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b2aa74a7-5559-4cd9-9247-8d5ac344115c'::uuid, 'Counterbalanced skater squat', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand tall on your right foot, curl your left leg to 90 degrees, and extend your arms forward.\r\n2. Lower your hips while bending your right knee, lean forward, and maintain balance by moving your left thigh backward.\r\n3. Hold this position for a while, return to the initial position, and repeat.', E'1. Keep your core engaged throughout the exercise to maintain stability and balance.\r\n2. Focus on maintaining an upright chest and straight back to ensure proper form and prevent injury.\r\n3. Breathe steadily throughout the exercise, exhaling as you lower into the squat and inhaling as you return to the starting position.\r\n4. Ensure your knee tracks over your toes during the squat to avoid unnecessary strain on your joints.', '{"image_male_start":"images/Legs/Counterbalanced Skater Squat.jpg","image_male_end":"images/Legs/Counterbalanced Skater Squat1.jpg","video_url":"videos/Legs/Counterbalanced Skater Squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('16c3660a-6422-419a-8154-859a92d39417'::uuid, 'Crab pose', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by sitting on the floor with your legs bent, feet flat on the floor, and hands placed behind you with your fingers pointing towards your body.\r\n2. Engage your core and press through your palms and feet to lift your hips off the floor, creating a tabletop position with your body.\r\n3. Hold this position, ensuring your hips are lifted high and your torso is parallel to the floor, while keeping your head in line with your spine.\r\n4. After holding the position for the desired duration, slowly lower your hips back to the floor and return to the starting position.', E'1. Focus on pressing through your palms and feet to lift your hips as high as possible, creating a straight line from your shoulders to your knees.\r\n2. Use a mat or soft surface to support your hands and feet to prevent discomfort during the exercise.\r\n3. Ensure your shoulders remain down and away from your ears to avoid unnecessary strain.\r\n4. Breathe deeply and steadily throughout the exercise, inhaling as you lift your hips and exhaling as you hold the position.\r\n', '{"image_male_start":"images/Yoga/Crab Pose.jpeg","video_url":"videos/Yoga/Crab Pose.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a6f709e6-1998-4d50-a71e-17c890988f42'::uuid, 'Crab twist toe touch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by sitting on the floor with your legs bent, feet flat on the floor, and hands placed behind you with your fingers pointing towards your body.\r\n2. Engage your glutes and press through your palms and feet to lift your hips off the floor, creating a tabletop position with your body.\r\n3. Simultaneously lift your right hand and left foot off the floor and twist your torso to reach your right hand towards your left foot, attempting to touch your left toe.\r\n4. Return your hand  and leg to the floor and repeat the movement on the opposite side by lifting your left hand and reaching towards your right foot. Continue alternating sides for the desired number of repetitions.', E'1. Perform the twist with control to maximize muscle activation and prevent injury.\r\n2. Ensure your shoulders remain down and away from your ears to avoid unnecessary strain.\r\n3. Breathe steadily throughout the exercise, exhaling as you twist and reach towards your toe and inhaling as you return to the starting position.\r\n4. Use a mat or soft surface to support your hands and feet to prevent discomfort during the exercise.', '{"image_male_start":"images/Abdominals/Crab Twist Toe Touch.jpeg","video_url":"videos/Abdominals/Crab Twist Toe Touch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5e0d645d-5ebb-4e5d-8724-06b47c18aa3d'::uuid, 'Criss cross arms lift', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by standing with your feet shoulder-width apart and your arms extended straight in front of you at your hip height, palms facing inwards.\r\n2. Cross your right arm over your left arm at the wrists and then cross your left arm over your right arm.\r\n3. Repeat the crossing movement until your hands are opposite your head. \r\n4. Lower your arms back to your hip level by crossing them down.', E'1. Focus on using your shoulder muscles to lift and lower your arms, maintaining a controlled motion throughout.\r\n2. Perform the movement with control to maximize muscle activation and prevent injury.\r\n3. Ensure your shoulders remain down and away from your ears to avoid unnecessary strain.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Criss Cross Arms Lift.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Criss Cross Arms Lift1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Criss Cross Arms Lift.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('35bef06e-5349-4192-9947-4ad84e9d88f0'::uuid, 'Criss cross elbow to knee', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by standing with your feet wider than shoulder-width apart and your hands placed behind your head, elbows pointing out to the sides.\r\n2. Engage your quadriceps and perform a light jump, crossing your legs in mid-air, and land with your feet crossed and immediately lightly jump back to the starting position.\r\n3. Lift your right knee towards your left elbow while twisting your torso to bring your left elbow towards your right knee.\r\n4. Return to the starting position, perform another light jump crossing your legs, and repeat the movement on the opposite side by lifting your left knee towards your right elbow. Continue alternating sides for the desired number of repetitions.', E'1. Focus on using your abdominal muscles to twist your torso and lift your knee, maintaining a controlled motion throughout.\r\n2. Perform the movement with control, especially during the jumps and twists, to maximize muscle activation and prevent injury.\r\n3. Breathe steadily throughout the exercise, exhaling as you twist and lift your knee and inhaling as you return to the starting position.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Criss Cross Elbow To Knee.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Criss Cross Elbow To Knee1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Criss Cross Elbow To Knee.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c5ecc94e-6268-4ccd-a0e8-b316419f5794'::uuid, 'Criss cross jack', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by standing with your feet wide apart and your arms extended straight out to the sides at shoulder level.\r\n2. Engage your quadriceps and perform a light jump, crossing your legs in mid-air while simultaneously bringing both arms straight in front of your chest.\r\n3. Land with your legs crossed and your arms in front of your chest.\r\n4. Immediately jump again to return to the starting position with your feet wide apart and your arms extended to the sides at shoulder level. Repeat the movement for the desired number of repetitions.', E'1. Focus on using your leg, chest and shoulder muscles to perform the jumps and crosses, maintaining a controlled motion throughout.\r\n2. Perform the movement with control, especially during the jumps, to maximize muscle activation and prevent injury.\r\n3. Breathe steadily throughout the exercise, exhaling as you cross your legs and arms and inhaling as you return to the starting position.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/criss cross jack.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/criss cross jack1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/criss cross jack.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6ab339c1-c9e9-40d5-9ce3-77d83e81e559'::uuid, 'Criss cross jump', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by standing with your feet wide apart and your arms bent out to the sides at shoulder level and hands facing each other.\r\n2. Engage your quadriceps and perform a light jump, crossing your legs in mid-air while simultaneously crossing both arms in front of your chest.\r\n3. Land with your legs crossed and your arms in front of your chest.\r\n4. Immediately jump again to return to the starting position with your feet wide apart and your arms bent out to the sides at shoulder level and hands facing each other. Repeat the movement for the desired number of repetitions.', E'1. Focus on using your leg, chest and arm muscles to perform the jumps and crosses, maintaining a controlled motion throughout.\r\n2. Perform the movement with control, especially during the jumps, to maximize muscle activation and prevent injury.\r\n3. Ensure your shoulders remain down and away from your ears to avoid unnecessary strain.\r\n', '{"image_male_start":"images/Calisthenics-Cardio-Functional/criss cross jump.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/criss cross jump1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/criss cross jump.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('15aec79c-6cb3-46cc-8c12-4c7d97e17251'::uuid, 'Criss cross leg raises', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by lying flat on your back with your legs extended straight out and your arms resting by your sides or under your lower back for support. Engage your core and lift both legs slightly off the floor.\r\n2. Start crisscrossing your legs in a scissor motion, crossing your right leg over your left and then your left leg over your right.\r\n3. Gradually move your legs upward while continuing to crisscross until they form a 45-degree angle with your torso. Then, lower them back down to just above the floor, maintaining the crisscross motion throughout.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Keep your core engaged throughout the exercise to maintain stability and support your lower back.\r\n2. Focus on using your leg muscles to control the movement, keeping your legs straight and performing the crisscross motion smoothly.\r\n3. Ensure your lower back remains pressed into the floor to avoid unnecessary strain.\r\n4. Breathe steadily throughout the exercise, exhaling as you move your legs upward and inhaling as you lower them.', '{"image_male_start":"images/Abdominals/Criss Cross Leg Raises.jpeg","video_url":"videos/Abdominals/Criss Cross Leg Raises.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('53ad3752-d228-41c4-ae95-0a27c681e6c6'::uuid, 'Cross over shoulder stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Begin by standing with your feet shoulder-width apart. Lean forward at your hips with a slight arch in your back.\r\n2. Cross your arms and place your hands on your knees.\r\n3. Engage your core and gently press your chest downward to feel the stretch in your shoulders and upper back.\r\n4. Hold the stretch for the desired duration, then slowly return to a standing position.', E'1. Keep your core engaged to maintain stability and support your lower back.\r\n2. Focus on keeping a slight arch in your back and avoid rounding your spine.\r\n3. Perform the stretch with control to avoid overextending your shoulders.\r\n4. Breathe deeply and steadily throughout the stretch, inhaling through your nose and exhaling through your mouth.', '{"image_male_start":"images/Shoulders/cross over shoulder stretch .jpg","video_url":"videos/Shoulders/cross over shoulder stretch .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b5507678-ada0-4ad7-8566-c0a6ae258b24'::uuid, 'Crossed arms front leg kick', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by standing with your feet shoulder-width apart and your arms crossed in front of your chest.\r\n2. Engage your core and lift your right leg straight in front of you to perform a front kick, keeping your leg as straight as possible.\r\n3. Lower your right leg back to the starting position.\r\n4. Immediately lift your left leg to perform a front kick, keeping your arms crossed and your core engaged. Continue alternating legs for the desired number of repetitions.', E'1. Focus on maintaining an upright posture, avoiding leaning back or forward as you kick.\r\n2. Breathe steadily throughout the exercise, exhaling as you kick and inhaling as you return to the starting position.\r\n3. Ensure your kicks are performed with a controlled motion, avoiding any jerky movements.', '{"image_male_start":"images/Legs/Crossed Arms Front Leg Kick.jpg","image_male_end":"images/Legs/Crossed Arms Front Leg Kick1.jpg","video_url":"videos/Legs/Crossed Arms Front Leg Kick.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9bc51464-fc30-48ff-93d4-c7f80765d805'::uuid, 'Crossover kneeling hip flexor stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Begin in a lunge position with your right foot on the floor and your left knee on the floor, ensuring both legs are bent at 90 degrees.\r\n2. Engage your core and rotate your torso towards your right leg, placing both arms straight and pulling on the outside of your right thigh.\r\n3. Gently push your hips forward while keeping your back straight to stretch.\r\n4. Hold this position for the desired duration, then switch sides and repeat.', E'1. Ensure your front knee is aligned over your ankle to avoid unnecessary strain on your knee joint.\r\n2. Perform the stretch with control to avoid overextending your hip flexors.\r\n3. Breathe deeply and steadily throughout the stretch, inhaling through your nose and exhaling through your mouth.', '{"image_male_start":"images/Stretching - Mobility/Crossover Kneeling Hip Flexor Stretch.jpg","image_male_end":"images/Stretching - Mobility/Crossover Kneeling Hip Flexor Stretch1.jpg","video_url":"videos/Stretching - Mobility/Crossover Kneeling Hip Flexor Stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3904410a-68ba-4774-8c7b-8fb13675bafd'::uuid, 'Crouching heel back calf stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Begin standing with your legs wide in a semi-lunge position, turned to the right side, with your left leg extended back and your right knee bent.\r\n2. Bend forward at the hips and place your hands on the floor in front of you for balance, keeping your back as straight as possible.\r\n3. Push your left heel down towards the floor, feeling a stretch in your left calf muscle.\r\n4. Hold the stretch for the desired duration, then switch sides and repeat the stretch on the right side.', E'1. Focus on keeping your back straight and your shoulders down and away from your ears.\r\n2. Perform the stretch with control to avoid overextending your calf muscles.\r\n3. Breathe deeply and steadily throughout the stretch, inhaling through your nose and exhaling through your mouth.\r\n4. Ensure your supporting leg (the one in front) remains bent to maintain balance.', '{"image_male_start":"images/Stretching - Mobility/Crouching Heel Back Calf Stretch.jpg","image_male_end":"images/Stretching - Mobility/Crouching Heel Back Calf Stretch1.jpg","video_url":"videos/Stretching - Mobility/Crouching Heel Back Calf Stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('09678b45-4474-4fae-a273-96638bae2757'::uuid, 'Crunch (arms straight)', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by lying flat on your back with your knees bent and your feet flat on the floor, hip-width apart.\r\n2. Extend your arms straight above your head, keeping them in line with your ears.\r\n3. Engage your core and lift your shoulder blades off the floor, reaching your arms straight up towards the ceiling.\r\n4. Lower your shoulder blades back to the floor with control, keeping your arms extended. Repeat the movement for the desired number of repetitions.', E'1. Avoid using your neck or momentum to lift your shoulders; focus on using your abdominal muscles.\r\n2. Use a mat or soft surface to support your back and prevent discomfort during the exercise.\r\n3. Breathe steadily throughout the exercise, exhaling as you lift your shoulders and inhaling as you lower them.', '{"image_male_start":"images/Abdominals/Crunch (arms straight).jpeg","video_url":"videos/Abdominals/Crunch (arms straight).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6283c6dc-0497-4cd4-bdb0-1762845fd8a5'::uuid, 'Crunch (hands overhead)', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by lying flat on your back with your knees bent and your feet flat on the floor, hip-width apart.\r\n2. Extend your arms straight overhead with hands close together, keeping them in line with your ears.\r\n3. Engage your core and lift your shoulder blades off the floor, reaching your arms straight up towards the ceiling.\r\n4. Lower your shoulder blades back to the floor with control, keeping your arms extended. Repeat the movement for the desired number of repetitions.', E'1. Avoid using your neck or momentum to lift your shoulders; focus on using your abdominal muscles.\r\n2. Perform the movement with control to maximize muscle activation and prevent injury.\r\n3. Breathe steadily throughout the exercise, exhaling as you lift your shoulders and inhaling as you lower them.\r\n4. Ensure your lower back remains pressed into the floor to avoid unnecessary strain.', '{"image_male_start":"images/Abdominals/Crunch (hands overhead).jpeg","video_url":"videos/Abdominals/Crunch (hands overhead).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6e458157-4576-43ce-9dca-16d1fd88582d'::uuid, 'Crunch (legs on stability ball)', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by lying flat on your back with your knees bent at a 90-degree angle and your lower legs resting on a stability ball.\r\n2. Place your hands behind your head with your elbows pointing out to the sides.\r\n3. Lift your shoulder blades off the floor, curling your upper body towards your knees while keeping your legs stable on the ball.\r\n4. Lower your shoulder blades back to the floor with control, maintaining your legs'' position on the ball. Repeat the movement for the desired number of repetitions.', E'1. Keep your core engaged throughout the exercise to maintain stability and support your lower back.\r\n2. Avoid pulling on your neck with your hands; focus on using your abdominal muscles to lift your shoulders.\r\n3. Breathe steadily throughout the exercise, exhaling as you lift your shoulders and inhaling as you lower them.', '{"image_male_start":"images/Abdominals/Crunch (legs on stability ball).jpeg","video_url":"videos/Abdominals/Crunch (legs on stability ball).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e164baa7-d356-47c3-8b45-b94d8e1373b6'::uuid, 'Crunch (on bosu ball)', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by sitting on a BOSU ball with your feet flat on the floor and your knees bent.\r\n2. Lean back to position your lower back against the BOSU ball, ensuring your upper body is supported. Place your hands behind your head with your elbows pointing out to the sides.\r\n3. Engage your core and lift your shoulder blades upwards, curling your upper body towards your knees.\r\n4. Lower your shoulder blades back down with control, maintaining your core engagement. Repeat the movement for the desired number of repetitions.', E'1. Avoid pulling on your neck with your hands; focus on using your abdominal muscles to lift your shoulders.\r\n2. Use a mat or soft surface under the BOSU ball if needed for additional stability and comfort.\r\n3. Breathe steadily throughout the exercise, exhaling as you lift your shoulders and inhaling as you lower them.\r\n4. Ensure your lower back remains in contact with the BOSU ball to avoid unnecessary strain.\r\n', '{"image_male_start":"images/Abdominals/Crunch (on bosu ball).jpeg","video_url":"videos/Abdominals/Crunch (on bosu ball).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7bfcd711-a787-419b-9701-ce4df5a802a4'::uuid, 'Crunch (on stability ball)', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by sitting on a stability ball with your feet flat on the floor and your knees bent at a 90-degree angle.\r\n2. Walk your feet forward and lean back to position your lower and mid-back on the stability ball. Your upper body should be supported by the ball. Place your hands behind your head with your elbows pointing out to the sides.\r\n3. Engage your core and lift your shoulder blades upwards, curling your upper body towards your knees.\r\n4. Lower your shoulder blades back down with control, maintaining your core engagement. Repeat the movement for the desired number of repetitions.', E'1. Avoid pulling on your neck with your hands; focus on using your abdominal muscles to lift your shoulders.\r\n2.  Ensure your lower back remains in contact with the stability ball to avoid unnecessary strain.\r\n3. Breathe steadily throughout the exercise, exhaling as you lift your shoulders and inhaling as you lower them.', '{"image_male_start":"images/Abdominals/Crunch (on stability ball).jpeg","video_url":"videos/Abdominals/Crunch (on stability ball).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1ed32a2f-666c-4cc2-953f-41e7c50176ca'::uuid, 'Crunch (straight leg up)', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by lying flat on your back with your legs extended straight up towards the ceiling. Keep your feet together, and your arms extended straight above your chest.\r\n2. Engage your core and lift your shoulder blades off the floor, reaching your arms towards your toes.\r\n3. Hold the crunch position briefly, squeezing your abdominal muscles at the top.\r\n4. Lower your shoulder blades back to the floor with control, keeping your legs extended upward. Repeat the movement for the desired number of repetitions.', E'1. Avoid using your neck or momentum to lift your shoulders; focus on using your abdominal muscles.\r\n2. Use a mat or soft surface to support your back and prevent discomfort during the exercise.\r\n3. Breathe steadily throughout the exercise, exhaling as you lift your shoulders and inhaling as you lower them.\r\n4. Ensure your lower back remains pressed into the floor to avoid unnecessary strain.\r\n', '{"image_male_start":"images/Abdominals/Crunch (straight leg up).jpeg","video_url":"videos/Abdominals/Crunch (straight leg up).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('21a977bf-4cde-43ae-9e36-4f216d16454b'::uuid, 'Crunch floor', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by lying flat on your back with your knees bent and your feet flat on the floor, hip-width apart.\r\n2. Place your hands behind your head with your elbows pointing out to the sides.\r\n3. Engage your core and lift your shoulder blades off the floor, curling your upper body towards your knees.\r\n4. Lower your shoulder blades back to the floor with control, maintaining your core engagement. Repeat the movement for the desired number of repetitions.', E'1. Avoid pulling on your neck with your hands; focus on using your abdominal muscles to lift your shoulders.\r\n2. Perform the movement with control to maximize muscle activation and prevent injury.\r\n3. Breathe steadily throughout the exercise, exhaling as you lift your shoulders and inhaling as you lower them.\r\n4. Ensure your lower back remains pressed into the floor to avoid unnecessary strain.', '{"image_male_start":"images/Abdominals/Crunch Floor.jpeg","video_url":"videos/Abdominals/Crunch Floor.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e4797d9c-ae4f-4a49-a40d-108976e1f426'::uuid, 'Crunch frog on floor', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin seated on the floor, leaning back slightly. Your arms should be extended out to the sides at shoulder level, and your legs should be extended straight and parallel just above the floor.\r\n2. Engage your core to simultaneously bring both knees towards your chest while lightly crunching your upper body towards your knees.\r\n3. As you crunch, bring your arms together towards the sides of your knees.\r\n4. Extend your legs back out and open your arms back to the starting position with control. Repeat the movement for the desired number of repetitions.', E'1. Focus on using your abdominal muscles to lift your legs and upper body, avoiding excessive use of momentum.\r\n2. Ensure your lower back remains stable and avoid arching it during the movement.\r\n3. Breathe steadily throughout the exercise, exhaling as you crunch and inhaling as you extend back out.', '{"image_male_start":"images/Abdominals/Crunch Frog on Floor.jpeg","video_url":"videos/Abdominals/Crunch Frog on Floor.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('cb4f4207-dfc8-47d9-bb0b-7e56df8b892f'::uuid, 'Crunch leg raise', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by lying flat on your back with your knees bent and your feet just off the floor.\r\n2. Place your hands behind your head with your elbows pointing out to the sides.\r\n3. Engage your core and lift your shoulder blades off the floor while simultaneously lifting your legs slightly to bring your knees towards your head.\r\n4. Lower your back to the floor and your legs back to the starting position, keeping your feet just off the floor. Repeat the movement for the desired number of repetitions.', E'1. Avoid using your neck or momentum to lift your shoulders; focus on using your abdominal muscles.\r\n2. Use a mat or soft surface to support your back and prevent discomfort during the exercise.\r\n3. Breathe steadily throughout the exercise, exhaling as you lift your shoulders and knees, and inhaling as you lower them.', '{"image_male_start":"images/Abdominals/Crunch leg raise.jpeg","video_url":"videos/Abdominals/Crunch leg raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('245afc86-0afc-4730-8a85-4dbe8a8dc7c9'::uuid, 'Crunch with medicine ball', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your knees bent and feet flat on the floor, hip-width apart. Hold a medicine ball with both hands, keeping your arms extended straight above your chest.\r\n2. Lift your upper back off the floor by contracting your abdominal muscles.\r\n3. Raise the medicine ball towards the ceiling as you perform the crunch, keeping your arms straight. Pause for a moment at the top of the movement, squeezing your abs.\r\n4. Slowly lower your upper body back to the starting position, keeping control of the movement. Repeat for the desired number of repetitions.', E'1. Avoid using your neck muscles to lift your head; focus on using your abdominal muscles.\r\n2. Ensure your feet remain flat on the floor and your knees stay bent at a consistent angle.\r\n3. Keep the movement slow and controlled to maximize muscle engagement and prevent injury.\r\n4. Use a medicine ball with an appropriate weight that allows you to maintain proper form.\r\n', '{"image_male_start":"images/Abdominals/Crunch with Medicine Ball.jpeg","video_url":"videos/Abdominals/Crunch with Medicine Ball.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a43576b7-a47b-429e-9ebe-9f07ce5669ac'::uuid, 'Curtsy lunge bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by standing with your feet hip-width apart and your hands on your hips or by your sides.\r\n2. Step your right leg behind and across your left leg, bending both knees to lower into a curtsy lunge. Your front knee should be aligned with your front ankle.\r\n3. Push through your left heel to return to the starting position.\r\n4. Repeat the movement on the opposite side, stepping your left leg behind and across your right leg. Continue alternating sides for the desired number of repetitions.', E'1. Keep your torso upright throughout the exercise to maintain balance and proper form.\r\n2. Ensure your front knee does not extend beyond your toes to protect your knees from strain.\r\n3. Focus on pushing through your heel as you return to the starting position to engage your glutes.', '{"image_male_start":"images/Legs/curtsy lunge bodyweight  .jpg","video_url":"videos/Legs/curtsy lunge bodyweight  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d7c88d8d-1082-4fec-95ce-adafa2c2525b'::uuid, 'Curtsy lunge slide with towel', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by standing with your feet hip-width apart and place a towel under your right foot.\r\n2. Slide your right foot behind and across your left leg, bending both knees to lower into a curtsy lunge. Your front knee should be aligned with your front ankle.\r\n3. Push through your left heel to return to the starting position, sliding your right foot back to the original position.\r\n4. Complete the desired number of repetitions on one side, then switch the towel to the other foot and repeat the movement with the opposite leg.', E'1. Perform the movement with control to maximize muscle activation and prevent injury.\r\n2. Ensure your front knee does not extend beyond your toes to protect your knees from strain.\r\n3. Focus on pushing through your heel as you return to the starting position to engage your glutes.\r\n4. Use a smooth surface to ensure the towel slides easily and reduces friction.', '{"image_male_start":"images/Legs/Curtsy Lunge Slide with Towel.jpg","image_male_end":"images/Legs/Curtsy Lunge Slide with Towel1.jpg","video_url":"videos/Legs/Curtsy Lunge Slide with Towel.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('995f5eda-0c9a-45c9-b154-6553efab558e'::uuid, 'Curtsy lunges Resistance band', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart and place a resistance band under your left foot. Hold the handles of the band with both hands either at shoulder height or by your abdomane sides.\r\n2. Step your right leg behind and across your left leg, while bending both knees to lower into a lunge.\r\n3. Push through your left heel to return to the starting position, bringing your right leg back to the starting position.\r\n4. Repeat for the desired number of repetitions, then switch sides to work the other leg.', E'1. Keep your chest up and your back straight to maintain proper form.\r\n2. Perform the movement slowly and with control to maximize muscle activation and reduce injury risk.\r\n3. Exhale as you push back to the starting position and inhale as you lower into the lunge.', '{"image_male_start":"images/Legs/Curtsy lunges resistance band  .jpg","video_url":"videos/Legs/Curtsy lunges resistance band  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3736c97c-420c-4d9c-9972-6c03096203f1'::uuid, 'Curtsy squat', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by standing with your feet hip-width apart and your hands on your hips or by your sides.\r\n2. Step your right leg behind and across your left leg, bending both knees to lower into a curtsy squat. Your front knee should be aligned with your front ankle, and your back knee should point towards the floor.\r\n3. Push through your left heel to return to the starting position.\r\n4. Repeat the movement on the opposite side, stepping your left leg behind and across your right leg. Continue alternating sides for the desired number of repetitions.', E'1. Perform the movement with control to maximize muscle activation and prevent injury.\r\n2. Ensure your front knee does not extend beyond your toes to protect your knees from strain.\r\n3. Focus on pushing through your heel as you return to the starting position to engage your glutes.', '{"image_male_start":"images/Legs/Curtsy Squat.jpg","image_male_end":"images/Legs/Curtsy Squat1.jpg","video_url":"videos/Legs/Curtsy Squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('77937fca-37f6-4d5b-9f26-7591fb5e326e'::uuid, 'Dead bug', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by lying flat on your back with your arms extended straight up towards the ceiling and your legs lifted with your knees bent at a 90-degree angle.\r\n2. Engage your core and slowly lower your right arm and left leg towards the floor, keeping your back flat on the floor and not allowing it to arch.\r\n3. Return your right arm and left leg to the starting position.\r\n4. Repeat the movement with your left arm and right leg. Continue alternating sides for the desired number of repetitions.', E'1. Keep your core engaged throughout the exercise to maintain stability and support your lower back. \r\n2. Avoid letting your leg touch the floor; keep it just above the floor to maintain tension in your muscles.\r\n3. Ensure your lower back remains pressed into the floor to avoid unnecessary strain.\r\n', '{"image_male_start":"images/Yoga/Dead Bug.jpeg","video_url":"videos/Yoga/Dead Bug.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b79e3d10-f762-4cd7-90aa-e5b326d632fa'::uuid, 'Dead bug extended arms', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by lying flat on your back, right arm extended overhead on the floor in line with your torso and left arm extended by your side. Right knee bent close to your chest, while the left leg is bent and lightly extended away from your hips level, keeping both lower legs parallel to the floor.\r\n2. In a semi circular motion bring your right arm to your side while slowly extending your right leg to pass your hip level and simultaneously bring your left arm in a semi circular motion extended overhead on the floor in line with your torso and your left knee closer to your chest.\r\n3. Repeat the movement with the opposite arm and leg, lowering the arm extended by your side and the opposite leg. Continue alternating sides for the desired number of repetitions.', E'1. Breathe steadily throughout the exercise, exhaling as you lower your arm and leg and inhaling as you return to the starting position.\r\n2. Avoid letting your leg touch the floor; keep it just above the floor to maintain tension in your muscles.\r\n3. Use a mat or soft surface to support your back and prevent discomfort during the exercise.', '{"image_male_end":"images/Abdominals/Dead Bug Extended Arms.jpeg","video_url":"videos/Abdominals/Dead Bug Extended Arms.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('76f2ed53-628d-4861-8bdd-11d884e9d2d6'::uuid, 'Dead hang stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Begin by standing under a pull-up bar or a similar overhead bar.\r\n2. Reach up and grasp the bar with both hands, palms facing forward (overhand grip), and your hands shoulder-width apart.\r\n3. Allow your body to hang freely with your feet off the floor, keeping your arms fully extended and your shoulders relaxed.\r\n4. Hold this position for the desired duration, focusing on deep breathing and maintaining a relaxed grip.', E'1. Keep your shoulders relaxed and avoid shrugging them towards your ears.\r\n2. Focus on deep, steady breaths to enhance the stretch and promote relaxation.\r\n3. Use a bar that is high enough to allow your body to hang freely without touching the floor.\r\n4. If you find it challenging to maintain the grip, use chalk to prevent slipping.\r\n5. Ensure the bar and your grip are secure to avoid any accidents during the stretch.', '{"image_male_start":"images/Stretching - Mobility/dead hang stretch.jpg","image_male_end":"images/Stretching - Mobility/dead hang stretch1.jpg","video_url":"videos/Stretching - Mobility/dead hang stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('825d7cc3-eef1-47bb-89a3-484890390ded'::uuid, 'Decline bench full sit up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by lying on a decline bench with your feet secured under the footpads.\r\n2. Place your hands behind your head with your elbows pointing out to the sides.\r\n3. Engage your core and lift your upper body towards your knees and stop until a few inches away.\r\n4. Lower your upper body back to the starting position with control. Repeat the movement for the desired number of repetitions.', E'1. Avoid pulling on your neck with your hands; focus on using your abdominal muscles to lift your shoulders.\r\n2. Perform the movement with control to maximize muscle activation and prevent injury.\r\n3. Breathe steadily throughout the exercise, exhaling as you lift your shoulders and inhaling as you lower them.', '{"video_url":"videos/Abdominals/Decline Bench Full Sit up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2970db0a-b591-43d1-bb6f-43718ed71e72'::uuid, 'Decline bench oblique crunches', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Secure your feet at the end of a decline bench, lie back with your knees slightly bent, and cross your hands close to your chest.\r\n2. Engage your core and lift your upper body off the bench while twisting your torso to the right.\r\n3. Squeeze your obliques at the top of the movement, ensuring that the contraction is felt along the side of your abdomen.\r\n4. Slowly lower your upper body back to the starting position and repeat the movement, this time twisting your torso to the left. Continue alternating sides for the desired number of repetitions.', E'1. Breathe out as you twist and crunch, and breathe in as you return to the starting position.\r\n2. Ensure your lower back stays in contact with the bench to support your spine.\r\n3. Keep your feet securely anchored to the bench to stabilize your body throughout the exercise.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5aa601d2-4f01-42c1-9d69-668b32112cd6'::uuid, 'Decline bench oblique crunches bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by lying on a decline bench with your feet secured under the footpads. Position yourself so that your hips are at the edge of the bench.\r\n2. Place your hands behind your head or crossed on your chest with your elbows pointing out to the sides.\r\n3. Engage your core and lift your upper body towards your right knee, twisting your torso to engage your oblique muscles.\r\n4. Lower your upper body back to the starting position with control and then lift your upper body towards your left knee. Continue alternating sides for the desired number of repetitions.', E'1. Keep your core engaged throughout the exercise to maintain stability and support your lower back.\r\n2. Avoid pulling on your neck with your hands; focus on using your abdominal and oblique muscles to lift your shoulders.\r\n3. Perform the movement with control to maximize muscle activation and prevent injury.', '{"image_male_start":"images/Abdominals/decline bench oblique crunches bodyweight.jpeg","video_url":"videos/Abdominals/decline bench oblique crunches bodyweight .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ba0b1745-4803-48a8-a266-a6797de48d1e'::uuid, 'Decline bench oblique crunches dumbbells', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Secure your feet at the end of a decline bench and lie back with your knees slightly bent. Hold a dumbbell in each hand close to your chest.\r\n2. Engage your core and lift your upper body off the bench by contracting your abdominal muscles, while simultaneously twisting your torso to the right.\r\n3. Squeeze your obliques at the top of the movement, ensuring that the contraction is felt along the side of your abdomen.\r\n4. Slowly lower your upper body back to the starting position and repeat the movement, this time twisting your torso to the left. Continue alternating sides for the desired number of repetitions.', E'1. Breathe out as you twist and crunch, and breathe in as you return to the starting position.\r\n2. Ensure your lower back stays in contact with the bench to support your spine.\r\n3. Use a weight that challenges you but allows you to maintain proper form.\r\n4. Keep your feet securely anchored to the bench to stabilize your body throughout the exercise.', '{"image_male_start":"images/Abdominals/decline bench oblique crunches dumbbells.jpeg","video_url":"videos/Abdominals/decline bench oblique crunches dumbbells .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('05296839-cf3c-4b6c-816d-0cc1481b9f6a'::uuid, 'Decline bent leg reverse crunch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by lying on a decline bench with your head at the higher end and place your hands on the side edges of the bench for stability. Bend your knees at 90 degrees and lift your legs so your thighs are perpendicular to the bench and your lower legs are parallel to the floor.\r\n2. Engage your core and lift your hips off the bench, curling your knees towards your chest while keeping both legs bent.\r\n3. Lower your hips back to the starting position with control, keeping your knees bent at 90 degrees. Repeat the movement for the desired number of repetitions.', E'1. Keep your core engaged throughout the exercise to maintain stability and support your lower back.\r\n2. Avoid using momentum to lift your hips; focus on using your abdominal muscles for the movement.\r\n3. Breathe steadily throughout the exercise, exhaling as you lift your hips and inhaling as you lower them.\r\n', '{"image_male_start":"images/Abdominals/Decline Bent Leg Reverse Crunch.jpeg","video_url":"videos/Abdominals/Decline Bent Leg Reverse Crunch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ac410a19-3924-40c4-a398-fe95e82e6b8d'::uuid, 'Decline chair push up diamond', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '353a86d0-9f31-40d3-bfba-969ae615da15'::uuid, E'1. Begin by placing your feet on a chair and positioning your hands on the floor close together, forming a diamond shape with your thumbs and index fingers.\r\n2. Engage your core and ensure your body forms a straight line from your head to your heels.\r\n3. Lower your chest towards your hands by bending your elbows, keeping them close to your body.\r\n4. Push through your hands to return to the starting position, straightening your arms. Repeat the movement for the desired number of repetitions.', E'1. Keep your core engaged throughout the exercise to maintain a straight body line and avoid sagging your hips.\r\n2. Ensure your hands are positioned directly under your chest when you lower yourself.\r\n3. Use a stable chair or bench to prevent any movement or slipping during the exercise.\r\n4. Breathe steadily throughout the exercise, exhaling as you push up and inhaling as you lower down.\r\n5. Avoid flaring your elbows out to the sides; keep them close to your body to engage your triceps more effectively.', '{"image_male_start":"images/Triceps/decline chair push up diamond.jpeg","video_url":"videos/Triceps/decline chair push up diamond  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b216b222-e3fe-4306-9700-b8deef02231c'::uuid, 'Decline diamond pike push-up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by placing your feet on a bench and positioning your hands on the floor close together, forming a diamond shape with your thumbs and index fingers. Hips raised towards the ceiling.\r\n2. Engage your core and ensure your body forms an inverted V shape with your legs and torso.\r\n3. Lower your head towards your hands by bending your elbows, keeping them close to your body.\r\n4. Push through your hands to return to the starting position, straightening your arms. Repeat the movement for the desired number of repetitions.', E'1. Keep your core engaged throughout the exercise to maintain stability and control.\r\n2. Ensure your hips stay raised and your legs remain straight to maintain the pike position.\r\n3. Perform the movement with control to maximize muscle activation and prevent injury.\r\n4. Breathe steadily throughout the exercise, exhaling as you push up and inhaling as you lower down.', '{"image_male_start":"images/Triceps/Decline Diamond Pike Push-up.jpeg","video_url":"videos/Triceps/Decline Diamond Pike Push-up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('bb3236b2-11c8-4317-a393-b488824bca94'::uuid, 'Decline kneeling push up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by placing your knees on a step up and position your hands on the floor shoulder-width apart.\r\n2. Engage your chest and ensure your body forms a straight line from your head to your knees.\r\n3. Lower your chest towards the floor by bending your elbows, keeping them at a 45-degree angle to your body.\r\n4. Push through your hands to return to the starting position, straightening your arms. Repeat the movement for the desired number of repetitions.', E'1. Avoid flaring your elbows out to the sides; keep them at a 45-degree angle to engage your chest and triceps more effectively.\r\n2. Perform the movement with control to maximize muscle activation and prevent injury.\r\n3. Breathe steadily throughout the exercise, exhaling as you push up and inhaling as you lower down.', '{"image_male_start":"images/Chest/Decline kneeling push up.jpg","image_male_end":"images/Chest/Decline kneeling push up1.jpg","video_url":"videos/Chest/Decline kneeling push up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2b7e2040-d3bb-40a5-b3f3-48bd3ca8a232'::uuid, 'Decline kneeling push up on box', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by placing your knees on a box and position your hands on the floor shoulder-width apart.\r\n2. Engage your chest and ensure your body forms a straight line from your head to your knees.\r\n3. Lower your chest towards the floor by bending your elbows, keeping them at a 45-degree angle to your body.\r\n4. Push through your hands to return to the starting position, straightening your arms. Repeat the movement for the desired number of repetitions.', E'1. Avoid flaring your elbows out to the sides; keep them at a 45-degree angle to engage your chest and triceps more effectively.\r\n2. Perform the movement with control to maximize muscle activation and prevent injury.\r\n3. Breathe steadily throughout the exercise, exhaling as you push up and inhaling as you lower down.', '{"image_male_start":"images/Chest/Decline Kneeling Push Up on Box.jpg","image_male_end":"images/Chest/Decline Kneeling Push Up on Box1.jpg","video_url":"videos/Chest/Decline Kneeling Push Up on Box.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4a5de442-eda4-4435-8507-975badebf969'::uuid, 'Decline levitating sit ups bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by lying on a decline bench with your feet secured under the footpads. Position your torso so it is parallel to the floor, ''levitating'' off the bench.\r\n2. Place your hands behind your head with your elbows pointing out to the sides.\r\n3. Engage your core and lift your upper body towards your knees, keeping your back straight and avoiding pulling on your neck.\r\n4. Lower your upper body back to the starting position with control, maintaining the parallel position. Repeat the movement for the desired number of repetitions.', E'1. Breathe steadily throughout the exercise, exhaling as you lift your shoulders and inhaling as you lower them.\r\n2. Ensure your lower back remains off the bench and parallel to the floor to engage your core muscles effectively.\r\n3. Use a stable decline bench to prevent any movement or slipping during the exercise.', '{"video_url":"videos/Abdominals/decline levitating sit ups bodyweight.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5aa5acce-4a6c-4db8-8684-d8643df61ee7'::uuid, 'Decline push up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by placing your feet on a bench and position your hands on the floor shoulder-width apart.\r\n2. Engage your core and ensure your body forms a straight line from your head to your heels.\r\n3. Lower your chest towards the floor by bending your elbows, keeping them at a 45-degree angle to your body.\r\n4. Push through your hands to return to the starting position, straightening your arms. Repeat the movement for the desired number of repetitions.', E'1. Keep your core engaged throughout the exercise to maintain a straight body line and avoid sagging your hips.\r\n2. Use a stable chair or bench to prevent any movement or slipping during the exercise.\r\n3. Perform the movement with control to maximize muscle activation and prevent injury.', '{"image_male_start":"images/Chest/decline push up.jpg","image_male_end":"images/Chest/decline push up1.jpg","video_url":"videos/Chest/decline push up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6c7373ca-046a-4dd3-9512-7242a6d35cd2'::uuid, 'Decline push up against wall', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by placing your feet against a wall and positioning your hands on the floor shoulder-width apart. Your body should be in a decline position with your feet elevated on the wall.\r\n2. Engage your core and ensure your body forms a straight line from your head to your feet.\r\n3. Lower your chest towards the floor by bending your elbows, keeping them at a 45-degree angle to your body.\r\n4. Push through your hands to return to the starting position, straightening your arms. Repeat the movement for the desired number of repetitions.', E'1. Ensure your hands are positioned directly under your shoulders when you lower yourself.\r\n2. Perform the movement with control to maximize muscle activation and prevent injury.\r\n3. Breathe steadily throughout the exercise, exhaling as you push up and inhaling as you lower down.\r\n4. Use a stable wall to ensure your feet remain securely in place throughout the exercise.\r\n', '{"image_male_start":"images/Chest/Decline Push Up against Wall.jpg","image_male_end":"images/Chest/Decline Push Up against Wall1.jpg","video_url":"videos/Chest/Decline Push Up against Wall.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('68a3d112-7521-461b-983b-3b8e6afc6636'::uuid, 'Decline shoulder tap', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by placing your feet on a bench and positioning your hands on the floor shoulder-width apart. Your body should be in a decline position with your feet elevated.\r\n2. Engage your core and ensure your body forms a straight line from your head to your heels.\r\n3. Lift your right hand off the floor and tap your left shoulder, lightly rotate your hips according to the tap side.\r\n4. Return your right hand to the floor and repeat the movement with your left hand, tapping your right shoulder. Continue alternating for the desired number of repetitions.', E'1. Keep your core engaged throughout the exercise to maintain a straight body line and avoid sagging your hips.\r\n2. Avoid letting your shoulders sag; keep them stable and aligned with your hands.\r\n3. Use a stable bench to prevent any movement or slipping during the exercise.\r\n', '{"image_male_start":"images/Calisthenics-Cardio-Functional/decline shoulder tap.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/decline shoulder tap1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/decline shoulder tap.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('db9373a4-944c-4f55-8fde-fd0105679af0'::uuid, 'Decline sit up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by lying on a decline bench with your feet secured under the footpads. Position yourself so that your hips are at the edge of the bench.\r\n2. Place your hands behind your head with your elbows pointing out to the sides.\r\n3. Engage your core and lift your upper body towards your knees until your torso forms a 90 degree angle with your thighs, keeping your back as straight as possible.\r\n4. Lower your upper body back to the starting position with control. Repeat the movement for the desired number of repetitions.', E'1. Keep your core engaged throughout the exercise to maintain stability and support your lower back.\r\n2. Avoid pulling on your neck with your hands; focus on using your abdominal muscles to lift your shoulders.\r\n3. Breathe steadily throughout the exercise, exhaling as you lift your shoulders and inhaling as you lower them.', '{"image_male_start":"images/Abdominals/decline sit up.jpeg","video_url":"videos/Abdominals/decline sit up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3a448e38-949f-4863-9d94-8c84b8cd83bc'::uuid, 'Decline sit ups dumbbells', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Secure your feet at the end of a decline bench and lie back with your knees slightly bent. Hold a dumbbell in each hand close to your chest.\r\n2. Engage your core and lift your upper body off the bench by contracting your abdominal muscles.\r\n3. Continue to lift your upper body until you are in a seated position, ensuring that the contraction is felt in your abs.\r\n4. Slowly lower your upper body back to the starting position with control, keeping your core engaged. Repeat for the desired number of repetitions.', E'1. Focus on using your abdominal muscles to lift your body, rather than relying on momentum.\r\n2. Breathe out as you sit up and breathe in as you return to the starting position.\r\n3. Keep your feet securely anchored to the bench to stabilize your body throughout the exercise.\r\n', '{"image_male_start":"images/Abdominals/decline sit ups dumbbells.jpeg","video_url":"videos/Abdominals/decline sit ups dumbbells .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('46549f16-88f9-488c-a091-3a073b4443d8'::uuid, 'Deep push-up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a plank position with your hands holding dumbbells on the floor, slightly wider than shoulder-width apart. Your feet should be on the floor, forming a straight line from your head to your heels.\r\n2. Engage your core and ensure your body forms a straight line from your head to your heels.\r\n3. Lower your chest towards the floor by bending your elbows, allowing your chest to go deeper than your hands.\r\n4. Push through your hands to return to the starting position, straightening your arms. Repeat the movement for the desired number of repetitions.', E'1. Keep your core engaged throughout the exercise to maintain a straight body line and avoid sagging your hips.\r\n2. Breathe steadily throughout the exercise, exhaling as you push up and inhaling as you lower down.\r\n3. Perform the movement with control to maximize muscle activation and prevent injury.\r\n', '{"image_male_start":"images/Chest/Deep Push-Up.jpg","image_male_end":"images/Chest/Deep Push-Up1.jpg","video_url":"videos/Chest/Deep Push-Up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('eb0a0962-db0b-42a4-9388-943a8dc1fc6a'::uuid, 'Diagonal chop cable', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Anchor one end of the band at chest height. Stand with your right side facing the anchor point, with your feet shoulder-width apart, and grasp the handle with both hands. Extend your arms to hold the handle opposite your chest.\r\n2. Pull the handle down and diagonally across your body, twisting your torso and pivoting your back foot to follow through. Bring the handle down towards the left side.\r\n3. Slowly return to the starting position with control. \r\n4. Repeat for the desired number of repetitions, then switch sides to work in the opposite direction', E'1. Perform the movement slowly and with control to maximize muscle activation and reduce injury risk.\r\n2. Exhale as you pull the handle down and across your body, and inhale as you return to the starting position.\r\n3. Use a lighter weight if needed to ensure proper form and gradually increase the resistance as you get stronger.', '{"image_male_start":"images/Abdominals/diagonal chop cable.jpeg","video_url":"videos/Abdominals/diagonal chop cable .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('bee268a2-90e1-42bf-824d-8018b58a192c'::uuid, 'Diagonal chop left', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start standing with your feet shoulder-width apart, clasping your hands together and holding them extended opposite your chest.\r\n2. Rotate your torso and simultaneously bring your hands diagonally across your body towards your left hip, bending your knees slightly as you turn.\r\n3. Keep your arms extended and pivot your right foot as you rotate to protect your knee from strain.\r\n4. Return to the starting position in a controlled manner, bringing your hands back opposite your chest.', E'1. Engage your core throughout the movement to stabilize your spine and enhance power.\r\n2. Pivot on your feet during the rotation to ensure a full range of motion and to reduce stress on your knees.\r\n3. Focus on exhaling as you chop down and inhaling as you return to the starting position.\r\n4. Maintain a slight bend in your knees throughout the exercise to aid in balance and prevent strain on your joints.', '{"image_male_start":"images/Abdominals/diagonal chop left.jpeg","video_url":"videos/Abdominals/diagonal chop left .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('35c2def7-1c95-4b12-b720-f16981355cbf'::uuid, 'Diagonal chop right', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start standing with your feet shoulder-width apart, clasping your hands together and holding them extended oposite your chest.\r\n2. Rotate your torso and simultaneously bring your hands diagonally across your body towards your right hip, bending your knees slightly as you turn.\r\n3. Keep your arms extended and pivot your right foot as you rotate to protect your knee from strain.\r\n4. Return to the starting position in a controlled manner, bringing your hands back opposite your chest.', E'1. Engage your core throughout the movement to stabilize your spine and enhance power.\r\n2. Pivot on your feet during the rotation to ensure a full range of motion and to reduce stress on your knees.\r\n3. Focus on exhaling as you chop down and inhaling as you return to the starting position.\r\n4. Maintain a slight bend in your knees throughout the exercise to aid in balance and prevent strain on your joints.', '{"image_male_start":"images/Abdominals/diagonal chop right.jpeg","video_url":"videos/Abdominals/diagonal chop right .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3b1b2da3-2dbc-411a-af1e-550fe75012c3'::uuid, 'Diagonal lunge', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet together, arms extended outwards at shoulder level.\r\n2. Step diagonally forward with your right foot, planting it at a 45-degree angle. As you lower into a lunge, rotate your torso to the right and lean down to touch your right foot with your left hand, keeping your left leg straight.\r\n3. Press through your right heel and rotate back to center as you return to the starting position.\r\n4. Repeat the movement with your left leg, stepping diagonally forward, rotating left, and touching your left foot with your right hand.\r\n', E'1. Maintain your arms extended at shoulder level throughout the exercise to help with balance and increase the workout intensity.\r\n2. Rotate your torso smoothly and keep your movements controlled to avoid any jerky motions that might cause injury.\r\n3. Ensure that your lunging knee does not extend past your toes to protect your knee joint.', '{"image_male_start":"images/Legs/Diagonal Lunge.jpg","image_male_end":"images/Legs/Diagonal Lunge1.jpg","video_url":"videos/Legs/Diagonal Lunge.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('df0a3184-507b-44fa-be33-c9728fea2fb0'::uuid, 'Diagonal opens', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, arms bent at the elbows, elbows facing outwards, and hands close to your chest.\r\n2. Slide your right hand over your left forearm, both arms in an opposite diagonal direction while keeping the elbows bent.\r\n3. Return your hands to the starting position and repeat the movement by sliding your left hand over your right forearm, extending in the opposite diagonal direction.', E'1. Ensure your movements are smooth and controlled to maintain tension and focus on muscle engagement.\r\n2. Focus on maintaining a rhythmic breathing pattern, inhaling as you extend and exhaling as you return to the start position.\r\n3. Maintain a slight tension in your core throughout the exercise to help stabilize your upper body.\r\n', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Diagonal Opens.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Diagonal Opens1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Diagonal Opens.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b15aa597-dbfa-4771-b162-49e7b73a7ba8'::uuid, 'Diagonal punch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, knees slightly bent, and hands in a guard position near your face.\r\n2. Rotate your torso to the right, and extend your right arm in a diagonal punch across your body.\r\n3. Return your right hand to the starting position as you rotate your torso back to center.\r\n4. Repeat the motion with your left arm, rotating your torso to the left to execute a diagonal punch across your body.', E'1. Keep your hands up and elbows slightly bent when not punching to protect your face and maintain balance.\r\n2. Rotate your hips and shoulders fully with each punch to maximize power and engage your core muscles.\r\n3. Practice the punches slowly at first to ensure proper technique before increasing speed and power.\r\n4. Exhale sharply with each punch to increase force and stabilize your core.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Diagonal Punch.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Diagonal Punch1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Diagonal Punch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e7fba936-f1f3-4c46-bb67-f33b06a04c75'::uuid, 'Diamond push up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a plank position with your hands close together under your chest, fingers forming a diamond shape (thumbs and index fingers touching).\r\n2. Lower your body towards the floor, keeping your elbows close to your body and your back straight.\r\n3. Pause briefly as your chest nearly touches your hands.\r\n4. Push back up to the starting plank position, maintaining a straight line from your head to your heels throughout the movement.', E'1. Ensure your elbows do not flare out; they should stay close to your body to maximize triceps engagement.\r\n2. Control your descent and ascent to increase muscle tension and enhance strength gains.\r\n3. Breathe in as you lower down and exhale forcefully as you push back up to help power the movement.\r\n4. Keep your head in a neutral position, aligned with your spine, to avoid neck strain.\r\n5. Perform the push-up at a slow to moderate pace to focus on form and muscle engagement without rushing.', '{"image_male_start":"images/Triceps/diamond push up.jpeg","video_url":"videos/Triceps/diamond push up  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b942d25d-1f00-49c1-a5aa-8111fd3af7dc'::uuid, 'Diamond push-up (on knees)', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by kneeling on a mat with your hands close together under your chest on the floor, fingers forming a diamond shape (thumbs and index fingers touching).\r\n2. Lean forward to shift your weight onto your hands while keeping your back straight and your core engaged.\r\n3. Lower your chest towards the floor by bending your elbows, keeping them close to your body.\r\n4. Press through your hands to lift your body back up to the starting position, maintaining the alignment of your spine throughout the movement.', E'1. Ensure your elbows point back rather than flaring out to the sides to maximize triceps activation and minimize shoulder strain.\r\n2. Keep your head and neck in a neutral position, aligned with your spine, to avoid any unnecessary strain.\r\n3. Breathe in as you lower yourself and exhale as you push back up, using your breath to help power the movement.', '{"image_male_start":"images/Triceps/Diamond Push-up (on knees).jpeg","video_url":"videos/Triceps/Diamond Push-up (on knees).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ecc894d0-f2ab-40bd-920e-516ed07d7d60'::uuid, 'Dip leg raise on couch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '0bcb2d29-e147-4deb-9a19-924da5ff89b3'::uuid, E'1. Sit on the edge of a couch with your hands placed next to your hips, gripping the edge for support.\r\n2. Lift your hips off the couch by pressing down into your hands and straightening your arms, while keeping your feet flat on the floor and both knees bent.\r\n3. As you bend your elbows to lower your body into a dip, simultaneously lift one leg, bent at the knee, towards your chest.\r\n4. Push through your hands to raise your body back up, straightening your arms and simultaneously lowering your lifted leg back to the starting position.', E'1. Ensure your grip on the couch is secure to maintain balance and control throughout the exercise.\r\n2. Focus on a controlled, smooth motion both when lowering into the dip and lifting your body up to maximize muscle engagement.\r\n3. Keep the movement of your arms and legs coordinated; as you push up, lower the leg, and vice versa. ', '{"image_male_start":"images/Triceps/Dip Leg Raise on couch.jpeg","video_url":"videos/Triceps/Dip Leg Raise on couch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9f5fea72-7ce8-413d-b1bb-91c0a267ef9f'::uuid, 'Dip on floor with chair', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '353a86d0-9f31-40d3-bfba-969ae615da15'::uuid, E'1. Sit on the floor with your back facing a chair and place your hands on the edge of the chair seat, fingers pointing towards your body.\r\n2. Bend your knees in front of you with your heels resting on the floor.\r\n3. Press down into the chair with your hands to lift your hips off the floor, straightening your arms.\r\n4. Bend your elbows to lower your body towards the floor until your elbows form about a 90-degree angle and push through your hands to lift your body back up to the starting position.', E'1. Ensure your hands are firmly placed on the chair and your fingers are well-aligned for a strong grip.\r\n2. Keep your movements controlled and steady to engage the triceps effectively and avoid any jerky movements.\r\n3. Avoid dipping too low to prevent shoulder strain; stopping at a 90-degree elbow angle is generally safe and effective.\r\n', '{"image_male_start":"images/Triceps/Dip on Floor with Chair.jpeg","video_url":"videos/Triceps/Dip on Floor with Chair.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ddbb4dd0-45ce-416d-8307-c8592a654e25'::uuid, 'Dips between chairs', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '353a86d0-9f31-40d3-bfba-969ae615da15'::uuid, E'1. Position two chairs parallel to each other, slightly wider than shoulder-width apart, with the seats facing away from you.\r\n2. Stand between the chairs and grasp the top of each chair back with your hands.\r\n3. Lift your body off the floor by straightening your arms, supporting your weight through your hands.\r\n4. Slowly lower your body by bending your elbows until they form about a 90-degree angle, keeping your body upright and close to the chair backs. Press through your hands to raise your body back to the starting position, extending your arms fully.', E'1. Check that the chairs are stable and strong enough to support your weight without tipping or moving.\r\n2. Keep your movements controlled and steady, focusing on using your triceps to lift and lower your body.\r\n3. Avoid locking your elbows at the top of the movement to keep tension on the muscles and protect your joints.', '{"image_male_start":"images/Triceps/Dips between Chairs.jpeg","video_url":"videos/Triceps/Dips between Chairs.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('108869b9-720f-4b2a-b27b-c7a91ed0ff16'::uuid, 'Donkey calf raise', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand on the edge of a step with your heels hanging off, placing your forefeet securely on the step.\r\n2. Lean forward and reach down to hold onto a bench in front of you for stability, keeping your back straight and hips aligned with your feet.\r\n3. Press down through your forefeet to elevate your heels as high as possible, fully contracting your calf muscles.\r\n4. Slowly lower your heels below the level of the step to maximize the stretch in your calves before the next lift.', E'1. Ensure your grip on the bench is secure to maintain balance and focus the effort on your calves.\r\n2. Keep your back flat and avoid rounding your shoulders to prevent unnecessary strain on your back.\r\n3. Emphasize the upward and downward movements equally to enhance muscle growth and strength in your calves.\r\n4. Maintain a slow, controlled pace to increase the intensity of the muscle contraction and effectiveness of the exercise.', '{"image_male_start":"images/Legs/Donkey Calf Raise.jpg","image_male_end":"images/Legs/Donkey Calf Raise1.jpg","video_url":"videos/Legs/Donkey Calf Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6a5479e1-418b-4338-b54e-14f20eddde4c'::uuid, 'Donkey kicks bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin on all fours in a tabletop position with your knees hip-width apart on the floor, hands under your shoulders, and your back flat.\r\n2. Keeping your knee bent at a 90-degree angle, lift your right leg up towards the ceiling, driving your heel upward as if pushing against the sky.\r\n3. Push your leg up until your thigh is in line with your body and your foot is above your knee.\r\n4. Lower your leg slowly back to the starting position without letting your knee touch the floor. Repeat the movement for the desired number of repetitions before switching to the left leg.', E'1. Ensure your movements are controlled and deliberate to maximize glute activation and minimize momentum.\r\n2. Keep your neck and spine in a neutral position by gazing down at the floor.\r\n3. Avoid swinging your leg or using jerky movements; the power should come from your glutes and not from momentum.\r\n', '{"image_male_start":"images/Legs/Donkey kicks bodyweight.jpg","image_male_end":"images/Legs/Donkey kicks bodyweight1.jpg","video_url":"videos/Legs/Donkey kicks bodyweight.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('19593860-6430-441c-aa24-daa46124608b'::uuid, 'Doorway biceps curl', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand in a doorway and grip the sides of the door frame at about hip height, palms facing forward or slightly inward depending on comfort and doorway design.\r\n2. Step forward with one foot to create tension in your arms and lean slightly back, so your body weight helps create resistance.\r\n3. Curl your elbows to raise your body slowly towards the door frame, keeping your elbows pinned at your sides.\r\n4. Slowly extend your arms back to the starting position, repeat the movement.', E'1. Ensure your grip is firm and your hands are positioned comfortably to avoid strain on your wrists.\r\n2. Keep your body straight and avoid swinging; the motion should come solely from your biceps.\r\n3. Adjust the position of your feet to increase or decrease resistance—the further you step and lean back, the harder the curl.', '{"image_male_start":"images/Biceps/Doorway Biceps Curl.jpeg","video_url":"videos/Biceps/Doorway Biceps Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('41db104c-0070-45b7-8763-d373a11df60b'::uuid, 'Double jump squat', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your hands close together in front of your torso. Lower into a squat position by bending your knees and hips, keeping your chest up and your weight in your heels. Stand back up to the starting position.\r\n2. Immediately lower into a squat again and then explosively jump up from the squat.\r\n3. Land softly on your feet after the jump, repeat the sequence.', E'1. Keep your chest up and back straight throughout the movement to maintain proper form and avoid injury.\r\n2. Perform the jumps in a fluid motion, transitioning smoothly between the squats and jumps.\r\n3. Focus on landing softly to reduce impact on your joints.', '{"image_male_start":"images/Legs/Double Jump Squat.jpg","image_male_end":"images/Legs/Double Jump Squat1.jpg","video_url":"videos/Legs/Double Jump Squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5515d4a7-2442-4c1a-ba57-b8bf2dd68c86'::uuid, 'Double knee drive', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, both arms bent and raised by your sides.\r\n2. Lift your right knee towards your chest while rotating your torso to the right, bringing your left elbow to touch your right knee twice.\r\n3. Lower your right leg back to the starting position and return your torso to face forward.\r\n4. Repeat the movement on the opposite side by lifting your left knee towards your chest, rotating your torso to the left, and bringing your right elbow to touch your left knee twice. Continue alternating sides.', E'1. Keep your upper body upright and avoid leaning too far forward or backward to maintain balance and proper form.\r\n2. Engage your core muscles to stabilize your body and enhance the rotational movement.\r\n3. Focus on a steady, rhythmic breathing pattern, exhaling as you bring your knee and elbow together. ', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Double Knee Drive.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Double Knee Drive1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Double Knee Drive.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('eb934a25-8118-4edf-a2ec-d5e43ec290b7'::uuid, 'Double punch front leg lift', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your hands in fists near your sides with cloesd fists.\r\n2. Simultaneously punch forward with both arms while lifting your right leg slightly bent at the knee to about waist height.\r\n3. Return your arms and right leg to the starting position.\r\n4. Immediately repeat the movement, this time lifting your left leg while simultaneously punching forward with both arms. Continue alternating leg lifts with each set of punches.', E'1. Ensure your punches are strong and controlled, extending fully without locking your elbows.\r\n2. Maintain a slight bend in the lifted leg to reduce strain and enhance control during the movement.\r\n3. Focus on a steady, rhythmic breathing pattern, exhaling as you punch and lift your leg, and inhaling as you return to the starting position.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Double Punch Front Leg Lift.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Double Punch Front Leg Lift1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Double Punch Front Leg Lift.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('11107f26-1c14-4697-a595-fbe4a06afd2d'::uuid, 'Downward dog sprint', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Get down on your fours and raise your hips while keeping your arms and legs straight to form an inverted V-shape.\r\n2. Raise and lower your feet alternately as if you are sprinting.\r\n3. Continue for a suitable duration.', NULL, '{"image_male_start":"images/Calisthenics-Cardio-Functional/Downward Dog Sprint.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Downward Dog Sprint1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Downward Dog Sprint.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7f913faf-e027-4b4e-bde1-eba3366f60e0'::uuid, 'Drag curl dumbbell', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an underhand grip (palms facing up). Let your arms hang straight down by your sides.\r\n2. Begin by dragging the dumbbells upward along your torso by bending your elbows and pulling them back, as if you are zipping up your jacket.\r\n3. Continue lifting the dumbbells until they reach chest height, focusing on squeezing your biceps at the top of the movement.\r\n4. Slowly lower the dumbbells back to the starting position, maintaining control throughout the descent. Repeat for the desired number of repetitions.', E'1. Focus on the mind-muscle connection, feeling the contraction in your biceps throughout the movement.\r\n2. Use a weight that allows you to perform the exercise with proper form without straining.\r\n3. Avoid using momentum; perform the exercise in a slow and controlled manner.', '{"image_male_start":"images/Biceps/drag curl dumbbell.jpeg","video_url":"videos/Biceps/drag curl dumbbell.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0c6a1570-3e53-4370-a833-34123236b3bd'::uuid, 'Drag curl Resistance band', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart and place a resistance band under your feet. Hold the handles of the band with both hands, palms facing forward.\r\n2. Keep your elbows close to your body and your back straight. Start with your arms fully extended down at your sides.\r\n3. Curl the handles up by dragging your elbows along your torso, keeping them close to your torso, until your hands reach chest level.\r\n4. Slowly lower the handles back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you curl the handles up and inhale as you lower them back down.\r\n2. Use a lighter resistance band if needed to ensure proper form and gradually increase the resistance as you get stronger.\r\n3. Focus on engaging your biceps throughout the movement.', '{"image_male_start":"images/Biceps/drag curl resistance band.jpeg","video_url":"videos/Biceps/drag curl resistance band .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('57971c27-fb97-493d-8a1a-93b57c130704'::uuid, 'Dumbbell ab crunch', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie on your back with your knees bent and feet flat on the floor, hip-width apart. Hold a dumbbell with both hands striaght over your chest.\r\n2. Lift your head, shoulders, and upper back off the floor by contracting your abdominal muscles.\r\n3. Raise the dumbbell towards the ceiling as you perform the crunch, keeping your arms straight. Pause for a moment at the top of the movement, squeezing your abs.\r\n4. Slowly lower your upper body back to the starting position, keeping control of the movement. Repeat for the desired number of repetitions.', E'1. Keep your lower back pressed against the floor throughout the exercise to avoid straining it.\r\n2. Avoid using your neck muscles to lift your head; focus on using your abdominal muscles.\r\n3. Breathe out as you lift your upper body and breathe in as you lower it.', '{"video_url":"videos/Abdominals/dumbbell ab crunch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4ee75a6c-0580-4900-a636-0368a9e6e117'::uuid, 'Dumbbell Alternate Bench Press (high start)', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie on a flat bench with your feet flat on the floor and a dumbbell in each hand. Start with both arms extended straight up over your chest, palms facing forward.\r\n2. Lower the right dumbbell towards your chest by bending your elbow while keeping the left arm extended and stable.\r\n3. Press the right dumbbell back to the starting position by extending your elbow and contracting your chest muscles.\r\n4. Repeat the movement with the left arm while keeping the right arm extended and stable. Continue alternating arms for the desired number of repetitions.', E'1. Lower the dumbbell in a controlled manner to avoid using momentum.\r\n2. Breathe out as you press the dumbbell up and breathe in as you lower it down.\r\n3. Ensure your feet remain flat on the floor to maintain stability.', '{"image_male_start":"images/Chest/Dumbbell Alternate Bench Press (high start).jpg","image_male_end":"images/Chest/Dumbbell Alternate Bench Press (high start)1.jpg","video_url":"videos/Chest/Dumbbell Alternate Bench Press (high start).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c23a1967-8453-4be1-9322-414e0ef1862a'::uuid, 'Dumbbell Alternate Biceps Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your arms fully extended by your sides and palms facing inwards.\r\n2. Keep your elbows close to your torso and curl the right dumbbell towards your shoulder by contracting your biceps. Rotate your forearm as you lift the dumbbell so that your palm faces your shoulder at the top of the movement.\r\n3. Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back to the starting position.\r\n4. Repeat the movement with your left arm while keeping the right arm extended. Continue alternating arms for the desired number of repetitions.', E'1. Keep your elbows stationary and close to your torso to isolate the biceps.\r\n2. Avoid using momentum or swinging your body to lift the dumbbells.\r\n3. Breathe out as you curl the dumbbell up and breathe in as you lower it.', '{"image_male_start":"images/Biceps/Dumbbell Alternate Biceps Curl.jpeg","video_url":"videos/Biceps/Dumbbell Alternate Biceps Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a34c7944-1890-41db-9141-e261ea91d8f7'::uuid, 'Dumbbell Alternate Biceps Curl (VERSION 2)', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench with your feet flat on the floor, holding a dumbbell in each hand with your arms fully extended by your sides and palms facing inwards.\r\n2. Keep your elbows close to your torso and curl the right dumbbell towards your shoulder by contracting your biceps. Rotate your forearm as you lift the dumbbell so that your palm faces your shoulder at the top of the movement.\r\n3. Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back to the starting position.\r\n4. Repeat the movement with your left arm while keeping the right arm extended. Continue alternating arms for the desired number of repetitions.', E'1. Keep your elbows stationary and close to your torso to isolate the biceps.\r\n2. Avoid using momentum or swinging your body to lift the dumbbells.\r\n3. Breathe out as you curl the dumbbell up and breathe in as you lower it.', '{"image_male_start":"images/Biceps/Dumbbell Alternate Biceps Curl (VERSION 2).jpeg","video_url":"videos/Biceps/Dumbbell Alternate Biceps Curl (VERSION 2).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b287a6f9-f755-46d0-83f6-5aec96a099fe'::uuid, 'Dumbbell Alternate Seated Hammer Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench with your feet flat on the floor and a dumbbell in each hand, palms facing your torso. Let your arms hang straight down by your sides.\r\n2. Keep your elbows close to your body and curl the right dumbbell towards your shoulder by bending your elbow. Keep your palm facing inward throughout the movement.\r\n3. Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back to the starting position.\r\n4. Repeat the movement with your left arm while keeping the right arm extended. Continue alternating arms for the desired number of repetitions.', E'1. Keep your wrists straight and aligned with your forearms throughout the exercise.\r\n2. Focus on using your biceps to lift the weight, avoiding any swinging or using momentum.\r\n3. Breathe out as you curl the dumbbell up and breathe in as you lower it.\r\n', '{"image_male_start":"images/Biceps/Dumbbell Alternate Seated Hammer Curl.jpeg","video_url":"videos/Biceps/Dumbbell Alternate Seated Hammer Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ad140617-f7db-4a3f-9c48-12e312ab3cc7'::uuid, 'Dumbbell Alternate Shoulder Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height. Your palms should be facing forward, and your elbows should be bent at a 90-degree angle.\r\n2. Engage your core and press the right dumbbell overhead until your arm is fully extended. Keep your left dumbbell in the starting position.\r\n3. Lower the right dumbbell back to shoulder height in a controlled manner.\r\n4. Repeat, alternating arms for the desired number of repetitions.', E'1. Avoid locking your elbows at the top of the movement to maintain tension in the muscles.\r\n2. Breathe out as you press the dumbbell overhead and breathe in as you lower it.\r\n3. Ensure your wrists remain straight and aligned with your forearms throughout the exercise.\r\n', '{"image_male_start":"images/Shoulders/Dumbbell Alternate Shoulder Press.jpg","image_male_end":"images/Shoulders/Dumbbell Alternate Shoulder Press1.jpg","video_url":"videos/Shoulders/Dumbbell Alternate Shoulder Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7d4217aa-6033-47bd-877e-312810ed871c'::uuid, 'Dumbbell Alternate Side Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height. Your palms should be facing each other, and your elbows should be bent at a 60-degree angle and facing downward.\r\n2. Press the right dumbbell overhead and slightly lean to the opposite side until your arm is fully extended.\r\n3. Lower the right dumbbell back to shoulder height in a controlled manner and press the left dumbbell overhead and slightly to the side.\r\n4. Continue alternating arms for the desired number of repetitions, ensuring a smooth and controlled movement.', E'1. Breathe out as you press the dumbbell overhead and breathe in as you lower it.\r\n2. Maintain a controlled pace to maximize muscle engagement and avoid using momentum.\r\n3. Ensure your wrists remain straight and aligned with your forearms throughout the exercise.', '{"image_male_start":"images/Shoulders/Dumbbell Alternate Side Press.jpg","image_male_end":"images/Shoulders/Dumbbell Alternate Side Press1.jpg","video_url":"videos/Shoulders/Dumbbell Alternate Side Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4786a96b-1d10-41d0-ab80-e86302523a4e'::uuid, 'Dumbbell armpit row', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your arms fully extended and palms facing your body.\r\n2. Pull the dumbbells up towards your armpits by bending your elbows. Your elbows should be pointing out to the sides.\r\n3. Lower the dumbbells back to the starting position in a controlled manner. Repeat the movement for the desired number of repetitions.\r\n', E'1. Keep your back straight and avoid rounding your shoulders during the exercise.\r\n2. Maintain a slight bend in your knees to reduce strain on your lower back.\r\n3. Breathe out as you lift the dumbbells and breathe in as you lower them.', '{"image_male_start":"images/Shoulders/dumbbell armpit row.jpg","image_male_end":"images/Shoulders/dumbbell armpit row1.jpg","video_url":"videos/Shoulders/dumbbell armpit row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6772ddfc-e3ba-47fc-b1b6-d4926e4c5c20'::uuid, 'Dumbbell Arnold Press (version 2)', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench holding a dumbbell in each hand at shoulder height with your palms facing each other and your elbows bent.\r\n2. Engage your shoulders and rotate your palms to face forward as you press the dumbbells overhead until your arms are fully extended.\r\n3. Reverse the motion by lowering the dumbbells back to shoulder height while rotating your palms to face each other again.\r\n4. Repeat the movement for the desired number of repetitions, ensuring a smooth and controlled motion throughout the exercise.', E'1. Avoid locking your elbows at the top of the movement to maintain tension in the muscles.\r\n2. Breathe out as you press the dumbbells overhead and breathe in as you lower them.\r\n3. Maintain a controlled pace to maximize muscle engagement and avoid using momentum.', '{"image_male_start":"images/Shoulders/Dumbbell Arnold Press (version 2).jpg","image_male_end":"images/Shoulders/Dumbbell Arnold Press (version 2)1.jpg","video_url":"videos/Shoulders/Dumbbell Arnold Press (version 2).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('75bb6038-85a8-477e-af28-3c0620608d79'::uuid, 'Dumbbell Arnold Press Seated', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench with back support, holding a dumbbell in each hand at shoulder height with your palms facing your body and your elbows bent. Your feet should be flat on the floor.\r\n2. Engage your shoulders and rotate your palms to face forward as you press the dumbbells overhead until your arms are fully extended.\r\n3. Reverse the motion by lowering the dumbbells back to shoulder height while rotating your palms to face your body again.\r\n4. Repeat the movement for the desired number of repetitions, ensuring a smooth and controlled motion throughout the exercise.', E'1. Keep your back pressed against the bench to maintain stability and prevent arching.\r\n2. Avoid locking your elbows at the top of the movement to maintain tension in the muscles.\r\n3. Breathe out as you press the dumbbells overhead and breathe in as you lower them.', '{"image_male_start":"images/Shoulders/Dumbbell Arnold Press Seated.jpg","image_male_end":"images/Shoulders/Dumbbell Arnold Press Seated1.jpg","video_url":"videos/Shoulders/Dumbbell Arnold Press Seated.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a7a020b7-62d8-40f7-bbc8-4537b33e294f'::uuid, 'Dumbbell Around Pullover', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie on your back on a bench with your feet flat on the floor. Hold a dumbbell in each hand, arms extended straight on your sides, palms facing down.\r\n2. Slowly raise the dumbbells in an arc over your torso and behind your head, keeping your arms straight.\r\n3. Return your arms back to the starting position in an arc motion, this time from your sides.\r\n4. Repeat the movement for the desired number of repetitions, ensuring a smooth and controlled motion throughout the exercise.', E'1. Focus on using your chest and shoulder muscles to control the movement, avoiding any swinging or using momentum.\r\n2. Ensure your wrists remain straight and aligned with your forearms throughout the exercise.\r\n3. Maintain a slight bend in your elbows to protect your joints.\r\n\r\n', '{"image_male_start":"images/Chest/Dumbbell Around Pullover.jpg","image_male_end":"images/Chest/Dumbbell Around Pullover1.jpg","video_url":"videos/Chest/Dumbbell Around Pullover.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3fb0875e-2845-4815-a32a-882f18bb1937'::uuid, 'Dumbbell Bar Grip Sumo Squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet wider than shoulder-width apart, toes pointing slightly outward. Hold a dumbbell vertically with both hands, like holding a bar, in front of your hips.\r\n2. Push your hips back and bend your knees to lower yourself until your thighs are parallel to the floor, keeping the dumbbell in line with your chest.\r\n3. Push through your heels to return to the starting position, straightening your legs and squeezing your glutes at the top. Repeat the movement for the desired number of repetitions.', E'1. Ensure your knees follow the direction of your toes to avoid placing unnecessary stress on your joints.\r\n2. Breathe in as you lower into the squat and breathe out as you push back up.\r\n3. Maintain a slow and controlled movement to maximize muscle engagement and stability.', '{"image_male_start":"images/Legs/Dumbbell Bar Grip Sumo Squat.jpg","image_male_end":"images/Legs/Dumbbell Bar Grip Sumo Squat1.jpg","video_url":"videos/Legs/Dumbbell Bar Grip Sumo Squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c125ba06-622d-40b1-b213-7490fa249928'::uuid, 'Dumbbell Bench Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie flat on a bench with a dumbbell in each hand, arms extended above your chest and palms facing forward.\r\n2. Engage your core and keep your feet flat on the floor, maintaining a natural arch in your lower back.\r\n3. Lower the dumbbells to your chest by bending your elbows, keeping your upper arms at a 45-degree angle to your torso.\r\n4. Push the dumbbells back to the starting position by straightening your arms, ensuring a controlled motion throughout. Repeat for the desired number of repetitions.', E'1. Keep your wrists straight and aligned with your forearms throughout the exercise.\r\n2. Avoid flaring your elbows too much; maintain a 45-degree angle to protect your shoulder joints.\r\n3. Breathe in as you lower the dumbbells and exhale as you press them back up.', '{"image_male_start":"images/Chest/Dumbbell Bench Press.jpg","image_male_end":"images/Chest/Dumbbell Bench Press1.jpg","video_url":"videos/Chest/Dumbbell Bench Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7aa26922-805b-4b92-af3a-0abc066be5a4'::uuid, 'Dumbbell Bench Seated Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a flat bench, holding a dumbbell in each hand at shoulder height, palms facing forward.\r\n2. Press the dumbbells upward until your arms are fully extended, ensuring your wrists remain straight and aligned with your forearms.\r\n3. Lower the dumbbells back to the starting position with a controlled motion. Repeat for the desired number of repetitions.\r\n', E'1. Ensure your elbows do not flare out excessively; keep them slightly in front of your body.\r\n2. Avoid arching your lower back; keep your core engaged and back pressed against the bench.\r\n3. Breathe out as you press the dumbbells upward and breathe in as you lower them back down.', '{"image_male_start":"images/Shoulders/Dumbbell Bench Seated Press.jpg","image_male_end":"images/Shoulders/Dumbbell Bench Seated Press1.jpg","video_url":"videos/Shoulders/Dumbbell Bench Seated Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('06e06c26-eae3-4bf0-b703-05af1679aca8'::uuid, 'Dumbbell Bench Squat', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your back facing a bench with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.\r\n2. Lower yourself into a squat by bending your knees and hips, keeping your chest up and back straight, until your thighs are parallel to the floor and your buttocks lightly touch the bench.\r\n3. Push through your heels to stand back up to the starting position, fully extending your hips and knees.\r\n4. Repeat the movement for the desired number of repetitions, maintaining proper form throughout.', E'1. Focus on pressing through your heels to activate your glutes and quadriceps effectively.\r\n2. Breathe in as you lower into the squat and exhale as you push back up to the starting position.\r\n3. Use a controlled, steady pace to maximize muscle engagement and maintain balance.', '{"image_male_start":"images/Legs/Dumbbell Bench Squat.jpg","image_male_end":"images/Legs/Dumbbell Bench Squat1.jpg","video_url":"videos/Legs/Dumbbell Bench Squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f3b20d68-1e11-4702-9402-46b62951ddbf'::uuid, 'Dumbbell bent arm lateral raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand, elbows bent at a 90-degree angle and palms facing your body.\r\n2. Engage your core and keep your back straight. Raise your upper arms to the sides until they are parallel to the floor, keeping your elbows bent at 90 degrees throughout the movement.\r\n3. Lower your arms back to the starting position with a controlled motion. Repeat for the desired number of repetitions.', E'1. Avoid using momentum; perform the movement slowly and with control to maximize muscle engagement.\r\n2. Ensure your elbows remain at a 90-degree angle throughout the exercise.\r\n3. Do not raise your arms above shoulder height to avoid unnecessary stress on your shoulder joints.\r\n', '{"image_male_start":"images/Shoulders/dumbbell bent arm lateral raise.jpg","image_male_end":"images/Shoulders/dumbbell bent arm lateral raise1.jpg","video_url":"videos/Shoulders/dumbbell bent arm lateral raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d654c1af-4230-493a-8680-8ea584cb952c'::uuid, 'Dumbbell Bent Arm Pullover', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie perpendicular on a bench with only your upper back supported and your hips slightly lowered. Hold a dumbbell with both hands above your chest, keeping your elbows slightly bent.\r\n2. Engage your core and keep your feet flat on the floor for stability. Slowly lower the dumbbell in an arc over your head, maintaining the slight bend in your elbows.\r\n3. Lower the dumbbell until your upper arms are in line with your torso or as far as comfortable, feeling a stretch in your chest and lats.\r\n4. Pull the dumbbell back to the starting position with a controlled motion, keeping your elbows slightly bent. Repeat for the desired number of repetitions.', E'1. Avoid letting your elbows flare out; maintain a slight bend throughout the movement.\r\n2. Ensure your shoulders and upper back remain in contact with the bench throughout the exercise.\r\n3. Perform the movement slowly and with control to maximize muscle engagement and prevent injury.\r\n', '{"image_male_start":"images/Back/Dumbbell Bent Arm Pullover.jpg","image_male_end":"images/Back/Dumbbell Bent Arm Pullover1.jpg","video_url":"videos/Back/Dumbbell Bent Arm Pullover.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3ffcb793-3089-4e7e-a0dc-0935f0773b32'::uuid, 'Dumbbell Bent Over Face Pull', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip (palms facing back). Bend at your hips and knees to lower your torso until it is parallel to the floor, keeping your back straight.\r\n2. Let the dumbbells hang directly below your shoulders, elbows slightly bent.\r\n3. Pull the dumbbells upward to the ceiling, bending your elbows and bringing them as high as possible and facing outward. Make sure to lead the dumbbells at face level.\r\n4. Lower the dumbbells back to the starting position with a controlled motion. Repeat for the desired number of repetitions.', E'1. Avoid using momentum; perform the movement slowly and with control to maximize muscle engagement.\r\n2. Breathe out as you pull the dumbbells towards your face and breathe in as you lower them back down.\r\n3. Use a weight that allows you to perform the exercise with proper form without straining.', '{"image_male_start":"images/Shoulders/Dumbbell Bent Over Face Pull.jpg","image_male_end":"images/Shoulders/Dumbbell Bent Over Face Pull1.jpg","video_url":"videos/Shoulders/Dumbbell Bent Over Face Pull.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('52587e62-eb0a-46b8-9608-cf9a1c3d2074'::uuid, 'Dumbbell Bent-Over Reverse Row', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip (palms facing towards you). Bend at your hips and knees to lower your torso until it is nearly parallel to the floor, keeping your back straight.\r\n2. Let the dumbbells hang directly below your shoulders, arms fully extended.\r\n3. Pull the dumbbells towards your torso, leading with your elbows and keeping them close to your body. Squeeze your shoulder blades together at the top of the movement.\r\n4. Lower the dumbbells back to the starting position with a controlled motion. Repeat for the desired number of repetitions.', E'1. Avoid using momentum; perform the movement slowly and with control to maximize muscle engagement.\r\n2. Breathe out as you pull the dumbbells towards your torso and breathe in as you lower them back down.\r\n3. Ensure your elbows remain close to your body throughout the exercise to protect your joints.', '{"image_male_start":"images/Back/Dumbbell Bent-Over Reverse Row.jpg","image_male_end":"images/Back/Dumbbell Bent-Over Reverse Row1.jpg","video_url":"videos/Back/Dumbbell Bent-Over Reverse Row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8592d87d-2c23-4005-b207-0e0c502ab5b7'::uuid, 'Dumbbell Bent-Over Row', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with a neutral grip (palms facing each other). Bend at your hips and knees to lower your torso until it is nearly parallel to the floor, keeping your back straight.\r\n2. Let the dumbbells hang directly below your shoulders, arms fully extended.\r\n3. Pull the dumbbells towards your torso, leading with your elbows and keeping them close to your body. Squeeze your shoulder blades together at the top of the movement.\r\n4. Lower the dumbbells back to the starting position with a controlled motion. Repeat for the desired number of repetitions.', E'1. Avoid using momentum; perform the movement slowly and with control to maximize muscle engagement.\r\n2. Breathe out as you pull the dumbbells towards your torso and breathe in as you lower them back down.\r\n3. Ensure your elbows remain close to your body throughout the exercise to protect your joints.', '{"image_male_start":"images/Back/Dumbbell Bent-Over Row.jpg","image_male_end":"images/Back/Dumbbell Bent-Over Row1.jpg","video_url":"videos/Back/Dumbbell Bent-Over Row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('49763475-1184-47bc-980a-efc2312ab06a'::uuid, 'Dumbbell bicep curl to shoulder press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an underhand grip (palms facing forward). Keep your elbows close to your torso.\r\n2. Perform bicep curls by bending your elbows to lift the dumbbells towards your shoulders, keeping your upper arms stationary.\r\n3. As you reach the top of the curl, rotate your wrists so that your palms face forward and press the dumbbells overhead by extending your arms fully.\r\n4. Lower the dumbbells back to shoulder height, then rotate your wrists back to the starting position and lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', E'1. Keep your elbows close to your body during the bicep curl and ensure they don’t flare out during the shoulder press.\r\n2. Exhale as you press the dumbbells overhead and inhale as you lower them.\r\n3. Start with a lighter weight to master the technique before progressing to heavier weights.', '{"image_male_start":"images/Shoulders/dumbbell bicep curl to shoulder press.jpg","image_male_end":"images/Shoulders/dumbbell bicep curl to shoulder press1.jpg","video_url":"videos/Shoulders/dumbbell bicep curl to shoulder press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('886e79b7-5947-453b-bbe6-0555ee1186c8'::uuid, 'Dumbbell Biceps Curl with Overhead Extension on Stability Ball', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Kneel on a stability ball with your forefeet on the floor for support. Hold a dumbbell in each hand with one arm extended overhead and the other arm hanging by your side.\r\n2. Simultaneously perform a bicep curl with the arm hanging by your side, bending your elbow to lift the dumbbell towards your shoulder and an overhead triceps extension with the other arm, bending your elbow to lower the dumbbell behind your head.\r\n3. Slowly return both arms to the starting position, ensuring control and stability throughout the movement. Repeat for the desired number of repetitions.\r\n', E'1. Maintain balance on the stability ball by engaging your core muscles throughout the exercise.\r\n2. Perform the movements slowly and with control to maximize muscle activation and reduce the risk of injury.\r\n3. Keep your elbows close to your body during the bicep curl and ensure your overhead arm remains stable during the triceps extension.', '{"image_male_start":"images/Biceps/Dumbbell Biceps Curl with Overhead Extension on Stability Ball.jpeg","video_url":"videos/Biceps/Dumbbell Biceps Curl with Overhead Extension on Stability Ball.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('aaf3a923-731a-4560-a0ad-1588f0602fef'::uuid, 'Dumbbell bulgarian box split squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand a few feet, back first in front of a box, holding a dumbbell in each hand with your arms hanging by your sides. Place the top of one foot on the box behind you.\r\n2. Lower your body by bending your front knee until your front thigh is parallel to the floor and your back knee is hovering just above the floor.\r\n3. Push through your front heel to return to the starting position, keeping your back straight and core engaged.\r\n4. Repeat for the desired number of repetitions, then switch legs and repeat the movement on the other side.', E'1. Start with a lighter weight to master the technique before progressing to heavier weights.\r\n2. Keep your torso upright and avoid leaning forward or arching your back during the movement.\r\n3. Engage your core throughout the exercise to stabilize your body and support your lower back.', '{"image_male_start":"images/Legs/dumbbell bulgarian box split squat.jpg","image_male_end":"images/Legs/dumbbell bulgarian box split squat1.jpg","video_url":"videos/Legs/dumbbell bulgarian box split squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('978ed7a1-3c86-48e8-830d-c5cfd257d0ab'::uuid, 'Dumbbell Bulgarian Split Squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand a few feet, back first in front of a bench, holding a dumbbell in each hand with your arms hanging by your sides. Place the top of one foot on the bench behind you.\r\n2. Lower your body by bending your front knee until your front thigh is parallel to the floor and your back knee is hovering just above the floor.\r\n3. Push through your front heel to return to the starting position, keeping your back straight and core engaged.\r\n4. Repeat for the desired number of repetitions, then switch legs and repeat the movement on the other side.', E'1. Start with a lighter weight to master the technique before progressing to heavier weights.\r\n2. Keep your torso upright and avoid leaning forward or arching your back during the movement.\r\n3. Engage your core throughout the exercise to stabilize your body and support your lower back.', '{"image_male_start":"images/Legs/Dumbbell Bulgarian Split Squat.jpg","image_male_end":"images/Legs/Dumbbell Bulgarian Split Squat1.jpg","video_url":"videos/Legs/Dumbbell Bulgarian Split Squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0119e519-5878-470a-9ce7-81f5e9a65cdc'::uuid, 'Dumbbell chest press decline', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie on a decline bench with your feet securely placed under the footpads. Hold a dumbbell in each hand with your arms fully extended above your chest, palms facing forward.\r\n2. Lower the dumbbells slowly towards your chest by bending your elbows, keeping your upper arms at a 45-degree angle to your body.\r\n3. Push the dumbbells back to the starting position by straightening your arms, squeezing your chest at the top of the movement.\r\n4. Repeat the movement for the desired number of repetitions, maintaining control throughout the exercise.', E'1. Ensure your feet are securely positioned under the footpads to prevent slipping during the movement.\r\n2. Maintain a steady and controlled motion, avoiding any jerking or sudden movements.\r\n3. Breathe in as you lower the dumbbells and exhale as you press them back up.', '{"image_male_start":"images/Chest/dumbbell chest press decline.jpg","image_male_end":"images/Chest/dumbbell chest press decline1.jpg","video_url":"videos/Chest/dumbbell chest press decline.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d3f954c7-4201-4415-8763-4d9a846a1e67'::uuid, 'Dumbbell chest press flat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie flat on a bench with your feet firmly on the floor. Hold a dumbbell in each hand with your arms fully extended above your chest, palms facing forward.\r\n2. Lower the dumbbells slowly towards your chest by bending your elbows, keeping your upper arms at a 45-degree angle to your body.\r\n3. Push the dumbbells back to the starting position by straightening your arms, squeezing your chest at the top of the movement.\r\n4. Repeat the movement for the desired number of repetitions, maintaining control throughout the exercise.', E'1. Ensure your feet are flat on the floor to provide a solid base of support.\r\n2. Maintain a steady and controlled motion, avoiding any jerking or sudden movements.\r\n3. Breathe in as you lower the dumbbells and exhale as you press them back up.', '{"image_male_start":"images/Chest/dumbbell chest press flat.jpg","image_male_end":"images/Chest/dumbbell chest press flat1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b1a26d2c-c128-49a2-bf40-f8e1743e9ddb'::uuid, 'Dumbbell chest press incline bench', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie on an incline bench with your feet firmly on the floor. Hold a dumbbell in each hand with your arms fully extended above your chest, palms facing forward.\r\n2. Lower the dumbbells slowly towards your chest by bending your elbows, keeping your upper arms at a 45-degree angle to your body.\r\n3. Push the dumbbells back to the starting position by straightening your arms, squeezing your chest at the top of the movement.\r\n4. Repeat the movement for the desired number of repetitions, maintaining control throughout the exercise.', E'1. Adjust the bench to a moderate incline (around 30-45 degrees) to effectively target the upper chest.\r\n2. Avoid arching your back excessively to prevent strain and injury.\r\n3. Avoid locking your elbows completely at the top of the press to maintain tension in your muscles.', '{"image_male_start":"images/Chest/dumbbell chest press incline bench.jpg","image_male_end":"images/Chest/dumbbell chest press incline bench1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('10a3cff4-dbcb-40d3-916f-9d5e738a12af'::uuid, 'Dumbbell chest pull over', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie crosswise on a bench, with your upper back and shoulders supported, feet firmly planted on the floor and hips slightly lowered. Hold a dumbbell with both hands above your chest, arms slightly bent.\r\n2. Slowly lower the dumbbell in an arc over your head and down towards the floor, maintaining a slight bend in your elbows.\r\n3. Bring the dumbbell back up to the starting position by reversing the arc motion, focusing on engaging your chest and lats.\r\n4. Repeat the movement for the desired number of repetitions, maintaining control throughout the exercise.', E'1. Keep a firm grip on the dumbbell to maintain control and prevent it from slipping.\r\n2. Avoid lowering the dumbbell too far to prevent shoulder strain.\r\n3. Engage your core to stabilize your body and support your lower back.', '{"image_male_start":"images/Chest/dumbbell chest pull over.jpg","image_male_end":"images/Chest/dumbbell chest pull over1.jpg","video_url":"videos/Chest/dumbbell chest pull over.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4ed230d3-bdc4-4576-a2b6-241d211da717'::uuid, 'Dumbbell Chest Supported Lateral Raises', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie face-down on an incline bench with your chest and stomach supported by the bench, and your feet firmly planted on the floor. Hold a dumbbell with both hands, arms extended straight down.\r\n2. Slowly raise the dumbbells in an arc over your head and towards your back, maintaining a slight bend in your elbows.\r\n3. Bring the dumbbell back to the starting position by reversing the arc motion, focusing on engaging your back and shoulder muscles.\r\n4. Repeat the movement for the desired number of repetitions, maintaining control throughout the exercise.', E'1. Keep a firm grip on the dumbbell to maintain control and prevent it from slipping.\r\n2. Avoid raising the dumbbell too far to prevent shoulder strain.\r\n3. Maintain a slight bend in your elbows to reduce stress on your joints.', '{"image_male_start":"images/Shoulders/Dumbbell Chest Supported Lateral Raises.jpg","image_male_end":"images/Shoulders/Dumbbell Chest Supported Lateral Raises1.jpg","video_url":"videos/Shoulders/Dumbbell Chest Supported Lateral Raises.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('cda91fa5-34c3-4d1d-8654-9d99b9dc3450'::uuid, 'Dumbbell close grip shoulder press sit up', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie on the floor with your knees bent and your feet flat on the floor. Hold a dumbbell in each hand with a close grip, elbows bent at 90 degrees resting on the floor.\r\n2. Engage your core and perform a sit-up by raising your torso towards your knees while simultaneously pressing the dumbbells overhead.\r\n3. Lower your torso back to the starting position while bringing the dumbbells back to shoulder height.\r\n4. Repeat the movement for the desired number of repetitions, maintaining control throughout the exercise.', E'1. Maintain a close grip on the dumbbells to ensure proper shoulder engagement.\r\n2. Engage your core throughout the movement to support your lower back.\r\n3. Keep your feet firmly planted on the floor to stabilize your body during the sit-up.', '{"image_male_start":"images/Shoulders/dumbbell close grip shoulder press sit up.jpg","image_male_end":"images/Shoulders/dumbbell close grip shoulder press sit up1.jpg","video_url":"videos/Shoulders/dumbbell close grip shoulder press sit up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('886872e2-10d4-4534-9546-215dd4797d0e'::uuid, 'Dumbbell close Legs Deadlift', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet close together, holding a dumbbell with both hands from the bar, allowing it to hang in front of you.\r\n2. Keep your back straight and hinge at the hips, lowering the dumbbell towards your feet while keeping it close to your legs.\r\n3. Lower the dumbbell until you feel a stretch in your hamstrings, ensuring your knees are slightly bent.\r\n4. Engage your glutes and hamstrings to lift your torso back to the starting position. Repeat the movement for the desired number of repetitions.', E'1. Maintain a slight bend in your knees to reduce stress on your joints.\r\n2. Engage your core to stabilize your spine during the movement.\r\n3. Keep the dumbbell close to your legs to maintain proper form and maximize muscle engagement.', '{"image_male_start":"images/Legs/Dumbbell close Legs Deadlift.jpg","image_male_end":"images/Legs/Dumbbell close Legs Deadlift1.jpg","video_url":"videos/Legs/Dumbbell close Legs Deadlift.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ffbce586-b78e-4c73-8e27-4ab13dc96b22'::uuid, 'Dumbbell Close-Grip Simultaneous Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with a close grip, palms facing front.\r\n2. Keep your elbows close to your torso and curl the dumbbells simultaneously towards your shoulders by contracting your biceps.\r\n3. Pause at the top of the movement, squeezing your biceps.\r\n4. Lower the dumbbells back to the starting position with control. Repeat the movement for the desired number of repetitions.', E'1. Keep your elbows stationary and close to your body throughout the exercise to isolate the biceps.\r\n2. Avoid swinging the weights or using momentum to lift the dumbbells.\r\n3. Focus on a slow and controlled movement to maximize muscle engagement.', '{"image_male_start":"images/Biceps/Dumbbell Close-Grip Simultaneous Curl.jpeg","video_url":"videos/Biceps/Dumbbell Close-Grip Simultaneous Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d9ccd5b9-4ded-4524-97a7-c467e6f3b0d5'::uuid, 'Dumbbell Cossack Squats (VERSION 2)', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet wider than shoulder-width apart, holding a dumbbell close to your chest between your palms, with your elbows bent facing down.\r\n2. Shift your weight to your right leg and bend your right knee, lowering your body into a squat position while keeping your left leg straight and your left foot flat on the floor.\r\n3. Push through your right heel to return to the starting position and repeat the movement on the other side. Alternate sides for the desired number of repetitions.', E'1. Ensure your knees track over your toes to avoid placing unnecessary stress on your joints.\r\n2. Start with a lighter weight if you''re new to the exercise, gradually increasing the load as you become more comfortable with the movement.\r\n3. Keep your chest up, back straight, and dumbbell close to your chest as you lower yourself.', '{"image_male_start":"images/Legs/Dumbbell Cossack Squats (VERSION 2).jpg","image_male_end":"images/Legs/Dumbbell Cossack Squats (VERSION 2)1.jpg","video_url":"videos/Legs/Dumbbell Cossack Squats (VERSION 2).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1a24cb2f-ff1f-409d-99ff-579ac52ae7f4'::uuid, 'Dumbbell Cross Body Hammer Curl (Version 2)', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your arms fully extended and palms facing your body.\r\n2. Keeping your upper arms stationary, curl the right dumbbell across your body towards your left shoulder, squeezing your biceps at the top of the movement.\r\n3. Slowly lower the dumbbell back to the starting position, maintaining control throughout the movement.\r\n4. Repeat the movement with your left arm, curling the dumbbell towards your right shoulder. Alternate sides for the desired number of repetitions.', E'1. Keep your elbows close to your body and avoid swinging your arms to ensure maximum biceps engagement.\r\n2. Maintain a neutral grip with your palms facing inwards throughout the exercise.\r\n3. Focus on a controlled, steady movement to avoid using momentum.', '{"image_male_start":"images/Biceps/Dumbbell Cross Body Hammer Curl (Version 2).jpeg","video_url":"videos/Biceps/Dumbbell Cross Body Hammer Curl (Version 2).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('97e9c51e-35fa-436f-b785-a02fe15c3dc6'::uuid, 'Dumbbell Crunch Hold with Legs Off', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie flat on your back with your knees straight and your legs lifted off the floor almost parallel to the floor, holding a dumbbell with both hands extended just over your hips.\r\n2. Engage your core and lift your shoulder blades off the floor, performing a crunch while pushing the dumbbell over your thighs.\r\n3. Hold the crunch position for a few seconds, ensuring your abs are fully engaged and your lower back remains pressed into the floor.\r\n4. Slowly lower your shoulders back to the floor, maintaining control of the dumbbell throughout the movement. Repeat for the desired number of repetitions.', E'1. Breathe out as you lift your shoulders off the floor and inhale as you lower them back down.\r\n2. Focus on engaging your core muscles throughout the exercise for maximum effectiveness.\r\n3. Start with a lighter weight to ensure proper form and gradually increase as you become more comfortable.', '{"image_male_start":"images/Abdominals/Dumbbell Crunch Hold with Legs Off.jpeg","video_url":"videos/Abdominals/Dumbbell Crunch Hold with Legs Off.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2e559463-b301-4d88-a37d-bebfc89f8f75'::uuid, 'Dumbbell Cuban Press (version 2)', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip. Let your arms hang straight down in front of your thighs.\r\n2. Raise your elbows to shoulder height, keeping your arms bent at a 90-degree angle, forming a "goalpost" position with your forearms perpendicular to your body.\r\n3. Rotate your shoulders to lift the dumbbells upward until your forearms are vertical.\r\n4. Press the dumbbells overhead until your arms are fully extended. Reverse the movement to return to the starting position. Repeat for the desired number of repetitions.', E'1. Avoid using momentum; use controlled movements to lift and lower the dumbbells.\r\n2. Keep your core engaged and maintain a neutral spine throughout the exercise.\r\n3. Start with a lighter weight to ensure proper form and gradually increase as you become more comfortable.', '{"image_male_start":"images/Shoulders/Dumbbell Cuban Press (version 2).jpg","image_male_end":"images/Shoulders/Dumbbell Cuban Press (version 2)1.jpg","video_url":"videos/Shoulders/Dumbbell Cuban Press (version 2).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a707a8d8-7ffa-4d2a-b8e5-39e46790a200'::uuid, 'Dumbbell Curl Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your arms hanging down by your sides. Your palms should face forward.\r\n2. Curl the dumbbells up towards your shoulders, keeping your elbows close to your body. From the top of the curl position, press the dumbbells overhead until your arms are fully extended. Your palms should be facing backward at the top of the press.\r\n3. Lower the dumbbells behind your head, bending at the elbows until forearms are parallel to the floor. Extend your arms to bring the dumbbells back overhead.\r\n4. Lower the dumbbells back to shoulder height, then reverse the curl movement to return to the starting position. Repeat for the desired number of repetitions.', E'1. Perform the movements in a controlled manner, avoiding any jerking or swinging.\r\n2. Ensure your elbows stay close to your body during the curl phase.\r\n3. Keep your wrists straight and avoid excessive bending during the press and extension.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('62721d54-c1ea-4ff8-9605-02d6ebf5cfba'::uuid, 'Dumbbell curls', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing inwards (neutral grip).\r\n2. Keep your elbows close to your torso and curl the dumbbells up towards your shoulders, rotating your wrists so your palms face upward at the top of the curl.\r\n3. Hold the top position for a brief moment, ensuring you squeeze your biceps.\r\n4. Slowly lower the dumbbells back to the starting position, rotating your wrists back to the neutral grip, maintaining control throughout the movement. Repeat for the desired number of repetitions.', E'1. Perform the movements in a controlled manner, avoiding any jerking or swinging.\r\n2. Ensure your elbows stay close to your body and do not flare out during the curl.\r\n3. Keep your wrists straight and avoid excessive bending.', '{"image_male_start":"images/Biceps/dumbbell curls.jpeg","video_url":"videos/Biceps/dumbbell curls.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('17eb9344-f421-48e9-a3f1-cb5975d6d686'::uuid, 'Dumbbell curls alternating', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing inwards (neutral grip).\r\n2. Keep your elbows close to your torso and curl one dumbbell up towards your shoulder, rotating your wrist so your palm faces upward (supinated grip) at the top of the curl.\r\n3. Hold the top position for a brief moment, ensuring you squeeze your biceps, then slowly lower the dumbbell back to the starting position, rotating your wrist back to the neutral grip.\r\n4. Repeat the curl with the other arm, alternating arms for the desired number of repetitions.', E'1. Perform the movements in a controlled manner, avoiding any jerking or swinging.\r\n2. Ensure your elbows stay close to your body and do not flare out during the curl.\r\n3. Keep your wrists straight and avoid excessive bending.', '{"video_url":"videos/Biceps/dumbbell curls alternating.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7c7446e1-c1fe-469d-95aa-868ab576ec8d'::uuid, 'Dumbbell curtsy lunge', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet hip-width apart, arms bent at 90 degrees, holding a dumbbell in each hand in front of your chest.\r\n2. Step your right leg behind and to the left of your left leg, lowering your hips into a curtsy lunge position. Your front knee should be aligned with your front ankle, and your back knee should hover just above the floor.\r\n3. Push through your left heel to return to the starting position, bringing your right leg back to starting position.\r\n4. Repeat the lunge with your left leg stepping behind and to the right of your right leg, alternating legs for the desired number of repetitions.', E'1. Ensure your front knee does not extend past your toes.\r\n2. Perform the movement in a controlled manner, focusing on balance and stability.\r\n3. Exhale as you push back to the starting position and inhale as you lower into the lunge.', '{"image_male_start":"images/Legs/Dumbbell Curtsy Lunge  .jpg","video_url":"videos/Legs/Dumbbell Curtsy Lunge  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('950b7553-7fee-40fc-a256-cbe28f6b3bfd'::uuid, 'Dumbbell Decline Alternate Bench Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by lying on a decline bench with your feet secured and a dumbbell in each hand, arms lowered and elbows bent at a 90-degree angle, palms facing forward.\r\n2. Press the left dumbbell upward until your arm is fully extended while keeping the right arm lowered.\r\n3. Lower the left dumbbell back to the starting position, and press the right dumbbell upward until your arm is fully extended.\r\n4. Alternate the press with each arm, maintaining control and stability throughout the exercise, and repeat for the desired number of repetitions.', E'1. Avoid locking your elbows at the top of the movement to keep tension on your muscles.\r\n2. Ensure your wrists remain straight and aligned with your forearms.\r\n3. Focus on a slow and controlled motion to maximize muscle engagement.', '{"image_male_start":"images/Chest/Dumbbell Decline Alternate Bench Press.jpg","image_male_end":"images/Chest/Dumbbell Decline Alternate Bench Press1.jpg","video_url":"videos/Chest/Dumbbell Decline Alternate Bench Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('008dca47-a8ab-4e46-a9d3-f30cbf67e0b0'::uuid, 'Dumbbell Decline Bench Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by lying on a decline bench with your feet secured and a dumbbell in each hand, arms lowered and elbows bent at a 90-degree angle, palms facing forward.\r\n2. Press both dumbbells upward simultaneously until your arms are fully extended, keeping the motion controlled.\r\n3. Lower the dumbbells back to the starting position with controlled motion until your elbows are at a 90-degree angle.\r\n4. Repeat the press and lowering motion for the desired number of repetitions, maintaining stability throughout the exercise.', E'1. Keep your feet firmly planted and secured to avoid slipping.\r\n2. Maintain a slight bend in your elbows at the top of the movement to protect your joints.\r\n3. Concentrate on using your chest muscles to press the weights, minimizing shoulder involvement.', '{"image_male_start":"images/Chest/Dumbbell Decline Bench Press.jpg","image_male_end":"images/Chest/Dumbbell Decline Bench Press1.jpg","video_url":"videos/Chest/Dumbbell Decline Bench Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e86135fb-2516-4aab-8426-28d856363f1c'::uuid, 'Dumbbell decline fly', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by lying on a decline bench with your feet secured and holding a dumbbell in each hand, arms extended straight out to your sides at chest level with palms facing up.\r\n2. Raise the dumbbells up in a wide arc until your arms are straight above your chest, maintaining a slight bend in your elbows.\r\n3. Slowly lower your arms back out to the sides in a controlled motion, keeping the slight bend in your elbows, until your arms are level with your chest.\r\n4. Repeat the steps for the desired number of repetitions, maintaining control throughout the exercise.', E'1. Exhale as you raise the dumbbells and inhale as you lower them.\r\n2. Avoid locking your elbows; maintain a slight bend to protect your joints.\r\n3. Ensure your wrists remain straight and aligned with your forearms.', '{"image_male_start":"images/Chest/Dumbbell Decline Fly.jpg","image_male_end":"images/Chest/Dumbbell Decline Fly1.jpg","video_url":"videos/Chest/Dumbbell Decline Fly.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('783116b4-d52b-4081-ac9f-66115ab7262f'::uuid, 'Dumbbell Decline Hammer Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by lying on a decline bench with your feet secured and holding a dumbbell in each hand, arms bent and dumbbells by your sides with palms facing each other.\r\n2. Raise the dumbbells up over your chest, extending your arms fully without locking your elbows, keeping your elbows close to your body.\r\n3. Slowly lower the dumbbells back to the starting position by your sides in a controlled motion.\r\n4. Repeat the steps for the desired number of repetitions, maintaining control throughout the exercise.', E'1. Exhale as you press the dumbbells up and inhale as you lower them.\r\n2. Avoid locking your elbows; maintain a slight bend to protect your joints.\r\n3. Ensure your wrists remain straight and aligned with your forearms.', '{"image_male_start":"images/Chest/Dumbbell Decline Hammer Press.jpg","image_male_end":"images/Chest/Dumbbell Decline Hammer Press1.jpg","video_url":"videos/Chest/Dumbbell Decline Hammer Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d1d81f54-10ff-4515-aadf-c38a5b359f99'::uuid, 'Dumbbell Decline One Arm Hammer Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by lying on a decline bench with your feet secured, holding a dumbbell in one hand with your arm bent and the dumbbell by your side, palm facing inward. Place your other hand on the bench for stability.\r\n2. Raise the dumbbell up over your chest, extending your arm fully without locking your elbow, keeping your elbow close to your body.\r\n3. Slowly lower the dumbbell back to the starting position by your side in a controlled motion.\r\n4. Repeat the steps for the desired number of repetitions, then switch arms and repeat.', E'1. Exhale as you press the dumbbells up and inhale as you lower them.\r\n2. Avoid locking your elbows; maintain a slight bend to protect your joints.\r\n3. Hold the bench tightly with your free hand to ensure proper balance.', '{"image_male_start":"images/Chest/Dumbbell Decline One Arm Hammer Press.jpg","image_male_end":"images/Chest/Dumbbell Decline One Arm Hammer Press1.jpg","video_url":"videos/Chest/Dumbbell Decline One Arm Hammer Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ac1d7006-f93b-4081-9de4-806c1be019ea'::uuid, 'Dumbbell Decline Overhead Sit-up', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by lying on a decline bench with your feet secured, holding a dumbbell in each hand extended overhead.\r\n2. Slowly lift your shoulders, and upper back off the bench while simultaneously bringing the dumbbells up and over your head.\r\n3. Continue to lift your torso until you are in an upright position with the dumbbell directly above your head.\r\n4. Slowly lower yourself back down to the starting position, keeping the dumbbells extended overhead.', E'1. Keep your neck in a neutral position to avoid strain.\r\n2. Focus on a smooth and controlled motion to maximize core engagement.\r\n3. Avoid using momentum to lift yourself; rely on your core muscles.', '{"image_male_start":"images/Abdominals/Dumbbell Decline Overhead Sit-up.jpeg","video_url":"videos/Abdominals/Dumbbell Decline Overhead Sit-up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ea1bfeb8-e814-433d-86ac-d490a9c6c330'::uuid, 'Dumbbell Decline Shrug', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by lying chest first on an incline bench with your feet flat on the floor. Hold a dumbbell in each hand with your arms extended straight down toward the floor, palms facing each other.\r\n2. Allow your shoulders to relax downward, feeling a stretch in your upper traps.\r\n3. Lift your shoulders upward towards your ears, squeezing your shoulder blades together at the top of the movement.\r\n4. Inhale and slowly lower your shoulders back down to the starting position.', E'1. Avoid using your arms to lift the weights; focus on lifting with your shoulders.\r\n2. Concentrate on squeezing your shoulder blades together at the top of the movement.\r\n3. Ensure your head and neck remain in a neutral position to avoid strain.', '{"image_male_start":"images/Shoulders/Dumbbell Decline Shrug.jpg","image_male_end":"images/Shoulders/Dumbbell Decline Shrug1.jpg","video_url":"videos/Shoulders/Dumbbell Decline Shrug.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('97d26a19-70a7-4652-b42a-23fe4d79ceee'::uuid, 'Dumbbell Decline Sit-up', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by lying on a decline bench with your feet securely positioned under the footpads. Hold a dumbbell with both hands against your chest.\r\n2. Lift your upper body towards your knees, keeping the dumbbell close to your chest.\r\n3. Sit up fully until your back is straight, then slowly lower your upper body back to the starting position.\r\n4. Repeat the exercise for the desired number of repetitions.', E'1. Keep the dumbbell close to your chest throughout the exercise to maintain balance.\r\n2. Focus on engaging your abdominal muscles, not using momentum.\r\n3. Keep your head and neck in line with your spine to avoid strain.\r\n', '{"image_male_start":"images/Abdominals/Dumbbell Decline Sit-up.jpeg","video_url":"videos/Abdominals/Dumbbell Decline Sit-up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('efc5bcc4-22e5-4dca-9bcd-df2b6605942b'::uuid, 'Dumbbell Decline triceps pull-over extension', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie on a decline bench with your feet secured and hold a dumbbell with both hands, extending your arms straight above your chest.\r\n2. Slowly lower the dumbbell in an arc over your head, keeping your arms slightly bent at the elbows.\r\n3. Once your arms are almost parallel to the floor, bend your elbows to lower the dumbbells down to your head sides, and immediately straighten your elbows.\r\n4. Raise both dumbbells in an arc over your head to starting position. Repeat for the desired number of repetitions.', E'1. Avoid locking your elbows; maintain a slight bend to reduce joint strain.\r\n2. Perform the movement slowly to maximize muscle activation and control.\r\n3. Ensure a full range of motion for optimal muscle engagement.\r\n', '{"image_male_start":"images/Triceps/Dumbbell Decline triceps pull-over extension.jpeg","video_url":"videos/Triceps/Dumbbell Decline triceps pull-over extension.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('eee57e48-0226-4d68-95b8-f7740fda96c8'::uuid, 'Dumbbell Decline Twist Fly', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by lying on a decline bench with your feet secured and holding a dumbbell in each hand. Extend your arms straight out to your sides at chest level with palms facing each up.\r\n2. As you raise the dumbbells up in a wide arc, twist your wrists so that your palms face backward, bringing the dumbbells to meet above your chest while maintaining a slight bend in your elbows.\r\n3. Slowly lower your arms back out to the sides in a controlled motion, twisting your wrists back so that your palms face up, until your arms are level with your chest.\r\n4. Repeat the raising and lowering motion for the desired number of repetitions, maintaining control throughout the exercise.', E'1. Avoid locking your elbows; maintain a slight bend to protect your joints.\r\n2. Ensure your wrists remain straight and aligned with your forearms during the twist.\r\n3. Focus on a slow and controlled motion to maximize muscle engagement.', '{"image_male_start":"images/Chest/Dumbbell Decline Twist Fly.jpg","image_male_end":"images/Chest/Dumbbell Decline Twist Fly1.jpg","video_url":"videos/Chest/Dumbbell Decline Twist Fly.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d4425106-a76b-4639-81e2-eea334d3e358'::uuid, 'Dumbbell diagonal chop', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell with both hands extended opposite your chest.\r\n2. Rotate your torso and lower the dumbbell diagonally across your body to the left side, extending your arms fully as you reach downward, while pivoting your feet towards your left side.\r\n3. In a controlled motion, bring the dumbbell back up to the starting position, reversing the diagonal path.\r\n4. Repeat the movement for the desired number of repetitions, then switch sides and repeat.', E'1. Rotate your torso and pivot your feet to allow for a full range of motion.\r\n2. Maintain a firm grip on the dumbbell to ensure control.\r\n3. Perform the movement in a controlled manner to avoid swinging the dumbbell.', '{"image_male_start":"images/Abdominals/dumbbell diagonal chop.jpeg","video_url":"videos/Abdominals/dumbbell diagonal chop.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('48bb498b-8a15-42e4-93ea-0904f818a273'::uuid, 'Dumbbell Drag Over Shoulder Bicep Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your arms extended down by your sides.\r\n2. Begin the movement by curling the dumbbells up towards your shoulders while dragging your elbows backward, keeping them close to your body.\r\n3. Once the dumbbells are close to your shoulders, push them up slowly to pass the shoulders.\r\n4. Slowly lower the dumbbells back to the starting position, and repeat for the desired number of repetitions.', E'1. Maintain a slow and controlled motion, avoiding any swinging or momentum.\r\n2. Exhale as you curl the dumbbells up and inhale as you lower them back down.\r\n3. Keep your elbows close to your body throughout the movement to focus the effort on your biceps.', '{"image_male_start":"images/Biceps/Dumbbell Drag Over Shoulder Bicep Curl.jpeg","video_url":"videos/Biceps/Dumbbell Drag Over Shoulder Bicep Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f7d46312-0ff8-48d0-abf8-6ee048a0dbea'::uuid, 'Dumbbell external rotation', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in one hand. Keep your opposite hand behind your back for support.\r\n2. Start with your working arm bent at a 90-degree angle, elbow close to your side, forearm parallel to the floor facing forward with the dumbbell held in a neutral position.\r\n3. Rotate your forearm outward, keeping your elbow fixed in place, until your palm faces forward.\r\n4. Slowly return to the starting position, bringing your forearm back to starting position. Repeat for the desired number of repetitions, then switch arms.', E'1. Keep your wrist straight and aligned with your forearm to avoid strain.\r\n2. Avoid rotating your torso; focus on moving just your forearm.\r\n3. Perform the exercise in front of a mirror to ensure proper form and alignment.', '{"image_male_start":"images/Shoulders/Dumbbell External Rotation.jpg","image_male_end":"images/Shoulders/Dumbbell External Rotation1.jpg","video_url":"videos/Shoulders/Dumbbell External Rotation.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4ed07b38-8582-4be6-af35-e6c9b469b2ff'::uuid, 'Dumbbell face down lying shoulder press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie face down on a flat bench with your legs bent at 90 degrees and crossed together. Hold a dumbbell in each hand, with your arms bent and elbows pointing outwards at shoulder height.\r\n2. Begin with the dumbbells at shoulder level, palms facing the floor. Press the dumbbells forward by extending your arms until your arms are fully extended but not locked out.\r\n3. Slowly bring the dumbbells back to the starting position at shoulder level, maintaining control throughout the movement. \r\n4. Repeat for the desired number of repetitions.', E'1. Ensure your wrists remain straight and aligned with your forearms.\r\n2. Keep your chest and abdomen firmly against the bench to avoid arching your back.\r\n3. Use a weight that allows you to maintain proper form throughout the exercise.', '{"image_male_start":"images/Shoulders/Dumbbell Face Down Lying Shoulder Press.jpg","image_male_end":"images/Shoulders/Dumbbell Face Down Lying Shoulder Press1.jpg","video_url":"videos/Shoulders/Dumbbell Face Down Lying Shoulder Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0a5ca413-ee20-4c65-abf0-03882ac0ec52'::uuid, 'Dumbbell farmer walks', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by standing upright with a dumbbell in each hand, arms fully extended at your sides, and palms facing inward. Ensure your feet are hip-width apart.\r\n2. Engage your core and keep your chest up and shoulders back to maintain proper posture.\r\n3. Start walking forward, taking controlled, even steps, while maintaining a tight grip on the dumbbells.\r\n4. Walk for the desired distance or time, keeping your torso upright and your core engaged. Once you reach the end of the distance, turn around and walk back to the starting point.', E'1. Maintain an upright posture throughout the exercise to prevent strain on your lower back.\r\n2. Keep your shoulders back and down, avoiding any hunching or rounding of your shoulders.\r\n3. Use a firm grip on the dumbbells to ensure they do not slip from your hands.', '{"image_male_start":"images/Legs/dumbbell farmer walks.jpg","image_male_end":"images/Legs/dumbbell farmer walks1.jpg","video_url":"videos/Legs/dumbbell farmer walks.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('de96dd06-ffec-4a53-a6fa-c1e001673afa'::uuid, 'Dumbbell floor Fly', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by lying on your back on the floor with your legs straight on the floor. Hold a dumbbell in each hand with your arms extended straight above your chest, palms facing each other.\r\n2. Slowly lower the dumbbells out to your sides in a wide arc, keeping a slight bend in your elbows. Lower until your upper arms slightly touch the floor. \r\n3. Bring the dumbbells back up to the starting position by squeezing your chest muscles, maintaining the slight bend in your elbows throughout the movement.', E'1. Perform the movement in a slow and controlled manner to maximize muscle engagement.\r\n2. Exhale as you lift the dumbbells back up and inhale as you lower them.\r\n3. Avoid allowing the dumbbells to touch at the top to maintain tension in the chest muscles.', '{"image_male_start":"images/Chest/Dumbbell floor Fly.jpg","image_male_end":"images/Chest/Dumbbell floor Fly1.jpg","video_url":"videos/Chest/Dumbbell floor Fly.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f634bf58-7502-4a03-9213-cf16b8f88c50'::uuid, 'Dumbbell fly flat bench', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by lying on a flat bench with your feet flat on the floor for stability. Hold a dumbbell in each hand with your arms extended straight above your chest, palms facing each other.\r\n2. Lower the dumbbells out to your sides in a wide arc, maintaining a slight bend in your elbows. Lower until your upper arms are parallel to the floor or slightly below chest level.\r\n3. Bring the dumbbells back up to the starting position by squeezing your chest muscles, keeping the slight bend in your elbows throughout the movement.', E'1. Avoid allowing the dumbbells to touch at the top to maintain tension in the chest muscles.\r\n2. Keep your feet flat on the floor to provide stability and support.\r\n3. Ensure your wrists remain straight and aligned with your forearms.', '{"video_url":"videos/Chest/dumbbell fly flat bench.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('df3ff06a-50f6-45ea-a2aa-100abaaa9a4b'::uuid, 'Dumbbell fly flat bench slow', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by lying on a flat bench with your feet flat on the floor for stability. Hold a dumbbell in each hand with your arms extended straight above your chest, palms facing each other.\r\n2. Slowly lower the dumbbells out to your sides in a wide arc, maintaining a slight bend in your elbows. Lower until your upper arms are parallel to the floor or slightly below chest level.\r\n3. Slowly bring the dumbbells back up to the starting position by squeezing your chest muscles, keeping the slight bend in your elbows throughout the movement.', E'1. Avoid allowing the dumbbells to touch at the top to maintain tension in the chest muscles.\r\n2. Keep your feet flat on the floor to provide stability and support.\r\n3. Ensure your wrists remain straight and aligned with your forearms.', '{"image_male_start":"images/Chest/dumbbell fly flat bench slow.jpg","image_male_end":"images/Chest/dumbbell fly flat bench slow1.jpg","video_url":"videos/Chest/dumbbell fly flat bench slow.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0faae36a-92b8-4c21-b0fa-fec90343a27d'::uuid, 'Dumbbell fly incline bench', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie down on an incline bench with your feet flat on the floor. Hold a dumbbell in each hand and lie back on the bench with your arms extended straight above your chest, palms facing each other.\r\n2. Slowly lower the dumbbells out to your sides in a wide arc, maintaining a slight bend in your elbows. Lower until your upper arms are parallel to the floor or slightly below chest level.\r\n3. Bring the dumbbells back up to the starting position by squeezing your chest muscles, keeping the slight bend in your elbows throughout the movement.\r\n4. Repeat for the desired number of repetitions, maintaining control and proper form throughout the exercise.', E'1. Avoid allowing the dumbbells to touch at the top to maintain tension in the chest muscles.\r\n2. Keep your feet flat on the floor to provide stability and support.\r\n3. Ensure your wrists remain straight and aligned with your forearms.', '{"image_male_start":"images/Chest/dumbbell fly incline bench.jpg","image_male_end":"images/Chest/dumbbell fly incline bench1.jpg","video_url":"videos/Chest/dumbbell fly incline bench.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('93e4cd0b-d824-41df-be1d-be560cd6c039'::uuid, 'Dumbbell Front Rack Lunge', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by standing with your feet hip-width apart, holding a dumbbell in each hand. Rack the dumbbells on your shoulders by bending your elbows and positioning your upper arms parallel to the floor.\r\n2. Keep your chest up, and step forward with your right leg. Lower your body by bending both knees until your right thigh is parallel to the floor and your left knee is just above the floor.\r\n3. Push through your right heel to return to the starting position. Repeat the movement with your left leg.\r\n4. Continue alternating legs for the desired number of repetitions.', E'1. Keep your front foot flat on the floor and your back foot balanced on the ball of your foot.\r\n2. Focus on keeping your weight evenly distributed between both legs.\r\n3. Use a weight that allows for proper form and control throughout the exercise to prevent strain or injury.', '{"image_male_start":"images/Legs/Dumbbell Front Rack Lunge.jpg","image_male_end":"images/Legs/Dumbbell Front Rack Lunge1.jpg","video_url":"videos/Legs/Dumbbell Front Rack Lunge.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('fac73d9c-506a-4421-86ff-aeea2d04943a'::uuid, 'Dumbbell Front Raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet hip-width apart, holding a dumbbell in each hand with your arms fully extended by your sides and palms facing your thighs.\r\n2. Raise the dumbbells in front of you to shoulder height, keeping your arms straight and palms facing down.\r\n3. Pause briefly at the top of the movement, ensuring your shoulders are not shrugging up towards your ears.\r\n4. Slowly lower the dumbbells back to the starting position in a controlled manner. Repeat for the desired number of repetitions.', E'1. Avoid swinging the weights; use a controlled motion to lift and lower the dumbbells.\r\n2. Maintain a slight bend in your elbows to reduce joint strain.\r\n3. Keep your shoulders down and relaxed throughout the exercise.', '{"image_male_start":"images/Shoulders/Dumbbell Front Raise.jpg","image_male_end":"images/Shoulders/Dumbbell Front Raise1.jpg","video_url":"videos/Shoulders/Dumbbell Front Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('761002df-7996-460f-8336-c70520429981'::uuid, 'Dumbbell Front Raise (version 2)', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet hip-width apart, holding a dumbbell vertical with both hands, arms fully extended down.\r\n2. Raise the dumbbell in front of you to shoulder height, keeping your arms straight.\r\n3. Pause briefly at the top of the movement, ensuring your shoulders are not shrugging up towards your ears.\r\n4. Slowly lower the dumbbell back to the starting position in a controlled manner. Repeat for the desired number of repetitions.', E'1. Avoid swinging the weights; use a controlled motion to lift and lower the dumbbell.\r\n2. Maintain a slight bend in your elbows to reduce joint strain.\r\n3. Keep your shoulders down and relaxed throughout the exercise.', '{"image_male_start":"images/Shoulders/Dumbbell Front Raise (version 2).jpg","image_male_end":"images/Shoulders/Dumbbell Front Raise (version 2)1.jpg","video_url":"videos/Shoulders/Dumbbell Front Raise (version 2).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b35fa439-1464-4e70-937d-baa7f1132637'::uuid, 'Dumbbell Front Squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand and racking them on your shoulders with your elbows pointing forward.\r\n2. Begin the movement by pushing your hips back and bending your knees to lower into a squat position.\r\n3. Continue lowering yourself until your thighs are parallel to the floor, ensuring your knees stay in line with your toes and your back remains straight.\r\n4. Push through your heels to stand back up, extending your hips and knees fully to return to the starting position. Repeat for the desired number of repetitions.', E'1. Ensure your elbows stay up and forward to keep the dumbbells stable on your shoulders.\r\n2. Avoid letting your knees collapse inward; keep them aligned with your toes.\r\n3. Maintain a neutral spine and avoid rounding your back.', '{"image_male_start":"images/Legs/Dumbbell Front Squat.jpg","image_male_end":"images/Legs/Dumbbell Front Squat1.jpg","video_url":"videos/Legs/Dumbbell Front Squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a0f94141-65ac-4815-aa11-9482e458d684'::uuid, 'Dumbbell Glute Bridge', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by lying on your back with your knees bent and feet flat on the floor, hip-width apart. Place a dumbbell horizontally across your hips, holding it securely with both hands.\r\n2. Engage your core and glutes, and press through your heels to lift your hips toward the ceiling. Your body should form a straight line from your shoulders to your knees.\r\n3. Squeeze your glutes at the top of the movement, holding for a brief moment while keeping the dumbbell stable on your hips.\r\n4. Lower your hips back to the starting position in a controlled manner without letting your glutes touch the floor. Repeat for the desired number of repetitions.', E'1. Ensure your knees stay aligned with your toes and do not splay outwards.\r\n2. Focus on squeezing your glutes at the top to maximize muscle activation.\r\n3. Avoid arching your lower back; maintain a neutral spine.', '{"image_male_start":"images/Legs/Dumbbell Glute Bridge.jpg","image_male_end":"images/Legs/Dumbbell Glute Bridge1.jpg","video_url":"videos/Legs/Dumbbell Glute Bridge.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5077b684-3880-4dba-aad4-e36562ac7370'::uuid, 'Dumbbell Goblet 2 sec Hold Squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell vertically against your chest with both hands, between your palms. Keep your elbows pointed downward.\r\n2. Push your hips back and bend your knees until your thighs are just lower than parallel to the floor.\r\n3. Hold the squat position for 2 seconds, keeping your chest up and your weight distributed evenly through your heels.\r\n4. Push through your heels to return to the standing position, squeezing your glutes at the top. Repeat for the desired number of repetitions.', E'1. Ensure your knees track over your toes and do not cave inward during the squat.\r\n2. Focus on keeping your weight on your heels to engage your glutes and hamstrings.\r\n3. Maintain a neutral spine and avoid rounding your lower back.', '{"image_male_start":"images/Legs/Dumbbell Goblet 2 sec Hold Squat.jpg","image_male_end":"images/Legs/Dumbbell Goblet 2 sec Hold Squat1.jpg","video_url":"videos/Legs/Dumbbell Goblet 2 sec Hold Squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2408f36c-be04-4e2f-81de-cda316c59cc2'::uuid, 'Dumbbell Goblet Curtsy Lunge', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet hip-width apart, holding a dumbbell vertically against your chest with both hands, between your palms. Keep your elbows pointed downward.\r\n2. Step your right foot behind and to the outside of your left foot, lowering your body into a curtsy lunge.\r\n3. Bend both knees until your right knee almost touches the floor. Keep your chest up and your weight evenly distributed.\r\n4. Push through your left heel to return to the starting position. Repeat on the opposite side.', E'1. Ensure your front knee tracks over your toes and does not extend past your toes during the lunge.\r\n2. Focus on keeping your weight on your front heel to engage your glutes and hamstrings.\r\n3. Maintain a neutral spine and avoid rounding your lower back.', '{"image_male_start":"images/Legs/Dumbbell Goblet Curtsy Lunge.jpg","image_male_end":"images/Legs/Dumbbell Goblet Curtsy Lunge1.jpg","video_url":"videos/Legs/Dumbbell Goblet Curtsy Lunge.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0350dd22-b875-4463-8ff1-418b9413feef'::uuid, 'Dumbbell Goblet Split Squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell vertically against your chest with both hands, between your palms. Keep your elbows pointed downward.\r\n2. Step your right foot forward into a split stance, ensuring your left foot remains stationary and slightly elevated on your forefoot.\r\n3. Lower your body by bending both knees to approximately 90 degrees, keeping your chest up and back straight. Your right knee should be directly above your right ankle, and your left knee should hover just above the floor.\r\n4. Push through your right heel to return to the starting position. Complete the desired number of repetitions on one side before switching to the other leg.', E'1. Ensure your front knee tracks over your toes and does not extend beyond them.\r\n2. Maintain a straight back and avoid leaning forward or rounding your shoulders.\r\n3. Focus on keeping your weight distributed evenly between both feet during the squat.', '{"image_male_start":"images/Legs/Dumbbell Goblet Split Squat.jpg","image_male_end":"images/Legs/Dumbbell Goblet Split Squat1.jpg","video_url":"videos/Legs/Dumbbell Goblet Split Squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d0296ee7-e43f-4967-be42-3b5ea3d8eb41'::uuid, 'Dumbbell Goblet Split Squat Front Foot Elevanted', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell vertically against your chest with both hands, between your palms. Keep your elbows pointed downward.\r\n2. Place your right foot on a step, while keeping your left leg extended on your forefoot on the floor behind you.\r\n3. Lower your body by bending the front knee to approximately 90 degrees. Your left knee should hover just above the floor.\r\n4. Push through your right heel to return to the starting position. Complete the desired number of repetitions on one side before switching to the other leg.', E'1. Ensure your front knee tracks over your toes and does not extend beyond them.\r\n2. Use a high enough step to perform the exercise comfortably.\r\n3. Focus on keeping your weight distributed evenly between both feet during the squat.', '{"image_male_start":"images/Legs/Dumbbell Goblet Split Squat Front Foot Elevanted.jpg","image_male_end":"images/Legs/Dumbbell Goblet Split Squat Front Foot Elevanted1.jpg","video_url":"videos/Legs/Dumbbell Goblet Split Squat Front Foot Elevanted.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('cd56cb5a-648c-4c93-b6ec-5bee84d3537f'::uuid, 'Dumbbell Goblet Squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell vertically against your chest with both hands, between your palms. Keep your elbows pointed downward.\r\n2. Push your hips back and bend your knees, making sure to keep your weight on your heels.\r\n3. Continue lowering yourself until your thighs are at least parallel to the floor, or as low as your mobility allows, while maintaining a straight back and keeping the dumbbell close to your chest.\r\n4. Push through your heels to return to the starting position, straightening your legs and extending your hips fully at the top.', E'1. Ensure your knees track over your toes and do not cave inward.\r\n2. Maintain a neutral spine and avoid rounding your back.\r\n3. Focus on pushing through your heels to engage your glutes and quadriceps effectively.', '{"image_male_start":"images/Legs/Dumbbell Goblet Squat.jpg","image_male_end":"images/Legs/Dumbbell Goblet Squat1.jpg","video_url":"videos/Legs/Dumbbell Goblet Squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('70f1c4cb-bc36-403d-884a-f973080b5436'::uuid, 'Dumbbell Half Biceps Curl for 21s', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing forward. Start with your arms fully extended by your sides.\r\n2. Curl the dumbbells upward until your elbows are at a 90-degree angle, stopping halfway up. Hold for a brief moment.\r\n3. Lower the dumbbells back to the starting position with a controlled motion.\r\n4. Repeat this half curl motion for the desired number of repetitions.', E'1. Avoid swinging your body or using momentum to lift the weights.\r\n2. Exhale as you curl the dumbbells up and inhale as you lower them.\r\n3. Ensure your wrists remain straight and aligned with your forearms.', '{"image_male_start":"images/Biceps/Dumbbell Half Biceps Curl for 21s.jpeg","video_url":"videos/Biceps/Dumbbell Half Biceps Curl for 21s.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('06032857-b1df-41f2-8e21-cfb1c634bc46'::uuid, 'Dumbbell half kneeling military press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin in a half-kneeling position with your right knee on the floor and left foot flat on the floor in front of you. Hold a dumbbell in each hand at shoulder level with your palms facing forward.\r\n2. Engage your core and press both dumbbells upward until your arms are fully extended overhead.\r\n3. Slowly lower the dumbbells back to shoulder level with control, maintaining a steady motion.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep your gaze forward and your neck in a neutral position.\r\n2. Exhale as you press the dumbbells up and inhale as you lower them.\r\n3. Ensure your front knee remains aligned over your ankle to maintain balance.', '{"image_male_start":"images/Shoulders/dumbbell half kneeling military press.jpg","image_male_end":"images/Shoulders/dumbbell half kneeling military press1.jpg","video_url":"videos/Shoulders/dumbbell half kneeling military press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9eba1776-8034-4121-ba1e-3ba96fecdb18'::uuid, 'Dumbbell Hammer Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with a neutral grip (palms facing your torso). Let your arms hang straight down at your sides.\r\n2. Curl the dumbbell in your right hand upward towards your shoulder by bending your elbow, focusing on engaging your biceps.\r\n3. Squeeze your biceps at the top of the movement, ensuring the dumbbell reaches shoulder height.\r\n4. Lower the dumbbell back to the starting position with control, fully extending your arm. Repeat the movement with your left arm.', E'1. Avoid using momentum; focus on a controlled motion.\r\n2. Keep your back straight and core engaged to prevent swaying.\r\n3. Maintain a neutral wrist position to reduce strain on your joints.', '{"image_male_start":"images/Biceps/Dumbbell Hammer Curl.jpeg","video_url":"videos/Biceps/Dumbbell Hammer Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b05155ec-bcb2-406f-bfed-4879d110b751'::uuid, 'Dumbbell Hammer Curl Simultaneous Arms', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with a neutral grip (palms facing your torso). Let your arms hang straight down at your sides.\r\n2. Simultaneously curl both dumbbells upward towards your shoulders by bending your elbows, focusing on engaging your biceps and forearms.\r\n3. Squeeze your biceps at the top of the movement, ensuring the dumbbells reach shoulder height.\r\n4. Lower the dumbbells back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Avoid using momentum; focus on a controlled motion.\r\n2. Keep your back straight and core engaged to prevent swaying.\r\n3. Maintain a neutral wrist position to reduce strain on your joints.', '{"image_male_start":"images/Biceps/Dumbbell Hammer Curl Simultaneous Arms.jpeg","video_url":"videos/Biceps/Dumbbell Hammer Curl Simultaneous Arms.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5c52fa3d-c5c4-42bd-ade0-14666225f06b'::uuid, 'Dumbbell Hammer Grip Incline Bench Two Arm Row', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Adjust an incline bench to a 45-degree angle. Lie face down on the bench with your feet firmly on the floor. Hold a dumbbell in each hand using a hammer grip (palms facing each other).\r\n2. Let your arms hang straight down toward the floor, fully extended, with your elbows slightly bent.\r\n3. Pull the dumbbells towards your torso by bending your elbows and squeezing your shoulder blades together.\r\n4. Pause briefly at the top of the movement, then slowly lower the dumbbells back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Avoid using momentum; perform the movement in a slow and controlled manner.\r\n2. Exhale as you pull the dumbbells towards your torso and inhale as you lower them.\r\n3. Keep your feet firmly planted on the floor for stability.', '{"image_male_start":"images/Back/Dumbbell Hammer Grip Incline Bench Two Arm Row.jpg","image_male_end":"images/Back/Dumbbell Hammer Grip Incline Bench Two Arm Row1.jpg","video_url":"videos/Back/Dumbbell Hammer Grip Incline Bench Two Arm Row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('92695cc6-f496-4caa-b725-77e113d5d6bd'::uuid, 'Dumbbell Hammer Preacher Curl Simultaneous Arms', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a preacher bench with your chest pressed against the pad, feet flat on the floor, and hold a dumbbell in each hand using a hammer grip (palms facing each other).\r\n2. Extend your arms fully over the bench pad, keeping a slight bend in your elbows to maintain tension on your biceps.\r\n3. Curl both dumbbells simultaneously towards your shoulders by bending your elbows, focusing on engaging your biceps. Squeeze your biceps at the top of the movement, ensuring the dumbbells reach shoulder height.\r\n4. Lower the dumbbells back to the starting position with control, fully extending your arms over the bench pad. Repeat for the desired number of repetitions.', E'1. Keep your upper arms pressed against the pad to isolate your biceps.\r\n2. Avoid using momentum; perform the movement in a slow and controlled manner.\r\n3. Exhale as you curl the dumbbells towards your shoulders and inhale as you lower them.', '{"image_male_start":"images/Biceps/Dumbbell Hammer Preacher Curl Simultaneous Arms.jpeg","video_url":"videos/Biceps/Dumbbell Hammer Preacher Curl Simultaneous Arms.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7058f61b-2296-4816-8a6c-330ca10588ab'::uuid, 'Dumbbell Hammer Strict Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your back fully supported against a wall, feet shoulder-width apart, and hold a dumbbell in each hand using a hammer grip (palms facing each other).\r\n2. Keep your arms extended straight down by your sides, with your upper arms and elbows pressed against the wall.\r\n3. Engage your core and curl both dumbbells simultaneously towards your shoulders by bending your elbows, focusing on engaging your biceps. Squeeze your biceps at the top of the movement, ensuring the dumbbells reach shoulder height.\r\n4. Lower the dumbbells back to the starting position with control, fully extending your arms down by your sides. Repeat for the desired number of repetitions.', E'1. Keep your upper arms and elbows pressed against the wall to isolate your biceps.\r\n2. Avoid using momentum; perform the movement in a slow and controlled manner.\r\n3. Ensure your back remains flat against the wall for stability.', '{"image_male_start":"images/Biceps/Dumbbell Hammer Strict Curl.jpeg","video_url":"videos/Biceps/Dumbbell Hammer Strict Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('beef7a70-54c9-4121-8513-1df426680204'::uuid, 'Dumbbell Hang Power Clean', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin in a squat position with your feet shoulder-width apart, holding a dumbbell in each hand with a neutral grip (palms facing each other), letting the dumbbells hang close to your shins.\r\n2. Explosively extend your hips and knees, shrugging your shoulders as you pull the dumbbells upward.\r\n3. As the dumbbells reach chest height, quickly rotate your wrists and elbows to catch the dumbbells on your shoulders while dropping into a partial squat.\r\n4. Stand up by extending your hips and knees, bringing the dumbbells to shoulder height. Lower the dumbbells back to the starting position with control and repeat for the desired number of repetitions.', E'1. Use your hips and knees to generate power for the lift, not your lower back.\r\n2. Move explosively during the upward phase and catch the dumbbells with control.\r\n3. Avoid locking your knees; keep a slight bend to protect your joints.', '{"image_male_start":"images/Powerlifting/Dumbbell Hang Power Clean.jpg","image_male_end":"images/Powerlifting/Dumbbell Hang Power Clean1.jpg","video_url":"videos/Powerlifting/Dumbbell Hang Power Clean.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a78df172-c3fc-49b2-b553-aedf44ce12ae'::uuid, 'Dumbbell High Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an underhand grip (palms facing up). Extend both arms straight out at shoulder level, keeping the dumbbells facing up.\r\n2. Curl the dumbbells upward towards your shoulders by bending your elbows.\r\n3. Squeeze your biceps at the top of the movement, ensuring the dumbbells reach close to your shoulders.\r\n4. Extend the dumbbells back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Keep your elbows in line with your shoulders and avoid swinging the weights.\r\n2. Use a controlled motion to prevent momentum from assisting the lift.\r\n3. Focus on contracting your biceps throughout the movement.', '{"image_male_start":"images/Biceps/Dumbbell High Curl.jpeg","video_url":"videos/Biceps/Dumbbell High Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e27d8c6f-53a8-468f-9dff-1e172a4fcf2a'::uuid, 'Dumbbell Hip Thrust', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on the floor with your upper back resting against a bench, knees bent, and feet flat on the floor. Hold a dumbbell with each hand across your hips.\r\n2. Press through your heels to lift your hips upward until your body forms a straight line from your shoulders to your knees.\r\n3. Hold the top position for a moment, ensuring your glutes are fully contracted.\r\n4. Lower your hips back down to the starting position with control. Repeat for the desired number of repetitions.', E'1. Press through your heels to maximize glute activation.\r\n2. Avoid arching your lower back; maintain a neutral spine.\r\n3. Focus on squeezing your glutes at the top of the movement.', '{"image_male_start":"images/Legs/Dumbbell Hip Thrust.jpg","image_male_end":"images/Legs/Dumbbell Hip Thrust1.jpg","video_url":"videos/Legs/Dumbbell Hip Thrust.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d8c1f261-5696-4701-a457-87d5a17faa0e'::uuid, 'Dumbbell Hip Thrust (VERSION 2)', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on the floor with your upper back resting against a bench, knees bent, and feet flat on the floor. Place a dumbbell across your hips, holding it with both hands for stability.\r\n2. Press through your heels to lift your hips upward until your body forms a straight line from your shoulders to your knees.\r\n3. Hold the top position for a moment, ensuring your glutes are fully contracted.\r\n4. Lower your hips back down to the starting position with control. Repeat for the desired number of repetitions.', E'1. Press through your heels to maximize glute activation.\r\n2. Avoid arching your lower back; maintain a neutral spine.\r\n3. Ensure the dumbbell is secure on your hips to avoid shifting during the exercise.', '{"image_male_start":"images/Legs/Dumbbell Hip Thrust (VERSION 2).jpg","image_male_end":"images/Legs/Dumbbell Hip Thrust (VERSION 2)1.jpg","video_url":"videos/Legs/Dumbbell Hip Thrust (VERSION 2).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3ecd7fb8-224f-4a8e-a0b2-f5e835e71f4c'::uuid, 'Dumbbell Incline Alternate Bicep Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on an incline bench set at a 45-degree angle, holding a dumbbell in each hand with your arms fully extended and palms facing forward.\r\n2. Curl the right dumbbell upward towards your shoulder by bending your elbow, focusing on engaging your biceps.\r\n3. Squeeze your biceps at the top of the movement, ensuring the dumbbell reaches shoulder height.\r\n4. Lower the right dumbbell back to the starting position with control while simultaneously starting to curl the left dumbbell upward. Continue alternating arms for the desired number of repetitions.', E'1. Keep your upper arms stationary to isolate the biceps.\r\n2. Maintain a controlled motion to prevent swinging or using momentum.\r\n3. Exhale as you curl the dumbbell upward and inhale as you lower it.', '{"image_male_start":"images/Biceps/Dumbbell Incline Alternate Bicep Curl.jpeg","video_url":"videos/Biceps/Dumbbell Incline Alternate Bicep Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b2cb3ea5-fad1-452e-af45-567901fc6001'::uuid, 'Dumbbell Incline Alternate Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on an incline bench set at a 45-degree angle, holding a dumbbell in each hand with your arms fully extended and palms facing each other.\r\n2. Curl the right dumbbell upward towards your shoulder by bending your elbow and rotating your wrist so that your palm faces up.\r\n3. Squeeze your biceps at the top of the movement, ensuring the dumbbell reaches shoulder height.\r\n4. Lower the right dumbbell back to the starting position with control, rotating the wrist as you curl. Continue alternating arms for the desired number of repetitions.', E'1. Keep your upper arms stationary to isolate the biceps.\r\n2. Maintain a controlled motion to prevent swinging or using momentum.\r\n3. Exhale as you curl the dumbbell upward and inhale as you lower it.', '{"image_male_start":"images/Biceps/Dumbbell Incline Alternate Curl.jpeg","video_url":"videos/Biceps/Dumbbell Incline Alternate Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9fa35d43-8d8d-4dc4-a874-3917a35f96c2'::uuid, 'Dumbbell Incline Alternate Hammer Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on an incline bench set at a 45-degree angle, holding a dumbbell in each hand with your arms fully extended and palms facing each other.\r\n2. Curl the right dumbbell upward towards your shoulder by bending your elbow, keeping your palms facing each other.\r\n3. Squeeze your biceps at the top of the movement, ensuring the dumbbell reaches shoulder height.\r\n4. Lower the right dumbbell back to the starting position, maintaining the hammer grip. Continue alternating arms for the desired number of repetitions.', E'1. Keep your upper arms stationary to isolate the biceps.\r\n2. Maintain a controlled motion to prevent swinging or using momentum.\r\n3. Exhale as you curl the dumbbell upward and inhale as you lower it.', '{"image_male_start":"images/Biceps/Dumbbell Incline Alternate Hammer Curl.jpeg","video_url":"videos/Biceps/Dumbbell Incline Alternate Hammer Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('02c72ff2-5197-425f-b7bb-1c7e24afa071'::uuid, 'Dumbbell Incline Alternate Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie on an incline bench set at a 45-degree angle, holding a dumbbell in each hand with your arms bent and dumbbells positioned near your chest.\r\n2. Press the right dumbbell upward until your arm is fully extended, keeping your palm facing forward.\r\n3. Lower the right dumbbell back to the starting position with control while simultaneously starting to press the left dumbbell upward, maintaining proper form.\r\n4. Continue alternating arms for the desired number of repetitions.', E'1. Ensure your wrists remain straight and aligned with your forearms.\r\n2. Avoid locking your elbows at the top of the press to protect your joints.\r\n3. Use a weight that allows for proper form and control.', '{"image_male_start":"images/Chest/Dumbbell Incline Alternate Press.jpg","image_male_end":"images/Chest/Dumbbell Incline Alternate Press1.jpg","video_url":"videos/Chest/Dumbbell Incline Alternate Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('72cec015-a3b2-4c1e-b5a8-f968c8a5efd5'::uuid, 'Dumbbell Incline Bench Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on an incline bench set at a 45-degree angle, holding a dumbbell in each hand with your arms bent and dumbbells positioned near your chest.\r\n2. Press both dumbbells upward until your arms are fully extended, keeping your palms facing forward.\r\n3. Lower the dumbbells back to the starting position with control.\r\n4. Repeat the pressing motion for the desired number of repetitions.', E'1. Ensure your wrists remain straight and aligned with your forearms.\r\n2. Avoid locking your elbows at the top of the press to protect your joints.\r\n3. Use a weight that allows for proper form and control.', '{"image_male_start":"images/Chest/Dumbbell Incline Bench Press.jpg","image_male_end":"images/Chest/Dumbbell Incline Bench Press1.jpg","video_url":"videos/Chest/Dumbbell Incline Bench Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d8b0e091-752e-4ada-8f45-ed87604710d0'::uuid, 'Dumbbell Incline Biceps Simultaneous Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on an incline bench set at a 45-degree angle, holding a dumbbell in each hand with your arms fully extended and palms facing forward.\r\n2. Curl both dumbbells simultaneously towards your shoulders by bending your elbows.\r\n3. Squeeze your biceps at the top of the movement, ensuring the dumbbells reach shoulder height.\r\n4. Lower the dumbbells back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Avoid using momentum; maintain a controlled motion throughout the exercise.\r\n2. Ensure your wrists remain straight and aligned with your forearms.\r\n3. Use a weight that allows for proper form and control.', '{"image_male_start":"images/Biceps/Dumbbell Incline Biceps Simultaneous Curl.jpeg","video_url":"videos/Biceps/Dumbbell Incline Biceps Simultaneous Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0b852a3d-803b-4f31-8f18-408d90925faa'::uuid, 'Dumbbell Incline Breeding', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on an incline bench set at a 45-degree angle, holding a dumbbell in each hand with your arms extended, elbows slightly bent, above your chest and palms facing forward.\r\n2. Slowly lower the dumbbells to your sides in a wide arc, maintaining the slight bend in your elbows.\r\n3. Bring the dumbbells back up in a controlled manner, following the same wide arc, until they meet above your chest.\r\n4. Repeat the movement for the desired number of repetitions, ensuring a controlled and steady motion throughout.', E'1. Avoid locking your elbows; maintain a slight bend to protect your joints.\r\n2. Ensure your wrists remain straight and aligned with your forearms.\r\n3. Focus on a slow and controlled motion to maximize muscle engagement.', '{"image_male_start":"images/Shoulders/Dumbbell Incline Breeding.jpg","image_male_end":"images/Shoulders/Dumbbell Incline Breeding1.jpg","video_url":"videos/Shoulders/Dumbbell Incline Breeding.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('783c3bb7-bef0-45ed-8c3e-dd47efe8bea4'::uuid, 'Dumbbell Incline Fly', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie on an incline bench set at a 45-degree angle, holding a dumbbell in each hand with your arms extended straight out to your sides at chest level, palms facing up.\r\n2. Engage your core and bring the dumbbells up in a controlled manner, following a wide arc, until they meet above your chest, maintaining a slight bend in your elbows.\r\n3. Slowly lower the dumbbells back out to your sides in a wide arc until your arms are level with your chest.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Exhale as you raise the dumbbells and inhale as you lower them.\r\n2. Avoid locking your elbows; maintain a slight bend to protect your joints.\r\n3. Ensure your wrists remain straight and aligned with your forearms.', '{"video_url":"videos/Chest/Dumbbell Incline Fly.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4280ec03-c7a5-499b-b36b-984463f483ba'::uuid, 'Dumbbell Incline Fly on Exercise Ball', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on an exercise ball and walk your feet forward until your middle back is supported on the ball, feet slightly wider than shoulder-width, hinge your hips to form a 90 degree angle with your torso. \r\n2. Hold a dumbbell in each hand with your arms extended straight out to your sides at chest level, palms facing up. Bring the dumbbells up in a controlled manner, following a wide arc, until they meet above your chest.\r\n3. Slowly lower the dumbbells back out to your sides in a wide arc until your arms are level with your chest.\r\n4. Repeat the movement for the desired number of repetitions, ensuring a controlled and steady motion throughout.', E'1. Keep your back supported on the ball and your hips lowered to maintain a stable position.\r\n2. Engage your core to stabilize your body and maintain proper form.\r\n3. Exhale as you raise the dumbbells and inhale as you lower them.', '{"image_male_start":"images/Chest/Dumbbell Incline Fly on Exercise Ball.jpg","image_male_end":"images/Chest/Dumbbell Incline Fly on Exercise Ball1.jpg","video_url":"videos/Chest/Dumbbell Incline Fly on Exercise Ball.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b4ca1152-3a9a-44cb-a2e3-2e7054baff33'::uuid, 'Dumbbell Incline Front Raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie on an incline bench set at a 45-degree angle with a dumbbell in each hand, arms straight, and palms facing down just over your thighs. \r\n2. Raise both dumbbells in front of you, keeping your arms straight, until they reach opposite your chest.\r\n3. Hold the position for a second, then slowly lower the dumbbells back to the starting position with control.\r\n4. Repeat the movement for the desired number of repetitions, maintaining a steady and controlled motion.', E'1. Avoid using momentum; focus on using your shoulder muscles to lift the weights.\r\n2. Engage your core to stabilize your body and prevent arching of the back.\r\n3. Exhale as you lift the dumbbells and inhale as you lower them.\r\n', '{"image_male_start":"images/Shoulders/Dumbbell Incline Front Raise.jpg","image_male_end":"images/Shoulders/Dumbbell Incline Front Raise1.jpg","video_url":"videos/Shoulders/Dumbbell Incline Front Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5ffaa620-5592-41ba-9e82-5370d843a6d0'::uuid, 'Dumbbell Incline Hammer Shoulder Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie on an incline bench set at a 45-degree angle with your feet flat on the floor. Hold a dumbbell in each hand at shoulder height with your palms facing each other (hammer grip) and elbows bent and set perpendicular to your torso.\r\n2. Press the dumbbells forward in a controlled motion until your arms are fully extended opposite your chest, maintaining the hammer grip.\r\n3. Return the dumbbells back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Ensure your wrists remain straight and aligned with your forearms.\r\n2. Choose a weight that allows for proper form and control.\r\n3. Focus on using your shoulder muscles to lift the weights, minimizing involvement from your chest.', '{"image_male_start":"images/Shoulders/Dumbbell Incline Hammer Shoulder Press.jpg","image_male_end":"images/Shoulders/Dumbbell Incline Hammer Shoulder Press1.jpg","video_url":"videos/Shoulders/Dumbbell Incline Hammer Shoulder Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c20bce17-8b0b-4294-adf4-01d2bbd0bba7'::uuid, 'Dumbbell Incline Hammer Simultaneous Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie on an incline bench set at a 45-degree angle with your feet flat on the floor. Hold a dumbbell in each hand with your arms fully extended and palms facing each other (hammer grip).\r\n2. Curl both dumbbells simultaneously towards your shoulders by bending your elbows, keeping your palms facing each other.\r\n3. Squeeze your biceps at the top of the movement, ensuring the dumbbells reach shoulder height.\r\n4. Lower the dumbbells back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Avoid swinging the dumbbells; use a slow and controlled motion.\r\n2. Keep your elbows close to your body throughout the movement.\r\n3. Ensure your wrists remain straight and aligned with your forearms.', '{"image_male_start":"images/Biceps/Dumbbell Incline Hammer Simultaneous Curl.jpeg","video_url":"videos/Biceps/Dumbbell Incline Hammer Simultaneous Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8cab0faf-1315-4efd-b94c-091272802e66'::uuid, 'Dumbbell Incline Lying Front Raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie chest-first on an incline bench set at a 45-degree angle with your forefeet firm on the floor, allowing your arms to hang straight down with a dumbbell in each hand, palms facing back.\r\n2. Raise both dumbbells forward and upward until your arms are in level with your torso, maintaining a slight bend in your elbows.\r\n3. Squeeze your shoulder muscles at the top of the movement, ensuring your arms are fully extended.\r\n4. Lower the dumbbells back to the starting position with control, allowing your arms to hang down. Repeat for the desired number of repetitions.', E'1. Exhale as you raise the dumbbells and inhale as you lower them.\r\n2. Avoid swinging the dumbbells; use a slow and controlled motion.\r\n3. Maintain a slight bend in your elbows throughout the movement.', '{"image_male_start":"images/Shoulders/Dumbbell Incline Lying Front Raise.jpg","image_male_end":"images/Shoulders/Dumbbell Incline Lying Front Raise1.jpg","video_url":"videos/Shoulders/Dumbbell Incline Lying Front Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8b763dcb-4ebd-4343-bc54-cf2e02f05cde'::uuid, 'Dumbbell Incline One Arm Lateral Raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Set an incline bench to a 45-degree angle and lie on your side with your lower arm resting on the bench. Hold a dumbbell with your upper hand, arm extended at your side with your palm facing your body.\r\n2. Raise the dumbbell up in an arc motion until your arm is straight at shoulder level.\r\n3. Lower the dumbbell back to the starting position with control. Repeat for the desired number of repetitions, then switch to the other side.', E'1. Exhale as you lift the dumbbell and inhale as you lower it.\r\n2. Hold the bench edge with your free hand to supportyour body during the exercise.\r\n3. Maintain a slight bend in your elbow throughout the movement to reduce strain on the joint.', '{"image_male_start":"images/Shoulders/Dumbbell Incline One Arm Lateral Raise.jpg","image_male_end":"images/Shoulders/Dumbbell Incline One Arm Lateral Raise1.jpg","video_url":"videos/Shoulders/Dumbbell Incline One Arm Lateral Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c1049c55-36ee-44c2-90dc-b89c17fc5302'::uuid, 'Dumbbell Incline One Arm Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Set an incline bench to a 45-degree angle and sit back against it, holding a dumbbell in one hand at shoulder height with your palm facing forward. Your other arm can hold the bench for stability.\r\n2. Press the dumbbell upward until your arm is fully extended above your upper chest.\r\n3. Lower the dumbbell back to shoulder height with control, keeping your elbow at a 45-degree angle to your body. Repeat for the desired number of repetitions before switching to the other arm.', E'1. Avoid locking your elbow at the top of the movement; maintain a slight bend.\r\n2. Hold the bench edge with your free hand to supportyour body during the exercise.\r\n3. Choose a weight that allows for proper form and control throughout the exercise.', '{"image_male_start":"images/Chest/Dumbbell Incline One Arm Press.jpg","image_male_end":"images/Chest/Dumbbell Incline One Arm Press1.jpg","video_url":"videos/Chest/Dumbbell Incline One Arm Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('84446d8f-137a-4b19-b165-090403b86eeb'::uuid, 'Dumbbell Incline Palms Back Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Set an incline bench to a 45-degree angle and sit back against it, holding a dumbbell in each hand at shoulder height with elbows bent and facing the floor, with an underhand grip (palms facing back).\r\n2. Press the dumbbells upward until your arms are fully extended above your chest, maintaining the underhand grip.\r\n3. Lower the dumbbells back to shoulder height with control, keeping your elbows close to your body. Repeat for the desired number of repetitions.', E'1. Exhale as you press the dumbbells upward and inhale as you lower them.\r\n2. Choose a weight that allows for proper form and control throughout the exercise.\r\n3. Use a controlled motion, focusing on the muscles being worked.\r\n', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8a5c4a26-229a-44be-a23e-e2d6837b5ac8'::uuid, 'Dumbbell Incline Rear Lateral Raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Set an incline bench to a 45-degree angle and lie chest-first against it, allowing your arms to hang down with a dumbbell in each hand, palms facing each other.\r\n2. Raise both arms out to the sides until they are at shoulder height, squeezing your shoulder blades together.\r\n3. Hold briefly at the top of the movement, ensuring your arms are parallel to the floor and in line with your shoulders.\r\n4. Lower the dumbbells back to the starting position with control, maintaining the slight bend in your elbows. Repeat for the desired number of repetitions.', E'1. Keep a slight bend in your elbows throughout the exercise to protect your joints.\r\n2. Ensure your wrists remain straight and aligned with your forearms.\r\n3. Select a weight that allows for proper form and control throughout the exercise.', '{"image_male_start":"images/Shoulders/Dumbbell Incline Rear Lateral Raise.jpg","image_male_end":"images/Shoulders/Dumbbell Incline Rear Lateral Raise1.jpg","video_url":"videos/Shoulders/Dumbbell Incline Rear Lateral Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('092b68f2-ea68-4507-87bb-3dc86680514f'::uuid, 'Dumbbell Incline Row', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Set an incline bench to a 45-degree angle and lie chest-first against it, allowing your arms to extend opposite your chest with a dumbbell in each hand, palms facing down.\r\n2. Row both dumbbells backward by bending your elbows and pulling them towards your sides.\r\n3. Return the dumbbells back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Use a slow and controlled motion to maximize muscle engagement and avoid swinging.\r\n2. Ensure your wrists remain straight and aligned with your forearms.\r\n3. Select a weight that allows for proper form and control throughout the exercise.\r\n', '{"image_male_start":"images/Back/Dumbbell Incline Row.jpg","image_male_end":"images/Back/Dumbbell Incline Row1.jpg","video_url":"videos/Back/Dumbbell Incline Row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6ccf0752-3631-4931-ac94-c90bd91250f3'::uuid, 'Dumbbell Incline Shrug', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Set an incline bench to a 45-degree angle and sit back against it, holding a dumbbell in each hand with your arms extended at your sides, palms facing each other.\r\n2. Shrug your shoulders upward, lifting the dumbbells towards your ears, without bending your elbows.\r\n3. Slowly lower your shoulders back to the starting position, maintaining control throughout the movement. Repeat for the desired number of repetitions.', E'1. Exhale as you shrug your shoulders upward and inhale as you lower them.\r\n2. Focus on lifting your shoulders straight up and down, avoiding any circular or forward motion.\r\n3. Use a slow and controlled motion to maximize muscle engagement and avoid swinging.', '{"image_male_start":"images/Shoulders/Dumbbell Incline Shrug.jpg","image_male_end":"images/Shoulders/Dumbbell Incline Shrug1.jpg","video_url":"videos/Shoulders/Dumbbell Incline Shrug.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e33543ab-29ae-4550-afbe-eaf5aead7fd6'::uuid, 'Dumbbell Incline Simultaneous Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Set an incline bench to a 45-degree angle and sit back against it, holding a dumbbell in each hand with your arms fully extended down, palms facing forward.\r\n2. Simultaneously curl both dumbbells upward towards your shoulders by bending your elbows.\r\n3. Squeeze your biceps at the top of the movement, ensuring the dumbbells reach shoulder height.\r\n4. Lower the dumbbells back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Focus on lifting the weights using your biceps, avoiding shoulder involvement.\r\n2. Use a slow and controlled motion to maximize muscle engagement and avoid swinging.\r\n3. Ensure your wrists remain straight and aligned with your forearms.\r\n4. Avoid locking your elbows at the bottom of the movement to keep tension on the muscles.', '{"image_male_start":"images/Biceps/Dumbbell Incline Simultaneous Curl.jpeg","video_url":"videos/Biceps/Dumbbell Incline Simultaneous Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('eb7090f5-7468-4248-bd6a-8d607d81913a'::uuid, 'Dumbbell Incline Squeeze Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Set an incline bench to a 45-degree angle and lie back against it, holding a dumbbell in each hand with your palms facing each other. Position the dumbbells just above your chest, pressed together.\r\n2. Press the dumbbells upward by extending your arms, keeping your elbows close to your torso.\r\n3. Fully extend your arms at the top, ensuring the dumbbells remain in contact with each other.\r\n4. Lower the dumbbells back to the starting position with control, keeping them squeezed together. Repeat for the desired number of repetitions.', E'1. Squeeze the dumbbells together throughout the entire movement to maximize chest engagement.\r\n2. Use a slow and controlled motion to maximize muscle engagement and avoid swinging.\r\n3. Ensure your wrists remain straight and aligned with your forearms.', '{"image_male_start":"images/Chest/Dumbbell Incline Squeeze Press.jpg","image_male_end":"images/Chest/Dumbbell Incline Squeeze Press1.jpg","video_url":"videos/Chest/Dumbbell Incline Squeeze Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a339d6ca-d0bb-4fa5-800c-cb4bb6b79071'::uuid, 'Dumbbell Incline Svend Close grip Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Set an incline bench to a 45-degree angle and lie back against it. Hold a single dumbbell pressed between your palms just above your chest with your fingers extended or interlaced around the handle.\r\n2. Press the dumbbell upward by extending your arms, keeping your elbows close to your torso.\r\n3. Fully extend your arms at the top, continuing to press the dumbbell between your palms.\r\n4. Lower the dumbbell back to the starting position with control, keeping the dumbbell pressed between your palms. Repeat for the desired number of repetitions.', E'1. Exhale as you press the dumbbell upward and inhale as you lower it.\r\n2. Avoid locking your elbows at the top of the movement to maintain tension on the muscles.\r\n3. Choose a weight that allows you to maintain proper form and control throughout the exercise.', '{"image_male_start":"images/Chest/Dumbbell Incline Svend Close grip Press.jpg","image_male_end":"images/Chest/Dumbbell Incline Svend Close grip Press1.jpg","video_url":"videos/Chest/Dumbbell Incline Svend Close grip Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('97cb036f-1267-46b7-ba28-1adeffcdffd8'::uuid, 'Dumbbell Incline Triceps Extension', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Set an incline bench to a 45-degree angle and lie back against it. Hold a dumbbell in each hand with your arms extended straight up, palms facing each other.\r\n2. Bend your elbows to lower the dumbbells behind your head in a controlled motion.\r\n3. Lower the dumbbells until your forearms are parallel to the floor, maintaining a 90-degree angle at your elbows.\r\n4. Extend your elbows to raise the dumbbells back to the starting position, keeping your upper arms stationary. Repeat for the desired number of repetitions.', E'1. Exhale as you extend the dumbbells upward and inhale as you lower them.\r\n2. Keep your upper arms stationary to ensure the movement targets your triceps.\r\n3. Use a slow and controlled motion to avoid swinging and ensure proper muscle engagement.', '{"image_male_start":"images/Triceps/Dumbbell Incline Triceps Extension.jpeg","video_url":"videos/Triceps/Dumbbell Incline Triceps Extension.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1dcab6f7-4fe8-4966-adeb-63c923a4ca44'::uuid, 'Dumbbell Incline Twisted Fly', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Set an incline bench to a 45-degree angle and lie back against it, holding a dumbbell in each hand. Start with your arms extended lightly bent by your sides, palms facing up, dumbbells held at chest level.\r\n2. Raise the dumbbells up over your chest in a wide arc, rotating your palms so they face backwards as you raise them up.\r\n3. Reverse the motion, bringing the dumbbells back down in a wide arc and rotating your palms back to face upward. Repeat for the desired number of repetitions.', E'1. Maintain a slight bend in your elbows throughout the movement to reduce joint strain.\r\n2. Use a slow and controlled motion to maximize muscle engagement.\r\n3. Avoid letting the dumbbells touch at the top to maintain tension on the muscles.', '{"image_male_start":"images/Chest/Dumbbell Incline Twisted Fly.jpg","image_male_end":"images/Chest/Dumbbell Incline Twisted Fly1.jpg","video_url":"videos/Chest/Dumbbell Incline Twisted Fly.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('32e8e47c-d3f7-4034-b884-95b8df8e9ef6'::uuid, 'Dumbbell Incline Two Arm Extension', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Set an incline bench to a 45-degree angle and lie back against it, holding a single dumbbell with both hands, gripping the handle securely. Start with the dumbbell extended straight up above your shoulders, with your palms facing each other.\r\n2. Slowly lower the dumbbell by bending your elbows, allowing the weight to move behind your head until your forearms are parallel to the floor.\r\n3. Pause briefly at the bottom of the movement, feeling the stretch in your triceps.\r\n4. Reverse the motion by extending your elbows, pushing the dumbbell back up to the starting position. Repeat for the desired number of repetitions.', E'1. Avoid locking your elbows at the top of the movement to maintain tension on the muscles.\r\n2. Exhale as you extend the dumbbell and inhale as you lower it.\r\n3. Use a slow and controlled motion to maximize muscle engagement and reduce the risk of injury.', '{"image_male_start":"images/Triceps/Dumbbell Incline Two Arm Extension.jpeg","video_url":"videos/Triceps/Dumbbell Incline Two Arm Extension.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0b766fbd-c508-4b35-9cd4-2c1652c0d174'::uuid, 'Dumbbell Iron Cross', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin in a squat position with your feet shoulder-width apart, holding a dumbbell in each hand. Extend your arms in front of your chest, keeping the dumbbells close together and your palms facing each other.\r\n2. Keep your back straight as you start to stand up. As you rise, simultaneously open your arms out to your sides, extending them at shoulder level, forming a "T" shape with your body.\r\n3. Pause briefly at the top of the movement, ensuring your arms are fully extended to the sides and parallel to the floor, with your palms facing forward.\r\n4. Bring your arms back in front of your chest while returning to the squat position. Repeat for the desired number of repetitions.', E'1. Use a slow and controlled motion to maximize muscle engagement and prevent momentum from taking over.\r\n2. Keep your wrists straight and aligned with your forearms throughout the movement.\r\n3. Start with lighter weights to ensure proper form before progressing to heavier dumbbells.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Dumbbell Iron Cross.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Dumbbell Iron Cross1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Dumbbell Iron Cross.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('fb3d9281-ad76-43d1-84b6-43fe4458d627'::uuid, 'Dumbbell Jumping Squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand by your sides. Keep your chest up, shoulders back, and core engaged.\r\n2. Lower yourself into a squat position by bending your knees and hips, keeping your back straight and the dumbbells close to your body.\r\n3. Explosively push through your heels to jump straight up into the air, extending your legs and keeping the dumbbells by your sides.\r\n4. Land softly on your forefeet. Repeat for the desired number of repetitions.', E'1. Ensure your knees track over your toes during the squat and landing phases to avoid strain on your joints.\r\n2. Use a controlled motion when landing to minimize impact on your joints.\r\n3. Keep your chest lifted and your back straight to maintain proper posture.', '{"image_male_start":"images/Legs/Dumbbell Jumping Squat.jpg","image_male_end":"images/Legs/Dumbbell Jumping Squat1.jpg","video_url":"videos/Legs/Dumbbell Jumping Squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6abcf636-a3ea-4bc1-b62a-531852f3af01'::uuid, 'Dumbbell Kickback', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by kneeling with the right leg on a bench and the left foot firmly planted on the floor. Lean down until your torso is parallel to the floor and place your right hand on the bench for support.Hold a dumbbell in the right hand. \r\n2. Start with your right arm bent at a 90-degree angle, with the upper arm parallel to the floor and the dumbbell close to your torso.\r\n3. Extend your arm backward by straightening your elbow, keeping your upper arm stationary and focusing on squeezing your triceps at the top of the movement.\r\n4. Slowly bend your elbow to return to the starting position, maintaining control and keeping your upper arm parallel to the floor. Repeat for the desired number of repetitions before switching to the other arm.', E'1. Keep your upper arm stationary throughout the movement to isolate the triceps effectively.\r\n2. Engage your core to maintain stability and prevent excessive movement of your torso.\r\n3. Use a controlled motion, avoiding swinging the dumbbell to ensure proper muscle engagement.', '{"image_male_start":"images/Triceps/Dumbbell Kickback.jpeg","video_url":"videos/Triceps/Dumbbell Kickback.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9b42866c-3714-498f-9643-3744431e1466'::uuid, 'Dumbbell Kneeling Arnold Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by kneeling on the floor with your knees shoulder-width apart. Hold a dumbbell in each hand at shoulder height with your palms facing your body and your elbows bent and facing down. \r\n2. Rotate your palms forward as you press the dumbbells overhead until your arms are fully extended.\r\n3. Reverse the motion, lowering the dumbbells back to shoulder height while rotating your palms back towards your body.\r\n4. Repeat for the desired number of repetitions, maintaining control throughout the movement.', E'1. Avoid arching your back; keep your spine neutral.\r\n2. Keep your movements smooth and controlled to avoid using momentum.\r\n3. Focus on maintaining the alignment of your elbows and wrists throughout the exercise.', '{"image_male_start":"images/Shoulders/Dumbbell Kneeling Arnold Press.jpg","image_male_end":"images/Shoulders/Dumbbell Kneeling Arnold Press1.jpg","video_url":"videos/Shoulders/Dumbbell Kneeling Arnold Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('da0027ac-6066-4e33-93a8-01b54802212d'::uuid, 'Dumbbell Kneeling Hold to Stand Clean grip', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin in a kneeling position on both knees with a dumbbell in each hand, held with a neutral grip (palms facing each other) at shoulder height.\r\n2. Engage your thighs and bring one foot forward, planting it flat on the floor to form a 90-degree angle with your knee. Press through the planted foot to stand up, bringing your other foot forward to meet it, standing upright.\r\n3. Lower back into the kneeling position by stepping one foot back and lowering the knee to the floor, followed by the other knee, returning to the starting position.\r\n4. Repeat the movement for the desired number of repetitions, alternating the leading leg if preferred.\r\n', E'1. Ensure your front knee is aligned with your ankle to avoid undue stress on the joint.\r\n2. Move smoothly and controlled, focusing on engaging your glutes and quadriceps during the transition.\r\n3. Use a weight that allows for proper form and control throughout the exercise.', '{"image_male_start":"images/Legs/Dumbbell Kneeling Hold to Stand Clean grip.jpg","image_male_end":"images/Legs/Dumbbell Kneeling Hold to Stand Clean grip1.jpg","video_url":"videos/Legs/Dumbbell Kneeling Hold to Stand Clean grip.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('cdaf18f5-70d4-405f-bd91-a4640dd04584'::uuid, 'Dumbbell kneeling squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin in a kneeling position with both knees on the floor, torso straight upright from knees to shoulders. Holding a dumbbell in each hand with a neutral grip (palms facing each other) at shoulder height.\r\n2. Bend your knees further pushing your hips backward to sit back onto your heels, keeping your torso upright.\r\n3. Push your hips forward and squeeze your glutes to return to the starting position.\r\n4. Repeat the movement for the desired number of repetitions, maintaining a controlled motion throughout.', E'1. Squeeze your glutes as you push your hips forward to maximize muscle activation.\r\n2. Keep your torso upright and avoid leaning forward during the movement.\r\n3. Use a controlled motion to avoid putting strain on your knees.', '{"image_male_start":"images/Legs/Dumbbell Kneeling Squat  .jpg","video_url":"videos/Legs/Dumbbell Kneeling Squat  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7b5051c6-3b8f-4de2-8969-2f5d5bc8daf9'::uuid, 'Dumbbell Lateral to Front Raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your arms at your sides and palms facing your body.\r\n2. Lift the dumbbells laterally to shoulder height, keeping a slight bend in your elbows.\r\n3. From the lateral position, move the dumbbells forward until they are directly in front of you, keeping them at shoulder height.\r\n4. Lower the dumbbells back to the starting position with control. Repeat the movement for the desired number of repetitions.', E'1. Maintain a slight bend in your elbows to protect your joints.\r\n2. Keep your shoulders down and back to avoid straining your neck.\r\n3. Use a weight that allows you to perform the exercise with proper form.', '{"image_male_start":"images/Shoulders/Dumbbell Lateral to Front Raise.jpg","image_male_end":"images/Shoulders/Dumbbell Lateral to Front Raise1.jpg","video_url":"videos/Shoulders/Dumbbell Lateral to Front Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a48916b2-3e42-4e19-9f7a-9461e4d4a816'::uuid, 'Dumbbell Leaning Fly', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench holding a dumbbell in each hand, with your arms hanging down by your sides and feet flat on the floor.\r\n2. Lean your torso slightly forward, keeping your back straight. Raise both arms out to your sides at shoulder height, maintaining a slight bend in your elbows.\r\n3. Lower the dumbbells down to your sides and repeat for the desired number of repetitions.', E'1. Avoid using momentum; focus on a slow and controlled movement.\r\n2. Maintain a slight bend in your elbows to protect your joints.\r\n3. Breathe steadily, exhaling as you bring the dumbbells across your body and inhaling as you extend them back out.', '{"image_male_start":"images/Shoulders/Dumbbell Leaning Fly.jpg","image_male_end":"images/Shoulders/Dumbbell Leaning Fly1.jpg","video_url":"videos/Shoulders/Dumbbell Leaning Fly.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('377e0da9-e925-4396-9da9-2f636008ad3e'::uuid, 'Dumbbell Low Windmill', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet slightly wider than shoulder-width apart, holding a dumbbell in your left hand. Extend your left arm down, and raise your right arm straight up overhead.\r\n2. Engage your core and hinge at your hips, bending your left knee slightly while keeping your right leg straight. Lower the dumbbell toward your left foot, keeping your back flat and left arm extended upward.\r\n3. Rotate your torso slightly to follow the movement of the dumbbell. Lower the dumbbell as close to the floor as you can while maintaining proper form.\r\n4. Reverse the motion by pushing through your left foot and straightening your torso back to the starting position. Repeat for the desired number of repetitions, then switch sides.', E'1. Ensure your back remains flat and avoid rounding your spine during the movement.\r\n2. Maintain a slight bend in your left knee while keeping your right leg straight.\r\n3. Focus on a controlled movement, avoiding any jerky or rapid motions.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Dumbbell Low Windmill.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Dumbbell Low Windmill1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Dumbbell Low Windmill.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f4e29381-d771-46be-927b-52c76903dc16'::uuid, 'Dumbbell lunge alternating on the spot', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet hip-width apart, holding a dumbbell in each hand by your sides.\r\n2. Take a step forward with your right foot and lower your body into a lunge position by bending both knees. Your right knee should be directly above your right ankle, and your left knee should hover just above the floor.\r\n3. Push through your right heel to return to the starting position.\r\n4. Repeat the movement with your left leg, alternating legs with each repetition.', E'1. Ensure your front knee does not extend past your toes to avoid strain on the knee joint.\r\n2. Maintain a steady and controlled pace to ensure proper form and balance.\r\n3. Exhale as you push back to the starting position and inhale as you lower into the lunge.', '{"image_male_start":"images/Legs/Dumbbell Lunge Alternating on the spot  .jpg","video_url":"videos/Legs/Dumbbell Lunge Alternating on the spot  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6ef9ca6c-14aa-4ea3-8b0e-dbba49f9c2f6'::uuid, 'Dumbbell lunge pulse', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet hip-width apart, holding a dumbbell in each hand by your sides.\r\n2. Take a step forward with your right foot and lower your body into a lunge position by bending both knees. Your right knee should be directly above your right ankle, and your left knee should hover just above the floor.\r\n3. From the lunge position, pulse up and down by slightly raising and lowering your body a few inches for 2-3 pulses. Keeping the movement controlled and small.\r\n4. Push through your right heel to return to the starting position. Repeat the movement with your left leg, alternating legs with each set.', E'1. Ensure your front knee does not extend past your toes to avoid strain on the knee joint.\r\n2. Maintain a steady and controlled pace to ensure proper form and balance.\r\n3. Exhale as you push back to the starting position and inhale as you lower into the lunge.', '{"image_male_start":"images/Legs/Dumbbell Lunge Pulse  .jpg","video_url":"videos/Legs/Dumbbell Lunge Pulse  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6ad7c499-fca2-43b5-8870-00a11f28f9b6'::uuid, 'Dumbbell lunge to overhead press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet hip-width apart, holding a dumbbell in each hand at shoulder height with your palms facing each other.\r\n2. Step forward with your right foot and lower your body into a lunge position by bending both knees while simultaneously pressing the dumbbells overhead until your arms are fully extended. Your right knee should be directly above your right ankle, and your left knee should hover just above the floor.\r\n3. Push through your right heel to return to the starting position while lowering the dumbbells back to shoulder height.\r\n4. Repeat the movement with your left leg, alternating legs with each set.', E'1. Ensure your front knee does not extend past your toes to avoid strain on the knee joint.\r\n2. Keep a steady and controlled pace to ensure proper form and balance.\r\n3. Exhale as you press the dumbbells overhead and inhale as you lower them back down.', '{"image_male_start":"images/Legs/Dumbbell Lunge to Overhead Press  .jpg","video_url":"videos/Legs/Dumbbell Lunge to Overhead Press  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('67ebb939-1d2b-4ba2-9741-023c445bfbd5'::uuid, 'Dumbbell lying external shoulder rotation', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie on your side on the floor with your knees slightly bent for stability. Support your head with your lower hand. Hold a dumbbell in your top hand, keeping your upper arm against your side and your elbow bent at 90 degrees.\r\n2. Start with your forearm across your abdomen, perpendicular to the floor.\r\n3. Rotate your shoulder to lift the dumbbell, bringing your forearm to a vertical position without moving your upper arm away from your side.\r\n4. Slowly lower the dumbbell back to the starting position, maintaining control throughout the movement.', E'1. Keep your upper arm stationary against your side to isolate the shoulder rotation.\r\n2. Perform the movement slowly and with control to avoid momentum and ensure proper muscle activation.\r\n3. Use a light weight to start with, as this exercise targets small stabilizing muscles.', '{"image_male_start":"images/Shoulders/dumbbell lying external shoulder rotation.jpg","image_male_end":"images/Shoulders/dumbbell lying external shoulder rotation1.jpg","video_url":"videos/Shoulders/dumbbell lying external shoulder rotation.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('367833b3-0833-439e-b89f-99e8763c5e8b'::uuid, 'Dumbbell Lying One Arm Neutral Triceps Extension', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie on your back on a flat bench with your feet firmly planted on the floor. Hold a dumbbell in one hand with a neutral grip, arm bent so that the forearm is parallel to the floor. Use your free hand to support the elbow of the working arm.\r\n2. Keeping your upper arm stationary, extend your elbow to lift the dumbbell towards the ceiling.\r\n3. Lower the dumbbell back to the starting position with control, ensuring your forearm returns to being parallel to the floor. Repeat for the desired number of repetitions, then switch to the other arm.', E'1. Avoid locking your elbow at the top of the movement to prevent joint strain.\r\n2. Focus on a slow and controlled motion to maximize muscle engagement.\r\n3. Exhale as you extend your arm and inhale as you lower the dumbbell.', '{"image_male_start":"images/Triceps/Dumbbell Lying One Arm Neutral Triceps Extension.jpeg","video_url":"videos/Triceps/Dumbbell Lying One Arm Neutral Triceps Extension.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('bb747350-0cd9-4d14-bade-6a2ab7d03a02'::uuid, 'Dumbbell Lying One Arm Rear Lateral Raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie face down on a flat bench with your legs bent and forefeet firm on the floor. Hold a dumbbell in one hand, letting it hang straight down from your shoulder and your free hand holding the bench for support.\r\n2. Keeping your elbow slightly bent, raise the dumbbell out to the side and up to shoulder level, squeezing your shoulder blade at the top of the movement.\r\n3. Slowly lower the dumbbell back to the starting position in a controlled manner. Repeat for the desired number of repetitions, then switch to the other arm.', E'1. Avoid using momentum; focus on a slow and controlled movement.\r\n2. Maintain a slight bend in your elbow throughout the exercise to reduce joint strain.\r\n3. Breathe steadily, exhaling as you lift the dumbbell and inhaling as you lower it.', '{"image_male_start":"images/Shoulders/Dumbbell Lying One Arm Rear Lateral Raise.jpg","image_male_end":"images/Shoulders/Dumbbell Lying One Arm Rear Lateral Raise1.jpg","video_url":"videos/Shoulders/Dumbbell Lying One Arm Rear Lateral Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('92f6f5f6-294d-4aaa-aecf-bb4ec786b3fe'::uuid, 'Dumbbell Lying Pronation Rotation on Floor', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie on your side on the floor with your knees bent and feet flat. Support your head with the lower hand. Hold a dumbbell in the top hand with your elbow resting on your side, bent at a 90-degree angle, and your palm facing your head.\r\n2. Slowly rotate your forearm, turning your palm down toward the knees while keeping your upper arm and elbow stationary.\r\n3. Rotate your forearm back to the starting position with control, ensuring the movement is smooth and steady. Repeat for the desired number of repetitions, then switch to the other arm.', E'1. Keep your upper arm and elbow stable throughout the exercise.\r\n2. Avoid using excessive weight to ensure proper form and prevent strain on the wrist and elbow.\r\n3. Focus on a slow and controlled rotation to maximize muscle engagement.\r\n', '{"image_male_start":"images/Forearms/Dumbbell Lying Pronation Rotation on Floor.jpeg","video_url":"videos/Forearms/Dumbbell Lying Pronation Rotation on Floor.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9de9533d-fa37-45fd-97e7-b2cccbace5bf'::uuid, 'Dumbbell Lying Rear Delt Row', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie face down on an incline bench with a dumbbell in each hand, arms hanging straight down, and palms facing forward.\r\n2. Pull the dumbbells towards your ribcage by squeezing your shoulder blades together, keeping your elbows pointed backward.\r\n3. Lower the dumbbells back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Avoid using momentum to lift the weights; use controlled motions for effective muscle engagement.\r\n2. Breathe out as you lift the dumbbells and breathe in as you lower them.\r\n3. Ensure your body remains stable on the bench and avoid lifting your chest.', '{"image_male_start":"images/Shoulders/Dumbbell Lying Rear Delt Row.jpg","image_male_end":"images/Shoulders/Dumbbell Lying Rear Delt Row1.jpg","video_url":"videos/Shoulders/Dumbbell Lying Rear Delt Row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('40e79fe8-d461-42e3-bc47-bb880caf5917'::uuid, 'Dumbbell Lying Rear Lateral Raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie face down on a flat bench with a dumbbell in each hand, arms hanging straight down, and palms facing each other.\r\n2. Raise the dumbbells out to your sides until your arms are parallel to the floor, maintaining a slight bend in your elbows.\r\n3. Lower the dumbbells back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep your neck in a neutral position and avoid straining it during the exercise.\r\n2. Focus on squeezing your shoulder blades together to maximize the activation of your rear deltoids and upper back muscles.\r\n3. Maintain a slight bend in your elbows throughout the movement to reduce joint strain.', '{"image_male_start":"images/Shoulders/Dumbbell Lying Rear Lateral Raise.jpg","image_male_end":"images/Shoulders/Dumbbell Lying Rear Lateral Raise1.jpg","video_url":"videos/Shoulders/Dumbbell Lying Rear Lateral Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('48c4097b-b68a-482f-abdb-42ad7a53aa0c'::uuid, 'Dumbbell Lying Supine Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie on a flat bench with a dumbbell in each hand, arms fully extended towards the floor by your sides, and palms facing your thighs.\r\n2. Curl the dumbbells by bending your elbows until your forearms are parallel to the floor while rotating the dumbbells to face backward.\r\n3. Lower the dumbbells back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Keep your upper arms stationary and only move your forearms to ensure maximum bicep engagement.\r\n2. Avoid using momentum; focus on a slow and controlled motion throughout the exercise.\r\n3. Use a weight that allows for proper form and control throughout the exercise.', '{"image_male_start":"images/Biceps/Dumbbell Lying Supine Curl.jpeg","video_url":"videos/Biceps/Dumbbell Lying Supine Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2a76ea02-1d6e-4d4a-a072-842e24ff6994'::uuid, 'Dumbbell Lying Triceps Extension', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie on a flat bench with your feet flat on the floor and knees bent at a 90-degree angle. Hold a dumbbell in each hand with your arms bent and forearms parallel to the floor, palms facing each other.\r\n2. Keeping your elbows stable, slowly extend your elbows to raise the dumbbells towards the ceiling until your arms are fully extended, keeping your upper arms stationary.\r\n3. Lower the dumbbells back to the starting position by bending your elbows, ensuring your forearms return to being parallel to the floor. \r\n4. Repeat the movements for the desired number of repetitions, maintaining control and proper form throughout the exercise.', E'1. Keep your upper arms stationary and only move your forearms to ensure maximum triceps engagement.\r\n2. Avoid using momentum; focus on a slow and controlled motion throughout the exercise.\r\n3. Maintain a neutral wrist position to prevent strain and injuries.', '{"image_male_start":"images/Triceps/Dumbbell Lying Triceps Extension.jpeg","video_url":"videos/Triceps/Dumbbell Lying Triceps Extension.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e1e02fed-f6f9-4a95-9926-f98354f1c139'::uuid, 'Dumbbell Lying Triceps Extension on Floor', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie on your back on the floor with your knees bent and feet flat on the floor. Hold one dumbbell with both hands, arms extended towards the ceiling, and palms facing each other. Position the dumbbell directly above your chest with your elbows slightly bent.\r\n2. Slowly bend your elbows to lower the dumbbell towards the floor just behind your forehead, keeping your upper arms stationary and elbows pointing towards the ceiling.\r\n3. Extend your elbows to raise the dumbbell back towards the ceiling until your arms are fully extended, keeping your upper arms stationary throughout the movement.\r\n4. Repeat the movements for the desired number of repetitions.', E'1. Keep your upper arms stationary and only move your forearms to ensure maximum triceps engagement.\r\n2. Avoid using momentum; focus on a slow and controlled motion.\r\n3. Maintain a neutral wrist position to prevent strain and injuries.', '{"image_male_start":"images/Triceps/Dumbbell Lying Triceps Extension on Floor.jpeg","video_url":"videos/Triceps/Dumbbell Lying Triceps Extension on Floor.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e58af4c3-41a8-4338-8f33-ef43fa2c37eb'::uuid, 'Dumbbell narrow stance squats', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet close together, about hip-width apart, holding a dumbbell in each hand at your sides with your palms facing your body.\r\n2. Begin the squat by pushing your hips back and bending your knees to lower your body, keeping the dumbbells at your sides.\r\n3. Lower yourself until your thighs are parallel to the floor or as low as you can comfortably go while maintaining proper form.\r\n4. Push through your heels to stand back up, straightening your legs and returning to the starting position. Repeat for the desired number of repetitions.', E'1. Ensure your weight is evenly distributed through your feet, especially your heels, to activate your glutes and quadriceps.\r\n2. Breathe in as you lower into the squat and breathe out as you push back up.\r\n3. Keep your knees in line with your toes to avoid excessive strain on your knees.', '{"image_male_start":"images/Legs/Dumbbell narrow stance squats.jpg","image_male_end":"images/Legs/Dumbbell narrow stance squats1.jpg","video_url":"videos/Legs/Dumbbell narrow stance squats.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6ddf3d45-bbcb-4f6c-b0a1-ffad062ca604'::uuid, 'Dumbbell One Arm Floor Fly', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie on your back on the floor with your legs straight. Hold a dumbbell in one hand with your arm slightly bent on the floor, palm facing up. Keep your free hand on the floor for support.\r\n2. Slowly raise your arm over your chest in a wide arc motion, keeping a slight bend in your elbow. \r\n3. Lower the dumbbell back to the starting position until your arm nearly touches the floor.\r\n4. Repeat for the desired repetitions, then switch to the other arm.', E'1. Keep a slight bend in your elbow to reduce strain on your joint.\r\n2. Avoid letting your back arch off the floor; keep it flat and supported.\r\n3. Focus on using your chest muscles to lift the dumbbell, minimizing shoulder involvement.', '{"image_male_start":"images/Chest/Dumbbell One Arm Floor Fly.jpg","image_male_end":"images/Chest/Dumbbell One Arm Floor Fly1.jpg","video_url":"videos/Chest/Dumbbell One Arm Floor Fly.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4714436a-4bb3-4f7f-b103-12bebbdefb70'::uuid, 'Dumbbell One Arm Floor Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie on your back on the floor with your legs straight on the floor. Hold a dumbbell in one hand with your arm extended straight up towards the ceiling, palm facing forward. Keep your free hand on the floor for support.\r\n2. Lower the dumbbell by bending your elbow until your upper arm touches the floor, bringing your elbow at a 45-degree angle to your body.\r\n3. Press the dumbbell back up to the starting position by extending your elbow, squeezing your chest at the top of the movement.\r\n4. Repeat for the desired number of repetitions, then switch to the other arm.', E'1. Avoid letting your back arch off the floor; keep it flat and supported.\r\n2. Focus on using your chest and triceps to lift the dumbbell.\r\n3. Keep your wrist straight and aligned with your forearm during the exercise.', '{"image_male_start":"images/Chest/Dumbbell One Arm Floor Press.jpg","image_male_end":"images/Chest/Dumbbell One Arm Floor Press1.jpg","video_url":"videos/Chest/Dumbbell One Arm Floor Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c76b2063-4228-4e0f-9fb9-8ca5d30b9041'::uuid, 'Dumbbell One Arm Front Raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in one hand with your arm extended down by your side, palm facing your thigh.\r\n2. Keeping your arm straight, lift the dumbbell directly in front of you to shoulder height, ensuring your palm is facing downwards.\r\n3. Pause briefly at the top of the movement, then slowly lower the dumbbell back to the starting position.\r\n4. Repeat for the desired number of repetitions, then switch to the other arm.', E'1. Keep your back straight and avoid swinging the dumbbell to use momentum.\r\n2. Engage your core to maintain stability and control throughout the exercise.\r\n3. Move the dumbbell in a slow and controlled manner to maximize muscle engagement.', '{"image_male_start":"images/Shoulders/Dumbbell One Arm Front Raise.jpg","image_male_end":"images/Shoulders/Dumbbell One Arm Front Raise1.jpg","video_url":"videos/Shoulders/Dumbbell One Arm Front Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('de7f7058-bf65-4e29-9b1f-b358b79fe5c6'::uuid, 'Dumbbell One Arm Hammer Preacher Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a preacher bench and place your right elbow on the arm pad, holding a dumbbell in a neutral grip (palm facing inward).\r\n2. Keeping your elbow pressed against the pad, curl the dumbbell towards your shoulder by bending your elbow.\r\n3. Squeeze your bicep at the top of the movement, ensuring the dumbbell reaches shoulder height.\r\n4. Slowly lower the dumbbell back to the starting position, fully extending your arm. Repeat for the desired number of repetitions, then switch to the other arm.', E'1. Keep your upper arm pressed firmly against the preacher pad to isolate the biceps.\r\n2. Perform the movement in a slow and controlled manner to maximize muscle engagement.\r\n3. Avoid swinging the dumbbell or using momentum to lift the weight.', '{"image_male_start":"images/Biceps/Dumbbell One Arm Hammer Preacher Curl.jpeg","video_url":"videos/Biceps/Dumbbell One Arm Hammer Preacher Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('86877932-07c0-407b-842d-12c199c063c1'::uuid, 'Dumbbell One Arm Kickback', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Start in a semi-lunge position with your left foot firmly planted on the floor in front and your right leg leg extended behind you lightly bent on your forefoot. Lean forward and place your left arm on your left knee for support.\r\n2. Hold a dumbbell in your right hand with your arm bent at a 90-degree angle, keeping your upper arm close to your torso and parallel to the floor and your forearm pointing back.\r\n3. Extend your elbow to straighten your arm, moving the dumbbell backward until your arm is fully extended.\r\n4. Slowly bend your elbow to return the dumbbell to the starting position. Repeat for the desired number of repetitions, then switch to the other arm.', E'1. Keep your upper arm stationary throughout the exercise to isolate the triceps.\r\n2. Perform the movement in a slow and controlled manner to maximize muscle engagement.\r\n3. Avoid swinging the dumbbell or using momentum to lift the weight.', '{"image_male_start":"images/Triceps/Dumbbell One Arm Kickback.jpeg","video_url":"videos/Triceps/Dumbbell One Arm Kickback.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f749a5a6-7c45-46af-bc91-487c3af97d8b'::uuid, 'Dumbbell One Arm Lateral Raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in one hand by your side with your palm facing your body. Keep your other hand on your hip or relaxed by your side.\r\n2. Lift the dumbbell out to the side, maintaining a slight bend in your elbow. Raise your arm until it is parallel to the floor.\r\n3. Lower the dumbbell back to the starting position, keeping the movement smooth and controlled.\r\n4. Repeat for the desired number of repetitions, then switch arms.', E'1. Perform the movement slowly and deliberately for maximum control.\r\n2. Avoid using momentum or swinging the dumbbell.\r\n3. Keep your wrist straight and aligned with your forearm.', '{"image_male_start":"images/Shoulders/Dumbbell One Arm Lateral Raise.jpg","image_male_end":"images/Shoulders/Dumbbell One Arm Lateral Raise1.jpg","video_url":"videos/Shoulders/Dumbbell One Arm Lateral Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('390b50d3-f9ca-4236-8dea-20932736fec2'::uuid, 'Dumbbell One Arm Low Fly', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in one hand. Extend your arm straight down in front of your body, palm facing forward.\r\n2. Lift the dumbbell in front of you sideways in a wide arc, maintaining a slight bend in your elbow.\r\n3. Raise your arm until the dumbbell is at your eye level, keeping your shoulder muscle engaged.\r\n4. Lower the dumbbell back to the starting position in a controlled manner. Repeat for the desired number of repetitions, then switch arms.', E'1. Maintain a slight bend in your elbow throughout the movement.\r\n2. Perform the movement slowly and with control to avoid using momentum.\r\n3. Focus on using your chest and shoulder muscles to lift the weight.', '{"image_male_start":"images/Shoulders/Dumbbell One Arm Low Fly.jpg","image_male_end":"images/Shoulders/Dumbbell One Arm Low Fly1.jpg","video_url":"videos/Shoulders/Dumbbell One Arm Low Fly.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5dfd9f3a-5e0a-48cc-9ddc-b7ce3456460d'::uuid, 'Dumbbell One Arm Reverse Preacher Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a preacher bench with your right arm extended over the pad, holding a dumbbell in your right hand using an overhand grip (palm facing down). Keep your right upper arm pressed against the pad.\r\n2. Curl the dumbbell upward towards your shoulder by bending your elbow, focusing on engaging your biceps and forearm muscles.\r\n3. Squeeze your biceps at the top of the movement, ensuring the dumbbell reaches shoulder height.\r\n4. Lower the dumbbell back to the starting position with control, fully extending your arm. Repeat for the desired number of repetitions, then switch to the other arm.', E'1. Keep your upper arm pressed firmly against the pad to isolate your biceps.\r\n2. Avoid using your back or shoulder to lift the weight.\r\n3. Perform the movement slowly and with control and avoid using momentum.', '{"image_male_start":"images/Biceps/Dumbbell One Arm Reverse Preacher Curl.jpeg","video_url":"videos/Biceps/Dumbbell One Arm Reverse Preacher Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('167603e6-3690-4f0a-80db-bc4a7b6e8c7a'::uuid, 'Dumbbell One arm Reverse Wrist Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench with your forearm resting on your thigh, palm facing down, holding a dumbbell with an overhand grip (palm facing down).\r\n2. Allow your wrist to extend downward so that the dumbbell hangs towards the floor, keeping your forearm stationary.\r\n3. Curl the dumbbell upward as high as possible by flexing your wrist, focusing on engaging your forearm muscles.\r\n4. Lower the dumbbell back to the starting position with control, fully extending your wrist. Repeat for the desired number of repetitions, then switch to the other arm.', E'1. Keep your forearm stable and only move your wrist.\r\n2. Perform the movement slowly and with control to avoid using momentum.\r\n3. Focus on using your forearm muscles to lift the weight.', '{"image_male_start":"images/Forearms/Dumbbell One arm Reverse Wrist Curl.jpeg","video_url":"videos/Forearms/Dumbbell One arm Reverse Wrist Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8e5bb2af-660d-4526-b7c9-5cf7dca9c906'::uuid, 'Dumbbell One Arm Row (rack support)', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand facing a dumbbell rack, placing your left hand on the rack for support. Hold a dumbbell in your right hand with a neutral grip, arm extended down.\r\n2. Lean downwards, step back with your right leg and keep it extended, bending both knees slightly and keep your back flat.\r\n3. Pull the dumbbell upward towards your hip, bending your elbow and keeping it close to your body, focusing on squeezing your back muscles.\r\n4. Lower the dumbbell back to the starting position with control, fully extending your arm. Repeat for the desired number of repetitions, then switch to the other arm.', E'1. Avoid rotating your torso; keep your shoulders square to the floor.\r\n2. Focus on using your back muscles to lift the weight, not your arm.\r\n3. Breathe out as you pull the dumbbell up and breathe in as you lower it.', '{"image_male_start":"images/Back/Dumbbell One Arm Row (rack support).jpg","image_male_end":"images/Back/Dumbbell One Arm Row (rack support)1.jpg","video_url":"videos/Back/Dumbbell One Arm Row (rack support).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a5fc974f-222d-48db-aa57-fe350776c770'::uuid, 'Dumbbell One Arm Seated Neutral Wrist Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench with your feet flat on the floor. Hold a dumbbell in your right hand with a neutral grip.\r\n2. Place your right forearm on your right thigh, allowing your wrist to extend beyond your knee. Keep your left hand resting on your left thigh for support.\r\n3. Curl the dumbbell upward by flexing your wrist, squeezing your forearm muscles at the top of the movement.\r\n4. Lower the dumbbell back to the starting position with control, extending your wrist. Repeat for the desired number of repetitions.', E'1. Keep your forearm stable and only move your wrist to isolate the forearm muscles.\r\n2. Use a controlled motion to avoid using momentum.\r\n3. Maintain a neutral grip throughout the exercise.', '{"image_male_start":"images/Forearms/Dumbbell One Arm Seated Neutral Wrist Curl.jpeg","video_url":"videos/Forearms/Dumbbell One Arm Seated Neutral Wrist Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('bfa6868d-b34e-44c3-9506-5d8f3b674b0a'::uuid, 'Dumbbell One Arm Shoulder Press (VERSION 2)', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin standing with your feet shoulder-width apart, holding a dumbbell in your right hand at shoulder height with your palm facing forward. Place your left hand on your hip for stability.\r\n2. Engage your core and press the dumbbell overhead by extending your right arm fully overhead.\r\n3. Lower the dumbbell back to shoulder height with control, maintaining a steady and smooth motion.\r\n4. Repeat the exercise for the desired number of repetitions.', E'1. Exhale as you press the dumbbell overhead and inhale as you lower it.\r\n2. Avoid arching your back; maintain a neutral spine throughout the exercise.\r\n3. Keep your movements controlled to prevent injury and ensure proper muscle engagement.', '{"image_male_start":"images/Shoulders/Dumbbell One Arm Shoulder Press (VERSION 2).jpg","image_male_end":"images/Shoulders/Dumbbell One Arm Shoulder Press (VERSION 2)1.jpg","video_url":"videos/Shoulders/Dumbbell One Arm Shoulder Press (VERSION 2).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e35416ab-ab6c-41ac-9a04-b8811e339c33'::uuid, 'Dumbbell One Arm Snatch', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Start in a squat position with your feet shoulder-width apart and a dumbbell on the floor between your feet. Grasp the dumbbell with your right hand, using an overhand grip, while keeping your back straight and core engaged.\r\n2. Drive through your heels and explosively extend your hips, knees, and ankles, pulling the dumbbell upward close to your body as you rise.\r\n3. As the dumbbell reaches shoulder height, raise your hand straight up to bring the dumbbell overhead, fully extending your arm.\r\n4. Stand up fully, keeping the dumbbell overhead. Lower the dumbbell back to the starting position with control and repeat for the desired number of repetitions.', E'1. Keep your core engaged and your back straight to maintain proper form.\r\n2. Exhale during the explosive upward movement and inhale when lowering the dumbbell.\r\n3. Focus on using your hips and legs to generate power, minimizing the strain on your arm and shoulder.', '{"image_male_start":"images/Powerlifting/Dumbbell One Arm Snatch.jpg","image_male_end":"images/Powerlifting/Dumbbell One Arm Snatch1.jpg","video_url":"videos/Powerlifting/Dumbbell One Arm Snatch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('19cb6028-6793-4481-a110-2057dcaeea73'::uuid, 'Dumbbell One Arm Triceps Extension (on bench)', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by sitting on a flat bench with your feet flat on the floor. Hold a dumbbell in your right hand, extending your arm straight above your shoulder. Place your left hand on your hip for support.\r\n2. Lower the dumbbell slowly behind your head by bending your elbow, keeping your upper arm stationary and your wrist straight.\r\n3. Extend your arm back to the starting position, fully straightening your elbow and squeezing your triceps at the top of the movement.\r\n4. Repeat for the desired number of repetitions.', E'1. Avoid flaring your elbow out to the side; keep it close to your head.\r\n2. Focus on isolating the triceps muscle by keeping your upper arm still.\r\n3. Exhale as you extend your arm and inhale as you lower the dumbbell.\r\n', '{"image_male_start":"images/Triceps/Dumbbell One Arm Triceps Extension (on bench).jpeg","video_url":"videos/Triceps/Dumbbell One Arm Triceps Extension (on bench).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9906078c-69c5-472e-ad4c-1f541bfc328b'::uuid, 'Dumbbell One Arm Wide Grip Bench Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by lying flat on a bench with your feet firmly planted on the floor. Hold a dumbbell in your right hand, extending your arm straight above your shoulder, with a wide grip and palm facing forward.\r\n2. Lower the dumbbell slowly towards the floor by bending your elbow, until your elbow passes lower than the bench.\r\n3. Push the dumbbell back up to the starting position by extending your arm, squeezing your chest muscles at the top of the movement.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep your feet firmly planted on the floor for stability.\r\n2. Focus on a slow and controlled movement to maximize muscle engagement.\r\n3. Keep your wrist straight to avoid unnecessary strain.', '{"image_male_start":"images/Chest/Dumbbell One Arm Wide Grip Bench Press.jpg","image_male_end":"images/Chest/Dumbbell One Arm Wide Grip Bench Press1.jpg","video_url":"videos/Chest/Dumbbell One Arm Wide Grip Bench Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('fae836cf-ab42-4389-8c21-9611d48b1c76'::uuid, 'Dumbbell One arm Wrist Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench with your feet flat on the floor. Hold a dumbbell in your right hand with your palm facing up, and rest your right forearm on your thigh, allowing your wrist to hang slightly off your knee.\r\n2. Curl the dumbbell upward by curling your wrist, bringing the weight as high as possible.\r\n3. Slowly lower the dumbbell back to the starting position, extending your wrist downward.\r\n4. Repeat for the desired number of repetitions, then switch to your left hand and perform the same steps.', E'1. Keep your forearm stationary on your thigh throughout the movement.\r\n2. Use a controlled motion to prevent momentum from aiding the lift.\r\n3. Focus on using only your wrist to lift the dumbbell, minimizing elbow movement.', '{"image_male_start":"images/Forearms/Dumbbell One arm Wrist Curl.jpeg","video_url":"videos/Forearms/Dumbbell One arm Wrist Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('80d4ec97-2900-4e54-bc99-bc57a6288749'::uuid, 'Dumbbell One Arm Zottman Preacher Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand behind an incline bench and lean your right arm on the bench''s headrest, holding a dumbbell in your hand with an underhand grip (palm facing up).\r\n2. Curl the dumbbell upward towards your shoulder, keeping your upper arm stationary and focusing on engaging your biceps.\r\n3. At the top of the curl, rotate your wrist to turn your palm downward, transitioning to an overhand grip.\r\n4. Slowly lower the dumbbell back to the starting position with the overhand grip. Rotate your wrist back to the underhand grip for the next repetition. Repeat for the desired number of repetitions.', E'1. Keep your upper arm pressed against the bench''s headrest throughout the exercise.\r\n2. Focus on a slow and controlled wrist rotation at the top of the curl.\r\n3. Use a lighter weight to master the wrist rotation and prevent strain.', '{"image_male_start":"images/Biceps/Dumbbell One Arm Zottman Preacher Curl.jpeg","video_url":"videos/Biceps/Dumbbell One Arm Zottman Preacher Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('fde315f8-7f95-4a68-8dbb-05f7f9a3f5c7'::uuid, 'Dumbbell Over Bench Reverse Wrist Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Kneel on the floor in front of a bench, placing both forearms over the bench while holding a dumbbell with an overhand grip (palm facing down).\r\n2. Rest your wrists just off the edge of the bench, allowing the dumbbells to hang downward.\r\n3. Curl the dumbbells upward by flexing your wrists, lifting the weight as high as possible while keeping your forearms flat on the bench.\r\n4. Slowly lower the dumbbells back to the starting position, fully extending your wrists. Repeat for the desired number of repetitions.', E'1. Keep your forearms pressed firmly against the bench to isolate the wrist movement.\r\n2. Use a controlled motion to lift and lower the dumbbells, avoiding any jerking movements.\r\n3. Avoid using your shoulder or upper arm to lift the weight.', '{"video_url":"videos/Forearms/Dumbbell Over Bench Reverse Wrist Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a55a7d3f-cc16-4135-8101-bddd8e074057'::uuid, 'Dumbbell Over Bench Wrist Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Kneel on the floor in front of a bench, placing both forearms over the bench while holding a dumbbell with an underhand grip (palms facing up).\r\n2. Rest your wrists just off the edge of the bench, allowing the dumbbells to hang downward.\r\n3. Curl the dumbbells upward by flexing your wrists, lifting the weights as high as possible while keeping your forearms flat on the bench.\r\n4. Slowly lower the dumbbells back to the starting position, fully extending your wrists. Repeat for the desired number of repetitions.', E'1. Keep your forearms pressed firmly against the bench to isolate the wrist movement.\r\n2. Use a controlled motion to lift and lower the dumbbells, avoiding any jerking movements.\r\n3. Avoid using your shoulder or upper arm to lift the weight.', '{"image_male_start":"images/Forearms/Dumbbell Over Bench Wrist Curl.jpeg","video_url":"videos/Forearms/Dumbbell Over Bench Wrist Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0fc19918-3dfd-4d5a-a7dd-7500f3027d2a'::uuid, 'dumbbell overhead extension seated', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench, holding a dumbbell with both hands and extending your arms fully overhead. Hold a dumbbell with your fingers wrapped around the dumbbell handle.\r\n2. Slowly bend your elbows, lowering the dumbbell behind your head until your forearms are parallel to the floor.\r\n3. Press the dumbbell back up by straightening your elbows, returning to the starting position with arms fully extended overhead.\r\n4. Repeat the movement for the desired number of repetitions, keeping your core engaged and back pressed against the bench.', E'1. Keep your elbows close to your head throughout the movement to maximize triceps activation.\r\n2. Use a controlled motion, avoiding any jerking or swinging of the weight.\r\n3. Maintain a firm grip on the dumbbell to ensure stability and control.', '{"image_male_start":"images/Triceps/dumbbell overhead extension seated.jpeg","video_url":"videos/Triceps/dumbbell overhead extension seated.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('40f30b84-f950-4469-8f2d-735f13f9d548'::uuid, 'dumbbell overhead extension standing', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell with both hands. Hold a dumbbell with your fingers wrapped around the dumbbell handle.\r\n2. Slowly bend your elbows, lowering the dumbbell behind your head until your forearms are parallel to the floor.\r\n3. Press the dumbbell back up by straightening your elbows, returning to the starting position with arms fully extended overhead.\r\n4. Repeat the movement for the desired number of repetitions, keeping your core engaged and back straight.', E'1. Keep your elbows close to your head throughout the movement to maximize triceps activation.\r\n2. Use a controlled motion, avoiding any jerking or swinging of the weight.\r\n3. Maintain a firm grip on the dumbbell to ensure stability and control.', '{"image_male_start":"images/Triceps/Dumbbell overhead extension standing.jpeg","video_url":"videos/Triceps/Dumbbell overhead extension standing.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e52fb56e-3ac9-43b6-b1ad-f4a37f0421de'::uuid, 'Dumbbell Overhead Lunge', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet hip-width apart, holding a dumbbell in each hand. Extend your arms fully overhead with your palms facing each other.\r\n2. Step forward with your right foot, lowering your hips until both knees are bent at approximately 90 degrees. Your back knee should hover just above the floor.\r\n3. Push through your front heel to return to the starting position, maintaining the dumbbells overhead throughout the movement.\r\n4. Alternate legs and repeat the movement for the desired number of repetitions.', E'1. Maintain a controlled motion to prevent any wobbling or loss of balance.\r\n2. Avoid leaning forward; keep your torso upright throughout the exercise.\r\n3. Inhale as you step forward and lower into the lunge, and exhale as you push back to the starting position.', '{"image_male_start":"images/Legs/Dumbbell Overhead Lunge.jpg","image_male_end":"images/Legs/Dumbbell Overhead Lunge1.jpg","video_url":"videos/Legs/Dumbbell Overhead Lunge.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3b583e08-e189-455f-949a-ec5b856128db'::uuid, 'Dumbbell Overhead Sit-up', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie on your back with your legs bent and feet flat on the floor. Hold a dumbbell in both hands, extending your arms straight overhead with your palms facing each other.\r\n2. Engage your core and lift your upper body off the floor into a sitting position, keeping the dumbbell directly overhead.\r\n3. Slowly lower your upper body back to the starting position, maintaining control and keeping the dumbbell overhead.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Ensure the dumbbell remains directly overhead and in line with your shoulders during the entire movement.\r\n2. Avoid using momentum; focus on a controlled and steady motion.\r\n3. Start with a lighter weight to ensure proper form and avoid strain.', '{"image_male_start":"images/Abdominals/Dumbbell Overhead Sit-up.jpeg","video_url":"videos/Abdominals/Dumbbell Overhead Sit-up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('706a699d-5b7e-44b0-8a1a-0ec147b1c97d'::uuid, 'Dumbbell Plyo Squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet wider than hip-width apart, holding a dumbbell with both hands, arms lowered down in front of you.\r\n2. Lower into a squat position by bending your knees and hips, ensuring your knees face outward and keeping your back straight.\r\n3. Push through your heels to raise back to the standing position, keeping your hips forward and glutes engaged throughout the movement.\r\n4. Lower back into the squat position, maintaining control and keeping your glutes engaged. Repeat for the desired number of repetitions.', E'1. Keep your knees aligned with your toes during the squat and standing phases.\r\n2. Use a controlled and steady motion to lower into the squat, avoiding any jerky movements.\r\n3. Focus on keeping your hips forward and glutes engaged as you return to the standing position.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d96a01e9-923e-47b2-9f56-d6c8166ea270'::uuid, 'Dumbbell Preacher Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a preacher bench and place your left arm on the padding. Hold a dumbbell in your left hand with an underhand grip (palm facing up), allowing your arm to hang straight down.\r\n2. Engage your biceps and curl the dumbbell upward towards your shoulder by bending your elbow. Keep your upper arm stationary against the bench.\r\n3. Squeeze your biceps at the top of the movement, ensuring the dumbbell reaches shoulder height.\r\n4. Lower the dumbbell back to the starting position with control, fully extending your arm. Repeat for the desired number of repetitions.', E'1. Keep your upper arm pressed firmly against the preacher bench to isolate the biceps.\r\n2. Avoid using momentum; focus on a slow and controlled movement.\r\n3. Use a full range of motion for maximum muscle engagement.', '{"image_male_start":"images/Biceps/Dumbbell Preacher Curl.jpeg","video_url":"videos/Biceps/Dumbbell Preacher Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a3623e2f-4cd5-42c1-bf60-e5f18aff10e3'::uuid, 'Dumbbell Preacher Curl (Turned Torso)', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a preacher bench and place your left arm on the padding, twisting your torso slightly to the right. Hold a dumbbell in your left hand with an underhand grip (palm facing up), allowing your arm to hang straight down.\r\n2. Engage your biceps and curl the dumbbell upward towards your shoulder by bending your elbow, keeping your upper arm stationary against the bench.\r\n3. Squeeze your biceps at the top of the movement, ensuring the dumbbell reaches shoulder height.\r\n4. Lower the dumbbell back to the starting position with control, fully extending your arm. Repeat for the desired number of repetitions.', E'1. Keep your upper arm pressed firmly against the preacher bench to isolate the biceps.\r\n2. Avoid using momentum; focus on a slow and controlled movement.\r\n3. Use a full range of motion for maximum muscle engagement.', '{"image_male_start":"images/Biceps/Dumbbell Preacher Curl (Turned Torso).jpeg","video_url":"videos/Biceps/Dumbbell Preacher Curl (Turned Torso).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('94dd5771-94fc-455e-99c7-3003f4733e2b'::uuid, 'Dumbbell Preacher Curl over Exercise Ball', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Kneel on the floor in front of an exercise ball. Lean forward to position your chest against the ball, and rest your upper arms on the ball. Hold a dumbbell with both hands with an underhand grip (palm facing up).\r\n2. Engage your biceps and curl the dumbbells upward towards your shoulders by bending your elbows, ensuring your upper arms remain stationary against the ball.\r\n3. Squeeze your biceps at the top of the movement, ensuring the dumbbells reaches shoulder height.\r\n4. Lower the dumbbells back to the starting position with control, fully extending your arm. Repeat for the desired number of repetitions.', E'1. Keep your upper arms pressed firmly against the exercise ball to isolate the biceps.\r\n2. Avoid using momentum; focus on a slow and controlled movement.\r\n3. Exhale as you curl the dumbbells upward and inhale as you lower them back down.', '{"image_male_start":"images/Biceps/Dumbbell Preacher Curl over Exercise Ball.jpeg","video_url":"videos/Biceps/Dumbbell Preacher Curl over Exercise Ball.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f0015e18-a14b-4ec3-9a0c-15e1d8f03f6e'::uuid, 'Dumbbell Press Squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell with both hands close to your chest.\r\n2. Lower your body into a squat position by bending your knees and hips. Make sure your thighs are parallel to the floor and your knees do not go past your toes.\r\n3. At the bottom of the squat, stay in position and press the dumbbell forward in front of your chest twice by extending your arms fully, then bring it back to your chest.\r\n4. Push through your heels to stand up and return to the starting position. Repeat for the desired number of repetitions.', E'1. Ensure your knees track over your toes and avoid letting them cave inward.\r\n2. Ensure the dumbbell moves in a straight line in front of your chest.\r\n3. Use a weight that allows you to perform the exercise with proper form.', '{"image_male_start":"images/Legs/Dumbbell Press Squat.jpg","image_male_end":"images/Legs/Dumbbell Press Squat1.jpg","video_url":"videos/Legs/Dumbbell Press Squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('35d077fc-f1b2-4a82-847e-5cb54a8b2e4f'::uuid, 'Dumbbell Pronate-grip Triceps Extension', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie flat on a bench with your feet firmly planted on the floor, holding a dumbbell in each hand. Extend your arms bent behind your head, keeping your arms at 45 degrees, holding the dumbbell with an overhand grip at shoulder width.\r\n2. Keeping your elbows stationary, bend your arms to lower the dumbbell behind your head.\r\n3. Extend your elbows to raise the dumbbell back to the starting position, fully extending your arms.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Focus on moving only your forearms; your upper arms should remain stationary.\r\n2. Avoid locking your elbows at the top of the movement.\r\n3. Use a controlled motion and avoid swinging the weight.', '{"image_male_start":"images/Triceps/Dumbbell Pronate-grip Triceps Extension.jpeg","video_url":"videos/Triceps/Dumbbell Pronate-grip Triceps Extension.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('86414f52-befa-4d4c-960a-ed71e83a06c0'::uuid, 'Dumbbell Prone Incline Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Set an incline bench to a 45-degree angle and lie chest first on the bench. Hold a dumbbell in each hand with your arms fully extended down and palms facing forward.\r\n2. Keeping your upper arms stationary, curl the dumbbells towards your shoulders by bending your elbows.\r\n3. Squeeze your biceps at the top of the movement, ensuring the dumbbells reach shoulder height.\r\n4. Lower the dumbbells back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Focus on a slow and controlled motion to maximize bicep engagement.\r\n2. Keep your wrists straight and aligned with your forearms.\r\n3. Avoid swinging the weights to isolate the biceps during the curl.', '{"image_male_start":"images/Biceps/Dumbbell Prone Incline Curl.jpeg","video_url":"videos/Biceps/Dumbbell Prone Incline Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a3b84bb2-4860-44bc-a1f8-6de2ba3b2042'::uuid, 'Dumbbell Prone Incline Hammer Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Set an incline bench to a 45-degree angle and lie chest first on the bench. Hold a dumbbell in each hand with your arms fully extended down and palms facing each other.\r\n2. Keeping your upper arms stationary, curl the dumbbells towards your shoulders by bending your elbows.\r\n3. Squeeze your biceps at the top of the movement, ensuring the dumbbells reach shoulder height.\r\n4. Lower the dumbbells back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Focus on a slow and controlled motion to maximize bicep engagement.\r\n2. Keep your wrists straight and aligned with your forearms.\r\n3. Avoid swinging the weights to isolate the biceps during the curl.', '{"image_male_start":"images/Biceps/Dumbbell Prone Incline Hammer Curl.jpeg","video_url":"videos/Biceps/Dumbbell Prone Incline Hammer Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e183837f-6dad-421d-ba9f-96b7a9825802'::uuid, 'Dumbbell Pullover', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by lying across a bench, with only your upper back and shoulders supported. Your feet should be flat on the floor, and your hips slightly lowered. Hold a dumbbell with both hands, palms pressed against the underside of the plates, arms extended straight above your chest.\r\n2. Keeping a slight bend in your elbows, lower the dumbbell in an arc over your head until your upper arms are in line with your torso.\r\n3. Pull the dumbbell back over your chest by contracting your chest and lats, following the same arc as you lowered it.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep a slight bend in your elbows throughout the movement to avoid joint strain.\r\n2. Ensure your upper back and shoulders are firmly supported on the bench.\r\n3. Avoid lowering the dumbbell too far behind your head to prevent shoulder strain.', '{"image_male_start":"images/Back/Dumbbell Pullover.jpg","image_male_end":"images/Back/Dumbbell Pullover1.jpg","video_url":"videos/Back/Dumbbell Pullover.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f2dcd2e1-6ca2-42c0-afa3-7de1849589af'::uuid, 'Dumbbell Pullover (VERSION 2)', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by lying on a flat bench, with your feet flat on the floor. Hold a dumbbell with both hands, palms pressed against the underside of the plates, arms extended straight above your chest.\r\n2. Keeping a slight bend in your elbows, lower the dumbbell in an arc over your head until your upper arms are in line with your torso.\r\n3. Pull the dumbbell back over your chest by contracting your chest and lats, following the same arc as you lowered it.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep a slight bend in your elbows throughout the movement to avoid joint strain.\r\n2. Ensure your back and shoulders are firmly supported on the bench.\r\n3. Avoid lowering the dumbbell too far behind your head to prevent shoulder strain.', '{"image_male_start":"images/Back/Dumbbell Pullover (VERSION 2).jpg","image_male_end":"images/Back/Dumbbell Pullover (VERSION 2)1.jpg","video_url":"videos/Back/Dumbbell Pullover (VERSION 2).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1141d9a5-6725-413c-8aee-ba24cb000d39'::uuid, 'Dumbbell Pullover Hip Extension on Exercise Ball', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by lying with your back on an exercise ball, feet flat on the floor, and knees bent at 90 degrees. Hold a dumbbell with both hands, palms pressed against the underside of the plates, arms extended straight above your chest.\r\n2. Lower your hips towards the floor by bending your knees, while simultaneously lowering the dumbbell in an arc over your head until your upper arms are in line with your torso.\r\n3. Extend your hips back to the starting position by squeezing your glutes and lifting your hips, while simultaneously pulling the dumbbell back over your chest by contracting your chest and lats.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep a slight bend in your elbows throughout the movement to avoid joint strain.\r\n2. Ensure your back is firmly supported on the exercise ball.\r\n3. Avoid lowering the dumbbell too far behind your head to prevent shoulder strain.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Dumbbell Pullover Hip Extension on Exercise Ball.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Dumbbell Pullover Hip Extension on Exercise Ball1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Dumbbell Pullover Hip Extension on Exercise Ball.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2fd1ca65-08de-4ac4-9954-e357fb881531'::uuid, 'Dumbbell Pullover on floor', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by lying flat on your back on the floor with your knees bent and feet flat. Hold a dumbbell with both hands, palms pressed against the underside of the plates, arms extended straight above your chest.\r\n2. Slowly lower the dumbbell in an arc over your head, keeping a slight bend in your elbows, until your upper arms are in line with your torso.\r\n3. Just before touching the floor, pull the dumbbell back over your chest by contracting your chest and lats, returning to the starting position.\r\n4. Repeat for the desired number of repetitions, maintaining control throughout the movement.', E'1. Maintain a slight bend in your elbows throughout the movement to protect your joints.\r\n2. Exhale as you pull the dumbbell back over your chest and inhale as you lower it.\r\n3. Use a weight that allows you to perform the exercise with proper form.', '{"image_male_start":"images/Back/Dumbbell Pullover on floor.jpg","image_male_end":"images/Back/Dumbbell Pullover on floor1.jpg","video_url":"videos/Back/Dumbbell Pullover on floor.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5b6c2389-8194-4bbc-a8c2-4964e59ce46a'::uuid, 'Dumbbell Push Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height, palms facing each other. Keep your elbows close to your body.\r\n2. Slightly bend your knees and lower your body into a quarter squat, then explosively extend your legs and perform a light jump to drive the dumbbells upward.\r\n3. Press the dumbbells overhead by extending your arms fully, locking out your elbows at the top of the movement.\r\n4. Lower the dumbbells back to shoulder height in a controlled manner and repeat for the desired number of repetitions.', E'1. Use the power generated from your legs and the light jump to help drive the dumbbells overhead.\r\n2. Use a weight that allows you to perform the exercise with proper form.\r\n3. Maintain a slight bend in your knees to absorb the impact of the weights.', '{"image_male_start":"images/Shoulders/Dumbbell Push Press.jpg","image_male_end":"images/Shoulders/Dumbbell Push Press1.jpg","video_url":"videos/Shoulders/Dumbbell Push Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('22b922d9-6152-4b8c-8772-dbf80a7588a4'::uuid, 'Dumbbell rdl stretch isometric', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet hip-width apart, holding a dumbbell in your left hand, arm fully extended by your side, and your palm facing your thigh. \r\n2. Hinge at your hips, lowering the dumbbell towards the floor while raising your left leg straight behind you, keeping it in line with your body. Your left leg should move in unison with your torso.\r\n3. Continue lowering the dumbbell until your torso is parallel to the floor and you feel a stretch in your hamstrings.\r\n4. Hold this stretched position for the desired duration, then return to the starting position.', E'1. Focus on hinging at your hips rather than bending your back.\r\n2. Keep your shoulders retracted and your chest lifted throughout the movement.\r\n3. Ensure your standing foot remains flat on the floor, with your weight distributed evenly.', '{"image_male_start":"images/Stretching - Mobility/dumbbell rdl stretch isometric  .jpg","video_url":"videos/Stretching - Mobility/dumbbell rdl stretch isometric  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('39d47331-7d06-4589-893b-9e1fda1ea440'::uuid, 'Dumbbell Rear Delt Row', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Kneel with your right knee on a bench and your left foot firmly planted on the floor for stability. Lean forward until your torso is parallel to the floor, and place your right hand on the bench for support. Hold a dumbbell in your left hand with an overhand grip, allowing it to hang straight down from your shoulder.\r\n2. Row the dumbbell up towards your side, allowing your elbow to flare out to the side. Focus on squeezing your shoulder blades together at the top of the movement.\r\n3. Hold the top position briefly, ensuring your upper arm is parallel to the floor and your elbow is pointing outward.\r\n4. Slowly lower the dumbbell back to the starting position with control, allowing your arm to fully extend.', E'1. Keep your elbow flared out to the side to target the rear delts effectively.\r\n2. Exhale as you row the dumbbell up and inhale as you lower it back down.\r\n3. Use a controlled and steady pace to maintain proper form and muscle engagement.', '{"image_male_start":"images/Shoulders/Dumbbell Rear Delt Row.jpg","image_male_end":"images/Shoulders/Dumbbell Rear Delt Row1.jpg","video_url":"videos/Shoulders/Dumbbell Rear Delt Row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('38fdbb44-6487-4af1-8508-a7c6160420f0'::uuid, 'Dumbbell Rear Full Shrugs', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand. Hold the dumbbells behind your back at shoulder width, with your palms facing each other.\r\n2. Lift your shoulders as high as possible towards your ears, squeezing your shoulders at the top of the movement.\r\n3. Slowly lower your shoulders back to the starting position with control, allowing your arms to fully extend.', E'1. Avoid using momentum or jerking motions; focus on a slow and controlled movement.\r\n2. Exhale as you lift your shoulders and inhale as you lower them back down.\r\n3. Keep your neck relaxed and avoid tensing it during the exercise.', '{"image_male_start":"images/Shoulders/Dumbbell Rear Full Shrugs.jpg","image_male_end":"images/Shoulders/Dumbbell Rear Full Shrugs1.jpg","video_url":"videos/Shoulders/Dumbbell Rear Full Shrugs.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a91ce747-775b-43c4-a804-c7c93182ba56'::uuid, 'Dumbbell Rear Lateral Raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your arms hanging straight down and palms facing each other.\r\n2. Hinge at the hips to lean forward, keeping your back straight and knees slightly bent. Your torso should be almost parallel to the floor.\r\n3. Lift the dumbbells out to the sides in a wide arc until your arms are in line with your shoulders. Keep a slight bend in your elbows throughout the movement.\r\n4. Slowly lower the dumbbells back to the starting position with control and repeat.', E'1. Focus on using your rear deltoids and upper back muscles to lift the weights.\r\n2. Avoid swinging the weights or using momentum; aim for a controlled and smooth motion.\r\n3. Exhale as you lift the dumbbells and inhale as you lower them.', '{"image_male_start":"images/Shoulders/Dumbbell Rear Lateral Raise.jpg","image_male_end":"images/Shoulders/Dumbbell Rear Lateral Raise1.jpg","video_url":"videos/Shoulders/Dumbbell Rear Lateral Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b87072a7-71d2-454a-bef4-f8e9079bc2d5'::uuid, 'Dumbbell Rear Lunge', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet hip-width apart, holding a dumbbell in each hand by your sides with your arms fully extended.\r\n2. Step your right foot back and lower your body into a lunge position, keeping your left knee over your left ankle and lowering your right knee towards the floor.\r\n3. Just before  your right knee touches the floor, push through your left heel to return to the starting position, bringing your right foot forward to stand up straight.\r\n4. Repeat the movement with your left leg stepping back. Alternate legs for the desired number of repetitions.', E'1. Maintain equal weight distribution between your front and back legs.\r\n2. Avoid letting your back knee touch the floor.\r\n3. Ensure your front knee does not go past your toes to avoid undue stress on the knee joint.', '{"image_male_start":"images/Legs/Dumbbell Rear Lunge.jpg","image_male_end":"images/Legs/Dumbbell Rear Lunge1.jpg","video_url":"videos/Legs/Dumbbell Rear Lunge.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('91dd39f0-ecdf-493e-b438-6471d46765b2'::uuid, 'Dumbbell Rear Lunge from Step', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand on a step with your feet hip-width apart, holding a dumbbell in each hand by your sides with your arms fully extended.\r\n2. Step your right foot back off the step and lower your body into a lunge position, keeping your left knee over your left ankle and lowering your right knee towards the floor.\r\n3. Just before  your right knee touches the floor, push through your left heel to return to the starting position on the step, bringing your right foot forward to stand up straight.\r\n4. Repeat the movement with your left leg stepping back off the step. Alternate legs for the desired number of repetitions.', E'1. Maintain equal weight distribution between your front and back legs.\r\n2. Avoid letting your back knee touch the floor.\r\n3. Ensure your front knee does not go past your toes to avoid undue stress on the knee joint.', '{"image_male_start":"images/Legs/Dumbbell Rear Lunge from Step.jpg","image_male_end":"images/Legs/Dumbbell Rear Lunge from Step1.jpg","video_url":"videos/Legs/Dumbbell Rear Lunge from Step.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0ebdc614-110e-4b9f-a4f7-f35df6400ccd'::uuid, 'Dumbbell Renegade Row', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin in a plank position with your feet hip-width apart and each hand holding a dumbbell, arms fully extended, and body forming a straight line from head to heels.\r\n2. Lift your right hand off the floor, rowing the dumbbell towards your right hip by bending your elbow and keeping your arm close to your body.\r\n3. Lower the dumbbell back to the floor with control, returning to the plank position.\r\n4. Repeat the row with your left hand. Alternate arms for the desired number of repetitions.', E'1. Maintain a straight body line, avoiding any sagging or lifting of the hips.\r\n2. Keep your core engaged to prevent your body from rotating during the row.\r\n3. Exhale as you lift the dumbbell and inhale as you lower it.', '{"image_male_start":"images/Back/Dumbbell Renegade Row.jpg","image_male_end":"images/Back/Dumbbell Renegade Row1.jpg","video_url":"videos/Back/Dumbbell Renegade Row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7abd943d-a429-4fbf-9fbd-905acee13a0f'::uuid, 'Dumbbell Reverse Fly', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by lying chest-first on an incline bench, with your feet planted firmly on the floor. Hold a dumbbell in each hand with your arms hanging down, palms facing each other.\r\n2. With a slight bend in your elbows, raise the dumbbells out to your sides until your arms are in line with your shoulders.\r\n3. Lower the dumbbells back to the starting position with control, maintaining the slight bend in your elbows.\r\n4. Repeat the exercise for the desired number of repetitions.', E'1. Keep your chest pressed against the bench to maintain stability.\r\n2. Focus on squeezing your shoulder blades together at the top of the movement.\r\n3. Exhale as you lift the dumbbells and inhale as you lower them.', '{"image_male_start":"images/Shoulders/Dumbbell Reverse Fly.jpg","image_male_end":"images/Shoulders/Dumbbell Reverse Fly1.jpg","video_url":"videos/Shoulders/Dumbbell Reverse Fly.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('caea3dff-66c0-400b-bdd7-cd44f04dd6ef'::uuid, 'Dumbbell Reverse grip Biceps Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip (palms facing down). Let the dumbbells hang by your sides.\r\n2. Keep your upper arms close to your body. Curl the dumbbells upward towards your shoulders by bending your elbows.\r\n3. Squeeze your biceps at the top of the movement, ensuring the dumbbells reach shoulder height.\r\n4. Lower the dumbbells back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Keep your wrists straight and avoid bending them throughout the movement.\r\n2. Keep your elbows close to your sides to ensure proper form.\r\n3. Exhale as you lift the dumbbells and inhale as you lower them.', '{"image_male_start":"images/Biceps/Dumbbell Reverse grip Biceps Curl.jpeg","video_url":"videos/Biceps/Dumbbell Reverse grip Biceps Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f663d3d3-7379-45ab-95a0-5d04eaedf398'::uuid, 'Dumbbell reverse lunge on the spot', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand by your sides, palms facing your body.\r\n2. Take a step backward with your right foot, lowering your body until your left thigh is parallel to the floor and your right knee is just above the floor.\r\n3. Push through your left heel to return to the starting position, bringing your right foot back to meet your left.\r\n4. Repeat the movement with your left leg, alternating legs for the desired number of repetitions.', E'1. Keep your back straight and your core engaged throughout the exercise.\r\n2. Make sure your front knee does not extend past your toes to avoid putting strain on the knee joint.\r\n3. Maintain a steady, controlled motion to ensure proper form and balance.', '{"image_male_start":"images/Legs/Dumbbell Reverse Lunge on the spot  .jpg","video_url":"videos/Legs/Dumbbell Reverse Lunge on the spot  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('72e3afe0-f601-4143-bc7b-6cb37f0c1f4d'::uuid, 'Dumbbell reverse lunges pulses', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand by your sides, palms facing your body.\r\n2. Take a step backward with your right foot, lowering your body until your left thigh is parallel to the floor and your right knee is just above the floor.\r\n3. Perform two small pulses by slightly raising and lowering your body while maintaining the lunge position.\r\n4. Push through your left heel to return to the starting position, bringing your right foot back to meet your left. Repeat the exercise for the desired number of repetitions.', E'1. Keep your back straight and your core engaged throughout the exercise.\r\n2. Make sure your front knee does not extend past your toes to avoid putting strain on the knee joint.\r\n3. Maintain a steady, controlled motion to ensure proper form and balance.', '{"image_male_start":"images/Legs/Dumbbell reverse lunges pulses  .jpg","video_url":"videos/Legs/Dumbbell reverse lunges pulses  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5f00b119-6b8b-4b5a-9420-44481dd3d752'::uuid, 'Dumbbell Reverse Spider Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by lying face down on an incline bench set at a 45-degree angle, with your chest supported on the bench and your forefeet planted firmly on the floor. Hold a dumbbell in each hand with an overhand grip (palms facing down), arms fully extended toward the floor.\r\n2. Keep your upper arms stationary as you curl the dumbbells up towards your shoulders, focusing on contracting your biceps.\r\n3. Squeeze your biceps at the top of the movement, ensuring your elbows remain steady.\r\n4. Lower the dumbbells back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Exhale as you curl the weights up and inhale as you lower them back down.\r\n2. Ensure your wrists remain straight and aligned with your forearms throughout the exercise.\r\n3. Keep your chest pressed against the bench to prevent any unnecessary movement.', '{"image_male_start":"images/Biceps/Dumbbell Reverse Spider Curl.jpeg","video_url":"videos/Biceps/Dumbbell Reverse Spider Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d4d159ef-40b2-47c4-87b7-370039beba63'::uuid, 'Dumbbell Reverse Wrist Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench with your feet flat on the floor, holding a dumbbell in each hand with an overhand grip (palms facing down). Rest your forearms on your thighs, letting your wrists hang over the edge of your knees.\r\n2. Start with your wrists in a neutral position, holding the dumbbells so that they point straight down.\r\n3. Curl the dumbbells up by extending your wrists upwards.\r\n4. Lower the dumbbells back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Avoid using momentum; focus on slow and controlled movements to maximize muscle engagement.\r\n2. Exhale as you curl the dumbbells up and inhale as you lower them back down.\r\n3. Maintain a firm grip on the dumbbells to prevent them from slipping.', '{"image_male_start":"images/Forearms/Dumbbell Reverse Wrist Curl.jpeg","video_url":"videos/Forearms/Dumbbell Reverse Wrist Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e5a4e39b-eb4c-4a28-bf59-69924c646ce5'::uuid, 'Dumbbell Romanian Deadlift', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet hip-width apart, holding a dumbbell in each hand with an overhand grip (palms facing your thighs). Keep your arms straight and the dumbbells close to your body.\r\n2. Hinge at the hips, pushing your hips back and lowering the dumbbells towards the floor. Keep a slight bend in your knees and maintain a neutral spine.\r\n3. Lower the dumbbells until the dumbbells reach just under your knees or until you feel a stretch in your hamstrings.\r\n4. Push through your heels to extend your hips and return to the starting position, bringing the dumbbells back to your thighs. Repeat for the desired number of repetitions.', E'1. Focus on hinging at the hips rather than bending at the waist.\r\n2. Keep the dumbbells close to your body throughout the movement for better control.\r\n3. Maintain a slight bend in your knees to reduce stress on your lower back.', '{"image_male_start":"images/Back/Dumbbell Romanian Deadlift.jpg","image_male_end":"images/Back/Dumbbell Romanian Deadlift1.jpg","video_url":"videos/Back/Dumbbell Romanian Deadlift.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('26006108-2f65-4546-a7fe-f57db2fd07e6'::uuid, 'Dumbbell Russian Twist with Legs Floor Off', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on the floor with your knees bent and your feet lifted slightly off the floor, balancing on your glutes. Hold a dumbbell with both hands at chest level, keeping your back straight and core engaged.\r\n2. Lean back slightly to form a V-shape with your torso and thighs, maintaining a straight spine.\r\n3. Rotate your torso to the right, bringing the dumbbell beside your right hip while keeping your legs stable together.\r\n4. Return to the center, then rotate your torso to the left, bringing the dumbbell beside your left hip. Continue alternating sides for the desired number of repetitions.', E'1. Keep your legs stable and together to maintain balance.\r\n2. Move slowly and with control to maximize muscle engagement.\r\n3. Use a weight that allows you to maintain proper form throughout the exercise.', '{"image_male_start":"images/Abdominals/Dumbbell Russian Twist with Legs Floor Off.jpeg","video_url":"videos/Abdominals/Dumbbell Russian Twist with Legs Floor Off.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('155db3f3-1362-4aef-8662-71e6e7aea6cc'::uuid, 'Dumbbell Scott Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand in front of your face, arms bent at 90 degrees, upper arms parallel to the floor.\r\n2. Move the dumbbells outward in an arc motion, keeping your elbows bent and slightly raised, until your arms are extended to your sides just higher than shoulder height.\r\n3. Bring the dumbbells back to the starting position in front of your face, maintaining the 90-degree bend in your elbows.\r\n4. Repeat the arc motion for the desired number of repetitions.', E'1. Keep your wrists straight and aligned with your forearms.\r\n2. Focus on using your shoulder muscles to move the weights.\r\n3. Avoid using excessive weights that compromise your form.', '{"image_male_start":"images/Shoulders/Dumbbell Scott Press.jpg","image_male_end":"images/Shoulders/Dumbbell Scott Press1.jpg","video_url":"videos/Shoulders/Dumbbell Scott Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('74b280ba-ebd0-490e-9d9f-103366aff941'::uuid, 'Dumbbell Scott Press (360 degrees)', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand in front of your face, arms bent at 90 degrees, upper arms parallel to the floor.\r\n2. Move the dumbbells outward in an arc motion, keeping your elbows bent and slightly raised, until your arms are extended to your sides just higher than shoulder height.\r\n3. Bring the dumbbells back to the starting position in front of your face, maintaining the 90-degree bend in your elbows.\r\n4. Repeat the arc motion for the desired number of repetitions.', E'1. Keep your wrists straight and aligned with your forearms.\r\n2. Focus on using your shoulder muscles to move the weights.\r\n3. Avoid using excessive weights that compromise your form.', '{"image_male_start":"images/Shoulders/Dumbbell Scott Press (360 degrees).jpg","image_male_end":"images/Shoulders/Dumbbell Scott Press (360 degrees)1.jpg","video_url":"videos/Shoulders/Dumbbell Scott Press (360 degrees).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d3f300fc-e6a2-4ff8-8939-9cfba8ff9fe1'::uuid, 'Dumbbell Seated Alternate Front Raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench with your feet flat on the floor and your back straight, holding a dumbbell in each hand with your arms hanging at your sides, palms facing your thighs.\r\n2. Raise your right arm straight in front of you to shoulder height while rotating the dumbbell to face down, keeping a slight bend in your elbow.\r\n3. Lower your right arm back to the starting position.\r\n4. Repeat by alternating arms for the desired number of repetitions.', E'1. Exhale as you raise each dumbbell and inhale as you lower it.\r\n2. Avoid swinging your body or using momentum; focus on controlled movements.\r\n3. Keep a slight bend in your elbows to reduce strain on your joints.', '{"image_male_start":"images/Shoulders/Dumbbell Seated Alternate Front Raise.jpg","image_male_end":"images/Shoulders/Dumbbell Seated Alternate Front Raise1.jpg","video_url":"videos/Shoulders/Dumbbell Seated Alternate Front Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b69ed91b-ae1b-40c5-8400-6ae1d26b379d'::uuid, 'Dumbbell Seated Alternate Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench with your back straight on the backrest and feet flat on the floor, holding a dumbbell in each hand in front of your face, arms bent at 90 degrees, upper arms parallel to the floor.\r\n2. Press the right dumbbell overhead until your arm is fully extended, keeping your left dumbbell in place.\r\n3. Lower the right dumbbell back to starting position and then press the left dumbbell overhead.\r\n4. Continue to alternate arms for the desired number of repetitions.', E'1. Ensure your wrists remain straight and aligned with your forearms.\r\n2. Use a weight that allows you to maintain proper form throughout the exercise.\r\n3. Press the dumbbells in a controlled manner, avoiding any jerking movements.', '{"image_male_start":"images/Shoulders/Dumbbell Seated Alternate Press.jpg","image_male_end":"images/Shoulders/Dumbbell Seated Alternate Press1.jpg","video_url":"videos/Shoulders/Dumbbell Seated Alternate Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('fdf478a5-6caa-446c-b69c-f571aa47feb7'::uuid, 'Dumbbell Seated Alternate Shoulder Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench with your back straight and feet flat on the floor, holding a dumbbell in each hand at shoulder level, elbows facing outside, palms facing forward.\r\n2. Press the right dumbbell overhead until your arm is fully extended, keeping your left dumbbell at shoulder level.\r\n3. Lower the right dumbbell back to shoulder level while simultaneously pressing the left dumbbell overhead.\r\n4. Continue to alternate arms for the desired number of repetitions.', E'1. Press the dumbbells in a controlled manner, avoiding any jerking movements.\r\n2. Keep your shoulders stable and avoid shrugging them during the press.\r\n3. Focus on using your shoulder muscles to lift the weights, minimizing involvement from other muscles.', '{"image_male_start":"images/Shoulders/Dumbbell Seated Alternate Shoulder Press.jpg","image_male_end":"images/Shoulders/Dumbbell Seated Alternate Shoulder Press1.jpg","video_url":"videos/Shoulders/Dumbbell Seated Alternate Shoulder Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ae3afc0c-21f4-4649-8180-8aa81cd78aa2'::uuid, 'Dumbbell Seated Bench Extension', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench with your back straight and feet flat on the floor, holding a dumbbell with both hands, positioning it behind your head.\r\n2. Begin with your elbows bent and pointed upwards, keeping your upper arms close to your head.\r\n3. Extend your elbows to lift the dumbbell upwards until your arms are fully extended, keeping your upper arms stationary.\r\n4. Lower the dumbbell back to the starting position with control, bending your elbows.', E'1. Avoid flaring your elbows out; keep them close to your head.\r\n2. Exhale as you extend your elbows and inhale as you lower the dumbbell.\r\n3. Ensure a slow and controlled movement to maintain proper form.', '{"image_male_start":"images/Triceps/Dumbbell Seated Bench Extension.jpeg","video_url":"videos/Triceps/Dumbbell Seated Bench Extension.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('16c59e56-b149-40ef-8fae-1a0e9cf18c04'::uuid, 'Dumbbell Seated Bent Arm Lateral raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench with your back straight and feet flat on the floor. Hold a dumbbell in each hand with your arms extended by your sides, palms facing each other.\r\n2. Raise your arms to the sides at shoulder level, keeping a light bend in your elbows throughout the movement.\r\n3. Lower the dumbbells back to the starting position with control. Repeat the exercise.', E'1. Maintain a slight bend in your elbows to reduce strain on your joints.\r\n2. Avoid swinging the weights; use a slow and controlled motion.\r\n3. Use a weight that allows you to maintain proper form throughout the exercise.', '{"image_male_start":"images/Shoulders/Dumbbell Seated Bent Arm Lateral raise.jpg","image_male_end":"images/Shoulders/Dumbbell Seated Bent Arm Lateral raise1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('db406340-2038-432a-9a33-c80c7877b961'::uuid, 'Dumbbell Seated Calf Raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench with your forefeet on a weight plate with heels extended to the floor, feet hip-width apart. Place a dumbbell on each knee, holding them in place with your hands.\r\n2. Lift your heels off the floor by extending your ankles, pushing through your forefeet to raise the dumbbells.\r\n3. Pause at the top of the movement, squeezing your calf muscles.\r\n4. Lower your heels back just before touching the floor with control, returning to the starting position. Repeat for the desired number of repetitions.', E'1. Ensure the dumbbells stay balanced on your knees throughout the exercise.\r\n2. Focus on the contraction in your calf muscles rather than using momentum.\r\n3. Use a full range of motion, ensuring a deep stretch at the bottom and a strong contraction at the top.', '{"image_male_start":"images/Legs/Dumbbell Seated Calf Raise.jpg","image_male_end":"images/Legs/Dumbbell Seated Calf Raise1.jpg","video_url":"videos/Legs/Dumbbell Seated Calf Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c7721165-8385-41d3-a9c4-626b35cb7d1b'::uuid, 'Dumbbell Seated Close Grip Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench with your back straight on the backrest and feet flat on the floor. Hold a dumbbell in each hand, bringing them close in front of your face with your palms facing your head.\r\n2. Press the dumbbells upward until your arms are extended overhead, maintaining a close grip throughout the movement.\r\n3. Lower the dumbbells back to the starting position with control, keeping the weights close together. Repeat for the desired number of repetitions.', E'1. Keep your back pressed firmly against the bench to avoid strain.\r\n2. Choose a weight that allows you to maintain proper form and control.\r\n3. Avoid locking your elbows at the top of the press; keep a slight bend to protect your joints.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7100bfcc-387b-4f51-b1d8-5ffbd257e556'::uuid, 'Dumbbell Seated Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench with your back straight and feet flat on the floor. Hold a dumbbell in each hand, letting your arms hang down by your sides with your palms facing your body (neutral grip).\r\n2. Keep your upper arms stationary and curl the dumbbells towards your shoulders by bending your elbows while rotating both wrists until your palms face the shoulders.\r\n3. Squeeze your biceps at the peak of the movement and hold for a second.\r\n4. Slowly lower the dumbbells back to the starting position. Repeat for the desired repetitions.', E'1. Avoid swinging your arms or using momentum; focus on controlled, slow movements.\r\n2. Exhale as you curl the dumbbells up and inhale as you lower them.\r\n3. Concentrate on using your biceps to lift the weights, minimizing shoulder involvement.', '{"image_male_start":"images/Biceps/Dumbbell Seated Curl.jpeg","video_url":"videos/Biceps/Dumbbell Seated Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d5609b9e-eb92-40dd-8e76-fe02d649f1a6'::uuid, 'Dumbbell Seated Front Raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit upright on a bench with your back on the backrest and feet flat on the floor. Hold a dumbbell in each hand, allowing your arms to hang down by your sides. Your palms should face your thighs.\r\n2. Begin the movement by raising both dumbbells in front of you, maintaining straight arms and rotating your palms to face down as the dumbbells rise.\r\n3. Continue lifting until your arms are parallel to the floor and the dumbbells are at shoulder height.\r\n4. Slowly and with control, lower the dumbbells back to the starting position, reversing the rotation of your palms to face your thighs again. Repeat for the desired number of repetitions.', E'1. Avoid using momentum; focus on slow and controlled movements.\r\n2. Exhale as you lift the dumbbells and inhale as you lower them.\r\n3. Maintain a slight bend in your elbows to reduce strain on your joints.', '{"image_male_start":"images/Shoulders/Dumbbell Seated Front Raise.jpg","image_male_end":"images/Shoulders/Dumbbell Seated Front Raise1.jpg","video_url":"videos/Shoulders/Dumbbell Seated Front Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6c45177a-ab93-4854-8890-fbf85cb9b8b0'::uuid, 'Dumbbell Seated Hammer Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit upright on a bench with your back on the backrest and feet flat on the floor. Hold a dumbbell in each hand, letting your arms hang down by your sides with your palms facing your body (neutral grip).\r\n2. Begin the movement by bending your elbows, curling the dumbbells up towards your shoulders. Your palms should continue to face each other throughout the movement.\r\n3. Squeeze your biceps at the top of the movement, ensuring the dumbbells reach shoulder height while keeping your elbows close to your body.\r\n4. Slowly lower the dumbbells back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Keep your back straight and pressed against the bench for stability.\r\n2. Avoid swinging the weights or using momentum; focus on a controlled motion.\r\n3. Exhale as you lift the dumbbells and inhale as you lower them.', '{"image_male_start":"images/Biceps/Dumbbell Seated Hammer Curl.jpeg","video_url":"videos/Biceps/Dumbbell Seated Hammer Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c682aed9-bfb9-4e7b-8801-2f62c9c6160f'::uuid, 'Dumbbell Seated Kickback', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on the edge of a bench with your feet flat on the floor. Hold a dumbbell in each hand, leaning slightly forward from your hips while keeping your back straight.\r\n2. Lift both upper arms so that they are parallel to the floor, keeping your elbows bent at a 90-degree angle. Your forearms should be hanging down, and your palms facing your body.\r\n3. Extend your arms straight back by straightening your elbows, keeping your upper arm stationary. Squeeze your triceps at the top of the movement.\r\n4. Slowly bend your elbows to return to the starting position. Repeat for the desired number of repetitions.', E'1. Keep your back straight and avoid rounding your shoulders.\r\n2. Exhale as you extend your arm and inhale as you return to the starting position.\r\n3. Use a controlled motion, focusing on squeezing your triceps at the top.', '{"image_male_start":"images/Triceps/Dumbbell Seated Kickback.jpeg","video_url":"videos/Triceps/Dumbbell Seated Kickback.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3759855e-1d33-44b8-b44e-7e93c5a32c79'::uuid, 'Dumbbell Seated Lateral Raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench with your feet flat on the floor, holding a dumbbell in each hand. Let your arms hang down by your sides with your palms facing your body.\r\n2. Keep a slight bend in your elbows as you lift both arms out to the sides until they reach shoulder height,  forming a "T" shape with your body.\r\n3. Slowly lower the dumbbells back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Avoid using momentum; lift and lower the weights in a controlled manner.\r\n2. Do not lock your elbows; maintain a slight bend to protect your joints.\r\n3. Exhale as you lift the dumbbells and inhale as you lower them.', '{"image_male_start":"images/Shoulders/Dumbbell Seated Lateral Raise.jpg","image_male_end":"images/Shoulders/Dumbbell Seated Lateral Raise1.jpg","video_url":"videos/Shoulders/Dumbbell Seated Lateral Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a8f6e20f-be26-48c8-91d2-5efef7fc2650'::uuid, 'Dumbbell Seated Neutral Wrist Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench with your feet flat on the floor. Hold a dumbbell in each hand with a neutral grip (palms facing each other).\r\n2. Rest your forearms on your thighs with your wrists hanging over the edge of your knees.\r\n3. Begin with your wrists in a neutral position, then curl the dumbbells upward by flexing your wrists.\r\n4. Hold the contraction briefly at the top, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', E'1. Keep your forearms stationary on your thighs throughout the exercise.\r\n2. Focus on moving only your wrists; avoid using your arms to lift the weights.\r\n3. Choose a weight that allows for proper form and control.', '{"image_male_start":"images/Forearms/Dumbbell Seated Neutral Wrist Curl.jpeg","video_url":"videos/Forearms/Dumbbell Seated Neutral Wrist Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a6d7d563-4696-4d6c-ab9e-d25a4f899313'::uuid, 'Dumbbell seated on exercise ball shoulder press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on an exercise ball with your feet flat on the floor, hip-width apart. Hold a dumbbell in each hand at shoulder level with your palms facing forward.\r\n2. Press the dumbbells upward until your arms are fully extended above your head.\r\n3. Briefly hold the position at the top, then slowly lower the dumbbells back to shoulder level.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Exhale as you press the dumbbells up and inhale as you lower them.\r\n2. Use a controlled motion to prevent any jerking or swinging.\r\n3. Ensure your feet are firmly planted on the floor to maintain balance.\r\n', '{"image_male_start":"images/Shoulders/dumbbell seated on exercise ball shoulder press.jpg","image_male_end":"images/Shoulders/dumbbell seated on exercise ball shoulder press1.jpg","video_url":"videos/Shoulders/dumbbell seated on exercise ball shoulder press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5064a558-6776-4507-9500-2b6c98a28348'::uuid, 'Dumbbell Seated One Leg Calf Raise Hammer Grip', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench with your right forefoot on a weightplate. Hold a dumbbell in your right hand and place it on your right thigh near your knee.\r\n2. Push through your right forefoot to raise your heel as high as possible, lifting the dumbbell. Briefly hold this position, squeezing your calf muscle.\r\n3. Slowly lower your heel back to the starting position. Repeat for the desired number of repetitions, then switch to the left leg.', E'1. Fully extend and contract your calf muscle for a full range of motion.\r\n2. Keep your core engaged for balance.\r\n3. Avoid placing the dumbbell directly on your knee joint.', '{"image_male_start":"images/Legs/Dumbbell Seated One Leg Calf Raise Hammer Grip.jpg","image_male_end":"images/Legs/Dumbbell Seated One Leg Calf Raise Hammer Grip1.jpg","video_url":"videos/Legs/Dumbbell Seated One Leg Calf Raise Hammer Grip.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ae6e868d-38be-424f-8adc-282ca90f2c59'::uuid, 'Dumbbell Seated Preacher Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a preacher bench with your chest against the support pad and your feet flat on the floor. Hold a dumbbell in each hand with an underhand grip (palms facing up).\r\n2. Extend your arms fully over the preacher bench pad, allowing the dumbbells to hang down in front of you.\r\n3. Curl the dumbbells upward towards your shoulders by bending your elbows, keeping your upper arms stationary against the pad.\r\n4. Squeeze your biceps at the top of the movement, then slowly lower the dumbbells back to the starting position. Repeat for the desired number of repetitions.', E'1. Keep your upper arms pressed against the pad to isolate the biceps.\r\n2. Ensure your wrists remain straight and aligned with your forearms.\r\n3. Avoid locking your elbows at the bottom of the movement.', '{"image_male_start":"images/Biceps/Dumbbell Seated Preacher Curl.jpeg","video_url":"videos/Biceps/Dumbbell Seated Preacher Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('39ff6b6c-e310-433e-85b2-17e3cb8ea824'::uuid, 'Dumbbell Seated Reverse grip Concentration Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench with your legs spread and your feet flat on the floor. Hold a dumbbell in your right hand with an overhand grip (palm facing down), lean forward and place your right elbow against the inside of your right thigh.\r\n2. Allow the dumbbell to hang straight down towards the floor while keeping your arm fully extended.\r\n3. Curl the dumbbell upward towards your shoulder by bending your elbow, focusing on engaging your biceps and forearms.\r\n4. Squeeze your biceps at the top of the movement, then slowly lower the dumbbell back to the starting position. Repeat for the desired number of repetitions.', E'1. Focus on squeezing your biceps and forearms at the top of the curl.\r\n2. Ensure your wrist remains straight and aligned with your forearm.\r\n3. Start with a lighter weight to ensure proper form.', '{"image_male_start":"images/Biceps/Dumbbell Seated Reverse grip Concentration Curl.jpeg","video_url":"videos/Biceps/Dumbbell Seated Reverse grip Concentration Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b156346f-2b45-4f75-97a0-1159164c67d9'::uuid, 'Dumbbell Seated Shoulder Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench with your back supported, holding a dumbbell in each hand at shoulder height with your palms facing forward.\r\n2. Press the dumbbells upward until your arms are fully extended above your head.\r\n3. Pause briefly at the top, ensuring your arms are straight but not locked.\r\n4. Lower the dumbbells back to shoulder height with control. Repeat for the desired number of repetitions.', E'1. Keep your back firmly against the bench to support your spine.\r\n2. Engage your core throughout the exercise to maintain stability.\r\n3. Exhale as you press the dumbbells up and inhale as you lower them.\r\n', '{"image_male_start":"images/Shoulders/Dumbbell Seated Shoulder Press.jpg","image_male_end":"images/Shoulders/Dumbbell Seated Shoulder Press1.jpg","video_url":"videos/Shoulders/Dumbbell Seated Shoulder Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('30581267-51c9-4469-adda-27a4178a0605'::uuid, 'Dumbbell seated shoulder press parallel grip', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench with back support. Hold a dumbbell in each hand at shoulder height, with your elbows bent at 90 degrees at chest level, facing forward, and your palms facing each other (parallel grip).\r\n2. Press the dumbbells upward by extending your elbows, until your arms are fully extended above your head.\r\n3. Pause briefly at the top of the movement, ensuring that your arms are straight but not locked.\r\n4. Lower the dumbbells back to starting position following the steps in reverse. Repeat for the desired number of repetitions.', E'1. Keep your back firmly pressed against the bench to support your spine.\r\n2. Engage your core muscles throughout the exercise to maintain stability.\r\n3. Exhale as you press the dumbbells upward and inhale as you lower them.', '{"image_male_start":"images/Shoulders/dumbbell seated shoulder press parallel grip.jpg","image_male_end":"images/Shoulders/dumbbell seated shoulder press parallel grip1.jpg","video_url":"videos/Shoulders/dumbbell seated shoulder press parallel grip.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6086b4d9-c9e0-4e75-ab09-26512a9d09e2'::uuid, 'Dumbbell shrugs', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your arms fully extended by your sides. Your palms should be facing your thighs.\r\n2. Raise your shoulders towards your ears by contracting your trapezius muscles, lifting the dumbbells without bending your elbows.\r\n3. Hold the contraction at the top for a brief moment, squeezing your trapezius muscles.\r\n4. Lower your shoulders back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep your back straight and avoid using momentum to lift the dumbbells.\r\n2. Focus on lifting your shoulders straight up rather than rolling them forward or backward.\r\n3. Exhale as you lift your shoulders and inhale as you lower them.', '{"image_male_start":"images/Shoulders/dumbbell shrugs.jpg","image_male_end":"images/Shoulders/dumbbell shrugs1.jpg","video_url":"videos/Shoulders/dumbbell shrugs.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7238d94f-0d12-4780-b288-0b4e2b546c16'::uuid, 'Dumbbell Side Bend', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in your right hand with your arm fully extended by your side. Place your left hand behind your head.\r\n2. Slowly bend to your right side at the waist, lowering the dumbbell towards the floor. \r\n3. Bend as far as comfortably possible, feeling a stretch in your left oblique muscles.\r\n4. Return to the starting position. Repeat for the desired number of repetitions, then switch to the left side.', E'1. Avoid using momentum; focus on a slow and controlled movement.\r\n2. Exhale as you bend to the side and inhale as you return to the starting position.\r\n3. Keep your head and neck in a neutral position, facing forward.', '{"video_url":"videos/Abdominals/Dumbbell Side Bend.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8435fa9d-cb66-482a-94c8-02f477e8490a'::uuid, 'Dumbbell side lunge alternating', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your arms at your sides.\r\n2. Take a large step to your right with your right foot, bending your right knee and lowering your hips down and back as if you are sitting into a chair. Keeping your left leg straight and rotating it until your left foot points to the ceiling.\r\n3. Lower yourself until your right thigh is parallel to the floor, ensuring your knee does not extend past your toes. The dumbbells should be hanging down towards the floor on either side of your right leg.\r\n4. Push through your right heel to return to the starting position. Continue alternating sides for the desired number of repetitions.', E'1. Keep your back straight and avoid leaning forward excessively.\r\n2. Keep your feet facing forward and your weight distributed evenly.\r\n3. Make sure your knee stays aligned with your toes during the lunge to prevent strain.', '{"image_male_start":"images/Legs/Dumbbell Side Lunge Alternating  .jpg","video_url":"videos/Legs/Dumbbell Side Lunge Alternating  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3cf4fc6f-f1bd-4e57-a9cc-b9225b4f2732'::uuid, 'Dumbbell side lunge left n right', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your arms at your sides.\r\n2. Take a large step to your right with your right foot, bending your right knee and lowering your hips down and back as if you are sitting into a chair. Keeping your left leg straight.\r\n3. Lower yourself until your right thigh is parallel to the floor, ensuring your knee does not extend past your toes. The dumbbells should be hanging down towards the floor on either side of your right leg.\r\n4. Push through your right heel to return to the starting position. Continue alternating sides for the desired number of repetitions.', E'1. Keep your back straight and avoid leaning forward excessively.\r\n2. Keep your feet facing forward and your weight distributed evenly.\r\n3. Make sure your knee stays aligned with your toes during the lunge to prevent strain.', '{"image_male_start":"images/Legs/dumbbell side lunge left n right.jpg","image_male_end":"images/Legs/dumbbell side lunge left n right1.jpg","video_url":"videos/Legs/dumbbell side lunge left n right.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f39cf295-aab6-49db-99d2-0031630f4f03'::uuid, 'Dumbbell Side Lunge Single Leg', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet together, holding a dumbbell with both hands close to your chest. \r\n2. Take a large step to your left with your left foot, bending your left knee and lowering your hips down and back as if you are sitting into a chair. Keep your right leg straight.\r\n3. Lower yourself until your left thigh is parallel to the floor.\r\n4. Push through your left heel to return to the starting position. Perform all repetitions on the left side before switching to the right side and repeating the exercise.', E'1. Keep your back straight and avoid leaning forward excessively.\r\n2. Keep your feet facing forward and your weight distributed evenly.\r\n3. Make sure your knee stays aligned with your toes during the lunge to prevent strain.', '{"image_male_start":"images/Legs/Dumbbell Side Lunge Single Leg.jpg","image_male_end":"images/Legs/Dumbbell Side Lunge Single Leg1.jpg","video_url":"videos/Legs/Dumbbell Side Lunge Single Leg.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('edb01224-31fc-4142-b9df-f44ead28674f'::uuid, 'Dumbbell Side Lying One Hand Raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie on your right side on a bench, with your legs stacked and your right elbow on the bench for support. Hold a dumbbell in your left hand with your arm resting along your left side.\r\n2. Slowly raise the dumbbell towards the ceiling, keeping your arm straight until it is fully extended.\r\n3. Lower the dumbbell back down to the starting position in a controlled manner, focusing on engaging your shoulder muscles throughout the movement.\r\n4. Repeat the exercise for the desired number of repetitions on your left side.', E'1. Keep your core engaged to maintain stability and prevent your torso from rotating.\r\n2. Use a slow and controlled motion to maximize muscle engagement and reduce the risk of injury.\r\n3. Focus on breathing steadily, exhaling as you lift the dumbbell and inhaling as you lower it.', '{"image_male_start":"images/Shoulders/Dumbbell Side Lying One Hand Raise.jpg","image_male_end":"images/Shoulders/Dumbbell Side Lying One Hand Raise1.jpg","video_url":"videos/Shoulders/Dumbbell Side Lying One Hand Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('52314a05-038f-441d-b4a6-b35345208c68'::uuid, 'Dumbbell Side Plank with Rear Fly', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by positioning yourself in a side plank on your right side, with your right elbow directly under your shoulder and both feet on the floor   shoulder-width apart. Hold a dumbbell in your left hand, with your arm extended straight out in front of your chest.\r\n2. Engage your core to lift your hips off the floor, creating a straight line from your head to your feet. Maintain this plank position throughout the exercise.\r\n3. Slowly raise the dumbbell in a wide arc motion outwards, lifting your arm until it is just higher than parallel to the floor, while slightly rotating your torso to the left.\r\n4. Lower the dumbbell back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Focus on a slow and controlled movement to effectively engage the shoulder and upper back muscles.\r\n2. Avoid letting your hips sag; keep your body in a straight line.\r\n3. Start with a lighter weight to ensure proper form before progressing to heavier dumbbells.', '{"image_male_start":"images/Abdominals/Dumbbell Side Plank with Rear Fly.jpeg","video_url":"videos/Abdominals/Dumbbell Side Plank with Rear Fly.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e729f71a-3172-468d-9f9c-3b9297b864f0'::uuid, 'Dumbbell Side Squat Side to Side', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by standing with your feet wider than shoulder-width apart, holding a dumbbell close to your chest.\r\n2. Shift your weight to your right leg, bending your knee and pushing your hips back to lower into a side lunge. Keep your left leg straight and your chest up.\r\n3. Push through your right heel to return to the starting position, straightening your leg.\r\n4. Continue alternating sides for the desired number of repetitions.', E'1. Keep your chest up and back straight throughout the movement.\r\n2. Engage your core to maintain balance and stability.\r\n3. Avoid letting your knees collapse inward; keep them aligned with your toes.', '{"image_male_start":"images/Legs/Dumbbell Side Squat Side to Side.jpg","image_male_end":"images/Legs/Dumbbell Side Squat Side to Side1.jpg","video_url":"videos/Legs/Dumbbell Side Squat Side to Side.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8f5c9d2f-21db-4847-becd-b6a8b5e0a141'::uuid, 'Dumbbell Simultaneous Biceps Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your arms fully extended and palms facing forward.\r\n2. Simultaneously curl both dumbbells upward towards your shoulders by bending your elbows, keeping your upper arms stationary.\r\n3. Squeeze your biceps at the top of the movement, ensuring the dumbbells reach shoulder height.\r\n4. Lower the dumbbells back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Keep your upper arms stationary and avoid swinging the weights.\r\n2. Avoid using momentum; focus on using your biceps to lift the weights.\r\n3. Exhale as you curl the weights up and inhale as you lower them.', '{"image_male_start":"images/Biceps/Dumbbell Simultaneous Biceps Curl.jpeg","video_url":"videos/Biceps/Dumbbell Simultaneous Biceps Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2970b780-80d6-4ae5-ac2b-81372c03093f'::uuid, 'Dumbbell Single Arm Floor Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by lying flat on your back on the floor with your knees bent and feet flat on the floor. Hold a dumbbell in your right hand with your arm bent and your elbow touching the floor, at a 45-degree angle from your body.\r\n2. Press the dumbbell up by extending your arm until it is fully straightened towards the ceiling.\r\n3. Lower the dumbbell back down with control, bringing your elbow back to a few inches off the floor.\r\n4. Complete the desired number of repetitions with the right arm, then switch to the left arm and repeat the movement.', E'1. Maintain a neutral wrist position throughout the movement.\r\n2. Exhale as you press the dumbbell up and inhale as you lower it.\r\n3. Ensure your non-working arm is firm on the floor for support.', '{"video_url":"videos/Chest/Dumbbell Single Arm Floor Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('cdd85534-e0f2-483b-ab91-540e8b53e1f4'::uuid, 'Dumbbell Single Arm Floor Press From Close Elbow', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by lying flat on your back on the floor with your knees bent and feet flat on the floor. Hold a dumbbell in your right hand, positioning your arm close to your body with your elbow touching the floor and bent at a 90-degree angle.\r\n2. Press the dumbbell up by extending your arm until it is fully straightened towards the ceiling.\r\n3. Lower the dumbbell back down with control, bringing your elbow back to the starting position close to your body and touching the floor.\r\n4. Complete the desired number of repetitions with the right arm, then switch to the left arm and repeat the movement.', E'1. Maintain a neutral wrist position throughout the movement.\r\n2. Exhale as you press the dumbbell up and inhale as you lower it.\r\n3. Ensure your non-working arm is firm on the floor for support.', '{"image_male_start":"images/Chest/Dumbbell Single Arm Floor Press From Close Elbow.jpg","image_male_end":"images/Chest/Dumbbell Single Arm Floor Press From Close Elbow1.jpg","video_url":"videos/Chest/Dumbbell Single Arm Floor Press From Close Elbow.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9fb4b5d8-1486-4761-b548-347575aca74c'::uuid, 'Dumbbell Single arm Leaning Lateral Raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by standing next to a weight cage, and grasp it with one hand for support. Lean your body slightly away from the surface, keeping your feet together. Hold a dumbbell in the other hand with your arm extended down by your side and palm facing your body.\r\n2. Raise the dumbbell out to the side until your arm reaches shoulder height, keeping a slight bend in your elbow and maintaining a controlled motion.\r\n3. Pause briefly at the top of the movement, ensuring your arm is parallel to the floor.\r\n4. Lower the dumbbell back to the starting position with control. Repeat for the desired number of repetitions, then switch to the other arm.', E'1. Do not raise the dumbbell higher than shoulder height to prevent shoulder strain.\r\n2. Use a controlled motion to lift and lower the weight, avoiding excessive momentum.\r\n3. Exhale as you lift the dumbbell and inhale as you lower it.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('144aae73-de9d-4c8d-b317-a1520b6f64df'::uuid, 'Dumbbell Single Arm Overhead Carry', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by standing with your feet shoulder-width apart, holding a dumbbell in your right hand. Press the dumbbell overhead until your arm is fully extended.\r\n2. Walk forward in a straight line for the desired distance, keeping the dumbbell steady overhead.\r\n3. Once you''ve covered the desired distance, carefully lower the dumbbell back to your shoulder and switch to your left hand. Repeat the movement with your left arm overhead.', E'1. Maintain a steady and controlled pace while walking.\r\n2. Ensure your arm is fully extended with your wrist straight.\r\n3. Avoid leaning or tilting your torso to one side.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Dumbbell Single Arm Overhead Carry.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Dumbbell Single Arm Overhead Carry1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Dumbbell Single Arm Overhead Carry.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6a66a0d4-3d31-4b4c-bdc9-5eb247638de1'::uuid, 'Dumbbell single arm overhead lunge', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '7352a8b5-30da-44d7-9cae-8a031f5d2aed'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in your right hand. Press the dumbbell overhead, fully extending your arm.\r\n2. Step forward with your right foot into a lunge position, lowering your hips until both knees are bent at a 90-degree angle.\r\n3. Push through your right heel to return to the starting position, maintaining the dumbbell overhead throughout the movement.\r\n4. Repeat for the desired number of repetitions.', E'1. Ensure your front knee does not extend past your toes during the lunge.\r\n2. Maintain an upright posture, keeping your chest up and shoulders back.\r\n3. Focus on a controlled descent into the lunge to avoid straining your knee joints.', '{"image_male_start":"images/Legs/Dumbbell Single Arm Overhead Lunge.jpg","image_male_end":"images/Legs/Dumbbell Single Arm Overhead Lunge1.jpg","video_url":"videos/Legs/Dumbbell Single Arm Overhead Lunge.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('80223bfd-ae54-48ef-8800-7a680d3f311c'::uuid, 'Dumbbell single arm row', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Place your left knee and left hand on a bench, lean your back down to almost parallel to the floor. Your right foot should be planted firmly on the floor, knee bent and slightly behind for balance. Hold a dumbbell in your right hand, arm extended towards the floor.\r\n2. Pull the dumbbell towards your hip by bending your elbow, keeping it close to your body. Focus on squeezing your back muscles at the top of the movement.\r\n3. Slowly lower the dumbbell back to the starting position, fully extending your arm with control.\r\n4. Repeat for the desired number of repetitions, then switch sides to perform the exercise with your left arm.', E'1. Avoid rotating your torso as you row; keep your core engaged to maintain stability.\r\n2. Use a controlled motion to lift and lower the dumbbell.\r\n3. Ensure your supporting knee and hand are positioned securely on the bench for stability.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('46d3c5b8-bc1b-499b-99fd-e590904fb3c4'::uuid, 'Dumbbell single arm shoulder press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by standing with your feet shoulder-width apart, holding a dumbbell in your right hand. Position the dumbbell at shoulder height, by its side, with your palm facing forward and your elbow bent and your free hand on your hip.\r\n2. Press the dumbbell overhead by extending your arm until it is fully straight.\r\n3. Lower the dumbbell back to shoulder height in a controlled manner. Repeat for the desired number of repetitions, then switch to your left hand.', E'1. Focus on using your shoulder muscles to lift the weight.\r\n2. Avoid arching your back; maintain a neutral spine.\r\n3. Breathe out as you press the dumbbell up and inhale as you lower it.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f1db496c-9628-4aef-bb53-f681f185d06e'::uuid, 'Dumbbell Single Arm Starfish Crunch', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by lying flat on your back with your arms and legs extended in a starfish position. Hold a dumbbell in your right hand and keep the left hand firm on the floor.\r\n2. Engage your core and lift your left leg and right arm simultaneously, aiming to touch the dumbbell to your left foot.\r\n3. Reach as high as possible, squeezing your abdominal muscles at the top of the movement.\r\n4. Lower your arm and leg back to the starting position in a controlled manner. Repeat for the desired number of repetitions, then switch to holding the dumbbell in your left hand and raising your right leg.', E'1. Ensure your movements are slow and controlled to maximize muscle engagement.\r\n2. Keep your non-working arm and leg extended on the floor for balance.\r\n3. Focus on using your abs to lift your arm and leg, not your neck or shoulders.', '{"image_male_start":"images/Abdominals/Dumbbell Single Arm Starfish Crunch.jpeg","video_url":"videos/Abdominals/Dumbbell Single Arm Starfish Crunch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('043d9d17-4fc7-456e-b5db-1568b0a2bd21'::uuid, 'Dumbbell Single Arm Underhand Front Raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in your right hand with an underhand grip (palm facing forward). Let your arm hang straight down at your side.\r\n2. Slowly raise the dumbbell in front of you to shoulder height, keeping your arm straight and your palm facing up.\r\n3. Pause briefly at the top of the movement, ensuring your arm is parallel to the floor.\r\n4. Lower the dumbbell back to the starting position in a controlled manner. Repeat for the desired number of repetitions, then switch to the left arm.', E'1. Maintain a slight bend in your elbow to protect your joints.\r\n2. Focus on using your shoulder muscles to lift the weight, not your biceps.\r\n3. Exhale as you raise the dumbbell and inhale as you lower it.', '{"image_male_start":"images/Shoulders/Dumbbell Single Arm Underhand Front Raise.jpg","image_male_end":"images/Shoulders/Dumbbell Single Arm Underhand Front Raise1.jpg","video_url":"videos/Shoulders/Dumbbell Single Arm Underhand Front Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('92fec31e-f279-4cf2-8c2c-f98203bb71db'::uuid, 'Dumbbell Single Leg Calf Raise Wall Support', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your right side facing a wall, placing your right hand on the wall for support and holding a dumbbell in your left hand. Lift your right leg off the floor, balancing on your left leg.\r\n2. Press through your eight forefoot to raise your heel off the floor as high as possible.\r\n3. Pause briefly at the top of the movement, squeezing your calf muscle.\r\n4. Lower your heel back to the starting position in a controlled manner. Repeat for the desired number of repetitions.', E'1. Keep your movements slow and controlled to maximize muscle engagement.\r\n2. Maintain a straight posture, avoiding leaning forward or backward.\r\n3. Exhale as you lift your heel and inhale as you lower it.', '{"image_male_start":"images/Legs/Dumbbell Single Leg Calf Raise Wall Support.jpg","image_male_end":"images/Legs/Dumbbell Single Leg Calf Raise Wall Support1.jpg","video_url":"videos/Legs/Dumbbell Single Leg Calf Raise Wall Support.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('aaf81582-cb44-492f-8868-c2dc6ea8fbbf'::uuid, 'Dumbbell Single Leg Deadlift', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet hip-width apart, holding a dumbbell in each hand extended down in front of you. Shift your weight onto your left leg and lift your right foot slightly off the floor behind you.\r\n2. Begin to hinge at your hips, extending your right leg straight behind you while lowering the dumbbells towards the floor. Keep a slight bend in your left knee.\r\n3. Lower the dumbbells until your torso is parallel to the floor, or as far as your flexibility allows, maintaining a straight line from your head to your right heel.\r\n4. Return to the starting position by driving through your left heel and bringing your right leg forward, keeping it off the floor. Repeat for the desired number of repetitions, then switch to the left hand and right leg.', E'1. Ensure your back stays straight throughout the exercise to avoid injury.\r\n2. Focus on a point in front of you to help maintain balance.\r\n3. Exhale as you lower the dumbbell and inhale as you return to the starting position.', '{"image_male_start":"images/Legs/Dumbbell Single Leg Deadlift.jpg","image_male_end":"images/Legs/Dumbbell Single Leg Deadlift1.jpg","video_url":"videos/Legs/Dumbbell Single Leg Deadlift.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('45ea7ff2-8535-4a3a-93c9-710d0901eee9'::uuid, 'Dumbbell Single Leg Glute Bridge', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by lying flat on your back with your knees bent and feet flat on the floor. Hold a dumbbell across your hips with both hands. Extend your left leg straight out in front of you, keeping it in line with your right thigh.\r\n2. Engage your core and squeeze your glutes. Drive through your right heel to lift your hips towards the ceiling, forming a straight line from your shoulders to your right knee.\r\n3. Hold the top position briefly, squeezing your glutes and maintaining a straight line with your body.\r\n4. Lower your hips back to the starting position with control, ensuring your left leg remains extended. Repeat for the desired number of repetitions, then switch to the other leg.', E'1. Ensure your shoulders, hips, and knees form a straight line at the top of the movement.\r\n2. Drive through your heel to maximize glute activation.\r\n3. Avoid overarching your lower back; keep the movement focused on your glutes and hamstrings.', '{"image_male_start":"images/Yoga/Dumbbell Single Leg Glute Bridge.jpg","image_male_end":"images/Yoga/Dumbbell Single Leg Glute Bridge1.jpg","video_url":"videos/Yoga/Dumbbell Single Leg Glute Bridge.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4997a3c9-c93e-43bf-a5d2-15216bdbb955'::uuid, 'Dumbbell Single Leg Split Squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by standing with your back facing a bench. Hold a dumbbell in each hand at your sides. Lift your left foot back to rest on the bench behind you.\r\n2. Lower your body into a squat position by bending your right knee, keeping your torso upright. Your right knee should align over your ankle, and your left knee should lower towards the floor without touching it.\r\n3. Push through your right heel to return to the starting position, straightening your right leg.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep your torso upright and avoid leaning forward.\r\n2. Ensure your front knee does not extend past your toes.\r\n3. Keep your front foot firmly planted.', '{"image_male_start":"images/Legs/Dumbbell Single Leg Split Squat.jpg","image_male_end":"images/Legs/Dumbbell Single Leg Split Squat1.jpg","video_url":"videos/Legs/Dumbbell Single Leg Split Squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('731404c2-57ed-42a2-bb40-7a85532cb11a'::uuid, 'Dumbbell Single Leg Squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by standing on your right leg, holding a dumbbell in each hand at your sides. Lift your left leg slightly off the floor, keeping it straight and extended in front of you.\r\n2. Lower your body into a squat position by bending your right knee. Your left leg should remain extended in front of you without touching the floor.\r\n3. Lower until your right thigh is parallel to the floor, ensuring your knee stays aligned with your foot and doesn''t go past your toes.\r\n4. Push through your right heel to return to standing position, keeping your left leg extended. Repeat for the desired repetitions, then switch to the left leg.', E'1. Start with a lower weight or no weight to master the form before increasing the resistance.\r\n2. Keep your torso upright and avoid leaning forward.\r\n3. Keep your balance by engaging your core and focusing on a fixed point in front of you.', '{"image_male_start":"images/Legs/Dumbbell Single Leg Squat.jpg","image_male_end":"images/Legs/Dumbbell Single Leg Squat1.jpg","video_url":"videos/Legs/Dumbbell Single Leg Squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('cc4f970c-ca9c-4e99-9801-d0ba9be9a4c1'::uuid, 'Dumbbell Single Leg Squat with Support (pistol)', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand next to a lifting cage and hold the lifting cage bar for support with your right hand. Hold a dumbbell in your left hand, allowing it to hang down to your side. Position your feet hip-width apart.\r\n2. Lift your right leg off the floor and extend it forward.\r\n3. Bend your right knee to lower your body into a squat position. Lower yourself as far as you can while maintaining control and balance.\r\n4. Press through the heel of your right leg to return to the starting position, fully extending your leg. Repeat for the desired number of repetitions.', E'1. Keep your chest up and avoid leaning forward excessively.\r\n2. Focus on maintaining balance by using the support lightly, not relying on it entirely.\r\n3. Perform the movement in a slow and controlled manner to ensure proper form and muscle engagement.', '{"image_male_start":"images/Legs/Dumbbell Single Leg Squat with Support (pistol).jpg","image_male_end":"images/Legs/Dumbbell Single Leg Squat with Support (pistol)1.jpg","video_url":"videos/Legs/Dumbbell Single Leg Squat with Support (pistol).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ee1f3c07-df0e-485b-b5b9-30dfee91bdcf'::uuid, 'Dumbbell Single Leg Step-Up', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand facing a sturdy platform, holding a dumbbell in each hand with arms at your sides.\r\n2. Lift and place your right foot on the platform, ensuring your entire foot is firm. \r\n3. Push through your right heel to lift your body onto the bench, bringing your left foot up to meet your right foot on the bench.\r\n4. Step back down with your left foot, followed by your right foot, returning to the starting position. Repeat for the desired number of reps, then switch to the left leg.', E'1. Ensure the bench or platform is stable and secure.\r\n2. Keep your chest up and shoulders back throughout the exercise.\r\n3. Push through your heel rather than your toes for better glute activation.\r\n', '{"image_male_start":"images/Legs/Dumbbell Single Leg Step-Up.jpg","image_male_end":"images/Legs/Dumbbell Single Leg Step-Up1.jpg","video_url":"videos/Legs/Dumbbell Single Leg Step-Up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7d816842-63a8-44ae-8a98-cb6563a4c9e0'::uuid, 'Dumbbell Split Squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet hip-width apart, holding a dumbbell in each hand at your sides.\r\n2. Step your right foot forward and your left foot back, keeping your feet hip-width apart for balance.\r\n3. Lower your body into a lunge position by bending both knees until your front knee is directly above your ankle and your back knee is hovering just above the floor.\r\n4. Push through your front heel to return to the starting position. Repeat for the desired number of repetitions, then switch legs.', E'1. Keep your torso upright and your core engaged throughout the movement.\r\n2. Ensure your front knee does not extend past your toes.\r\n3. Keep your feet hip-width apart to maintain balance.', '{"image_male_start":"images/Legs/Dumbbell Split Squat.jpg","image_male_end":"images/Legs/Dumbbell Split Squat1.jpg","video_url":"videos/Legs/Dumbbell Split Squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('396d8e2c-2492-4612-8623-5ec5560fce77'::uuid, 'Dumbbell squats', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand at your sides. Keep your chest up and shoulders back.\r\n2. Bend your knees and push your hips back as if you are sitting in a chair, lowering your body into a squat position. Ensure your knees do not extend beyond your toes.\r\n3. Continue lowering until your thighs are parallel to the floor, keeping your weight evenly distributed through your heels.\r\n4. Push through your heels to stand back up to the starting position, squeezing your glutes at the top.', E'1. Keep your feet flat on the floor to maintain stability.\r\n2. Align your knees with your toes throughout the movement to prevent straining your knees.\r\n3. Lower yourself in a controlled manner to maintain balance and form.', '{"image_male_start":"images/Legs/Dumbbell Squats  .jpg","video_url":"videos/Legs/Dumbbell Squats  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('70e5da2f-5344-46f2-b671-2d95d5de8df3'::uuid, 'Dumbbell squats to shoulder press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height just in front of your shoulders, palms facing each other.\r\n2. Lower into a squat by bending your knees and hips, keeping your back straight and chest up until your thighs are parallel to the floor.\r\n3. Push through your heels to stand up while simultaneously pressing the dumbbells overhead until your arms are fully extended.\r\n4. Lower the dumbbells back to shoulder height as you prepare for the next squat. Repeat the movement for the desired number of repetitions.', E'1. Ensure your knees do not extend past your toes during the squat to avoid unnecessary strain.\r\n2. Exhale as you press the dumbbells overhead and inhale as you lower into the squat.\r\n3. Keep your back straight and avoid leaning forward during the squat.', '{"image_male_start":"images/Legs/Dumbbell Squats to Shoulder Press  .jpg","video_url":"videos/Legs/Dumbbell Squats to Shoulder Press  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('86bc6ef9-ad70-4465-9f40-cee73096dfb6'::uuid, 'Dumbbell Standing Alternate Overhead Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing each other.\r\n2. Press the right dumbbell overhead until your arm is fully extended while keeping the left dumbbell at shoulder height.\r\n3. Lower the right dumbbell back to shoulder height and then press the left dumbbell overhead until your left arm is fully extended.\r\n4. Continue alternating the press between your right and left arms for the desired number of repetitions.', E'1. Ensure your back remains straight and avoid leaning backward during the press.\r\n2. Exhale as you press the dumbbell overhead and inhale as you lower it back down.\r\n3. Use a controlled motion to avoid jerking the weights and maintain proper form.', '{"image_male_start":"images/Shoulders/Dumbbell Standing Alternate Overhead Press.jpg","image_male_end":"images/Shoulders/Dumbbell Standing Alternate Overhead Press1.jpg","video_url":"videos/Shoulders/Dumbbell Standing Alternate Overhead Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('045c69bf-162b-4ada-80e0-bf6b41256476'::uuid, 'Dumbbell Standing Alternate Raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your arms hanging by your sides and palms facing backward.\r\n2. Raise the right dumbbell in front of you until your arm is parallel to the floor, keeping a slight bend in your elbow.\r\n3. Lower the right dumbbell back to the starting position and then raise the left dumbbell in front of you until your arm is parallel to the floor.\r\n4. Continue alternating the raise between your right and left arms for the desired number of repetitions.', E'1. Use a controlled motion to avoid swinging the weights and maintain proper form.\r\n2. Keep your head and neck in a neutral position, looking straight ahead.\r\n3. Avoid locking your elbows at the top of the movement to reduce joint strain.', '{"image_male_start":"images/Shoulders/Dumbbell Standing Alternate Raise.jpg","image_male_end":"images/Shoulders/Dumbbell Standing Alternate Raise1.jpg","video_url":"videos/Shoulders/Dumbbell Standing Alternate Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('64975a80-1b6f-48dd-b73d-d35dbb9691f8'::uuid, 'Dumbbell Standing Alternate Vertical Front Raises', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your arms hanging straight down by your sides, palms facing your body.\r\n2. Raise the right dumbbell in front of you, keeping your arm straight but not locked, until it reaches shoulder height.\r\n3. Lower the right dumbbell back to the starting position and then raise the left dumbbell in front of you to shoulder height.\r\n4. Continue alternating the raise between your right and left arms for the desired number of repetitions.', E'1. Use a controlled motion to avoid swinging the weights and maintain proper form.\r\n2. Keep your head and neck in a neutral position, looking straight ahead.\r\n3. Avoid locking your elbows at the top of the movement to reduce joint strain.', '{"image_male_start":"images/Shoulders/Dumbbell Standing Alternate Vertical Front Raises.jpg","image_male_end":"images/Shoulders/Dumbbell Standing Alternate Vertical Front Raises1.jpg","video_url":"videos/Shoulders/Dumbbell Standing Alternate Vertical Front Raises.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d32f1720-0e25-4bd2-85f5-0fa2f1c3adc2'::uuid, 'Dumbbell Standing Around World', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your arms hanging by your sides and palms facing forward.\r\n2. Slowly raise both dumbbells outward to the sides, keeping your arms straight, until they reach shoulder height.\r\n3. Continue lifting the dumbbells in a circular motion above your head until they meet at the top with your arms fully extended.\r\n4. Reverse the motion, lowering the dumbbells back down in the same circular path until they are by your sides again. Repeat for the desired number of repetitions.', E'1. Exhale as you lift the dumbbells and inhale as you lower them.\r\n2. Use a controlled motion to prevent using momentum to lift the weights.\r\n3. Maintain a slight bend in your elbows to reduce stress on your joints.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('765e0112-8a6f-4da6-a6fa-926edd3929f7'::uuid, 'Dumbbell Standing Behind Back Shoulders Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand. Your hands should be at a level behind your neck with your palms facing forward and elbows bent.\r\n2. Press the dumbbells upward overhead by extending your arms fully.\r\n3. Squeeze your shoulders at the top of the movement, ensuring your arms are fully extended and in line with your shoulders.\r\n4. Lower the dumbbells back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you press the dumbbells up and inhale as you lower them.\r\n2. Use a controlled motion to avoid using momentum to lift the weights.\r\n3. Keep your head and neck in a neutral position, looking straight ahead.', '{"image_male_start":"images/Shoulders/Dumbbell Standing Behind Back Shoulders Press.jpg","image_male_end":"images/Shoulders/Dumbbell Standing Behind Back Shoulders Press1.jpg","video_url":"videos/Shoulders/Dumbbell Standing Behind Back Shoulders Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c4c12ab0-4537-4fa2-843b-bde87b885e0f'::uuid, 'Dumbbell Standing Both Arms Kickback', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand. Bend your knees slightly and hinge forward at the hips, keeping your back straight and your torso almost parallel to the floor.\r\n2. Begin with your arms bent at 90 degrees, elbows close to your sides, and dumbbells hanging down.\r\n3. Extend both arms straight back by straightening your elbows, keeping your upper arms stationary and close to your body. Focus on squeezing your triceps at the top of the movement.\r\n4. Slowly bend your elbows to return the dumbbells to the starting position. Repeat for the desired number of repetitions.', E'1. Keep your back flat and avoid rounding your shoulders.\r\n2. Keep your head in a neutral position, looking slightly forward.\r\n3. Exhale as you extend your arms back and inhale as you return to the starting position.', '{"image_male_start":"images/Triceps/Dumbbell Standing Both Arms Kickback.jpeg","video_url":"videos/Triceps/Dumbbell Standing Both Arms Kickback.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5b24fa38-df30-4a19-8b96-c5e728062975'::uuid, 'Dumbbell standing calf raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand upright with your feet hip-width apart, holding a dumbbell in each hand at your sides. Keep your posture straight and your core engaged.\r\n2. Slowly raise your heels off the floor by pushing through your forefeet, lifting your body upward as high as possible.\r\n3. Hold the top position for a brief moment, feeling the contraction in your calf muscles.\r\n4. Lower your heels back down to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep your movements slow and controlled to maximize muscle engagement.\r\n2. Avoid bouncing at the top or bottom of the movement.\r\n3. Maintain a straight posture throughout the exercise.', '{"image_male_start":"images/Legs/dumbbell standing calf raise.jpg","image_male_end":"images/Legs/dumbbell standing calf raise1.jpg","video_url":"videos/Legs/dumbbell standing calf raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a7303ec0-2ac1-46a1-a5ba-7ab5c91d46e1'::uuid, 'Dumbbell Standing Calf Raise on Step', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand on a step platform with your heels hanging off the edge, holding a dumbbell in each hand at your sides. Position your feet hip-width apart.\r\n2. Slowly raise your heels as high as possible by pushing through your forefeet, lifting your body upward.\r\n3. Hold the top position for a brief moment, feeling the contraction in your calf muscles.\r\n4. Lower your heels below the edge of the step, feeling a stretch in your calves. Repeat for the desired number of repetitions.', E'1. Ensure the step or platform is stable and secure before starting the exercise.\r\n2. Keep your movements slow and controlled to maximize muscle engagement.\r\n3. Avoid bouncing at the top or bottom of the movement.', '{"image_male_start":"images/Legs/Dumbbell Standing Calf Raise on Step.jpg","image_male_end":"images/Legs/Dumbbell Standing Calf Raise on Step1.jpg","video_url":"videos/Legs/Dumbbell Standing Calf Raise on Step.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5ecfc583-0d0a-4dd4-bd6c-93ffe4bd072c'::uuid, 'Dumbbell Standing Concentration Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in your right hand. Slightly bend your knees and lean your torso forward, placing your left hand on your left knee for support. Allow your right arm to hang straight down towards the floor.\r\n2. Curl the dumbbell towards your opposite shoulder by bending your elbow, keeping your upper arm stationary.\r\n3. Squeeze your biceps at the peak of the movement, ensuring the dumbbell reaches close to your shoulder.\r\n4. Lower the dumbbell back to the starting position with control. Repeat for the desired repetitions, then switch to the other arm.', E'1. Keep your upper arm stationary throughout the exercise to isolate the biceps.\r\n2. Perform the movement slowly and with control to maximize muscle engagement.\r\n3. Avoid using momentum to lift the dumbbell.', '{"image_male_start":"images/Biceps/Dumbbell Standing Concentration Curl.jpeg","video_url":"videos/Biceps/Dumbbell Standing Concentration Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7e05825b-11d8-462d-8a5b-2234865ec7f8'::uuid, 'Dumbbell Standing Curl Arnold Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand, positioned just in front of your shoulders. Your elbows should be facing down, and your palms facing your shoulders.\r\n2. Press the dumbbells overhead while rotating your wrists so your palms face forward, fully extending your arms at the top of the movement.\r\n3. Reverse the movement by lowering the dumbbells back to shoulder level, rotating your wrists back to the starting position.\r\n4. Repeat the press and rotation for the desired number of repetitions.', E'1. Perform the movement slowly and with control, focusing on the rotation of your wrists.\r\n2. Avoid using momentum to lift the dumbbells; focus on muscle engagement.\r\n3. Maintain a slight bend in your knees for better balance.', '{"image_male_start":"images/Shoulders/Dumbbell Standing Curl Arnold Press.jpg","image_male_end":"images/Shoulders/Dumbbell Standing Curl Arnold Press1.jpg","video_url":"videos/Shoulders/Dumbbell Standing Curl Arnold Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6fbecdbb-5443-4c79-bdc9-4f5572f46c68'::uuid, 'Dumbbell Standing Front Raise Above Head', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip (palms facing down). Let your arms hang straight down in front of your hips.\r\n2. Raise both dumbbells simultaneously in front of you, keeping your arms straight and lifting until the dumbbells are above your head.\r\n3. Hold the position briefly at the top, ensuring your arms are fully extended above your head.\r\n4. Lower the dumbbells back to the starting position with control, keeping your movements slow and steady. Repeat for the desired number of repetitions.', E'1. Exhale as you raise the dumbbells and inhale as you lower them.\r\n2. Avoid using momentum; focus on controlled movements.\r\n3. Keep a slight bend in your elbows to reduce strain on your joints.', '{"image_male_start":"images/Shoulders/Dumbbell Standing Front Raise Above Head.jpg","image_male_end":"images/Shoulders/Dumbbell Standing Front Raise Above Head1.jpg","video_url":"videos/Shoulders/Dumbbell Standing Front Raise Above Head.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('dbed752d-7f69-4bab-97ea-8bcbc69c31bb'::uuid, 'Dumbbell Standing Hammer Drag Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with a neutral grip (palms facing each other). Let the dumbbells hang by your sides.\r\n2. Drag the dumbbells upward keeping the dumbbells close to your torso by pulling your elbows backward while lifting.\r\n3. Continue dragging the dumbbells until they reach the level of your lower chest, squeezing your biceps at the top of the movement.\r\n4. Lower the dumbbells back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Focus on dragging the dumbbells upward, not curling them in a traditional manner.\r\n2. Maintain a neutral grip and keep the dumbbells close to your body.\r\n3. Breathe out as you lift the dumbbells and inhale as you lower them.', '{"image_male_start":"images/Biceps/Dumbbell Standing Hammer Drag Curl.jpeg","video_url":"videos/Biceps/Dumbbell Standing Hammer Drag Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('25250fc8-7cb0-45bf-ac9f-5b6fe9cf9ee6'::uuid, 'Dumbbell Standing One Arm Concentration Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in your right hand. Bend your knees and hinge to your hips to lean forward and place your right elbow on the inside of your right thigh and your left hand on your left knee for support.\r\n2. Curl the dumbbell upward towards your shoulder by bending your elbow, focusing on engaging your biceps.\r\n3. Squeeze your biceps at the top of the movement, ensuring the dumbbell reaches shoulder height.\r\n4. Lower the dumbbell back to the starting position, fully extending your arm. Repeat for the desired number of repetitions, then switch to the left arm.', E'1. Focus on isolating the biceps and minimizing movement in your shoulder.\r\n2. Maintain a slight bend in your elbow to avoid locking out the joint.\r\n3. Breathe out as you curl the dumbbell and inhale as you lower it.', '{"image_male_start":"images/Biceps/Dumbbell Standing One Arm Concentration Curl.jpeg","video_url":"videos/Biceps/Dumbbell Standing One Arm Concentration Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('713deee8-4c22-4fcb-8c9d-2095964e3103'::uuid, 'Dumbbell Standing One Arm Curl Over Incline Bench', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand behind an incline bench set at a 45-degree angle, holding a dumbbell in your right hand using an underhand grip (palm facing up). Place your right arm over the bench so your upper arm rests against the incline pad.\r\n2. Keep your upper arm stationary and your elbow slightly bent. Curl the dumbbell upward towards your shoulder by bending your elbow, focusing on engaging your biceps.\r\n3. Squeeze your biceps at the top of the movement, ensuring the dumbbell reaches shoulder height.\r\n4. Lower the dumbbell back to the starting position, fully extending your arm. Repeat for the desired number of repetitions, then switch to the left arm.', E'1. Focus on isolating the biceps, minimizing movement in your shoulder and upper arm.\r\n2. Maintain a slight bend in your elbow to avoid locking out the joint.\r\n3. Breathe out as you curl the dumbbell and inhale as you lower it.', '{"image_male_start":"images/Biceps/Dumbbell Standing One Arm Curl Over Incline Bench.jpeg","video_url":"videos/Biceps/Dumbbell Standing One Arm Curl Over Incline Bench.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ac547df1-e9dd-4dda-84ad-351ab4716625'::uuid, 'Dumbbell Standing One Arm Extension', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in your right hand and place your left hand to your hip for support. Raise your right arm overhead, extending it fully with your palm facing forward.\r\n2. Keep your upper arm stationary and your elbow close to your head. Lower the dumbbell behind your head by bending your elbow.\r\n3. Extend your arm back to the starting position by straightening your elbow. Ensure your upper arm remains stationary throughout the movement.\r\n4. Repeat for the desired number of repetitions, then switch to the left arm.', E'1. Focus on isolating the triceps, minimizing movement in your shoulder and upper arm.\r\n2. Maintain a slight bend in your elbow to avoid locking out the joint.\r\n3. Breathe out as you extend the dumbbell and inhale as you lower it.', '{"image_male_start":"images/Triceps/Dumbbell Standing One Arm Extension.jpeg","video_url":"videos/Triceps/Dumbbell Standing One Arm Extension.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0eeb2484-4183-4a52-a9a8-99488bc2add4'::uuid, 'Dumbbell Standing Overhead Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height to your sides, with your palms facing forward and elbows bent.\r\n2. Press the dumbbells overhead by extending your arms fully without locking your elbows.\r\n3. Lower the dumbbells back to shoulder height in a controlled motion.\r\n4. Repeat for the desired number of repetitions.', E'1. Avoid locking your elbows at the top of the movement.\r\n2. Breathe out as you press the dumbbells up and inhale as you lower them.\r\n3. Ensure your wrists remain straight and aligned with your forearms.', '{"image_male_start":"images/Shoulders/Dumbbell Standing Overhead Press.jpg","image_male_end":"images/Shoulders/Dumbbell Standing Overhead Press1.jpg","video_url":"videos/Shoulders/Dumbbell Standing Overhead Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f4ca07e4-e222-4d31-b02b-2dd7df0ff515'::uuid, 'Dumbbell Standing Palms In Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand at head height with your palms facing each other and elbows bent.\r\n2. Press the dumbbells overhead by extending your arms fully without locking your elbows.\r\n3. Lower the dumbbells back to head height in a controlled motion, keeping your core engaged and back straight.\r\n4. Repeat for the desired number of repetitions.', E'1. Avoid locking your elbows at the top of the movement.\r\n2. Breathe out as you press the dumbbells up and inhale as you lower them.\r\n3. Use a controlled motion to avoid shoulder injury.', '{"image_male_start":"images/Shoulders/Dumbbell Standing Palms In Press.jpg","image_male_end":"images/Shoulders/Dumbbell Standing Palms In Press1.jpg","video_url":"videos/Shoulders/Dumbbell Standing Palms In Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b2cd0e9f-3643-475b-a838-ff6fc00a2ef3'::uuid, 'Dumbbell Standing Preacher Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in one hand. Position yourself behind a preacher bench and place the back of your upper arm on the bench arm pad.\r\n2. Start with your arm fully extended and the dumbbell in a supinated grip (palm facing up).\r\n3. Curl the dumbbell upward towards your shoulder by bending your elbow, keeping the back of your arm pressed against the bench.\r\n4. Lower the dumbbell back to the starting position, fully extending your arm. Repeat for the desired number of repetitions, then switch to the other arm.', E'1. Keep your upper arm firmly pressed against the bench to isolate the biceps.\r\n2. Avoid using momentum to lift the dumbbell; focus on controlled movements.\r\n3. Exhale as you curl the dumbbell up and inhale as you lower it.', '{"image_male_start":"images/Biceps/Dumbbell Standing Preacher Curl.jpeg","video_url":"videos/Biceps/Dumbbell Standing Preacher Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f5c01b34-bb8d-4a1a-af4c-5bc0358957e2'::uuid, 'Dumbbell Standing Reverse Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with a neutral grip (palms facing each other). Let your arms hang straight by your sides.\r\n2. Keep your upper arms stationary and curl the dumbbells towards your shoulders by bending your elbows while rotating your wrists so your palms face down.\r\n3. Squeeze your biceps muscles at the peak of the movement, ensuring the dumbbells reach shoulder height.\r\n4. Lower the dumbbells back to the starting position with control. Repeat for the desired repetitions.', E'1. Keep your upper arms close to your body and stationary throughout the exercise.\r\n2. Avoid swinging the dumbbells; focus on controlled movements.\r\n3. Exhale as you curl the dumbbells up and inhale as you lower them.', '{"image_male_start":"images/Biceps/Dumbbell Standing Reverse Curl.jpeg","video_url":"videos/Biceps/Dumbbell Standing Reverse Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1b571569-c68e-4ec8-920f-a183b76de17a'::uuid, 'Dumbbell Standing Simultaneous Biceps Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1.  Stand with your feet shoulder-width apart, holding a dumbbell in each hand with a neutral grip (palms facing each other). Let your arms hang straight by your sides.\r\n2. Keep your upper arms stationary and curl the dumbbells towards your shoulders by bending your elbows while rotating your wrists so your palms face up.\r\n3. Squeeze your biceps muscles at the peak of the movement, ensuring the dumbbells reach shoulder height.\r\n4. Lower the dumbbells back to the starting position with control. Repeat for the desired repetition.', E'1. Keep your upper arms close to your body and stationary throughout the exercise.\r\n2. Avoid swinging the dumbbells; focus on controlled movements.\r\n3. Exhale as you curl the dumbbells up and inhale as you lower them.', '{"image_male_start":"images/Biceps/Dumbbell Standing Simultaneous Biceps Curl.jpeg","video_url":"videos/Biceps/Dumbbell Standing Simultaneous Biceps Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('60f854f8-29fc-4a88-b185-052206a55fcf'::uuid, 'Dumbbell Standing Single Arm Cross Raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1.Stand with your feet shoulder-width apart, holding a dumbbell in your right hand with a neutral grip. Extend your right arm straight down at your side. Your left hand should be on your hip for support.\r\n2. Raise the dumbbell diagonally across your body towards your left shoulder, keeping your arm straight and maintaining a slight bend in your elbow.\r\n3. Hold the position briefly at the top, ensuring the dumbbell reaches shoulder height.\r\n4. Lower the dumbbell back to the starting position, keeping your movements slow and steady. Repeat for the desired number of repetitions, then switch to the left arm.', E'1. Exhale as you raise the dumbbell and inhale as you lower it.\r\n2. Avoid using momentum; focus on controlled movements.\r\n3. Keep a slight bend in your elbow to reduce strain on your joints.', '{"image_male_start":"images/Chest/Dumbbell Standing Single Arm Cross Raise.jpg","image_male_end":"images/Chest/Dumbbell Standing Single Arm Cross Raise1.jpg","video_url":"videos/Chest/Dumbbell Standing Single Arm Cross Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('67ac8cdf-9be1-4b48-83d9-fab8ab834c1e'::uuid, 'Dumbbell Standing Single Leg Calf Raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your left foot on the floor, keeping your right foot a few inches off the floor, holding a dumbbell in both hands with your arms hanging by your sides.\r\n2. Press through your left heel to raise your heel off the floor as high as possible by extending your ankle.\r\n3. Hold the position briefly at the top, squeezing your calf muscle.\r\n4. Lower your heel back down to the starting position with control. Repeat for the desired number of repetitions, then switch to the right leg.', E'1. Use a full range of motion, lifting your heel as high as possible.\r\n2. Avoid bouncing; focus on a slow and controlled movement.\r\n3. Maintain a steady pace and avoid using momentum.', '{"image_male_start":"images/Legs/Dumbbell Standing Single Leg Calf Raise.jpg","image_male_end":"images/Legs/Dumbbell Standing Single Leg Calf Raise1.jpg","video_url":"videos/Legs/Dumbbell Standing Single Leg Calf Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4d87e9b5-dc54-4e99-b36e-46213e4daf42'::uuid, 'Dumbbell Standing Triceps Extension', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell with both hands behind your head. Your elbows should be bent, and your upper arms should be close to your ears.\r\n2. Extend your arms fully by pressing the dumbbell overhead until your arms are straight. Keep your elbows close to your head.\r\n3. Lower the dumbbell back down behind your head by bending your elbows, returning to the starting position.\r\n4. Repeat the extension and flexion of your arms for the desired number of repetitions.', E'1. Avoid flaring your elbows out; keep them close to your ears.\r\n2. Use a controlled motion, avoiding swinging the dumbbell.\r\n3. Exhale as you extend your arms and inhale as you lower the dumbbell.', '{"image_male_start":"images/Triceps/Dumbbell Standing Triceps Extension.jpeg","video_url":"videos/Triceps/Dumbbell Standing Triceps Extension.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a61060be-dfee-4794-91ff-0ba2a980d9d3'::uuid, 'Dumbbell Standing Wide Simultaneous Biceps Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing slightly outwards and your arms extended down by your sides. Position your arms slightly wider than your shoulders.\r\n2. Curl both dumbbells diagonally upward simultaneously by bending your elbows, keeping your upper arms stationary.\r\n3. Squeeze your biceps at the top of the movement when the dumbbells reach shoulder height.\r\n4. Lower the dumbbells back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Keep your upper arms stationary; only your forearms should move.\r\n2. Avoid swinging the dumbbells; use a controlled motion.\r\n3. Exhale as you curl the dumbbells up and inhale as you lower them.', '{"image_male_start":"images/Biceps/Dumbbell Standing Wide Simultaneous Biceps Curl.jpeg","video_url":"videos/Biceps/Dumbbell Standing Wide Simultaneous Biceps Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a1be9386-26f2-4820-a37f-c025860da5b9'::uuid, 'Dumbbell Standing Wrist Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell with both hands with an underhand grip (palms facing forward). Let your arms hang straight down in front of your hips.\r\n2. Keeping your upper arms stationary, curl your wrists upward as far as possible, bringing the dumbbell up towards your forearms.\r\n3. Squeeze your forearm muscles at the top of the movement.\r\n4. Lower the dumbbell back to the starting position with control, fully extending your wrists. Repeat for the desired number of repetitions.', E'1. Keep your upper arms and elbows close to your body; only your wrists should move.\r\n2. Avoid using momentum; perform the movement in a controlled manner.\r\n3. Use a weight that allows you to perform the exercise with proper form.', '{"image_male_start":"images/Forearms/Dumbbell Standing Wrist Curl.jpeg","video_url":"videos/Forearms/Dumbbell Standing Wrist Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('987553ea-2b05-471b-b150-7cc947fb2365'::uuid, 'Dumbbell Starfish Crunch Alternating', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by lying flat on your back with your arms and legs extended out in a starfish position, holding a dumbbell in each hand.\r\n2. Simultaneously lift your right arm and left leg towards each other, crunching your torso and bringing the dumbbell towards your left foot.\r\n3. Lower back down to the starting position with control.\r\n4. Repeat the movement with your left arm and right leg, alternating sides for the desired number of repetitions.', E'1. Perform the exercise in a controlled manner to maximize muscle engagement.\r\n2. Avoid using momentum to lift your limbs; focus on the contraction of your core muscles.\r\n3. Exhale as you lift your arm and leg, and inhale as you lower them back down.\r\n', '{"image_male_start":"images/Abdominals/Dumbbell Starfish Crunch Alternating.jpeg","video_url":"videos/Abdominals/Dumbbell Starfish Crunch Alternating.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('24049273-3f80-41b8-96b2-76dc1d32274c'::uuid, 'Dumbbell Static Lunge', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by standing with your feet shoulder-width apart, holding a dumbbell in each hand at your sides. Step your right foot forward and your left foot back.\r\n2. Lower your body by bending both knees until your right thigh is parallel to the floor and your left knee nearly touches the floor.\r\n3. Push through your right heel to return to the starting position, keeping your feet in the same place.\r\n4. Repeat the movement for the desired number of repetitions before switching to the other leg.', E'1. Maintain an upright posture throughout the exercise.\r\n2. Keep your front knee aligned with your ankle to avoid strain.\r\n3. Avoid letting your front knee extend past your toes.', '{"image_male_start":"images/Legs/Dumbbell Static Lunge.jpg","image_male_end":"images/Legs/Dumbbell Static Lunge1.jpg","video_url":"videos/Legs/Dumbbell Static Lunge.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('701e2377-fb3a-461c-801d-9e30ff527873'::uuid, 'Dumbbell Step up on Bench', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by standing in front of a bench with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.\r\n2. Place your right foot on the bench, ensuring your entire foot is firmly planted. Push through your right heel to lift your body onto the bench, bringing your left foot up to meet the right.\r\n3. Step down with your left foot first, followed by your right foot, returning to the starting position.\r\n4. Repeat the movement for the desired number of repetitions, then switch to the other leg.', E'1. Avoid pushing off with your back leg; focus on using your front leg to lift your body.\r\n2. Ensure your entire foot is on the bench to avoid slipping.\r\n3. Control your descent to prevent injury.', '{"image_male_start":"images/Legs/Dumbbell Step up on Bench.jpg","image_male_end":"images/Legs/Dumbbell Step up on Bench1.jpg","video_url":"videos/Legs/Dumbbell Step up on Bench.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('eb05d52d-eeb2-4456-ad6f-dde40a374fbc'::uuid, 'Dumbbell Step-up with Knee Raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by standing in front of a bench with your feet shoulder-width apart, holding a dumbbell in each hand at your sides.\r\n2. Place your right foot on the bench, ensuring your entire foot is firmly planted. Push through your right heel to lift your body onto the bench, simultaneously lifting your left knee up towards your chest.\r\n3. Lower your left leg back down to the floor, followed by your right leg, returning to the starting position.\r\n4. Repeat the movement for the desired number of repetitions, then switch to the other leg.', E'1. Focus on using your front leg to lift your body, not pushing off with your back leg.\r\n2. Ensure your entire foot is on the bench to avoid slipping.\r\n3. Control your ascend and descent to prevent injury.', '{"image_male_start":"images/Legs/Dumbbell Step-up with Knee Raise.jpg","image_male_end":"images/Legs/Dumbbell Step-up with Knee Raise1.jpg","video_url":"videos/Legs/Dumbbell Step-up with Knee Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e3aa3346-ab44-456a-b9b5-930daa3cb77b'::uuid, 'Dumbbell Stiff Leg Deadlift', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet hip-width apart, holding a dumbbell in each hand in front of your thighs with your palms facing your body.\r\n2. Keeping a slight bend in your knees, hinge at your hips and lower the dumbbells towards the floor, maintaining a straight back and keeping the dumbbells close to your legs.\r\n3. Lower the dumbbells until you feel a stretch in your hamstrings, ensuring your back remains straight.\r\n4. Return to the starting position, extending your hips and standing tall. Repeat for the desired number of repetitions.', E'1. Keep your back straight and avoid rounding your shoulders.\r\n2. Engage your core throughout the exercise for stability.\r\n3. Focus on hinging at the hips rather than bending at the waist.', '{"image_male_start":"images/Legs/Dumbbell Stiff Leg Deadlift.jpg","image_male_end":"images/Legs/Dumbbell Stiff Leg Deadlift1.jpg","video_url":"videos/Legs/Dumbbell Stiff Leg Deadlift.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1502214a-3881-4f70-91fc-621150d1ede4'::uuid, 'Dumbbell Straight Arm Crunch', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by lying flat on your back with your knees bent and feet flat on the floor, holding a dumbbell with both hands extended straight above your chest.\r\n2. Engage your core and lift your upper back off the floor, raising the dumbbell towards the ceiling as high as possible, while keeping your arms straight.\r\n3. Lower your upper back, back to the floor with control, maintaining the arms extended above your chest. Repeat for the desired number of repetitions.', E'1. Keep your arms straight and avoid bending your elbows during the movement.\r\n2. Focus on reaching the dumbbell straight up rather than forward.\r\n3. Exhale as you crunch up and inhale as you lower down.', '{"image_male_start":"images/Abdominals/Dumbbell Straight Arm Crunch.jpeg","video_url":"videos/Abdominals/Dumbbell Straight Arm Crunch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8f4bf8f2-c1fc-4311-98e5-23e4ba64d325'::uuid, 'Dumbbell Straight Arm Twisting Sit-up', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by lying flat on your back with your knees bent and feet flat on the floor, holding a dumbbell with both hands extended straight above your chest.\r\n2. Bend your core and lift your upper body off the floor, raising the dumbbell towards the ceiling as high as possible. As you crunch, twist your torso to the right, bringing the dumbbell towards your right side.\r\n3. Lower your upper body back to the floor with control, maintaining your arms extended above your chest. Repeat the movement, this time twisting to the left. Continue alternating sides for the desired number of repetitions.', E'1. Keep your arms straight and avoid bending your elbows during the movement.\r\n2. Use a weight that allows for proper form and control.\r\n3. Exhale as you twist up and inhale as you lower down.', '{"image_male_start":"images/Abdominals/Dumbbell Straight Arm Twisting Sit-up.jpeg","video_url":"videos/Abdominals/Dumbbell Straight Arm Twisting Sit-up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f15f8af3-8297-4d32-ae16-e79a050af6d0'::uuid, 'Dumbbell Straight Leg Deadlift', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by standing with your feet hip-width apart, holding a dumbbell in each hand with your palms facing your thighs. Keep your legs straight but not locked.\r\n2. Keep your back straight and hinge at your hips, lowering the dumbbells towards the floor. Push your hips back while keeping the dumbbells close to your legs.\r\n3. Lower the dumbbells until you feel a stretch in your hamstrings, ensuring your back remains straight.\r\n4. Return to the starting position by driving your hips forward and standing up straight, squeezing your glutes at the top. Repeat for the desired number of repetitions.', E'1. Engage your core throughout the movement to support your spine.\r\n2. Keep the dumbbells close to your legs as you lower and lift them.\r\n3. Focus on hinging at the hips rather than bending at the waist.', '{"image_male_start":"images/Legs/Dumbbell Straight Leg Deadlift.jpg","image_male_end":"images/Legs/Dumbbell Straight Leg Deadlift1.jpg","video_url":"videos/Legs/Dumbbell Straight Leg Deadlift.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9851d38a-b95d-4a5f-8745-911e38b7cfb5'::uuid, 'Dumbbell Straight Leg Russian Twist', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on the floor with your legs extended straight just off the floor, and hold a dumbbell with both hands close to your chest. Lean back slightly to engage your core, keeping your back straight.\r\n2. Rotate your torso to the right, moving the dumbbell towards the floor beside your right hip while keeping your legs extended just off the floor.\r\n3. Rotate your torso back to the center, bringing the dumbbell back to center.\r\n4. Continue rotating your torso to the left, moving the dumbbell towards the floor beside your left hip. Return to the center. Repeat for the desired number of repetitions, alternating sides.', E'1. Avoid leaning back too far to prevent strain on your lower back.\r\n2. Exhale as you twist to each side and inhale as you return to the center.\r\n3. Keep your legs extended and together to maintain stability.', '{"image_male_start":"images/Abdominals/Dumbbell Straight Leg Russian Twist.jpeg","video_url":"videos/Abdominals/Dumbbell Straight Leg Russian Twist.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('91063f24-1fda-4ef7-908a-94d0162152dd'::uuid, 'Dumbbell Suitcase Carry', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet hip-width apart, holding a dumbbell in one hand at your side, allowing your arm to hang. Ensure your shoulders are level and your posture is upright.\r\n2. Begin walking forward in a straight line, keeping the dumbbell close to your body. Walk for the desired distance or time.\r\n3. Maintain a neutral spine and avoid leaning to one side to balance the weight. Focus on keeping your torso stable and your strides even.\r\n4. After completing the desired distance or time, switch the dumbbell to the other hand and repeat the exercise, ensuring equal work on both sides.', E'1. Maintain a steady and controlled pace while walking.\r\n2. Avoid shrugging your shoulder or letting the dumbbell swing.\r\n3. Use a weight that challenges your grip and core stability without compromising your form.', '{"image_male_start":"images/Legs/Dumbbell Suitcase Carry.jpg","image_male_end":"images/Legs/Dumbbell Suitcase Carry1.jpg","video_url":"videos/Legs/Dumbbell Suitcase Carry.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('90e34af6-b22f-458d-8de9-191737d7596c'::uuid, 'Dumbbell Sumo Squat Off Benches', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand between two benches with a wide stance, toes pointed slightly outward. Hold a dumbbell with both hands, letting it hang between your legs.\r\n2. Lower yourself into a wide squat by bending your knees and pushing your hips back. Lower until your thighs are parallel to the floor.\r\n3. Push through your heels to stand back up, squeezing your glutes at the top of the movement.\r\n4. Repeat the squat for the desired number of repetitions.', E'1. Ensure your knees track over your toes and do not collapse inward during the squat.\r\n2. Keep your back straight and chest up to avoid leaning forward.\r\n3. Use a weight that challenges your strength but allows you to maintain proper form.', '{"image_male_start":"images/Legs/Dumbbell Sumo Squat Off Benches.jpg","image_male_end":"images/Legs/Dumbbell Sumo Squat Off Benches1.jpg","video_url":"videos/Legs/Dumbbell Sumo Squat Off Benches.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('be80a4e6-c04e-41fb-b2de-3b8f8f1032da'::uuid, 'Dumbbell Supported Sissy Squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Position yourself on a sissy squat machine with your feet shoulder-width apart and your lower legs securely supported by the machine''s pads. Hold a dumbbell close to your chest with both hands.\r\n2. Slowly lower your body by bending your knees, keeping your back straight.\r\n3. Lower until your thighs are almost parallel to the floor.\r\n4. Push through your thighs to rise back to the starting position. Repeat for the desired number of repetitions.', E'1. Ensure your knees track over your toes and do not collapse inward during the squat.\r\n2. Perform the movement slowly and with control to maximize muscle engagement.\r\n3. Avoid locking your knees at the top of the movement; keep a slight bend.', '{"image_male_start":"images/Legs/Dumbbell Supported Sissy Squat.jpg","image_male_end":"images/Legs/Dumbbell Supported Sissy Squat1.jpg","video_url":"videos/Legs/Dumbbell Supported Sissy Squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('fb12b95a-c4b2-438a-b35e-577d3759441b'::uuid, 'Dumbbell Svend Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell with both hands. Position the dumbbell vertically in front of your chest with your palms facing each other and your fingers interlocked.\r\n2. Engage your chest and press the dumbbells together with your palms, activating your chest muscles.\r\n3. Extend your arms straight out in front of you at shoulder height, keeping the dumbbell pressed together in your palms.\r\n4. Bring the dumbbell back to your chest. Repeat for the desired number of repetitions.', E'1. Maintain constant pressure on the dumbbell to activate your chest muscles effectively.\r\n2. Avoid locking your elbows at the end of the extension; keep a slight bend.\r\n3. Perform the movement slowly and with control to maximize muscle engagement.', '{"image_male_start":"images/Chest/Dumbbell Svend Press.jpg","image_male_end":"images/Chest/Dumbbell Svend Press1.jpg","video_url":"videos/Chest/Dumbbell Svend Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a6d837e1-093b-4396-9104-92fae0e8ccd3'::uuid, 'Dumbbell Tate Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie on a flat bench with a dumbbell in each hand. Position the dumbbells above your chest, with your arms fully extended and your palms facing forward.\r\n2. Bend your elbows and lower the dumbbells inward and towards your chest, keeping the dumbbells facing forward.\r\n3. Bring the dumbbells together just before touching your chest, elbows pointing out to the sides.\r\n4. Extend your arms back to the starting position, extending the dumbbells upward. Repeat for the desired number of repetitions.', E'1. Keep your wrists straight and aligned with your forearms.\r\n2. Focus on controlled movements and avoid using momentum.\r\n3. Choose a weight that allows for proper form and full range of motion.', '{"image_male_start":"images/Chest/Dumbbell Tate Press.jpg","image_male_end":"images/Chest/Dumbbell Tate Press1.jpg","video_url":"videos/Triceps/Dumbbell Tate Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4fa5ebae-7363-4311-8cd1-3748c3f3cb1d'::uuid, 'dumbbell triceps kick back single arm', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by standing with your feet shoulder-width apart, holding a dumbbell in your right hand. Bend your knees slightly and hinge forward at your hips, keeping your back straight. Place your left hand on your left knee for support.\r\n2. Lift your right elbow backward to bring the dumbbell close to your torso, with your upper arm parallel to the floor and your forearm perpendicular to the floor.\r\n3. Extend your right arm fully behind you by straightening your elbow, keeping your upper arm stationary. Squeeze your triceps at the top of the movement.\r\n4. Slowly return the dumbbell to the starting position by bending your elbow. Repeat for the desired number of repetitions, then switch to the left arm and repeat.\r\n', E'1. Keep your upper arm close to your body and stationary throughout the exercise.\r\n2. Focus on a slow and controlled movement to maximize triceps engagement.\r\n3. Avoid swinging the weight; use only your triceps to perform the movement.', '{"image_male_start":"images/Triceps/Dumbbell triceps kick back single arm.jpeg","video_url":"videos/Triceps/Dumbbell triceps kick back single arm.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('68b0e16c-b1b3-497a-b8be-15db6f77fb74'::uuid, 'Dumbbell upright shoulder external rotation', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by standing with your feet shoulder-width apart, holding a dumbbell in your right hand. Bend your right elbow to 90 degrees, keeping your elbow at shoulder level, extended to your side and lower your forearm vertical to the floor.\r\n2. Keep your elbow fixed at your side and slowly rotate your forearm upward, raising the dumbbell until your forearm is up vertical to the floor. \r\n3. Slowly return the dumbbell to the starting position by rotating your forearm down. Repeat for the desired number of repetitions, then switch to the left arm and repeat.', E'1. Use a lightweight dumbbell to avoid strain and maintain proper form.\r\n2. Focus on a slow and controlled movement to engage the rotator cuff muscles effectively.\r\n3. Avoid using momentum; ensure the movement is controlled by your shoulder muscles.', '{"image_male_start":"images/Shoulders/Dumbbell Upright Shoulder External Rotation.jpg","image_male_end":"images/Shoulders/Dumbbell Upright Shoulder External Rotation1.jpg","video_url":"videos/Shoulders/Dumbbell Upright Shoulder External Rotation.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d614520b-9d77-40e2-83d6-313cb80ce53d'::uuid, 'Dumbbell V-up', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by lying flat on your back with your legs extended straight and holding a dumbbell with both hands extended on the floor, arms fully extended.\r\n2. Simultaneously lift your legs, upper body and dumbbell off the floor, bringing your legs and arms together to form a V-shape.\r\n3. Reach the dumbbell towards your feet, keeping your arms and legs as straight as possible.\r\n4. Slowly lower your legs, upper body and dumbbell back to the starting position. Repeat for the desired number of repetitions.', E'1. Maintain straight arms and legs to maximize the effectiveness of the exercise.\r\n2. Exhale as you lift into the V-up position and inhale as you lower back down.\r\n3. Avoid jerking or using momentum; perform the movement in a controlled manner.', '{"image_male_start":"images/Abdominals/Dumbbell V-up.jpeg","video_url":"videos/Abdominals/Dumbbell V-up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5d792f69-0668-4e41-8b01-b848c9e1c6e9'::uuid, 'Dumbbell w press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand. Bend your elbows at 90 degrees to bring the dumbbells up to shoulder height, with palms facing forward. Elbows should be pointing out and lower than shoulder level.\r\n2. Raise the dumbbells upward, in an arc motion, until both dumbbells are above your head.\r\n3. Slowly lower the dumbbells back down to the starting position, keeping your elbows bent at 90 degrees. \r\n4. Repeat the exercise for the desired number of repetitions.\r\n', E'1. Ensure your movements are controlled and avoid using momentum.\r\n2. Exhale as you press the dumbbells upward and inhale as you lower them back down.\r\n3. Keep your wrists straight and aligned with your forearms throughout the exercise.', '{"image_male_start":"images/Shoulders/dumbbell w press.jpg","image_male_end":"images/Shoulders/dumbbell w press1.jpg","video_url":"videos/Shoulders/dumbbell w press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('bd28ab89-1956-45df-8e32-9d43665e1dfd'::uuid, 'Dumbbell Waiter Biceps Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell with both hands vertically and elbows close to your body.\r\n2. Curl the dumbbell upwards towards your chest by bending your elbows.\r\n3. Squeeze your biceps at the top of the movement, ensuring the dumbbell reaches shoulder height.\r\n4. Lower the dumbbell back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Focus on moving the weight with your biceps, avoiding momentum.\r\n2. Exhale as you curl the dumbbell upward and inhale as you lower it.\r\n3. Keep your elbows close to your body throughout the exercise.', '{"image_male_start":"images/Biceps/Dumbbell Waiter Biceps Curl.jpeg","video_url":"videos/Biceps/Dumbbell Waiter Biceps Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9276697f-1eac-4057-8c00-ce9453f8f24a'::uuid, 'Dumbbell Zottman Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an underhand grip (palms facing forward) and arms fully extended by your sides.\r\n2. Keep your upper arms stationary as you curl the dumbbells upwards towards your shoulders by bending your elbows.\r\n3. At the top of the movement, rotate your wrists to turn your palms downward (overhand grip), then lower the dumbbells back to the starting position with control.\r\n4. Rotate your wrists back to the underhand grip at the bottom, and repeat for the desired number of repetitions.', E'1. Focus on moving the weight with your biceps, avoiding momentum.\r\n2. Keep your elbows close to your body throughout the exercise.\r\n3. Ensure smooth and controlled wrist rotation at the top of the curl.', '{"image_male_start":"images/Biceps/Dumbbell Zottman Curl.jpeg","video_url":"videos/Biceps/Dumbbell Zottman Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('dd30baa9-e4f3-4f71-8a84-ae27908cd6a5'::uuid, 'Dumbbell Zottman Preacher Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a preacher bench, holding a dumbbell in each hand with an underhand grip (palms facing up). Position your upper arms on the preacher bench pad and fully extend your arms.\r\n2. Curl the dumbbells upwards towards your shoulders by bending your elbows.\r\n3. At the top of the movement, rotate your wrists to turn your palms downward (overhand grip), then lower the dumbbells back to the starting position with control.\r\n4. Rotate your wrists back to the underhand grip at the bottom, and repeat for the desired number of repetitions.', E'1. Keep your upper arms pressed against the pad to isolate the biceps.\r\n2. Focus on a full range of motion for maximum muscle activation.\r\n3. Perform the exercise slowly to increase time under tension.', '{"image_male_start":"images/Biceps/Dumbbell Zottman Preacher Curl.jpeg","video_url":"videos/Biceps/Dumbbell Zottman Preacher Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d16f007f-6d4f-488b-86e2-a0358d08a5d8'::uuid, 'Dumbbells around the world', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your arms extended down by your sides and palms facing forward.\r\n2. Slowly lift the dumbbells in a wide arc out to your sides, keeping your arms straight but not locked.\r\n3. Continue the movement until the dumbbells meet above your head, forming a full circle with your arms.\r\n4. Lower the dumbbells back down in the same wide arc to the starting position. Repeat the movement for the desired number of repetitions, ensuring a smooth and controlled motion throughout the exercise.', E'1. Maintain a slight bend in your elbows to protect your joints.\r\n2. Avoid arching your lower back; keep your core engaged to maintain proper posture.\r\n3. Ensure your wrists remain straight and aligned with your forearms throughout the exercise.\r\n', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b04b047f-0478-4dbb-8fe1-e044496b075d'::uuid, 'Dumbbells bent over row', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body. Bend your knees slightly and hinge forward at the hips. Let your arms hang straight down from your shoulders.\r\n2. Pull the dumbbells towards your hips, keeping your elbows close to your body and squeezing your shoulder blades together at the top of the movement.\r\n3. Hold the contraction for a moment, focusing on engaging your back muscles.\r\n4. Slowly lower the dumbbells back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep your back straight and avoid rounding your shoulders.\r\n2. Exhale as you pull the dumbbells up and inhale as you lower them.\r\n3. Focus on pulling with your back muscles rather than your arms.', '{"image_male_start":"images/Back/dumbbells bent over row.jpg","image_male_end":"images/Back/dumbbells bent over row1.jpg","video_url":"videos/Back/dumbbells bent over row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6e66f634-a38c-420b-a3d6-cbc4a783c2c6'::uuid, 'Dumbbells bent over row pronated grip', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your palms facing your body. Bend your knees slightly and hinge forward at the hips. Let your arms hang straight down from your shoulders.\r\n2. Pull the dumbbells towards your hips, keeping your elbows close to your body and squeezing your shoulder blades together at the top of the movement.\r\n3. Hold the contraction for a moment, focusing on engaging your back muscles.\r\n4. Slowly lower the dumbbells back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep your back straight and avoid rounding your shoulders.\r\n2. Exhale as you pull the dumbbells up and inhale as you lower them.\r\n3. Focus on pulling with your back muscles rather than your arms.', '{"image_male_start":"images/Back/dumbbells bent over row pronated grip.jpg","image_male_end":"images/Back/dumbbells bent over row pronated grip1.jpg","video_url":"videos/Back/dumbbells bent over row pronated grip.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('788e6c01-cfa1-4d70-8c87-d640511b358e'::uuid, 'Dumbbells plank to alternating row', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin in a high plank position with your hands gripping a dumbbell each on the floor, directly under your shoulders, and your body forming a straight line from head to heels. Your feet should be slightly wider than hip-width apart for stability.\r\n2. Keeping your core tight, lift the right dumbbell off the floor, rowing it towards your right hip while balancing on your left hand and feet.\r\n3. Lower the dumbbell back to the floor with control, returning to the high plank position.\r\n4. Repeat the rowing motion with your left hand, alternating sides for the desired number of repetitions.', E'1. Keep your hips level and avoid rotating your body as you row.\r\n2. Maintain a straight line from head to heels throughout the exercise.\r\n3. Use a weight that allows you to maintain proper form without compromising balance.', '{"video_url":"videos/Back/dumbbells plank to alternating row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e8c3838d-35a4-41b0-a02b-6d29aee88b5c'::uuid, 'dumbbells triceps kick back both arms', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by standing with your feet shoulder-width apart, holding a dumbbell in each hand. Bend your knees slightly and hinge forward at your hips and lower your upper body to almost parallel to the floor.\r\n2. Bend your elbows to bring the dumbbells close to your torso, with your upper arms parallel to the floor and your forearms perpendicular to the floor.\r\n3. Extend your arms fully behind you by straightening your elbows, keeping your upper arms stationary. Squeeze your triceps at the top of the movement.\r\n4. Slowly return the dumbbells to the starting position by bending your elbows. Repeat for the desired number of repetitions.', E'1. Avoid swinging the weights; use only your triceps to perform the movement.\r\n2. Focus on a slow and controlled movement to maximize triceps engagement.\r\n3. Exhale as you extend your arms and inhale as you return to the starting position.\r\n', '{"video_url":"videos/Triceps/dumbbells triceps kick back both arms.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('15000e17-c41e-49c6-a768-4850996182b4'::uuid, 'Dumbell Burpee', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand. Lower the dumbbells to the floor as you squat down, placing them shoulder-width apart.\r\n2. Jump your feet back into a plank position, keeping your body in a straight line from head to heels.\r\n3. Jump your feet back towards the dumbbells, landing in a squat position. As you stand up, lift the dumbbells off the floor.\r\n4. Jump up explosively, extending your arms overhead with the dumbbells. Land softly and immediately lower the dumbbells back to the floor to start the next repetition.', E'1. Land softly on your feet to minimize impact on your joints.\r\n2. Keep your feet hip-width apart for stability during the plank and jump phases.\r\n3. Start with lighter weights to get comfortable with the movement, then gradually increase the weight.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Dumbell Burpee.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Dumbell Burpee1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Dumbell Burpee.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7a841e28-abf1-41b4-bd00-d0ab3e62034f'::uuid, 'Dynamic Back Stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your arms straight down by your sides.\r\n2. Explosively swing your arms upwards in a wide arc until they are overhead, stretching your back muscles dynamically.\r\n3. Immediately swing your arms back down to your sides in a controlled manner, allowing your back to relax.\r\n4. Repeat the movement continuously for the desired number of repetitions.', E'1. Keep your movements fluid and controlled to maximize the stretch and avoid any sudden jerks that could cause injury.\r\n2. Engage your core muscles to support your lower back throughout the movement.\r\n3. Ensure your knees are slightly bent to maintain balance and reduce strain on your lower back.', '{"image_male_start":"images/Stretching - Mobility/Dynamic Back Stretch.jpg","image_male_end":"images/Stretching - Mobility/Dynamic Back Stretch1.jpg","video_url":"videos/Stretching - Mobility/Dynamic Back Stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e91db686-14db-46c6-8a90-bcca76dc207b'::uuid, 'Dynamic Leg Swing', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand next to a wall or sturdy object, using your right hand to support yourself and left hand on your hip. Position your feet hip-width apart.\r\n2. Swing your left leg forward and backward in a controlled, yet dynamic motion while lightly rotating your hips. Keep your leg straight but not locked at the knee.\r\n3. Allow the movement to be fluid, swinging your leg as high forward and backward as your flexibility allows.\r\n4. After completing the desired number of repetitions, switch sides and repeat the movement with your right leg while supporting yourself with your left hand.', E'1. Keep the swinging leg straight, but avoid locking the knee to reduce strain on the joint.\r\n2. Perform the swings in a controlled manner to maximize the stretch and avoid any sudden jerks.\r\n3. Focus on smooth, fluid movements, gradually increasing the range of motion as your muscles warm up.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Dynamic Leg Swing.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Dynamic Leg Swing1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Dynamic Leg Swing.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4bd8e0c6-c34c-4299-aa76-533f33e79439'::uuid, 'Elbow back stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your arms at your sides.\r\n2. Bring both hands behind you and place them on your lower back, fingers pointing downward.\r\n3. Gently push your hips forward and lean your upper body backward, feeling a stretch in your chest and shoulders.\r\n4. Hold the stretch for a few seconds, then return to the starting position. Repeat the movement for the desired number of repetitions.', E'1. Engage your core muscles to support your lower back as you lean backward.\r\n2. Avoid overextending your lower back; only lean back as far as comfortable without causing pain.\r\n3. Breathe deeply throughout the exercise, inhaling as you prepare to stretch and exhaling as you lean back.\r\n', '{"image_male_start":"images/Stretching - Mobility/elbow back stretch  .jpg","video_url":"videos/Stretching - Mobility/elbow back stretch  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('293598ca-ea70-43d3-8a04-08e059d307c7'::uuid, 'Elbow Extension And Supination Pronation Forearm Stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your arms extended in front of you at hip level, palms open and over each other, with one hand crossing over the other.\r\n2. Keep your palms crossed over each other and perform a wrist curl by bending your wrists upward.\r\n3. Extend your wrists back down to the starting position.\r\n4. Repeat the wrist curl and extension movements for the desired number of repetitions, then switch the position of your hands and repeat.', E'1. Ensure your wrists and forearms do the majority of the movement, minimizing shoulder involvement.\r\n2. Maintain straight arms and avoid bending your elbows during the stretch.\r\n3. Perform the stretch with both hand positions to maintain muscle balance and flexibility.\r\n\r\n', '{"image_male_start":"images/Stretching - Mobility/Elbow Extension And Supination Pronation Forearm Stretch.jpg","image_male_end":"images/Stretching - Mobility/Elbow Extension And Supination Pronation Forearm Stretch1.jpg","video_url":"videos/Stretching - Mobility/Elbow Extension And Supination Pronation Forearm Stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('97dd6c93-2604-4991-afb1-934ebfebb48f'::uuid, 'Elbow Flexor Stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand next to a wall with your feet shoulder-width apart, and extend your right arm out fully against the wall at shoulder height, palm facing the wall.\r\n2. Rotate your torso away from the wall to increase the stretch in your arm.\r\n3. Ensure your right arm is straight and press your palm firmly against the wall.\r\n4. Hold the stretch for 15-30 seconds, feeling the stretch in your forearm and elbow flexors, then switch to the other arm.', E'1. Ensure the stretch is felt in the forearm, elbow flexors, and chest muscles without causing pain.\r\n2. Breathe deeply and steadily throughout the stretch, focusing on relaxing the muscles.\r\n3. Perform the stretch on both arms to maintain muscle balance and flexibility.\r\n\r\n', '{"image_male_start":"images/Stretching - Mobility/Elbow Flexor Stretch.jpg","image_male_end":"images/Stretching - Mobility/Elbow Flexor Stretch1.jpg","video_url":"videos/Stretching - Mobility/Elbow Flexor Stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('371e7652-7a81-40e6-aec1-ea2d1477e57b'::uuid, 'Elbow Lift Reverse Push Up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on the floor between two chairs, with your torso facing the ceiling and your elbows resting on the chairs, arms bent at 90 degrees.\r\n2. Extend your legs out in front of you, keeping them together and straight, and lift your hips into a reverse plank position, forming a straight line from your shoulders to your heels.\r\n3. Press through your elbows to lift your torso and hips slightly higher, engaging your triceps and core muscles.\r\n4. Lower your body back down by bending your elbows, keeping your torso and legs straight throughout the movement. Repeat for the desired number of repetitions.', E'1. Ensure the chairs are stable and securely placed to prevent slipping or tipping during the exercise.\r\n2. Keep your movements slow and controlled to maximize muscle engagement and avoid injury.\r\n3. Engage your core throughout the exercise to maintain a straight body line and support your lower back.', '{"image_male_start":"images/Back/Elbow Lift Reverse Push Up.jpg","image_male_end":"images/Back/Elbow Lift Reverse Push Up1.jpg","video_url":"videos/Back/Elbow Lift Reverse Push Up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d9cfadac-5b8d-48f4-8b25-9d365bba58e0'::uuid, 'Elbow Push Plank Up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a forearm plank position with your elbows directly under your shoulders and your body forming an arch line from your head to your heels.\r\n2. Push through your forearms to lift your elbows a few inches off the floor, keeping your fists on the floor.\r\n3. Keep pressing through your forearms to raise your hips off the floor until your torso is straight, maintaining the plank position.\r\n4. Lower your hips back down to the floor, followed by your elbows, returning to the starting position. Repeat for the desired number of repetitions.', E'1. Perform the exercise on a non-slip surface to prevent your forearms from slipping.\r\n2. Ensure your elbows remain under your shoulders to maintain proper form and prevent strain.\r\n3. Move slowly and with control to maximize muscle engagement and prevent injury.', '{"image_male_start":"images/Abdominals/Elbow Push Plank Up.jpeg","video_url":"videos/Abdominals/Elbow Push Plank Up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3185cdf9-2068-42a3-a234-7b4aafa6d37b'::uuid, 'Elbow-Up and Down Dynamic Plank', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a forearm plank position with your elbows directly under your shoulders and your body forming a straight line from your head to your heels.\r\n2. Lift your elbows a few inches off the floor, keeping your forearms off the floor and fists on the floor.\r\n3. Place your right hand on the floor, followed by your left hand, pushing your body up into a high plank position with your arms fully extended.\r\n4. Lower your right hand back to the floor, followed by your left hand, returning to the starting position. Repeat the movement, alternating which arm you start with each time.', E'1. Focus on steady breathing, exhaling as you push up and inhaling as you lower down.\r\n2. Avoid rotating your hips; keep them level to increase core stability.\r\n3. Perform the exercise on a non-slip surface to prevent your forearms and hands from slipping.', '{"image_male_start":"images/Abdominals/Elbow-Up and Down Dynamic Plank.jpeg","video_url":"videos/Abdominals/Elbow-Up and Down Dynamic Plank.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('410ef48f-9d3c-4071-8dba-72a02964e07f'::uuid, 'Elbows Back Stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your arms at your sides.\r\n2. Bring both hands behind you and place them on your lower back, fingers pointing downward.\r\n3. Gently push your hips forward and lean your upper body backward, feeling a stretch in your chest and shoulders.\r\n4. Hold the stretch for a few seconds, then return to the starting position. Repeat the movement for the desired number of repetitions.', E'1. Engage your core muscles to support your lower back as you lean backward.\r\n2. Avoid overextending your lower back; only lean back as far as comfortable without causing pain.\r\n3. Breathe deeply throughout the exercise, inhaling as you prepare to stretch and exhaling as you lean back.\r\n', '{"image_male_start":"images/Stretching - Mobility/Elbows Back Stretch.jpg","image_male_end":"images/Stretching - Mobility/Elbows Back Stretch1.jpg","video_url":"videos/Stretching - Mobility/Elbows Back Stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8b6be35e-e6f2-4f59-bad6-30cf43448133'::uuid, 'Elevated Push Up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Place your hands on elevated surfaces just wider than shoulder-width apart. Position your feet together on the floor, forming a straight line from your head to your heels.\r\n2. Engage your core and lower your chest towards the elevated surfaces by bending your elbows, keeping them at a 45-degree angle from your body.\r\n3. Lower your body until your chest nearly touches the floor between the elevated surfaces, maintaining a straight back and tight core throughout the movement.\r\n4. Push through your hands to return to the starting position, fully extending your arms. Repeat the movement for the desired number of repetitions.', E'1. Perform the movement with control, lowering yourself slowly to maximize muscle activation and prevent injury.\r\n2. Breathe steadily throughout the exercise, exhaling as you push up and inhaling as you lower down.\r\n3. Avoid flaring your elbows out to the sides; keep them at a 45-degree angle to engage your chest and triceps more effectively.', '{"image_male_start":"images/Chest/Elevated Push Up.jpg","image_male_end":"images/Chest/Elevated Push Up1.jpg","video_url":"videos/Chest/Elevated Push Up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('53a9c63e-88f7-4906-b7f8-ad37c7d0144b'::uuid, 'Elevated Standing Calf Raise', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand on the edge of a step with your heels hanging off, placing your forefeet securely on the edge. Hold onto a stable surface for balance if necessary.\r\n2. Lower your heels below the level of the platform to feel a stretch in your calf muscles.\r\n3. Press through your forefeet to raise your heels as high as possible, fully contracting your calf muscles.\r\n4. Slowly lower your heels back down to the starting position, maintaining control throughout the movement. Repeat for the desired number of repetitions.', E'1. Focus on pressing through the forefeet and avoid using momentum to lift your heels.\r\n2. Maintain a slight bend in your knees to reduce strain and keep the movement fluid.\r\n3. Ensure the platform or step is stable and secure to prevent slipping or tipping during the exercise.\r\n', '{"image_male_start":"images/Legs/Elevated Standing Calf Raise.jpg","image_male_end":"images/Legs/Elevated Standing Calf Raise1.jpg","video_url":"videos/Legs/Elevated Standing Calf Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d697ebc1-4f50-464c-a863-b8084c1cb284'::uuid, 'Exercise Ball Back Extension With Hands Behind Head', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Position yourself face down on an exercise ball with your hips resting on the ball and your feet anchored against a wall or stable surface for balance.\r\n2. Place your hands behind your head, elbows pointing out to the sides.\r\n3. Engage your core and lower your upper body towards the floor, rounding your back slightly.\r\n4. Lift your upper body back up until your body forms a straight line from your head to your hips. Repeat for the desired number of repetitions.', E'1. Focus on lifting with your back muscles rather than pulling with your hands to avoid neck strain.\r\n2. Breathe steadily, inhaling as you lower your body and exhaling as you lift it.\r\n3. Ensure your feet are firmly anchored to prevent slipping and maintain balance.\r\n4. Avoid overextending your back at the top of the movement to prevent strain.', '{"image_male_start":"images/Back/Exercise Ball Back Extension With Hands Behind Head.jpg","image_male_end":"images/Back/Exercise Ball Back Extension With Hands Behind Head1.jpg","video_url":"videos/Back/Exercise Ball Back Extension With Hands Behind Head.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1a177fe2-68b4-46fa-8eaa-e43feb3874ec'::uuid, 'Exercise ball back stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '4e9ce883-ea47-492d-be41-fc224e54b4c7'::uuid, E'1. Sit on an exercise ball with your feet flat on the floor, hip-width apart, and your hands resting on your thighs.\r\n2. Slowly walk your feet forward and roll your body down the ball, allowing your back to drape over the ball until your lower back is supported.\r\n3. Extend your arms at your sides, allowing them to hang naturally to the floor, and relax into the stretch, letting your spine gently curve over the ball.\r\n4. Hold the stretch for 15-30 seconds, breathing deeply and allowing your back muscles to relax.', E'1. Ensure your feet are firmly planted on the floor to maintain stability and balance.\r\n2. Use a properly inflated exercise ball to ensure it supports your weight and provides a comfortable stretch.\r\n3. Focus on relaxing your back and letting your spine naturally curve over the ball.\r\n4. Breathe deeply and steadily, inhaling through your nose and exhaling through your mouth to enhance relaxation.\r\n', '{"image_male_start":"images/Stretching - Mobility/exercise ball back stretch  .jpg","video_url":"videos/Stretching - Mobility/exercise ball back stretch  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('db29f7e9-967c-4e6c-9b60-e076770e5810'::uuid, 'Exercise Ball Body Saw', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a plank position with your forearms resting on an exercise ball and your body forming a straight line from your head to your heels.\r\n2. Engage your core and slowly roll the ball a few inches away from your body.\r\n3. Reverse the motion by rolling the ball closer to your forearms.\r\n4. Continue the rolling motion for the desired number of repetitions, maintaining a straight body line throughout.', E'1. Breathe steadily throughout the exercise, exhaling as you move forward and inhaling as you move back.\r\n2. Avoid allowing your lower back to arch; keep your spine in a neutral position.\r\n3. Use a properly inflated exercise ball to ensure stability and control during the movement.', '{"image_male_start":"images/Abdominals/Exercise Ball Body Saw.jpeg","video_url":"videos/Abdominals/Exercise Ball Body Saw.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b9fd1af5-6874-46e5-8ee9-979de55578d1'::uuid, 'Exercise ball hip flexor stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Sit on an exercise ball in a lunge position with your left foot flat on the floor in front of you and your right leg extended behind you, the ball supporting your hips.\r\n2. Lower your hips downwards towards the floor, allowing the ball to support your weight and feeling a stretch in your right hip flexor.\r\n3. Keep your torso upright and your core engaged as you hold the stretch.\r\n4. Hold the stretch for 15-30 seconds, then switch legs and repeat on the other side.', E'1. Move slowly into the stretch to prevent overextending or causing discomfort.\r\n2. Breathe deeply and steadily, focusing on relaxing the hip flexor muscles.\r\n3. Use a properly inflated exercise ball to provide adequate support for your hips.', '{"image_male_start":"images/Stretching - Mobility/exercise ball hip flexor stretch.jpg","image_male_end":"images/Stretching - Mobility/exercise ball hip flexor stretch1.jpg","video_url":"videos/Stretching - Mobility/exercise ball hip flexor stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c4f21c53-4b15-4227-8aea-6f978a4c8e61'::uuid, 'Exercise ball lat stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '4e9ce883-ea47-492d-be41-fc224e54b4c7'::uuid, E'1. Begin on the floor in a tabletop position with your hands and knees on the floor.\r\n2. Have an exercise ball on your right side and position your right hand on the ball, keeping your arm bent at 90 degrees.\r\n3. Slowly roll the ball forward with your right hand, extending your right arm overhead and lowering your chest lightly towards the floor, feeling the stretch along your back.\r\n4. Hold the stretch for 15-30 seconds, then slowly roll the ball back towards you to return to the starting position. Repeat on the left side.', E'1. Ensure your hips remain above your knees to maintain proper form and support.\r\n2. Move slowly into the stretch to prevent overextending or causing discomfort.\r\n3. Use a properly inflated exercise ball to provide adequate support for your arm.', '{"image_male_start":"images/Stretching - Mobility/exercise ball lat stretch  .jpg","video_url":"videos/Stretching - Mobility/exercise ball lat stretch  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8051f0c3-1d40-46fd-89d7-8b32984a95db'::uuid, 'Exercise Ball Leg Curl', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your arms at your sides, palms facing down. Place your heels and calves on top of an exercise ball.\r\n2. Engage your core and lift your hips off the floor, forming a straight line from your shoulders to your heels. This is your starting position.\r\n3. Bend your knees and roll the ball towards your glutes by pulling your heels in. Keep your hips elevated and maintain the straight line from your shoulders to your knees.\r\n4. Slowly extend your legs, rolling the ball back to the starting position while keeping your hips lifted. Repeat for the desired number of repetitions.', E'1. Use a properly inflated exercise ball to provide stability and ease of movement.\r\n2. Move slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Focus on steady breathing, exhaling as you curl the ball in and inhaling as you extend your legs.', '{"image_male_start":"images/Legs/Exercise Ball Leg Curl.jpg","image_male_end":"images/Legs/Exercise Ball Leg Curl1.jpg","video_url":"videos/Legs/Exercise Ball Leg Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('65345104-d5ae-47d2-aaf3-344bb0456e6c'::uuid, 'Exercise ball lower back dynamic stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '4e9ce883-ea47-492d-be41-fc224e54b4c7'::uuid, E'1. Begin on your hands and feet with your arms and legs straight, positioning an exercise ball under your hips.\r\n2. Slowly lower your body onto the ball, allowing it to support your hips and torso, while keeping your arms and legs straight and your hips bent.\r\n3. Relax into the stretch for a second, letting your back gently arch over the ball and feeling a stretch in your lower back.\r\n4. Repeat for the desired number of repetitions.', E'1. Focus on deep, steady breathing, inhaling as you lower onto the ball and exhaling as you return to the starting position.\r\n2. Ensure the exercise ball is properly inflated to provide adequate support and facilitate smooth movement.\r\n3. Avoid overextending your back; only lower onto the ball as far as is comfortable without causing strain.', '{"image_male_start":"images/Stretching - Mobility/exercise ball lower back dynamic stretch  .jpg","video_url":"videos/Stretching - Mobility/exercise ball lower back dynamic stretch  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9c9452a7-0d8e-429c-93ef-fe94db0b67be'::uuid, 'Exercise ball lower back prone stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '4e9ce883-ea47-492d-be41-fc224e54b4c7'::uuid, E'1. Begin on your hands and feet with your arms and legs straight, positioning an exercise ball under your hips.\r\n2. Slowly lower your body onto the ball, allowing it to support your hips and torso, while keeping your arms and legs straight and your hips bent.\r\n3. Relax into the stretch, letting your back gently arch over the ball and feeling a stretch in your lower back.\r\n4. Hold the stretch for 15-30 seconds. Repeat for the desired number of repetitions.', E'1. Focus on deep, steady breathing, inhaling as you lower onto the ball and exhaling as you return to the starting position.\r\n2. Ensure the exercise ball is properly inflated to provide adequate support and facilitate smooth movement.\r\n3. Avoid overextending your back; only lower onto the ball as far as is comfortable without causing strain.', '{"image_male_start":"images/Stretching - Mobility/exercise ball lower back prone stretch  .jpg","video_url":"videos/Stretching - Mobility/exercise ball lower back prone stretch  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ec9b2709-24b0-4172-b4e1-8ec64d0ed188'::uuid, 'Exercise ball lying side lat stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '4e9ce883-ea47-492d-be41-fc224e54b4c7'::uuid, E'1. Begin by lying on your side with an exercise ball positioned under your armpit and lower ribs. Extend your top leg straight and bend your lower leg, placing the foot flat on the floor for stability.\r\n2. Extend your top arm on your side, keeping it along the line of your body, and allow your bottom arm to hang in a comfortable position for support over the ball.\r\n3. Allow your body to relax over the ball, feeling a stretch along the side of your torso and through your latissimus dorsi (lats).\r\n4. Hold the stretch for 15-30 seconds, breathing deeply and steadily. Slowly roll back to the starting position and repeat on the other side.\r\n', E'1. Focus on deep, steady breathing, inhaling as you extend into the stretch and exhaling as you hold the stretch.\r\n2. Avoid overextending your back; only stretch as far as is comfortable without causing strain.\r\n3. Make sure your top leg is firmly planted on the floor to provide stability and support.', '{"image_male_start":"images/Stretching - Mobility/exercise ball lying side lat stretch.jpg","image_male_end":"images/Stretching - Mobility/exercise ball lying side lat stretch1.jpg","video_url":"videos/Stretching - Mobility/exercise ball lying side lat stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1ec3aa42-192b-4ffc-9021-ba22602a3613'::uuid, 'Exercise Ball Lying Side Lat Stretch V.2', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '4e9ce883-ea47-492d-be41-fc224e54b4c7'::uuid, E'1. Begin by lying on your side with an exercise ball positioned under your armpit and lower ribs. Extend your top leg straight and bend your lower leg, placing the foot flat on the floor for stability.\r\n2. Allow your bottom arm to hang in a comfortable position for support over the ball and extend your left arm overhead, reaching it along the line of your body.\r\n3. Allow your body to relax over the ball, feeling a stretch along the side of your torso and through your latissimus dorsi (lats).\r\n4. Hold the stretch for 15-30 seconds, breathing deeply and steadily. Slowly roll back to the starting position and repeat on the other side.\r\n', E'1. Focus on deep, steady breathing, inhaling as you extend into the stretch and exhaling as you hold the stretch.\r\n2. Avoid overextending your back; only stretch as far as is comfortable without causing strain.\r\n3. Make sure your top leg is firmly planted on the floor to provide stability and support.', '{"image_male_start":"images/Stretching - Mobility/Exercise Ball Lying Side Lat Stretch V.2.jpg","image_male_end":"images/Stretching - Mobility/Exercise Ball Lying Side Lat Stretch V.21.jpg","video_url":"videos/Stretching - Mobility/Exercise Ball Lying Side Lat Stretch V.2.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('28327052-9fcf-43b7-a6cd-799bb3faea23'::uuid, 'Exercise Ball One Legged Diagonal Kick Hamstring Curl', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by lying on your back with your arms at your sides, palms facing down. Place your left heel and calf on top of an exercise ball, with your right leg extended straight and aligned with your hips.\r\n2. Engage your core and lift your hips off the floor, forming a straight line from your shoulders to your left heel.\r\n3. Bend your left knee and roll the ball diagonally towards the middle of your hips, pulling your heel in while simultaneously raising your right leg upwards along the line of your hips.\r\n4. Extend your left leg, rolling the ball back to the starting position, while lowering your right leg back to the floor. Repeat for the desired number of repetitions.\r\n5. Switch legs and repeat the movement with your right heel and calf on the ball and your left leg extending upwards.', E'1. Move slowly and with control to maximize muscle engagement and prevent injury.\r\n2. Focus on steady breathing, exhaling as you curl the ball in and inhale as you extend your leg.\r\n3. Use a properly inflated exercise ball to provide stability and ease of movement.', '{"image_male_start":"images/Legs/Exercise Ball One Legged Diagonal Kick Hamstring Curl.jpg","image_male_end":"images/Legs/Exercise Ball One Legged Diagonal Kick Hamstring Curl1.jpg","video_url":"videos/Legs/Exercise Ball One Legged Diagonal Kick Hamstring Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0b0fb910-6e21-4502-ad9b-8435e7dfe621'::uuid, 'Exercise ball seated hamstring stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Sit on an exercise ball with your feet flat on the floor, hip-width apart, and your back straight.\r\n2. Extend your right leg straight out in front of you, keeping your heel on the floor and your toes pointing up.\r\n3. Slowly hinge at your hips, leaning forward while keeping your back straight, and reach towards your right toes with your right hand. Feel the stretch along the back of your right leg (hamstring).\r\n4. Hold the stretch for 15-30 seconds, breathing deeply and steadily. Return to the starting position and repeat with your left leg.', E'1. Focus on deep, steady breathing, inhaling as you prepare to stretch and exhaling as you lean forward.\r\n2. Only stretch as far as is comfortable without causing pain or discomfort.\r\n3. Ensure the exercise ball is properly inflated to provide adequate support and stability.', '{"image_male_start":"images/Stretching - Mobility/exercise ball seated hamstring stretch.jpg","image_male_end":"images/Stretching - Mobility/exercise ball seated hamstring stretch1.jpg","video_url":"videos/Stretching - Mobility/exercise ball seated hamstring stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('cf03d7f1-798d-44fb-92eb-3e879c713079'::uuid, 'Exercise ball seated quad stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Sit on an exercise ball with your feet flat on the floor, hip-width apart.\r\n2. Slowly roll forward until your back is supported on the ball, keeping your shoulders and head relaxed on the ball, and place your arms at your sides for balance.\r\n3. Bend your left leg with your foot flat on the floor for support. Bend your right leg, placing the forefoot on the floor and the heel on the ball to feel the stretch in your right quadriceps.\r\n4. Hold the stretch for 15-30 seconds, breathing deeply and steadily. Slowly return to the starting position and repeat with the opposite leg.', E'1. Focus on deep, steady breathing, inhaling as you prepare to stretch and exhaling as you hold the stretch.\r\n2. Only stretch as far as is comfortable without causing pain or discomfort.\r\n3. Ensure the exercise ball is properly inflated to provide adequate support and stability.', '{"image_male_start":"images/Stretching - Mobility/exercise ball seated quad stretch.jpg","image_male_end":"images/Stretching - Mobility/exercise ball seated quad stretch1.jpg","video_url":"videos/Stretching - Mobility/exercise ball seated quad stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('46c0eca6-9f17-4945-a6f6-f338e928a8d5'::uuid, 'Exercise ball sit ups', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on an exercise ball with your feet flat on the floor, hip-width apart, leaning back so the ball supports your lower back and hips. Place your hands behind your head.\r\n2. Engage your core and lift your upper body until vertical to the floor, performing a sit-up while keeping your chin slightly tucked and your back straight.\r\n3. Lower your upper body back down to the starting position with control, maintaining tension in your core.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Ensure your lower back remains in contact with the exercise ball to support your spine and prevent injury.\r\n2. Move slowly and with control to avoid using momentum and to maximize muscle engagement.\r\n3. Focus on steady breathing, exhaling as you lift your upper body and inhaling as you lower it.\r\n4. Avoid pulling on your neck with your hands if they are placed behind your head; instead, use your core muscles to lift.', '{"image_male_start":"images/Abdominals/exercise ball sit ups.jpeg","video_url":"videos/Abdominals/exercise ball sit ups.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b7044175-1cd5-449f-a0ee-55f1e1e06518'::uuid, 'Exercise Ball Wall Squat', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and place an exercise ball between your lower back and a wall. Lean slightly into the ball for support.\r\n2. Slowly lower your body into a squat position by bending your knees and hips, keeping your back straight and allowing the ball to roll along your back.\r\n3. Lower yourself until your thighs are parallel to the floor, ensuring your knees do not extend past your toes.\r\n4. Push through your heels to return to the starting position, straightening your legs. Repeat for the desired number of repetitions.', E'1. Ensure your feet are positioned far enough in front of you so that your knees do not extend past your toes when squatting.\r\n2. Move slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Focus on steady breathing, inhaling as you lower into the squat and exhaling as you push back up.\r\n4. Maintain an upright posture with your back against the ball to avoid leaning forward.', '{"image_male_start":"images/Legs/Exercise Ball Wall Squat.jpg","image_male_end":"images/Legs/Exercise Ball Wall Squat1.jpg","video_url":"videos/Legs/Exercise Ball Wall Squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('70721381-46a5-4c37-a005-326467d6bb45'::uuid, 'Explosive push ups', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a standard push-up position with your hands placed slightly wider than shoulder-width apart and your body forming a straight line from head to heels.\r\n2. Lower your chest towards the floor by bending your elbows, keeping your core tight and your body straight.\r\n3. Push through your hands explosively to extend your arms rapidly, generating maximum force without lifting your hands off the floor.\r\n4. Lower into the next push-up with control, immediately repeating the explosive movement for the desired number of repetitions.', E'1. Keep your movements controlled and focus on generating power in the push without lifting off the floor.\r\n2. Breathe steadily, exhaling as you push up explosively and inhaling as you lower down.\r\n3. Focus on explosive power and control rather than speed to maximize effectiveness.\r\n4. Use a non-slip surface to prevent your hands from slipping during the exercise.\r\n', '{"image_male_start":"images/Chest/Explosive push ups.jpg","image_male_end":"images/Chest/Explosive push ups1.jpg","video_url":"videos/Chest/Explosive push ups.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6a1b0f97-f9bd-4365-8829-16afcbacfe2d'::uuid, 'Extended Side Angle', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet wide apart, about 3-4 feet, with your right foot turned out 90 degrees and your left foot slightly turned in. Place your hands on your hips.\r\n2. Bend your right knee, ensuring it aligns over your right ankle, and lower your right thigh until it is parallel to the floor. Extend your left leg straight.\r\n3. Lean to your right side by bending your right knee further and place your right elbow on your right thigh. Raise your left arm overhead, creating a straight line from your left hand to your left foot.\r\n4. Hold the position for a moment, then return to the starting position with control. Repeat on the other side.', E'1. Ensure your bent knee is aligned with your ankle to avoid strain on the knee joint.\r\n2. Only stretch as far as is comfortable without causing pain or discomfort.\r\n3. Focus on deep, steady breathing, inhaling as you extend into the stretch and exhaling as you hold the stretch.\r\n4. Use a yoga block or modify the hand placement if needed for additional support.', '{"image_male_start":"images/Yoga/Extended Side Angle.jpg","image_male_end":"images/Yoga/Extended Side Angle1.jpg","video_url":"videos/Yoga/Extended Side Angle.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('296083cb-89cc-4980-8181-221ac5091e32'::uuid, 'Extension And Inclination Neck Stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your back straight and shoulders relaxed.\r\n2. Slowly rotate your head to the left side while diagonally lowering your head, bringing your chin towards your left shoulder to feel a stretch in your neck.\r\n3. Hold the stretch for a few seconds, breathing deeply and steadily.\r\n4. Return to the neutral position and repeat on the other side by rotating your head to the right and diagonally lowering your head towards your right shoulder. Repeat for the desired number of repetitions.', E'1. Maintain good posture with your back straight and shoulders relaxed throughout the exercise.\r\n2. Perform the stretches in a smooth, fluid motion to enhance flexibility and reduce muscle tension.\r\n3. Avoid overextending your neck; only stretch as far as is comfortable without causing pain or discomfort.\r\n', '{"image_male_start":"images/Stretching - Mobility/Extension And Inclination Neck Stretch.jpg","image_male_end":"images/Stretching - Mobility/Extension And Inclination Neck Stretch1.jpg","video_url":"videos/Stretching - Mobility/Extension And Inclination Neck Stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f3f8b864-5f36-4fd6-9f47-27fce9bc2e4b'::uuid, 'Extension Of Arms In Vertical Stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, your back straight, and your core engaged.\r\n2. Raise your arms overhead, interlocking your fingers and turning your palms upward.\r\n3. Stretch upwards as much as possible, lengthening your spine and reaching towards the ceiling. Hold the position for 15-30 seconds.\r\n4. Slowly release the stretch and bring your arms back down to your sides. Repeat for the desired number of repetitions.', E'1. Move slowly and with control to maximize the stretch and avoid any sudden movements.\r\n2. Focus on deep, steady breathing, inhaling as you reach upwards and exhaling as you hold the stretch.\r\n3. Avoid arching your back; instead, focus on lengthening your spine.', '{"image_male_start":"images/Stretching - Mobility/Extension Of Arms In Vertical Stretch.jpg","image_male_end":"images/Stretching - Mobility/Extension Of Arms In Vertical Stretch1.jpg","video_url":"videos/Stretching - Mobility/Extension Of Arms In Vertical Stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('25335b0a-4ba1-4d1e-88e4-19bd81f6a6aa'::uuid, 'Ez bar biceps curl close grip', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0e9c1392-3e8d-454d-be69-641c3a69f2b9'::uuid, E'1. Stand with your feet shoulder-width apart, holding an EZ bar with hands closer than shoulder-width, palms facing forward, and your arms fully extended down.\r\n2. Curl the EZ bar towards your chest by bending your elbows, keeping your upper arms stationary and close to your body.\r\n3. Squeeze your biceps at the top of the movement, ensuring the bar reaches shoulder height.\r\n4. Slowly lower the bar back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Focus on engaging your biceps throughout the movement.\r\n2. Perform the movement slowly and with control to maximize biceps activation and reduce injury risk.\r\n3. Exhale as you curl the bar up and inhale as you lower it back down.', '{"image_male_start":"images/Biceps/Ez bar biceps curl close grip.jpeg","video_url":"videos/Biceps/Ez bar biceps curl close grip .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6bd00cc7-8d3c-4793-8c84-407a46bcc6cf'::uuid, 'Ez bar biceps curl normal grip', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0e9c1392-3e8d-454d-be69-641c3a69f2b9'::uuid, E'1. Stand with your feet shoulder-width apart, holding an EZ bar with hands at shoulder-width, palms facing forward, and your arms fully extended down.\r\n2. Curl the EZ bar towards your chest by bending your elbows, keeping your upper arms stationary and close to your body.\r\n3. Squeeze your biceps at the top of the movement, ensuring the bar reaches shoulder height.\r\n4. Slowly lower the bar back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Focus on engaging your biceps throughout the movement.\r\n2. Perform the movement slowly and with control to maximize biceps activation and reduce injury risk.\r\n3. Exhale as you curl the bar up and inhale as you lower it back down.', '{"image_male_start":"images/Biceps/Ez bar biceps curl normal grip.jpeg","video_url":"videos/Biceps/Ez bar biceps curl normal grip .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ec6395d7-1309-4bce-9d3a-95b4ba11d2e6'::uuid, 'Ez bar biceps curl wide grip', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0e9c1392-3e8d-454d-be69-641c3a69f2b9'::uuid, E'1. Stand with your feet shoulder-width apart, holding an EZ bar with hands just wider than shoulder-width, palms facing forward, and your arms fully extended down.\r\n2. Curl the EZ bar towards your chest by bending your elbows, keeping your upper arms stationary and close to your body.\r\n3. Squeeze your biceps at the top of the movement, ensuring the bar reaches shoulder height.\r\n4. Slowly lower the bar back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Focus on engaging your biceps throughout the movement.\r\n2. Perform the movement slowly and with control to maximize biceps activation and reduce injury risk.\r\n3. Exhale as you curl the bar up and inhale as you lower it back down.', '{"image_male_start":"images/Biceps/Ez bar biceps curl wide grip.jpeg","video_url":"videos/Biceps/Ez bar biceps curl wide grip .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2c97d160-c861-4b36-8170-0f4b4c37ae6e'::uuid, 'Ez bar cable curl wide grip', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0e9c1392-3e8d-454d-be69-641c3a69f2b9'::uuid, E'1. Stand facing the cable machine with your feet shoulder-width apart, holding an EZ bar attached to the low pulley, hands just wider than shoulder-width, palms facing forward.\r\n2. Curl the EZ bar towards your shoulder by bending your elbows, keeping your upper arms stationary and close to your body.\r\n3. Squeeze your biceps at the top of the movement, ensuring the bar reaches shoulder height.\r\n4. Slowly lower the bar back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Focus on engaging your biceps throughout the movement.\r\n2. Perform the movement slowly and with control to maximize biceps activation and reduce injury risk.\r\n3. Exhale as you curl the bar up and inhale as you lower it back down.', '{"image_male_start":"images/Biceps/Ez bar cable curl wide grip.jpeg","video_url":"videos/Biceps/Ez bar cable curl wide grip .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9040b109-79a4-49c4-89f0-01be26448d4e'::uuid, 'Ez bar cable curl wide grip crossover machine', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0e9c1392-3e8d-454d-be69-641c3a69f2b9'::uuid, E'1. Stand facing the cable machine with your feet shoulder-width apart, holding an EZ bar attached to the low pulley of a crossover machine, hands just wider than shoulder-width, palms facing forward.\r\n2. Curl the EZ bar towards your shoulder by bending your elbows, keeping your upper arms stationary and close to your body.\r\n3. Squeeze your biceps at the top of the movement, ensuring the bar reaches shoulder height.\r\n4. Slowly lower the bar back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Focus on engaging your biceps throughout the movement.\r\n2. Perform the movement slowly and with control to maximize biceps activation and reduce injury risk.\r\n3. Exhale as you curl the bar up and inhale as you lower it back down.', '{"image_male_start":"images/Biceps/ez bar cable curl wide grip crossover machine.jpeg","video_url":"videos/Biceps/ez bar cable curl wide grip crossover machine.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('722034eb-18fa-457d-9fe7-34538cd19426'::uuid, 'Ez bar overhead extensions standing', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '0e9c1392-3e8d-454d-be69-641c3a69f2b9'::uuid, E'1. Stand with your feet shoulder-width apart, holding an EZ bar with an overhand grip. Raise the bar overhead until your arms are fully extended, with your hands positioned closer together on the bar.\r\n2. Keep your elbows close to your head and slowly lower the bar behind your head by bending your elbows.\r\n3. Lower the bar until your arms are fully bent.\r\n4. Extend your elbows to raise the bar back to the starting position, fully extending your arms overhead.', E'1. Ensure your elbows remain close to your head throughout the movement to effectively target the triceps.\r\n2. Use a controlled motion and avoid swinging the bar or using momentum.\r\n3. Avoid locking your elbows at the top of the movement to maintain tension on the triceps.', '{"image_male_start":"images/Triceps/ez bar overhead extensions standing.jpeg","video_url":"videos/Triceps/ez bar overhead extensions standing  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c5e20c5e-548a-461a-aa94-68649171bb9c'::uuid, 'Ez bar seated close grip shoulder press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '0e9c1392-3e8d-454d-be69-641c3a69f2b9'::uuid, E'1. Sit on a bench with back support, holding an EZ bar with a close overhand grip. Position the bar at shoulder height with your palms facing your neck and your elbows pointing forward.\r\n2. Press the bar overhead by extending your elbows upward.\r\n3. Fully extend your arms without locking your elbows at the top of the movement.\r\n4. Lower the bar back to the starting position at shoulder height with control, keeping your elbows pointing forward.', E'1. Ensure your elbows stay in front of you throughout the movement to effectively target the shoulders.\r\n2. Avoid locking your elbows at the top to keep tension on the shoulder muscles.\r\n3. Inhale as you lower the bar and exhale as you press it overhead.', '{"image_male_start":"images/Shoulders/ez bar seated close grip shoulder press .jpg","video_url":"videos/Shoulders/ez bar seated close grip shoulder press .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f78e4809-2f26-4bc1-9690-2269e0fd3d03'::uuid, 'EZ Bar Seated Wrist Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '0e9c1392-3e8d-454d-be69-641c3a69f2b9'::uuid, E'1. Sit on a bench holding an EZ bar with an underhand grip (palms facing up). Rest your forearms on your thighs with your wrists just beyond the edge, allowing the bar to hang down.\r\n2. Curl your wrists upward by flexing your forearms, lifting the EZ bar as high as possible while keeping your forearms stationary on your thighs.\r\n3. Squeeze your forearms at the top of the movement.\r\n4. Lower the bar back to the starting position in a controlled manner, allowing your wrists to fully extend.', E'1. Keep your forearms stationary on your thighs throughout the exercise.\r\n2. Use a controlled motion and avoid using momentum or swinging the bar.\r\n3. Avoid lifting your forearms off your thighs to ensure proper isolation of the forearm muscles.', '{"image_male_start":"images/Forearms/EZ Bar Seated Wrist Curl.jpeg","video_url":"videos/Forearms/EZ Bar Seated Wrist Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('11475b55-2353-4d09-aa11-569d74f0a999'::uuid, 'EZ Bar Standing Front Raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '0e9c1392-3e8d-454d-be69-641c3a69f2b9'::uuid, E'1. Stand with your feet shoulder-width apart, holding an EZ bar with an overhand grip (palms facing down), hands placed slightly wider than shoulder-width apart. Let the bar hang in front of your thighs.\r\n2. Raise the EZ bar directly in front of you to shoulder height until parallel to the floor.\r\n3. Pause briefly at the top of the movement, squeezing your shoulder muscles.\r\n4. Lower the bar back to the starting position in a controlled manner.', E'1. Avoid using momentum to lift the bar; focus on a controlled motion.\r\n2. Exhale as you lift the bar and inhale as you lower it.\r\n3. Keep your wrists in a neutral position to avoid strain.', '{"image_male_start":"images/Shoulders/EZ Bar Standing Front Raise.jpg","image_male_end":"images/Shoulders/EZ Bar Standing Front Raise1.jpg","video_url":"videos/Shoulders/EZ Bar Standing Front Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('da3945bd-ba70-405c-917a-6cb20c74ba11'::uuid, 'EZ Barbell Anti Gravity Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '0e9c1392-3e8d-454d-be69-641c3a69f2b9'::uuid, E'1. Lie chest first on an incline bench, holding an EZ barbell with palms facing the floor, hands positioned shoulder-width apart. Hold the barbell close to your shoulders, just under your face, with elbows bent.\r\n2. Press the barbell forward in a straight line until your arms are fully extended, keeping the bar parallel to the floor.\r\n3. Pause briefly at the end of the movement, ensuring your arms are straight and the barbell is fully extended forward.\r\n4. Return the barbell back to the starting position with control, bringing it close to your shoulders. Repeat the exercise.', E'1. Avoid using momentum; focus on a controlled and steady motion.\r\n2. Exhale as you press the barbell forward and inhale as you lower it.\r\n3. Focus on using your shoulders to press the weight, minimizing lower back involvement.', '{"image_male_start":"images/Shoulders/EZ Barbell Anti Gravity Press.jpg","image_male_end":"images/Shoulders/EZ Barbell Anti Gravity Press1.jpg","video_url":"videos/Shoulders/EZ Barbell Anti Gravity Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('96630937-8b68-463b-a0cb-4e1f22ee6365'::uuid, 'EZ Barbell Close grip Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '0e9c1392-3e8d-454d-be69-641c3a69f2b9'::uuid, E'1. Stand with your feet shoulder-width apart, holding an EZ barbell with a close grip (hands positioned closer than shoulder-width apart) and palms facing up.\r\n2. Curl the barbell upward towards your shoulders by bending your elbows, focusing on engaging your biceps.\r\n3. Squeeze your biceps at the top of the movement, ensuring the barbell reaches shoulder height.\r\n4. Lower the barbell back to the starting position with control, fully extending your arms.', E'1. Keep your elbows stationary and close to your body throughout the movement.\r\n2. Avoid using momentum or swinging your body to lift the barbell.\r\n3. Exhale as you curl the barbell up and inhale as you lower it.', '{"image_male_start":"images/Biceps/EZ Barbell Close grip Curl.jpeg","video_url":"videos/Biceps/EZ Barbell Close grip Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d1ed037f-8972-4554-9197-9fa72e5261eb'::uuid, 'EZ Barbell Curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '0e9c1392-3e8d-454d-be69-641c3a69f2b9'::uuid, E'1. Stand with your feet shoulder-width apart, holding an EZ barbell with a normal grip (hands positioned at shoulder-width apart) and palms facing up.\r\n2. Curl the barbell upward towards your shoulders by bending your elbows, focusing on engaging your biceps.\r\n3. Squeeze your biceps at the top of the movement, ensuring the barbell reaches shoulder height.\r\n4. Lower the barbell back to the starting position with control, fully extending your arms.', E'1. Keep your elbows stationary and close to your body throughout the movement.\r\n2. Avoid using momentum or swinging your body to lift the barbell.\r\n3. Exhale as you curl the barbell up and inhale as you lower it.', '{"image_male_start":"images/Biceps/EZ Barbell Curl.jpeg","video_url":"videos/Biceps/EZ Barbell Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('69412755-f250-4b08-8a35-89494c99a3e6'::uuid, 'Fast feet', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, knees slightly bent, and your arms at your sides.\r\n2. Quickly alternate lifting your feet off the floor, moving them up and down rapidly as if running in place, but without moving forward.\r\n3. Keep your core engaged and maintain a slight bend in your knees to stay light on your feet.\r\n4. Continue the rapid foot movement for the desired duration, maintaining a steady and controlled pace.', E'1. Stay on your forefeet to maintain quick, light movements.\r\n2. Use your arms for balance, allowing them to move naturally as your feet move.\r\n3. Focus on quick, controlled movements to maximize speed and effectiveness.\r\n4. Breathe steadily throughout the exercise, inhaling through your nose and exhaling through your mouth.\r\n', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Fast feet  .jpg","video_url":"videos/Calisthenics-Cardio-Functional/Fast feet  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b5a5a314-2529-448d-9e5f-aebdfd8e7650'::uuid, 'Feet together barbell squats', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet together, holding a barbell across your upper back with an overhand grip. Ensure the barbell is balanced and rests comfortably on your traps.\r\n2. Slowly lower your body into a squat by bending your knees and hips, keeping your knees aligned with your toes.\r\n3. Lower yourself until your thighs are at least parallel to the floor, or as low as your flexibility allows, without compromising form.\r\n4. Push through your heels to stand back up, extending your knees and hips to return to the starting position.', E'1. Keep your feet together throughout the entire movement to maintain balance and stability.\r\n2. Ensure your knees track over your toes and do not cave inward.\r\n3. Maintain a neutral spine and keep your chest up to avoid rounding your back.', '{"image_male_start":"images/Legs/Feet Together barbell Squats  .jpg","video_url":"videos/Legs/Feet Together barbell Squats  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9463c739-53ec-438e-aba0-ab12cd57431d'::uuid, 'Fire hydrant bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin on the floor in an all-fours position with your hands directly under your shoulders and your knees under your hips. Keep your back straight and your core engaged.\r\n2. Keeping your knee bent at a 90-degree angle, lift your right leg out to the side until your thigh is parallel to the floor. Keep your hips level and avoid rotating your torso.\r\n3. Hold the position for a moment, then lower your right leg back to the starting position with control.\r\n4. Repeat the movement for the desired number of repetitions, then switch to your left leg and repeat.', E'1. Avoid rotating your hips or torso; focus on isolating the movement in your hip.\r\n2. Perform the exercise on a stable, non-slip surface to prevent slipping or injury.\r\n3. Breathe steadily, exhaling as you lift your leg and inhaling as you lower it.\r\n4. Ensure your hands are positioned directly under your shoulders to maintain proper form and prevent strain.\r\n', '{"image_male_start":"images/Legs/fire hydrant bodyweight  .jpg","video_url":"videos/Legs/fire hydrant bodyweight  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1891dbfa-ea53-4431-b532-39f3d54098b4'::uuid, 'Fire hydrant circle bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin on the floor in an all-fours position with your hands directly under your shoulders and your knees under your hips. Keep your back straight and your core engaged.\r\n2. Keeping your knee bent at a 90-degree angle, lift your right leg out to the side until your thigh is parallel to the floor.\r\n3. Move your right leg in a circular motion, making small controlled circles with your knee while keeping your hips level and avoiding torso rotation.\r\n4. Complete the desired number of circles, then lower your right leg back to the starting position. Repeat on the left side.', E'1. Avoid rotating your hips or torso; focus on isolating the movement in your hip.\r\n2. Perform the exercise on a stable, non-slip surface to prevent slipping or injury.\r\n3. Breathe steadily, exhaling as you lift your leg and inhaling as you lower it.\r\n4. Ensure your hands are positioned directly under your shoulders to maintain proper form and prevent strain.\r\n', '{"image_male_start":"images/Legs/fire hydrant circle bodyweight.jpg","image_male_end":"images/Legs/fire hydrant circle bodyweight1.jpg","video_url":"videos/Legs/fire hydrant circle bodyweight.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8c479052-82db-477f-868b-b19bed43e34d'::uuid, 'Fixed bar stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '35516b5e-1db4-4a4c-84d8-d7845b9c83f1'::uuid, E'1. Stand facing a fixed vertical bar. Position your feet shoulder-width apart and grasp the bar with both hands, palms facing each other.\r\n2. Step back slightly and lean your hips backward, allowing your arms to extend fully and your upper body to lean forward. Keep your back straight and your knees bent.\r\n3. Lean backwards and down to the floor while pulling back with your hips to feel a deep stretch in your shoulders, upper back, and lats.\r\n4. Hold the stretch for 15-30 seconds, breathing deeply and steadily. Slowly return to the starting position by stepping forward and releasing the bar.', E'1. Move slowly and with control to maximize the stretch and avoid any sudden movements.\r\n2. Only stretch as far as is comfortable without causing pain or discomfort.\r\n3. Ensure the bar is securely fixed and can support your weight.', '{"image_male_start":"images/Stretching - Mobility/fixed bar stretch  .jpg","video_url":"videos/Stretching - Mobility/fixed bar stretch  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('34a528cf-6e4d-44de-acd4-57575f8ee662'::uuid, 'Flat bench cable fly', 'Resistance', 'strength', 'weight_reps', 'intermediate', '7c8ccea6-1ecd-4abd-a28f-2f05d0d539a5'::uuid, E'1. Position a flat bench between two cable machines with the pulleys set at the lowest position. Attach handles to the pulleys and lie down on the bench with your feet flat on the floor.\r\n2. Grasp the handles with both hands, palms facing up, and extend your arms out to your sides at chest level.\r\n3. Raise the handles over your chest in a wide arc, keeping a slight bend in your elbows, squeezing your chest at the top.\r\n4. Slowly bring the handles back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep a slight bend in your elbows throughout the movement to avoid straining your joints.\r\n2. Focus on engaging your chest muscles throughout the movement.\r\n3. Inhale as you loer the handles back down and exhale as you raise them up.', '{"image_male_start":"images/Chest/flat bench cable fly.jpg","image_male_end":"images/Chest/flat bench cable fly1.jpg","video_url":"videos/Chest/flat bench cable fly.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d5cbc519-fc97-40b2-9b20-6900e9fb9e5b'::uuid, 'Floor cable Resistance band press', 'Resistance', 'strength', 'weight_reps', 'intermediate', '23ac3a8b-7dc5-4dd2-aaa6-7d6ffd8421f7'::uuid, E'1. Lie on the floor with your knees bent and feet flat on the floor. Position a resistance band under your upper back, holding a handle in each hand with your palms facing forward.\r\n2. Position your elbows on the floor bent at a 90-degree angle.\r\n3. Press the handles straight up towards the ceiling until your arms are fully extended, keeping a slight bend in your elbows.\r\n4. Slowly return to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you press the handles up and inhale as you return them to the starting position.\r\n2. Use a lighter resistance band if needed to ensure proper form and gradually increase the resistance as you get stronger.\r\n3. Focus on engaging your chest muscles throughout the movement.', '{"image_male_start":"images/Chest/floor cable resistance band press.jpg","image_male_end":"images/Chest/floor cable resistance band press1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('cd0c601c-bd1d-4fca-9e81-c9e9f105e245'::uuid, 'Flutter kicks', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your legs extended and your arms at your sides, palms facing down. Place your hands under your hips for added support if needed.\r\n2. Lift your legs off the floor a few inches, keeping them straight and close together.\r\n3. Quickly alternate kicking your legs up and down in a small, controlled motion, engaging your core throughout the movement.\r\n4. Continue the flutter kicks for the desired duration, maintaining a steady and controlled pace. Lower your legs back to the floor to complete the exercise.', E'1. Move your legs in a controlled manner to maximize muscle engagement and prevent injury.\r\n2. Focus on steady breathing, exhaling as you kick your legs and inhaling as you maintain the movement.\r\n3. Avoid letting your lower back arch off the floor; keep it pressed down to prevent strain.\r\n4. Adjust the height of your kicks to suit your fitness level and comfort, starting with smaller kicks and increasing the range of motion as you build strength.\r\n', '{"image_male_start":"images/Abdominals/flutter kicks.jpeg","video_url":"videos/Abdominals/flutter kicks .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c8c52d6b-7d35-413d-be1c-a07f00ec9da4'::uuid, 'Front raise Resistance bands', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart, placing the resistance band under both feet. Hold the handles of the resistance band with your palms facing backwards and your arms extended down in front of you.\r\n2. Raise your arms straight in front of you to shoulder height, keeping a slight bend in your elbows.\r\n3. Slowly lower your arms back to the starting position with control.\r\n4. Repeat for the desired number of repetitions.', E'1. Focus on engaging your shoulder muscles throughout the movement.\r\n2. Maintain a neutral wrist position to prevent strain.\r\n3. Stand with a slight bend in your knees for better stability.', '{"image_male_start":"images/Shoulders/front raise resistance bands .jpg","video_url":"videos/Shoulders/front raise resistance bands .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('eb8ab81a-0860-483e-aca2-682b74eced24'::uuid, 'Front raises barbell', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with an overhand grip (palms facing your hips), hands placed at shoulder-width.\r\n2. Lift the barbell in front of you by raising your arms straight out until they are parallel to the floor.\r\n3. Hold the barbell at the top of the movement for a brief moment, ensuring your shoulders are fully engaged.\r\n4. Slowly lower the barbell back to the starting position in a controlled manner, keeping your arms straight throughout the movement.', E'1. Avoid using momentum to lift the barbell; focus on using your shoulder muscles.\r\n2. Keep your core engaged to prevent arching your lower back.\r\n3. Maintain a slight bend in your elbows to reduce strain on your joints.', '{"image_male_start":"images/Shoulders/front raises barbell .jpg","video_url":"videos/Shoulders/front raises barbell .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('26565b0b-41d2-4682-ba28-816cc047df16'::uuid, 'Front raises dumbbell seated', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench with your feet flat on the floor, holding a dumbbell in each hand with an overhand grip (palms facing down), arms hanging down by your sides.\r\n2. Lift the dumbbells in front of you by raising your arms straight forward until they are at head height.\r\n3. Hold the dumbbells at the top of the movement for a brief moment, ensuring your shoulders are fully engaged.\r\n4. Slowly lower the dumbbells back to the starting position in a controlled manner.', E'1. Avoid using momentum to lift the dumbbells; focus on using your shoulder muscles.\r\n2. Keep your core engaged to prevent arching your lower back.\r\n3. Maintain a slight bend in your elbows to reduce strain on your joints.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('da74c256-72fb-4475-b1d2-05f6930cb24f'::uuid, 'Front shoulder stretch with bar', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Stand with your feet shoulder-width apart, holding a bar with both hands, palms facing down, and hands placed slightly wider than shoulder-width apart.\r\n2. Extend your arms straight down in front of you at shoulder height, keeping your back straight and core engaged.\r\n3. Gently raise the bar overhead and bend them both at 90 degrees to lower them until you feel a stretch in your shoulders.\r\n4. Hold the stretch for 20-30 seconds. Repeat as needed.', E'1. Keep your back straight and avoid arching or rounding your spine.\r\n2. Use a lighter bar to ensure proper form and gradually increase the stretch as you become more flexible.\r\n3. Breathe deeply and steadily throughout the stretch to help relax your muscles.', '{"image_male_start":"images/Stretching - Mobility/front shoulder stretch with bar.jpg","image_male_end":"images/Stretching - Mobility/front shoulder stretch with bar1.jpg","video_url":"videos/Stretching - Mobility/front shoulder stretch with bar.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('88e7cc68-129f-4340-8996-caab87a9b28f'::uuid, 'Front squats dumbbell low', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet wider than shoulder-width apart, toes pointing slightly out. Hold a dumbbell in each hand, hanging by your sides, with your palms facing each other.\r\n2. Lower your body into a squat by bending your knees and hinging at your hips, pushing your knees lightly outwards as you descend.\r\n3. Continue lowering yourself until your thighs are just lower than parallel to the floor.\r\n4. Push through your heels to return to the starting position, extending your hips and knees. Repeat for the desired number of repetitions.', E'1. Ensure your knees track over your toes and do not cave inward during the squat.\r\n2. Maintain a straight back and avoid leaning forward excessively.\r\n3. Keep your chest up and your shoulders back to maintain proper posture.', '{"image_male_start":"images/Legs/front squats dumbbell low.jpg","image_male_end":"images/Legs/front squats dumbbell low1.jpg","video_url":"videos/Legs/front squats dumbbell low.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4ff520e1-3dea-4c4a-b3f8-fdccfca8bad0'::uuid, 'Front squats dumbbell over shoulders', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand. Position the dumbbells over your shoulders with your palms facing forward and elbows pointing down.\r\n2. Lower your body into a squat by bending your knees and hinging at your hips, pushing your knees lightly outwards as you descend.\r\n3. Continue lowering yourself until your thighs are just lower than parallel to the floor.\r\n4. Push through your heels to return to the starting position, extending your hips and knees. Repeat for the desired number of repetitions.', E'1. Ensure your knees track over your toes and do not cave inward during the squat.\r\n2. Maintain a straight back and avoid leaning forward excessively.\r\n3. Keep your chest up and your shoulders back to maintain proper posture.', '{"image_male_start":"images/Legs/front squats dumbbell over shoulders.jpg","image_male_end":"images/Legs/front squats dumbbell over shoulders1.jpg","video_url":"videos/Legs/front squats dumbbell over shoulders.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('650589aa-5cb1-46f0-93ef-6f9f5bc8f4c9'::uuid, 'Front squats kettlelbell over shoulders', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, holding a kettlebell in each hand. Place the kettlebells resting on opposite shoulders with your palms facing down and elbows pointing forward.\r\n2. Lower your body into a squat by bending your knees and hinging at your hips, pushing your knees lightly outwards as you descend.\r\n3. Continue lowering yourself until your thighs are parallel to the floor.\r\n4. Push through your heels to return to the starting position, extending your hips and knees. Repeat for the desired number of repetitions.', E'1. Ensure your knees track over your toes and do not cave inward during the squat.\r\n2. Maintain a straight back and avoid leaning forward excessively.\r\n3. Keep your chest up and your shoulders back to maintain proper posture.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2ae5dba4-c23a-4c90-aef3-62eb622d8d9c'::uuid, 'Full planche push up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a full planche position with your hands placed on the floor shoulder-width apart and your body parallel to the floor, fully supported by your hands. Your legs should be extended straight behind you, and your core and glutes engaged to maintain a straight line from head to heels.\r\n2. Lower your body towards the floor by bending your elbows, keeping your body in a horizontal position throughout the movement.\r\n3. Push through your hands to extend your arms and return to the starting planche position.\r\n4. Repeat the movement for the desired number of repetitions, maintaining control and stability throughout the exercise.', E'1. Engage your core and glutes to maintain a straight body line and prevent sagging or arching.\r\n2. Ensure your hands are positioned directly under your shoulders to maintain proper form and support.\r\n3. Use a non-slip surface to prevent your hands from slipping during the exercise.\r\n4. This is an advanced exercise; ensure you have adequate strength and balance before attempting it.', '{"image_male_start":"images/Chest/Full planche push up.jpg","image_male_end":"images/Chest/Full planche push up1.jpg","video_url":"videos/Chest/Full planche push up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d55dbb82-6810-45b4-aab0-0230285a2328'::uuid, 'Glute bridge with abduction bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your knees bent and your feet flat on the floor, hip-width apart. Place your arms at your sides with palms facing down.\r\n2. Engage your core and glutes and lift your hips towards the ceiling until your body forms a straight line from your shoulders to your knees.\r\n3. While holding the bridge position, spread your knees apart as far as comfortable, keeping your feet flat on the floor.\r\n4. Bring your knees back together, then lower your hips back to the starting position. Repeat for the desired number of repetitions.', E'1. Ensure your hips remain lifted and in line with your body during the abduction movement.\r\n2. Avoid letting your knees collapse inward; maintain control during the abduction movement.\r\n3. Focus on steady breathing, exhaling as you lift your hips and spread your knees, and inhaling as you lower your hips.', '{"image_male_start":"images/Legs/Glute Bridge With Abduction Bodyweight.jpg","image_male_end":"images/Legs/Glute Bridge With Abduction Bodyweight1.jpg","image_female_start":"images/Legs/Glute Bridge With Abduction Bodyweight_Female.jpg","image_female_end":"images/Legs/Glute Bridge With Abduction Bodyweight_Female1.jpg","video_url":"videos/Legs/Glute Bridge With Abduction Bodyweight.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('99002a35-51c1-4e19-bafd-0ba3cd43104c'::uuid, 'Goblet kettlebell squats', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '7352a8b5-30da-44d7-9cae-8a031f5d2aed'::uuid, E'1. Stand with your feet shoulder-width apart, holding a kettlebell close to your chest with both hands, gripping at the handle.\r\n2. Lower your body into a squat by bending your knees and hinging at your hips.\r\n3. Continue lowering yourself until your thighs are parallel to the floor.\r\n4. Push through your heels to return to the starting position, extending your hips and knees. Repeat for the desired number of repetitions.', E'1. Ensure your knees track over your toes and do not cave inward during the squat.\r\n2. Maintain a straight back and avoid leaning forward excessively.\r\n3. Breathe in as you lower into the squat and exhale as you push back up to the starting position.', '{"image_male_start":"images/Legs/goblet kettlebell squats  .jpg","video_url":"videos/Legs/goblet kettlebell squats  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f31db5aa-de3b-4793-ab30-57ec27491a56'::uuid, 'Good morning resistace band', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart, placing a resistance band under both feet. Hold a handle with each hand and place it close to your shoulders.\r\n2. Hinge at your hips to lower your torso forward until it is almost parallel to the floor, keeping your back straight.\r\n3. Slowly return to the starting position by extending your hips and knees to raise your torso.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep your back straight and avoid rounding your spine.\r\n2. Focus on engaging your glutes and hamstrings throughout the movement.\r\n3. Exhale as you raise your torso and inhale as you lower it.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('66422bbc-9ac9-4baf-ab64-9945ec085e4e'::uuid, 'Good mornings barbell', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell across your upper back with an overhand grip.\r\n2. Begin to hinge at your hips, pushing your hips back while lowering your torso towards the floor.\r\n3. Continue to lower your torso until it is almost parallel to the floor.\r\n4. Return to the starting position by driving your hips forward and raising your torso back up. Repeat for the desired number of repetitions.', E'1. Maintain a straight back and avoid rounding your spine.\r\n2. Focus on hinging at the hips rather than bending at the waist.\r\n3. Keep a slight bend in your knees to reduce stress on your lower back.', '{"video_url":"videos/Back/good mornings barbell .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6c9bf987-e5f5-48de-a010-7a2e4d3fe693'::uuid, 'Good mornings dumbbells', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand. Bring the dumbbells at shoulder height, with your elbows bent and pointing forward.\r\n2. Begin to hinge at your hips, pushing your hips back while lowering your torso towards the floor.\r\n3. Continue to lower your torso until it is almost parallel to the floor, feeling a stretch in your hamstrings.\r\n4. Return to the starting position by driving your hips forward and raising your torso back up. Repeat for the desired number of repetitions.', E'1. Maintain a straight back and avoid rounding your spine.\r\n2. Focus on hinging at the hips rather than bending at the waist.\r\n3. Keep a slight bend in your knees to reduce stress on your lower back.', '{"image_male_start":"images/Back/good mornings dumbbells.jpg","image_male_end":"images/Back/good mornings dumbbells1.jpg","video_url":"videos/Back/good mornings dumbbells.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('29f43068-28f4-4b90-8b01-fcc8b86148da'::uuid, 'Good mornings kettlebell', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '7352a8b5-30da-44d7-9cae-8a031f5d2aed'::uuid, E'1. Stand with your feet shoulder-width apart, holding a kettlebell with both hands at chest height. Keep your elbows bent and pointing downward.\r\n2. Begin to hinge at your hips, pushing your hips back while lowering your torso towards the floor.\r\n3. Continue to lower your torso until it is almost parallel to the floor, feeling a stretch in your hamstrings.\r\n4. Return to the starting position by driving your hips forward and raising your torso back up. Repeat for the desired number of repetitions.', E'1. Maintain a straight back and avoid rounding your spine.\r\n2. Focus on hinging at the hips rather than bending at the waist.\r\n3. Keep a slight bend in your knees to reduce stress on your lower back.', '{"image_male_start":"images/Back/good mornings kettlebell .jpg","video_url":"videos/Back/good mornings kettlebell .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5ce82aee-82ee-4ef6-876a-93a2b7238451'::uuid, 'Gym Rowing Machine Normal Speed', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd1b09d97-2d9c-4d96-8fa5-9c8a98e393c6'::uuid, E'1. Sit on the rowing machine with your feet securely strapped into the footrests, knees bent, and hands grasping the handle with an overhand grip.\r\n2. Push through your legs to extend your knees and drive your body backward, keeping your arms straight until your legs are almost fully extended.\r\n3. Just before your legs are fully extended, pull the handle towards your lower chest by bending your elbows and squeezing your shoulder blades together.\r\n4. Reverse the motion by extending your arms forward first, then bending your knees to return to starting position. Repeat for the desired number of repetitions or time.', E'1. Keep your back straight and avoid rounding your spine throughout the exercise.\r\n2. Use a moderate resistance level to ensure proper form and gradually increase the resistance as you get stronger.\r\n3. Exhale as you pull, and inhale as you return to the starting position.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Gym Rowing Machine Normal Speed.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Gym Rowing Machine Normal Speed1.jpg","image_female_start":"images/Calisthenics-Cardio-Functional/Gym Rowing Machine Normal Speed_female.jpg","image_female_end":"images/Calisthenics-Cardio-Functional/Gym Rowing Machine Normal Speed_female1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Gym Rowing Machine Normal Speed.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2abc096e-7192-4682-9a90-6403e33082c1'::uuid, 'Hack Squat Machine', 'Resistance', 'strength', 'weight_reps', 'intermediate', '728a4c43-332b-462b-9bff-00f84d999f5c'::uuid, E'1. Position yourself on the hack squat machine with your shoulders under the pads and your feet shoulder-width apart on the foot platform. Keep your back pressed against the backrest.\r\n2. Release the safety handles and slowly lower your body by bending your knees until your thighs are parallel to the foot platform.\r\n3. Push through your heels to extend your legs and return to the starting position.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep your back pressed against the backrest throughout the exercise.\r\n2. Focus on keeping your knees aligned with your toes to avoid straining your joints.\r\n3. Exhale as you push up and inhale as you lower your body.', '{"image_male_start":"images/Legs/Hack Squat Machine_Female.jpg","image_female_start":"images/Legs/Hack Squat Machine_Female.jpg","image_female_end":"images/Legs/Hack Squat Machine_Female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3fc92228-f629-4629-9481-ae2058855a96'::uuid, 'Hack Squat Machine Squat', 'Resistance', 'strength', 'weight_reps', 'intermediate', '728a4c43-332b-462b-9bff-00f84d999f5c'::uuid, E'1. Position yourself on the hack squat machine with your shoulders under the pads and your feet shoulder-width apart on the foot platform. Keep your back pressed against the backrest.\r\n2. Release the safety handles and slowly lower your body by bending your knees until your thighs are parallel to the foot platform.\r\n3. Push through your heels to extend your legs and return to the starting position.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep your back pressed against the backrest throughout the exercise.\r\n2. Focus on keeping your knees aligned with your toes to avoid straining your joints.\r\n3. Exhale as you push up and inhale as you lower your body.', '{"image_male_start":"images/Legs/Hack Squat Machine Squat.jpg","image_male_end":"images/Legs/Hack Squat Machine Squat1.jpg","video_url":"videos/Legs/Hack Squat Machine Squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a755e6db-069c-431c-95be-aeb6ebaa3e20'::uuid, 'Half burpees', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a high plank position with your hands placed directly under your shoulders and your body forming a straight line from head to heels.\r\n2. Quickly jump your feet forward towards your hands, landing with your heels on the floor in a squat position.\r\n3. Immediately jump your feet back to return to the high plank position, keeping your body straight and your core engaged.\r\n4. Repeat the movement for the desired number of repetitions, maintaining a quick and controlled pace.', E'1. Focus on steady breathing, exhaling as you jump your feet forward and back, and inhaling as you hold the plank position.\r\n2. Ensure your hands are placed directly under your shoulders in the plank position to maintain proper form and prevent strain.\r\n3. Use a non-slip surface to prevent your feet or hands from slipping during the exercise.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Half burpees  .jpg","video_url":"videos/Calisthenics-Cardio-Functional/Half burpees  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('bbe5913d-8bb7-43f7-8beb-51ff8cff9213'::uuid, 'Hammer curl Resistance band simultaneous', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart, placing the resistance band under both feet. Hold the handles with your palms facing each other and your arms extended down at your sides.\r\n2. Curl the handles up towards your shoulders simultaneously by bending your elbows, keeping your palms facing each other throughout the movement.\r\n3. Slowly lower the handles back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Keep your elbows close to your body and avoid swinging your arms.\r\n2. Focus on engaging your biceps and forearms throughout the movement.\r\n3. Exhale as you curl the handles up and inhale as you lower them back down.', '{"image_male_start":"images/Biceps/hammer curl resistance band simultaneous.jpeg","video_url":"videos/Biceps/hammer curl resistance band simultaneous.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b400a12e-260b-4ae4-8e66-416a24ae83b5'::uuid, 'HAMMER STRENGTH ISO-LATERAL LEG CURL Alternating Legs', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'cf71b4dd-e72b-4734-aa19-5566477202ad'::uuid, E'1. Lie face down on the Hammer Strength Iso-Lateral Leg Curl machine, placing your ankles under the leg pads and holding the handles on the sides of the machine for stability. Start with both legs fully extended.\r\n2. Curl one leg by bending your knee and pulling your ankle towards your glutes, keeping the other leg extended.\r\n3. Squeeze your hamstrings at the top of the movement and slowly lower your leg back to the starting position with control.\r\n4. Repeat with the other leg, alternating legs for the desired number of repetitions.', E'1. Keep your hips pressed against the bench throughout the exercise.\r\n2. Focus on engaging your hamstrings throughout the movement.\r\n3. Exhale as you curl your leg and inhale as you lower it back down.', '{"image_male_start":"images/Legs/HAMMER STRENGTH ISO-LATERAL LEG CURL Alternating Legs_Female.jpg","image_female_start":"images/Legs/HAMMER STRENGTH ISO-LATERAL LEG CURL Alternating Legs_Female.jpg","image_female_end":"images/Legs/HAMMER STRENGTH ISO-LATERAL LEG CURL Alternating Legs_Female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('da6d0180-2025-4882-ab9f-8b09eab4c224'::uuid, 'HAMMER STRENGTH ISO-LATERAL LEG CURL Single Leg', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'cf71b4dd-e72b-4734-aa19-5566477202ad'::uuid, E'1. Lie face down on the Hammer Strength Iso-Lateral Leg Curl machine, placing your ankles under the leg pads and holding the handles on the sides of the machine for stability. Start with both legs fully extended.\r\n2. Curl your right leg by bending your knee and pulling your ankle towards your glutes, keeping the other leg extended.\r\n3. Squeeze your hamstring at the top of the movement and slowly lower your leg back to the starting position with control.\r\n4. Repeat with the same leg for the desired number of repetitions and then switch to your left leg and repeat.', E'1. Keep your hips pressed against the bench throughout the exercise.\r\n2. Focus on engaging your hamstrings throughout the movement.\r\n3. Exhale as you curl your leg and inhale as you lower it back down.', '{"image_male_start":"images/Legs/HAMMER STRENGTH ISO-LATERAL LEG CURL_Single Leg.jpg","image_male_end":"images/Legs/HAMMER STRENGTH ISO-LATERAL LEG CURL_Single Leg1.jpg","image_female_start":"images/Legs/HAMMER STRENGTH ISO-LATERAL LEG CURL Single Leg_Female.jpg","image_female_end":"images/Legs/HAMMER STRENGTH ISO-LATERAL LEG CURL Single Leg_Female1.jpg","video_url":"videos/Legs/HAMMER STRENGTH ISO-LATERAL LEG CURL_Single Leg.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1b3d2ee4-7f67-44cf-a74f-2e38b42aee2f'::uuid, 'HAMMER STRENGTH ISO-LATERAL LEG CURL_Alternate Legs', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'cf71b4dd-e72b-4734-aa19-5566477202ad'::uuid, E'1. Lie face down on the Hammer Strength Iso-Lateral Leg Curl machine, placing your ankles under the leg pads and holding the handles on the sides of the machine for stability. Start with both legs fully extended.\r\n2. Curl one leg by bending your knee and pulling your ankle towards your glutes, keeping the other leg extended.\r\n3. Squeeze your hamstrings at the top of the movement and slowly lower your leg back to the starting position with control.\r\n4. Repeat with the other leg, alternating legs for the desired number of repetitions.', E'1. Keep your hips pressed against the bench throughout the exercise.\r\n2. Focus on engaging your hamstrings throughout the movement.\r\n3. Exhale as you curl your leg and inhale as you lower it back down.', '{"image_male_start":"images/Legs/HAMMER STRENGTH ISO-LATERAL LEG CURL_Alternate Legs.jpg","image_male_end":"images/Legs/HAMMER STRENGTH ISO-LATERAL LEG CURL_Alternate Legs1.jpg","video_url":"videos/Legs/HAMMER STRENGTH ISO-LATERAL LEG CURL_Alternate Legs.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('210e9544-841b-488d-a465-9abda31120d5'::uuid, 'HAMMER STRENGTH ISO-LATERAL LEG CURL_Both Leg', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'cf71b4dd-e72b-4734-aa19-5566477202ad'::uuid, E'1. Lie face down on the Hammer Strength Iso-Lateral Leg Curl machine, placing your ankles under the leg pads and holding the handles on the sides of the machine for stability. Start with both legs fully extended.\r\n2. Curl both legs by bending your knees and pulling your ankles towards your glutes.\r\n3. Squeeze your hamstrings at the top of the movement and slowly lower your legs back to the starting position with control.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep your hips pressed against the bench throughout the exercise.\r\n2. Focus on engaging your hamstrings throughout the movement.\r\n3. Exhale as you curl your leg and inhale as you lower it back down.', '{"image_male_start":"images/Legs/HAMMER STRENGTH ISO-LATERAL LEG CURL_Both Leg.jpg","image_male_end":"images/Legs/HAMMER STRENGTH ISO-LATERAL LEG CURL_Both Leg1.jpg","image_female_start":"images/Legs/HAMMER STRENGTH ISO-LATERAL LEG CURL_Both Leg_Female.jpg","image_female_end":"images/Legs/HAMMER STRENGTH ISO-LATERAL LEG CURL_Both Leg_Female1.jpg","video_url":"videos/Legs/HAMMER STRENGTH ISO-LATERAL LEG CURL_Both Leg.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('39ff976c-2f1b-4b14-89f5-10ed658db61e'::uuid, 'HAMMER STRENGTH ISO-LATERAL LEG CURL_Single Leg', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'cf71b4dd-e72b-4734-aa19-5566477202ad'::uuid, E'1. Lie face down on the Hammer Strength Iso-Lateral Leg Curl machine, placing your ankles under the leg pads and holding the handles on the sides of the machine for stability. Start with both legs fully extended.\r\n2. Curl your right leg by bending your knee and pulling your ankle towards your glutes, keeping the other leg extended.\r\n3. Squeeze your hamstring at the top of the movement and slowly lower your leg back to the starting position with control.\r\n4. Repeat with the same leg for the desired number of repetitions and then switch to your left leg and repeat.', E'1. Keep your hips pressed against the bench throughout the exercise.\r\n2. Focus on engaging your hamstrings throughout the movement.\r\n3. Exhale as you curl your leg and inhale as you lower it back down.', '{"image_male_start":"images/Legs/HAMMER STRENGTH ISO-LATERAL LEG CURL_Single Leg.jpg","image_male_end":"images/Legs/HAMMER STRENGTH ISO-LATERAL LEG CURL_Single Leg1.jpg","video_url":"videos/Legs/HAMMER STRENGTH ISO-LATERAL LEG CURL_Single Leg.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6726324f-5ace-4446-afe0-c215418bfdb2'::uuid, 'Hammer Strength MTS Iso-Lateral Biceps Curl Alternate Arm', 'Resistance', 'strength', 'weight_reps', 'intermediate', '19c915e4-c3a9-45c3-a353-2dc75641ee31'::uuid, E'1. Sit on the Hammer Strength MTS Iso-Lateral Biceps Curl machine with your feet flat on the floor. Grasp the handles with both hands, palms facing up, and position your elbows on the pads.\r\n2. Curl one handle by bending your elbow, bringing your hand towards your shoulder while keeping the other arm extended.\r\n3. Squeeze your biceps at the top of the movement and slowly lower the handle back to the starting position with control.\r\n4.  Repeat with the other arm, alternating arms for the desired number of repetitions.', E'1. Exhale as you curl the handle up and inhale as you lower it back down.\r\n2. Maintain a neutral wrist position to prevent strain.\r\n3. Focus on engaging your biceps throughout the movement.\r\n', '{"image_male_start":"images/Biceps/Hammer Strength MTS Iso-Lateral Biceps Curl Alternate Arm_Female.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('31c139a0-d875-4df4-a73c-cae4fb884988'::uuid, 'Hammer Strength MTS Iso-Lateral Biceps Curl Arm Alternating', 'Resistance', 'strength', 'weight_reps', 'intermediate', '19c915e4-c3a9-45c3-a353-2dc75641ee31'::uuid, E'1. Sit on the Hammer Strength MTS Iso-Lateral Biceps Curl machine with your feet flat on the floor. Grasp the handles with both hands, palms facing up, and position your elbows on the pads.\r\n2. Curl one handle by bending your elbow, bringing your hand towards your shoulder while keeping the other arm extended.\r\n3. Squeeze your biceps at the top of the movement and slowly lower the handle back to the starting position with control.\r\n4.  Repeat with the other arm, alternating arms for the desired number of repetitions.', E'1. Exhale as you curl the handle up and inhale as you lower it back down.\r\n2. Maintain a neutral wrist position to prevent strain.\r\n3. Focus on engaging your biceps throughout the movement.\r\n', '{"image_male_start":"images/Biceps/Hammer Strength MTS Iso-Lateral Biceps Curl Arm Alternating.jpeg","video_url":"videos/Biceps/Hammer Strength MTS Iso-Lateral Biceps Curl Arm Alternating.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f5b5e39d-e814-42b1-9e5b-ce975803b536'::uuid, 'Hammer Strength MTS Iso-Lateral Biceps Curl Both Arm', 'Resistance', 'strength', 'weight_reps', 'intermediate', '19c915e4-c3a9-45c3-a353-2dc75641ee31'::uuid, E'1. Sit on the Hammer Strength MTS Iso-Lateral Biceps Curl machine with your feet flat on the floor. Grasp the handles with both hands, palms facing up, and position your elbows on the pads.\r\n2. Curl both handles by bending your elbows, bringing your hands towards your shoulders.\r\n3. Squeeze your biceps at the top of the movement and slowly lower the handles back to the starting position with control.\r\n4.  Repeat for the desired number of repetitions.', E'1. Exhale as you curl the handles up and inhale as you lower them back down.\r\n2. Maintain a neutral wrist position to prevent strain.\r\n3. Focus on engaging your biceps throughout the movement.\r\n', '{"image_male_start":"images/Biceps/Hammer Strength MTS Iso-Lateral Biceps Curl Both Arm_Female.jpeg","video_url":"videos/Biceps/Hammer Strength MTS Iso-Lateral Biceps Curl Both Arm.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('fd1d753d-3ba5-40ed-b692-3f96cf3d9cd2'::uuid, 'Hammer Strength MTS Iso-Lateral Biceps Curl Single Arm', 'Resistance', 'strength', 'weight_reps', 'intermediate', '19c915e4-c3a9-45c3-a353-2dc75641ee31'::uuid, E'1. Sit on the Hammer Strength MTS Iso-Lateral Biceps Curl machine with your feet flat on the floor. Grasp the handles with both hands, palms facing up, and position your elbows on the pads.\r\n2. Curl the right handle by bending your elbow, bringing your hand towards your shoulder while keeping the other arm extended.\r\n3. Squeeze your biceps at the top of the movement and slowly lower the handle back to the starting position with control.\r\n4.  Repeat with the same arm for the desired number of repetitions and then switch to your left arm and repeat.', E'1. Exhale as you curl the handle up and inhale as you lower it back down.\r\n2. Maintain a neutral wrist position to prevent strain.\r\n3. Focus on engaging your biceps throughout the movement.\r\n', '{"image_male_start":"images/Biceps/Hammer Strength MTS Iso-Lateral Biceps Curl Single Arm_Female.jpeg","video_url":"videos/Biceps/Hammer Strength MTS Iso-Lateral Biceps Curl Single Arm.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('cd85339c-3715-4e90-a347-d4d7f0895484'::uuid, 'HAMMER STRENGTH MTS ISO-LATERAL DECLINE PRESS Alternate Arms', 'Resistance', 'strength', 'weight_reps', 'intermediate', '53ea8430-0519-4821-8528-65f92d96f08b'::uuid, E'1. Sit on the Hammer Strength MTS Iso-Lateral Decline Press, back pressed against the backrest and feet flat on the floor. Grasp the handles with both hands, palms facing down.\r\n2. Press one handle forward by extending your arm, keeping the other arm stationary. \r\n3. Squeeze your chest muscles at the bottom of the movement and slowly return the handle to the starting position with control.\r\n4. Repeat with the other arm, alternating arms for the desired number of repetitions.', E'1. Exhale as you press the handle and inhale as you return it to the starting position.\r\n2. Keep your back pressed against the backrest throughout the exercise.\r\n3. Focus on engaging your chest muscles throughout the movement.', '{"image_male_start":"images/Chest/HAMMER STRENGTH MTS ISO-LATERAL DECLINE PRESS Alternate Arms.jpg","image_male_end":"images/Chest/HAMMER STRENGTH MTS ISO-LATERAL DECLINE PRESS Alternate Arms1.jpg","video_url":"videos/Chest/HAMMER STRENGTH MTS ISO-LATERAL DECLINE PRESS Alternate Arms.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d38457fd-1561-41da-9713-0ad4056877e0'::uuid, 'HAMMER STRENGTH MTS ISO-LATERAL DECLINE PRESS Alternating Arms', 'Resistance', 'strength', 'weight_reps', 'intermediate', '53ea8430-0519-4821-8528-65f92d96f08b'::uuid, E'1. Sit on the Hammer Strength MTS Iso-Lateral Decline Press, back pressed against the backrest and feet flat on the floor. Grasp the handles with both hands, palms facing down.\r\n2. Press one handle forward by extending your arm, keeping the other arm stationary. \r\n3. Squeeze your chest muscles at the bottom of the movement and slowly return the handle to the starting position with control.\r\n4. Repeat with the other arm, alternating arms for the desired number of repetitions.', E'1. Exhale as you press the handle and inhale as you return it to the starting position.\r\n2. Keep your back pressed against the backrest throughout the exercise.\r\n3. Focus on engaging your chest muscles throughout the movement.', '{"image_male_start":"images/Chest/HAMMER STRENGTH MTS ISO-LATERAL DECLINE PRESS Alternating Arms_Female.jpg","image_female_start":"images/Chest/HAMMER STRENGTH MTS ISO-LATERAL DECLINE PRESS Alternating Arms_Female.jpg","image_female_end":"images/Chest/HAMMER STRENGTH MTS ISO-LATERAL DECLINE PRESS Alternating Arms_Female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7e8bacc3-8613-47cd-93ef-73b697dac1e9'::uuid, 'HAMMER STRENGTH MTS ISO-LATERAL DECLINE PRESS Both Arm', 'Resistance', 'strength', 'weight_reps', 'intermediate', '53ea8430-0519-4821-8528-65f92d96f08b'::uuid, E'1. Sit on the Hammer Strength MTS Iso-Lateral Decline Press, back pressed against the backrest and feet flat on the floor. Grasp the handles with both hands, palms facing down.\r\n2. Press both handles forward by extending your arms.\r\n3. Squeeze your chest muscles at the bottom of the movement and slowly return the handles to the starting position with control.\r\n4. Repeat for the desired number of repetitions.', E'1. Exhale as you press the handles and inhale as you return it to the starting position.\r\n2. Keep your back pressed against the backrest throughout the exercise.\r\n3. Focus on engaging your chest muscles throughout the movement.', '{"image_male_start":"images/Chest/HAMMER STRENGTH MTS ISO-LATERAL DECLINE PRESS Both Arm_Female.jpg","image_female_start":"images/Chest/HAMMER STRENGTH MTS ISO-LATERAL DECLINE PRESS Both Arm_Female.jpg","image_female_end":"images/Chest/HAMMER STRENGTH MTS ISO-LATERAL DECLINE PRESS Both Arm_Female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('21470012-806d-424c-89a5-6607b437ba0b'::uuid, 'HAMMER STRENGTH MTS ISO-LATERAL DECLINE PRESS Both Arms', 'Resistance', 'strength', 'weight_reps', 'intermediate', '53ea8430-0519-4821-8528-65f92d96f08b'::uuid, E'1. Sit on the Hammer Strength MTS Iso-Lateral Decline Press, back pressed against the backrest and feet flat on the floor. Grasp the handles with both hands, palms facing down.\r\n2. Press both handles forward by extending your arms.\r\n3. Squeeze your chest muscles at the bottom of the movement and slowly return the handles to the starting position with control.\r\n4. Repeat for the desired number of repetitions.', E'1. Exhale as you press the handles and inhale as you return it to the starting position.\r\n2. Keep your back pressed against the backrest throughout the exercise.\r\n3. Focus on engaging your chest muscles throughout the movement.', '{"image_male_start":"images/Chest/HAMMER STRENGTH MTS ISO-LATERAL DECLINE PRESS Both Arms.jpg","image_male_end":"images/Chest/HAMMER STRENGTH MTS ISO-LATERAL DECLINE PRESS Both Arms1.jpg","video_url":"videos/Chest/HAMMER STRENGTH MTS ISO-LATERAL DECLINE PRESS Both Arms.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('16440fcc-d9ac-4d79-bf17-f59ede7137c9'::uuid, 'HAMMER STRENGTH MTS ISO-LATERAL DECLINE PRESS Single Arm', 'Resistance', 'strength', 'weight_reps', 'intermediate', '53ea8430-0519-4821-8528-65f92d96f08b'::uuid, E'1. Sit on the Hammer Strength MTS Iso-Lateral Decline Press, back pressed against the backrest and feet flat on the floor. Grasp the handles with both hands, palms facing down.\r\n2. Press the right handle forward by extending your arm, keeping the other arm stationary. \r\n3. Squeeze your chest muscles at the bottom of the movement and slowly return the handle to the starting position with control.\r\n4. Repeat with the same arm for the desired number of repetitions and then switch to your left arm and repeat.', E'1. Exhale as you press the handle and inhale as you return it to the starting position.\r\n2. Keep your back pressed against the backrest throughout the exercise.\r\n3. Focus on engaging your chest muscles throughout the movement.', '{"image_male_start":"images/Chest/HAMMER STRENGTH MTS ISO-LATERAL DECLINE PRESS Single Arm.jpg","image_male_end":"images/Chest/HAMMER STRENGTH MTS ISO-LATERAL DECLINE PRESS Single Arm1.jpg","image_female_start":"images/Chest/HAMMER STRENGTH MTS ISO-LATERAL DECLINE PRESS Single Arm_Female.jpg","image_female_end":"images/Chest/HAMMER STRENGTH MTS ISO-LATERAL DECLINE PRESS Single Arm_Female1.jpg","video_url":"videos/Chest/HAMMER STRENGTH MTS ISO-LATERAL DECLINE PRESS Single Arm.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('03a92ae6-4b94-4608-9cc9-c6283809e82c'::uuid, 'Hammer Strength Plate Loaded High Row Alternate Arms', 'Resistance', 'strength', 'weight_reps', 'intermediate', '825d0d50-6358-4cd6-97b0-ccd2dd4e5fff'::uuid, E'1. Sit on the Hammer Strength Plate Loaded High Row machine with your feet flat on the floor and your chest pressed against the chest pad. Grasp the handles with both hands, palms facing forward.\r\n2. Pull one handle towards your torso by bending your elbow and squeezing your shoulder blade back, while keeping the other arm extended.\r\n3. Squeeze your back muscles at the end of the movement and slowly return the handle to the starting position with control.\r\n4. Repeat with the other arm, alternating arms for the desired number of repetitions.', E'1. Keep your chest pressed against the pad and your back straight throughout the exercise.\r\n2. Focus on engaging your back muscles throughout the movement.\r\n3. Exhale as you pull the handle towards your torso and inhale as you return it to the starting position.', '{"image_male_start":"images/Back/Hammer Strength Plate Loaded High Row Alternate Arms_Female.jpg","image_female_start":"images/Back/Hammer Strength Plate Loaded High Row Alternate Arms_Female.jpg","image_female_end":"images/Back/Hammer Strength Plate Loaded High Row Alternate Arms_Female1.jpg","video_url":"videos/Back/Hammer Strength Plate Loaded High Row Alternate Arms.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('75156800-686f-40c4-ac04-0d3da913db6a'::uuid, 'Hammer Strength Plate Loaded High Row Both Arms', 'Resistance', 'strength', 'weight_reps', 'intermediate', '825d0d50-6358-4cd6-97b0-ccd2dd4e5fff'::uuid, E'1. Sit on the Hammer Strength Plate Loaded High Row machine with your feet flat on the floor and your chest pressed against the chest pad. Grasp the handles with both hands, palms facing forward.\r\n2. Pull both handles towards your torso by bending your elbows and squeezing your shoulder blades back.\r\n3. Squeeze your back muscles at the end of the movement and slowly return the handles to the starting position with control.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep your chest pressed against the pad and your back straight throughout the exercise.\r\n2. Focus on engaging your back muscles throughout the movement.\r\n3. Exhale as you pull the handle towards your torso and inhale as you return it to the starting position.', '{"image_male_start":"images/Back/Hammer Strength Plate Loaded High Row Both Arms_Female.jpg","image_female_start":"images/Back/Hammer Strength Plate Loaded High Row Both Arms_Female.jpg","image_female_end":"images/Back/Hammer Strength Plate Loaded High Row Both Arms_Female1.jpg","video_url":"videos/Back/Hammer Strength Plate Loaded High Row Both Arms.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8f8504d2-0fcb-4b07-b751-aab1b23f3807'::uuid, 'Hammer Strength Plate Loaded High Row Single Arm', 'Resistance', 'strength', 'weight_reps', 'intermediate', '825d0d50-6358-4cd6-97b0-ccd2dd4e5fff'::uuid, E'1. Sit on the Hammer Strength Plate Loaded High Row machine with your feet flat on the floor and your chest pressed against the chest pad. Grasp the handles with both hands, palms facing forward.\r\n2. Pull the right handle towards your torso by bending your elbow and squeezing your shoulder blade back, while keeping the other arm extended.\r\n3. Squeeze your back muscles at the end of the movement and slowly return the handle to the starting position with control.\r\n4. Repeat with the same arm for the desired number of repetitions and then switch to your left arm and repeat.', E'1. Keep your chest pressed against the pad and your back straight throughout the exercise.\r\n2. Focus on engaging your back muscles throughout the movement.\r\n3. Exhale as you pull the handle towards your torso and inhale as you return it to the starting position.', '{"image_male_start":"images/Back/Hammer Strength Plate Loaded High Row Single Arm.jpg","image_male_end":"images/Back/Hammer Strength Plate Loaded High Row Single Arm1.jpg","video_url":"videos/Back/Hammer Strength Plate Loaded High Row Single Arm.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('320a8691-8f2b-4e0f-b1b0-24d2e00990f1'::uuid, 'Hammer Strength Plate Loaded High Row Single Arms', 'Resistance', 'strength', 'weight_reps', 'intermediate', '825d0d50-6358-4cd6-97b0-ccd2dd4e5fff'::uuid, E'1. Sit on the Hammer Strength Plate Loaded High Row machine with your feet flat on the floor and your chest pressed against the chest pad. Grasp the handles with both hands, palms facing forward.\r\n2. Pull the right handle towards your torso by bending your elbow and squeezing your shoulder blade back, while keeping the other arm extended.\r\n3. Squeeze your back muscles at the end of the movement and slowly return the handle to the starting position with control.\r\n4. Repeat with the same arm for the desired number of repetitions and then switch to your left arm and repeat.', E'1. Keep your chest pressed against the pad and your back straight throughout the exercise.\r\n2. Focus on engaging your back muscles throughout the movement.\r\n3. Exhale as you pull the handle towards your torso and inhale as you return it to the starting position.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('20d9b19f-8d38-4e43-afff-280da3ba1778'::uuid, 'HAMMER STRENGTH Plate-Loaded Combination Iso-Lateral Chest - Chest Press', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'cbeb9fc2-1d0e-4c15-a483-411ac788a9f9'::uuid, E'1. Sit on the Hammer Strength Plate-Loaded Iso-Lateral Chest Press machine, back pressed against the backrest and feet flat on the floor. Grasp the handles with both hands, palms facing down.\r\n2. Press the handles forward by extending your arms, keeping your elbows slightly bent at the end of the movement.\r\n3. Squeeze your chest muscles at the top of the movement and slowly return the handles to the starting position with control.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep your back pressed against the backrest throughout the exercise.\r\n2. Focus on engaging your chest muscles throughout the movement.\r\n3. Exhale as you press the handles forward and inhale as you return them to the starting position.', '{"image_male_start":"images/Chest/HAMMER STRENGTH Plate-Loaded Combination Iso-Lateral Chest - Chest Press_Female.jpg","image_female_start":"images/Chest/HAMMER STRENGTH Plate-Loaded Combination Iso-Lateral Chest - Chest Press_Female.jpg","image_female_end":"images/Chest/HAMMER STRENGTH Plate-Loaded Combination Iso-Lateral Chest - Chest Press_Female1.jpg","video_url":"videos/Chest/HAMMER STRENGTH Plate-Loaded Combination Iso-Lateral Chest - Chest Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b2e7fdb6-857d-4438-85b3-e10d64bfc0a7'::uuid, 'HAMMER STRENGTH Plate-Loaded Combination Iso-Lateral Chest - Chest Press Alternate Arm', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'cbeb9fc2-1d0e-4c15-a483-411ac788a9f9'::uuid, E'1. Sit on the Hammer Strength Plate-Loaded Iso-Lateral Chest Press machine, back pressed against the backrest and feet flat on the floor. Grasp the handles with both hands, palms facing down.\r\n2. Press one handle forward by extending your arm, keeping your elbow slightly bent at the end of the movement.\r\n3. Squeeze your chest muscles at the top of the movement and slowly return the handle to the starting position with control.\r\n4. Repeat with the other arm, alternating arms for the desired number of repetitions.', E'1. Keep your back pressed against the backrest throughout the exercise.\r\n2. Focus on engaging your chest muscles throughout the movement.\r\n3. Exhale as you press the handles forward and inhale as you return them to the starting position.', '{"image_male_start":"images/Chest/HAMMER STRENGTH Plate-Loaded Combination Iso-Lateral Chest - Chest Press Alternate Arm_Female.jpg","image_female_start":"images/Chest/HAMMER STRENGTH Plate-Loaded Combination Iso-Lateral Chest - Chest Press Alternate Arm_Female.jpg","image_female_end":"images/Chest/HAMMER STRENGTH Plate-Loaded Combination Iso-Lateral Chest - Chest Press Alternate Arm_Female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('48b56564-6c85-456b-9e11-ad0b093f11e9'::uuid, 'HAMMER STRENGTH Plate-Loaded Combination Iso-Lateral Chest - Chest Press Single Arm', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'cbeb9fc2-1d0e-4c15-a483-411ac788a9f9'::uuid, E'1. Sit on the Hammer Strength Plate-Loaded Iso-Lateral Chest Press machine, back pressed against the backrest and feet flat on the floor. Grasp the handles with both hands, palms facing down.\r\n2. Press the right handle forward by extending your arm, keeping your elbow slightly bent at the end of the movement.\r\n3. Squeeze your chest muscles at the top of the movement and slowly return the handle to the starting position with control.\r\n4. Repeat with the same arm for the desired number of repetitions and then switch to your left arm and repeat.', E'1. Keep your back pressed against the backrest throughout the exercise.\r\n2. Focus on engaging your chest muscles throughout the movement.\r\n3. Exhale as you press the handle forward and inhale as you return it to the starting position.', '{"image_male_start":"images/Chest/HAMMER STRENGTH Plate-Loaded Combination Iso-Lateral Chest - Chest Press_Single arm.jpg","image_male_end":"images/Chest/HAMMER STRENGTH Plate-Loaded Combination Iso-Lateral Chest - Chest Press_Single arm1.jpg","image_female_start":"images/Chest/HAMMER STRENGTH Plate-Loaded Combination Iso-Lateral Chest - Chest Press Single Arm_Female.jpg","image_female_end":"images/Chest/HAMMER STRENGTH Plate-Loaded Combination Iso-Lateral Chest - Chest Press Single Arm_Female1.jpg","video_url":"videos/Chest/HAMMER STRENGTH Plate-Loaded Combination Iso-Lateral Chest - Chest Press_Single arm.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('254798a4-7fa7-47b0-8419-06688e3cd3c5'::uuid, 'HAMMER STRENGTH Plate-Loaded Combination Iso-Lateral Chest - Chest Press_Alternating arms', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'cbeb9fc2-1d0e-4c15-a483-411ac788a9f9'::uuid, E'1. Sit on the Hammer Strength Plate-Loaded Iso-Lateral Chest Press machine, back pressed against the backrest and feet flat on the floor. Grasp the handles with both hands, palms facing down.\r\n2. Press one handle forward by extending your arm, keeping your elbow slightly bent at the end of the movement.\r\n3. Squeeze your chest muscles at the top of the movement and slowly return the handle to the starting position with control.\r\n4. Repeat with the other arm, alternating arms for the desired number of repetitions.', E'1. Keep your back pressed against the backrest throughout the exercise.\r\n2. Focus on engaging your chest muscles throughout the movement.\r\n3. Exhale as you press the handles forward and inhale as you return them to the starting position.', '{"image_male_start":"images/Chest/HAMMER STRENGTH Plate-Loaded Combination Iso-Lateral Chest - Chest Press_Alternating arms.jpg","image_male_end":"images/Chest/HAMMER STRENGTH Plate-Loaded Combination Iso-Lateral Chest - Chest Press_Alternating arms1.jpg","video_url":"videos/Chest/HAMMER STRENGTH Plate-Loaded Combination Iso-Lateral Chest - Chest Press_Alternating arms.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5abb8565-b551-47af-9a65-66bbd8548c74'::uuid, 'HAMMER STRENGTH Plate-Loaded Combination Iso-Lateral Chest - Chest Press_Single arm', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'cbeb9fc2-1d0e-4c15-a483-411ac788a9f9'::uuid, E'1. Sit on the Hammer Strength Plate-Loaded Iso-Lateral Chest Press machine, back pressed against the backrest and feet flat on the floor. Grasp the handles with both hands, palms facing down.\r\n2. Press the right handle forward by extending your arm, keeping your elbow slightly bent at the end of the movement.\r\n3. Squeeze your chest muscles at the top of the movement and slowly return the handle to the starting position with control.\r\n4. Repeat with the same arm for the desired number of repetitions and then switch to your left arm and repeat.', E'1. Keep your back pressed against the backrest throughout the exercise.\r\n2. Focus on engaging your chest muscles throughout the movement.\r\n3. Exhale as you press the handle forward and inhale as you return it to the starting position.', '{"image_male_start":"images/Chest/HAMMER STRENGTH Plate-Loaded Combination Iso-Lateral Chest - Chest Press_Single arm.jpg","image_male_end":"images/Chest/HAMMER STRENGTH Plate-Loaded Combination Iso-Lateral Chest - Chest Press_Single arm1.jpg","video_url":"videos/Chest/HAMMER STRENGTH Plate-Loaded Combination Iso-Lateral Chest - Chest Press_Single arm.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('61ed6bc3-36c9-4275-9e1e-04fca144ee53'::uuid, 'Hamstring lying curl up stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Lie on your back with your legs extended and your arms at your sides.\r\n2. Bend your right knee and bring it towards your chest until thigh is vertical to the floor, interlacing your fingers behind your thigh.\r\n3. Slowly straighten your right leg, extending your heel towards the ceiling and feeling the stretch in your hamstring. Keep your left leg extended and flat on the floor.\r\n4. Hold the stretch for 15-30 seconds, then slowly bend your right knee and lower your leg back to the starting position. Repeat on the left side.', E'1. Keep your lower back pressed into the floor to maintain proper alignment and support.\r\n2. Engage your core to stabilize your body and prevent your back from arching.\r\n3. Move slowly and with control to maximize the stretch and avoid any sudden movements.', '{"image_male_start":"images/Stretching - Mobility/hamstring lying curl up stretch.jpg","image_male_end":"images/Stretching - Mobility/hamstring lying curl up stretch1.jpg","video_url":"videos/Stretching - Mobility/hamstring lying curl up stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('435e399f-cfb8-42fd-b7d6-7999da515811'::uuid, 'Hamstring lying straight leg stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Lie on your back with your legs extended and your arms at your sides.\r\n2. Lift your right leg towards the ceiling, keeping it straight. Use both hands to gently hold the back of your right leg, just below the knee or higher if possible.\r\n3. Pull your right leg gently towards your torso, feeling the stretch in your hamstring. Keep your left leg extended and flat on the floor.\r\n4. Hold the stretch for 15-30 seconds, then slowly lower your right leg back to the starting position. Repeat on the left side.', E'1. Move slowly and with control to maximize the stretch and avoid any sudden movements.\r\n2. Perform the stretch on a comfortable surface, such as a yoga mat, to prevent discomfort or injury.\r\n3. Only stretch as far as is comfortable without causing pain or discomfort.', '{"image_male_start":"images/Stretching - Mobility/hamstring lying straight leg stretch.jpg","image_male_end":"images/Stretching - Mobility/hamstring lying straight leg stretch1.jpg","video_url":"videos/Stretching - Mobility/hamstring lying straight leg stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('bd63b378-b05b-42f3-9578-7ad63f707019'::uuid, 'Handstand push on chair', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by placing a sturdy chair against a wall for stability. Position yourself in front of the chair, with your back facing it.\r\n2. Place your hands on the floor slightly wider than shoulder-width apart, about a foot away from the chair. Kick up into a handstand position, with your feet resting on the seat of the chair.\r\n3. Slowly lower your head towards the floor by bending your elbows, keeping your body straight and your core engaged.\r\n4. Push through your hands to extend your arms and return to the starting handstand position. Repeat for the desired number of repetitions.', E'1. Engage your core throughout the exercise to maintain stability and prevent arching your back.\r\n2. Keep your movements slow and controlled to maximize muscle engagement and prevent injury.\r\n3. Focus on steady breathing, exhaling as you push up and inhaling as you lower down.', '{"image_male_start":"images/Shoulders/handstand push on chair .jpg","video_url":"videos/Shoulders/handstand push on chair .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('888cd497-ab06-4f3d-b37c-cb5998aa25fe'::uuid, 'Hanging knee raises', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Hang from a pull-up bar with your hands shoulder-width apart, palms facing forward or towards each other. Allow your body to hang straight with your feet off the floor.\r\n2. Engage your core and, keeping your legs together, bend your knees and lift them towards your chest.\r\n3. Raise your knees as high as comfortably possible, aiming to bring them towards your chest.\r\n4. Slowly lower your legs back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Avoid swinging your body; use controlled movements to lift and lower your legs.\r\n2. Focus on steady breathing, exhaling as you lift your knees and inhaling as you lower them.\r\n3. Ensure your grip on the bar is secure to prevent slipping.', '{"image_male_start":"images/Abdominals/hanging knee raises.jpeg","video_url":"videos/Abdominals/hanging knee raises  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f25129d8-87e5-4053-a9b5-ab4255bc8334'::uuid, 'Hanging oblique crunches', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Hang from a pull-up bar with your hands shoulder-width apart, palms facing forward or towards each other. Allow your body to hang straight with your feet off the floor.\r\n2. Engage your core and, keeping your legs together, bend your knees and lift them towards your right elbow, twisting your torso to engage your obliques.\r\n3. Raise your knees as high as comfortably possible, aiming to bring them towards your elbow.\r\n4. Slowly lower your legs back to the starting position with control. Repeat the movement, this time lifting your knees towards your left elbow. Alternate sides for the desired number of repetitions.', E'1. Avoid swinging your body; use controlled movements to lift and lower your legs.\r\n2. Focus on steady breathing, exhaling as you lift your knees and twist, and inhaling as you lower them.\r\n3. Ensure your grip on the bar is secure to prevent slipping.', '{"image_male_start":"images/Abdominals/hanging oblique crunches.jpeg","video_url":"videos/Abdominals/hanging oblique crunches .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b285793a-8387-43e9-8628-662010498518'::uuid, 'Heel touches', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your knees bent and your feet flat on the floor, hip-width apart. Position your arms along your sides with your palms facing down.\r\n2. Lift your shoulders slightly off the floor, engaging your core and keeping your neck relaxed.\r\n3. Reach your right hand towards your right heel, bending your torso to the side. Return to the center and then reach your left hand towards your left heel.\r\n4. Alternate sides in a controlled manner, maintaining the contraction in your core throughout the exercise. Repeat for the desired number of repetitions.', E'1. Move slowly and with control to maximize the effectiveness of the exercise and prevent injury.\r\n2. Focus on steady breathing, exhaling as you reach towards your heel and inhaling as you return to the center.\r\n3. Ensure your lower back remains pressed into the floor to prevent strain.', '{"image_male_start":"images/Abdominals/heel touches.jpeg","video_url":"videos/Abdominals/heel touches .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f20075a2-e420-404a-9b23-77d56419d1a9'::uuid, 'High cable kneeling crunch', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'e6b14232-455e-4a8b-91c7-e842d5b57b66'::uuid, E'1. Attach a rope handle to a high pulley on a cable machine. Kneel down facing the machine, holding the rope handles with both hands, and position them close to your head.\r\n2. Keep your back straight and engage your core muscles topull the rope down by crunching your torso towards your knees, bringing your elbows towards your thighs.\r\n3. Just before your elbows touch your thighs, return to the starting position with control, keeping the tension on the cable.\r\n4. Repeat for the desired number of repetitions.', E'1. Ensure your knees are firmly planted on the floor for stability.\r\n2. Keep your hips stable and avoid using momentum.\r\n3. Exhale as you crunch down and inhale as you return to the starting position.', '{"video_url":"videos/Abdominals/high cable kneeling crunch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c18a9e38-ee17-461c-8388-b279d2530765'::uuid, 'High knee twist', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet hip-width apart and your arms raised to shoulder height in front of you, palms facing down.\r\n2. Lift your right knee towards your left elbow while simultaneously twisting your torso to the right, engaging your core.\r\n3. Return to the starting position, then lift your left knee towards your right elbow while twisting your torso to the left.\r\n4. Alternate sides in a controlled manner, maintaining a steady rhythm. Repeat for the desired number of repetitions.', E'1. Twist your torso and lift your knee simultaneously to engage both your abs and obliques.\r\n2. Move smoothly and with control to avoid straining your back or hips.\r\n3. Ensure your movements are balanced and controlled to prevent injury.\r\n', '{"image_male_start":"images/Abdominals/high knee twist.jpeg","video_url":"videos/Abdominals/high knee twist .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ffba5639-762d-4af8-ac74-cdc29b6104af'::uuid, 'High knees', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet hip-width apart and your arms at your sides.\r\n2. Begin by lifting your right knee towards your chest as high as possible while simultaneously swinging your left arm forward.\r\n3. Quickly switch to lift your left knee towards your chest while swinging your right arm forward, mimicking a running motion.\r\n4. Continue to alternate knees rapidly, maintaining a steady rhythm and engaging your core. Repeat for the desired duration or number of repetitions.', E'1. Lift your knees as high as possible while maintaining proper form and balance.\r\n2. Move quickly but with control to maximize cardiovascular benefits and prevent injury.\r\n3. Ensure your movements are balanced and coordinated to avoid straining your muscles.\r\n', '{"image_male_start":"images/Calisthenics-Cardio-Functional/high knees.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/high knees1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/high knees.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('182e771e-93b2-43bb-a013-bd8899d575ec'::uuid, 'High plank', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin on the floor on your hands and knees. Position your hands directly under your shoulders and your knees under your hips.\r\n2. Extend your legs straight back, one at a time, coming onto the balls of your feet to form a straight line from your head to your heels. Your body should be in a high plank position.\r\n3. Engage your core, glutes, and legs to maintain a straight body line. Keep your shoulders directly over your wrists.\r\n4. Hold the plank position for the desired amount of time, maintaining proper form and steady breathing.', E'1. Keep your core engaged throughout the exercise to maintain stability and prevent sagging or arching of your back.\r\n2. Ensure your hands are positioned directly under your shoulders to support your weight evenly.\r\n3. Breathe steadily, inhaling through your nose and exhaling through your mouth to help maintain focus and endurance.\r\n', '{"image_male_start":"images/Yoga/High plank.jpeg","video_url":"videos/Yoga/High plank.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e5d652e3-5500-4435-b71e-7bc5d4d084ae'::uuid, 'High Resistance band kneeling crunch', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Attach a resistance band to a high anchor point. Kneel down facing the anchor point, holding the handles of the resistance band with both hands, bend your arms at 90 degrees to bring your hands close to your face, palms facing each other.\r\n2. Pull the resistance band down by crunching your torso towards your knees, bringing your elbows towards your thighs.\r\n3. Slowly return to the starting position with control, keeping the tension on the band. \r\n4. Repeat for the desired number of repetitions.', E'1. Ensure your knees are firmly planted on the floor for stability.\r\n2. Keep your hips stable and avoid using momentum.\r\n3. Exhale as you crunch down and inhale as you return to the starting position.', '{"image_male_start":"images/Abdominals/high resistance band kneeling crunch.jpeg","video_url":"videos/Abdominals/high resistance band kneeling crunch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7253459f-b6c1-45f1-b3e2-ff89c9ab819d'::uuid, 'Hollow hold', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your legs extended and your arms stretched overhead.\r\n2. Engage your core and lift your shoulders and legs off the floor, keeping your lower back pressed into the floor. Your body should form a slight curve with your arms and legs elevated.\r\n3. Hold this position, maintaining tension in your core and keeping your lower back flat against the floor.\r\n4. Continue to hold the position for the desired duration, then slowly lower your shoulders and legs back to the starting position.', E'1. Ensure your shoulders and legs are lifted at the same height to create a balanced position.\r\n2. Focus on steady breathing, inhaling through your nose and exhaling through your mouth to help maintain focus and endurance.\r\n3. If the full hollow hold is too challenging, you can modify the position by bending your knees or keeping your arms by your sides.\r\n4. Avoid straining your neck; keep it relaxed and in line with your spine.', '{"image_male_start":"images/Abdominals/hollow hold.jpeg","video_url":"videos/Abdominals/hollow hold .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b4c3fac3-d840-44ed-8cc1-e36d708efafe'::uuid, 'In and out squats jump bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand tall with your back straight, feet shoulder-width apart, and clasp your hands in front of your chest.\r\n2. Lower your hips, jump up and land into a squat position with your knees bent, thighs parallel to the floor, and feet placed wider than your shoulder width.\r\n3. Then lower your hips again, jump up, and land into a squat position with your knees bent, thighs parallel to the floor, and feet placed hip-width apart this time.\r\n4. Repeat by jumping in and out alternately.', E'1. Land softly on your forefeet to reduce impact on your joints.\r\n2. Ensure your knees are aligned with your toes when you squat to avoid strain.\r\n3. Move quickly but with control to maximize the effectiveness of the exercise and prevent injury.', '{"image_male_start":"images/Legs/in and out squats jump bodyweight  .jpg","video_url":"videos/Legs/in and out squats jump bodyweight  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('cfb922f9-bcea-45ad-8677-25ddd4dabcca'::uuid, 'In and out squats jump bodyweight (2)', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand tall with your back straight, feet shoulder-width apart, and clasp your hands in front of your chest.\r\n2. Lower your hips, jump up and land into a squat position with your knees bent, thighs parallel to the floor, and feet placed wider than your shoulder width.\r\n3. Then lower your hips again, jump up, and land into a squat position with your knees bent, thighs parallel to the floor, and feet placed hip-width apart this time.\r\n4. Repeat by jumping in and out alternately.', E'1. Land softly on your forefeet to reduce impact on your joints.\r\n2. Ensure your knees are aligned with your toes when you squat to avoid strain.\r\n3. Move quickly but with control to maximize the effectiveness of the exercise and prevent injury.', '{"image_male_start":"images/Legs/in and out squats jump bodyweight (2).jpg","image_male_end":"images/Legs/in and out squats jump bodyweight (2)1.jpg","video_url":"videos/Legs/in and out squats jump bodyweight (2).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6e207771-945a-4775-bed8-599566009fcb'::uuid, 'Incline bench cable fly', 'Resistance', 'strength', 'weight_reps', 'intermediate', '7c8ccea6-1ecd-4abd-a28f-2f05d0d539a5'::uuid, E'1. Set an incline bench between two cable machines with the pulleys positioned at the middle setting. Lie back on the bench with your feet flat on the floor. Grasp a handle in each hand, with your palms facing up and your arms extended to your sides.\r\n2. Keep a slight bend in your elbows and your back pressed firmly against the bench.\r\n3. Raise the handles opposite your chest in a wide arc, until your arms are level with your chest, squeezing your chest muscles at the top of the movement.\r\n4. Lower the handles back the starting position in a controlled manner. Repeat for the desired number of repetitions.', E'1. Keep a slight bend in your elbows throughout the exercise to avoid straining your joints.\r\n2. Keep your back and head pressed firmly against the bench.\r\n3. Exhale as you bring the handles up and inhale as you lower them down.', '{"image_male_start":"images/Chest/incline bench cable fly.jpg","image_male_end":"images/Chest/incline bench cable fly1.jpg","video_url":"videos/Chest/incline bench cable fly.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('66b66109-bb04-450c-b029-ebdca1feb7df'::uuid, 'Incline diamond push up on bench', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Position yourself facing a bench. Place your hands on the edge of the bench close together so that your thumbs and index fingers form a diamond shape.\r\n2. Step your feet back to extend your legs fully, keeping your body in a straight line from head to heels. Engage your core to maintain stability.\r\n3. Lower your chest towards the bench by bending your elbows, keeping them close to your body.\r\n4. Push through your hands to extend your arms and return to the starting position. Repeat for the desired number of repetitions.', E'1. Move slowly and with control to maximize muscle engagement and prevent injury.\r\n2. Focus on steady breathing, exhaling as you push up and inhaling as you lower down.\r\n3. Avoid flaring your elbows out to the sides; keep them close to your body to engage your triceps more effectively.\r\n4. Use a stable, non-slip bench to prevent any movement or slipping during the exercise.', '{"image_male_start":"images/Triceps/incline diamond push up On Bench.jpeg","video_url":"videos/Triceps/incline diamond push up On Bench.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('49ef086a-633e-40b9-9c40-de2059e46756'::uuid, 'Incline dumbbell curl', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Set an adjustable bench to a 45-degree incline and sit back against it with your feet flat on the floor. Hold a dumbbell in each hand with your arms fully extended down by your sides, palms facing forward (supinated grip).\r\n2. Engage your core and keep your elbows close to your torso. Slowly curl both dumbbells up towards your shoulders simultaneously, maintaining the supinated grip with your palms facing upward.\r\n3. Squeeze your biceps at the top of the movement, then slowly lower the dumbbells back to the starting position with control.\r\n4. Repeat for the desired number of repetitions.', E'1. Focus on a full range of motion, ensuring you fully extend your arms at the bottom of each curl.\r\n2. Maintain a slight bend in your elbows at the start to avoid locking them out.\r\n3. Keep your upper arms stationary and close to your torso to isolate the biceps effectively.', '{"video_url":"videos/Biceps/incline dumbbell curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4a1c4480-2c9f-4e9e-9c3f-a83a4e8a9962'::uuid, 'Incline lateral raises dumbbell', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Adjust an incline bench to a 45-degree angle and lie chest-first against it, with your feet firmly planted on the floor for stability.\r\n2. Hold a dumbbell in each hand with a neutral grip (palms facing each other), allowing the dumbbells to hang down towards the floor in line with your shoulders.\r\n3. Keeping your arms slightly bent at the elbows, raise the dumbbells up and out to the sides until they reach shoulder height.\r\n4. Lower the dumbbells back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Maintain a slight bend in your elbows throughout the movement to reduce joint strain.\r\n2. Keep your body stabilized against the bench to isolate your shoulder muscles.\r\n3. Use a slow and controlled motion to maximize muscle engagement.', '{"image_male_start":"images/Shoulders/incline lateral raises dumbbell.jpg","image_male_end":"images/Shoulders/incline lateral raises dumbbell1.jpg","video_url":"videos/Shoulders/incline lateral raises dumbbell.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d794066a-f9dc-4d62-9a7a-1564c9b2d77b'::uuid, 'Intermediate hip flexor and quad stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Lie on your stomach with your legs extended and your arms at your sides. Position an elastic cable around your right ankle.\r\n2. Bend your right knee to bring your foot towards your glutes, holding the elastic cable in your both hands.\r\n3. Gently pull on the cable to bring your foot closer to your glutes, feeling the stretch in your quadriceps. Hold this position for a moment.\r\n4. Extend your right leg lightly backwards, allowing the cable to provide resistance and deepen the stretch in your hip flexor and quadriceps. Repeat the movement for the desired number of repetitions, then switch to the left leg.', E'1. Focus on deep, steady breathing, inhaling as you extend your leg and exhaling as you pull your foot towards your glutes.\r\n2. If you find it difficult to reach the cable, use a longer strap or adjust the tension to ensure a comfortable stretch.\r\n3. Ensure your head and neck remain in a neutral position, looking down towards the floor to avoid strain.\r\n4. Perform the stretch on a comfortable surface, such as a yoga mat, to prevent discomfort or injury.', '{"image_male_start":"images/Stretching - Mobility/intermediate hip flexor and quad stretch.jpg","image_male_end":"images/Stretching - Mobility/intermediate hip flexor and quad stretch1.jpg","video_url":"videos/Stretching - Mobility/intermediate hip flexor and quad stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6b4388bf-6b84-4371-8f46-f171eb5e556c'::uuid, 'Inverted rows on smith machine', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '132c52b1-6336-4426-a457-c35a314038f2'::uuid, E'1. Position a bar on the smith machine at about waist height. Lie on your back underneath the bar with your legs extended and your heels on the floor.\r\n2. Grasp the bar with an overhand grip, hands slightly wider than shoulder-width apart.\r\n3. Engage your core and pull your chest towards the bar by bending your elbows, keeping your body in a straight line from head to heels.\r\n4. Lower yourself back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Focus on using your back muscles to pull yourself up, rather than your arms.\r\n2. Adjust the height of the bar or your foot position to make the exercise easier or harder as needed.\r\n3. Breathe steadily, exhaling as you pull up and inhaling as you lower yourself down.\r\n4. Ensure the bar is securely locked in place on the smith machine to prevent any movement.\r\n', '{"image_male_start":"images/Back/inverted rows on smith machine.jpg","image_male_end":"images/Back/inverted rows on smith machine1.jpg","video_url":"videos/Back/inverted rows on smith machine.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a1554d53-5fec-4469-b5ce-9c62a255d1c6'::uuid, 'Iron cross stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your arms extended out to your sides, forming a T-shape, and your legs extended straight.\r\n2. Lift your right leg towards the ceiling, keeping it straight, and then lower it across your body towards your left hand while keeping your shoulders flat on the floor.\r\n3. Allow your right leg to lower as far as comfortably possible, feeling a stretch in your lower back, glutes, and hamstrings.\r\n4. Hold the stretch for 15-30 seconds, then slowly return your right leg to the starting position. Repeat on the other side with your left leg.', E'1. Only stretch as far as is comfortable without causing pain or discomfort.\r\n2. Perform the stretch on a comfortable surface, such as a yoga mat, to prevent discomfort or injury.\r\n3. If you have limited flexibility, bend your knee slightly to reduce strain and gradually work towards straightening your leg.', '{"image_male_start":"images/Stretching - Mobility/iron cross stretch.jpg","image_male_end":"images/Stretching - Mobility/iron cross stretch1.jpg","video_url":"videos/Stretching - Mobility/iron cross stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3f1aaa4a-5d42-4fff-a2c8-598cf142474e'::uuid, 'Iso Lateral Shoulder Press Alternate Arms', 'Resistance', 'strength', 'weight_reps', 'intermediate', '1a636d29-2aec-4f45-914e-8fab15563d39'::uuid, E'1. Sit on the Iso-Lateral Shoulder Press machine, back pressed against the backrest and feet flat on the floor. Grasp the handles with both hands, palms facing forward.\r\n2. Press one handle upward by extending your arm fully while keeping the other arm stationary.\r\n3. Squeeze your shoulder muscles at the top of the movement and slowly return the handle to the starting position with control.\r\n4. Repeat with the other arm, alternating arms for the desired number of repetitions.', E'1. Keep your back pressed against the backrest throughout the exercise.\r\n2. Focus on engaging your shoulder muscles throughout the movement.\r\n3. Exhale as you press the handle upward and inhale as you return it to the starting position.', '{"image_male_start":"images/Shoulders/Iso Lateral Shoulder Press Alternate Arms.jpg","image_male_end":"images/Shoulders/Iso Lateral Shoulder Press Alternate Arms1.jpg","image_female_start":"images/Shoulders/Iso Lateral Shoulder Press Alternate Arms_Female.jpg","image_female_end":"images/Shoulders/Iso Lateral Shoulder Press Alternate Arms_Female1.jpg","video_url":"videos/Shoulders/Iso Lateral Shoulder Press Alternate Arms.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6b1c24fe-7e73-4aa0-985f-d3dbe4f6594c'::uuid, 'Iso Lateral Shoulder Press Both Arm', 'Resistance', 'strength', 'weight_reps', 'intermediate', '1a636d29-2aec-4f45-914e-8fab15563d39'::uuid, E'1. Sit on the Iso-Lateral Shoulder Press machine, back pressed against the backrest and feet flat on the floor. Grasp the handles with both hands, palms facing forward.\r\n2. Press both handles upward by extending your arms fully with control.\r\n3. Squeeze your shoulder muscles at the top of the movement and slowly return the handles to the starting position.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep your back pressed against the backrest throughout the exercise.\r\n2. Focus on engaging your shoulder muscles throughout the movement.\r\n3. Exhale as you press the handles upward and inhale as you return them to the starting position.', '{"image_male_start":"images/Shoulders/Iso Lateral Shoulder Press Both Arm_Female.jpg","image_female_start":"images/Shoulders/Iso Lateral Shoulder Press Both Arm_Female.jpg","image_female_end":"images/Shoulders/Iso Lateral Shoulder Press Both Arm_Female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9fd57677-40a2-42ed-95a0-9a2b1c2bdeb5'::uuid, 'Iso Lateral Shoulder Press Both Arms', 'Resistance', 'strength', 'weight_reps', 'intermediate', '1a636d29-2aec-4f45-914e-8fab15563d39'::uuid, E'1. Sit on the Iso-Lateral Shoulder Press machine, back pressed against the backrest and feet flat on the floor. Grasp the handles with both hands, palms facing forward.\r\n2. Press both handles upward by extending your arms fully with control.\r\n3. Squeeze your shoulder muscles at the top of the movement and slowly return the handles to the starting position.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep your back pressed against the backrest throughout the exercise.\r\n2. Focus on engaging your shoulder muscles throughout the movement.\r\n3. Exhale as you press the handles upward and inhale as you return them to the starting position.', '{"image_male_start":"images/Shoulders/Iso Lateral Shoulder Press Both Arms.jpg","image_male_end":"images/Shoulders/Iso Lateral Shoulder Press Both Arms1.jpg","video_url":"videos/Shoulders/Iso Lateral Shoulder Press Both Arms.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ccd22cb5-0586-49d1-add1-5c55b7c7fab2'::uuid, 'Iso Lateral Shoulder Press Single Arm', 'Resistance', 'strength', 'weight_reps', 'intermediate', '1a636d29-2aec-4f45-914e-8fab15563d39'::uuid, E'1. Sit on the Iso-Lateral Shoulder Press machine, back pressed against the backrest and feet flat on the floor. Grasp the handles with both hands, palms facing forward.\r\n2. Press the right handle upward by extending your arm fully while keeping the other arm stationary.\r\n3. Squeeze your shoulder muscles at the top of the movement and slowly return the handle to the starting position with control.\r\n4. Repeat with the same arm for the desired number of repetitions.', E'1. Keep your back pressed against the backrest throughout the exercise.\r\n2. Focus on engaging your shoulder muscles throughout the movement.\r\n3. Exhale as you press the handle upward and inhale as you return it to the starting position.', '{"image_male_start":"images/Shoulders/Iso Lateral Shoulder Press Single Arm.jpg","image_male_end":"images/Shoulders/Iso Lateral Shoulder Press Single Arm1.jpg","image_female_start":"images/Shoulders/Iso Lateral Shoulder Press Single Arm_Female.jpg","image_female_end":"images/Shoulders/Iso Lateral Shoulder Press Single Arm_Female1.jpg","video_url":"videos/Shoulders/Iso Lateral Shoulder Press Single Arm.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6a889223-3c48-457c-a4be-f6f92943b509'::uuid, 'Jack knives', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie flat on your back with your legs extended and your arms stretched on your sides.\r\n2. Simultaneously lift your upper body and legs towards each other, reaching your hands towards your feet. Engage your core to lift both your torso and legs.\r\n3. Try to touch your hands to your feet at the top of the movement, forming a "V" shape with your body.\r\n4. Slowly lower your upper body and legs back to the starting position with control. Repeat for the desired number of repetitions.', E'1. If the full movement is too challenging, modify by bending your knees slightly.\r\n2. Focus on steady breathing, exhaling as you lift your body and inhaling as you lower it.\r\n3. Ensure your lower back remains pressed into the floor during the movement to prevent strain.', '{"image_male_start":"images/Abdominals/jack knives.jpeg","video_url":"videos/Abdominals/jack knives .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('06c4346b-5ff9-43a7-97b9-e631941b47f9'::uuid, 'Jump Rope alternating foot', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'ecbf4b6a-ecec-4ea8-a7d2-4e389d03d2e1'::uuid, E'1. Stand with your feet together, holding a jump rope with the handles in each hand. Position the rope behind you, ready to swing it over your head.\r\n2. Swing the rope over your head and, as it passes under your feet, lift one foot off the floor, quickly followed by the other foot, allowing the rope to pass beneath both feet in succession.\r\n3. Continue to alternate feet with each jump, lifting one foot after the other, maintaining a steady rhythm and keeping your jumps low and controlled.\r\n4. Repeat the movement for the desired duration or number of repetitions, ensuring a smooth and continuous motion.', E'1. Focus on quick, controlled movements, keeping your jumps low to minimize impact on your joints.\r\n2. Use your wrists to swing the rope, rather than your arms, to maintain a smooth and efficient motion.\r\n3. Wear supportive footwear to protect your feet and ankles during the exercise.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Jump Rope alternating foot.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Jump Rope alternating foot1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Jump Rope alternating foot.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8967fa9f-b047-4c35-a8b5-f263c328c913'::uuid, 'Jump Rope basic jump', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'ecbf4b6a-ecec-4ea8-a7d2-4e389d03d2e1'::uuid, E'1. Stand with your feet together, holding a jump rope with the handles in each hand. Position the rope behind you, ready to swing it over your head.\r\n2. Swing the rope over your head and, as it passes under your feet, jump with both feet simultaneously, keeping your jumps low to the floor.\r\n3. Land softly on your forefeet and immediately swing the rope over your head again for the next jump.\r\n4. Continue jumping at a steady rhythm, maintaining a smooth and continuous motion for the desired duration or number of repetitions.', E'1. Focus on quick, controlled movements, keeping your jumps low to minimize impact on your joints.\r\n2. Use your wrists to swing the rope, rather than your arms, to maintain a smooth and efficient motion.\r\n3. Wear supportive footwear to protect your feet and ankles during the exercise.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Jump Rope basic jump.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Jump Rope basic jump1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Jump Rope basic jump.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('fc13db5a-74d8-4d38-9879-db31d253c8f0'::uuid, 'Jump Rope double bounce', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'ecbf4b6a-ecec-4ea8-a7d2-4e389d03d2e1'::uuid, E'1. Stand with your feet together, holding a jump rope with the handles in each hand. Position the rope behind you, ready to swing it over your head.\r\n2. Swing the rope over your head and, as it passes under your feet, perform a small jump, landing on your forefeet.\r\n3. Immediately perform a second smaller bounce while keeping the rope in motion and preparing for the next swing.\r\n4. Continue with the double bounce rhythm, maintaining a smooth and controlled motion for the desired duration or number of repetitions.', E'1. Focus on quick, controlled movements, keeping your jumps low to minimize impact on your joints.\r\n2. Use your wrists to swing the rope, rather than your arms, to maintain a smooth and efficient motion.\r\n3. Wear supportive footwear to protect your feet and ankles during the exercise.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Jump Rope double bounce.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Jump Rope double bounce1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Jump Rope double bounce.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('23e11c2d-1f30-41d3-af29-e8ad1d49193b'::uuid, 'Jump Rope face pull', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'ecbf4b6a-ecec-4ea8-a7d2-4e389d03d2e1'::uuid, E'1. Loop the jump rope over a vertical bar or similar stable structure, ensuring the rope is at about hip height. Stand facing the bar with your feet shoulder-width apart, holding the handles of the jump rope with both hands.\r\n2. Step back slightly to create tension in the rope, keeping your core engaged and your back straight.\r\n3. Pull the rope towards your face by bending your elbows and bringing your hands towards your ears, engaging your upper back and shoulder muscles.\r\n4. Extend your arms back out to the starting position with control. Repeat the movement for the desired number of repetitions.', E'1. Focus on squeezing your shoulder blades together as you pull the rope towards your face to maximize muscle engagement.\r\n2. Move slowly  with control and avoid using momentum to prevent injury.\r\n3. Breathe steadily, exhaling as you pull the rope towards your face and inhaling as you extend your arms back out.\r\n4. Ensure the vertical bar or structure is stable and can support the tension in the rope to prevent slipping or injury.', '{"image_male_start":"images/Shoulders/Jump Rope face pull.jpg","image_male_end":"images/Shoulders/Jump Rope face pull1.jpg","video_url":"videos/Shoulders/Jump Rope face pull.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a07bb710-1f45-4778-90ae-8d896817e8ea'::uuid, 'Jump Rope row', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'ecbf4b6a-ecec-4ea8-a7d2-4e389d03d2e1'::uuid, E'1. Loop the jump rope over a vertical bar or similar stable structure, ensuring the rope is at about hip height. Stand facing the bar with your feet shoulder-width apart, holding the handles of the jump rope with both hands.\r\n2. Step back slightly to create tension in the rope, keeping your core engaged and your back straight.\r\n3. Pull the rope towards your torso by bending your elbows and bringing your hands towards your sides, engaging your upper back and shoulder muscles.\r\n4. Extend your arms back out to the starting position with control. Repeat the movement for the desired number of repetitions.', E'1. Focus on squeezing your shoulder blades together as you pull the rope towards your torso to maximize muscle engagement.\r\n2. Ensure the vertical bar or structure is stable and can support the tension in the rope to prevent slipping or injury.\r\n3. Breathe steadily, exhaling as you pull the rope towards your torso and inhaling as you extend your arms back out.', '{"image_male_start":"images/Back/Jump Rope row female.jpg","video_url":"videos/Back/Jump Rope row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('bb0cd140-c7b7-40fe-a4b0-d84bb49221c0'::uuid, 'Jump squats bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your arms at your sides.\r\n2. Lower your body into a squat position by bending your knees and pushing your hips back, keeping your chest up and your core engaged.\r\n3. Explosively jump up, extending your legs fully and swinging your arms up for momentum.\r\n4. Land softly back into the squat position with your knees bent and your hips pushed back. Repeat for the desired number of repetitions.', E'1. Land softly on your forefeet to reduce impact on your joints.\r\n2. Ensure your knees are aligned with your toes when you squat to avoid strain.\r\n3. Move quickly but with control to maximize the effectiveness of the exercise and prevent injury.', '{"image_male_start":"images/Legs/Jump Squats bodyweight  .jpg","video_url":"videos/Legs/Jump Squats bodyweight  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('03417f59-7d79-4639-80d7-3cfee3fa6c9f'::uuid, 'Jumping jack', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet together and your arms at your sides.\r\n2. Jump your feet out to the sides while simultaneously raising your arms overhead, forming an "X" shape with your body.\r\n3. Quickly jump back to the starting position with your feet together and your arms at your sides.\r\n4. Repeat the movement for the desired duration or number of repetitions, maintaining a steady rhythm.', E'1. Maintain a slight bend in your knees throughout the exercise to absorb impact and reduce strain on your joints.\r\n2. Keep your movements light and quick to enhance cardiovascular benefits.\r\n3. Engage your shoulders and back muscles when raising your arms to ensure full range of motion.\r\n4. Keep your gaze forward and your head in a neutral position to maintain alignment.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/jumping jack  .jpg","video_url":"videos/Calisthenics-Cardio-Functional/jumping jack  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6735b109-1d9a-440e-ad31-b01a3649d7df'::uuid, 'Kettlebell bulgarian split squat right', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '7352a8b5-30da-44d7-9cae-8a031f5d2aed'::uuid, E'1. Stand facing away from a bench, holding a kettlebell in each hand with arms hanging by your sides. Place your right foot on the bench behind you.\r\n2. Keep your left foot firmly planted on the floor and lower your body by bending your left knee, descending until your left thigh is parallel to the floor.\r\n3. Press through your left heel to return to the starting position, straightening your leg.\r\n4. Repeat for the desired number of repetitions.', E'1. Ensure your front knee does not extend past your toes during the descent.\r\n2. Focus on keeping your torso upright; avoid leaning forward excessively.\r\n3. Exhale as you push up to the starting position and inhale as you lower your body.', '{"image_male_start":"images/Legs/kettlebell bulgarian split squat right  .jpg","video_url":"videos/Legs/kettlebell bulgarian split squat right  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7fd55b15-b714-41de-b803-9dab26446918'::uuid, 'Kettlebell bulgarian split squat right side view', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '7352a8b5-30da-44d7-9cae-8a031f5d2aed'::uuid, E'1. Stand facing away from a bench, holding a kettlebell in each hand with arms hanging by your sides. Place your left foot on the bench behind you.\r\n2. Keep your right foot firmly planted on the floor and lower your body by bending your right knee, descending until your right thigh is parallel to the floor.\r\n3. Press through your right heel to return to the starting position, straightening your leg.\r\n4. Repeat for the desired number of repetitions.', E'1. Ensure your front knee does not extend past your toes during the descent.\r\n2. Focus on keeping your torso upright; avoid leaning forward excessively.\r\n3. Exhale as you push up to the starting position and inhale as you lower your body.', '{"image_male_start":"images/Legs/kettlebell bulgarian split squat right side view  .jpg","video_url":"videos/Legs/kettlebell bulgarian split squat right side view  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0b8001bc-6885-4533-a3b1-6528ad96d69b'::uuid, 'Kettlebell half kneeling shoulder press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '7352a8b5-30da-44d7-9cae-8a031f5d2aed'::uuid, E'1. Begin in a half-kneeling position with your right knee on the floor and your left foot flat on the floor in front of you. Hold a kettlebell in your right hand, racked at shoulder height with your elbow bent, facing the floor, and close to your body.\r\n2. Press the kettlebell overhead by extending your right arm fully, keeping your wrist straight and in line with your shoulder.\r\n3. Lower the kettlebell back to the starting position with control.\r\n4. Repeat for the desired number of repetitions.', E'1. Ensure your knee and hip are aligned, maintaining a 90-degree angle in both legs.\r\n2. Press the kettlebell straight up, avoiding any forward or backward motion.\r\n3. Exhale as you press the kettlebell overhead and inhale as you lower it back down.', '{"image_male_start":"images/Shoulders/kettlebell half kneeling shoulder press .jpg","video_url":"videos/Shoulders/kettlebell half kneeling shoulder press .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b3b4305a-f5da-43f2-b86b-9ec58ad465bf'::uuid, 'Kettlebell kneeling one arm shoulder press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '7352a8b5-30da-44d7-9cae-8a031f5d2aed'::uuid, E'1. Begin in a kneeling position on both knees with your torso upright. Hold a kettlebell in your right hand at shoulder height, with your elbow bent, facing the floor, and close to your body.\r\n2. Press the kettlebell overhead by extending your right arm fully, keeping your wrist straight and aligned with your shoulder.\r\n3. Lower the kettlebell back to the starting position.\r\n4. Repeat for the desired number of repetitions.', E'1. Maintain a neutral spine throughout the movement.\r\n2. Press the kettlebell straight up, avoiding any forward or backward motion.\r\n3. Exhale as you press the kettlebell overhead and inhale as you lower it back down.', '{"image_male_start":"images/Shoulders/kettlebell kneeling one arm shoulder press .jpg","video_url":"videos/Shoulders/kettlebell kneeling one arm shoulder press .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6852427f-215c-4ec2-bc5a-a48578ad5342'::uuid, 'Kettlebell seesaw press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '7352a8b5-30da-44d7-9cae-8a031f5d2aed'::uuid, E'1. Begin in a standing position with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder height. Your elbows should be bent, facing the floor and your palms facing inward.\r\n2. Press the kettlebell in your right hand overhead by extending your right arm fully while slightly leaning your torso to your left side.\r\n3. Lower the right kettlebell back to shoulder height and then press the kettlebell in your left hand overhead by extending your left arm fully and slightly leaning your torso to the right side.\r\n4. Continue alternating the presses for the desired number of repetitions.\r\n', E'1. Press each kettlebell straight up, avoiding any forward or backward motion.\r\n2. Exhale as you press each kettlebell overhead and inhale as you lower it back down.\r\n3. Ensure your wrists stay straight and aligned with your forearms to prevent strain.', '{"image_male_start":"images/Shoulders/Kettlebell Seesaw Press.jpg","image_male_end":"images/Shoulders/Kettlebell Seesaw Press1.jpg","video_url":"videos/Shoulders/Kettlebell Seesaw Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b4a0e124-1b7a-4d28-8ba5-59a4d8369ee7'::uuid, 'Kettlebell single arm clean and press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '7352a8b5-30da-44d7-9cae-8a031f5d2aed'::uuid, E'1. Stand with your feet shoulder-width apart and the kettlebell placed on the floor between your feet. Bend your knees and hinge at your hips to grab the kettlebell with your right hand.\r\n2. Explosively extend your hips and knees to lift the kettlebell off the floor and swing it up to shoulder height. As the kettlebell rises, rotate your wrist to catch it in a rack position with your elbow bent and close to your body.\r\n3. Press the kettlebell overhead by extending your right arm fully, keeping your wrist straight and aligned with your shoulder.\r\n4. Lower the kettlebell back to the rack position with control, then return it to the starting position on the floor. Repeat for the desired number of repetitions, then switch to the left hand.', E'1. Use your hips and legs to generate power for the clean.\r\n2. Use an appropriate weight to maintain proper form and control.\r\n3. Keep your wrist straight and aligned with your forearm during the press.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Kettlebell Single Arm Clean and Press.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Kettlebell Single Arm Clean and Press1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Kettlebell Single Arm Clean and Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('eee05944-f391-4a3e-8e4d-2148e1f08d0a'::uuid, 'Kettlebell single leg glute bridge pullover', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '7352a8b5-30da-44d7-9cae-8a031f5d2aed'::uuid, E'1. Lie on your back with your knees bent and feet flat on the floor, holding a kettlebell with both hands extended straight on the floor. Extend your right leg upwards bent at 90 degrees.\r\n2. Press through your left heel to lift your hips off the floor, forming a straight line from your shoulders to your left knee. Simultaneously, extend the kettlebell overhead with both arms, keeping a slight bend in your elbows.\r\n3. Lower your hips back to the floor while bringing the kettlebell back to the starting position.\r\n4. Repeat for the desired number of repetitions, then switch to your left leg extended and perform the same motion.', E'1. Lower the kettlebell and your hips in a controlled manner to prevent any sudden movements or loss of balance.\r\n2. Focus on squeezing your glutes at the top of the bridge for maximum activation.\r\n3. Inhale as you lower your hips and the kettlebell, and exhale as you lift them.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Kettlebell Single Leg Glute Bridge Pullover.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Kettlebell Single Leg Glute Bridge Pullover1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Kettlebell Single Leg Glute Bridge Pullover.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('23cffe3a-0d1c-4e5c-a07d-a5aabef92133'::uuid, 'Kettlebell situp press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '7352a8b5-30da-44d7-9cae-8a031f5d2aed'::uuid, E'1. Begin by lying on your back with your legs straight on the floor, holding a kettlebell with both hands at your chest.\r\n2. Lift your upper body off the floor until it is vertical to the floor, and then press the kettlebell overhead by extending your arms.\r\n3. Lower the kettlebell back close to your chest.\r\n4. Slowly lower your upper body back to the starting. Repeat for the desired number of repetitions', E'1. Use a controlled motion to lift and lower your upper body, avoiding any jerky movements.\r\n2. Engage your core throughout the movement to maintain control and stability.\r\n3. Choose a moderate weight for the kettlebell to ensure proper form and control.', '{"image_male_start":"images/Abdominals/Kettlebell situp press.jpeg","video_url":"videos/Abdominals/Kettlebell situp press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a8451566-7c26-47e8-b4a1-2282ed3a914d'::uuid, 'Kettlebell split squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '7352a8b5-30da-44d7-9cae-8a031f5d2aed'::uuid, E'1. Stand with your feet hip-width apart, holding a kettlebell in each hand with your arms hanging by your sides. Take a step forward with your right foot and position your left foot back, standing on the ball of your left foot.\r\n2. Bend both knees to lower your body into a split squat. Your back knee should hover just above the floor, and your front thigh should be parallel to the floor.\r\n3. Push through your right heel to return to the starting position, fully extending both legs.\r\n4. Repeat for the desired number of repetitions, then switch legs and perform the same number of repetitions on the other side.', E'1. Keep your chest up and your back straight throughout the movement.\r\n2. Ensure your front knee stays aligned with your ankle, not extending past your toes.\r\n3. Keep your feet hip-width apart to maintain proper alignment and balance.', '{"image_male_start":"images/Legs/Kettlebell Split squat.jpg","image_male_end":"images/Legs/Kettlebell Split squat1.jpg","video_url":"videos/Legs/Kettlebell Split squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('13a61793-36f0-4d6b-8800-f4706331a8f2'::uuid, 'Kettlebell squats', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '7352a8b5-30da-44d7-9cae-8a031f5d2aed'::uuid, E'1. Stand with your feet shoulder-width apart, holding a kettlebell with each hand hanging by your sides.\r\n2. Lower your body into a squat by bending your knees and pushing your hips back as if sitting in a chair.\r\n3. Continue lowering yourself until your thighs are parallel to the floor, making sure your knees track over your toes.\r\n4. Push through your heels to stand back up to the starting position, fully extending your legs.', E'1. Ensure your knees stay in line with your toes to prevent any inward collapse.\r\n2. Inhale as you lower into the squat and exhale as you push back up to standing.\r\n3. Focus on pressing through your heels to activate your glutes and quadriceps.', '{"image_male_start":"images/Legs/kettlebell squats  .jpg","video_url":"videos/Legs/kettlebell squats  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('883f6262-d733-4d2c-b53d-073269077888'::uuid, 'Kettlebell Standing Bottoms-up One Arm Shoulder Press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '7352a8b5-30da-44d7-9cae-8a031f5d2aed'::uuid, E'1. Stand with your feet shoulder-width apart, holding a kettlebell in your right hand with the bell facing up (bottoms-up position). Place your  left hand on your hip.\r\n2. Press the kettlebell overhead by extending your elbow, keeping your wrist straight.\r\n3. Once your arm is fully extended overhead, pause for a second to fully activate the shoulder muscles.\r\n4. Slowly lower the kettlebell back to the starting position with control, keeping the bottoms-up orientation throughout the movement. Repeat for the desired number of repetitions.', E'1. Maintain a strong grip on the kettlebell to keep it stable in the bottoms-up position.\r\n2. Start with a lighter weight to master the balance and control required for the bottoms-up position.\r\n3. Avoid locking your elbow completely at the top of the press to protect your joint.', '{"image_male_start":"images/Shoulders/Kettlebell Standing Bottoms-up One Arm Shoulder Press.jpg","image_male_end":"images/Shoulders/Kettlebell Standing Bottoms-up One Arm Shoulder Press1.jpg","video_url":"videos/Shoulders/Kettlebell Standing Bottoms-up One Arm Shoulder Press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('304adab7-99ef-43ba-aacf-cf3290362d1a'::uuid, 'Kettlebell strict press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '7352a8b5-30da-44d7-9cae-8a031f5d2aed'::uuid, E'1. Stand with your feet shoulder-width apart, holding a kettlebell in your right hand, close to the front of your shoulder. The kettlebell should rest against the back of your wrist, with your palm facing inward and your elbow close to your body facing down.\r\n2. Press the kettlebell directly overhead by extending your arm upward, keeping your wrist straight.\r\n3. Lower the kettlebell back to the starting position with control, returning it to shoulder height.\r\n4. Repeat for the desired number of repetitions, then switch to the left hand and perform the exercise on the other side.', E'1. Maintain a neutral wrist position to avoid strain.\r\n2. Avoid using momentum; focus on a slow, controlled press.\r\n3. Exhale as you press the kettlebell up and inhale as you lower it.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Kettlebell strict press.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Kettlebell strict press1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Kettlebell strict press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('421a415e-9d72-476d-94b3-e51b7e4d399a'::uuid, 'Kettlebell suitcase squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '7352a8b5-30da-44d7-9cae-8a031f5d2aed'::uuid, E'1. Stand with your feet shoulder-width apart, holding a kettlebell in your right hand next to your right thigh, with your arm extended. Your left arm can hang by your side or be extended in front of you for counterbalance.\r\n2. Push your hips back as if sitting into a chair to lower your body into a squat until your thighs are parallel to the floor.\r\n3. Push through your heels to stand back up to the starting position, maintaining a straight back and engaged core. \r\n4. Repeat for the desired number of repetitions, then switch the kettlebell to your left hand and perform the exercise on the other side.', E'1. Keep your back straight and avoid leaning to one side.\r\n2. Use a weight that allows you to maintain proper form throughout the exercise.\r\n3. Ensure your knees track over your toes to prevent knee strain.', '{"image_male_start":"images/Legs/Kettlebell Suitcase Squat.jpg","image_male_end":"images/Legs/Kettlebell Suitcase Squat1.jpg","video_url":"videos/Legs/Kettlebell Suitcase Squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c3b24070-4f57-4e30-ad68-acfd290dd4fc'::uuid, 'Kettlebell sumo deadlift', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '7352a8b5-30da-44d7-9cae-8a031f5d2aed'::uuid, E'1. Place a kettlebell on the floor between your feet. Stand with your feet wider than shoulder-width apart and your toes pointed slightly outward. \r\n2. Hinge at your hips and bend your knees to lower your body, reaching down to grasp the kettlebell handle with both hands, keeping your back straight and chest up.\r\n3. Push through your heels to lift the kettlebell off the floor, extending your hips and knees simultaneously.\r\n4. Lower the kettlebell back to the starting position. Repeat for the desired number of repetitions.', E'1. Ensure your knees track over your toes to prevent knee strain.\r\n2. Maintain a wide stance with toes pointed slightly outward.\r\n3. Use a weight that allows you to maintain proper form throughout the exercise.', '{"image_male_start":"images/Back/Kettlebell Sumo Deadlift.jpg","image_male_end":"images/Back/Kettlebell Sumo Deadlift1.jpg","video_url":"videos/Back/Kettlebell Sumo Deadlift.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3f53a382-e124-4d2c-aff3-a0ca56ded009'::uuid, 'Kettlebell Sumo Deadlift with High Pull', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '7352a8b5-30da-44d7-9cae-8a031f5d2aed'::uuid, E'1. Place a kettlebell on the floor between your feet. Stand with your feet wider than shoulder-width apart and your toes pointed slightly outward. \r\n2. Hinge at your hips and bend your knees to lower your body, reaching down to grasp the kettlebell handle with both hands, keeping your back straight and chest up.\r\n3. Push through your heels to lift the kettlebell off the floor, extending your hips and knees simultaneously. As you reach the standing position, explosively pull the kettlebell upward towards your chin by bending your elbows and keeping them pointed outward.\r\n4. Lower the kettlebell back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Use a weight that allows you to maintain proper form throughout the exercise.\r\n2. Push through your heels to maximize power and stability.\r\n3. Ensure your knees track over your toes to prevent knee strain.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Kettlebell Sumo Deadlift with High Pull.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Kettlebell Sumo Deadlift with High Pull1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Kettlebell Sumo Deadlift with High Pull.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('fc3cad6e-4adc-4d8b-9eba-0209beeb65cb'::uuid, 'Kettlebell sumo squat', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '7352a8b5-30da-44d7-9cae-8a031f5d2aed'::uuid, E'1. Stand with your feet wider than shoulder-width apart, toes pointed slightly outward. Hold a kettlebell with both hands close to your chest.\r\n2. Hinge at your hips while bending your knees to lower your body into a squat.\r\n3. Lower yourself until your thighs are parallel to the floor or slightly below.\r\n4. Push through your heels to rise back to the starting position, fully extending your hips and knees. Repeat for the desired number of repetitions.', E'1. Ensure your knees track over your toes to prevent knee strain.\r\n2. Exhale as you rise from the squat, inhale as you lower into it.\r\n3. Maintain a wide stance with toes pointed slightly outward.', '{"image_male_start":"images/Legs/Kettlebell Sumo Squat.jpg","image_male_end":"images/Legs/Kettlebell Sumo Squat1.jpg","video_url":"videos/Legs/Kettlebell Sumo Squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('498d6c60-d809-47a2-bc0f-5ed00d3e5e04'::uuid, 'Kettlebell sumo squat (version 2)', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '7352a8b5-30da-44d7-9cae-8a031f5d2aed'::uuid, E'1. Stand with your feet wider than shoulder-width apart, toes pointed slightly outward. Hold a kettlebell with both hands, letting it hang down between your legs.\r\n2. Hinge at your hips while bending your knees to lower your body into a squat.\r\n3. Lower yourself until your thighs are parallel to the floor or slightly below.\r\n4. Push through your heels to rise back to the starting position, fully extending your hips and knees. Repeat for the desired number of repetitions.', E'1. Ensure your knees track over your toes to prevent knee strain.\r\n2. Exhale as you rise from the squat, inhale as you lower into it.\r\n3. Maintain a wide stance with toes pointed slightly outward.', '{"image_male_start":"images/Legs/Kettlebell Sumo Squat (VERSION 2).jpg","image_male_end":"images/Legs/Kettlebell Sumo Squat (VERSION 2)1.jpg","video_url":"videos/Legs/Kettlebell Sumo Squat (VERSION 2).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c08f356c-40ca-4b70-91b0-3d2094b9d10b'::uuid, 'Kettlebell sumo squat off stepbox', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '7352a8b5-30da-44d7-9cae-8a031f5d2aed'::uuid, E'1. Stand between two stepboxes with a wide stance, toes pointed slightly outward. Hold a kettlebell with both hands, letting it hang between your legs.\r\n2. Lower yourself into a wide squat by bending your knees and pushing your hips back. Lower until your thighs are parallel to the floor.\r\n3. Push through your heels to stand back up, squeezing your glutes at the top of the movement.\r\n4. Repeat the squat for the desired number of repetitions.', E'1. Ensure your knees track over your toes and do not collapse inward during the squat.\r\n2. Keep your back straight and chest up to avoid leaning forward.\r\n3. Use a weight that challenges your strength but allows you to maintain proper form.', '{"image_male_start":"images/Legs/Kettlebell Sumo Squat off Stepbox.jpg","image_male_end":"images/Legs/Kettlebell Sumo Squat off Stepbox1.jpg","video_url":"videos/Legs/Kettlebell Sumo Squat off Stepbox.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4426062b-b43e-4548-a2d4-ff7b372ac95c'::uuid, 'Kettlebell swing', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '7352a8b5-30da-44d7-9cae-8a031f5d2aed'::uuid, E'1. Stand with your feet shoulder-width apart, toes pointing slightly outward. Place a kettlebell on the floor between your feet. Bend at your hips and knees to reach forward and grab the kettlebell with both hands, keeping your back straight and chest up.\r\n2. Hinge at your hips to swing the kettlebell back between your legs, allowing a slight bend in your knees.\r\n3. Drive through your hips, extending them forcefully to swing the kettlebell forward and up to shoulder height. Allow the momentum to carry the kettlebell upwards, keeping your arms straight but not locked.\r\n4. As the kettlebell begins to descend, hinge at your hips again to let it swing back between your legs, preparing for the next repetition. Repeat for the desired number of repetitions.', E'1. Use the power from your hips, not your arms, to generate the swing.\r\n2. Keep your back straight and avoid rounding your shoulders.\r\n3. Exhale as you swing the kettlebell up, inhale as it swings back down.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Kettlebell Swing.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Kettlebell Swing1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Kettlebell Swing.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('fbed0068-0a99-4787-ae7d-53db1330f487'::uuid, 'Kettlebell swing (Version 2)', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '7352a8b5-30da-44d7-9cae-8a031f5d2aed'::uuid, E'1. Stand with your feet shoulder-width apart, toes pointing slightly outward. Place a kettlebell vertically on the floor between your feet. Bend at your hips and knees to reach forward and grab the kettlebell with both hands, interlocking your fingers.\r\n2. Hinge at your hips to swing the kettlebell back between your legs, allowing a slight bend in your knees.\r\n3. Drive through your hips, extending them forcefully to swing the kettlebell forward and up to shoulder height. Allow the momentum to carry the kettlebell upwards, keeping your arms straight but not locked.\r\n4. As the kettlebell begins to descend, hinge at your hips again to let it swing back between your legs, preparing for the next repetition. Repeat for the desired number of repetitions.', E'1. Use the power from your hips, not your arms, to generate the swing.\r\n2. Keep your back straight and avoid rounding your shoulders.\r\n3. Exhale as you swing the kettlebell up, inhale as it swings back down.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Kettlebell Swing (Version 2).jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Kettlebell Swing (Version 2)1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Kettlebell Swing (Version 2).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6cd69c53-979e-401b-aed8-02600b853cb6'::uuid, 'Kettlebell thruster', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '7352a8b5-30da-44d7-9cae-8a031f5d2aed'::uuid, E'1. Begin by standing with your feet shoulder-width apart, holding a kettlebell in each hand at shoulder level, palms facing inward. Keep your elbows close to your.\r\n2. Lower into a squat by bending your hips and knees until your thighs are parallel to the floor.\r\n3. Push through your heels to stand back up while simultaneously pressing the kettlebells overhead. Fully extend your arms at the top of the movement.\r\n4. Lower the kettlebells back to shoulder level as you prepare for the next repetition. Repeat for the desired number of repetitions.', E'1. Exhale as you press the kettlebells overhead, inhale as you lower into the squat.\r\n2. Choose an appropriate weight to maintain control throughout the exercise.\r\n3. Keep your wrists straight and aligned with your forearms.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Kettlebell Thruster.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Kettlebell Thruster1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Kettlebell Thruster.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e21266af-88fc-466e-8a66-b3e08ea029ea'::uuid, 'Kettlebells sumo deadlift with high pull', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '7352a8b5-30da-44d7-9cae-8a031f5d2aed'::uuid, E'1. Place two kettlebells on the floor between your feet. Stand with your feet wider than shoulder-width apart and your toes pointed slightly outward. \r\n2. Hinge at your hips and bend your knees to lower your body, reaching down to grasp the kettlebell handles, one in each hand, keeping your back straight and chest up.\r\n3. Push through your heels to lift the kettlebells off the floor, extending your hips and knees simultaneously. As you reach the standing position, pull the kettlebells upward towards your chin by bending your elbows and keeping them pointed outward.\r\n4. Lower the kettlebells back to the starting position. Repeat for the desired number of repetitions.', E'1. Keep your back straight and avoid rounding your shoulders.\r\n2. Exhale as you lift the kettlebell and perform the high pull, inhale as you lower it.\r\n3. Push through your heels to maximize power and stability.', '{"image_male_start":"images/Back/Kettlebells Sumo Deadlift with High Pull.jpg","image_male_end":"images/Back/Kettlebells Sumo Deadlift with High Pull1.jpg","video_url":"videos/Back/Kettlebells Sumo Deadlift with High Pull.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0f8fddf6-926f-4848-bd1d-8483a4918bd6'::uuid, 'Knee to chest stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Stand upright with your feet hip-width apart and your arms at your sides.\r\n2. Lift your right knee towards your chest, wrapping your hands around your knee to gently pull your knee closer to your chest.\r\n3. Hold the stretch for 15-30 seconds, feeling the stretch. Keep your left leg straight and maintain your balance.\r\n4. Release your right knee and lower your leg back to the starting position. Repeat the stretch with your left knee. Alternate sides for the desired number of repetitions.', E'1. Use a gentle but firm grip to avoid pulling too hard and causing strain.\r\n2. Engage your core to maintain balance and stability throughout the stretch.\r\n3. Move slowly and with control to maximize the effectiveness of the stretch and avoid any sudden movements.', '{"image_male_start":"images/Stretching - Mobility/knee to chest stretch  .jpg","video_url":"videos/Stretching - Mobility/knee to chest stretch  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('bcf35041-791c-41e7-a84d-81a2412447ed'::uuid, 'Kneeling hip flexor stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Begin in a kneeling position with your right knee on the floor and your left foot in front of you, forming a 90-degree angle with your left knee.\r\n2. Place your hands on your hips or on your left thigh for support. Engage your core and keep your back straight.\r\n3. Gently push your hips forward, feeling the stretch in your right hip flexor. Hold the stretch for 15-30 seconds.\r\n4. Return to the starting position and switch legs, performing the stretch with your left knee on the floor and your right foot in front. Repeat for the desired number of repetitions.', E'1. Ensure your front knee is directly above your ankle to avoid putting unnecessary strain on your knee joint.\r\n2. Maintain an upright posture with your shoulders relaxed and your chest open.\r\n3. Move slowly and with control to maximize the effectiveness of the stretch and avoid any sudden movements.\r\n', '{"image_male_start":"images/Stretching - Mobility/kneeling hip flexor stretch  .jpg","video_url":"videos/Stretching - Mobility/kneeling hip flexor stretch  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ea51aee8-cfda-4d32-89fe-edc48a372619'::uuid, 'Kneeling lat floor stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a tabletop position on the floor with your hands directly under your shoulders and your knees under your hips.\r\n2. Extend your right arm forward on the floor, palm facing up, while keeping your left hand in place.\r\n3. Bend your left elbow to lower your chest towards the floor, feeling the stretch in your lat muscles and upper back. Keep your head relaxed and look down at the floor.\r\n4. Hold the stretch for 15-30 seconds, breathing deeply and steadily. Slowly return to the starting position and repeat on the other side by extending your left arm forward and bending your right elbow.', E'1. Ensure your extended arm is fully extended to get the most effective stretch in your lats and upper back.\r\n2. Perform the stretch on a comfortable surface, such as a yoga mat, to prevent discomfort or injury.\r\n3. Relax your shoulders and neck to avoid tension in these areas.', '{"image_male_start":"images/Stretching - Mobility/kneeling lat floor stretch.jpg","image_male_end":"images/Stretching - Mobility/kneeling lat floor stretch1.jpg","video_url":"videos/Stretching - Mobility/kneeling lat floor stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('765d513e-bb9b-4a0c-87ee-a1d90a51c0d5'::uuid, 'Kneeling leg curl machine', 'Resistance', 'strength', 'weight_reps', 'intermediate', '8239c9cf-c829-4bdb-9d7d-53776a47155a'::uuid, E'1. Kneel on the leg curl machine with one leg bent on the knee rest behind you and the other leg extended and secured under the pad.\r\n2. Hold onto the handles for stability and keep your back straight.\r\n3. Curl the extended leg by bending your knee and pulling your heel towards your glutes, squeezing your hamstrings at the top of the movement.\r\n4. Slowly return your leg to the starting position with control. Repeat for the desired number of repetitions, then switch legs.', E'1. Keep your back straight and avoid arching or rounding your spine.\r\n2. Focus on engaging your hamstrings throughout the movement.\r\n3. Exhale as you curl your leg up and inhale as you lower it back down.', '{"image_male_start":"images/Legs/kneeling leg curl machine  .jpg","video_url":"videos/Legs/kneeling leg curl machine  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('429553a3-63cd-4614-9231-c31dbd43a6bd'::uuid, 'Kneeling squat jumps bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a kneeling position on the floor with your knees hip-width apart and your toes pointing behind you. Sit back on your heels with your arms at your sides.\r\n2. Engage your core and glutes, then swing your arms forward and upward to generate momentum.\r\n3. Explosively jump up from your knees, bringing your feet forward to land in a squat position with your feet shoulder-width apart and your knees bent.\r\n4. Stand up from the squat position and then return to the starting kneeling position. Repeat for the desired number of repetitions.', E'1. Use your arms to generate momentum and assist with the jump.\r\n2. Land softly on your forefeet to reduce impact on your joints.\r\n3. Ensure your knees are aligned with your toes when you land in the squat position to avoid strain.', '{"image_male_start":"images/Legs/Kneeling Squat Jumps bodyweight  .jpg","video_url":"videos/Legs/Kneeling Squat Jumps bodyweight  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1b7ab539-a61f-4874-acfe-d26755d36ccf'::uuid, 'Kneeling wrist flexor stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Begin in a tabletop position on the floor with your hands directly under your shoulders and your knees under your hips.\r\n2. Rotate your hands so that your fingers are pointing towards your knees, palms flat on the floor.\r\n3. Slowly shift your weight back towards your heels to increase the stretch in your wrists and forearms, keeping your palms flat on the floor.\r\n4. Hold the stretch for 15-30 seconds, breathing deeply and steadily. Release the stretch by shifting your weight forward and gently lifting your hands off the floor. Repeat for the desired number of repetitions.', E'1. Keep your palms flat on the floor and your fingers pointing towards your knees to maximize the stretch in your wrist flexors.\r\n2. Move slowly and with control to avoid any sudden movements that could cause strain.\r\n3. If the stretch is too intense, reduce the angle by bringing your hands closer to your knees.', '{"image_male_start":"images/Stretching - Mobility/kneeling wrist flexor stretch  .jpg","video_url":"videos/Stretching - Mobility/kneeling wrist flexor stretch  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('19c7a523-a570-4e74-aecc-a32be7f68585'::uuid, 'Landmine chest press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Begin by standing with your feet shoulder-width apart, holding the end of a barbell with the right hand at chest level. The other end of the barbell should be anchored securely in a landmine attachment or corner.\r\n2. Press the barbell forward and slightly upward until your arm is fully extended.\r\n3. Squeeze your chest muscles at the top of the movement.\r\n4. Slowly lower the barbell back to the starting position at chest level. Repeat for the desired number of repetitions.', E'1. Keep your back straight and avoid arching it during the press.\r\n2. Exhale as you press the barbell forward and inhale as you lower it back.\r\n3. Focus on using your chest muscles to press the barbell.', '{"image_male_start":"images/Chest/landmine chest  press.jpg","video_url":"videos/Chest/landmine chest  press  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('58ab0c2e-2e92-4006-ba46-df65ff20527c'::uuid, 'Landmine row', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Begin by standing with your feet shoulder-width apart and knees slightly bent. Position yourself so that the end of a barbell, anchored in a landmine attachment or a secure corner, is between your feet.\r\n2. Bend at the hips and knees to lean forward and grab the barbell with both hands using a v handle.\r\n3. Pull the barbell towards your chest by squeezing your shoulder blades together and bending your elbows.\r\n4. Lower the barbell back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Exhale as you pull the barbell towards you and inhale as you lower it back.\r\n2. Ensure your feet are firmly planted and your stance is stable.\r\n3. Focus on squeezing your shoulder blades together to engage your middle back muscles.', '{"image_male_start":"images/Back/Landmine row.jpg","image_male_end":"images/Back/Landmine row1.jpg","video_url":"videos/Back/Landmine row.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2a5044a9-a958-4d78-85c2-a0c34d7a670e'::uuid, 'Lat pull down close grip', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd8a6a67e-71db-4542-9dd7-a185a3e773af'::uuid, E'1. Sit at the lat pulldown machine with your feet flat on the floor and knees secured under the pads. Grasp the bar with both hands just closer than shoulder-width apart, and your arms fully extended above you.\r\n2. Pull the bar down towards your upper chest by bending your elbows and squeezing your shoulder blades together, keeping your back straight.\r\n3. Hold the contraction for a second, then slowly return the bar to the starting position with control, fully extending your arms.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep your back straight and avoid leaning backward excessively.\r\n2. Focus on engaging your back muscles throughout the movement.\r\n3. Exhale as you pull the bar down and inhale as you return to the starting position.', '{"image_male_start":"images/Back/lat pull down close grip .jpg","video_url":"videos/Back/lat pull down close grip .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('94a062df-dff2-4768-93e5-c6f3183a6929'::uuid, 'Lat pull down normal grip', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd8a6a67e-71db-4542-9dd7-a185a3e773af'::uuid, E'1. Sit at the lat pulldown machine with your feet flat on the floor and knees secured under the pads. Grasp the bar with both hands, just wider than shoulder-width apart, and your arms fully extended above you.\r\n2. Pull the bar down towards your upper chest by bending your elbows and squeezing your shoulder blades together, keeping your back straight.\r\n3. Hold the contraction for a second, then slowly return the bar to the starting position with control, fully extending your arms.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep your back straight and avoid leaning backward excessively.\r\n2. Focus on engaging your back muscles throughout the movement.\r\n3. Exhale as you pull the bar down and inhale as you return to the starting position.', '{"image_male_start":"images/Back/lat pull down normal grip .jpg","video_url":"videos/Back/lat pull down normal grip .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9f5019fe-45e3-47f8-9c1c-7d3e35c40fc3'::uuid, 'Lat pull down wide grip', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd8a6a67e-71db-4542-9dd7-a185a3e773af'::uuid, E'1. Sit at the lat pulldown machine with your feet flat on the floor and knees secured under the pads. Grasp the bar with both hands, wider than shoulder-width apart, and your arms fully extended above you.\r\n2. Pull the bar down towards your upper chest by bending your elbows and squeezing your shoulder blades together, keeping your back straight.\r\n3. Hold the contraction for a second, then slowly return the bar to the starting position with control, fully extending your arms.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep your back straight and avoid leaning backward excessively.\r\n2. Focus on engaging your back muscles throughout the movement.\r\n3. Exhale as you pull the bar down and inhale as you return to the starting position.', '{"image_male_start":"images/Back/lat pull down wide grip .jpg","video_url":"videos/Back/lat pull down wide grip .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c730fbb3-3901-4e0a-8001-8ea70826562d'::uuid, 'Lateral raise bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand upright with your feet shoulder-width apart and your arms at your sides.\r\n2. Raise your arms out to the sides until they are parallel to the floor, keeping your elbows slightly bent and your palms facing down.\r\n3. Hold the position for a second, then slowly lower your arms back to your sides with control.\r\n4. Repeat the movement for the desired number of repetitions, maintaining a steady and controlled pace.', E'1. Avoid lifting your shoulders; focus on using your deltoids to raise your arms.\r\n2. Move slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Breathe steadily, exhaling as you raise your arms and inhaling as you lower them.\r\n4. Ensure your elbows remain slightly bent to reduce strain on your joints.', '{"image_male_start":"images/Shoulders/lateral raise bodyweight .jpg","video_url":"videos/Shoulders/lateral raise bodyweight .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('31f29058-aae2-4d87-820e-94bf3a34faab'::uuid, 'Lateral raise to shoulder press Resistance band cable', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart, placing the resistance band under both feet. Hold the handles of the resistance band with your palms facing inward and your arms at your sides.\r\n2. Perform a lateral raise by lifting the handles out to the sides until your arms are parallel to the floor, keeping a slight bend in your elbows.\r\n3. Once your arms are parallel to the floor, rotate your wrists so your palms face forward, bend your arms at 90 degrees up and press the handles overhead until your arms are fully extended.\r\n4. Lower the handles back to shoulder height, rotate your wrists back to the starting position, and then lower your arms back to your sides. Repeat for the desired number of repetitions.', E'1. Keep your back straight and avoid using momentum.\r\n2. Use a lighter resistance band if needed to ensure proper form and gradually increase the resistance as you get stronger.\r\n3. Exhale as you lift the handles and press them overhead, and inhale as you lower them back down.', '{"image_male_start":"images/Shoulders/lateral raise to shoulder press resistance band cable .jpg","video_url":"videos/Shoulders/lateral raise to shoulder press resistance band cable .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4d425925-1cfa-49f9-8c28-6978f4d04f08'::uuid, 'Lateral raises dumbbell', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by standing with your feet shoulder-width apart, holding a dumbbell in each hand at your sides with your palms facing your body.\r\n2. Raise both arms out to the sides until they reach shoulder height, maintaining a slight bend in your elbows.\r\n3. Pause briefly at the top of the movement, ensuring your arms are parallel to the floor.\r\n4. Lower the dumbbells back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Do not raise the dumbbells higher than shoulder height to prevent shoulder strain.\r\n2. Maintain a slight bend in your elbows throughout the exercise.\r\n3. Keep your wrists straight and aligned with your forearms.', '{"image_male_start":"images/Shoulders/lateral raises dumbbell.jpg","image_male_end":"images/Shoulders/lateral raises dumbbell1.jpg","video_url":"videos/Shoulders/lateral raises dumbbell.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b951ae93-7048-4482-89fc-511826810923'::uuid, 'lateral raises dumbbell seated with swing', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on a bench with your feet flat on the floor, holding a dumbbell in each hand with your arms hanging by your sides and palms facing your body. Keep your torso leaning towards the floor.\r\n2. Begin raising your torso while swinging both arms out to the sides until they reach shoulder height, using a controlled momentum and bending your elbows at 90 degrees as you raise up.\r\n3. Pause briefly at the top of the movement, ensuring your arms are parallel and your torso vertical to the floor.\r\n4. Lower the dumbbells back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Do not raise the dumbbells higher than shoulder height to prevent shoulder strain.\r\n2. Use a controlled swing to lift the weights; avoid excessive momentum.\r\n3. Exhale as you lift the dumbbells and inhale as you lower them.', '{"video_url":"videos/Shoulders/Lateral raises dumbbell seated with swing.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a07be2f6-b5c8-4237-9115-ca51fe0bb259'::uuid, 'Lateral raises on cable machine', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your right side facing the cable machine, feet shoulder-width apart. Attach a handle to the low pulley and grasp the handle with your left hand, palm facing inward.\r\n2. Raise the handle out to your side until your left arm is parallel to the floor, keeping a slight bend in your elbow.\r\n3. Slowly lower the handle back to the starting position with control. \r\n4.Repeat for the desired number of repetitions, then switch sides to work the opposite arm.', E'1. Keep your back straight and avoid using momentum.\r\n2. Focus on engaging your shoulder muscles throughout the movement.\r\n3. Exhale as you raise the handle and inhale as you lower it back down.', '{"image_male_start":"images/Shoulders/lateral raises on cable machine.jpg","image_male_end":"images/Shoulders/lateral raises on cable machine1.jpg","video_url":"videos/Shoulders/lateral raises on cable machine.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('55048852-4b39-4d15-9b15-8cbdd9375e87'::uuid, 'Leaning Dumbbell Lateral Raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand next to a lifting cage, holding a dumbbell in your right hand. Grasp the lifting cage bar for support with your left hand and lean your body to the opposite side by extending your arm.\r\n2. With your right arm hanging down, raise the dumbbell out to your side until your arm is parallel to the floor, keeping a slight bend in your elbow and your palm facing down.\r\n3. Lower the dumbbell back to the starting position with control. Complete the desired number of repetitions.', E'1. Avoid using momentum; lift the dumbbell with control.\r\n2. Exhale as you lift the dumbbell and inhale as you lower it.\r\n3. Maintain a slight bend in your elbow throughout the exercise.', '{"image_male_start":"images/Shoulders/Leaning dumbbell lateral raise.jpg","image_male_end":"images/Shoulders/Leaning dumbbell lateral raise1.jpg","video_url":"videos/Shoulders/Leaning dumbbell lateral raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5c057f87-9a00-42f9-ae79-5658f82ac660'::uuid, 'Leg extended stretch on bench', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Begin by sitting on the edge of a bench with both legs bent and your feet flat on the floor. Keep your back straight and your core engaged.\r\n2. Extend your right leg forward until it is parallel to the floor, keeping your leg straight.\r\n3. Hold the stretch for 15-30 seconds, feeling the stretch in your hamstring and lower back.\r\n4. Slowly bring your right leg back to the starting position with both feet flat on the floor. Repeat the stretch with your left leg extended. Alternate sides for the desired number of repetitions.', E'1. Ensure your extended leg is straight and parallel to the floor to get the most effective stretch.\r\n2. Perform the stretch on a stable, non-slip surface to prevent discomfort or injury.\r\n3. If you find it difficult to hold your leg up, you can use your hands to support your thigh.', '{"image_male_start":"images/Stretching - Mobility/Leg extended stretch on bench.jpg","image_male_end":"images/Stretching - Mobility/Leg extended stretch on bench1.jpg","video_url":"videos/Stretching - Mobility/Leg extended stretch on bench.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b4c20837-04f0-4392-b4de-91f15cde8129'::uuid, 'Leg lift circles', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your legs extended and your arms at your sides, palms facing down.\r\n2. Lift both legs off the floor, about a foot above the floor, keeping your legs straight and your core engaged.\r\n3. Begin to draw small circles in the air with both legs moving together in a controlled and steady motion. Perform the circles in one direction for a set number of repetitions.\r\n4. Switch directions and draw circles with both legs in the opposite direction for the same number of repetitions. Lower your legs back to the starting position.', E'1. Keep your legs as straight as possible to maximize the stretch and engagement in your hip flexors and quadriceps.\r\n2. Perform the exercise on a comfortable, non-slip surface to prevent discomfort or injury.\r\n3. If you find it difficult to keep your legs straight, you can start with smaller circles and gradually increase the size as you build strength and flexibility.', '{"image_male_start":"images/Abdominals/leg lift circles.jpeg","video_url":"videos/Abdominals/leg lift circles .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0084a8e2-a194-4e36-ab96-352486209267'::uuid, 'Leg press machine close stance', 'Resistance', 'strength', 'weight_reps', 'intermediate', '28deca28-3c3f-422f-9707-032a51268ee5'::uuid, E'1. Sit on the leg press machine and position your feet close together in the center of the foot platform, keeping your feet flat and parallel. Adjust the seat so that your knees are bent at about a 90-degree angle.\r\n2. Hold the handles on the sides of the seat for stability. Keep your back pressed against the backrest and your core engaged.\r\n3. Press through your heels to extend your legs, pushing the platform away from you until your legs are fully extended but not locked at the knees.\r\n4. Slowly return to the starting position by bending your knees with control. Repeat for the desired number of repetitions.', E'1. Keep your back pressed against the backrest throughout the exercise.\r\n2. Ensure both feet remain flat on the platform for better stability and muscle balance.\r\n3. Exhale as you press the platform away and inhale as you return to the starting position.', '{"image_male_start":"images/Legs/leg press machine close stance  .jpg","video_url":"videos/Legs/leg press machine close stance  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8280a750-f61a-4672-9076-b12fa33af818'::uuid, 'Leg press machine normal stance', 'Resistance', 'strength', 'weight_reps', 'intermediate', '28deca28-3c3f-422f-9707-032a51268ee5'::uuid, E'1. Sit on the leg press machine and position your feet at shoulder-width, in the center of the foot platform, keeping your feet flat and parallel. Adjust the seat so that your knees are bent at about a 90-degree angle.\r\n2. Hold the handles on the sides of the seat for stability. Keep your back pressed against the backrest and your core engaged.\r\n3. Press through your heels to extend your legs, pushing the platform away from you until your legs are fully extended but not locked at the knees.\r\n4. Slowly return to the starting position by bending your knees with control. Repeat for the desired number of repetitions.', E'1. Keep your back pressed against the backrest throughout the exercise.\r\n2. Ensure both feet remain flat on the platform for better stability and muscle balance.\r\n3. Exhale as you press the platform away and inhale as you return to the starting position.', '{"image_male_start":"images/Legs/Leg press machine normal stance.jpg","image_male_end":"images/Legs/Leg press machine normal stance1.jpg","image_female_start":"images/Legs/Leg press machine normal stance_Female.jpg","image_female_end":"images/Legs/Leg press machine normal stance_Female1.jpg","video_url":"videos/Legs/Leg press machine normal stance.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('317bd48e-473a-4e47-aa02-abe12b64529b'::uuid, 'Leg press wide high stance', 'Resistance', 'strength', 'weight_reps', 'intermediate', '28deca28-3c3f-422f-9707-032a51268ee5'::uuid, E'1. Sit on the leg press machine and position your feet just wider than shoulder-width, high in the center of the foot platform, keeping your feet flat and parallel. Adjust the seat so that your knees are bent at about a 90-degree angle.\r\n2. Hold the handles on the sides of the seat for stability. Keep your back pressed against the backrest and your core engaged.\r\n3. Press through your heels to extend your legs, pushing the platform away from you until your legs are fully extended but not locked at the knees.\r\n4. Slowly return to the starting position by bending your knees with control. Repeat for the desired number of repetitions.', E'1. Keep your back pressed against the backrest throughout the exercise.\r\n2. Ensure both feet remain flat on the platform for better stability and muscle balance.\r\n3. Exhale as you press the platform away and inhale as you return to the starting position.', '{"image_male_start":"images/Legs/leg press wide high stance  .jpg","video_url":"videos/Legs/leg press wide high stance  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c05e1871-a0d4-4bcf-af05-a4879462128a'::uuid, 'Leg press wide high stance behind view', 'Resistance', 'strength', 'weight_reps', 'intermediate', '28deca28-3c3f-422f-9707-032a51268ee5'::uuid, E'1. Sit on the leg press machine and position your feet just wider than shoulder-width, high in the center of the foot platform, keeping your feet flat and parallel. Adjust the seat so that your knees are bent at about a 90-degree angle.\r\n2. Hold the handles on the sides of the seat for stability. Keep your back pressed against the backrest and your core engaged.\r\n3. Press through your heels to extend your legs, pushing the platform away from you until your legs are fully extended but not locked at the knees.\r\n4. Slowly return to the starting position by bending your knees with control. Repeat for the desired number of repetitions.', E'1. Keep your back pressed against the backrest throughout the exercise.\r\n2. Ensure both feet remain flat on the platform for better stability and muscle balance.\r\n3. Exhale as you press the platform away and inhale as you return to the starting position.', '{"image_male_start":"images/Legs/leg press wide high stance behind view  .jpg","video_url":"videos/Legs/leg press wide high stance behind view  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a5cb39c7-8f2f-4faf-8cec-eb35e2a53abc'::uuid, 'Leg raises (straight legs)', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Position yourself on a captain''s chair, supporting your body weight with your forearms on the arm pads and your back against the backrest. Let your legs hang straight down.\r\n2. Engage your core and keep your legs straight. Lift both legs together while keeping them straight.\r\n3. Raise your legs until they are parallel to the floor or as high as you can comfortably go, maintaining control throughout the movement.\r\n4. Slowly lower your legs back down to the starting position without swinging. Repeat for the desired number of repetitions.', E'1. Avoid swinging your legs or using momentum; focus on controlled movements to maximize muscle engagement and prevent injury.\r\n2. Breathe steadily, exhaling as you lift your legs and inhaling as you lower them.\r\n3. Ensure your arms and shoulders remain stable to support your body weight effectively.', '{"image_male_start":"images/Abdominals/Leg raises (straight legs).jpeg","video_url":"videos/Abdominals/Leg raises (straight legs).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0e0b1119-ec44-4d0a-bb8f-63cbcd6136f5'::uuid, 'Legs hand reach spine stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by sitting on the floor with your legs extended straight together in front of you. Keep your back straight and your core engaged.\r\n2. Slowly bend forward at the hips, reaching your hands towards your feet. Keep your legs straight and your toes pointing up.\r\n3. Continue to reach forward, aiming to touch your toes or go as far as your flexibility allows. Allow your head and neck to relax as you stretch.\r\n4. Hold the stretch for 15-30 seconds, breathing deeply and steadily.\r\n', E'1. Allow your head and neck to relax completely to maximize the stretch in your spine.\r\n2. Perform the stretch on a comfortable, non-slip surface to prevent slipping or discomfort.\r\n3. If you find it difficult to reach your toes, use a yoga strap or towel around your feet to assist.', '{"image_male_start":"images/Stretching - Mobility/Legs hand reach spine stretch.jpg","image_male_end":"images/Stretching - Mobility/Legs hand reach spine stretch1.jpg","video_url":"videos/Stretching - Mobility/Legs hand reach spine stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('16d2110d-0d06-4546-9024-08a30297fba5'::uuid, 'Long arm crunches', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie flat on your back with your knees bent and your feet flat on the floor, hip-width apart. Extend your arms straight in line with your head, keeping them close to your ears, and hands crossed over each other.\r\n2. Engage your core and lift your upper body off the floor, with your arms following your torso line, until it forms a 45-degree angle with the floor.\r\n3. Hold the top position for a moment, squeezing your abdominal muscles.\r\n4. Slowly lower your body back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep your arms straight and aligned with your ears to ensure proper form and avoid straining your neck.\r\n2. Press your lower back firmly into the floor throughout the exercise to prevent lower back strain.\r\n3. Use a comfortable, non-slip exercise mat to provide cushioning and prevent slipping during the movement.', '{"image_male_start":"images/Abdominals/long arm crunches.jpeg","video_url":"videos/Abdominals/long arm crunches .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f7b0d43f-e8cd-44e6-b2c9-f9cc8c9dc26a'::uuid, 'Low Cable Overhead Flyes', 'Resistance', 'strength', 'weight_reps', 'intermediate', '7c8ccea6-1ecd-4abd-a28f-2f05d0d539a5'::uuid, E'1. Stand in the center of a cable machine with the pulleys set at the lowest position. Grasp the handles with each hand, palms facing up, and take a step forward to create tension in the cables.\r\n2. Lean lightly forward and position your feet shoulder-width apart, keeping your back straight and your arms extended slightly behind you.\r\n3. Raise the handles up and together in a wide arc, bringing them to meet above your head, while keeping a slight bend in your elbows.\r\n4. Slowly lower your arms back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep your back straight and avoid using momentum.\r\n2. Focus on squeezing your shoulder muscles at the top of the movement.\r\n3. Exhale as you raise the handles and inhale as you lower them back down.', '{"image_male_start":"images/Shoulders/Low Cable Overhead Flyes.jpg","image_male_end":"images/Shoulders/Low Cable Overhead Flyes1.jpg","video_url":"videos/Shoulders/Low Cable Overhead Flyes.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b87dc95b-1260-466c-8e4c-20546e94944f'::uuid, 'Low Resistance band lying bicep curl', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Attach the middle of the resistance band to a low anchor point in front of you. Lie on a bench with your feet flat on the floor, holding a handle in each hand with your palms facing up and your arms extended straight by your sides.\r\n2. Curl the handles towards your shoulders by bending your elbows, keeping your upper arms stationary.\r\n3. Slowly return to the starting position with control, fully extending your arms. \r\n4. Repeat for the desired number of repetitions.', E'1. Keep your back flat on the bench and avoid arching your spine.\r\n2. Focus on engaging your biceps throughout the movement.\r\n3. Exhale as you curl the handles up and inhale as you lower them back down.', '{"image_male_start":"images/Biceps/low resistance band lying bicep curl.jpeg","video_url":"videos/Biceps/low resistance band lying bicep curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('73f92f86-55a6-4c61-9bdc-a78825fefa07'::uuid, 'Low Resistance band lying bicep curl half repetition', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Attach the middle of the resistance band to a low anchor point in front of you. Lie on a bench with your feet flat on the floor, holding a handle in each hand with your palms facing up and your arms extended straight by your sides.\r\n2. Curl the handles halfway towards your shoulders by bending your elbows until your forearms are parallel to the floor, keeping your upper arms stationary.\r\n3. Slowly return to the starting position with control, fully extending your arms. \r\n4. Repeat for the desired number of repetitions.', E'1. Keep your back flat on the bench and avoid arching your spine.\r\n2. Focus on engaging your biceps throughout the movement.\r\n3. Exhale as you curl the handles up and inhale as you lower them back down.', '{"video_url":"videos/Biceps/low resistance band lying bicep curl half repetition.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b032377a-d8fc-4410-81ec-e2fa09e7853b'::uuid, 'Lunge front kick', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand upright with your feet hip-width apart and your arms at your sides.\r\n2. Lift your right leg to perform a front kick, extending your leg straight out in front of you.\r\n3. As you bring your right leg back down, step it behind you into a lunge position, lowering your hips until your left thigh is parallel to the floor and your right knee nearly touches the floor.\r\n4. Push through your left heel to stand back up, returning to the starting position. Repeat the movement on the same side or alternate legs for the desired number of repetitions.', E'1. Ensure your front knee is aligned with your ankle during the lunge to avoid strain.\r\n2. Perform the front kick with control, avoiding any jerky movements to prevent injury.\r\n3. Focus on steady breathing, exhaling as you perform the front kick and inhaling as you lower into the lunge.', '{"image_male_start":"images/Legs/lunge front kick  .jpg","video_url":"videos/Legs/lunge front kick  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c5f48978-ba60-41b1-a94b-bd16bd77791e'::uuid, 'Lunge pulses bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand upright with your feet hip-width apart. Step your right foot forward into a lunge position, lowering your hips until your right thigh is parallel to the floor and your left knee nearly touches the floor.\r\n2. From the lunge position, perform small pulses by slightly raising and lowering your hips in a controlled manner. \r\n3. Continue pulsing for the desired number of repetitions or duration, keeping your core engaged and maintaining balance.\r\n4. Return to the starting position by pushing through your right heel and repeat the exercise on the opposite leg.', E'1. Ensure your front knee is aligned with your ankle and does not extend past your toes to avoid strain.\r\n2. Use a controlled motion and avoid bouncing to maintain muscle tension and effectiveness.\r\n3. Perform the pulses with control, avoiding any jerky movements to prevent injury.', '{"image_male_start":"images/Legs/lunge pulses bodyweight.jpg","image_male_end":"images/Legs/lunge pulses bodyweight1.jpg","video_url":"videos/Legs/lunge pulses bodyweight.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9bb1c7ba-642d-4a47-9a6d-6dfeb2a0f5e8'::uuid, 'Lunge reverse with Resistance band', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart, placing the middle of the resistance band under your left foot. Hold the handles of the resistance band at shoulder height with your elbows bent and facing the floor.\r\n2. Step your right leg back into a reverse lunge, bending both knees to lower your right knee towards the floor while keeping your left knee aligned with your ankle.\r\n3. Push through your left heel to return to the starting position, bringing your right leg forward.\r\n4. Repeat for the desired number of repetitions, then switch sides to work the other leg.', E'1. Exhale as you push back up to the starting position and inhale as you lower into the lunge.\r\n2. Focus on engaging your glutes and quadriceps throughout the movement.\r\n3. Ensure your front knee does not extend past your toes to avoid joint strain.', '{"image_male_start":"images/Legs/lunge reverse with resistance band  .jpg","video_url":"videos/Legs/lunge reverse with resistance band  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('336afd7a-097d-42c4-a1d0-134adbdd7058'::uuid, 'Lunge rotation left and right bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand upright with your feet hip-width apart and your arms bent at your sides, hands close to your torso.\r\n2. Step your right foot forward into a lunge position, lowering your hips until your right thigh is parallel to the floor and your left knee nearly touches the floor.\r\n3. Rotate your torso to the right, bringing your arms to the right side, then rotate your torso to the left, bringing your arms to the left side.\r\n4. Return your torso to the center and push through your right heel to return to the starting position. Repeat the movement on the opposite leg. Alternate sides for the desired number of repetitions.', E'1. Ensure your front knee is aligned with your ankle and does not extend past your toes to avoid strain.\r\n2. Keep your back straight and your chest lifted to maintain proper posture.\r\n3. Perform the rotations with control, avoiding any jerky movements to prevent injury.', '{"image_male_start":"images/Legs/lunge rotation left and right bodyweight.jpg","image_male_end":"images/Legs/lunge rotation left and right bodyweight1.jpg","video_url":"videos/Legs/lunge rotation left and right bodyweight.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0419b6b2-d29d-433c-a59e-616432397dc0'::uuid, 'Lunge to knee drive left bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand upright with your feet hip-width apart and your arms at your sides.\r\n2. Step your left foot back into a lunge position, lowering your hips until your right thigh is parallel to the floor and your left knee nearly touches the floor.\r\n3. Push through your right heel to stand back up, simultaneously driving your left knee up towards your chest.\r\n4. Return your left leg to the starting position and repeat for the desired number of repetitions. Switch sides and repeat the movement with your right leg stepping back.', E'1. Ensure your front knee is aligned with your ankle and does not extend past your toes to avoid strain.\r\n2. Perform the knee drive with control, avoiding any jerky movements to prevent injury.\r\n3. Focus on steady breathing, exhaling as you drive your knee up and inhaling as you lower into the lunge.', '{"image_male_start":"images/Legs/Lunge to Knee Drive left bodyweight  .jpg","video_url":"videos/Legs/Lunge to Knee Drive left bodyweight  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9c9f12b0-5313-4222-9f4f-5585da091760'::uuid, 'Lunge to knee drive right bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand upright with your feet hip-width apart and your arms at your sides.\r\n2. Step your right foot back into a lunge position, lowering your hips until your left thigh is parallel to the floor and your right knee nearly touches the floor.\r\n3. Push through your left heel to stand back up, simultaneously driving your right knee up towards your chest.\r\n4. Return your right leg to the starting position and repeat for the desired number of repetitions. Switch sides and repeat the movement with your left leg stepping back.', E'1. Ensure your front knee is aligned with your ankle and does not extend past your toes to avoid strain.\r\n2. Perform the knee drive with control, avoiding any jerky movements to prevent injury.\r\n3. Focus on steady breathing, exhaling as you drive your knee up and inhaling as you lower into the lunge.', '{"image_male_start":"images/Legs/Lunge to Knee Drive right bodyweight  .jpg","video_url":"videos/Legs/Lunge to Knee Drive right bodyweight  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6463146c-fcb1-4be5-9808-f86f3ce612ab'::uuid, 'lunges alternate leg with pause bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand upright with your feet hip-width apart and your arms at your sides.\r\n2. Step your right foot forward into a lunge position, lowering your hips until your right thigh is parallel to the floor and your left knee nearly touches the floor. Pause for a moment in this position.\r\n3. Push through your right heel to return to the starting position, then step your left foot forward into a lunge position, lowering your hips until your left thigh is parallel to the floor and your right knee nearly touches the floor. Pause for a moment in this position.\r\n4. Push through your left heel to return to the starting position. Alternate legs for the desired number of repetitions.', E'1. Ensure your front knee is aligned with your ankle and does not extend past your toes to avoid strain.\r\n2. Perform each lunge with control, pausing briefly to enhance muscle engagement.\r\n3. Focus on steady breathing, exhaling as you push back to the starting position and inhaling as you step forward into the lunge.', '{"image_male_start":"images/Legs/lunges alternate leg with pause bodyweight  .jpg","video_url":"videos/Legs/lunges alternate leg with pause bodyweight  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0fbabbd1-7191-4b8b-a5e5-bf6be9360b19'::uuid, 'Lunges same leg side view bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand upright with your feet hip-width apart and your arms at your sides.\r\n2. Step your right foot forward into a lunge position, lowering your hips until your right thigh is parallel to the floor and your left knee nearly touches the floor. Pause for a moment in this position.\r\n3. Push through your right heel to return to the starting position.\r\n4. Repeat the lunge with your right leg for the desired number of repetitions before switching to your left leg.', E'1. Focus on steady breathing, exhaling as you push back to the starting position and inhaling as you step forward into the lunge.\r\n2. Keep your back straight and your chest lifted to maintain proper posture.\r\n3. Use a controlled motion when bringing your leg back to the starting position to maintain balance.', '{"image_male_start":"images/Legs/lunges same leg side view bodyweight.jpg","image_male_end":"images/Legs/lunges same leg side view bodyweight1.jpg","video_url":"videos/Legs/lunges same leg side view bodyweight.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('59cf8ef1-dbeb-496e-8afb-efdd7a3e8a02'::uuid, 'Lunging straight leg calf stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Stand upright with your feet hip-width apart and your arms at your sides.\r\n2. Step your right foot back into a lunge position, keeping your right leg straight and your heel on the floor. Bend your left knee slightly, keeping your left foot flat on the floor.\r\n3. Lean forward slightly, pressing your hips downward and feeling the stretch in your right calf. Hold this position for 15-30 seconds.\r\n4. Return to the starting position and switch legs, stepping your left foot back and repeating the stretch.', E'1. Ensure your back leg remains straight and your heel stays on the floor to maximize the stretch in your calf.\r\n2. Keep your front knee aligned with your ankle to avoid unnecessary strain on your joints.\r\n3. Perform the stretch on a stable, non-slip surface to prevent slipping or discomfort.', '{"image_male_start":"images/Stretching - Mobility/lunging straight leg calf stretch.jpg","image_male_end":"images/Stretching - Mobility/lunging straight leg calf stretch1.jpg","video_url":"videos/Stretching - Mobility/lunging straight leg calf stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4f021ab0-a2b5-4792-957e-1717d5dfe233'::uuid, 'lying (prone) abdominal stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Begin by lying face down on the floor with your legs extended straight behind you and your hands placed under your shoulders, palms flat on the floor.\r\n2. Slowly press your hands into the floor to lift your chest upward, extending your spine. Keep your hips and legs relaxed on the floor.\r\n3. Continue to lift your chest until you feel a comfortable stretch in your abdomen and lower back. Hold this position for 15-30 seconds, keeping your elbows slightly bent.\r\n4. Slowly lower your chest back down to the floor and return to the starting position. Repeat for the desired number of repetitions.', E'1. Avoid locking your elbows; keep them slightly bent to prevent strain on your joints.\r\n2. Breathe deeply and steadily, inhaling as you lift your chest and exhaling as you hold the stretch.\r\n3. Perform the stretch on a comfortable surface, such as a yoga mat, to prevent discomfort or injury.', '{"image_male_start":"images/Stretching - Mobility/lying (prone) abdominal stretch.jpg","image_male_end":"images/Stretching - Mobility/lying (prone) abdominal stretch1.jpg","video_url":"videos/Stretching - Mobility/lying (prone) abdominal stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c2588efd-ce1b-48bb-bb89-b6595e122434'::uuid, 'Lying abs Resistance band', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Lie on your back with your knees bent and feet flat on the floor. Attach the resistance band to a low anchor point behind your head and hold the handles with both hands, keeping your arms bent and handles close to your head.\r\n2. Curl your upper body, bringing your elbows towards your knees while lifting your back off the floor. \r\n3. Slowly lower your upper body back to the starting position with control. \r\n4. Repeat for the desired number of repetitions.', E'1. Exhale as you curl your torso up and inhale as you lower it back down.\r\n2. Keep your feet flat on the floor for better stability.\r\n3. Focus on engaging your abdominal muscles throughout the movement.', '{"image_male_start":"images/Abdominals/lying abs resistance band.jpeg","video_url":"videos/Abdominals/lying abs resistance band .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c795f697-004e-475a-86d1-658a59933c4d'::uuid, 'Lying back extension', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by lying face down on the floor with your legs extended straight behind you and your hands placed behind your head, elbows out to the sides.\r\n2. Engage your core and glutes, then lift your upper torso off the floor, keeping your neck in a neutral position and your lower body relaxed on the floor.\r\n3. Hold the top position for a moment, squeezing your lower back muscles.\r\n4. Slowly lower your upper torso back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep your neck in a neutral position to avoid straining it.\r\n2. Perform the exercise on a comfortable, non-slip surface to prevent discomfort or injury.\r\n3. If you find it challenging to lift your upper torso, you can start with smaller movements and gradually increase the range of motion as you build strength.', '{"image_male_start":"images/Back/lying back extension .jpg","video_url":"videos/Back/lying back extension .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8609693e-8a77-4d9a-b17b-2fd5849d282b'::uuid, 'Lying bench external shoulder rotation', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back on a bench with your arms extended out to the sides, your elbows bent at 90 degrees, and your forearms hanging off the sides of the bench, perpendicular to the floor in line with your head.\r\n2. Rotate your shoulders to lift your forearms upward until they are vertical to the floor, maintaining the 90-degree angle at your elbows throughout the movement.\r\n3. Slowly lower your forearms back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep your core engaged and your back flat against the bench to maintain stability.\r\n2. Move slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Keep your elbows fixed at a 90-degree angle throughout the movement to isolate the shoulder rotation.', '{"image_male_start":"images/Shoulders/lying bench external shoulder rotation.jpg","image_male_end":"images/Shoulders/lying bench external shoulder rotation1.jpg","video_url":"videos/Shoulders/lying bench external shoulder rotation.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0639ed5f-f33c-4839-87ae-50d9e48118cb'::uuid, 'Lying bench internal rotation stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back on a bench with your arms extended out to the sides, your elbows bent at 90 degrees, and your forearms hanging off the sides of the bench, perpendicular to the floor in line with your torso.\r\n2. Rotate your shoulders to lift your forearms upward until they are vertical to the floor, maintaining the 90-degree angle at your elbows throughout the movement.\r\n3. Slowly lower your forearms back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep your core engaged and your back flat against the bench to maintain stability.\r\n2. Move slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Keep your elbows fixed at a 90-degree angle throughout the movement to isolate the shoulder rotation.', '{"image_male_start":"images/Shoulders/lying bench internal rotation stretch.jpg","image_male_end":"images/Shoulders/lying bench internal rotation stretch1.jpg","video_url":"videos/Shoulders/lying bench internal rotation stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('821b9a2e-b2a5-4913-9846-bba6a3d572d3'::uuid, 'Lying crossover stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your legs extended straight and your arms out to the sides to form a T shape.\r\n2. Bend and lift your right leg and cross it over your body, aiming to touch the floor on the left side, and extend your left arm to hold your right knee down. \r\n3. Hold the stretch for 15-30 seconds, feeling the stretch in your lower back and hips.\r\n4. Slowly return your right leg to the starting position. Repeat the stretch with your left leg, crossing it over your body to the right side. Alternate sides for the desired number of repetitions.', E'1. Move slowly and with control to avoid any sudden movements that could cause strain.\r\n2. Focus on deep, steady breathing, inhaling as you lift your leg and exhaling as you hold the stretch.\r\n3. Avoid forcing your leg to touch the floor if you feel any pain; go as far as your flexibility allows.', '{"image_male_start":"images/Stretching - Mobility/lying crossover stretch  .jpg","video_url":"videos/Stretching - Mobility/lying crossover stretch  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3095c52c-cec4-462b-b17c-1383655890dc'::uuid, 'Lying glute stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Lie on your back with your knees bent and feet flat on the floor.\r\n2. Cross your right ankle over your left knee, forming a figure-four position.\r\n3. Grasp the back of your left thigh with both hands and gently pull your left leg towards your chest. Hold the stretch for 15-30 seconds, feeling the stretch in your right glute and hip.\r\n4. Slowly release your left leg and return to the starting position. Repeat the stretch with your left ankle crossed over your right knee. Alternate sides for the desired number of repetitions.', E'1. Keep your head and shoulders relaxed on the floor to avoid tension in your neck and upper back.\r\n2. Avoid pulling too hard; go as far as your flexibility allows without causing pain.\r\n3. Use a towel or strap if needed to assist in pulling your leg towards your chest.\r\n', '{"image_male_start":"images/Stretching - Mobility/lying glute stretch  .jpg","video_url":"videos/Stretching - Mobility/lying glute stretch  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('582301e4-8a1d-4fab-b971-5fcf64d8577a'::uuid, 'Lying hip flexor stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Lie on your back with your legs straight on the floor.\r\n2. Lift your right knee towards your chest, holding it with both hands to keep it close while extending your left leg straight off floor, keeping it in line with your right foot.\r\n3. Hold the stretch for 15-30 seconds, then slowly release your right knee and return to the starting position. Repeat the stretch with your left knee lifted towards your chest and your right leg extended. Alternate sides for the desired number of repetitions.', E'1. Keep your lower back pressed into the floor to avoid strain and to deepen the stretch.\r\n2. Start with a smaller range of motion if you feel any discomfort, gradually increasing as flexibility improves.\r\n3. Focus on deep, steady breathing, inhaling as you prepare for the stretch and exhaling as you hold the stretch.', '{"image_male_start":"images/Stretching - Mobility/lying hip flexor stretch  .jpg","video_url":"videos/Stretching - Mobility/lying hip flexor stretch  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2b81d125-4b69-4e68-b70d-2025a1249c80'::uuid, 'Lying lateral raises bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie face down on the floor with your legs extended straight and your arms extended out to your sides, palms facing down.\r\n2. Lift both arms straight upwards, keeping them in line with your shoulders. Maintain a slight bend in your elbows.\r\n3. Hold the top position for a second, feeling the contraction in your shoulder and upper back muscles.\r\n4. Slowly lower your arms back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Maintain a slight bend in your elbows to reduce strain on your joints.\r\n2. Perform the exercise on a comfortable, non-slip surface to prevent discomfort or injury.\r\n3. Move slowly and with control to maximize muscle engagement and prevent injury.', '{"image_male_start":"images/Shoulders/lying lateral raises bodyweight.jpg","image_male_end":"images/Shoulders/lying lateral raises bodyweight1.jpg","video_url":"videos/Shoulders/lying lateral raises bodyweight.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('276006e0-8ae5-4d06-9b31-a82fb4c11e04'::uuid, 'Lying leg curl machine', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie face down on the lying leg curl machine, positioning your legs under the padded lever, just above your ankles. Adjust the machine so that your knees are just off the edge of the bench.\r\n2. Grasp the handles on the sides of the machine for stability and keep your back flat against the bench.\r\n3. Curl your legs up towards your glutes by bending your knees, squeezing your hamstrings at the top of the movement.\r\n4. Slowly lower the padded lever back to the starting position with control, fully extending your legs. Repeat for the desired number of repetitions.', E'1. Keep your hips pressed against the bench throughout the exercise to isolate the hamstring muscles.\r\n2. Avoid using momentum; let your muscles do the work.\r\n3. Exhale as you curl your legs up and inhale as you lower them back down.', '{"image_male_start":"images/Legs/lying leg curl machine  .jpg","video_url":"videos/Legs/lying leg curl machine  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('04272c5c-3a22-4f05-b1d5-1b7d2e799d3b'::uuid, 'Lying leg raise', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie flat on your back with your legs extended and your arms at your sides, palms facing down firm on the floor.\r\n2. Engage your core muscles and press your lower back into the floor.\r\n3. Keeping your legs straight, lift them up towards the ceiling until they are perpendicular to the floor.\r\n4. Slowly lower your legs back to the starting position with control, stopping just before they touch the floor. Repeat for the desired number of repetitions.', E'1. Exhale as you lift your legs up and inhale as you lower them back down.\r\n2. Keep your legs as straight as possible for maximum effectiveness.\r\n3. Focus on engaging your abdominal muscles throughout the movement.', '{"image_male_start":"images/Abdominals/lying leg raise.jpeg","video_url":"videos/Abdominals/lying leg raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6c39daba-98c3-4fb9-a8fa-fb908dab02e7'::uuid, 'Lying pull over with Resistance band cable', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Attach the middle of the resistance band to a low anchor point behind you. Lie on your back on the floor, knees bent and feet flat on the floor, holding a handle in each hand with your arms extended straight above your head, palms facing forward.\r\n2. Keeping your arms straight, pull the handles over your head and towards the floor until your arms are in line with your body.\r\n3. Slowly return the handles to the starting position with control, keeping your arms straight. \r\n4. Repeat for the desired number of repetitions.', E'1. Exhale as you pull the handles over your head and inhale as you return them to the starting position.\r\n2. Maintain a slight bend in your elbows to reduce strain on your joints.\r\n3. Focus on engaging your lats and chest muscles throughout the movement.', '{"image_male_start":"images/Chest/lying pull over with resistance band cable.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('27cb987b-356b-4512-aa5a-fc056872e5f3'::uuid, 'Lying quadriceps stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Lie face down on the floor with your legs extended straight and your arms resting by your sides.\r\n2. Bend your right knee and reach back with your right hand to grasp your right ankle or foot.\r\n3. Gently pull your right foot towards your glutes, feeling the stretch in your right quadriceps. Keep your hips pressed into the floor.\r\n4. Hold the stretch for 15-30 seconds, then slowly release your right foot and return to the starting position. Repeat the stretch on your left leg. Alternate sides for the desired number of repetitions.', E'1. Keep your hips pressed into the floor to maximize the stretch in your quadriceps and avoid straining your lower back.\r\n2. Move slowly and with control to avoid any sudden movements that could cause strain.\r\n3. If you cannot reach your foot comfortably, use a towel or strap around your ankle to assist with the stretch.', '{"image_male_start":"images/Stretching - Mobility/lying quadriceps stretch.jpg","image_male_end":"images/Stretching - Mobility/lying quadriceps stretch1.jpg","video_url":"videos/Stretching - Mobility/lying quadriceps stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b2bf95fa-cffc-42ef-9dff-f2e4a2a6454d'::uuid, 'Lying side quadriceps stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Lie on your side with your legs extended straight and your head resting on your lower hand. Extend your top arm and reach back to grasp your top ankle or foot.\r\n2. Bend your top knee and gently pull your foot towards your glutes with your hand, feeling the stretch in your quadriceps. Keep your hips stacked and your body in a straight line.\r\n3. Hold the stretch for 15-30 seconds, breathing deeply and steadily.\r\n4. Slowly release your foot and return to the starting position. Repeat the stretch on the other side. Alternate sides for the desired number of repetitions.', E'1. Keep your hips stacked and your body in a straight line to maintain proper alignment and maximize the stretch.\r\n2. If you cannot reach your foot comfortably, use a towel or strap around your ankle to assist with the stretch.\r\n3. Focus on deep, steady breathing, inhaling as you prepare for the stretch and exhaling as you hold the stretch.', '{"image_male_start":"images/Stretching - Mobility/lying side quadriceps stretch  .jpg","video_url":"videos/Stretching - Mobility/lying side quadriceps stretch  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('16df70b2-4772-4bb4-98d4-05df9ed9f73e'::uuid, 'Machine chest press decline', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'a6017729-dbd0-4f07-97fd-b74f488c07d7'::uuid, E'1. Sit on the decline chest press machine with your feet flat on the floor. Grasp the handles with both hands at chest level, palms facing down.\r\n2. Press the handles forward by extending your arms, keeping your elbows slightly bent at the end of the movement.\r\n3. Squeeze your chest muscles at the bottom of the movement and slowly return the handles to the starting position with control, bringing them back to chest level.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep your back pressed against the backrest throughout the exercise.\r\n2. Focus on engaging your chest muscles throughout the movement.\r\n3. Exhale as you press the handles forward and downward, and inhale as you return them to the starting position.', '{"image_male_start":"images/Chest/machine chest press decline.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4c1e8d6f-8f44-440e-8a8d-939fab438df1'::uuid, 'Machine chest press incline', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'a6017729-dbd0-4f07-97fd-b74f488c07d7'::uuid, E'1. Sit on the incline chest press machine with your feet flat on the floor. Grasp the handles with both hands, elbows facing the floor, palms facing forward.\r\n2. Press the handles upward by extending your arms, keeping your elbows slightly bent at the end of the movement.\r\n3. Squeeze your chest muscles at the top of the movement and slowly return the handles to the starting position with control, bringing them back to chest level.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep your back pressed against the backrest throughout the exercise.\r\n2. Focus on engaging your chest muscles throughout the movement.\r\n3. Exhale as you press the handles forward and downward, and inhale as you return them to the starting position.', '{"image_male_start":"images/Chest/machine chest press incline.jpg","image_male_end":"images/Chest/machine chest press incline1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1b4de794-abc0-46e5-b28f-fdd8e69443a5'::uuid, 'Machine fly', 'Resistance', 'strength', 'weight_reps', 'intermediate', '1ef31452-7681-4bfc-9d1a-bc84acc60cf8'::uuid, E'1. Sit on the chest fly machine with your feet flat on the floor and your back pressed firmly against the backrest. Grasp the handles, arms parallel to the floor, with both hands at chest level and palms facing forward.\r\n2. Keep a slight bend in your elbows and your arms extended out to your sides.\r\n3. Bring the handles together in front of your chest by squeezing your chest muscles, keeping your elbows slightly bent.\r\n4. Slowly return the handles to the starting position with control, bringing them back to your sides. Repeat for the desired number of repetitions.', E'1. Keep your back pressed against the backrest throughout the exercise to maintain proper form.\r\n2. Focus on engaging your chest muscles throughout the movement.\r\n3. Exhale as you bring the handles together and inhale as you return them to the starting position.', '{"image_male_start":"images/Chest/machine fly.jpg","image_male_end":"images/Chest/machine fly1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('34f08bc6-c7df-4fc5-a64f-a6b15bdc4008'::uuid, 'Machine lateral raise', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on the lateral raise machine with your feet flat on the floor and your back pressed firmly against the backrest. Adjust the seat height so that the pads rest against the outside of your upper arms.\r\n2. Grasp the handles with both hands, keeping your elbows bent.\r\n3. Raise your arms out to the sides until they are parallel to the floor and slowly lower your arms back to the starting position with control. \r\n4. Repeat for the desired number of repetitions.', E'1. Exhale as you raise your arms and inhale as you lower them back down.\r\n2. Use a moderate weight to ensure proper form and gradually increase the resistance as you get stronger.\r\n3. Focus on engaging your shoulder muscles throughout the movement.', '{"image_male_start":"images/Shoulders/machine lateral raise.jpg","image_male_end":"images/Shoulders/machine lateral raise1.jpg","video_url":"videos/Shoulders/machine lateral raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('92c32d19-e7c9-4a74-ae61-300360acd2ab'::uuid, 'MAJOR GROUPS Muscle body', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, '1. Stand tall with your back straight, arms by your side, and feet shoulder-width apart.', NULL, '{"image_male_start":"images/Calisthenics-Cardio-Functional/MAJOR GROUPS Muscle body male.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1039969e-f287-4126-9170-d487a5284285'::uuid, 'Middle back rotation stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand upright with your feet shoulder-width apart and your hands placed on your hips.\r\n2. Slowly rotate your torso to the right, keeping your hips facing forward. Twist as far as is comfortable, feeling the stretch in your middle back.\r\n3. Return to the center and repeat the rotation to the right once more.\r\n4. Rotate your torso to the left side twice in the same manner, alternating sides for the desired number of repetitions.', E'1. Keep your hips facing forward to ensure the stretch targets your middle back effectively.\r\n2. Perform the stretch on a stable, non-slip surface to prevent slipping or discomfort.\r\n3. Avoid forcing the twist; go as far as your flexibility allows without causing pain.', '{"image_male_start":"images/Stretching - Mobility/middle back rotation stretch.jpg","image_male_end":"images/Stretching - Mobility/middle back rotation stretch1.jpg","video_url":"videos/Stretching - Mobility/middle back rotation stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('49ed418f-009e-4416-875e-5c22911485fe'::uuid, 'Middle crunches', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your legs extended straight on the floor and your arms straight by your sides, palms facing the floor.\r\n2. Curl your abdomen, raising your upper back off the floor, while simultaneously lifting your legs straight up towards the ceiling and raise your arms towards your feet.\r\n3. Just before your hands and feet touch, lower your upper back, legs and arms back to the starting position with control. \r\n4. Repeat for the desired number of repetitions.', E'1. Exhale as you lift your upper back, legs and arms up, and inhale as you lower them back down.\r\n2. Keep your legs as straight as possible for maximum abdominal activation.\r\n3. Focus on engaging your abdominal muscles throughout the movement.', '{"image_male_start":"images/Abdominals/middle crunches.jpeg","video_url":"videos/Abdominals/middle crunches .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ebd7158d-dfc1-485f-a499-d215ad3b3492'::uuid, 'Military press bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand upright with your feet shoulder-width apart and your arms bent at the elbows, hands positioned at shoulder height with palms facing forward.\r\n2. Engage your shoulders and press your hands upward until your arms are fully extended above your head.\r\n3. Hold the top position for a moment, feeling the contraction in your shoulder muscles.\r\n4. Slowly lower your hands back to shoulder height with control. Repeat for the desired number of repetitions.', E'1. Breathe consistently, exhaling as you press your hands upward and inhaling as you lower them.\r\n2. Keep your head aligned with your spine to prevent neck strain.\r\n3. Avoid using momentum; focus on muscle strength to perform the movements.', '{"image_male_start":"images/Shoulders/military press bodyweight .jpg","video_url":"videos/Shoulders/military press bodyweight .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('67eb1adf-baed-4518-991e-8dbbceaec5f7'::uuid, 'Modified hindu push up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a plank position with your hands slightly wider than shoulder-width apart and your feet hip-width apart. Your body should form a straight line from head to heels.\r\n2. Lower your chest towards the floor by bending your elbows, keeping your body straight.\r\n3. Push through your hands to raise your hips up and back into a downward-facing dog position, forming an inverted V-shape with your body.\r\n4. Lower your hips and return to the plank position by moving your body forward. Repeat for the desired number of repetitions.', E'1. Engage your core to maintain a straight body line during the plank position and prevent your hips from sagging.\r\n2. Lower your chest towards the floor with controlled movement to ensure proper muscle engagement and avoid injury.\r\n3. As you push into the downward-facing dog, focus on driving your hips upward while keeping your arms and legs as straight as possible.', '{"image_male_start":"images/Yoga/Modified Hindu Push up.jpg","image_male_end":"images/Yoga/Modified Hindu Push up1.jpg","video_url":"videos/Yoga/Modified Hindu Push up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2119361c-6f35-4af9-b71c-e1c7f12ca82f'::uuid, 'Mountain climbers', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1.Begin in a plank position on your toes and hands, with your body in a straight line from head to heels.\r\n2. Bend your right knee and bring it towards your right elbow and stop when your knee is close to the elbow.\r\n3. Return to the starting plank position, then repeat the movement on the opposite side.\r\n4. Continue alternating sides for the desired number of repetitions.', E'1. Ensure you keep your movements smooth and controlled to maintain form and avoid injury.\r\n2. Maintain a steady breathing pattern, exhaling as you bring your knee towards your elbow and inhaling as you return to the plank position.\r\n3. Keep your shoulders stable and your core engaged throughout the exercise to enhance effectiveness.', '{"image_male_start":"images/Abdominals/mountain climbers.jpeg","video_url":"videos/Abdominals/mountain climbers.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('44a03ee6-1a78-4da7-826b-68e2149b96af'::uuid, 'MTS ISO-LATERAL KNEELING LEG CURL', 'Resistance', 'strength', 'weight_reps', 'intermediate', '41a888dc-9e8a-4146-b683-b681e55eefde'::uuid, E'1. Adjust the MTS Iso-Lateral Kneeling Leg Curl machine to fit your height. Kneel on the machine with your left knee on the knee pad and the right leg extended, securing your ankle under the padded lever. Rest your chest against the chest pad.\r\n2. Hold onto the handles for stability and keep your back straight.\r\n3. Curl your leg by bending your knee and pulling your heel towards your glutes, squeezing your hamstrings at the top of the movement.\r\n4. Slowly lower your leg back to the starting position with control. Repeat for the desired number of repetitions, then switch legs.', E'1. Keep your chest pressed against the pad and your back straight throughout the exercise.\r\n2. Focus on engaging your hamstrings throughout the movement.\r\n3. Exhale as you curl your leg up and inhale as you lower it back down.', '{"image_male_start":"images/Legs/MTS ISO-LATERAL KNEELING LEG CURL.jpg","image_male_end":"images/Legs/MTS ISO-LATERAL KNEELING LEG CURL1.jpg","image_female_start":"images/Legs/MTS ISO-LATERAL KNEELING LEG CURL_Female.jpg","image_female_end":"images/Legs/MTS ISO-LATERAL KNEELING LEG CURL_Female1.jpg","video_url":"videos/Legs/MTS ISO-LATERAL KNEELING LEG CURL.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c91fe64d-9014-4986-90f8-e23f50c4a301'::uuid, 'Normal Push-up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a plank position with your hands placed slightly wider than shoulder-width apart and your feet together. Your body should form a straight line from head to heels.\r\n2. Engage your chest and lower your body towards the floor by bending your elbows, keeping them at a 45-degree angle to your body.\r\n3. Lower your chest until it is just above the floor.\r\n4. Push through your hands to raise your body back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Keep your elbows at a 45-degree angle to your body to maximize chest and triceps engagement and reduce shoulder strain.\r\n2. Breathe steadily, exhaling as you push up and inhaling as you lower yourself.\r\n3. Keep your head aligned with your spine to avoid straining your neck.', '{"image_male_start":"images/Chest/Normal Push-up.jpg","image_male_end":"images/Chest/Normal Push-up1.jpg","video_url":"videos/Chest/Normal Push-up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('62c61eb4-36fb-4305-8f95-7cf60e95548f'::uuid, 'Oblique crunch', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your knees bent and feet flat on the floor. Place your hands behind your head, keeping your elbows wide.\r\n2. Engage your core muscles and lift your upper back off the floor, rotating your abdomen to raise your right elbow towards the ceiling.\r\n3. Squeeze your obliques at the top of the movement and slowly lower your upper back to the starting position with control.\r\n4. Repeat for the desired number of repetitions, then switch sides to work the opposite oblique.', E'1. Exhale as you lift and rotate your upper body, and inhale as you lower it back down.\r\n2. Avoid pulling on your neck with your hands; let your abs do the work.\r\n3. Focus on engaging your oblique muscles throughout the movement.', '{"image_male_start":"images/Abdominals/oblique crunch.jpeg","video_url":"videos/Abdominals/oblique crunch .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('931fbecf-ee9e-4026-89c2-942e784a7052'::uuid, 'One arm reverse dumbbell fly', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by standing with your feet shoulder-width apart, holding a dumbbell in one hand with a neutral grip. Bend at the hips and knees, keeping your back straight and almost parallel to the floor, and extend your free hand to hold on a bench.\r\n2.  Allow the dumbbell to hang straight down from your shoulder, with your arm fully extended towards the floor.\r\n3. Raise the dumbbell out to the side until your arm is parallel to the floor, keeping a slight bend in your elbow.\r\n4. Lower the dumbbell back to the starting position with control. Repeat for the desired number of repetitions, then switch to the other arm.', E'1. Use a controlled motion to lift and lower the dumbbell, avoiding momentum.\r\n2. Focus on using your shoulder muscles to lift the weight rather than swinging your arm.\r\n3. Keep a slight bend in your elbow throughout the exercise to reduce strain on your joints.', '{"image_male_start":"images/Shoulders/one arm reverse dumbbell fly.jpg","image_male_end":"images/Shoulders/one arm reverse dumbbell fly1.jpg","video_url":"videos/Shoulders/one arm reverse dumbbell fly.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0af3f690-c826-4370-a9d5-e1d3709f881b'::uuid, 'Over head weight sit up', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'ba1cac69-c4db-4c14-8076-0f34af9c1f91'::uuid, E'1. Begin by lying on your back with your knees bent and your feet on the floor. Hold a weight plate with both hands, extending your arms straight above your chest.\r\n2. Engage your core muscles and sit up by lifting your upper body towards your knees, keeping the weight extended upwards and your arms straight.\r\n3. Continue to sit up until your torso is upright, maintaining the weight above your head throughout the movement.\r\n4. Lower to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you crunch up and inhale as you lower back down.\r\n2. Start with a lighter weight to master the form before progressing to heavier weights.\r\n3. Perform the movement slowly and with control to maximize muscle engagement and avoid injury.', '{"image_male_start":"images/Abdominals/over head weight sit up.jpeg","video_url":"videos/Abdominals/over head weight sit up .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('dfb1ae18-cd33-406a-ac31-c15ca73ca21f'::uuid, 'Over weight ab crunch', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Begin by lying on your back with your legs straight on the floor close together. Hold a dumbbell with both hands, keeping your arms bent and behind your head, close to the floor.\r\n2. Engage your core muscles and lift your torso off the floor while bending your knees and raising them to your chest, and bringing the dumbbell close to your knees.\r\n3. Lower your body back to the starting position with control. Repeat for the desired number of repetitions.\r\n', E'1. Exhale as you crunch up and inhale as you lower back down.\r\n2. Start with a lighter weight to master the form before progressing to heavier weights.\r\n3. Perform the movement slowly and with control to maximize muscle engagement and avoid injury.', '{"image_male_start":"images/Abdominals/over weight ab crunch.jpeg","video_url":"videos/Abdominals/over weight ab crunch .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e55e58af-9a67-463c-b918-b343f267b800'::uuid, 'Overhand clap', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand upright with your feet shoulder-width apart and your arms extended down to your sides, palms facing your torso.\r\n2. Lift your arms overhead, bringing your palms together in a clapping motion.\r\n3. Lower your arms back to the starting position with control, keeping them straight and at shoulder height.\r\n4. Repeat the movement for the desired number of repetitions, maintaining a smooth and controlled motion.', E'1. Focus on steady breathing, inhaling as you lift your arms and exhaling as you lower them.\r\n2. Ensure your shoulders stay relaxed and away from your ears to avoid unnecessary tension.\r\n3. Keep your movements smooth and controlled and avoid using momentum.', '{"image_male_start":"images/Shoulders/overhand clap .jpg","video_url":"videos/Shoulders/overhand clap .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e079e17e-523d-41d3-8964-a0b72bfa8c07'::uuid, 'Overhand tricep stretching single arm', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand upright with your feet shoulder-width apart.\r\n2. Raise your right arm overhead and bend your elbow, reaching your right hand down towards your upper back.\r\n3. Bring your left arm overhead and hold your right elbow with your left hand, gently pulling your right elbow to the left side to deepen the stretch. Hold this position for 15-30 seconds.\r\n4. Release the stretch and return to the starting position. Repeat on the left side by raising your left arm overhead and bending your elbow, using your right hand to assist with the stretch. Alternate sides for the desired number of repetitions.', E'1. Avoid arching your back; keep your spine neutral to maximize the stretch and prevent injury.\r\n2. Keep your core engaged to maintain balance and support your lower back.\r\n3. Use gentle pressure when pulling on your elbow to avoid overstretching and potential discomfort.', '{"image_male_start":"images/Triceps/Overhand tricep stretching single arm.jpeg","video_url":"videos/Triceps/Overhand tricep stretching single arm.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e3ccbfda-2f2b-4dab-a3be-86bab0d48da6'::uuid, 'Overhead extension Resistance band both arms', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart, placing the middle of the resistance band under both feet. Hold the handles of the resistance band with both hands and extend your arms overhead, keeping your elbows close to your ears and your palms facing each other.\r\n2. Lower the handles behind your head by bending your elbows until your forearms are about parallel to the floor, keeping your upper arms stationary.\r\n3. Extend your arms back to the starting position by straightening your elbows. \r\n4. Repeat for the desired number of repetitions.', E'1. Keep your elbows close to your ears and avoid flaring them out to isolate the triceps.\r\n2. Keep your shoulders down and relaxed to avoid neck tension.\r\n3. Exhale as you extend your arms and inhale as you lower them back down.', '{"image_male_start":"images/Triceps/overhead extension resistance band both arms.jpeg","video_url":"videos/Triceps/overhead extension resistance band both arms  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('bebb2ca1-d784-43ff-8b2c-1859ea9b5103'::uuid, 'Overhead triceps stretch side angle', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand upright with your feet shoulder-width apart.\r\n2. Raise your right arm overhead and bend your elbow, reaching your right hand down towards your upper back.\r\n3. Bring your left arm overhead and hold your right elbow with your left hand, gently pulling your right elbow to the left side to deepen the stretch. Hold this position for 15-30 seconds.\r\n4. Release the stretch and return to the starting position. Repeat on the left side by raising your left arm overhead and bending your elbow, using your right hand to assist with the stretch. Alternate sides for the desired number of repetitions.', E'1. Avoid arching your back; keep your spine neutral to maximize the stretch and prevent injury.\r\n2. Keep your core engaged to maintain balance and support your lower back.\r\n3. Use gentle pressure when pulling on your elbow to avoid overstretching and potential discomfort.', '{"image_male_start":"images/Stretching - Mobility/overhead triceps stretch side angle.jpg","image_male_end":"images/Stretching - Mobility/overhead triceps stretch side angle1.jpg","video_url":"videos/Stretching - Mobility/overhead triceps stretch side angle.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d625160a-635b-4b05-931b-62f9ea88654a'::uuid, 'Palm up palm down rotation', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand upright with your feet shoulder-width apart and your arms extended straight at your sides at shoulder height.\r\n2. Slowly rotate your forearms in the opposite direction so that your palms face up while slightly lowering your arms.\r\n3. Slowly raise your arms back to the starting position while rotating your forearms so that both palms face down. \r\n4. Repeat for the desired repetitions.', E'1. Focus on steady breathing, exhaling as you lower your arms and inhaling as you return to the starting position.\r\n2. Keep your shoulders relaxed and away from your ears to avoid unnecessary tension.\r\n3. Maintain a slight bend in your elbows to reduce strain on your joints.', '{"image_male_start":"images/Shoulders/palm up palm down rotation .jpg","video_url":"videos/Shoulders/palm up palm down rotation .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0e08a47d-5c4d-4e74-a6da-170d07b07531'::uuid, 'Pec deck fly machine', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'a1c23345-7a3f-4f47-b874-d83028c84eba'::uuid, E'1. Sit on the Pec Deck machine with your feet flat on the floor and your back pressed firmly against the backrest. Bend your arms at 90 degrees and rest your elbows on the elbow pads and grasp the handles, upper arms parallel to the floor and palms facing forward.\r\n2. Squeeze your chest muscles to bring the handles together in front of your chest.\r\n3. Slowly return to the starting position with control, bringing your elbows back to your sides. \r\n4. Repeat for the desired number of repetitions.', E'1. Keep your back pressed against the backrest throughout the exercise to maintain proper form.\r\n2. Focus on engaging your chest muscles throughout the movement.\r\n3. Exhale as you bring your elbows together and inhale as you return them to the starting position.', '{"video_url":"videos/Chest/pec deck fly machine.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e24d07db-b12a-4503-925f-83494121b138'::uuid, 'Pike push up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a plank position with your hands slightly wider than shoulder-width apart and your feet hip-width apart. Your body should form a straight line from head to heels.\r\n2. Walk your feet towards your hands, lifting your hips up towards the ceiling to form an inverted V-shape. Keep your arms and legs straight, and your head between your arms.\r\n3. Lower your head towards the floor by bending your elbows, keeping them pointed outwards.\r\n4. Push through your hands to return to the starting inverted V position, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Keep your head aligned with your arms to avoid straining your neck.\r\n2. Ensure your elbows point outwards to target your shoulders effectively.\r\n3. Perform the exercise on a stable, non-slip surface to prevent slipping and ensure safety.', '{"image_male_start":"images/Triceps/Pike push up.jpeg","video_url":"videos/Triceps/Pike push up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5cea3388-6f18-4717-b128-08e4a79d2dc1'::uuid, 'Plank cross knee drive', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a plank position with your hands directly under your shoulders and your body forming a straight line from head to heels. Engage your core.\r\n2. Lift your right knee and drive it towards your left elbow and straighten your leg, twisting your torso slightly to the left as you do so.\r\n3. Return your right leg to the starting plank position.\r\n4. Repeat the movement with your left knee, driving it towards your right elbow. Alternate sides for the desired number of repetitions.', E'1. Keep your core engaged throughout the exercise to maintain stability and support your lower back.\r\n2. Move slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Focus on steady breathing, exhaling as you drive your knee towards your elbow and inhaling as you return to the starting position.', '{"image_male_start":"images/Abdominals/plank cross knee drive.jpeg","video_url":"videos/Abdominals/plank cross knee drive .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('67d51453-f85d-4238-adfa-6dab919fdd70'::uuid, 'Plank jack', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a plank position with your elbows directly under your shoulders and your body forming a straight line from head to heels. Engage your core.\r\n2. Jump your feet out to the sides, slightly wider than shoulder-width apart, while keeping your upper body stable.\r\n3. Quickly jump your feet back together to return to the starting plank position.\r\n4. Continue jumping your feet in and out for the desired number of repetitions or duration.', E'1. Move quickly but with control to maximize muscle engagement and prevent injury.\r\n2. Maintain a neutral head position, looking slightly ahead of your hands, to keep your neck aligned with your spine.\r\n3. Ensure your body stays in a straight line, avoiding sagging hips or raised buttocks.', '{"image_male_start":"images/Abdominals/plank jack.jpeg","video_url":"videos/Abdominals/plank jack .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ceeda50f-2e1c-4ebf-9f3a-06cad5005cc4'::uuid, 'Plank Knee Tucks', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a plank position with your hands directly under your shoulders and your body forming a straight line from head to heels.\r\n2. Quickly jump both knees towards your chest, landing with both feet flat on the floor beneath you.\r\n3. Immediately jump your feet back to the starting plank position.\r\n4. Continue jumping your feet in and out for the desired number of repetitions.', E'1. Use controlled, explosive movements to quickly bring your knees to your chest and return to plank position.\r\n2. Ensure your shoulders remain directly over your wrists to maintain alignment and reduce strain on your shoulders.\r\n3. Keep your hips level throughout the movement to maintain proper form and avoid sagging or raising your hips.\r\n', '{"image_male_start":"images/Abdominals/Plank Knee Tucks.jpeg","video_url":"videos/Abdominals/Plank Knee Tucks .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7c2785a8-dc98-4a82-93a6-54f9e92bf184'::uuid, 'Plank lunges', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a plank position with your hands directly under your shoulders and your body forming a straight line from head to heels.\r\n2. Bring your right knee forward and place your right foot outside your right hand, keeping your left leg extended straight back.\r\n3. Return your right foot to the plank position.\r\n4. Repeat the movement with your left knee, bringing your left foot forward to place it outside your left hand. Alternate sides for the desired number of repetitions.', E'1. Move your leg slowly and with control to maximize muscle engagement and prevent injury.\r\n2. Breathe steadily, exhaling as you bring your foot forward and inhaling as you return to the plank position.\r\n3. Ensure your body stays in a straight line, avoiding sagging hips or raised buttocks.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/plank lunges  .jpg","video_url":"videos/Calisthenics-Cardio-Functional/plank lunges  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e46f2066-98f1-4056-82e5-b9d747a9b810'::uuid, 'Plank on elbows', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin by lying face down on the floor. Place your elbows directly under your shoulders and your forearms flat on the floor, parallel to each other.\r\n2. Engage your core and lift your body off the floor, forming a straight line from your head to your heels. Your elbows and toes should support your body weight.\r\n3. Hold this position, keeping your core tight and your body straight. Avoid letting your hips sag or rise too high.\r\n4. Maintain the plank position for the desired amount of time, focusing on your form and breathing steadily.', E'1. Engage your core throughout the exercise to maintain stability and support your lower back.\r\n2. Keep your body in a straight line from head to heels, avoiding any sagging or lifting of the hips.\r\n3. Keep your shoulders directly above your elbows to maintain proper alignment and reduce strain on your shoulders.\r\n', '{"image_male_start":"images/Abdominals/plank on elbows.jpeg","video_url":"videos/Abdominals/plank on elbows.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('88b1341b-f415-4d4f-bb30-e42e9ee30379'::uuid, 'Plank reach through', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a side plank position on your right side with your right elbow supporting your body, your left arm raised vertically towards the ceiling, and your body forming a straight line from head to heels.\r\n2. Lower your left arm, reaching it under and across your torso while slightly lowering your hips.\r\n3. Return your left arm to the starting position, lifting your hips back to the straight line.\r\n4. Repeat for the desired number of repetitions, then switch to the left side and repeat the movement with your right arm.', E'1. Engage your core throughout the exercise to maintain stability and support your lower back.\r\n2. Ensure your supporting arm or elbow is directly under your shoulder to maintain proper alignment and reduce strain.\r\n3. Keep your hips stable and aligned with your body, avoiding excessive rotation.\r\n4. Focus on steady breathing, exhaling as you reach under your torso and inhaling as you return to the starting position.\r\n', '{"image_male_start":"images/Abdominals/plank reach through.jpeg","video_url":"videos/Abdominals/plank reach through .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6a84f1a3-9484-43ca-9db5-299aa76fb7b3'::uuid, 'Plank reverse fly with bottle', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Start in a high plank position with your hands placed directly under your shoulders and your body forming a straight line from head to heels. Hold a water bottle in your right hand, and keep your feet slightly wider than hip-width apart for stability.\r\n2. Lift the water bottle out to the side while keeping your arm straight, raising it until it is parallel to the floor.\r\n3. Slowly lower the bottle back to the starting position with control.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Keep your core engaged to maintain a stable plank position and prevent your hips from sagging or rotating.\r\n2. Perform the movement slowly and with control to maximize muscle engagement and avoid using momentum.\r\n3. Keep your arm straight and avoid locking your elbow to protect your joint.', '{"image_male_start":"images/Shoulders/plank reverse fly with bottle .jpg","video_url":"videos/Shoulders/plank reverse fly with bottle .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('82aef8bd-f90a-4b52-a01b-d64f1821fd0b'::uuid, 'Plank shoulder taps', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a plank position with your hands directly under your shoulders and your body forming a straight line from head to heels.\r\n2. Lift your right hand off the floor and tap your left shoulder, keeping your hips stable and minimizing rotation.\r\n3. Return your right hand to the starting position.\r\n4. Repeat the movement with your left hand, lifting it off the floor and tapping your right shoulder. Alternate sides for the desired number of repetitions.', E'1. Keep your hips level throughout the movement to maintain proper form and avoid rotating your torso.\r\n2. Perform the exercise on a stable, non-slip surface to prevent slipping and ensure safety.\r\n3. Keep your shoulders directly over your wrists to maintain alignment and reduce strain on your shoulders.\r\n', '{"image_male_start":"images/Calisthenics-Cardio-Functional/plank shoulder taps  .jpg","video_url":"videos/Calisthenics-Cardio-Functional/plank shoulder taps  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('72dde12c-5a41-407e-a926-14e129b1eef5'::uuid, 'Plate front raise', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, holding a weight plate with both hands. Keep your arms extended straight down in front of your hips.\r\n2. Raise the plate in front of you with straight arms until they are parallel to the floor, keeping a slight bend in your elbows.\r\n3. Pause briefly at the top of the movement, then slowly lower the plate back to the starting position with control.\r\n4. Repeat the movement for the desired number of repetitions, maintaining good form throughout.', E'1. Avoid using momentum to lift the plate; focus on a slow and controlled movement.\r\n2. Keep a slight bend in your elbows to protect your joints.\r\n3. Breathe steadily, exhaling as you lift the plate and inhaling as you lower it.', '{"image_male_start":"images/Shoulders/plate front raise .jpg","video_url":"videos/Shoulders/plate front raise .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('cc532edc-c21e-4740-a14e-e8acc0ec7d55'::uuid, 'Plate loaded chest press incline', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'a6017729-dbd0-4f07-97fd-b74f488c07d7'::uuid, E'1. Sit on the plate-loaded incline chest press machine with your feet flat on the floor. Grasp the handles with both hands, elbows facing the floor, palms facing forward.\r\n2. Press the handles upward by extending your arms, keeping your elbows slightly bent at the end of the movement.\r\n3. Squeeze your chest muscles at the top of the movement and slowly return the handles to the starting position with control, bringing them back to chest level.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep your back pressed against the backrest throughout the exercise.\r\n2. Focus on engaging your chest muscles throughout the movement.\r\n3. Exhale as you press the handles and inhale as you return them to the starting position.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f5d2db59-d646-4d28-819e-04285daf4eb0'::uuid, 'Plyo side lunge stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand upright with your feet wider than shoulder-width apart and both arms extended straight out to your sides.\r\n2. Bend your right knee and lower into a side lunge while simultaneously rotating your torso to the right and bringing your left hand to touch your right leg. Keeping your left leg straight.\r\n3. Push off your right foot to return to the starting wide stance position, straightening your right leg and rotating your torso back to the center.\r\n4. Repeat the movement on the left side, bending your left knee into a side lunge and rotating your torso to bring your right hand to touch your left leg. Alternate sides for the desired number of repetitions.', E'1. Ensure your bent knee stays aligned with your toes to avoid strain on your knee joint.\r\n2. Move with control to maximize muscle engagement and prevent injury.\r\n3. Focus on steady breathing, exhaling as you lower into the lunge and inhaling as you return to the starting position.', '{"image_male_start":"images/Stretching - Mobility/plyo side lunge stretch  .jpg","video_url":"videos/Stretching - Mobility/plyo side lunge stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5631938d-da2a-4de2-b3bd-6d46a571251b'::uuid, 'Preacher curl barbell', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Sit on a preacher bench with your feet flat on the floor, holding a barbell with an underhand grip (palms facing up), shoulder-width wide, and your arms resting on the preacher pad.\r\n2. Curl the barbell towards your shoulders by bending your elbows, keeping your upper arms pressed against the pad.\r\n3. Squeeze your biceps at the top of the movement, ensuring the barbell reaches shoulder height.\r\n4. Slowly lower the barbell back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Keep your upper arms stationary against the pad to isolate the biceps.\r\n2. Use a weight that allows you to maintain proper form throughout the exercise.\r\n3. Exhale as you curl the barbell up and inhale as you lower it.', '{"image_male_start":"images/Biceps/preacher curl barbell.jpeg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('dc5ee07d-8d28-4b3c-ac5b-065e62c3aa85'::uuid, 'Preacher curl dumbbells simultaneous', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a preacher bench with your feet flat on the floor, holding a dumbbell in each hand with an underhand grip (palms facing up), and your arms extended over the preacher bench pad.\r\n2. Engage your core and curl both dumbbells towards your shoulders by bending your elbows, keeping your upper arms pressed against the pad.\r\n3. Squeeze your biceps at the top of the movement, ensuring the dumbbells reach shoulder height.\r\n4. Slowly lower the dumbbells back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Keep your upper arms stationary against the pad to isolate the biceps.\r\n2. Keep your wrists straight and avoid letting them bend backward.\r\n3. Exhale as you curl the dumbbells up and inhale as you lower them.', '{"image_male_start":"images/Biceps/preacher curl dumbbells simultaneous.jpeg","video_url":"videos/Biceps/preacher curl dumbbells simultaneous .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8063120b-090e-456a-bd25-b224badf64ab'::uuid, 'Preacher curl ez bar', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '0e9c1392-3e8d-454d-be69-641c3a69f2b9'::uuid, E'1. Sit on a preacher bench with your feet flat on the floor, holding an EZ bar with an underhand grip (palms facing up), shoulder-width wide, and your arms resting on the preacher pad.\r\n2. Curl the EZ bar towards your shoulders by bending your elbows, keeping your upper arms pressed against the pad.\r\n3. Squeeze your biceps at the top of the movement, ensuring the bar reaches shoulder height.\r\n4. Slowly lower the bar back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Keep your upper arms stationary against the pad to isolate the biceps.\r\n2. Use a weight that allows you to maintain proper form throughout the exercise.\r\n3. Exhale as you curl the barbell up and inhale as you lower it.', '{"image_male_start":"images/Biceps/preacher curl ez bar.jpeg","video_url":"videos/Biceps/preacher curl ez bar.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4f0d72fd-e19b-445d-8530-f829ec2f3cb8'::uuid, 'Preacher curl ez bar close grip', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '0e9c1392-3e8d-454d-be69-641c3a69f2b9'::uuid, E'1. Sit on a preacher bench with your feet flat on the floor, holding an EZ bar with an underhand grip (palms facing up), just closer than shoulder-width wide, and your arms resting on the preacher pad.\r\n2. Curl the EZ bar towards your shoulders by bending your elbows, keeping your upper arms pressed against the pad.\r\n3. Squeeze your biceps at the top of the movement, ensuring the bar reaches shoulder height.\r\n4. Slowly lower the bar back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Keep your upper arms stationary against the pad to isolate the biceps.\r\n2. Use a weight that allows you to maintain proper form throughout the exercise.\r\n3. Exhale as you curl the barbell up and inhale as you lower it.', '{"image_male_start":"images/Biceps/preacher curl ez bar close grip.jpeg","video_url":"videos/Biceps/preacher curl ez bar close grip.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('780fa290-e1e2-4acf-9a2b-875b46cf7961'::uuid, 'Preacher curl ez bar wide grip', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '0e9c1392-3e8d-454d-be69-641c3a69f2b9'::uuid, E'1. Sit on a preacher bench with your feet flat on the floor, holding an EZ bar with an underhand grip (palms facing up), just wider than shoulder-width wide, and your arms resting on the preacher pad.\r\n2. Curl the EZ bar towards your shoulders by bending your elbows, keeping your upper arms pressed against the pad.\r\n3. Squeeze your biceps at the top of the movement, ensuring the bar reaches shoulder height.\r\n4. Slowly lower the bar back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Keep your upper arms stationary against the pad to isolate the biceps.\r\n2. Use a weight that allows you to maintain proper form throughout the exercise.\r\n3. Exhale as you curl the barbell up and inhale as you lower it.', '{"image_male_start":"images/Biceps/preacher curl ez bar wide grip.jpeg","video_url":"videos/Biceps/preacher curl ez bar wide grip.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4873c608-3659-4699-8510-6f9937c2b38c'::uuid, 'Pretzel stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Sit on the floor with your legs extended straight in front of you.\r\n2. Bend your right knee, placing your right foot flat on the floor inside your left thigh. \r\n3. Rotate your torso to the right and place your left elbow on the outside of your right knee, using your right hand on the floor behind you for support.\r\n4. Hold the stretch for 15-30 seconds, then slowly release and return to the starting position. Repeat on the other side by switching the positions of your legs and rotating your torso to the left.', E'1. Use your supporting hand on the floor behind you to maintain balance and assist with the rotation.\r\n2. Move into the stretch slowly and with control to prevent overstretching and injury.\r\n3. Breathe deeply and steadily, using your breath to help deepen the stretch and relax your muscles.\r\n', '{"image_male_start":"images/Stretching - Mobility/pretzel stretch.jpg","image_male_end":"images/Stretching - Mobility/pretzel stretch1.jpg","video_url":"videos/Stretching - Mobility/pretzel stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c80f99a2-8998-40ef-81cf-a865d337a88e'::uuid, 'Prone bench row barbell pronate grip', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Lie chest-first on an incline bench, holding a barbell with a pronate grip (palms facing down) and your hands placed shoulder-width apart. Extend your arms straight down towards the floor.\r\n2. Pull the barbell towards your upper abdomen by bending your elbows, keeping them close to your body.\r\n3. Squeeze your shoulder blades together at the top of the movement, ensuring the barbell reaches reaches close to the bench.\r\n4. Slowly lower the barbell back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Focus on pulling with your back muscles rather than your arms.\r\n2. Exhale as you pull the barbell up and inhale as you lower it.\r\n3. Use a weight that allows you to maintain proper form throughout the exercise.', '{"image_male_start":"images/Back/prone bench row barbell pronate grip.jpg","image_male_end":"images/Back/prone bench row barbell pronate grip1.jpg","video_url":"videos/Back/prone bench row barbell pronate grip.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a799fe14-ddbb-4129-8905-cb59573705ff'::uuid, 'Prone bench row barbell reverse grip', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Lie chest-first on an incline bench, holding a barbell with a reverse grip (palms facing up) and your hands placed shoulder-width apart. Extend your arms straight down towards the floor.\r\n2. Pull the barbell towards your abdomen by bending your elbows, keeping them close to your body.\r\n3. Squeeze your shoulder blades together at the top of the movement, ensuring the barbell reaches close to the bench.\r\n4. Slowly lower the barbell back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Focus on pulling with your back muscles rather than your arms.\r\n2. Exhale as you pull the barbell up and inhale as you lower it.\r\n3. Keep your elbows close to your body to maximize back muscle engagement.', '{"image_male_start":"images/Back/Prone bench row barbell reverse grip .jpg","video_url":"videos/Back/Prone bench row barbell reverse grip .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ee182cca-64c4-4c57-a711-7bf884cce6a3'::uuid, 'Prone bench row dumbbells', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie chest-first on an incline bench, holding a dumbbell in each hand with a neutral grip (palms facing each other), and your arms extended straight down towards the floor.\r\n2. Pull the dumbbells towards your abdomen by bending your elbows, keeping them close to your body.\r\n3. Squeeze your shoulder blades together at the top of the movement, ensuring the dumbbells reach the sides of your torso.\r\n4. Slowly lower the dumbbells back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Focus on pulling with your back muscles rather than your arms.\r\n2. Exhale as you pull the dumbbells up and inhale as you lower them.\r\n3. Use a weight that allows you to maintain proper form throughout the exercise.', '{"image_male_start":"images/Back/prone bench row dumbbells.jpg","image_male_end":"images/Back/prone bench row dumbbells1.jpg","video_url":"videos/Back/prone bench row dumbbells.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a9dba37b-d558-49bd-84c3-9af991cf87ac'::uuid, 'Prone bench row dumbbells pronated grip', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie chest-first on an incline bench, holding a dumbbell in each hand with a reverse grip (palms facing down), and your arms extended straight down towards the floor.\r\n2. Pull the dumbbells towards your abdomen by bending your elbows, keeping them close to your body.\r\n3. Squeeze your shoulder blades together at the top of the movement, ensuring the dumbbells reach the sides of your torso.\r\n4. Slowly lower the dumbbells back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Focus on pulling with your back muscles rather than your arms.\r\n2. Exhale as you pull the dumbbells up and inhale as you lower them.\r\n3. Use a weight that allows you to maintain proper form throughout the exercise.', '{"image_male_start":"images/Back/prone bench row dumbbells pronated grip.jpg","image_male_end":"images/Back/prone bench row dumbbells pronated grip1.jpg","video_url":"videos/Back/prone bench row dumbbells pronated grip.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('724c820d-97b2-4675-9618-10204d74e297'::uuid, 'Prone bench row dumbbells supinated grip', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie chest-first on an incline bench, holding a dumbbell in each hand with a supinate grip (palms facing up), and your arms extended straight down towards the floor.\r\n2. Pull the dumbbells towards your abdomen by bending your elbows, keeping them close to your body.\r\n3. Squeeze your shoulder blades together at the top of the movement, ensuring the dumbbells reach the sides of your torso.\r\n4. Slowly lower the dumbbells back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Focus on pulling with your back muscles rather than your arms.\r\n2. Exhale as you pull the dumbbells up and inhale as you lower them.\r\n3. Use a weight that allows you to maintain proper form throughout the exercise.', '{"image_male_start":"images/Back/prone bench row dumbbells supinated grip.jpg","image_male_end":"images/Back/prone bench row dumbbells supinated grip1.jpg","video_url":"videos/Back/prone bench row dumbbells supinated grip.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d9202737-b00e-482b-934a-c317ecffdd8b'::uuid, 'Prone front raises barbell on bench', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Lie chest-first on an incline bench, holding a barbell with both hands using a pronated grip (palms facing down) and a shoulder-width hand placement. Your arms should be extended straight down towards the floor.\r\n2. Lift the barbell straight up in front of you until your arms are parallel to the floor.\r\n3. Slowly lower the barbell back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep your body pressed firmly against the bench to prevent lower back strain.\r\n2. Focus on lifting with your shoulders and not your arms to maximize shoulder engagement.\r\n3. Exhale as you lift the barbell and inhale as you lower it.', '{"image_male_start":"images/Shoulders/prone front raises barbell on bench.jpg","image_male_end":"images/Shoulders/prone front raises barbell on bench1.jpg","video_url":"videos/Shoulders/prone front raises barbell on bench.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('af983ba3-5c53-485e-9a07-306dee7bd78a'::uuid, 'Prone front raises dumbbell on bench', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Lie chest-first on an incine bench, holding a dumbbell in each hand with an overhand grip (palms facing down). Your arms should be extended straight down towards the floor.\r\n2. Raise the dumbbells straight up in front of you until your arms are in line with your torso.\r\n3. Slowly lower the dumbbells back to the starting position. \r\n4. Repeat for the desired repetitions.', E'1. Keep your body pressed firmly against the bench to prevent lower back strain.\r\n2. Focus on lifting with your shoulders and not your arms to maximize shoulder engagement.\r\n3. Exhale as you lift the barbell and inhale as you lower it.', '{"image_male_start":"images/Shoulders/prone front raises dumbbell on bench.jpg","image_male_end":"images/Shoulders/prone front raises dumbbell on bench1.jpg","video_url":"videos/Shoulders/prone front raises dumbbell on bench.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('849f82f6-fcea-4193-ad62-0e1091d87f2e'::uuid, 'Pull apart cable Resistance band', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart, holding a resistance band with both hands, arms extended straight in front of you at shoulder height. Your palms should be facing the floor.\r\n2. Pull the resistance band apart by moving your arms out to your sides.\r\n3. Slowly return your arms to the starting position with control. \r\n4. Repeat for the desired number of repetitions.', E'1. Keep your arms straight throughout the exercise, maintaining a slight bend in your elbows to avoid locking them.\r\n2. Perform the movement slowly and with control to maximize muscle activation and reduce injury risk.\r\n3. Exhale as you pull the band apart and inhale as you return to the starting position.', '{"image_male_start":"images/Shoulders/pull apart cable resistance band .jpg","video_url":"videos/Shoulders/pull apart cable resistance band .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7cf83c17-4f2c-421e-b195-20b5f15b9475'::uuid, 'Pull up normal grip', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '54938b47-43e8-47cd-9efc-18b4424e71e1'::uuid, E'1. Stand beneath a pull-up bar and grasp it with an overhand grip (palms facing away from you), hands slightly wider than shoulder-width apart.\r\n2. Engage your back muscles and pull yourself up towards the bar by bending your elbows.\r\n3. Continue pulling until your chin is above the bar, focusing on contracting your back muscles.\r\n4. Lower yourself back to the starting position in a controlled manner, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Use a full range of motion, fully extending your arms at the bottom and pulling up until your chin is above the bar.\r\n2. Focus on engaging your back muscles, particularly the latissimus dorsi, to perform the pull-up effectively.\r\n3. Breathe steadily, exhaling as you pull up and inhaling as you lower yourself down.\r\n4. Avoid using momentum to swing your body; maintain a controlled movement throughout the exercise.\r\n5. Perform the exercise on a stable, secure pull-up bar to ensure safety.', '{"image_male_start":"images/Back/pull up normal grip .jpg","video_url":"videos/Back/pull up normal grip .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('00051401-a4c9-423e-aa6e-e26f387eb33b'::uuid, 'Pull up wide grip', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '54938b47-43e8-47cd-9efc-18b4424e71e1'::uuid, E'1. Stand beneath a pull-up bar and grasp it with an overhand grip (palms facing away from you), hands wider than shoulder-width apart.\r\n2. Engage your back muscles to pull yourself up towards the bar by bending your elbows.\r\n3. Continue pulling until your chin is above the bar, focusing on contracting your back muscles.\r\n4. Lower yourself back to the starting position in a controlled manner, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Use a full range of motion, fully extending your arms at the bottom and pulling up until your chin is above the bar.\r\n2. Focus on engaging your back muscles, particularly the latissimus dorsi, to perform the pull-up effectively.\r\n3. Breathe steadily, exhaling as you pull up and inhaling as you lower yourself down.\r\n4. Avoid using momentum to swing your body; maintain a controlled movement throughout the exercise.\r\n5. Perform the exercise on a stable, secure pull-up bar to ensure safety.', '{"image_male_start":"images/Back/pull up wide grip .jpg","video_url":"videos/Back/pull up wide grip .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('298eee7d-da3c-45d9-b15c-efc3915da8c3'::uuid, 'Pull up wide grip front view', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '54938b47-43e8-47cd-9efc-18b4424e71e1'::uuid, E'1. Stand beneath a pull-up bar and grasp it with an overhand grip (palms facing away from you), hands wider than shoulder-width apart.\r\n2. Engage your back muscles to pull yourself up towards the bar by bending your elbows.\r\n3. Continue pulling until your chin is above the bar, focusing on contracting your back muscles.\r\n4. Lower yourself back to the starting position in a controlled manner, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Use a full range of motion, fully extending your arms at the bottom and pulling up until your chin is above the bar.\r\n2. Focus on engaging your back muscles, particularly the latissimus dorsi, to perform the pull-up effectively.\r\n3. Breathe steadily, exhaling as you pull up and inhaling as you lower yourself down.\r\n4. Avoid using momentum to swing your body; maintain a controlled movement throughout the exercise.\r\n5. Perform the exercise on a stable, secure pull-up bar to ensure safety.', '{"video_url":"videos/Back/pull up wide grip front view .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2d3dd61a-78d0-4fa2-b04e-9275051fbfd7'::uuid, 'Push up and rotation', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a plank position with your hands placed shoulder-width apart and your feet together. Your body should form a straight line from head to heels.\r\n2. Lower your body towards the floor by bending your elbows, keeping them close to your body. Perform a push-up.\r\n3. As you push back up, shift your weight onto your left hand and rotate your torso to the right, raising your right arm towards the ceiling. Your body should form a T-shape.\r\n4. Return your right hand to the floor and lower your body into another push-up. Repeat the movement, this time rotating to the left and raising your left arm towards the ceiling. Alternate sides for the desired number of repetitions.', E'1. Breathe steadily, exhaling as you push up and rotate, and inhaling as you lower your body.\r\n2. Ensure your body forms a straight line during the push-up and rotation, avoiding any sagging or arching of the back.\r\n3. Keep your feet hip-width apart to provide a stable base for the rotation.', '{"image_male_start":"images/Chest/push up and rotation.jpg","image_male_end":"images/Chest/push up and rotation1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d1a3fcf5-d035-4da5-89a6-d5a9833481e1'::uuid, 'Push up plus', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a plank position with your hands placed slightly wider than shoulder-width apart and your feet hip-width apart. Your body should form a straight line from head to heels.\r\n2. Push through your hands to protract your shoulder blades, rounding your upper back slightly.\r\n3. Lower your body towards the floor by bending your elbows, keeping them close to your body to perform a push-up.\r\n4. Return to the plank position. Repeat the sequence for the desired number of repetitions.', E'1. Maintain a straight body line during the push-up, avoiding any sagging or arching of the back.\r\n2. Keep your elbows close to your body during the push-up to effectively target your chest and triceps.\r\n3. Perform the exercise on a stable, non-slip surface to prevent slipping and ensure safety.', '{"image_male_start":"images/Chest/Push up plus.jpg","image_male_end":"images/Chest/Push up plus1.jpg","video_url":"videos/Chest/Push up plus.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('af8c26fd-e652-474e-b58e-a9fb5320ca6f'::uuid, 'Push ups bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a plank position with your hands placed slightly wider than shoulder-width apart and your feet together. Your body should form a straight line from head to heels.\r\n2. Lower your body towards the floor by bending your elbows, keeping them at a 45-degree angle to your body.\r\n3. Lower your chest until it is just above the floor, maintaining a straight body line and keeping your neck neutral.\r\n4. Push through your hands to raise your body back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Keep your core engaged throughout the exercise to maintain a straight body line and avoid sagging your hips.\r\n2. Lower yourself with control, ensuring your chest almost touches the floor while maintaining proper form.\r\n3. Keep your elbows at a 45-degree angle to your body to maximize chest and triceps engagement and reduce shoulder strain.', '{"image_male_start":"images/Chest/push ups bodyweight.jpg","image_male_end":"images/Chest/push ups bodyweight1.jpg","video_url":"videos/Chest/push ups bodyweight.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('57ff88b9-77b0-4f4a-8940-d777360377f4'::uuid, 'Raised leg crunch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your legs straight, vertical to the floor. Place your hands behind your head with your elbows pointing outwards.\r\n2. Engage your core and lift your shoulders off the floor, bringing your chest towards your knees. \r\n3. Hold the top position for a moment, squeezing your abdominal muscles.\r\n4. Lower your shoulders back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Avoid pulling on your neck with your hands; instead, use your abdominal muscles to lift your shoulders.\r\n2. Breathe steadily, exhaling as you lift your shoulders and inhaling as you lower them.\r\n3. Keep your lower back pressed against the floor to prevent strain and maintain proper form.\r\n4. Perform the exercise on a comfortable, non-slip surface to ensure safety and reduce discomfort.\r\n', '{"image_male_start":"images/Abdominals/raised leg crunch.jpeg","video_url":"videos/Abdominals/raised leg crunch .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('81e473eb-2973-48a6-bd8d-fa130b0b8107'::uuid, 'Reaching up shoulder stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Stand upright with your feet shoulder-width apart.\r\n2. Bend your right elbow and bring your right arm behind your back, raising your hand upward with your palm facing out.\r\n3. Hold the stretch for 15-30 seconds, then slowly release and return to the starting position. Repeat on the other side by bending your left elbow and using your right hand to assist with the stretch.', E'1. Move slowly and with control to avoid any sudden movements that could cause strain.\r\n2. Keep your core engaged to maintain balance and support your lower back.\r\n3. Avoid arching your back; keep your spine neutral to maximize the stretch and prevent injury.', '{"image_male_start":"images/Shoulders/reaching up shoulder stretch .jpg","video_url":"videos/Shoulders/reaching up shoulder stretch .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2c7198ab-5d16-43f2-8e82-ad453277b12b'::uuid, 'Rear deltoid fly cable Resistance band', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Attach the resistance band to a shoulder height anchor point in front of you. Stand with your feet shoulder-width apart and hold the handles with both hands, arms extended straight in front of you at shoulder height, palms facing each other.\r\n2. Pull the handles out to your sides by extending your arms and squeezing your shoulder blades together, keeping a slight bend in your elbows.\r\n3. Slowly return your arms to the starting position with control. \r\n4. Repeat for the desired number of repetitions.', E'1. Exhale as you pull the handles apart and inhale as you return to the starting position.\r\n2. Use a lighter resistance band if needed to ensure proper form and gradually increase the resistance as you get stronger.\r\n3. Focus on engaging your rear deltoid and upper back muscles throughout the movement.', '{"image_male_start":"images/Shoulders/rear deltoid fly cable resistance band .jpg","video_url":"videos/Shoulders/rear deltoid fly cable resistance band .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('647a032f-5d51-4383-8c87-b54c97f457ed'::uuid, 'Rear deltoid stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Stand upright with your feet shoulder-width apart.\r\n2. Extend your right arm, slightly bent, across your body at shoulder height.\r\n3. Use your left hand to gently pull your right arm towards your chest, feeling the stretch in the rear deltoid.\r\n4. Hold the stretch for 15-30 seconds, then slowly release and return to the starting position. Repeat on the other side by extending your left arm and using your right hand to assist with the stretch.', E'1. Keep your shoulders relaxed and away from your ears to maximize the stretch.\r\n2. Avoid twisting your torso; keep your upper body facing forward.\r\n3. Move slowly and with control to avoid any sudden movements that could cause strain.\r\n', '{"image_male_start":"images/Stretching - Mobility/rear deltoid stretch.jpg","image_male_end":"images/Stretching - Mobility/rear deltoid stretch1.jpg","video_url":"videos/Stretching - Mobility/rear deltoid stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7b6296dd-52a4-4d7a-a4d3-a697dae10411'::uuid, 'Resistance band - cable row', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Attach a resistance band to a sturdy anchor point at chest height. Kneel on one knee with the opposite leg forward, foot flat on the ground. \r\n2. Hold the band handles with both hands, arms extended forward, and palms facing down.\r\n3. Pull the band handles towards your chest by bending your elbows and squeezing your shoulder blades together at the end of the movement.\r\n4. Return to the starting position with control. Repeat for the desired repetitions.', E'1. Focus on squeezing your shoulder blades together at the peak of the row to maximize back activation.\r\n2. Adjust the resistance band tension or your kneeling position for an appropriate challenge.\r\n3. Avoid shrugging your shoulders; keep them down and relaxed.', '{"image_male_start":"images/Back/resistance band - cable row .jpg","video_url":"videos/Back/resistance band - cable row .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('424abc6d-2805-4792-a4a2-d99feee0497b'::uuid, 'Resistance Band Assisted Front Rack Stretch', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand in the middle of a weight cage with a horizontal bar at chest level. Place the resistance band under your left foot and hold the other end of the band with your left hand.\r\n2. Bring your left elbow up and rest it on the horizontal bar, allowing your forearm to lean backward. The band should extend down by your shoulder, creating tension.\r\n3. Slowly allow your forearm to lean back to increase the stretch in your shoulder, keeping your hand close to your shoulder.\r\n4. Hold the stretch for 20-30 seconds, then slowly release the tension and switch to the other arm.', E'1. Keep your elbow securely on the bar to ensure proper stretch.\r\n2. Allow your forearm to naturally lean back without forcing the movement.\r\n3. Keep a relaxed grip on the band to avoid unnecessary tension.', '{"image_male_start":"images/Stretching - Mobility/Resistance Band Assisted Front Rack Stretch.jpg","image_male_end":"images/Stretching - Mobility/Resistance Band Assisted Front Rack Stretch1.jpg","image_female_start":"images/Stretching - Mobility/Resistance Band Assisted Front Rack Stretch_Female.jpg","image_female_end":"images/Stretching - Mobility/Resistance Band Assisted Front Rack Stretch_Female1.jpg","video_url":"videos/Stretching - Mobility/Resistance Band Assisted Front Rack Stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('de89ed4b-21f8-479c-8528-a2b951ce3838'::uuid, 'Resistance Band Assisted Push-up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Secure two loop elastic bands on a straight bar, ensuring they are securely anchored. Position each band over your shoulders.\r\n2. Set yourself in a plank position with your hands placed slightly wider than shoulder-width apart and your feet together. The resistance bands should provide support as you perform the push-ups.\r\n3. Engage your core and lower your body towards the floor by bending your elbows, keeping them at a 45-degree angle to your body. Allow the resistance bands to assist you as you descend.\r\n4. Push through your hands to raise your body back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Ensure the resistance bands are securely positioned over your shoulders and anchored to the straight bar to provide consistent assistance.\r\n2. Breathe steadily, exhaling as you push up and inhaling as you lower yourself.\r\n3. Lower yourself with control, ensuring your chest almost touches the floor while maintaining proper form.\r\n4. Keep your elbows at a 45-degree angle to your body to maximize chest and triceps engagement and reduce shoulder strain.', '{"image_male_start":"images/Chest/Resistance Band Assisted Push-up.jpg","image_male_end":"images/Chest/Resistance Band Assisted Push-up1.jpg","image_female_start":"images/Chest/Resistance Band Assisted Push-up_Female.jpg","image_female_end":"images/Chest/Resistance Band Assisted Push-up_Female1.jpg","video_url":"videos/Chest/Resistance Band Assisted Push-up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8fc48690-f041-4050-9c50-2f88d1ee3fdb'::uuid, 'Resistance Band Bent Leg Kickback (Kneeling)', 'Resistance', 'strength', 'weight_reps', 'intermediate', '819ba608-6b86-4333-80f2-88416b84445b'::uuid, E'1. Place a loop resistance band around both thighs, just above your knees. Start in a kneeling position on all fours with your hands directly under your shoulders and knees under your hips.\r\n2. Engage your core and keep your back flat. Begin with your left knee bent at a 90-degree angle and your foot flexed.\r\n3. Push your left foot upward towards the ceiling while keeping your knee bent, squeezing your glutes at the top of the movement.\r\n4. Slowly return your leg to the starting position with control. Repeat for the desired number of repetitions, then switch to the right leg.', E'1. Use a loop resistance band that provides enough tension to challenge your muscles without compromising form.\r\n2. Exhale as you kick your leg back and inhale as you return it to the starting position.\r\n3. Focus on engaging your glutes throughout the movement.', '{"image_male_start":"images/Legs/Resistance Band Bent Leg Kickback (Kneeling).jpg","image_male_end":"images/Legs/Resistance Band Bent Leg Kickback (Kneeling)1.jpg","image_female_start":"images/Legs/Resistance Band Bent Leg Kickback (Kneeling)_Female.jpg","image_female_end":"images/Legs/Resistance Band Bent Leg Kickback (Kneeling)_Female1.jpg","video_url":"videos/Legs/Resistance Band Bent Leg Kickback (Kneeling).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e7af364a-d395-4c05-8985-0c6c0e6f0b63'::uuid, 'Resistance Band Calf Press Sitting on Chair', 'Resistance', 'strength', 'weight_reps', 'intermediate', '819ba608-6b86-4333-80f2-88416b84445b'::uuid, E'1. Sit on a chair with your back straight, knees bent at 90 degrees and feet flat hovering just above the floor. Loop a resistance band around your forefeet, holding the ends of the band with your hands.\r\n2. Extend your forefeet downward to point your toes to the floor, pressing against the resistance of the band to engage your calf muscles.\r\n3. Slowly return to the starting position with control, flexing your forefeet back towards you. \r\n4. Repeat for the desired number of repetitions.', E'1. Keep your back straight and avoid leaning forward.\r\n2. Keep your hands steady to ensure consistent tension in the band.\r\n3. Exhale as you press your toes forward and inhale as you return them to the starting position.', '{"image_male_start":"images/Legs/Resistance Band Calf Press Sitting on Chair.jpg","image_male_end":"images/Legs/Resistance Band Calf Press Sitting on Chair1.jpg","image_female_start":"images/Legs/Resistance Band Calf Press Sitting on Chair_Female.jpg","image_female_end":"images/Legs/Resistance Band Calf Press Sitting on Chair_Female1.jpg","video_url":"videos/Legs/Resistance Band Calf Press Sitting on Chair.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0265d3ed-a22a-4650-b554-72fd301c6950'::uuid, 'Resistance Band Clam', 'Resistance', 'strength', 'weight_reps', 'intermediate', '819ba608-6b86-4333-80f2-88416b84445b'::uuid, E'1. Place a loop resistance band around your thighs, just above your knees. Lie on your side with your legs bent at a 90-degree angle and your feet stacked together.\r\n2. Rest your head on your bottom arm and place your top hand on the floor for stability.\r\n3. Keeping your feet together, lift your top knee as high as you can without moving your pelvis or back, squeezing your glutes at the top of the movement.\r\n4. Slowly return your knee to the starting position with control. Repeat for the desired number of repetitions, then switch to the other side.', E'1. Keep your feet together to ensure proper form and muscle activation.\r\n2. Exhale as you lift your knee and inhale as you lower it back down.\r\n3. Ensure your head and neck remain aligned with your spine for comfort.', '{"image_male_start":"images/Legs/Resistance Band Clam.jpg","image_male_end":"images/Legs/Resistance Band Clam1.jpg","image_female_start":"images/Legs/Resistance Band Clam_Female.jpg","image_female_end":"images/Legs/Resistance Band Clam_Female1.jpg","video_url":"videos/Legs/Resistance Band Clam.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('31ba06af-05e2-41a0-b575-3e9f54d7cd96'::uuid, 'Resistance Band Cross Body Single Straight Arm Supinated Pulldown', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Attach the resistance band to a high anchor point in front of you, on your left side. Stand with your feet shoulder-width apart, holding the handle with your right hand, palm facing up.\r\n2. Extend your right arm straight opposite the left side of your head, keeping your arm straight.\r\n3. Pull the handle down across your body towards your right hip until fully extended by your side and slowly return to the starting position.\r\n4. Repeat for the desired number of repetitions, then switch to the other side.', E'1. Exhale as you pull the band down and inhale as you release it back up.\r\n2. Focus on pulling with your back muscles rather than your arm for better engagement.\r\n3. Ensure your hips stay square and stable, avoiding any twisting motion.', '{"image_male_start":"images/Back/Resistance Band Cross Body Single Straight Arm Supinated Pulldown.jpg","image_male_end":"images/Back/Resistance Band Cross Body Single Straight Arm Supinated Pulldown1.jpg","video_url":"videos/Back/Resistance Band Cross Body Single Straight Arm Supinated Pulldown.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7f0d4709-bb86-45a3-bb84-fef792dc1f6e'::uuid, 'Resistance band face pull', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Attach a resistance band to an anchor point at face height. Stand facing the anchor point with your feet shoulder-width apart, holding the handles with both hands, palms facing down.\r\n2. Step back to create tension in the band and extend your arms straight in front of you at shoulder height.\r\n3. Pull the handles towards your face by bending your elbows and spreading them out to the sides, keeping your upper arms parallel to the floor.\r\n4. Slowly return to the starting position with control and repeat for the desired number of repetitions.', E'1. Exhale as you pull the handles towards your face and inhale as you return to the starting position.\r\n2. Use a lighter resistance band if needed to ensure proper form and gradually increase the resistance as you get stronger.\r\n3. Focus on engaging your upper back and rear shoulders throughout the movement.', '{"image_male_start":"images/Shoulders/Resistance band face pull.jpg","image_male_end":"images/Shoulders/Resistance band face pull1.jpg","video_url":"videos/Shoulders/Resistance band face pull.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('81450002-d997-4202-beaf-0731e3816083'::uuid, 'Resistance Band Floor Hyperextension', 'Resistance', 'strength', 'weight_reps', 'intermediate', '819ba608-6b86-4333-80f2-88416b84445b'::uuid, E'1. Lie face down on the floor with a loop resistance band over your ankles and another loop resistance band over your forearms. Extend your arms forward and keep your legs straight.\r\n2. Engage your core and glutes, and lift your chest and legs off the floor simultaneously, spreading your legs apart against the resistance of the band.\r\n3. Squeeze your lower back muscles at the top of the movement, keeping your arms and legs straight.\r\n4. Slowly lower your chest and legs back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep your neck in a neutral position to avoid straining it.\r\n2. Focus on engaging your lower back and glute muscles throughout the movement.\r\n3. Exhale as you lift your chest and legs and inhale as you lower them back down.', '{"image_male_start":"images/Back/Resistance Band Floor Hyperextension.jpg","image_male_end":"images/Back/Resistance Band Floor Hyperextension1.jpg","video_url":"videos/Back/Resistance Band Floor Hyperextension.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c57051ec-17ae-453d-a160-57a3274c22d3'::uuid, 'Resistance Band Glute Bridge', 'Resistance', 'strength', 'weight_reps', 'intermediate', '819ba608-6b86-4333-80f2-88416b84445b'::uuid, E'1. Lie on your back with your knees bent and feet flat on the floor, hip-width apart. Place a loop resistance band just above your knees. Keep your hands extended by your sides with hands firm on the floor.\r\n2. Engage your core and glutes, and lift your hips towards the ceiling, forming a straight line from your shoulders to your knees.\r\n3. Hold the bridge position for a moment, squeezing your glutes at the top.\r\n4. Slowly lower your hips back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Avoid arching your lower back; keep a straight line from your shoulders to your knees.\r\n2. Focus on engaging your glutes throughout the movement.\r\n3. Exhale as you lift your hips and press your knees outward, and inhale as you bring your knees back together and lower your hips .', '{"image_male_start":"images/Yoga/Resistance Band Glute Bridge_Female.jpg","image_female_start":"images/Yoga/Resistance Band Glute Bridge_Female.jpg","image_female_end":"images/Yoga/Resistance Band Glute Bridge_Female1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ce8435f3-dc88-42ae-9200-3590ce554f64'::uuid, 'Resistance Band Glute Bridge Abduction', 'Resistance', 'strength', 'weight_reps', 'intermediate', '819ba608-6b86-4333-80f2-88416b84445b'::uuid, E'1. Lie on your back with your knees bent and feet flat on the floor, hip-width apart. Place a loop resistance band just above your knees. Keep your hands extended by your sides with hands firm on the floor.\r\n2. Engage your core and glutes, and lift your hips towards the ceiling, forming a straight line from your shoulders to your knees.\r\n3. While holding the bridge position, press your knees outward against the resistance band to stretch them as far as possible.\r\n4. Slowly bring your knees back together, then lower your hips back to the starting position. Repeat for the desired number of repetitions.', E'1. Avoid arching your lower back; keep a straight line from your shoulders to your knees.\r\n2. Focus on engaging your glutes and hip abductors throughout the movement.\r\n3. Exhale as you lift your hips and press your knees outward, and inhale as you bring your knees back together and lower your hips .', '{"image_male_start":"images/Yoga/Resistance Band Glute Bridge Abduction.jpg","image_male_end":"images/Yoga/Resistance Band Glute Bridge Abduction1.jpg","image_female_start":"images/Yoga/Resistance Band Glute Bridge Abduction_Female.jpg","image_female_end":"images/Yoga/Resistance Band Glute Bridge Abduction_Female1.jpg","video_url":"videos/Yoga/Resistance Band Glute Bridge Abduction.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('850a7859-4e97-4b9a-93e5-e46828dffe21'::uuid, 'Resistance Band Glute Bridge_Version2', 'Resistance', 'strength', 'weight_reps', 'intermediate', '819ba608-6b86-4333-80f2-88416b84445b'::uuid, E'1. Lie on your back with your knees bent and feet flat on the floor, hip-width apart. Place a loop resistance band just above your knees. Bring your hands close to your chest and interlock your fingers. \r\n2. Engage your core and glutes, and lift your hips towards the ceiling, forming a straight line from your shoulders to your knees.\r\n3. Hold the bridge position for a moment, squeezing your glutes at the top.\r\n4. Slowly lower your hips back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Avoid arching your lower back; keep a straight line from your shoulders to your knees.\r\n2. Focus on engaging your glutes throughout the movement.\r\n3. Exhale as you lift your hips and press your knees outward, and inhale as you bring your knees back together and lower your hips .', '{"image_male_start":"images/Yoga/Resistance Band Glute Bridge_Version2.jpg","image_male_end":"images/Yoga/Resistance Band Glute Bridge_Version21.jpg","image_female_start":"images/Yoga/Resistance Band Glute Bridge_Version2_Female.jpg","image_female_end":"images/Yoga/Resistance Band Glute Bridge_Version2_Female1.jpg","video_url":"videos/Yoga/Resistance Band Glute Bridge_Version2.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('fb56fbf9-e4bb-408e-926b-09386b0ca9b1'::uuid, 'Resistance Band Hip Thrust (VERSION 2)', 'Resistance', 'strength', 'weight_reps', 'intermediate', '819ba608-6b86-4333-80f2-88416b84445b'::uuid, E'1. Lie on your back with your knees bent and feet flat on the floor, hip-width apart. Place a loop resistance band firmly under your heels and pass it over your thighs close to your hips. Keep your hands extended by your sides with hands firm on the floor.\r\n2. Engage your core and glutes, and lift your hips towards the ceiling, forming a straight line from your shoulders to your knees.\r\n3. Hold the bridge position for a moment, squeezing your glutes at the top.\r\n4. Slowly lower your hips back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Avoid arching your lower back; keep a straight line from your shoulders to your knees.\r\n2. Focus on engaging your glutes throughout the movement.\r\n3. Exhale as you lift your hips and press your knees outward, and inhale as you bring your knees back together and lower your hips .', '{"image_male_start":"images/Legs/Resistance Band Hip Thrust (VERSION 2).jpg","image_male_end":"images/Legs/Resistance Band Hip Thrust (VERSION 2)1.jpg","image_female_start":"images/Legs/Resistance Band Hip Thrust (VERSION 2)_Female.jpg","image_female_end":"images/Legs/Resistance Band Hip Thrust (VERSION 2)_Female1.jpg","video_url":"videos/Legs/Resistance Band Hip Thrust (VERSION 2).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6bb04322-6157-4c44-b1e0-6d1d45f45a9a'::uuid, 'Resistance Band Hip Thrusts on Knees', 'Resistance', 'strength', 'weight_reps', 'intermediate', '819ba608-6b86-4333-80f2-88416b84445b'::uuid, E'1. Kneel on the floor with a loop resistance band anchored at a low point behind you and wrapped around your hips. Keep your back straight and your core engaged.\r\n2. Sit back on your heels, ensuring the resistance band remains taut.\r\n3. Thrust your hips forward, coming up onto your knees and squeezing your glutes at the top of the movement.\r\n4. Slowly lower your hips back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you thrust your hips forward and inhale as you sit back on your heels.\r\n2. Ensure the resistance band stays securely anchored behind you to maintain consistent tension.\r\n3. Focus on engaging your glutes throughout the movement.', '{"image_male_start":"images/Legs/Resistance Band Hip Thrusts on Knees.jpg","image_male_end":"images/Legs/Resistance Band Hip Thrusts on Knees1.jpg","image_female_start":"images/Legs/Resistance Band Hip Thrusts on Knees_Female.jpg","image_female_end":"images/Legs/Resistance Band Hip Thrusts on Knees_Female1.jpg","video_url":"videos/Legs/Resistance Band Hip Thrusts on Knees.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7659162a-1147-4626-9f43-6780ee16a599'::uuid, 'Resistance Band Kneeling Cross Body Single Straight Arm Supinated Pulldown', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Attach the resistance band to a high anchor point in front of you, on your left side. Kneel on the floor on your right knee and your left foot flat on the floor, holding the handle with your right hand, palm facing up.\r\n2. Extend your right arm straight opposite the left side of your head, keeping your arm straight.\r\n3. Pull the handle down across your body towards your right hip until fully extended by your side and slowly return to the starting position.\r\n4. Repeat for the desired number of repetitions, then switch to the other side.', E'1. Exhale as you pull the band down and inhale as you release it back up.\r\n2. Focus on pulling with your back muscles rather than your arm for better engagement.\r\n3. Ensure your hips stay square and stable, avoiding any twisting motion.', '{"image_male_start":"images/Back/Resistance Band Kneeling Cross Body Single Straight Arm Supinated Pulldown.jpg","image_male_end":"images/Back/Resistance Band Kneeling Cross Body Single Straight Arm Supinated Pulldown1.jpg","video_url":"videos/Back/Resistance Band Kneeling Cross Body Single Straight Arm Supinated Pulldown.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('bc7c8457-da4a-482b-acf0-e4532a9f36a9'::uuid, 'Resistance Band Kneeling Leg Half Circle', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Start on all fours with your hands directly under your shoulders and knees under your hips. Attach a loop resistance band around your thighs, just above your knees.\r\n2. Lift your right leg a few inches off the floor and extend it straight back.\r\n3. Move your right leg in a half-circle motion inward over your left leg until it lightly touches the floor, keeping the resistance band taut.\r\n4. Slowly return your right leg to the starting position with control. Repeat for the desired number of repetitions, then switch to the left leg.', E'1. Exhale as you move your leg in the half-circle motion and inhale as you return it to the starting position.\r\n2. Keep your shoulders and hips squared to the floor.\r\n3. Focus on engaging your glutes and hip abductors throughout the movement.', '{"image_male_start":"images/Legs/Resistance Band Kneeling Leg Half Circle.jpg","image_male_end":"images/Legs/Resistance Band Kneeling Leg Half Circle1.jpg","video_url":"videos/Legs/Resistance Band Kneeling Leg Half Circle.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d91e0d12-bb29-4f03-b6e9-80e25001535b'::uuid, 'Resistance Band Kneeling Leg Half Circle on bench', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Start in a tabletop position on a bench, with your hands holding the edges for support and your knees under your hips. Attach a loop resistance band around your thighs, just above your knees.\r\n2. Lift your right leg off the bench and extend it straight back, keeping it under bench level.\r\n3. Move your right leg in a half-circle motion inward over your left leg until it comes in level with the bench, keeping the resistance band taut.\r\n4. Slowly return your right leg to the starting position with control. Repeat for the desired number of repetitions, then switch to the left leg.', E'1. Exhale as you move your leg in the half-circle motion and inhale as you return it to the starting position.\r\n2. Keep your shoulders and hips squared to the floor.\r\n3. Focus on engaging your glutes and hip abductors throughout the movement.', '{"image_male_start":"images/Legs/Resistance Band Kneeling Leg Half Circle on bench.jpg","image_male_end":"images/Legs/Resistance Band Kneeling Leg Half Circle on bench1.jpg","image_female_start":"images/Legs/Resistance Band Kneeling Leg Half Circle on bench_Female.jpg","image_female_end":"images/Legs/Resistance Band Kneeling Leg Half Circle on bench_Female1.jpg","video_url":"videos/Legs/Resistance Band Kneeling Leg Half Circle on bench.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ad889d50-3078-4922-9ec4-a5f627f30e81'::uuid, 'Resistance Band Leg Curl', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart and a loop resistance band around your ankles. Arms are hanging by your sides.\r\n2. Bend your right knee and curl your right leg towards your glutes, keeping your thigh stationary.\r\n3. Slowly return your right leg to the starting position with control, fully extending it. \r\n4. Repeat for the desired number of repetitions, then switch to the left leg.', E'1. Exhale as you curl your leg up and inhale as you extend it back down.\r\n2. Maintain a slight bend in your standing leg for balance.\r\n3. Focus on engaging your hamstrings throughout the movement.', '{"image_male_start":"images/Legs/Resistance Band Leg Curl.jpg","image_male_end":"images/Legs/Resistance Band Leg Curl1.jpg","image_female_start":"images/Legs/Resistance Band Leg Curl_Female.jpg","image_female_end":"images/Legs/Resistance Band Leg Curl_Female1.jpg","video_url":"videos/Legs/Resistance Band Leg Curl.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7e507eb6-d976-4752-b39c-1bf1df3e0868'::uuid, 'Resistance Band Leg Kickback', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Start on all fours with your hands directly under your shoulders and knees under your hips. Place a loop resistance band under your right foot and hold the other end on the floor with your right hand.\r\n2. Kick your right leg backward until it''s parallel to the floor, extending it fully while keeping the resistance band taut.\r\n3. Slowly return your right leg to the starting position with control.\r\n4. Repeat for the desired number of repetitions, then switch to the left leg.', E'1. Exhale as you kick your leg back and inhale as you return it to the starting position.\r\n2. Ensure the resistance band stays securely under your foot and hand to maintain consistent tension.\r\n3. Focus on engaging your glutes throughout the movement.', '{"image_male_start":"images/Legs/Resistance Band Leg Kickback.jpg","image_male_end":"images/Legs/Resistance Band Leg Kickback1.jpg","image_female_start":"images/Legs/Resistance Band Leg Kickback_Female.jpg","image_female_end":"images/Legs/Resistance Band Leg Kickback_Female1.jpg","video_url":"videos/Legs/Resistance Band Leg Kickback.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('499edbfe-1c9b-4d81-87cc-9fb513bd6753'::uuid, 'Resistance Band Lying Abduction', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Lie on your back with your legs extended straight up towards the ceiling and a loop resistance band around your ankles. Place your arms by your sides on the floor for stability.\r\n2. Engage your core and keep your legs straight and feet flexed.\r\n3. Open your legs wide apart against the resistance of the band, keeping your legs straight and maintaining control.\r\n4. Slowly bring your legs back together to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you open your legs and inhale as you bring them back together.\r\n2. Maintain a steady pace to ensure consistent tension on the muscles.\r\n3. Focus on engaging your hip abductors and glute muscles throughout the movement.', '{"image_male_start":"images/Legs/Resistance Band Lying Abduction.jpg","image_male_end":"images/Legs/Resistance Band Lying Abduction1.jpg","image_female_start":"images/Legs/Resistance Band Lying Abduction_Female.jpg","image_female_end":"images/Legs/Resistance Band Lying Abduction_Female1.jpg","video_url":"videos/Legs/Resistance Band Lying Abduction.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('600ff411-bb9c-47ba-9eaf-d7938a668775'::uuid, 'Resistance Band Lying Bent Knee Hip Abduction', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Lie on your back with your knees bent and feet touching together, with a loop resistance band around your thighs, just above your knees. Place your arms on the floor by your sides for stability.\r\n2. Open your knees wide apart against the band''s resistance, keeping your feet together and maintaining control.\r\n3. Slowly bring your knees back together to the starting position with control. \r\n4. Repeat for the desired number of repetitions.', E'1. Use a resistance band with enough tension to challenge your muscles without compromising form.\r\n2. Focus on engaging your hip abductors and glutes throughout the movement.\r\n3. Keep your feet together and avoid lifting them off the floor.', '{"image_male_start":"images/Legs/Resistance Band Lying Bent Knee Hip Abduction.jpg","image_male_end":"images/Legs/Resistance Band Lying Bent Knee Hip Abduction1.jpg","video_url":"videos/Legs/Resistance Band Lying Bent Knee Hip Abduction.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b1c5e1cd-7f41-4286-91ab-991a152119f5'::uuid, 'Resistance Band Lying Bent Knee Raise', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Attach the resistance loop band to a low anchor point and lie on your back with your knees bent and feet touching together. Wrap the other end of the loop resistance band over your feet. Place your arms on the floor by your sides.\r\n2. Keep both legs straight and a few inches off the floor.\r\n3. Slowly bend your knees and bring your legs up until your thighs are perpendicular to the floor and for a 90 degree. \r\n4. Straighten your legs to the starting position with control and repeat for the desired number of repetitions.', E'1. Focus on engaging your abdominals throughout the movement.\r\n2. Avoid lifting your lower back off the floor; keep it pressed down for the duration of the exercise.\r\n3. Maintain a slight bend in your knee if necessary to reduce strain.', '{"image_male_start":"images/Abdominals/Resistance Band Lying Bent Knee Raise.jpeg","video_url":"videos/Abdominals/Resistance Band Lying Bent Knee Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('50aa8732-a1a1-41f2-93b5-97b213b5191d'::uuid, 'Resistance Band Lying Hyperextension Abduction', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Lie face down on the floor with your arms crossed under your head, resting your forehead on your arms. Place a loop resistance band around your thighs, just above your knees. Keep your legs extended and feet together.\r\n2. Engage your core and glutes to lift your legs straight off the floor while resting your head on your arms.\r\n3. While lifting your legs, spread them wide apart against the band''s resistance, keeping your legs straight.\r\n4. Slowly bring your legs back together while lowering them to the starting position with control. Repeat for the desired repetitions.', E'1. Focus on engaging your glutes and hip abductors throughout the movement.\r\n2. Exhale as you lift and open your legs, and inhale as you bring them back together and lower them.\r\n3. Keep your core engaged throughout the exercise to maintain stability and protect your lower back.', '{"image_male_start":"images/Back/Resistance Band Lying Hyperextension Abduction.jpg","image_male_end":"images/Back/Resistance Band Lying Hyperextension Abduction1.jpg","video_url":"videos/Back/Resistance Band Lying Hyperextension Abduction.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f82c0a5e-0a64-4e45-9d36-78b16dbbdb9d'::uuid, 'Resistance Band Lying Leg Raise', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Lie flat on your back with your arms by your sides and a loop resistance band around your thighs, just above your knees. Keep your legs extended and together.\r\n2. Engage your core to lift your right leg straight up towards the ceiling, keeping the resistance band taut and your left leg flat on the floor.\r\n3. Slowly lower your leg back down with control, stopping just before your heel touches the floor.\r\n4. Repeat for the desired number of repetitions, then switch to lifting your left leg.', E'1. Focus on engaging your abdominals throughout the movement.\r\n2. Avoid lifting your lower back off the floor; keep it pressed down for the duration of the exercise.\r\n3. Maintain a slight bend in your knee if necessary to reduce strain.', '{"image_male_start":"images/Legs/Resistance Band Lying Leg Raise.jpg","image_male_end":"images/Legs/Resistance Band Lying Leg Raise1.jpg","image_female_start":"images/Legs/Resistance Band Lying Leg Raise_Female.jpg","image_female_end":"images/Legs/Resistance Band Lying Leg Raise_Female1.jpg","video_url":"videos/Legs/Resistance Band Lying Leg Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4092e581-a301-4485-838c-ad54ccda784e'::uuid, 'Resistance Band One Leg Glute Bridge', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Lie on your back with your knees bent and feet flat on the floor, hip-width apart. Place a loop resistance band around your right thigh, just above your knee, and loop it under your right forefoot.\r\n2. Press through your right heel to lift your hips towards the ceiling, forming a straight line from your shoulders to your knees, while keeping your left leg bent off the floor.\r\n3. Hold the bridge position for a second, then slowly lower your hips back to the starting position with control. \r\n4. Repeat for the desired number of repetitions, then switch to the left leg.', E'1. Focus on engaging your glutes and hamstrings throughout the movement.\r\n2. Exhale as you lift your hips and inhale as you lower them back down.\r\n3. Use a resistance band that provides enough tension to challenge your muscles without compromising form.', '{"image_male_start":"images/Legs/Resistance Band One Leg Glute Bridge.jpg","image_male_end":"images/Legs/Resistance Band One Leg Glute Bridge1.jpg","image_female_start":"images/Legs/Resistance Band One Leg Glute Bridge_Female.jpg","image_female_end":"images/Legs/Resistance Band One Leg Glute Bridge_Female1.jpg","video_url":"videos/Legs/Resistance Band One Leg Glute Bridge.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7360a9e5-f3cf-4c96-9011-bce1d9d6bd2c'::uuid, 'Resistance Band One Leg Kickback (Bent Position)', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Start standing with a loop resistance band around your ankles. Bend forward at your hips, keeping your back straight, and place your hands on an incline bench''s top edge for support.\r\n2. Engage your glutes and lift your right leg off the floor, reaching as high as possible while keeping it straight.\r\n3. Slowly return your right leg to the starting position with control.\r\n4. Repeat for the desired number of repetitions, then switch to the left leg.', E'1. Exhale as you kick your leg back and inhale as you return it to the starting position.\r\n2. Use a resistance band that provides enough tension to challenge your muscles without compromising form.\r\n3. Keep your upper body straight and avoid rounding your back.', '{"image_male_start":"images/Legs/Resistance Band One Leg Kickback (Bent Position).jpg","image_male_end":"images/Legs/Resistance Band One Leg Kickback (Bent Position)1.jpg","image_female_start":"images/Legs/Resistance Band One Leg Kickback (Bent Position)_Female.jpg","image_female_end":"images/Legs/Resistance Band One Leg Kickback (Bent Position)_Female1.jpg","video_url":"videos/Legs/Resistance Band One Leg Kickback (Bent Position).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e4897405-c109-48c7-98b3-f756d36ff90c'::uuid, 'Resistance Band Pull Apart', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart, holding a loop resistance band with both hands. Your arms should be extended straight in front of you at shoulder height, and your palms should be facing down.\r\n2. Pull the resistance band apart by moving your arms out to your sides, squeezing your shoulder blades together, and keeping your arms straight.\r\n3. Slowly return your arms to the starting position with control, maintaining tension in the band. \r\n4. Repeat for the desired number of repetitions.', E'1. Keep your arms straight throughout the exercise, maintaining a slight bend in your elbows.\r\n2. Maintain a neutral wrist position to prevent strain.\r\n3. Focus on engaging your upper back and shoulder muscles throughout the movement.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Resistance Band Pull Apart.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Resistance Band Pull Apart1.jpg","image_female_start":"images/Calisthenics-Cardio-Functional/Resistance Band Pull Apart_Female.jpg","image_female_end":"images/Calisthenics-Cardio-Functional/Resistance Band Pull Apart_Female1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Resistance Band Pull Apart.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c54f08ab-9e8f-46b8-af05-8ac8a7a73838'::uuid, 'Resistance Band Reverse Hyper with Stability Ball on Flat Bench', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Place a flat bench in front of you and lie face down on the bench with your hips on the edge and your legs extended straight behind you. Place a loop resistance band around your thighs, just above your knees, and a stability ball between your feet.\r\n2. Grip the sides of the bench for stability and ensure the stability ball is secure between your feet.\r\n3. Engage your core and glutes, then lift your legs upward, squeezing your glutes and keeping your legs straight.\r\n4. Slowly lower your legs back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep a firm grip on the sides of the bench to maintain stability.\r\n2. Focus on lifting with your glutes and not using momentum.\r\n3. Maintain a steady breathing rhythm, exhaling as you lift and inhaling as you lower your legs.', '{"image_male_start":"images/Legs/Resistance Band Reverse Hyper with Stability Ball on Flat Bench.jpg","image_male_end":"images/Legs/Resistance Band Reverse Hyper with Stability Ball on Flat Bench1.jpg","image_female_start":"images/Legs/Resistance Band Reverse Hyper with Stability Ball on Flat Bench_Female.jpg","image_female_end":"images/Legs/Resistance Band Reverse Hyper with Stability Ball on Flat Bench_Female1.jpg","video_url":"videos/Legs/Resistance Band Reverse Hyper with Stability Ball on Flat Bench.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a1289169-da05-4606-9efc-1006695c0a90'::uuid, 'Resistance Band Seated Bent Knee Abduction', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Sit on the floor with your legs bent at a 90-degree angle and your feet flat on the floor. Place a loop resistance band around your thighs, just above your knees.\r\n2. Engage your core, lean slightly back, and place your hands on the floor behind you for support.\r\n3. Press your knees outward against the resistance of the band, spreading your legs as wide as possible while keeping your feet flat on the floor.\r\n4. Slowly bring your knees back together to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you press your knees outward and inhale as you bring them back together.\r\n2. Keep your feet flat on the floor and avoid lifting them off the floor.\r\n3. Focus on engaging your hip abductors and glutes throughout the movement.\r\n', '{"image_male_start":"images/Legs/Resistance Band Seated Bent Knee Abduction.jpg","image_male_end":"images/Legs/Resistance Band Seated Bent Knee Abduction1.jpg","image_female_start":"images/Legs/Resistance Band Seated Bent Knee Abduction_Female.jpg","image_female_end":"images/Legs/Resistance Band Seated Bent Knee Abduction_Female1.jpg","video_url":"videos/Legs/Resistance Band Seated Bent Knee Abduction.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('78d81329-38bb-42e2-a8f9-29486bb1b341'::uuid, 'Resistance Band Seated Hip Abduction', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Sit on a bench with your legs bent at a 90-degree angle, feet slightly off the floor, and a loop resistance band around your thighs, just above your knees. Place your hands on the bench for support.\r\n2. Engage your core and sit up straight, keeping your back neutral.\r\n3. Press your knees outward against the resistance of the band, opening your legs as wide as possible while keeping your feet slightly elevated.\r\n4. Slowly bring your knees back together to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you press your knees outward and inhale as you bring them back together.\r\n2. Keep your feet slightly off the floor to maintain consistent tension.\r\n3. Focus on engaging your hip abductors and glutes throughout the movement.', '{"image_male_start":"images/Legs/Resistance Band Seated Hip Abduction.jpg","image_male_end":"images/Legs/Resistance Band Seated Hip Abduction1.jpg","image_female_start":"images/Legs/Resistance Band Seated Hip Abduction_Female.jpg","image_female_end":"images/Legs/Resistance Band Seated Hip Abduction_Female1.jpg","video_url":"videos/Legs/Resistance Band Seated Hip Abduction.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3a89ff7d-091f-445b-9f31-a1c2321c4ae8'::uuid, 'Resistance Band Shoulder Adduction', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Attach one end of a resistance band to a sturdy anchor point at a high height. Stand with your left side facing the anchor point, holding the other end of the band with your right hand.\r\n2. Stand with your feet shoulder-width apart. Extend your right arm straight out to the side parallel to the floor, palm facing down.\r\n3. Pull the band towards your body, bringing your right hand close to your hip, keeping your arm straight.\r\n4. Slowly return your right arm to the starting position with control. Repeat for the desired number of repetitions, then switch to the left side.', E'1. Perform the movement slowly and with control to maximize muscle activation and reduce injury risk.\r\n2. Exhale as you pull the band across your body and inhale as you return to the starting position.\r\n3. Use a resistance band that provides enough tension to challenge your muscles without compromising form.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Resistance Band Shoulder Adduction.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Resistance Band Shoulder Adduction1.jpg","image_female_start":"images/Calisthenics-Cardio-Functional/Resistance Band Shoulder Adduction_Female.jpg","image_female_end":"images/Calisthenics-Cardio-Functional/Resistance Band Shoulder Adduction_Female1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Resistance Band Shoulder Adduction.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('97d59e4a-3395-4ef7-ae00-0fe895a23d02'::uuid, 'Resistance Band Side Plank Glute Raise', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Place a loop resistance band around your thighs, just above your knees. Begin by lying on your left side with your legs bent at 90 degrees and stacked on top of each other.\r\n2. Prop yourself up on your left forearm, ensuring your elbow is directly under your shoulder. Engage your core and lift your hips slightly off the floor.\r\n3. Keeping your legs bent, lift your top leg upwards against the resistance of the band while also raising your hips until your torso is parallel to the floor, squeezing your glutes at the top of the movement.\r\n4. Slowly lower your leg and hips back to the starting position with control. Repeat for the desired number of repetitions, then switch to the other side.', E'1. Focus on engaging your glutes and hip abductors throughout the movement.\r\n2. Exhale as you lift your leg and hip, and inhale as you lower it back down.\r\n3. Maintain a steady pace to ensure consistent tension in the muscles.', '{"image_male_start":"images/Legs/Resistance Band Side Plank Glute Raise.jpg","image_male_end":"images/Legs/Resistance Band Side Plank Glute Raise1.jpg","image_female_start":"images/Legs/Resistance Band Side Plank Glute Raise_Female.jpg","image_female_end":"images/Legs/Resistance Band Side Plank Glute Raise_Female1.jpg","video_url":"videos/Legs/Resistance Band Side Plank Glute Raise.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5786ddcd-ec2f-4ec3-834e-835609af747f'::uuid, 'Resistance Band Squat', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart and place a loop resistance band around your thighs, just above your knees. Keep your chest up and bring both hands close to your chest.\r\n2. Lower your body into a squat position by bending your knees and pushing your hips back as if you are sitting in a chair.\r\n3. Push through your heels to stand back up to the starting position, keeping the resistance band taut.\r\n4. Repeat for the desired number of repetitions.', E'1. Keep your chest up and lean slightly forward to maintain proper form.\r\n2. Ensure your knees stay in line with your toes and do not collapse inward.\r\n3. Exhale as you stand up and inhale as you lower into the squat.', '{"image_male_start":"images/Legs/Resistance Band Squat.jpg","image_male_end":"images/Legs/Resistance Band Squat1.jpg","image_female_start":"images/Legs/Resistance Band Squat_Female.jpg","image_female_end":"images/Legs/Resistance Band Squat_Female1.jpg","video_url":"videos/Legs/Resistance Band Squat.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b9907e10-d29e-42df-b243-2306ec0c2311'::uuid, 'Resistance Band Squat Jump', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart and place a loop resistance band around your thighs, just above your knees. Keep your chest up and bring both hands close to your chest.\r\n2. Lower your body into a squat position by bending your knees and pushing your hips back as if you are sitting in a chair.\r\n3. Explosively jump up by pushing through your heels extending your legs fully and reaching your arms upward.\r\n4. Land softly back into the squat position, absorbing the impact through your legs. Repeat for the desired number of repetitions.', E'1. Land softly with your knees slightly bent to reduce impact on your joints.\r\n2. Perform the movement with control, especially when landing, to maximize muscle activation and reduce injury risk.\r\n3. Exhale as you jump up and inhale as you lower into the squat.', '{"image_male_start":"images/Legs/Resistance Band Squat Jump.jpg","image_male_end":"images/Legs/Resistance Band Squat Jump1.jpg","image_female_start":"images/Legs/Resistance Band Squat Jump_Female.jpg","image_female_end":"images/Legs/Resistance Band Squat Jump_Female1.jpg","video_url":"videos/Legs/Resistance Band Squat Jump.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1cbbefe7-de87-41e8-839e-98e72f28ebba'::uuid, 'Resistance Band Standing Balance Glute Kickback', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart and place a loop resistance band around your ankles. Place your hands on your hips for balance.\r\n2. Shift your weight onto your right leg and lift your left foot slightly off the floor.\r\n3. Keeping your right leg straight, kick it back and upward against the band''s resistance, squeezing your glutes at the top of the movement.\r\n4. Slowly return your left leg to the starting position with control. Repeat for the desired number of repetitions, then switch to the right leg.', E'1. Maintain a slight bend in your standing leg for balance.\r\n2. Exhale as you kick your leg back and inhale as you return it to the starting position.\r\n3. Use a resistance band that provides enough tension to challenge your muscles without compromising form.', '{"image_male_start":"images/Legs/Resistance Band Standing Balance Glute Kickback.jpg","image_male_end":"images/Legs/Resistance Band Standing Balance Glute Kickback1.jpg","image_female_start":"images/Legs/Resistance Band Standing Balance Glute Kickback_Female.jpg","image_female_end":"images/Legs/Resistance Band Standing Balance Glute Kickback_Female1.jpg","video_url":"videos/Legs/Resistance Band Standing Balance Glute Kickback.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('fecfb591-6f4c-476d-a8db-cd92be86871c'::uuid, 'Resistance Band Standing Balance Glute Kickback (VERSION 2)', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart and place a loop resistance band around your thighs, just above your knees. Place your hands on your hips for balance.\r\n2. Shift your weight onto your right leg and lift your left foot slightly off the floor.\r\n3. Keeping your right leg straight, kick it back and upward against the band''s resistance, squeezing your glutes at the top of the movement.\r\n4. Slowly return your left leg to the starting position with control. Repeat for the desired number of repetitions, then switch to the right leg.', E'1. Maintain a slight bend in your standing leg for balance.\r\n2. Exhale as you kick your leg back and inhale as you return it to the starting position.\r\n3. Use a resistance band that provides enough tension to challenge your muscles without compromising form.', '{"image_male_start":"images/Legs/Resistance Band Standing Balance Glute Kickback (VERSION 2).jpg","image_male_end":"images/Legs/Resistance Band Standing Balance Glute Kickback (VERSION 2)1.jpg","image_female_start":"images/Legs/Resistance Band Standing Balance Glute Kickback (VERSION 2)_Female.jpg","image_female_end":"images/Legs/Resistance Band Standing Balance Glute Kickback (VERSION 2)_Female1.jpg","video_url":"videos/Legs/Resistance Band Standing Balance Glute Kickback (VERSION 2).mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('22ce77d2-b611-4027-8126-592d78a78a63'::uuid, 'Resistance Band Standing Balance Hip Abduction', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart and place a loop resistance band around your thighs, just above your knees. Place your hands on your hips for balance.\r\n2. Shift your weight onto your right leg and lift your left foot slightly off the floor.\r\n3. Keeping your left leg straight, lift it to the side against the band''s resistance, squeezing your hip abductors at the top of the movement.\r\n4. Slowly return your leg to the starting position with control. Repeat for the desired number of repetitions, then switch to the right leg.', E'1. Exhale as you lift your leg and inhale as you return it to the starting position.\r\n2. Maintain a slight bend in your standing leg for balance.\r\n3. Keep your upper body straight and avoid leaning to the side.', '{"image_male_start":"images/Legs/Resistance Band Standing Balance Hip Abduction.jpg","image_male_end":"images/Legs/Resistance Band Standing Balance Hip Abduction1.jpg","image_female_start":"images/Legs/Resistance Band Standing Balance Hip Abduction_Female.jpg","image_female_end":"images/Legs/Resistance Band Standing Balance Hip Abduction_Female1.jpg","video_url":"videos/Legs/Resistance Band Standing Balance Hip Abduction.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b31489fb-dcae-44f9-80b1-7b751580b7af'::uuid, 'Resistance Band Standing External Rotation', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart and place a loop resistance band around your wrists. Keep your elbows bent at 90 degrees and close to your sides, with your forearms parallel to the floor and pointing forward.\r\n2. Rotate your shoulders outwards by pulling the resistance band apart while keeping your elbows fixed at your sides.\r\n3. Slowly return your forearms to the starting position with control, maintaining tension in the band. \r\n4. Repeat for the desired number of repetitions.', E'1. Perform the movement slowly and with control to maximize muscle activation and reduce shoulder injury risk.\r\n2. Exhale as you rotate your forearms outward and inhale as you return them to the starting position.\r\n3. Keep your elbows fixed at your sides to ensure proper form.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Resistance Band Standing External Rotation.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Resistance Band Standing External Rotation1.jpg","image_female_start":"images/Calisthenics-Cardio-Functional/Resistance Band Standing External Rotation_Female.jpg","image_female_end":"images/Calisthenics-Cardio-Functional/Resistance Band Standing External Rotation_Female1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Resistance Band Standing External Rotation.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e68c6e17-be3c-4f53-9321-c5f36500dacd'::uuid, 'Resistance Band Standing Hip Abduction', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart and place a loop resistance band around your thighs, just above your knees. Bend your hips and knees to lower into a half-squat position, and lean your back slightly forward, keeping your back straight.\r\n2. Press your knees outward against the band''s resistance, opening your legs as wide as possible.\r\n3. Slowly bring your knees back together to the starting position with control, keeping tension in the band.\r\n4. Repeat the movement for the desired number of repetitions, maintaining the half squat position.', E'1. Exhale as you press your knees outward and inhale as you bring them back together.\r\n2. Use a resistance band that provides enough tension to challenge your muscles without compromising form.\r\n3. Ensure your feet remain flat on the floor and your weight is evenly distributed.', '{"image_male_start":"images/Legs/Resistance Band Standing Hip Abduction.jpg","image_male_end":"images/Legs/Resistance Band Standing Hip Abduction1.jpg","image_female_start":"images/Legs/Resistance Band Standing Hip Abduction_Female.jpg","image_female_end":"images/Legs/Resistance Band Standing Hip Abduction_Female1.jpg","video_url":"videos/Legs/Resistance Band Standing Hip Abduction.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('644e69f5-78bb-480c-a56b-3e6c14f283f9'::uuid, 'Resistance Band Standing Single Arm Shoulder Extension', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Attach one end of a resistance band to a sturdy anchor point at hips height. Stand facing the anchor point and hold the other end of the band in your right hand.\r\n2. Extend your right arm up, pointing to the anchor point, with your palm facing down.\r\n3. Pull the band backward, keeping your arm straight, and until it reaches parallel to your side.\r\n4. Slowly return your arm to the starting position with control. Repeat for the desired number of repetitions, then switch to the left arm.', E'1. Focus on engaging your shoulder and upper back muscles throughout the movement.\r\n2. Keep your elbow slightly bent to reduce strain on your joints.\r\n3. Ensure the resistance band stays taut throughout the exercise.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Resistance Band Standing Single Arm Shoulder Extension.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Resistance Band Standing Single Arm Shoulder Extension1.jpg","image_female_start":"images/Calisthenics-Cardio-Functional/Resistance Band Standing Single Arm Shoulder Extension_Female.jpg","image_female_end":"images/Calisthenics-Cardio-Functional/Resistance Band Standing Single Arm Shoulder Extension_Female1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Resistance Band Standing Single Arm Shoulder Extension.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('239bc35f-b3c4-40ce-86b4-c139ebb0d855'::uuid, 'Resistance Band Standing Single Arm Shoulder Flexion', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Attach one end of a resistance band to a sturdy anchor point at hips height. Stand with your back facing the anchor point and hold the other end of the band in your right hand.\r\n2. Extend your right arm back, pointing to the anchor point, with your palm facing forward.\r\n3. Pull the band forward, keeping your arm straight, and until it reaches your lower chest height.\r\n4. Slowly return your arm to the starting position with control. Repeat for the desired number of repetitions, then switch to the left arm.', E'1. Focus on engaging your shoulder and upper back muscles throughout the movement.\r\n2. Keep your elbow slightly bent to reduce strain on your joints.\r\n3. Ensure the resistance band stays taut throughout the exercise.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Resistance Band Standing Single Arm Shoulder Flexion.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Resistance Band Standing Single Arm Shoulder Flexion1.jpg","image_female_start":"images/Calisthenics-Cardio-Functional/Resistance Band Standing Single Arm Shoulder Flexion_Female.jpg","image_female_end":"images/Calisthenics-Cardio-Functional/Resistance Band Standing Single Arm Shoulder Flexion_Female1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Resistance Band Standing Single Arm Shoulder Flexion.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('699dbfdd-797a-42b9-8571-359e44818399'::uuid, 'Resistance Band Upper Body Dead Bug', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Lie flat on your back with your knees bent at a 90-degree angle, knees right above your hips. Attach two loop resistance bands at a low point, extending behind you. \r\n2. Hold the end of each band in each hand, keeping your arms extended straight up towards the ceiling.\r\n3. Lower your right leg towards the floor while keeping your left leg and arms in the starting position.\r\n4. Repeat the movement with your left leg, alternating legs for the desired number of repetitions.', E'1. Exhale as you lower your leg and inhale as you return it to the starting position.\r\n2. Keep your lower back pressed into the floor to avoid strain.\r\n3. Focus on engaging your core muscles throughout the movement.', '{"image_male_start":"images/Yoga/Resistance Band Upper Body Dead Bug_Female.jpeg","video_url":"videos/Yoga/Resistance Band Upper Body Dead Bug.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('745e6ae9-6b2e-42eb-9bd9-ec18d2946f18'::uuid, 'Resistance bands facepull', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Secure the middle of the resistance band to a sturdy anchor point at head height. Stand facing the anchor point with your feet shoulder-width apart, holding one handle of the band in each hand with your arms extended straight in front of you, palms facing down.\r\n2. Pull the handles towards your face, bending your elbows and flaring them out to the sides until your hands are at your face sides.\r\n3. Squeeze your shoulder blades together at the end of the movement, keeping your upper arms parallel to the floor.\r\n4. Slowly extend your arms back to the starting position with control, maintaining tension in the band. Repeat for the desired number of repetitions.', E'1. Ensure the resistance band is securely anchored to avoid slipping.\r\n2. Exhale as you pull the band towards your face and inhale as you return to the starting position.\r\n3. Maintain a slight bend in your knees for better balance and support.', '{"image_male_start":"images/Shoulders/resistance bands facepull .jpg","video_url":"videos/Shoulders/resistance bands facepull .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('527f5371-08c2-4c12-9f75-48fecf6e3e04'::uuid, 'Reverse Ab Wheel Rollout', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '9ffbc39a-4891-4f46-b1f7-17bd2c6b7261'::uuid, E'1. Begin in a plank position with your hands on the floor, arms straight, and the ab roller set under your feet. Your legs should be straight back, forming a straight line from head to heels.\r\n2. Engage your core and slowly roll the ab roller towards your hands, keeping your legs straight. Continue rolling until your thighs are vertical to the floor.\r\n3. Hold the position briefly, ensuring your core is tight and your back is straight.\r\n4. Roll the ab roller back to the starting position with control, maintaining a straight line with your body. Repeat for the desired number of repetitions.', E'1. Breathe steadily, exhaling as you roll the roller towards your hands and inhaling as you return to the starting position.\r\n2. Avoid arching your back; maintain a neutral spine to prevent strain on your lower back.\r\n3. Start with a small range of motion if you are new to this exercise, gradually increasing the distance as you build strength.\r\n4. Perform the exercise on a stable, non-slip surface to ensure safety and prevent slipping.', '{"image_male_start":"images/Abdominals/Reverse Ab Wheel Rollout_Female.jpeg","video_url":"videos/Abdominals/Reverse Ab Wheel Rollout.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('fe2a0242-763f-470d-83f5-daf47daa9b48'::uuid, 'Reverse cable fly on crossover', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand in the center of a cable crossover machine with the pulleys set at shoulder height. Grasp the left handle with your right hand and the right handle with your left hand, crossing the cables in front of you and palms facing the floor.\r\n2. Stand with your feet shoulder-width apart and keep your back straight. Extend your arms straight in front of you at chest height, palms facing down.\r\n3. Pull the handles outwards and backward in a reverse fly motion, keeping your arms straight, until both arms are fully extended to your sides.\r\n4. Slowly return your arms to the starting position with control. Repeat for the desired number of repetitions.', E'1. Exhale as you pull the handles outward and inhale as you return to the starting position.\r\n2. Keep your elbows slightly bent to reduce strain on your joints.\r\n3. Focus on engaging your upper back and shoulder muscles throughout the movement.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a97cf647-adbb-418c-a993-bfafa527092d'::uuid, 'Reverse crunch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your knees bent and feet flat on the floor. Place your arms by your sides with palms facing down for stability.\r\n2. Lift your legs off the floor, bending your knees at a 90-degree angle so that your thighs are perpendicular to the floor and your calves are parallel to the floor.\r\n3. Engage your core and lift your hips off the floor, curling your knees towards your chest. Focus on using your abdominal muscles to lift your hips.\r\n4. Slowly lower your hips back to the starting position, keeping your knees bent at a 90-degree angle. Repeat for the desired number of repetitions.', E'1. Avoid using momentum to lift your hips; focus on using your abdominal muscles.\r\n2. Breathe steadily, exhaling as you lift your hips and inhaling as you lower them back down.\r\n3. Keep your head and shoulders relaxed on the floor to avoid straining your neck.', '{"image_male_start":"images/Abdominals/reverse crunch.jpeg","video_url":"videos/Abdominals/reverse crunch .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('46921132-dcdb-4bda-a695-e7d83a41a104'::uuid, 'Reverse crunch with kick out', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your knees bent and feet flat on the floor. Place your arms by your sides with palms facing down for stability.\r\n2. Lift your legs off the floor, bending your knees at a 90-degree angle so that your thighs are perpendicular to the floor and your calves are parallel to the floor.\r\n3. Extend your legs straight out in front of you, keeping them off the floor to perform a kick-out.\r\n4. Bend your knees back to the starting position and engage your core to lift your hips off the floor, curling your knees towards your chest. Lower your hips back to the starting position. Repeat for the desired number of repetitions.', E'1. Avoid using momentum to lift your hips; focus on using your abdominal muscles.\r\n2. Perform the exercise on a comfortable, non-slip surface to ensure safety and reduce discomfort.\r\n3. Keep your head and shoulders relaxed on the floor to avoid straining your neck.', '{"image_male_start":"images/Abdominals/reverse crunch with kick out.jpeg","video_url":"videos/Abdominals/reverse crunch with kick out .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('41748985-f1c1-46e9-aed8-4846c00817cf'::uuid, 'Reverse grip lat pull down', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd8a6a67e-71db-4542-9dd7-a185a3e773af'::uuid, E'1. Sit at a lat pulldown machine with your feet flat on the floor and knees secured under the pads. Grasp the bar with an underhand grip (palms facing you) at shoulder-width apart, arms fully extended above you.\r\n2. Engage your core and keep your back straight. Lean back slightly to create a natural arch in your lower back.\r\n3. Pull the bar towards your upper chest, bringing your elbows down to your sides while squeezing your shoulder blades together.\r\n4. Slowly return the bar to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Exhale as you pull the bar down and inhale as you return it to the starting position.\r\n2. Avoid using momentum or swinging your body to lift the weight.\r\n3. Keep your wrists straight and avoid letting them bend backward.', '{"image_male_start":"images/Back/reverse grip lat pull down .jpg","video_url":"videos/Back/reverse grip lat pull down .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5b09b886-d7c0-429c-861e-b78f30c32262'::uuid, 'Reverse grip Resistance band simultaneous', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart and place the middle of a resistance band under both feet. Hold one handle in each hand with an overhand grip (palms facing down), arms fully extended by your sides.\r\n2. Simultaneously curl both handles upward towards your shoulders by bending your elbows and squeezing your biceps at the top of the movement.\r\n3. Slowly lower the handles back to the starting position with control, fully extending your arms. \r\n4. Repeat for the desired number of repetitions.', E'1. Exhale as you curl the handles upward and inhale as you lower them back down.\r\n2. Use a resistance band that provides enough tension to challenge your muscles without compromising form.\r\n3. Maintain a steady pace to ensure consistent tension on the muscles.', '{"image_male_start":"images/Biceps/reverse grip resistance band simultaneous.jpeg","video_url":"videos/Biceps/reverse grip resistance band simultaneous .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6fcea5ef-3a99-4ce8-bc43-9ee048da03eb'::uuid, 'Reverse lunge left Resistance band', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart and place the middle of a resistance band under your right foot. Hold one handle in each hand with your arms bent and hands close to your face sides.\r\n2. Step your left foot back into a lunge position, lowering your left knee towards the floor while keeping your right knee over your ankle.\r\n3. Push through your right heel to return to the starting position, bringing your foot forward to stand up straight.\r\n4. Repeat for the desired repetitions, then switch to the left leg.', E'1. Exhale as you push through your heel to stand up and inhale as you lower into the lunge.\r\n2. Keep your front knee aligned with your toes to avoid unnecessary strain.\r\n3. Focus on engaging your glutes and quadriceps throughout the movement.', '{"image_male_start":"images/Legs/reverse lunge left resistance band  .jpg","video_url":"videos/Legs/reverse lunge left resistance band  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0a414634-827c-40ce-b739-abcaec1d86d7'::uuid, 'Reverse machine fly', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'e5090dd6-0740-439b-9454-397339f2ef2e'::uuid, E'1. Sit on a stool with your back straight, knees bent, and feet on the floor.\r\n2. Extend your arms forward and grab the handles of the machine with your palms facing down.\r\n3. Pull the handles by opening your arms wide to your sides.\r\n4. As your arms are aligned with the shoulders, return to the initial position and repeat.', E'1. Exhale as you pull the handles outward and inhale as you return to the starting position.\r\n2. Keep your elbows slightly bent to reduce strain on your joints.\r\n3. Focus on engaging your upper back and shoulder muscles throughout the movement.', '{"image_male_start":"images/Shoulders/reverse machine fly .jpg","video_url":"videos/Shoulders/reverse machine fly .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('751cf08f-bf69-4752-bcea-846e69f1ea24'::uuid, 'Reverse shoulder stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Stand upright with your feet shoulder-width apart, facing away from a hip-level box or surface.\r\n2. Place your hands on the box behind you with your arms straight, palms down.\r\n3. Slowly bend your knees to lower your body, keeping your arms straight and allowing your shoulders to stretch as you lower yourself.\r\n4. Hold the stretch for 15-30 seconds, feeling the stretch in your shoulders and chest. Slowly straighten your legs to return to the starting position.', E'1. Perform the stretch on a stable, non-slip surface to ensure safety and prevent slipping.\r\n2. Keep your shoulders relaxed and away from your ears to maximize the stretch.\r\n3. Ensure your hands are securely positioned on the box to prevent slipping.\r\n', '{"image_male_start":"images/Shoulders/reverse shoulder stretch.jpg","image_male_end":"images/Shoulders/reverse shoulder stretch1.jpg","video_url":"videos/Shoulders/reverse shoulder stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('30360446-994a-400e-a515-5a0543daa87c'::uuid, 'Runner stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Begin in a standing position with your feet hip-width apart.\r\n2. Step your right foot slightly forward, keeping it straight. Lightly bend your left knee.\r\n3. Lower your torso and arms towards your right foot, reaching down with your hands while keeping your back straight.\r\n4. Hold the stretch for 15-30 seconds, feeling the stretch in your right hamstring. Slowly return to the starting position and repeat on the other side.\r\n\r\n', E'1. Ensure your front knee remains straight but not locked to maximize the hamstring stretch.\r\n2. Keep your back leg slightly bent and your heel on the floor to deepen the calf stretch.\r\n3. Perform the stretch on a stable, non-slip surface to ensure safety and prevent slipping.', '{"image_male_start":"images/Stretching - Mobility/runner stretch.jpg","image_male_end":"images/Stretching - Mobility/runner stretch1.jpg","video_url":"videos/Stretching - Mobility/runner stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('117b290e-c1c7-49d2-ad5e-7ac5bde8f361'::uuid, 'Russian twist', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on the floor with your knees bent and feet flat on the floor. Lean back slightly so that your torso forms a V-shape with your thighs.\r\n2. Clasp your hands together in front of your chest.\r\n3. Rotate your torso to the right, bringing your hands opposite your right hip.\r\n4. Rotate back through the center and to the left, bringing your hands opposite your left hip. Continue alternating sides for the desired number of repetitions.', E'1. Move your torso, not just your arms, to ensure you are engaging your oblique muscles.\r\n2. Breathe steadily, exhaling as you rotate to each side and inhaling as you return to the center.\r\n3. Keep your back straight and avoid hunching your shoulders to maintain proper form.\r\n', '{"image_male_start":"images/Abdominals/russian twist.jpeg","video_url":"videos/Abdominals/russian twist .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('37ed1676-b5be-43fc-9794-6e35f0d38ce2'::uuid, 'Russian twist weighted ball', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on the floor with your knees bent and feet flat. Hold a weighted ball with both hands, keeping it opposite to your chest with straight arms.\r\n2. Lean back slightly, keeping your back straight.\r\n3. Rotate your torso to the right, bringing the weighted ball towards the floor beside your hip.\r\n4. Rotate your torso to the left, moving the weighted ball towards the floor beside your left hip. Repeat the twisting motion for the desired number of repetitions.', E'1. Engage your core throughout the movement to maintain balance and stability.\r\n2. Ensure your movements are smooth and controlled to maximize core engagement.\r\n3. Focus on twisting from your torso, not just moving your arms side to side.', '{"image_male_start":"images/Abdominals/russian twist weighted ball.jpeg","video_url":"videos/Abdominals/russian twist weighted ball.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5e336d2c-e678-4214-b0c7-e86914fa7c47'::uuid, 'Scapula push up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a plank position with your hands directly under your shoulders and your body forming a straight line from head to heels. Keep your feet hip-width apart.\r\n2. Without bending your elbows, squeeze your shoulder blades together, allowing your chest to lower slightly towards the floor. \r\n3. Push your shoulder blades apart, rounding your upper back slightly and lifting your chest away from the floor. \r\n4. Continue to alternate between the retraction and protraction phases for the desired number of repetitions, maintaining a steady and controlled movement.', E'1. Breathe steadily, exhaling as you protract and inhaling as you retract your shoulder blades.\r\n2. Maintain a straight body line, avoiding any sagging or arching of the back.\r\n3. Perform the exercise on a stable, non-slip surface to ensure safety and prevent slipping.', '{"image_male_start":"images/Yoga/Scapula push up.jpg","image_male_end":"images/Yoga/Scapula push up1.jpg","video_url":"videos/Yoga/Scapula push up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('62c63055-05b4-4a96-a7af-162bd34c20cb'::uuid, 'Scissors kick', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your legs extended and your arms by your sides, palms facing down.\r\n2. Lift both legs off the floor a few inches, keeping them straight.\r\n3. Alternately cross your legs over each other in a scissor-like motion. Move your right leg over your left leg and then switch, bringing your left leg over your right leg.\r\n4. Continue alternating legs in a controlled manner for the desired number of repetitions or duration.', E'1. Ensure your lower back remains pressed against the floor to avoid strain and maintain proper form.\r\n2. Move your legs slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Perform the exercise on a comfortable, non-slip surface to ensure safety and reduce discomfort.\r\n4. Avoid letting your legs drop too low, which could increase strain on your lower back.\r\n', '{"image_male_start":"images/Abdominals/scissors kick.jpeg","video_url":"videos/Abdominals/scissors kick .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1e317ddf-5216-4dda-afd0-ad55d9086dc8'::uuid, 'Seated cable row V bar machine', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'b7ec08fd-b7eb-4a14-a54d-f3d91be90da6'::uuid, E'1. Sit on the cable row machine with your feet secure on the foot platform. Grasp the V bar with both hands.\r\n2. Sit upright with your back straight, extending your arms fully in front of you.\r\n3. Pull the V bar towards your abdomen by bringing your elbows back and squeezing your shoulder blades together.\r\n4. Slowly extend your arms back to the starting position. Repeat for the desired repetitions.', E'1. Keep your back straight throughout the exercise to avoid strain.\r\n2. Engage your core to maintain stability and proper posture.\r\n3. Perform the movement slowly and with control to maximize muscle activation and reduce the risk of injury.', '{"image_male_start":"images/Back/seated cable row V bar machine .jpg","video_url":"videos/Back/seated cable row V bar machine .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('fc52157a-23c2-43c0-b409-0d137c4be5b0'::uuid, 'Seated calf machine', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on the calf raise machine with your forefeet positioned on the foot platform and your knees secured under the padded lever.\r\n2. Hold the handles with both hands and allow your heels to lower as far as possible, fully stretching your calves.\r\n3. Press through your forefeet to lift your heels as high as possible, then slowly lower your heels back to the starting position.\r\n4. Repeat for the desired repetitions.\r\n', E'1. Keep your back straight and torso still throughout the exercise.\r\n2. Maintain tension in the calves from start to finish.\r\n3. Lower your heels slowly to emphasize the eccentric portion of the lift.', '{"image_male_start":"images/Legs/seated calf machine  .jpg","video_url":"videos/Legs/seated calf machine  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('de42072e-5861-4d03-9793-4a604ea99114'::uuid, 'Seated calf raises dumbbell on knee', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench with your forefeet on the edge of a plate, close together, allowing your heels to hang off. Place a dumbbell on both knees, holding them securely with your hands.\r\n2. Raise your heels as high as possible, pushing through your forefeet and lifting the dumbbells.\r\n3. Lower your heels back down to the starting position in a controlled manner. Repeat for the desired number of repetitions, then switch to the left leg and repeat.', E'1. Focus on using your calf muscles to lift and lower your heel.\r\n2. Keep the movement slow and controlled to maximize muscle engagement.\r\n3. Avoid bouncing or using momentum to lift the weight.', '{"image_male_start":"images/Legs/Seated calf raises dumbbell on knee.jpg","image_male_end":"images/Legs/Seated calf raises dumbbell on knee1.jpg","video_url":"videos/Legs/Seated calf raises dumbbell on knee.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e78095a8-c1a8-481d-81be-c39f19feabda'::uuid, 'Seated calf stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Sit on the floor with your legs extended straight in front of you. Keep your back straight and your core engaged.\r\n2. Extend your right foot while lightly bending the left knee, reaching forward to grasp your toes with both hands.\r\n3. Gently pull your toes towards you, feeling the stretch in your calf muscle.\r\n4. Hold the stretch for 15-30 seconds, then slowly release. Repeat on the left leg.', E'1. Focus on maintaining a straight back to enhance the effectiveness of the stretch.\r\n2. Ensure your movements are slow and controlled to prevent overstretching or injury.\r\n3. If you find it difficult to reach your toes, use a towel or strap for assistance without forcing the stretch.\r\n4. Keep your shoulders relaxed and away from your ears to prevent unnecessary tension.\r\n', '{"image_male_start":"images/Stretching - Mobility/seated calf stretch.jpg","image_male_end":"images/Stretching - Mobility/seated calf stretch1.jpg","video_url":"videos/Stretching - Mobility/seated calf stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d0d782dc-c95a-4473-a415-b9bc11bb8b14'::uuid, 'Seated cross leg glute stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Sit on the floor with your legs extended straight in front of you.\r\n2. Bend your right knee and cross your right leg over your left thigh and lightly bend your left knee placing your left foot flat on the floor.\r\n3. Keeping your back straight, lower your chest towards your crossed leg, reaching your hands stright to the floor to deepen the stretch.\r\n4. Hold the stretch for 15-30 seconds, feeling the stretch in your right glute. Slowly release and return to the starting position. Repeat on the left side.', E'1. Maintain a straight back as you lower your chest to enhance the effectiveness of the stretch.\r\n2. Move slowly and with control to prevent any sudden movements that could cause strain.\r\n3. Ensure your bent knees remains stable and aligned with your body to avoid placing excess strain on the knee joints.', '{"image_male_start":"images/Yoga/seated cross leg glute stretch.jpg","image_male_end":"images/Yoga/seated cross leg glute stretch1.jpg","video_url":"videos/Yoga/seated cross leg glute stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('faab8772-f824-43ec-86ff-e392b7480801'::uuid, 'Seated dumbbell one arm shoulder press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on a bench with back support, holding a dumbbell in your right hand at shoulder height, palm facing forward. Keep your back straight and feet flat on the floor.\r\n2. Press the dumbbell upward until your arm is fully extended overhead, keeping your wrist straight.\r\n3. Lower the dumbbell back to shoulder height with control.\r\n4. Repeat for the desired number of repetitions, then switch to your left arm and repeat.', E'1. Avoid arching your back; keep it pressed against the backrest of the bench.\r\n2. Move the dumbbell in a straight line to maximize muscle engagement.\r\n3. Exhale as you press the dumbbell up and inhale as you lower it.', '{"image_male_start":"images/Shoulders/seated dumbbell one arm shoulder press.jpg","image_male_end":"images/Shoulders/seated dumbbell one arm shoulder press1.jpg","video_url":"videos/Shoulders/seated dumbbell one arm shoulder press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9d73a527-0414-4c2b-8fab-af43cc0e10a8'::uuid, 'Seated dumbbell rear delt fly', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Sit on the edge of a bench with your feet flat on the floor and a dumbbell in each hand. Lean forward at your hips until your chest is close to your thighs, letting your arms hang down towards the floor with palms facing each other.\r\n2. With a slight bend in your elbows, raise the dumbbells out to the sides until your arms are parallel to the floor.\r\n3. Squeeze your shoulder blades together at the top of the movement.\r\n4. Lower the dumbbells back to the starting position in a controlled manner.', E'1. Keep your back straight and avoid rounding your shoulders.\r\n2. Exhale as you lift the dumbbells and inhale as you lower them.\r\n3. Avoid swinging the weights or using momentum to lift the dumbbells.', '{"image_male_start":"images/Shoulders/seated dumbbell rear delt fly.jpg","image_male_end":"images/Shoulders/seated dumbbell rear delt fly1.jpg","video_url":"videos/Shoulders/seated dumbbell rear delt fly.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ce903ffc-a70d-4484-9291-d985c510858a'::uuid, 'Seated floor crunches', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on the floor with your legs extended straight out in front of you, forming an L-shape with your torso.\r\n2. Place your hands behind your head without pulling on your neck, elbows facing outwards.\r\n3. Engage your core and bend your torso towards your thighs, performing a crunch while keeping your legs straight.\r\n4. Bring your torso back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Avoid pulling on your neck with your hands; use your abdominal muscles to lower your torso.\r\n2. Breathe steadily, exhaling as you lift your torso and inhaling as you lower it back down.\r\n3. Keep your legs straight and flat on the floor to maintain stability during the exercise.', '{"image_male_start":"images/Abdominals/Seated floor crunches.jpeg","video_url":"videos/Abdominals/Seated floor crunches.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d5fac31c-a340-4da5-95d0-5caaf9701a0d'::uuid, 'Seated flutter kicks', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on a bench with your legs extended straight out in front of you. Lean back slightly, supporting yourself by gripping the sides of the bench.\r\n2. Lift both legs off the bench a few inches, keeping them straight.\r\n3. Begin the flutter kicks by alternately raising and lowering your legs in a scissor-like motion, moving your right leg up while your left leg moves down and vice versa.\r\n4. Continue the flutter kicks for the desired number of repetitions or duration, keeping your core engaged and your movements controlled.', E'1. Keep your back straight and avoid rounding your shoulders to maintain proper form.\r\n2. Perform the exercise on a stable, non-slip bench to ensure safety and prevent slipping.\r\n3. If you are new to this exercise, start with a smaller range of motion and gradually increase it as you build strength.', '{"image_male_start":"images/Abdominals/seated flutter kicks.jpeg","video_url":"videos/Abdominals/seated flutter kicks .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2a23c15b-32dd-47de-b58b-2ed1f05c3324'::uuid, 'Seated hip abductor machine', 'Resistance', 'strength', 'weight_reps', 'intermediate', '379b9cc2-e621-4bfd-8c4d-0073eb8a2cbe'::uuid, E'1. Sit down on the hip abduction machine and place your feet flat on the footrests while positioning your outer thighs against the padded levers.\r\n2. Grip the side handles to stabilize your upper body and press your legs outward against the resistance, pushing the pads apart in a controlled motion.\r\n3. Pause for a second at the peak of the movement, then slowly return to the starting position.\r\n4. Repeat for the desired repetitions.', E'1. Sit upright with your back firmly against the backrest to maintain proper posture.\r\n2. Focus on squeezing your glutes and outer thighs throughout the movement.\r\n3. Perform the movement slowly and avoid using momentum to push the legs outward.', '{"image_male_start":"images/Legs/Seated Hip Abductor Machine.jpg","image_male_end":"images/Legs/Seated Hip Abductor Machine1.jpg","image_female_start":"images/Legs/Seated Hip Abductor Machine_Female.jpg","image_female_end":"images/Legs/Seated Hip Abductor Machine_Female1.jpg","video_url":"videos/Legs/Seated Hip Abductor Machine.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1cb494c3-bcbc-4523-9c57-9ad00c30409b'::uuid, 'Seated leg curl machine', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'eb86dcd9-df19-44ae-b784-7f624a093e6d'::uuid, E'1. Sit on the machine with your back against the backrest and your legs fully extended. Adjust the backrest and leg pads so the pad rests just above your heels.\r\n2. Pull your heels down by bending your knees until the pad reaches down as far as possible.\r\n3. Pause for a second, then slowly return to the starting position. \r\n4. Repeat for the desired repetitions.', E'1. Exhale as you curl and inhale as you return to the starting position.\r\n2. Do not let the weight stack drop; control the descent movement for maximum muscle activation.\r\n3. Keep your toes pointed forward throughout the exercise.', '{"image_male_start":"images/Legs/Seated leg curl machine  .jpg","video_url":"videos/Legs/Seated leg curl machine  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2c51f22a-d88b-4c17-b34e-9dbc8f0c6f7a'::uuid, 'Seated machine hip adductor', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on a hip abductor machine with your back straight, knees open wide and bent, and feet on the footrests.\r\n2. Set the padded bars against the inner sides of your knees.\r\n3. Close your knees to bring the bars together.\r\n4. As the bars come together, return to the initial position and repeat.', NULL, '{"image_male_start":"images/Legs/Seated Machine Hip Adductor.jpg","image_male_end":"images/Legs/Seated Machine Hip Adductor1.jpg","image_female_start":"images/Legs/Seated machine hip adductor_Female.jpg","image_female_end":"images/Legs/Seated machine hip adductor_Female1.jpg","video_url":"videos/Legs/Seated Machine Hip Adductor.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('acdc6853-ad8a-4e90-8615-3b2ed05cbc59'::uuid, 'Seated normal grip row machiNe', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'b7ec08fd-b7eb-4a14-a54d-f3d91be90da6'::uuid, E'1. Sit on a bench facing a row machine with a straight back and your feet placed on the footrests.\r\n2. Hold the rod above your knees with an overhand grip of your hands while keeping your arms straight.\r\n3. Pull the cable towards your chest by bending your arms and taking your elbows past your back.\r\n4. Return to the initial position and repeat.', NULL, '{"image_male_start":"images/Back/seated normal grip row machine .jpg","video_url":"videos/Back/seated normal grip row machine .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ca13c0b5-2dfd-4c66-bd95-995ffb0f74ef'::uuid, 'Seated Resistance band - cable rows', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Sit on the floor with your legs fully extended and feet together, anchoring the resistance band around the soles of your feet. Hold the handles with both hands, arms extended forward, palms facing each other.\r\n2. Keep your back straight, chest up, and core engaged to stabilize your body.\r\n3. Pull the handles towards your torso by bending your elbows, keeping your arms close to your body. Focus on squeezing your shoulder blades together at the peak of the movement.\r\n4. Slowly extend your arms back to the starting position, maintaining control over the resistance band. Repeat for the desired number of repetitions.', E'1. Keep your back straight and avoid slouching to maintain proper form.\r\n2. Engage your core to prevent any rocking or unnecessary movement during the exercise.\r\n3. Use a controlled motion to pull and release the resistance band, avoiding jerking movements.', '{"image_male_start":"images/Back/seated resistance band - cable rows .jpg","video_url":"videos/Back/seated resistance band - cable rows .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('fee8dff3-ce4d-42d2-bd1a-bee6bac12d00'::uuid, 'Seated shoulder flexor depressor retractor stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Sit on the floor with your legs extended straight in front of you and your back straight.\r\n2. Extend both arms down to your sides, then lean back slightly.\r\n3. Bring both arms about a foot behind you, keeping them straight, and place your hands on the floor with your fingers pointing forward.\r\n4. Hold this position for 15-30 seconds, feeling the stretch in your shoulders. Slowly return to the starting position.', E'1. Ensure your arms remain straight and your hands are firmly placed on the floor to maximize the stretch in your shoulders.\r\n2. Avoid lifting your shoulders towards your ears; keep them relaxed and down to deepen the stretch.\r\n3. Perform the stretch on a stable, non-slip surface to ensure safety and prevent slipping.', '{"image_male_start":"images/Shoulders/seated shoulder flexor depressor retractor stretch.jpg","image_male_end":"images/Shoulders/seated shoulder flexor depressor retractor stretch1.jpg","video_url":"videos/Shoulders/seated shoulder flexor depressor retractor stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('75c3d0da-91c5-4412-9bf8-2a0aaf3c203c'::uuid, 'Seated shoulder press barbell', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Sit on a bench with a backrest, feet flat on the floor. Hold a barbell with an overhand grip (palms facing forward), hands placed slightly wider than shoulder-width apart. Rest the barbell on your upper chest.\r\n2. Press the barbell overhead by extending your elbows, keeping your back firmly against the backrest.\r\n3. Fully extend your arms at the top of the movement, ensuring the barbell is directly above your head.\r\n4. Lower the barbell back down to your upper chest with control. Repeat for the desired number of repetitions.', E'1. Keep your wrists straight and aligned with your forearms to avoid strain.\r\n2. Avoid locking your elbows at the top of the movement to protect your joints.\r\n3. Exhale as you press the barbell up and inhale as you lower it down.', '{"image_male_start":"images/Shoulders/seated shoulder press barbell.jpg","image_male_end":"images/Shoulders/seated shoulder press barbell1.jpg","video_url":"videos/Shoulders/seated shoulder press barbell.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('76315ec6-7264-4a07-8be4-395cabede32a'::uuid, 'Seated side stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on a bench with your feet flat on the floor and your back straight.\r\n2. Extend your right arm overhead, keeping your left hand holding on the bench for support.\r\n3. Lean your torso to the left, reaching your right arm over your head and to the left side, feeling the stretch along the right side of your body.\r\n4. Hold the stretch for 15-30 seconds, then slowly return to the starting position. Repeat on the other side by extending your left arm overhead and leaning to the right.', E'1. Move into the stretch gradually, ensuring that your movements are controlled to avoid muscle strain.\r\n2. Ensure your supporting hand is firmly placed on the bench to maintain stability.\r\n3. Perform the stretch on a stable, non-slip surface to ensure safety and reduce discomfort.\r\n', '{"image_male_start":"images/Yoga/seated side stretch  .jpg","video_url":"videos/Yoga/seated side stretch  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('546715ca-687d-4f94-b3ef-9e10b832bcad'::uuid, 'Seated single leg hamstring stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Sit on the floor with your legs extended straight in front of you.\r\n2. Bend your left knee and place the sole of your left foot against your right inner thigh. Keep your right leg extended and straight.\r\n3. Reach forward with both hands towards your right foot, keeping your back straight. Aim to grasp your toes or reach as far as comfortable.\r\n4. Hold the stretch for 15-30 seconds, feeling the stretch in your right hamstring. Slowly release and return to the starting position. Repeat on the other side by extending your left leg and bending your right knee.', E'1. Keep your extended leg straight and avoid locking your knee to protect the joint.\r\n2. Ensure your bent knee is relaxed and the sole of your foot is comfortably placed against your inner thigh.\r\n3. Move into the stretch gradually and with control to prevent muscle strain or injury.', '{"image_male_start":"images/Stretching - Mobility/seated single leg hamstring stretch.jpg","image_male_end":"images/Stretching - Mobility/seated single leg hamstring stretch1.jpg","video_url":"videos/Stretching - Mobility/seated single leg hamstring stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('66b85695-b909-42e7-acf9-8d5e76b3ef85'::uuid, 'Seated straight leg calf stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'de08e8c8-a4ec-465b-ae07-cc976f64cd81'::uuid, E'1. Sit on the floor with your legs extended straight in front of you.\r\n2. Lightly bend both knees and extend your right foot, reaching forward to grasp your toes with your right hand.\r\n3. Gently pull your toes towards you, feeling the stretch in your calf muscle.\r\n4. Hold the stretch for 15-30 seconds, then slowly release. Repeat on the left leg.', E'1. Maintain a straight back as you reach forward to enhance the effectiveness of the stretch.\r\n2. Engage your core muscles to support your lower back and avoid rounding your shoulders.\r\n3. Move slowly and with control to prevent overstretching or injury.', '{"image_male_start":"images/Stretching - Mobility/seated straight leg calf stretch  .jpg","video_url":"videos/Stretching - Mobility/seated straight leg calf stretch  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2338a625-9065-499f-82ad-6ea112b25c80'::uuid, 'Seated v up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Sit on the floor with your legs extended straight in front of you and your arms placed on the floor slightly behind you for support.\r\n2. Engage your core and lift your torso off the floor, bringing your knees towards your chest to form a V shape with your body.\r\n3. Hold the top position for a moment, squeezing your abdominal muscles.\r\n4. Lower your legs and torso back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Breathe steadily, exhaling as you lift into the V position and inhaling as you lower back down.\r\n2. Avoid using momentum to lift your legs and torso; focus on using your abdominal muscles.\r\n3. Keep your back straight and avoid rounding your shoulders to maintain proper form.', '{"image_male_start":"images/Abdominals/seated v up.jpeg","video_url":"videos/Abdominals/seated v up .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('83a7e341-9d58-4621-af2a-a2ba21f31a96'::uuid, 'Shadow boxing', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, one foot slightly in front of the other, and your knees slightly bent. Position your hands in front of your face in a guard position, with your elbows close to your body.\r\nBegin throwing punches in the air, alternating between jabs, crosses, hooks, and uppercuts. Use a full range of motion and rotate your hips and shoulders to generate power.\r\nMove around as you throw your punches, incorporating footwork to simulate a real boxing match. Step forward, backward, and side to side, keeping light on your feet.\r\nContinue shadow boxing for the desired duration, maintaining a steady pace and controlled movements.', E'1. Focus on proper form and technique with each punch to maximize effectiveness and prevent injury.\r\n2. Breathe steadily, exhaling with each punch and inhaling between movements.\r\n3. Keep your hands up in the guard position to protect your face, even while moving and throwing punches.\r\n4. Use your lower body to generate power, rotating your hips and pivoting on your feet with each punch.\r\n5. Maintain a light and agile stance, allowing you to move quickly and fluidly.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Shadow Boxing  .jpg","video_url":"videos/Calisthenics-Cardio-Functional/Shadow Boxing  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('43f250c0-8184-4064-a1aa-f63125eb6cd3'::uuid, 'Shoulder abduction', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand upright with your feet shoulder-width apart and your arms at your sides.\r\n2. Slowly raise your arms out to the sides until they reach shoulder height, forming a T shape with your body. Keep your palms facing down and your elbows slightly bent.\r\n3. Hold the position for a moment, feeling the activation in your shoulders.\r\n4. Slowly lower your arms back to the starting position. Repeat for the desired number of repetitions.', E'1. Move your arms slowly and with control to maximize muscle engagement and prevent injury.\r\n2. Breathe steadily, exhaling as you raise your arms and inhaling as you lower them.\r\n3. Ensure your shoulders stay relaxed and away from your ears throughout the movement.\r\n4. Avoid using momentum to lift your arms; focus on using your shoulder muscles.', '{"image_male_start":"images/Shoulders/shoulder abduction .jpg","video_url":"videos/Shoulders/shoulder abduction .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('45ff0fda-b58b-4a5c-b4e2-1a9798f305ae'::uuid, 'Shoulder circle', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand upright with your feet shoulder-width apart and your arms relaxed, hanging straight down by your sides.\r\n2. Begin by making small circular motions with your shoulders, moving them backward in a controlled manner.\r\n3. Gradually increase the size of the circles, maintaining a steady pace.\r\n4. Repeat for the desired number of repetitions.', E'1. Move your shoulders slowly and with control to maximize muscle engagement and prevent injury.\r\n2. Breathe steadily, exhaling as you complete each circle and inhaling as you start the next.\r\n3. Avoid using momentum to move your shoulders; focus on using your shoulder muscles.\r\n', '{"image_male_start":"images/Shoulders/shoulder circle .jpg","video_url":"videos/Shoulders/shoulder circle .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f8659770-8d80-4e69-bf52-4317a6fea9d3'::uuid, 'Shoulder extension', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand upright with your feet shoulder-width apart and your arms straight by your sides.\r\n2. Slowly extend your arms straight forward, and up overhead, keeping them straight and parallel to each other .\r\n3. Hold the top position for a moment. Slowly lower your arms back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Breathe steadily, exhaling as you raise your arms overhead and inhaling as you lower them back down.\r\n2. Ensure your shoulders stay relaxed and away from your ears throughout the movement.\r\n3. Avoid using momentum to lift your arms; focus on using your shoulder muscles.', '{"image_male_start":"images/Shoulders/shoulder extension .jpg","video_url":"videos/Shoulders/shoulder extension .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e39e48c8-0400-4934-bafa-430f224284ac'::uuid, 'Side lateral raise Resistance band', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart and place the middle of a resistance band under both feet. Hold one handle in each hand, arms down by your sides, and palms facing inward.\r\n2. Lift your arms out to the sides until they are parallel to the floor, forming a "T" shape with your body. Focusing on lifting with your shoulders and keeping your palms facing down.\r\n3. Slowly lower your arms back to the starting position with control.\r\n4. Repeat for the desired number of repetitions.', E'1. Exhale as you lift your arms and inhale as you lower them back down.\r\n2. Use a resistance band that provides enough tension to challenge your muscles without compromising form.\r\n3. Avoid swinging your body or using momentum to lift the band.', '{"image_male_start":"images/Shoulders/side lateral raise resistance band .jpg","video_url":"videos/Shoulders/side lateral raise resistance band .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('eefb50ce-69d7-4b6e-9911-33abbe01ad99'::uuid, 'Side lunges bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand upright with your feet hip-width apart and your hands clasped in front of you for balance.\r\n2. Take a big step to the right with your right foot, lowering your body into a lunge position. Your right knee should be bent and your left leg should remain straight.\r\n3. Push through your right heel to return to the starting position.\r\n4. Repeat on the other side by stepping out to the left with your left foot, lowering into a lunge, and then returning to the starting position.', E'1. Ensure your knee does not extend past your toes in the lunge position to protect your knee joint.\r\n2. Maintain a straight back and avoid leaning forward excessively during the lunge.\r\n3. Breathe steadily, inhaling as you step out and lower into the lunge, and exhaling as you push back to the starting position.', '{"image_male_start":"images/Legs/side lunges bodyweight  .jpg","video_url":"videos/Legs/side lunges bodyweight  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b12db285-0666-4c54-b1bc-031df1e3b5dc'::uuid, 'Side lying floor stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your left side with your legs stacked on top of each other and your body in a straight line. Rest your head on your left arm.\r\n2. Extend your right arm straight over your head.\r\n3. Slowly lower your right hand towards your left hand to stretch your back.\r\n4. Hold the stretch for 15-30 seconds, feeling the stretch in your back and shoulders. Slowly return to the starting position and repeat on the other side by lying on your right side and following the same steps.\r\n', E'1. Ensure your extended arm stays straight to maximize the stretch in your back and shoulders.\r\n2. Keep your core engaged to support your lower back during the stretch.\r\n3. Perform the stretch on a comfortable, non-slip surface to ensure safety and reduce discomfort.', '{"image_male_start":"images/Stretching - Mobility/side lying floor stretch.jpg","image_male_end":"images/Stretching - Mobility/side lying floor stretch1.jpg","video_url":"videos/Stretching - Mobility/side lying floor stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3a05ca0d-175f-4c87-9734-1ea54f503fc4'::uuid, 'Side lying leg lift left', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your right side with your legs extended straight and stacked on top of each other. Rest your head on your right arm and place your left hand on your hips.\r\n2. Slowly lift your left leg straight up towards the ceiling, keeping it straight and in line with your body.\r\n3. Hold the top position for a moment, feeling the contraction in your outer thigh and hip.\r\n4. Slowly lower your leg back to the starting position with control. Repeat for the desired number of repetitions, then switch to your left side and perform the exercise with your right leg.', E'1. Breathe steadily, exhaling as you lift your leg and inhaling as you lower it.\r\n2. Ensure your leg stays straight and in line with your body throughout the movement.\r\n3. Avoid using momentum to lift your leg; focus on using your hip and thigh muscles.', '{"image_male_start":"images/Legs/side lying leg lift left  .jpg","video_url":"videos/Legs/side lying leg lift left  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d49d88c1-a442-4fbe-8e87-bb4ee412b1f3'::uuid, 'side lying leg lift right', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your left side with your legs extended straight and stacked on top of each other. Rest your head on your left arm and place your right hand on your hips.\r\n2. Slowly lift your right leg straight up towards the ceiling, keeping it straight and in line with your body.\r\n3. Hold the top position for a moment, feeling the contraction in your outer thigh and hip.\r\n4. Slowly lower your leg back to the starting position with control. Repeat for the desired number of repetitions, then switch to your right side and perform the exercise with your left leg.', E'1. Breathe steadily, exhaling as you lift your leg and inhaling as you lower it.\r\n2. Ensure your leg stays straight and in line with your body throughout the movement.\r\n3. Avoid using momentum to lift your leg; focus on using your hip and thigh muscles.', '{"image_male_start":"images/Legs/side lying leg lift right  .jpg","video_url":"videos/Legs/side lying leg lift right  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('8a90aa1a-c14b-488e-bd68-2327a51d792c'::uuid, 'Side plank', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your right side with your legs extended straight and stacked on top of each other. Prop yourself up on your right elbow, keeping your elbow directly under your shoulder.\r\n2. Engage your core and lift your hips off the floor, forming a straight line from your head to your feet.\r\n3. Hold the position for the desired duration, keeping your body straight and your core tight.\r\n4. Slowly lower your hips back to the starting position with control. Repeat on the other side by lying on your left side and following the same steps.', E'1. Ensure your elbow is directly under your shoulder to support your upper body.\r\n2. Focus on keeping your head in line with your spine to prevent neck strain.\r\n3. Maintain a straight body line, avoiding any sagging or lifting of the hips.\r\n4. Perform the exercise on a comfortable, non-slip surface to ensure safety and reduce discomfort.', '{"image_male_start":"images/Abdominals/side plank.jpeg","video_url":"videos/Abdominals/side plank.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('134efe75-0b66-4672-b969-415051e73eea'::uuid, 'side plank oblique crunch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a side plank position on your right side, with your legs extended straight and stacked on top of each other. Prop yourself up on your right elbow, keeping your elbow directly under your shoulder. Place your left hand on your hip.\r\n2. Engage your core and lift your hips off the floor, forming a straight line from your head to your feet.\r\n3. Lower your hips towards the floor without touching it, then raise them back up to the starting position, squeezing your obliques at the top.\r\n4. Repeat for the desired number of repetitions, then switch to the other side and perform the exercise on your left side.', E'1. Keep your core engaged throughout the exercise to maintain balance and stability.\r\n2. Move your hips slowly and with control to maximize muscle engagement and prevent injury.\r\n3. Breathe steadily, exhaling as you lift your hips and inhaling as you lower them.', '{"image_male_start":"images/Abdominals/side plank oblique crunch.jpeg","video_url":"videos/Abdominals/side plank oblique crunch .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('15ec4799-81ae-4d8e-9a93-0ce4dfc1db8f'::uuid, 'Side Plank with hip lift', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a side plank position on your right side, with your legs extended straight and stacked on top of each other. Prop yourself up on your right elbow, keeping your elbow directly under your shoulder. Raise your left arm straight toward the ceiling.\r\n2. Engage your core and lift your hips off the floor, forming a straight line from your head to your feet.\r\n3. Once in the top position, perform two small controlled bounces with your hips, lifting them slightly higher each time.\r\n4. Lower your hips back to the floor without touching it and repeat the steps for the desired number of repetitions, then switch to the other side and perform the exercise on your left side.', E'1. Move your hips slowly and with control to maximize muscle engagement and prevent injury.\r\n2. Breathe steadily, exhaling as you lift your hips and inhaling as you lower them.\r\n3. Ensure your elbow is directly under your shoulder to support your upper body.', '{"image_male_start":"images/Yoga/Side plank with hip lift.jpeg","video_url":"videos/Yoga/Side plank with hip lift.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('722610d1-ec37-4490-873e-84742b630568'::uuid, 'Side push up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your right side with your legs bent and stacked on top of each other. Place your right arm across your chest and your left hand on the floor in front of you for support.\r\n2. Engage your core and press your left hand into the floor, lifting your upper body off the floor.\r\n3. Hold the top position for a moment, feeling the contraction in your chest and triceps.\r\n4. Slowly lower your upper body back to the starting position with control. Repeat for the desired number of repetitions, then switch to your left side and perform the exercise with your right hand for support.', E'1. Breathe steadily, exhaling as you push up and inhaling as you lower back down.\r\n2. Ensure your supporting hand is firmly placed on the floor to provide stability.\r\n3. Avoid using momentum to lift your upper body; focus on using your chest and triceps muscles.', '{"image_male_start":"images/Chest/Side push up.jpg","image_male_end":"images/Chest/Side push up1.jpg","video_url":"videos/Chest/Side push up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4cc359a5-0838-4ada-b285-90774723938a'::uuid, 'Side to side punch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand upright with your feet wider than shoulder-width apart and your knees slightly bent. Hold your fists up in front of your face in a guard position.\r\n2. Rotate your torso to the left as you punch across your body with your right hand, extending your arm fully. Keep your legs and hips stationary.\r\n3. Quickly return to the starting position, then rotate your torso to the right as you punch across your body with your left hand.\r\n4. Continue alternating punches from side to side for the desired duration or number of repetitions, maintaining a steady rhythm and controlled movements.', E'1. Focus on rotating your torso to generate power in your punches while keeping your legs and hips stationary.\r\n2. Breathe steadily, exhaling as you punch and inhaling as you return to the starting position.\r\n3. Keep your fists up in a guard position when not punching to simulate a defensive stance.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/side to side punch  .jpg","video_url":"videos/Calisthenics-Cardio-Functional/side to side punch  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('bbf084f3-5308-4d94-a418-65413a2b7138'::uuid, 'Side to side push up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a standard push-up position with your hands placed slightly wider than shoulder-width apart, your body forming a straight line from head to heels.\r\n2. Lower your body into a push-up, bending both arms but leaning more to the right side, bringing your chest closer to your right hand.\r\n3. Push through both hands to return to the starting position.\r\n4. Lower your body into a push-up again, this time leaning more to the left side, bringing your chest closer to your left hand. Continue alternating sides with each push-up for the desired number of repetitions.', E'1. Breathe steadily, exhaling as you lower your chest and inhaling as you push back up.\r\n2. Ensure your hands are placed firmly on the floor to provide stability during the exercise.\r\n3. Focus on using your chest and triceps muscles to push back up to the starting position.', '{"image_male_start":"images/Chest/Side to side push up.jpg","image_male_end":"images/Chest/Side to side push up1.jpg","video_url":"videos/Chest/Side to side push up.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ff759a9b-6cff-4b47-851f-ea5d8c7089a5'::uuid, 'Side wrist pull stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand upright with your feet shoulder-width apart.\r\n2. Extend your right arm across your torso at chest height, keeping it bent and your forearm parallel to the floor.\r\n3. Bend your left arm and use your left hand to grasp your right hand, gently pulling your right wrist backward to feel a stretch in your right wrist and forearm.\r\n4. Hold the stretch for 15-30 seconds, then slowly release. Repeat on the other side.', E'1. Move your wrist slowly and with control to avoid any sudden movements that could cause strain.\r\n2. Breathe deeply and steadily as you hold the stretch.\r\n3. Focus on relaxing into the stretch to allow your muscles to lengthen fully.\r\n', '{"image_male_start":"images/Stretching - Mobility/side wrist pull stretch  .jpg","video_url":"videos/Stretching - Mobility/side wrist pull stretch  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a8f85f9f-2459-4904-9cd8-aa85784a69e5'::uuid, 'Single arm cable row left', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Set the cable pulley to a mid position and attach a single handle. Stand facing the machine with your feet shoulder-width apart. Grasp the handle with your left hand, arm extended towards the machine.\r\n2. Slightly bend your knees, push your hips backward, and lean forward slightly for balance.\r\n3. Pull the handle towards your torso, bending your elbow and squeezing your shoulder blade back. Keeping your elbow close to your body.\r\n4. Slowly extend your arm back to the starting position with control. Repeat for the desired repetitions, then switch to the right arm.', E'1. Exhale as you pull the handle towards your torso and inhale as you extend your arm back.\r\n2. Use a weight that provides enough resistance to challenge your muscles without compromising form.\r\n3. Avoid using your body to generate momentum; keep the movement isolated to your arm and back.', '{"image_male_start":"images/Back/single arm cable row left .jpg","video_url":"videos/Back/single arm cable row left .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1ae75275-c2fc-47b8-8004-b37de96d1f57'::uuid, 'Single arm cable row right', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Set the cable pulley to a mid position and attach a single handle. Stand facing the machine with your feet shoulder-width apart. Grasp the handle with your right hand, arm extended towards the machine.\r\n2. Slightly bend your knees, push your hips backward, and lean forward slightly for balance.\r\n3. Pull the handle towards your torso, bending your elbow and squeezing your shoulder blade back. Keeping your elbow close to your body.\r\n4. Slowly extend your arm back to the starting position with control. Repeat for the desired repetitions, then switch to the right arm.', E'1. Exhale as you pull the handle towards your torso and inhale as you extend your arm back.\r\n2. Use a weight that provides enough resistance to challenge your muscles without compromising form.\r\n3. Avoid using your body to generate momentum; keep the movement isolated to your arm and back.', '{"video_url":"videos/Back/single arm cable row right .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1893b0ae-a0b8-408b-a171-db9fc237784a'::uuid, 'Single arm overhead extension Resistance band', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart and secure one end of the resistance band under your left foot. Hold the other end of the band with your right hand, raising your right arm overhead, keeping your elbow close to your head and your palm facing forward.\r\n2. Start with your right elbow bent and your hand behind your head.\r\n3. Extend your right arm upward, fully straightening your elbow. Then, slowly lower your hand back to the starting position with control. \r\n4. Repeat for the desired number of repetitions, then switch to the left arm.', E'1. Exhale as you extend your arm upward and inhale as you lower it back down.\r\n2. Avoid arching your back; keep your posture upright.\r\n3. Focus on engaging your triceps throughout the movement.', '{"image_male_start":"images/Triceps/single arm overhead extension resistance band.jpeg","video_url":"videos/Triceps/single arm overhead extension resistance band  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1ba5ca44-ba4c-42c3-96aa-68c104d1a9d3'::uuid, 'Single arm standing low cable row', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Set the cable pulley to a low position and attach a single handle. Stand facing the machine with your feet shoulder-width apart. Grasp the handle with your left hand, arm extended towards the machine.\r\n2. Slightly bend your knees, push your hips backward, and lean forward slightly for balance.\r\n3. Pull the handle towards your torso, bending your elbow and squeezing your shoulder blade back. Keeping your elbow close to your body.\r\n4. Slowly extend your arm back to the starting position with control. Repeat for the desired repetitions, then switch to the right arm.', E'1. Exhale as you pull the handle towards your torso and inhale as you extend your arm back.\r\n2. Use a weight that provides enough resistance to challenge your muscles without compromising form.\r\n3. Avoid using your body to generate momentum; keep the movement isolated to your arm and back.', '{"video_url":"videos/Back/single arm standing low cable row .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f3ae11fe-d6c2-4b0b-94e9-abffbe1f4298'::uuid, 'Single Dumbbell Biceps Curls', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell with both hands using an underhand grip (palm facing up), holding it from under the plates. Let the dumbbell hang down in front of your hips.\r\n2. Curl the dumbbell upward towards your chest by bending your elbow, focusing on engaging your biceps.\r\n3. Lower the dumbbell back to the starting position with control. Repeat for the desired number of repetitions. ', E'1. Keep your upper arm stationary throughout the movement.\r\n2. Avoid using momentum or swinging the dumbbell; focus on controlled motion.\r\n3. Exhale as you lift the dumbbell and inhale as you lower it.', '{"image_male_start":"images/Biceps/Single Dumbbell Biceps Curls.jpeg","video_url":"videos/Biceps/Single Dumbbell Biceps Curls.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0a4b78a5-a147-4a59-a4fd-b6257324bfae'::uuid, 'Single kettlebell deadlift', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '7352a8b5-30da-44d7-9cae-8a031f5d2aed'::uuid, E'1. Stand with your feet shoulder-width apart, holding a kettlebell in one hand in front of your body. Keep your back straight and shoulders back.\r\n2. Bend at your hips and knees to lower the kettlebell towards the floor, keeping your back flat.\r\n3. Push through your heels to return to the standing position, extending your hips and knees.\r\n4. Squeeze your glutes at the top of the movement, then lower the kettlebell back down in a controlled manner. Repeat for the desired number of repetitions, then switch to the other hand and repeat.', E'1. Exhale as you lift the kettlebell and inhale as you lower it.\r\n2. Ensure your knees do not cave inward; keep them aligned with your toes.\r\n3. Focus on hinging at the hips rather than bending at the waist.', '{"image_male_start":"images/Back/Single Kettlebell Deadlift.jpg","image_male_end":"images/Back/Single Kettlebell Deadlift1.jpg","video_url":"videos/Back/Single Kettlebell Deadlift.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1681102e-7ca4-43e7-98bb-5abd0f5d9abb'::uuid, 'Single leg calf raise leg press machine', 'Resistance', 'strength', 'weight_reps', 'intermediate', '28deca28-3c3f-422f-9707-032a51268ee5'::uuid, E'1. Lie on the leg press machine and straighten your left leg, placing your forefoot on the platform, while your heel hangs off the edge. Your right foot should be resting on the floor.\r\n2. Press through your forefoot to lift the platform upward by extending your ankle and squeezing your calf at the top of the movement.\r\n3. Slowly lower your heel back down to the starting position with control, ensuring you achieve a full range of motion. \r\n4. Repeat for the desired number of repetitions, then switch to the right leg.', E'1. Keep your knee slightly bent to reduce strain on your joints.\r\n2. Ensure your heel drops below the edge of the platform to achieve a full range of motion.\r\n3. Maintain a steady pace to ensure consistent tension on the muscles.', '{"image_male_start":"images/Legs/single leg calf raise leg press machine  .jpg","video_url":"videos/Legs/single leg calf raise leg press machine  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9616f216-90c3-4457-b8a1-428ad56cb3cf'::uuid, 'Single leg incline 45 degree leg press machine', 'Resistance', 'strength', 'weight_reps', 'intermediate', '28deca28-3c3f-422f-9707-032a51268ee5'::uuid, E'1. Lie on the leg press machine and place your left foot flat on the platform while your right foot rests on the floor.\r\n2. Engage your core and keep your back pressed against the seat. Release the safety handles of the leg press machine.\r\n3. Press through your left foot to extend your leg fully, pushing the platform upward.\r\n4. Slowly lower the platform back down to the starting position with control. Repeat for the desired number of repetitions, then switch to the right leg.', E'1. Exhale as you press the platform upward and inhale as you lower it back down.\r\n2. Ensure your knee stays aligned with your toes to avoid unnecessary strain.\r\n3. Keep your knee slightly bent at the top of the movement to reduce strain on your joints.', '{"image_male_start":"images/Legs/single leg incline 45 degree leg press machine  .jpg","video_url":"videos/Legs/single leg incline 45 degree leg press machine  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7148ca41-e34b-42e6-a2da-dc94b6f26016'::uuid, 'Single leg romanian deadlift dumbbell', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with feet hip-width apart, holding a dumbbell in your right hand. Shift your weight onto the right leg and keep it straight.\r\n2. Hinge at your hips, extending your left leg straight back while lowering the dumbbell towards the floor.\r\n3. Continue lowering until your upper body and extended leg are parallel to the floor and level from ankle to shoulders.\r\n4. Return to the starting position by driving through your standing heel. Repeat for the desired number of repetitions, then switch legs.', E'1. Exhale as you lower the dumbbell and inhale as you return to the start.\r\n2. Maintain a slight bend in the standing knee to avoid joint strain.\r\n3. Practice the movement without weights to master the form before adding resistance.', '{"image_male_start":"images/Legs/single leg romanian deadlift dumbbell  .jpg","video_url":"videos/Legs/single leg romanian deadlift dumbbell  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('82fa93bf-52b6-40dd-93ff-b2e2e9f2d18f'::uuid, 'Single leg romanian deadlifts right cable Resistance band', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Attach one end of the resistance band to a low anchor point and hold the other end in your right hand. Stand on your left leg with your right leg slightly bent and your left foot firmly on the floor.\r\n2. Hinge at your hips and lower your torso until it''s parallel to the floor while extending your right leg straight back, keeping your left knee slightly bent. \r\n3. Return to the starting position by driving your hips forward and bringing your right leg back down.\r\n4. Repeat for the desired number of repetitions, then switch to the left leg. ', E'1. Exhale as you hinge forward and inhale as you return to the starting position.\r\n2. Maintain a slight bend in your standing knee for balance and stability.\r\n3. Keep your back straight and avoid rounding your shoulders.', '{"image_male_start":"images/Legs/single leg romanian deadlifts right cable resistance band  .jpg","video_url":"videos/Legs/single leg romanian deadlifts right cable resistance band  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('59d9433f-6de2-4ef8-ba95-001355d4e0cd'::uuid, 'Sit-ups', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your knees bent and feet flat on the floor, hip-width apart. Place your hands behind your head.\r\n2. Engage your core and lift your upper body off the floor, curling your chest towards your knees.\r\n3. Continue to lift your torso until you are in a sitting position with your chest close to your knees.\r\n4. Slowly lower your upper body back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Keep your core engaged throughout the exercise to maximize muscle engagement and support your lower back.\r\n2. Move your body slowly and with control to avoid using momentum and to prevent injury.\r\n3. Breathe steadily, exhaling as you lift your torso and inhaling as you lower it back down.', '{"image_male_start":"images/Abdominals/Situps.jpeg","video_url":"videos/Abdominals/Situps.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c20b0ea3-c3af-4df4-b3cf-c5c523bd5481'::uuid, 'Skipping', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet together and arms by your sides as if holding the handles of a skipping rope, one in each hand. Engage your core and maintain an upright posture.\r\n2. Swing your hands in a circular motion as if turning a skipping rope, and jump lightly off the floor, keeping your knees slightly bent and landing softly on your forefeet.\r\n3. Keep your jumps low and quick, simulating skipping with a rope. Repeat for the desired duration or number of repetitions.', E'1. Breathe steadily and rhythmically to maintain oxygen flow during the exercise.\r\n2. Focus on keeping your jumps low to the floor to minimize impact on your joints.\r\n3. Stay relaxed and avoid tensing your shoulders and arms.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/skipping  .jpg","video_url":"videos/Calisthenics-Cardio-Functional/skipping  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('58f93342-0ceb-4574-a97e-8843ef082c66'::uuid, 'Smith machine bulgarian split squat', 'Resistance', 'strength', 'weight_reps', 'intermediate', '132c52b1-6336-4426-a457-c35a314038f2'::uuid, E'1. Position yourself under the bar of a smith machine, resting it across your shoulders, and hold it firmly with both hands. Place your right foot back on a bench or box behind you, ensuring your left foot is firmly planted on the floor in front.\r\n2. Lower your body by bending your left knee, keeping your torso upright and your right knee pointing towards the floor.\r\n3. Continue lowering until your left thigh is parallel to the floor and your right knee is close to, but not touching the floor.\r\n4. Push through your left heel to return to the starting position, extending your left leg fully. Repeat for the desired number of repetitions, then switch to your right leg.\r\n', E'1. Ensure your front knee stays in line with your toes to avoid unnecessary strain on the knee joint.\r\n2. Keep your torso upright and avoid leaning forward or backward excessively.\r\n3. Breathe steadily, exhaling as you push up and inhaling as you lower down.', '{"image_male_start":"images/Legs/smith machine bulgarian split squat  .jpg","video_url":"videos/Legs/smith machine bulgarian split squat  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e9e6ad93-3391-4769-a162-951130199659'::uuid, 'Smith machine calf raise', 'Resistance', 'strength', 'weight_reps', 'intermediate', '132c52b1-6336-4426-a457-c35a314038f2'::uuid, E'1. Position yourself under the bar of a smith machine, resting it across your shoulders, and hold it firmly with both hands. Place your feet shoulder-width apart with your toes pointing forward.\r\n2. Lift your heels off the floor by pushing through your forefeet, raising your body upwards.\r\n3. Continue lifting until you are standing on your forefeet, then slowly lower your heels back to the starting position with control.\r\n4. Repeat for the desired number of repetitions.\r\n', E'1. Breathe steadily, exhaling as you lift your heels and inhaling as you lower them back down.\r\n2. Perform the movement slowly and with control to maximize muscle activation and reduce injury risk.\r\n3. Ensure your knees remain slightly bent to avoid knee strain.', '{"image_male_start":"images/Legs/smith machine calf raise  .jpg","video_url":"videos/Legs/smith machine calf raise  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('3c6d6f79-8d0a-40d7-9f03-21b550fb4593'::uuid, 'Smith machine press decline', 'Resistance', 'strength', 'weight_reps', 'intermediate', '132c52b1-6336-4426-a457-c35a314038f2'::uuid, E'1. Position a decline bench under the smith machine. Adjust the bench so that the barbell is at chest height when lying on the bench.\r\n2. Lie on the decline bench with your feet secured under the foot pads. Grip the barbell with your hands slightly wider than shoulder-width apart.\r\n3. Unrack the barbell and lower it to your chest until it slightly touches it.\r\n4. Press the barbell back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Breathe steadily, exhaling as you press the barbell up and inhaling as you lower it down.\r\n2. Ensure your feet are securely placed under the foot pads to prevent slipping.\r\n3. Focus on using your chest muscles to press the weight, avoiding excessive strain on your shoulders.', '{"image_male_start":"images/Chest/smith machine press decline.jpg","image_male_end":"images/Chest/smith machine press decline1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0dc31409-c284-4b7a-a7c8-04ed529f4695'::uuid, 'Smith machine press flat', 'Resistance', 'strength', 'weight_reps', 'intermediate', '132c52b1-6336-4426-a457-c35a314038f2'::uuid, E'1. Position a flat bench under the smith machine. Adjust the bench so that the barbell is at chest height when lying on the bench.\r\n2. Lie on the flat bench with your feet flat on the floor. Grip the barbell with your hands slightly wider than shoulder-width apart.\r\n3. Unrack the barbell and lower it to your chest until it slightly touches it.\r\n4. Press the barbell back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Breathe steadily, exhaling as you press the barbell up and inhaling as you lower it down.\r\n2. Ensure your feet are firmly set on the floor for balance and support.\r\n3. Focus on using your chest muscles to press the weight, avoiding excessive strain on your shoulders.', '{"image_male_start":"images/Chest/smith machine press flat.jpg","image_male_end":"images/Chest/smith machine press flat1.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('d04cd837-65e6-4841-b2de-8cb14f5a6f11'::uuid, 'Smith machine press incline', 'Resistance', 'strength', 'weight_reps', 'intermediate', '132c52b1-6336-4426-a457-c35a314038f2'::uuid, E'1. Position an incline bench under the smith machine. Adjust the bench so that the barbell is at chest height when lying on the bench.\r\n2. Lie on the incline bench with your feet flat on the floor. Grip the barbell with your hands slightly wider than shoulder-width apart.\r\n3. Unrack the barbell and lower it to your chest until it slightly touches it.\r\n4. Press the barbell back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Breathe steadily, exhaling as you press the barbell up and inhaling as you lower it down.\r\n2. Ensure your feet are firmly set on the floor for balance and support.\r\n3. Focus on using your chest muscles to press the weight, avoiding excessive strain on your shoulders.', '{"image_male_start":"images/Chest/smith machine press incline.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c568f6e5-7a94-45eb-b1a2-2597b7db20dc'::uuid, 'Smith machine shoulder press', 'Resistance', 'strength', 'weight_reps', 'intermediate', '132c52b1-6336-4426-a457-c35a314038f2'::uuid, E'1. Position an adjustable bench under the Smith machine and set it to a vertical position. Adjust the barbell to your shoulder height.\r\n2. Sit on the bench with your back straight and feet flat on the floor. Grip the barbell with your hands slightly wider than shoulder-width apart.\r\n3. Unrack the barbell and press it upward until your arms are fully extended above your head.\r\n4. Lower the barbell back to shoulder height with control. Repeat for the desired number of repetitions.', E'1. Ensure your back remains flat against the bench throughout the movement.\r\n2. Focus on using your shoulder muscles to press the weight, avoiding excessive strain on your neck.\r\n3. Keep your elbows slightly bent at the top to avoid straining your elbow joints.', '{"image_male_start":"images/Shoulders/smith machine shoulder press .jpg","video_url":"videos/Shoulders/smith machine shoulder press .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('52857be0-ffd1-43f1-ba7c-fd3952396cb8'::uuid, 'Spider curl barbell', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Set an incline bench at a 45-degree angle and lie face down, ensuring your chest is supported and your feet are firm on the floor. Hold a barbell with an underhand grip and hands shoulder-width apart.\r\n2. Let your arms hang straight down towards the floor, keeping your elbows slightly bent.\r\n3. Curl the barbell towards your shoulders by bending your elbows, keeping your upper arms stationary, and focusing on contracting your biceps.\r\n4. Slowly lower the barbell back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Use a full range of motion to fully engage the biceps.\r\n2. Ensure your elbows remain stationary and do not flare out during the movement.\r\n3. Adjust the weight of the barbell to provide enough challenge without compromising form.', '{"image_male_start":"images/Biceps/spider curl barbell.jpeg","video_url":"videos/Biceps/spider curl barbell .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('20a4ad6a-a741-4a47-8af1-30cda8ac8698'::uuid, 'Spider curl dumbbells simultaneous', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Set an incline bench at a 45-degree angle and lie face down, ensuring your chest is supported and your feet are firm on the floor. Hold a dumbbell in each hand with an underhand grip, hands shoulder-width apart.\r\n2. Let your arms hang straight down towards the floor, keeping your elbows slightly bent.\r\n3. Curl the dumbbells towards your shoulders by bending your elbows, keeping your upper arms stationary, and focusing on contracting your biceps.\r\n4. Slowly lower the dumbbells back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Use a full range of motion to fully engage the biceps.\r\n2. Ensure your elbows remain stationary and do not flare out during the movement.\r\n3. Adjust the weight of the dumbbells to provide enough challenge without compromising form.', '{"image_male_start":"images/Biceps/spider curl dumbbells simultaneous.jpeg","video_url":"videos/Biceps/spider curl dumbbells simultaneous.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('255f367b-e2f8-4e13-8214-30e96b1cc7ff'::uuid, 'Spider curl ez bar', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '0e9c1392-3e8d-454d-be69-641c3a69f2b9'::uuid, E'1. Set an incline bench at a 45-degree angle and lie face down, ensuring your chest is supported and your feet are firm on the floor. Hold an EZ bar with an underhand grip and hands shoulder-width apart.\r\n2. Let your arms hang straight down towards the floor, keeping your elbows slightly bent.\r\n3. Curl the EZ bar towards your shoulders by bending your elbows, keeping your upper arms stationary, and focusing on contracting your biceps.\r\n4. Slowly lower the EZ bar back to the starting position with control, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Use a full range of motion to fully engage the biceps.\r\n2. Ensure your elbows remain stationary and do not flare out during the movement.\r\n3. Adjust the weight of the barbell to provide enough challenge without compromising form.', '{"image_male_start":"images/Biceps/spider curl ez bar.jpeg","video_url":"videos/Biceps/spider curl ez bar .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b903b458-c92f-4ecf-a757-80c7e2d7f297'::uuid, 'Spider plank', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a standard plank position with your forearms on the floor, elbows directly under your shoulders, and your body forming a straight line from head to heels. Engage your core and keep your feet hip-width apart.\r\n2. Lift your right foot off the floor and bring your right knee towards your right elbow, keeping your hips level and your core tight.\r\n3. Return your right foot to the starting position, maintaining a stable plank position.\r\n4. Repeat the movement with your left leg, bringing your left knee towards your left elbow. Continue alternating legs for the desired duration or number of repetitions.', E'1. Breathe steadily throughout the exercise, exhaling as you bring your knee towards your elbow and inhaling as you return to the starting position.\r\n2. Focus on keeping your hips level and avoiding excessive torso rotation.\r\n3. Use a mat to cushion your forearms and feet for added comfort.', '{"image_male_start":"images/Abdominals/spider plank.jpeg","video_url":"videos/Abdominals/spider plank .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('84ccfa7b-8bb2-4819-ac7b-8dc5d62184c2'::uuid, 'Standing Ab Wheel Rollout', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '9ffbc39a-4891-4f46-b1f7-17bd2c6b7261'::uuid, E'1. Stand with your feet shoulder-width apart, holding an ab wheel with both hands. Engage your core and maintain an upright posture.\r\n2. Bend at your hips and knees to lower the ab wheel to the floor in front of your feet. Keep your arms extended and your back straight.\r\n3. Slowly roll the ab wheel forward, extending your body into a plank position. Ensure your core remains tight and your back stays straight throughout the movement.\r\n4. Roll the ab wheel back towards your feet, bending at your hips and knees to return to the starting position. Repeat for the desired number of repetitions.', E'1. Perform the movement slowly and with control to maximize muscle activation and reduce injury risk.\r\n2. Breathe steadily throughout the exercise, exhaling as you roll out and inhaling as you return.\r\n3. Keep your back straight and avoid sagging or arching your lower back.', '{"image_male_start":"images/Abdominals/Standing Ab Wheel Rollout_Female.jpeg","video_url":"videos/Abdominals/Standing Ab Wheel Rollout.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('84b38a82-9830-4a0d-aa5f-a8df53951130'::uuid, 'standing adductor stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet wider than shoulder-width apart, toes pointing slightly outward. Keep your hands to your hips.\r\n2. Shift your weight to your right leg, bending your right knee while keeping your left leg straight. Lean your torso slightly forward.\r\n3. Hold the stretch for 20-30 seconds, feeling a stretch along the inner thigh of your left leg.\r\n4. Return to the starting position and repeat the stretch on the other side by shifting your weight to your left leg and bending your left knee.', E'1. Ensure your bent knee does not extend past your toes to avoid unnecessary strain on the knee joint.\r\n2. Perform the stretch slowly and with control to maximize muscle flexibility and reduce injury risk.\r\n3. Gradually increase the depth of the stretch as your flexibility improves.', '{"image_male_start":"images/Stretching - Mobility/standing adductor stretch  .jpg","video_url":"videos/Stretching - Mobility/standing adductor stretch  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0bb3a17f-165a-4e53-986e-698148763d1f'::uuid, 'Standing arnold press dumbbell', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height. Your palms should be facing backward, and your elbows should be bent.\r\n2. Begin to press the dumbbells overhead. As you press, rotate your palms so they face forward at the top of the movement.\r\n3. Fully extend your arms at the top, ensuring your biceps are near your ears.\r\n4. Slowly lower the dumbbells back to the starting position by rotating your palms back towards your shoulders. Repeat for the desired number of repetitions.', E'1. Rotate your wrists smoothly during the pressing and lowering phases to avoid strain.\r\n2. Breathe steadily, exhaling as you press the weights up and inhaling as you lower them back down.\r\n3. Focus on the full range of motion to engage all parts of the shoulder muscles effectively.', '{"image_male_start":"images/Shoulders/standing arnold press dumbbell.jpg","image_male_end":"images/Shoulders/standing arnold press dumbbell1.jpg","video_url":"videos/Shoulders/standing arnold press dumbbell.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9799b56b-aa00-4a73-a54c-c896daac1ae6'::uuid, 'Standing bow hamstring stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet together and your arms by your sides. Engage your core and maintain an upright posture.\r\n2. Hinge at your hips and lower your torso towards your legs, reaching your hands towards the back of your feet. Keep your back straight and avoid rounding your shoulders.\r\n3. Hold the stretch for 20-30 seconds, feeling a stretch along the back of your legs. \r\n4. Return to the starting position and repeat the stretch as needed.\r\n', E'1. Perform the stretch slowly and with control to maximize muscle flexibility and reduce injury risk.\r\n2. Ensure your weight is distributed evenly on both feet to maintain balance.\r\n3. Focus on keeping your back straight and avoiding excessive rounding of your spine.', '{"image_male_start":"images/Stretching - Mobility/standing bow hamstring stretch.jpg","image_male_end":"images/Stretching - Mobility/standing bow hamstring stretch1.jpg","video_url":"videos/Stretching - Mobility/standing bow hamstring stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('67e91395-7864-4cb8-a2ef-6a5e2fdd5c9e'::uuid, 'Standing cable oblique twist', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Stand sideways to a cable machine with your feet shoulder-width apart. Attach a handle to a mid-pulley and grasp it with both hands. Bend your arms at 90 degrees and keep your elbows close to your torso sides.\r\n2. Engage your core and keep your arms stationary as you twist your torso away from the machine, pulling the handle across your body.\r\n3. Twist until your shoulders are turned 90 degrees from the machine, feeling the stretch in your oblique muscles.\r\n4. Slowly return to the starting position with control, keeping your arms straight. Repeat for the desired number of repetitions, then switch sides.', E'1. Use your oblique muscles to twist, not your arms, hips, or legs.\r\n2. Keep your feet planted firmly on the floor.\r\n3. Adjust the cable machine weight to a challenging but manageable level.', '{"image_male_start":"images/Abdominals/standing cable oblique twist.jpeg","video_url":"videos/Abdominals/standing cable oblique twist .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('60854de6-2f11-452c-a478-950066e7f1cc'::uuid, 'Standing calf raise Resistance band', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart, holding a resistance band under your forefeet. Hold the handles of the band by your sides.\r\n2. Slowly lift your heels off the floor by pushing through your forefeet, raising your body upwards.\r\n3. Continue lifting until you are standing on your forefeet, feeling a strong contraction in your calves.\r\n4. Slowly lower your heels back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Focus on pushing through your forefeet, avoiding excessive pressure on your toes.\r\n2. Move slowly and with control to maximize muscle activation and avoid injury.\r\n3. Ensure the resistance band is secure and provides enough challenge without compromising form.', '{"video_url":"videos/Legs/standing calf raise resistance band  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('9827a4b4-64a8-4971-bd28-0e440cfc8e40'::uuid, 'Standing calf raises smith machine', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand in front of the Smith machine bar and place both hands on the bar keeping your arms straight. Place your forefeet shoulder-width apart on a low platform, heels extended to the floor.\r\n2. Slowly lift your heels off the floor by pushing through your forefeet, raising your body upwards.\r\n3. Continue lifting until you are standing on your forefeet, feeling a strong contraction in your calves.\r\n4. Slowly lower your heels back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Focus on pushing through your forefeet, avoiding excessive pressure on your toes.\r\n2. Move slowly and with control to maximize muscle activation and avoid injury.\r\n3. Keep your knees slightly bent to avoid strain or injury of your joints.', '{"image_male_start":"images/Legs/standing calf raises smith machine  .jpg","video_url":"videos/Legs/standing calf raises smith machine  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('6e69ac36-dfe6-43cc-85da-05d470069e28'::uuid, 'Standing dumbbell alternate shoulder press', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing forward and elbows pointing to the floor.\r\n2. Press the right dumbbell overhead until your arm is fully extended, keeping the left dumbbell at shoulder height.\r\n3. Lower the right dumbbell back to shoulder height with control and then press the left dumbbell overhead until your arm is fully extended.\r\n4. Continue alternating arms for the desired number of repetitions.', E'1. Focus on your breathing: exhale while pressing the dumbbell up and inhale while lowering it.\r\n2. Avoid shrugging your shoulders to minimize neck strain.\r\n3. Incorporate shoulder warm-up exercises to prepare the muscles for the workout.', '{"image_male_start":"images/Shoulders/standing dumbbell alternate shoulder press.jpg","image_male_end":"images/Shoulders/standing dumbbell alternate shoulder press1.jpg","video_url":"videos/Shoulders/standing dumbbell alternate shoulder press.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('821c1892-ec54-42c8-a2e2-cb04c8136298'::uuid, 'Standing front raise dumbbell', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with your arms fully extended in front of your hips and palms facing your thighs.\r\n2. Raise both arms straight in front of you until they are parallel to the floor, keeping a slight bend in your elbows.\r\n3. Lower your arms back to the starting position with control.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Warm up your shoulders with light exercises before starting to prevent injury.\r\n2. Keep your head and neck in a neutral position to avoid unnecessary strain.\r\n3. Focus on your breathing: exhale as you lift the dumbbell and inhale as you lower it.', '{"image_male_start":"images/Shoulders/standing front raise dumbbell.jpg","image_male_end":"images/Shoulders/standing front raise dumbbell1.jpg","video_url":"videos/Shoulders/standing front raise dumbbell.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('cda0da53-4ba7-42bd-9364-d843d3075e20'::uuid, 'Standing gastrocnemius stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '4ec743bc-cfcd-4426-a49b-ad90f93abe76'::uuid, E'1. Stand facing a bench with your feet shoulder-width apart.\r\n2. Place your right foot on the bench, keeping your heel on the bench and your toes pointing up. Your left foot should remain flat on the floor.\r\n3. Lean forward slightly, grab your right heel with your right hand, and straighten your leg while lightly pulling your forefoot.\r\n4. Hold the stretch for 20-30 seconds, then switch legs and repeat. Perform the stretch for the desired number of repetitions on each side.', E'1. Keep your knees slightly bent to avoid strain or injury of your joints.\r\n2. Gradually increase the depth of the stretch as your flexibility improves.\r\n3. Use a bench at a comfortable height to ensure an effective stretch.', '{"image_male_start":"images/Stretching - Mobility/standing gastrocnemius stretch.jpg","image_male_end":"images/Stretching - Mobility/standing gastrocnemius stretch1.jpg","video_url":"videos/Stretching - Mobility/standing gastrocnemius stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b1d5fe06-d01b-4822-8bf8-8ef7ecf35617'::uuid, 'Standing hamstring calf stretch with Resistance band', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart, holding a resistance band in both hands. Place the center of the band under your right forefoot.\r\n2. Extend your right leg straight out in front of you, keeping your heel on the floor and your toes pointing upward. Hold the ends of the resistance band to create tension.\r\n3. Gently pull on the resistance band, leaning your torso forward to increase the stretch in your right hamstring. Keep your back straight and avoid rounding your shoulders.\r\n4. Hold the stretch for 20-30 seconds, then switch to your left leg and repeat. Perform the stretch for the desired number of repetitions on each side.', E'1. Focus on keeping your extended leg straight and your toes pointing upward.\r\n2. Ensure your standing leg remains slightly bent to maintain balance.\r\n3. Use a resistance band with appropriate tension to provide an effective stretch.', '{"image_male_start":"images/Stretching - Mobility/standing hamstring calf stretch with resistance band.jpg","image_male_end":"images/Stretching - Mobility/standing hamstring calf stretch with resistance band1.jpg","video_url":"videos/Stretching - Mobility/standing hamstring calf stretch with resistance band.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4138b8a0-a5d8-4fea-8174-97f2941fa6e7'::uuid, 'Standing lat cable pull over', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Stand facing a cable machine with your feet shoulder-width apart. Attach a straight bar to the high pulley and hold it with both hands, arms extended and palms facing down.\r\n2. Slightly bend your knees, hinge at your hips, and lean forward slightly. Keep your arms straight and pull the bar down in an arc motion towards your thighs. \r\n3. Keep pulling the bar down until it reaches your thighs, feeling a strong contraction in your lats.\r\n4. Slowly return the bar to the starting position with control, maintaining tension in your lats. Repeat for the desired number of repetitions.', E'1. Breathe steadily: exhale as you pull the bar down and inhale as you return it to the starting position.\r\n2. Focus on using your lat muscles to pull the bar, avoiding excessive movement of your arms.\r\n3. Keep your shoulders relaxed and avoid shrugging them towards your ears.', '{"image_male_start":"images/Back/standing lat cable pull over .jpg","video_url":"videos/Back/standing lat cable pull over .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('587f5a2c-2e74-4ca6-9ca8-a4adecccdfb5'::uuid, 'Standing lateral stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, arms relaxed by your sides. Engage your core and maintain an upright posture.\r\n2. Place your right hand behind your head. Keep your left hand extended down the side of your leg.\r\n3. Gently bend your torso to the left as far as possible and hold the stretch for 20-30 seconds, feeling a stretch along the right side of your torso.\r\n4. Return to the starting position and repeat the stretch on the other side.', E'1. Perform the stretch slowly and with control to maximize muscle flexibility and reduce injury risk.\r\n2. Gradually increase the depth of the stretch as your flexibility improves.\r\n3. Focus on keeping your back straight and avoiding excessive rounding of your spine.', '{"image_male_start":"images/Stretching - Mobility/standing lateral stretch  .jpg","video_url":"videos/Stretching - Mobility/standing lateral stretch  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a0c5b0bb-94ac-48f8-9ddf-df60acdd384d'::uuid, 'Standing leg elevated hamstring stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', '4ec743bc-cfcd-4426-a49b-ad90f93abe76'::uuid, E'1. Stand facing an incline bench with your feet shoulder-width apart. Place your right heel on the edge of the bench headrest, keeping your leg straight and toes pointing upward.\r\n2. Engage your core and hinge at your hips, leaning your torso towards your right leg.\r\n3. Reach towards your right foot with both hands, feeling a stretch along the back of your right leg (hamstring). Hold this position for 20-30 seconds.\r\n4. Return to the starting position and switch legs. Perform the stretch for the desired number of repetitions on each side.', E'1. Focus on keeping your extended leg straight and your toes pointing upward.\r\n2. Ensure your standing leg remains slightly bent to maintain balance.\r\n3. Set the bench at an elevated surface at a comfortable height to ensure an effective stretch.', '{"image_male_start":"images/Stretching - Mobility/standing leg elevated hamstring stretch.jpg","image_male_end":"images/Stretching - Mobility/standing leg elevated hamstring stretch1.jpg","video_url":"videos/Stretching - Mobility/standing leg elevated hamstring stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('1393da63-5b18-4a1e-931b-f265844a3266'::uuid, 'Standing oblique crunch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, placing your hands behind your head with your elbows flared out to the sides. Engage your core and maintain an upright posture.\r\n2. Lift your right knee towards your right elbow while simultaneously bending your torso to the right to bring your elbow and knee closer together.\r\n3. Return to the starting position by lowering your right leg and straightening your torso.\r\n4. Repeat the movement on the left side, lifting your left knee towards your left elbow. Continue alternating sides for the desired number of repetitions.', E'1. Breathe steadily: exhale as you crunch to the side and inhale as you return to the starting position.\r\n2. Ensure your standing leg remains slightly bent to maintain balance.\r\n3. Keep your back straight and avoid leaning forward or backward during the exercise.', '{"image_male_start":"images/Abdominals/standing oblique crunch.jpeg","video_url":"videos/Abdominals/standing oblique crunch .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b8636089-1eb5-4f1f-9540-a4982b1013f1'::uuid, 'Standing one arm chest stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your right side facing near a wall with your feet shoulder-width apart. Extend your right arm to the side at shoulder height and place your palm flat against the wall.\r\n2. Slowly turn your body away from the wall, keeping your arm extended and feeling a stretch in your chest and shoulder.\r\n3. Hold the stretch for 20-30 seconds, maintaining a gentle pressure.\r\n4. Return to the starting position and repeat the stretch on the left side. Perform the stretch for the desired number of repetitions on each side.', E'1. Focus on keeping your extended arm straight and your palm flat against the wall.\r\n2. Ensure your shoulders remain relaxed and avoid tensing them up towards your ears.\r\n3. Use a gentle motion to avoid over-stretching and potential muscle strain.', '{"image_male_start":"images/Stretching - Mobility/standing one arm chest stretch.jpg","image_male_end":"images/Stretching - Mobility/standing one arm chest stretch1.jpg","video_url":"videos/Stretching - Mobility/standing one arm chest stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('68594301-083f-4ea6-a557-8274877ff7f3'::uuid, 'Standing overhand shoulder stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, arms extended straight out in front of you at shoulder level, palms facing down.\r\n2. Swiftly raise your right arm overhead while simultaneously lowering your left arm down towards your thigh to your side. Keeping both arms straight.\r\n3. Swiftly return to the starting position and repeat the stretch by raising your left arm overhead and lowering your right arm. \r\n4. Perform the stretch for the desired number of repetitions.', E'1. Breathe steadily throughout the stretch, exhaling as you raise and lower your arms and inhaling as you return to the starting position.\r\n2. Focus on keeping both arms straight and avoiding any twisting or turning of your torso.\r\n3. Use a gentle motion to avoid over-stretching and potential muscle strain.', '{"image_male_start":"images/Shoulders/standing overhand shoulder stretch .jpg","video_url":"videos/Shoulders/standing overhand shoulder stretch .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4faa4272-53c1-4b72-9bb1-e6f054189a2e'::uuid, 'Standing quadriceps stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and find a stable surface to hold onto for balance if needed.\r\n2. Bend your right knee and bring your heel towards your glutes. Grasp your right ankle with your right hand.\r\n3. Keep your knees close together and lightly pull your right ankle upward, feeling a stretch along the front of your right thigh.\r\n4. Hold the stretch for 20-30 seconds, then release your right ankle and return to the starting position. Repeat the stretch on the left leg.', E'1. Perform the stretch slowly and with control to maximize muscle flexibility and reduce injury risk.\r\n2. Ensure your supporting leg remains slightly bent to maintain balance.\r\n3. Focus on keeping your torso upright and avoid leaning forward or backward.', '{"image_male_start":"images/Stretching - Mobility/standing quadriceps stretch.jpg","image_male_end":"images/Stretching - Mobility/standing quadriceps stretch1.jpg","video_url":"videos/Stretching - Mobility/standing quadriceps stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('fd14ec19-60ed-4eed-b6f8-7fe179ff073d'::uuid, 'Standing quadriceps stretch side angle', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and find a stable surface to hold onto for balance if needed.\r\n2. Bend your right knee and bring your heel towards your glutes. Grasp your right ankle with your right hand.\r\n3. Keep your knees close together and lightly pull your right ankle upward, feeling a stretch along the front of your right thigh.\r\n4. Hold the stretch for 20-30 seconds, then release your right ankle and return to the starting position. Repeat the stretch on the left leg.', E'1. Perform the stretch slowly and with control to maximize muscle flexibility and reduce injury risk.\r\n2. Ensure your supporting leg remains slightly bent to maintain balance.\r\n3. Focus on keeping your torso upright and avoid leaning forward or backward.', '{"image_male_start":"images/Stretching - Mobility/Standing quadriceps stretch side angle  .jpg","video_url":"videos/Stretching - Mobility/Standing quadriceps stretch side angle  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e4e2ded3-6752-4b1c-8f1f-9f96a56b8dcb'::uuid, 'Standing reverse shoulder stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, keeping your posture upright. Clasp your hands behind your back, interlocking your fingers.\r\n2. Straighten your arms and slowly lift your hands upwards, feeling a stretch in your shoulders.\r\n3. Hold the stretch for 20-30 seconds, and return to the starting position by lowering your hands and releasing the clasp. \r\n4. Repeat the stretch for the desired number of repetitions.', E'1. Focus on keeping your arms straight and avoiding any bending at the elbows.\r\n2. Ensure your shoulders remain relaxed and avoid tensing them up towards your ears.\r\n3. Use a gentle motion to avoid over-stretching and potential muscle strain.', '{"image_male_start":"images/Shoulders/standing reverse shoulder stretch .jpg","video_url":"videos/Shoulders/standing reverse shoulder stretch .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('30d27801-1a69-4d91-872f-8a1c889cbaaa'::uuid, 'Standing shoulder press dumbbell', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand at shoulder height with your palms facing forward and elbows pointing to the floor.\r\n2. Press both dumbbells overhead until your arms are fully extended, keeping your elbows slightly bent at the top.\r\n3. Slowly lower the dumbbells back to shoulder height with control, maintaining tension in your shoulders.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Breathe steadily: exhale as you press the dumbbells up and inhale as you lower them down.\r\n2. Focus on using your shoulder muscles to lift the weight, avoiding excessive strain on your neck.\r\n3. Keep your back straight and avoid arching your lower back during the press.', '{"image_male_start":"images/Shoulders/Standing shoulder press dumbbell.jpg","image_male_end":"images/Shoulders/Standing shoulder press dumbbell1.jpg","video_url":"videos/Shoulders/Standing shoulder press dumbbell.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('5268ffe9-96de-4a9e-956f-9f24b14da1dd'::uuid, 'Standing side leg raises', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and your hands on your hips for balance.\r\n2. Shift your weight onto your left leg and slowly lift your right leg out to the side as high as you comfortably can, keeping it straight.\r\n3. Hold the raised leg for a second, and slowly lower your right leg back to the starting position with control. \r\n4. Repeat for the desired number of repetitions, then switch to your left leg.', E'1. Focus on keeping your torso upright and avoid leaning to the side.\r\n2. Keep your supporting leg slightly bent to maintain balance.\r\n3. Start with a smaller range of motion and gradually increase it as your strength improves.', '{"image_male_start":"images/Legs/Standing Side leg raises  .jpg","video_url":"videos/Legs/Standing Side leg raises  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ec0d0181-9670-40cd-ad9a-a5fcf9a1acac'::uuid, 'Standing side slope stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, keeping your posture upright. Raise your right arm overhead and allow your left hand to hang by your side.\r\n2. Gently lean your torso to the left, reaching your right arm over your head and feeling a stretch along the right side of your torso.\r\n3. Hold the stretch for 20-30 seconds, and slowly return to the starting position.\r\n4. Perform the stretch for the desired number of repetitions on each side.', E'1. Ensure your shoulders remain relaxed and avoid tensing them up towards your ears.\r\n2. Use a gentle motion to avoid over-stretching and potential muscle strain.\r\n3. Gradually increase the depth of the stretch as your flexibility improves.', '{"image_male_start":"images/Stretching - Mobility/standing side slope stretch  .jpg","video_url":"videos/Stretching - Mobility/standing side slope stretch  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e587413d-0f5c-4bb7-9cd4-e73ed49934a6'::uuid, 'Standing swimmer', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, your left arm extended up, your right arm extended down, and your palms facing forward.\r\n2. Simultaneously move your right arm up while moving your left arm down and lightly rotating your core, mimicking a swimming motion. Keep your arms straight throughout the movement.\r\n3. Continue alternating arms in a smooth, controlled motion for the desired repetitions.', E'1. Keep your core tight to maintain balance and stability.\r\n2. Focus on keeping your movements smooth and fluid, avoiding any jerky motions.\r\n3. Breathe steadily: exhale as you move your arms back and inhale as you return to the starting position.', '{"image_male_start":"images/Shoulders/standing swimmer .jpg","video_url":"videos/Shoulders/standing swimmer .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('08e017d1-521b-48a0-bc86-88182214a59b'::uuid, 'Standing toe touch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, keeping your posture upright and your arms relaxed by your sides.\r\n2. Simultaneously lift your right leg straight up to hip height while raising your left arm to touch your right toes.\r\n3. Return your right leg and left arm to the starting position with control.\r\n4. Repeat the movement on the opposite side. Continue alternating sides for the desired number of repetitions.', E'1. Focus on keeping both your leg and arm straight throughout the movement.\r\n2. Ensure your supporting leg remains slightly bent to maintain balance.\r\n3. Keep your core tight to maintain balance and stability.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/standing toe touch  .jpg","video_url":"videos/Calisthenics-Cardio-Functional/standing toe touch  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('43145226-2926-4533-95b5-4d257f16ba84'::uuid, 'Standing Y raise', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, with your arms extended forward, parallel to each other.\r\n2. With slightly bent elbows, raise both arms diagonally overhead to form a "Y" shape.\r\n3. Slowly lower your arms back to the starting position. \r\n4. Repeat the movement for the desired repetitions', E'1. Move slowly and with control to maximize muscle activation and avoid injury.\r\n2. Breathe steadily: exhale as you raise your arms and inhale as you lower them.\r\n3. Focus on keeping your arms in a diagonal line to form a "Y" shape and avoid any excessive swinging.', '{"image_male_start":"images/Shoulders/standing y raise .jpg","video_url":"videos/Shoulders/standing y raise .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('fbe0e96d-4ab6-4be3-8534-9b0c76b5a8f5'::uuid, 'Star crunches', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie flat on your back with your arms and legs extended out to form an "X" shape. Keep your core engaged and your lower back pressed into the floor.\r\n2. Crunch your abdominal muscles to lift your shoulders and legs off the floor and lift your arms and legs towards each other, reaching your hands towards your ankles.\r\n3. Lower your arms and legs back to the starting position with control.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Breathe steadily: exhale as you lift your arm and leg, and inhale as you return to the starting position.\r\n2. Focus on using your abdominal muscles to lift your arms and legs off the floor.\r\n3. Use a mat to provide cushioning and support for your back.\r\n', '{"image_male_start":"images/Abdominals/star crunches.jpeg","video_url":"videos/Abdominals/star crunches.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e7760613-f80d-4e81-823d-b82e6ef1d5b8'::uuid, 'Star jump', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet together and your arms by your sides, maintaining an upright posture.\r\n2. Bend your knees slightly and lower into a half-squat position to prepare for the jump.\r\n3. Explosively jump upwards, spreading your legs out to the sides and extending your arms overhead to form a star shape in mid-air.\r\n4. Land softly with your feet together and your arms by your sides, immediately bending your knees to absorb the impact. Repeat the movement for the desired number of repetitions.', E'1. Focus on using your leg muscles to generate the jump, avoiding excessive strain on your knees.\r\n2. Ensure your knees are slightly bent as you land to absorb the impact and prevent injury.\r\n3. Start with smaller jumps to perfect your form before increasing the height.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/star jump.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/star jump1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/star jump.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('51341d25-8761-4976-ae78-3997c6440c9f'::uuid, 'Stationary Exercise Bike', 'Resistance', 'strength', 'weight_reps', 'intermediate', '791b8ac0-fb3c-4b64-b6a6-8790852c4f0a'::uuid, E'1. Adjust the seat height so that when you sit on the bike, your feet can comfortably reach the pedals with a slight bend in your knees at the bottom of the pedal stroke.\r\n2. Sit on the bike with your back straight, and grip the handlebars lightly. Place your feet securely on the pedals, ensuring they are aligned properly.\r\n3. Begin pedaling by pushing down on one pedal while pulling up on the opposite pedal, creating a smooth, circular motion.\r\n4. Adjust the resistance level using the bike''s control knob or digital settings to match your desired intensity. Continue pedaling for the duration of your workout.', E'1. Maintain good posture by keeping your back straight and shoulders relaxed to avoid strain.\r\n2. Start with a lower resistance level if you are a beginner and gradually increase it as you build strength and endurance.\r\n3. Breathe steadily throughout the exercise, inhaling deeply and exhaling fully.', '{"image_male_start":"images/Calisthenics-Cardio-Functional/Stationary Exercise Bike.jpg","image_male_end":"images/Calisthenics-Cardio-Functional/Stationary Exercise Bike1.jpg","video_url":"videos/Calisthenics-Cardio-Functional/Stationary Exercise Bike.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('b7b4608a-2a16-4880-b7e7-b7345943e8eb'::uuid, 'Step up on chair bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand facing a sturdy chair with your feet shoulder-width apart, keeping your posture upright.\r\n2. Place your left foot firmly on the chair, ensuring your entire foot is supported.\r\n3. Push through your left heel to lift your body onto the chair, bringing your right foot up to stand on the chair with both feet.\r\n4. Step down carefully with your right foot first, followed by your left foot. Repeat the movement for the desired number of repetitions, then switch legs.', E'1. Breathe steadily: exhale as you step up and inhale as you step down.\r\n2. Focus on pushing through your heel to engage your glutes and quadriceps.\r\n3. Ensure the chair or bench is stable and secure before starting the exercise.', '{"image_male_start":"images/Legs/step up on chair bodyweight  .jpg","video_url":"videos/Legs/step up on chair bodyweight  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('fc0eac28-376b-4a7f-ae57-8fc7b30fbcf8'::uuid, 'Straight bar cable pull down', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd8a6a67e-71db-4542-9dd7-a185a3e773af'::uuid, E'1. Stand facing a cable machine with a straight bar attached to the high pulley. Grip the bar with your hands slightly wider than shoulder-width apart, palms facing down.\r\n2. Slightly bend your knees, push your hips back, and lean your torso forward slightly. Pull the bar down towards your thighs in a straight line, keeping your arms straight and your elbows slightly bent.\r\n3. Pull the bar down until it reaches your thighs, feeling a strong contraction in your lats.\r\n4. Slowly return the bar to the starting position with control, maintaining tension in your lats. Repeat for the desired number of repetitions.', E'1. Breathe steadily: exhale as you pull the bar down and inhale as you return it to the starting position.\r\n2. Adjust the weight on the cable machine to provide enough challenge without compromising form.\r\n3. Keep your shoulders relaxed and avoid shrugging them towards your ears.', '{"image_male_start":"images/Back/straight bar cable pull down .jpg","video_url":"videos/Back/straight bar cable pull down .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('f4bef478-fae8-499b-83f8-fe4bfe92b8ad'::uuid, 'Straight bar cable row close grip', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'b7ec08fd-b7eb-4a14-a54d-f3d91be90da6'::uuid, E'1. Sit at a cable row machine with your feet placed on the footrests and knees slightly bent. Grasp the straight bar with a close grip, palms facing down.\r\n2. Engage your core and maintain a straight back. Pull the bar towards your abdomen, squeezing your shoulder blades together and keeping your elbows close to your body.\r\n3. Hold the contraction for a moment, feeling the muscles in your back activating.\r\n4. Slowly extend your arms to return the bar to the starting position. Repeat for the desired number of repetitions.', E'1. Breathe steadily: exhale as you pull the bar towards you and inhale as you extend your arms.\r\n2. Adjust the weight on the cable machine to provide enough challenge without compromising form.\r\n3. Keep your shoulders relaxed and avoid shrugging them towards your ears.', '{"image_male_start":"images/Back/straight bar cable row close grip .jpg","video_url":"videos/Back/straight bar cable row close grip .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('79306464-7fa3-46b9-b390-cd5b48ac2b29'::uuid, 'Straight bar cable row normal grip', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'b7ec08fd-b7eb-4a14-a54d-f3d91be90da6'::uuid, E'1. Sit at a cable row machine with your feet placed on the footrests and knees slightly bent. Grasp the straight bar with hands just wider than shoulder-width, palms facing down.\r\n2. Engage your core and maintain a straight back. Pull the bar towards your abdomen, squeezing your shoulder blades together and keeping your elbows close to your body.\r\n3. Hold the contraction for a moment, feeling the muscles in your back activating.\r\n4. Slowly extend your arms to return the bar to the starting position. Repeat for the desired number of repetitions.', E'1. Breathe steadily: exhale as you pull the bar towards you and inhale as you extend your arms.\r\n2. Adjust the weight on the cable machine to provide enough challenge without compromising form.\r\n3. Keep your shoulders relaxed and avoid shrugging them towards your ears.', '{"image_male_start":"images/Back/straight bar cable row normal grip .jpg","video_url":"videos/Back/straight bar cable row normal grip .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('74c84a36-1cdc-49f9-aaa1-e07a9d2e584b'::uuid, 'Sumo squat in between legs Resistance band', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet wider than shoulder-width apart, toes pointing slightly outward. Place a resistance band under your feet.\r\n2. Hold the ends of the resistance band with both hands in between your legs, keeping your hands at hip level.\r\n3. Lower your body into a squat by bending your knees and pushing your hips back. Keep your chest up and your back straight.\r\n4. Lower until your thighs are parallel to the floor, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', E'1. Breathe steadily: inhale as you lower into the squat and exhale as you push back up to the starting position.\r\n2. Focus on keeping your knees in line with your toes to avoid inward collapse.\r\n3. Ensure your chest stays up and avoid leaning forward excessively.', '{"image_male_start":"images/Legs/sumo squat in between legs resistance band.jpg","image_male_end":"images/Legs/sumo squat in between legs resistance band1.jpg","video_url":"videos/Legs/sumo squat in between legs resistance band.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0c8329bb-1ba9-457b-8d2e-ef18ea1bed8c'::uuid, 'Sumo squat over shoulder Resistance band', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet wider than shoulder-width apart, toes pointing slightly outward. Place a resistance band under your feet.\r\n2. Hold the ends of the resistance band with both hands near your shoulders, palms facing forward and elbows pointing down.\r\n3. Lower your body into a squat by bending your knees and pushing your hips back. Keep your chest up and your back straight.\r\n4. Lower until your thighs are parallel to the floor, then push through your heels to return to the starting position. Repeat for the desired number of repetitions.', E'1. Breathe steadily: inhale as you lower into the squat and exhale as you push back up to the starting position.\r\n2. Focus on keeping your knees in line with your toes to avoid inward collapse.\r\n3. Ensure your chest stays up and avoid leaning forward excessively.', '{"image_male_start":"images/Legs/Sumo squat over shoulder resistance band.jpg","image_male_end":"images/Legs/Sumo squat over shoulder resistance band1.jpg","video_url":"videos/Legs/Sumo squat over shoulder resistance band.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c9d01402-b1e2-4bc0-bd4c-978b9651de3b'::uuid, 'Superman', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie face down on the floor with your arms extended straight out in front of you and your legs extended straight behind you.\r\n2. Simultaneously lift your arms, chest, and legs off the floor as high as you comfortably can, engaging your lower back and glutes.\r\n3. Hold the lifted position for a second, feeling the contraction in your lower back and glutes.\r\n4. Slowly lower your arms, chest, and legs back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Focus on using your lower back and glute muscles to lift your body off the floor.\r\n2. Keep your neck in a neutral position to avoid straining it.\r\n3. Use a mat to provide cushioning and support for your body.', '{"image_male_start":"images/Back/superman .jpg","video_url":"videos/Back/superman .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c19e4aa9-e8b9-43ef-8b94-3d1f192a8b7a'::uuid, 'Superman holds', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie face down on the floor with your arms extended straight out in front of you and your legs extended straight behind you.\r\n2. Simultaneously lift your arms, chest, and legs off the floor as high as you comfortably can, engaging your lower back and glutes.\r\n3. Hold the lifted position for 5-10 seconds, feeling the contraction in your lower back and glutes.\r\n4. Slowly lower your arms, chest, and legs back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Focus on using your lower back and glute muscles to lift your body off the floor.\r\n2. Keep your neck in a neutral position to avoid straining it.\r\n3. Use a mat to provide cushioning and support for your body.', '{"image_male_start":"images/Yoga/superman holds.jpg","image_male_end":"images/Yoga/superman holds1.jpg","video_url":"videos/Yoga/superman holds.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a3ed4048-5c64-4a2c-9c83-0bf6569e766e'::uuid, 'Superman pulls', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie face down on the floor with a resistance band secured to a low anchor point in front of you. Hold one end of the resistance band in each hand with your arms extended straight out in front of you and your legs extended straight behind you.\r\n2. Simultaneously lift your arms, chest, and legs off the floor as high as you comfortably can, engaging your lower back and glutes.\r\n3. While holding the lifted position, bend your elbows and pull the resistance band towards your shoulders, squeezing your shoulder blades together.\r\n4. Extend your arms back out in front of you, keeping tension on the resistance band, and then slowly lower your arms, chest, and legs back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Focus on using your lower back and glute muscles to lift your body off the floor.\r\n2. Keep your neck in a neutral position to avoid straining it.\r\n3. Use a mat to provide cushioning and support for your body.', '{"image_male_start":"images/Back/superman pulls .jpg","video_url":"videos/Back/superman pulls .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e759d9c2-4149-4bd3-aa7f-f2a5bc598da4'::uuid, 'Superman pulls Resistance band', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Lie face down on the floor with your arms extended straight out in front of you and your legs extended straight behind you.\r\n2. Simultaneously lift your arms and chest off the floor as high as you comfortably can, engaging your lower back and glutes.\r\n3. While holding the lifted position, bend your elbows and pull your arms back towards your shoulders, squeezing your shoulder blades together.\r\n4. Extend your arms back out in front of you and slowly lower your chest back to the starting position. Repeat for the desired repetitions.', E'1. Breathe steadily: exhale as you lift and pull the resistance band, and inhale as you extend your arms and lower your body.\r\n2. Gradually increase the duration of the hold and the number of repetitions as your strength improves.\r\n3. Keep your neck in a neutral position to avoid straining it.\r\n', '{"image_male_start":"images/Back/superman pulls resistance band.jpg","image_male_end":"images/Back/superman pulls resistance band1.jpg","video_url":"videos/Back/superman pulls resistance band.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('58eeab79-d3e3-4b18-acbc-21ff7cd8c8d9'::uuid, 'Supine push up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your knees bent and feet flat on the floor. Position your elbows to your sides with your forearms perpendicular to the floor and hands kept closed.\r\n2. Engage your core and press your elbows into the floor, lifting your upper back and shoulders off the floor.\r\n3. Hold the lifted position for a second, feeling the contraction in your upper back.\r\n4. Slowly lower your upper back and shoulders back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Breathe steadily: exhale as you lift your upper back and shoulders, and inhale as you lower them back down.\r\n2. Focus on using your shoulders and upper back muscles to lift your upper body off the floor.\r\n3. Use a mat to provide cushioning and support for your back.', '{"image_male_start":"images/Back/Supine Push up .jpg","video_url":"videos/Back/Supine Push up .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ee2f6c25-71b6-4011-a54d-6912713d6c71'::uuid, 'Svend press decline bench', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'ba1cac69-c4db-4c14-8076-0f34af9c1f91'::uuid, E'1. Lie on a decline bench with your feet secured under the foot pads and your back firmly against the bench. Hold a weight plate with both hands, pressing your palms against the flat sides of the plate at chest level with your fingers pointing up.\r\n2. Engage your chest and press the weight plate straight out in front of you by extending your arms.\r\n3. Squeeze your chest muscles as you press the plate outward until your arms are fully extended.\r\n4. Slowly bring the plate back to your chest with control. Repeat for the desired number of repetitions.', E'1. Focus on pressing through your chest, not your shoulders, to emphasize chest muscle activation.\r\n2. Choose a weight that challenges you but allows you to maintain proper form.\r\n3. Avoid locking your elbows completely at the top of the movement to keep tension on the chest muscles.', '{"image_male_start":"images/Chest/svend press decline bench.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('c03aeb39-5fa9-489e-8035-bc492834a025'::uuid, 'Svend press flat bench', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'ba1cac69-c4db-4c14-8076-0f34af9c1f91'::uuid, E'1. Lie on a flat bench with your feet flat on the floor and your back firmly against the bench. Hold a weight plate with both hands, pressing your palms against the flat sides of the plate at chest level with your fingers pointing up.\r\n2. Engage your chest and press the weight plate straight out in front of you by extending your arms.\r\n3. Squeeze your chest muscles as you press the plate outward until your arms are fully extended.\r\n4. Slowly bring the plate back to your chest with control. Repeat for the desired number of repetitions.', E'1. Focus on pressing through your chest, not your shoulders, to emphasize chest muscle activation.\r\n2. Choose a weight that challenges you but allows you to maintain proper form.\r\n3. Avoid locking your elbows completely at the top of the movement to keep tension on the chest muscles.', '{"image_male_end":"images/Chest/svend press  flat bench.jpg","video_url":"videos/Chest/svend press  flat bench  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('13c3ecdd-5c45-48a7-9230-3ab8e283e3ee'::uuid, 'Svend press incline bench', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'ba1cac69-c4db-4c14-8076-0f34af9c1f91'::uuid, E'1. Lie on an incline bench with your feet flat on the floor and your back firmly against the bench. Hold a weight plate with both hands, pressing your palms against the flat sides of the plate at chest level with your fingers pointing up.\r\n2. Engage your chest and press the weight plate straight out in front of you by extending your arms.\r\n3. Squeeze your chest muscles as you press the plate outward until your arms are fully extended.\r\n4. Slowly bring the plate back to your chest with control. Repeat for the desired number of repetitions.', E'1. Focus on pressing through your chest, not your shoulders, to emphasize chest muscle activation.\r\n2. Choose a weight that challenges you but allows you to maintain proper form.\r\n3. Avoid locking your elbows completely at the top of the movement to keep tension on the chest muscles.', '{"image_male_start":"images/Chest/svend press incline bench.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('37bcaa3e-4ff0-48f4-b5cd-4cdf5057005e'::uuid, 'Trap bar deadlift', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'd2db0953-15ad-4c5e-81e2-0c301cedd1b7'::uuid, E'1. Stand in the center of a trap bar with your feet shoulder-width apart. Bend your knees and hips to lower your body, and grasp the trap bar handles with a neutral grip (palms facing in).\r\n2. Engage your core; keep your chest up and your back straight. Push through your heels to lift the trap bar off the floor, extending your hips and knees simultaneously.\r\n3. Stand up straight, pulling your shoulders back at the top of the movement.\r\n4. Slowly lower the bar back to the floor by bending your hips and knees, maintaining a straight back. Repeat for the desired number of repetitions.', E'1. Ensure your chest remains up and your back stays straight to avoid injury.\r\n2. Push through your heels to engage your glutes and hamstrings effectively.\r\n3. Avoid locking your knees completely at the top of the movement to maintain tension in your muscles.', '{"image_male_start":"images/Back/trap bar deadlift.jpg","image_male_end":"images/Back/trap bar deadlift1.jpg","video_url":"videos/Back/trap bar deadlift.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('46ba3d1b-04f5-4bd1-9e2b-38a3f1a8375e'::uuid, 'Trap bar shrug', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand in the center of a trap bar with your feet shoulder-width apart. Bend your knees and hips to lower your body, and grasp the handles of the trap bar with a neutral grip (palms facing in).\r\n2. Stand up straight with the trap bar at arm''s length by your sides, keeping your core engaged and back straight.\r\n3. Lift your shoulders towards your ears, squeezing your traps at the top of the movement.\r\n4. Slowly lower your shoulders back to the starting position. Repeat for the desired number of repetitions.', E'1. Breathe steadily: exhale as you shrug your shoulders and inhale as you lower them.\r\n2. Keep your neck relaxed and avoid straining it during the movement.\r\n3. Ensure your back remains straight and avoid leaning forward or backward.', '{"image_male_start":"images/Shoulders/trap bar shrug .jpg","video_url":"videos/Shoulders/trap bar shrug .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7b00bd88-5a81-47bd-92d9-4f7095735165'::uuid, 'Tricep cable kickback on crossover machine', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Stand facing the cable machine with your feet shoulder-width apart, and set the cable at a low position. Hold the cable end in one hand and bend slightly forward at the hips, keeping your back straight and your knees slightly bent.\r\n2. Position your upper arm parallel to the floor with your elbow bent at a 90-degree angle, keeping your elbow close to your side.\r\n3. Extend your arm backward by straightening your elbow, keeping your upper arm stationary, and only moving your forearm.\r\n4. Slowly return to the starting position by bending your elbow. Repeat for the desired number of repetitions, then switch arms.', E'1. Focus on using your triceps to perform the extension, avoiding excessive use of your shoulders or back.\r\n2. Keep your upper arm stationary throughout the exercise to ensure proper form.\r\n3. Use a weight that allows you to maintain control and proper form throughout the exercise.', '{"image_male_start":"images/Triceps/tricep cable kickback on crossover machine.jpeg","video_url":"videos/Triceps/tricep cable kickback on crossover machine.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('33208078-11ee-4d70-99b3-2ed1fda5ad12'::uuid, 'Tricep extension machine', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'b65535fb-68b6-4023-99b6-c3882b1aa15e'::uuid, E'1. Sit on the tricep extension machine, adjusting the seat height so that your upper arms comfortably rest on the arm pad, with your elbows bent at a 90-degree angle.\r\n2. Grasp the handles with a neutral grip, ensuring your elbows are below the pivot point.\r\n3. Push the handles forward by straightening your elbows and fully extending your arms while keeping your upper arms stationary.\r\n4. Slowly return to the starting position by bending your elbows. Repeat for the desired number of repetitions.', E'1. Breathe steadily: exhale as you extend your arms and inhale as you return to the starting position.\r\n2. Focus on using your triceps to push the handles, avoiding excessive use of your shoulders or back.\r\n3. Keep your upper arms stationary on the pad to ensure proper form.', '{"image_male_start":"images/Triceps/Tricep Extension Machine.jpg","image_male_end":"images/Triceps/Tricep Extension Machine1.jpg","image_female_start":"images/Triceps/Tricep Extension Machine_Female.jpg","image_female_end":"images/Triceps/Tricep Extension Machine_Female1.jpg","video_url":"videos/Triceps/Tricep Extension Machine.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('e3cd1e8e-213d-47d1-b19e-52c618b8ec1c'::uuid, 'Triceps dip machine', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'ae580acb-3c8a-4589-a39d-863915b3b75f'::uuid, E'1. Sit down on the triceps dip machine and place your feet flat on the floor. Adjust the seat height so that your upper arms are parallel to the floor when you grasp the handles.\r\n2. Grip the handles firmly, keeping your elbows bent and close to your sides. Slightly lean your torso forward.\r\n3. Push the handles downward by straightening your elbows and extending your arms fully while keeping your upper arms stationary.\r\n4. Slowly return to the starting position. Repeat for the desired number of repetitions.', E'1. Keep your elbows close to your sides throughout the exercise to ensure proper form.\r\n2. Avoid locking your elbows completely at the end of the movement to maintain tension in your triceps.\r\n3. Use a weight that allows you to maintain control and proper form throughout the exercise.', '{"image_male_start":"images/Triceps/triceps dip machine.jpeg","video_url":"videos/Triceps/triceps dip machine.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('33470a11-c638-4ce0-9316-eab3cc8b4809'::uuid, 'Triceps light stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and raise your right arm at chest height across your chest, bending your elbow.\r\n2. Use your left hand to gently grab your right elbow, pulling it across your chest to deepen the stretch in your triceps.\r\n3. Hold the stretch for 20-30 seconds, feeling a gentle stretch in your triceps.\r\n4. Release the stretch and repeat with your left arm. Perform the stretch for the desired number of repetitions.', E'1. Avoid twisting your torso; keep it stable and facing forward.\r\n2. Breathe deeply and steadily, relaxing into the stretch.\r\n3. Do not pull too hard; the stretch should be gentle and not cause pain.', '{"image_male_start":"images/Stretching - Mobility/triceps light stretch  .jpg","video_url":"videos/Stretching - Mobility/triceps light stretch  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('74720f99-252a-4172-84d7-a6dc8993c983'::uuid, 'Triceps rope extension on crossover machine', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd96af026-8ebc-405b-8263-77b866cc82e3'::uuid, E'1. Attach a rope handle to the high pulley of a crossover machine. Stand facing the machine with your feet shoulder-width apart, and grasp the ends of the rope with both hands, palms facing each other.\r\n2. Step back slightly to create tension in the cable and position your body so your upper arms are close to your sides, and your elbows are bent at a 90-degree angle.\r\n3. Push the rope down by straightening your elbows, separating the rope ends, and extending your arms fully while keeping your upper arms stationary.\r\n4. Slowly return to the starting position by bending your elbows. Repeat for the desired number of repetitions.', E'1. Focus on using your triceps to push the rope, avoiding excessive use of your shoulders or back.\r\n2. Keep your upper arms stationary and close to your sides throughout the exercise to ensure proper form.\r\n3. Avoid locking your elbows completely at the end of the movement to maintain tension in your triceps.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('76675d18-413a-46f5-9018-eae4d9342833'::uuid, 'Upper back stretch', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart and extend your arms straight out in front of you at shoulder height, rounding your upper back and pushing your hands forward.\r\n2. Lower both arms backward, bringing them to your sides just past behind your hips.\r\n3. Hold the stretch for 20-30 seconds, feeling a gentle squeeze in your upper back and shoulder blades. \r\n4. Release and repeat for the desired number of repetitions.', E'1. Breathe deeply and steadily, relaxing into the stretch.\r\n2. Avoid shrugging your shoulders up towards your ears; keep them relaxed.\r\n3. Do not overextend your arms; the stretch should be gentle and not cause pain.', '{"image_male_start":"images/Stretching - Mobility/upper back stretch.jpg","image_male_end":"images/Stretching - Mobility/upper back stretch1.jpg","video_url":"videos/Stretching - Mobility/upper back stretch.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('51bc1e1e-3ea3-47e5-8c4c-58fa1a801bad'::uuid, 'Upright row barbell', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Stand with your feet shoulder-width apart, holding a barbell with an overhand grip (palms facing down), hands placed shoulder-width apart. Allow the barbell to rest against your thighs with your arms fully extended.\r\n2. Pull the barbell upward along the front of your body by bending your elbows and lifting your upper arms.\r\n3. Continue lifting the barbell until it reaches chest height, keeping your elbows higher than your wrists throughout the movement.\r\n4. Slowly lower the barbell back to the starting position by extending your arms fully. Repeat for the desired number of repetitions.', E'1. Lead with your elbows to ensure proper muscle engagement and avoid wrist strain.\r\n2. Breathe steadily, exhaling as you lift the barbell and inhaling as you lower it back down.\r\n3. Avoid using momentum or swinging your body to lift the barbell.', '{"image_male_start":"images/Shoulders/upright row barbell .jpg","video_url":"videos/Shoulders/upright row barbell .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('4a697a56-68ed-4e42-8fef-671b4d96690b'::uuid, 'Upright row cable Resistance band', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart in the middle of a resistance band, holding a handle in each hand with an overhand grip (palms facing back). Ensure the band is taut when your arms are extended downwards.\r\n2. Lift the handles straight up towards your chin, leading with your elbows and keeping the band close to your body.\r\n3. Raise the handles until your elbows are slightly higher than your shoulders and pointing to your sides.\r\n4. Slowly lower the handles back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Breathe steadily: exhale as you lift the handles and inhale as you lower them.\r\n2. Use a resistance band that allows you to maintain control and proper form throughout the exercise.\r\n3. Avoid lifting the handles too high, which can put unnecessary strain on your shoulder joints.', '{"image_male_start":"images/Shoulders/upright row cable resistance band .jpg","video_url":"videos/Shoulders/upright row cable resistance band .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ccdc1401-44fe-4e7d-a4f3-057ecb38470f'::uuid, 'Upright row dumbbell', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an overhand grip (palms facing your thighs). Let the dumbbells rest against your thighs.\r\n2. Lift the dumbbells straight up towards your chin, leading with your elbows and keeping the weights close to your body.\r\n3. Raise the dumbbells until your elbows are level with your shoulders, ensuring your upper arms are parallel to the floor.\r\n4. Slowly lower the dumbbells back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Breathe steadily: exhale as you lift the dumbbells and inhale as you lower them.\r\n2. Focus on using your shoulders and upper back to lift the dumbbells, avoiding excessive use of your biceps.\r\n3. Avoid lifting the dumbbells too high, which can put unnecessary strain on your shoulder joints.', '{"image_male_start":"images/Shoulders/upright row dumbbell.jpg","image_male_end":"images/Shoulders/upright row dumbbell1.jpg","video_url":"videos/Shoulders/upright row dumbbell.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('0123e32b-dfc3-4337-9d9e-d17538d7f17a'::uuid, 'Upright row ez bar', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '0e9c1392-3e8d-454d-be69-641c3a69f2b9'::uuid, E'1. Stand with your feet shoulder-width apart, holding an EZ Bar with an overhand grip (palms facing down), hands placed shoulder-width apart. Allow the barbell to rest against your thighs with your arms fully extended.\r\n2. Pull the EZ Bar upward along the front of your body by bending your elbows and lifting your upper arms.\r\n3. Continue lifting the EZ Bar until it reaches chest height, keeping your elbows higher than your wrists throughout the movement.\r\n4. Slowly lower the EZ Bar back to the starting position by extending your arms fully. Repeat for the desired number of repetitions.', E'1. Lead with your elbows to ensure proper muscle engagement and avoid wrist strain.\r\n2. Breathe steadily, exhaling as you lift the barbell and inhaling as you lower it back down.\r\n3. Avoid using momentum or swinging your body to lift the EZ Bar.', '{"image_male_start":"images/Shoulders/upright row ez bar .jpg","video_url":"videos/Shoulders/upright row ez bar .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a2d92b50-d25f-409c-ae18-d1ea2a4cd619'::uuid, 'Upward rotation Bent arms', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your feet shoulder-width apart, arms bent at 90 degrees with your upper arms parallel to the floor, and your forearms pointing down to the floor.\r\n2. Rotate your forearms upwards until your fingers point towards the ceiling, keeping your upper arms stationary.\r\n3. Slowly rotate them back to the starting position.\r\n4. Repeat for the desired repetitions', E'1. Focus on using your shoulder muscles to rotate your arms, avoiding excessive use of your neck or back.\r\n2. Keep your upper arms stationary throughout the movement to ensure proper form.\r\n3. Lift your arms as high as comfortable, to avoid unnecessary strain on your shoulder joints.', '{"image_male_start":"images/Shoulders/upward rotation bent arms.jpg","image_male_end":"images/Shoulders/upward rotation bent arms1.jpg","video_url":"videos/Shoulders/upward rotation bent arms.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('ecc664ba-7c26-4b35-a54d-5e11940f71ca'::uuid, 'V bar lat pull down', 'Resistance', 'strength', 'weight_reps', 'intermediate', 'd8a6a67e-71db-4542-9dd7-a185a3e773af'::uuid, E'1. Sit at a lat pulldown machine with your feet flat on the floor and knees secured under the pads. Grasp the V-bar attached to the machine, arms fully extended above you, and hands shoulder-width apart.\r\n2. Pull the bar down towards your upper chest and bring your elbows downwards.\r\n3. Squeeze your shoulder blades together at the bottom of the movement.\r\n4. Slowly return the V-bar to the starting position. Repeat for the desired repetitions.', E'1. Breathe steadily: exhale as you pull the bar down and inhale as you return to the starting position.\r\n2. Focus on using your back muscles to pull the bar, avoiding excessive use of your arms.\r\n3. Keep your wrists straight and avoid bending them during the pull to prevent strain.', '{"image_male_start":"images/Back/v bar lat pull down .jpg","video_url":"videos/Back/v bar lat pull down .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('18ca941c-1eea-4d8f-a1be-8cd705ad6947'::uuid, 'V crunches', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie flat on your back on the floor with your legs extended and your arms extended on the floor overhead.\r\n2. Simultaneously lift your legs and torso off the floor, reaching your hands towards your feet to form a ''V'' shape with your body.\r\n3. Squeeze your abdominal muscles at the top of the movement, ensuring your hands reach towards your feet.\r\n4. Slowly lower your legs and torso back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Breathe steadily: exhale as you lift into the ''V'' position and inhale as you lower back down.\r\n2. Avoid using momentum to lift your legs and torso; focus on using your abdominal muscles.\r\n3. Keep your legs and arms straight throughout the movement for maximum effectiveness.', '{"image_male_start":"images/Abdominals/V crunches.jpeg","video_url":"videos/Abdominals/V crunches.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('16a4c1b1-6f1a-40e9-bdfd-29af66da0380'::uuid, 'V up', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie flat on your back on the floor with your legs and arms extended so that your body forms a straight line.\r\n2. Simultaneously lift your legs and torso off the floor, reaching your hands towards your feet to form a ''V'' shape with your body.\r\n3. Squeeze your abdominal muscles at the top of the movement, ensuring your hands reach towards your feet.\r\n4. Slowly lower your legs and torso back to the starting position with control. Repeat for the desired number of repetitions.', E'1. Breathe steadily: exhale as you lift into the ''V'' position and inhale as you lower back down.\r\n2. Avoid using momentum to lift your legs and torso; focus on using your abdominal muscles.\r\n3. Keep your legs and arms straight throughout the movement for maximum effectiveness.', '{"image_male_start":"images/Abdominals/v up.jpeg","video_url":"videos/Abdominals/v up .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('589bd45e-ea00-448f-9817-0220eb863d40'::uuid, 'Walkout', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand upright with your feet shoulder-width apart and arms relaxed by your sides.\r\n2. Bend your hips and knees to place your hands on the floor before you.\r\n3. Walk your hands forward, keeping your legs straight, until you are in a plank position with your hands under your shoulders and your body forming a straight line from head to heels.\r\n4. Walk your hands back towards your feet, lifting your hips and forming an inverted V shape with your body. Repeat for the desired number of repetitions.', E'1. Avoid letting your hips sag or rise too high when in the plank position.\r\n2. Keep your legs as straight as possible while walking your hands to and from the plank position.\r\n3. Use a mat to provide cushioning for your hands and prevent slipping.', '{"image_male_start":"images/Abdominals/walkout.jpeg","video_url":"videos/Abdominals/walkout .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2955404a-c712-456c-8706-b4d59a2343c8'::uuid, 'Wall sit bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your back against a wall and your feet shoulder-width apart, about 2 feet away from the wall.\r\n2. Slide your back down the wall until your thighs are parallel to the floor, and your knees are directly above your ankles.\r\n3. Hold this position, keeping your back flat against the wall and your hands relaxed by your sides or on your thighs.\r\n4. Maintain the position for the desired duration, then slowly stand back up.', E'1. Ensure your knees do not extend past your toes to avoid placing unnecessary strain on your joints.\r\n2. Breathe steadily and avoid holding your breath during the exercise.\r\n3. Press your lower back firmly against the wall to ensure proper alignment.', '{"image_male_start":"images/Legs/wall sit bodyweight.jpg","image_male_end":"images/Legs/wall sit bodyweight1.jpg","video_url":"videos/Legs/wall sit bodyweight.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('19c10f33-cbde-4d8e-9951-62e328e45dca'::uuid, 'Wall squat bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your back against a wall and your feet shoulder-width apart, about 2 feet away from the wall.\r\n2. Slide your back down the wall until your thighs are parallel to the floor and your knees are at a 90-degree angle, ensuring your knees are directly above your ankles.\r\n3. Push through your heels to stand back up, sliding your back up the wall until you return to the starting position.\r\n4. Repeat for the desired number of repetitions.', E'1. Ensure your knees do not extend past your toes to avoid placing unnecessary strain on your joints.\r\n2. Breathe steadily: inhale as you lower into the squat and exhale as you stand back up.\r\n3. Press your lower back firmly against the wall to ensure proper alignment and support.', '{"image_male_start":"images/Legs/wall squat bodyweight.jpg","image_male_end":"images/Legs/wall squat bodyweight1.jpg","video_url":"videos/Legs/wall squat bodyweight.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7d8b8274-7a8d-4c73-bd20-40085047b19a'::uuid, 'Wall squat with pause bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Stand with your back against a wall and your feet shoulder-width apart, about 2 feet away from the wall.\r\n2. Slide your back down the wall until your thighs are parallel to the floor and your knees are at a 90-degree angle, ensuring your knees are directly above your ankles.\r\n3. Pause for 5-10 seconds and then push through your heels to stand back up, sliding your back up the wall until you return to the starting position.\r\n4. Repeat for the desired number of repetitions.', E'1. Ensure your knees do not extend past your toes to avoid placing unnecessary strain on your joints.\r\n2. Breathe steadily: inhale as you lower into the squat and exhale as you stand back up.\r\n3. Press your lower back firmly against the wall to ensure proper alignment and support.', '{"image_male_start":"images/Legs/wall squat with pause bodyweight  .jpg","video_url":"videos/Legs/wall squat with pause bodyweight  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('addd93dd-1fd3-4cdc-9991-9399c92362c3'::uuid, 'weighted standing shoulder press with plate', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'ba1cac69-c4db-4c14-8076-0f34af9c1f91'::uuid, E'1. Stand with your feet shoulder-width apart, holding a weight plate with both hands at chest level, elbows bent and pointing down.\r\n2. Press the plate upward by extending your arms fully above your head, keeping your core tight and your back straight.\r\n3. Lower the plate back down to chest level in a controlled manner.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Breathe steadily: exhale as you press the plate up and inhale as you lower it down.\r\n2. Avoid locking your elbows at the top of the press to keep tension on your shoulder muscles.\r\n3. Maintain a slight bend in your knees for better balance and support.', '{"image_male_start":"images/Shoulders/weighted standing shoulder press with plate .jpg","video_url":"videos/Shoulders/weighted standing shoulder press with plate .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('effe1235-96e9-48d0-87f5-14e3dd86a519'::uuid, 'Wheels To Heaven', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '9ffbc39a-4891-4f46-b1f7-17bd2c6b7261'::uuid, E'1. Lie on your back with your legs straight together, and your arms resting by your sides. Position an ab roller between your heels.\r\n2. Lift your legs up towards the ceiling, keeping them slightly bent, holding the ab roller securely between your heels.\r\n3. Engage your core and push your legs upward, raising your hips high off the floor.\r\n4. Lower your hips back down slowly keeping your legs up. Repeat for the desired number of repetitions.', E'1. Start with a smaller range of motion if you are new to the exercise and gradually increase it as you gain strength.\r\n2. Breathe steadily: exhale as you lift your legs and hips, and inhale as you lower them back down.\r\n3. Avoid using momentum to lift your hips; focus on using your abdominal muscles.', '{"image_male_start":"images/Abdominals/Wheels To Heaven_Female.jpeg","video_url":"videos/Abdominals/Wheels To Heaven.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('2a4c4d66-e201-407d-8f0d-3f3f9d8e3899'::uuid, 'Wheels To Toes', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '9ffbc39a-4891-4f46-b1f7-17bd2c6b7261'::uuid, E'1. Lie on your back with your legs straight together and your arms extended diagonally overhead, holding an ab roller.\r\n2. Lift your legs up towards the ceiling, keeping them straight, and simultaneously raise the ab roller towards your toes, lifting your upper back off the floor.\r\n3. Slowly lower your legs and the ab roller back down to the starting position, stopping just before they touch the floor.\r\n4. Repeat the movement for the desired number of repetitions.', E'1. Use a mat or soft surface to support your back and prevent discomfort.\r\n2. Ensure your lower back stays in contact with the floor when your legs are lowered.\r\n3. Start with a smaller range of motion if you are new to the exercise and gradually increase it as you gain strength.', '{"image_male_start":"images/Abdominals/Wheels To Toes_Female.jpeg","video_url":"videos/Abdominals/Wheels To Toes.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('a3d413e5-64d7-4007-baab-1daff57f2fda'::uuid, 'Wide push ups bodyweight', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Begin in a plank position with your hands placed wider than shoulder-width apart and your feet together. Your body should form a straight line from head to heels.\r\n2. Engage your chest and lower your body towards the floor by bending your elbows, keeping them at a 90-degree angle to your body.\r\n3. Lower your chest until it is just above the floor.\r\n4. Push through your hands to raise your body back to the starting position, fully extending your arms. Repeat for the desired number of repetitions.', E'1. Keep your elbows at a 90-degree angle to your body to maximize chest and triceps engagement and reduce shoulder strain.\r\n2. Breathe steadily, exhaling as you push up and inhaling as you lower yourself.\r\n3. Keep your head aligned with your spine to avoid straining your neck.', '{"image_male_start":"images/Chest/wide push ups bodyweight.jpg"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('64ab61a8-87e9-4a94-bbc1-328d633c38fe'::uuid, 'Wind wipers', 'Bodyweight', 'strength', 'weight_reps', 'intermediate', 'c262cf7f-b27f-4dc4-b751-e52a5389258b'::uuid, E'1. Lie on your back with your arms extended out to the sides for stability, lift your legs up towards the ceiling, and keep them bent at 90 degrees.\r\n2. Lower your knees to the right side, keeping them bent together until they are just above the floor.\r\n3. Raise your knees back to the center position, and then lower them to the left side until they are just above the floor.\r\n4. Repeat the movement, alternating sides, for the desired number of repetitions.', E'1. Use a mat or soft surface to support your back and prevent discomfort.\r\n2. Avoid using momentum to move your legs; focus on using your abdominal and oblique muscles.\r\n3. Keep your shoulders flat on the floor to maintain stability and proper form.', '{"image_male_start":"images/Abdominals/wind wipers.jpeg","video_url":"videos/Abdominals/wind wipers .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('52c38816-8cb9-44f6-a100-33944ff2ef37'::uuid, 'Wrist curl barbell', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Kneel on the floor in front of a bench, placing both forearms over the bench while holding a barbell with an underhand grip (palms facing up).\r\n2. Rest your wrists just off the edge of the bench, allowing the barbell to hang downward.\r\n3. Curl the barbell upward by flexing your wrists, lifting it as high as possible while keeping your forearms flat on the bench.\r\n4. Slowly lower the barbell back to the starting position, fully extending your wrists. Repeat for the desired number of repetitions.', E'1. Keep your forearms pressed firmly against the bench to isolate the wrist movement.\r\n2. Use a controlled motion to lift and lower the barbell, avoiding any jerking movements.\r\n3. Avoid using your shoulder or upper arm to lift the weight.', '{"image_male_start":"images/Forearms/wrist curl barbell.jpeg","video_url":"videos/Forearms/wrist curl barbell  .mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('98b7c9e3-857a-486b-ab78-a399768122c3'::uuid, 'Wrist curl dumbbell', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Kneel on the floor in front of a bench, placing both forearms over the bench while holding a dumbbell with an underhand grip (palms facing up) in each hand.\r\n2. Rest your wrists just off the edge of the bench, allowing the dumbbells to hang downward.\r\n3. Curl the dumbbells upward by flexing your wrists, lifting the weights as high as possible while keeping your forearms flat on the bench.\r\n4. Slowly lower the dumbbells back to the starting position, fully extending your wrists. Repeat for the desired number of repetitions.', E'1. Keep your forearms pressed firmly against the bench to isolate the wrist movement.\r\n2. Use a controlled motion to lift and lower the dumbbells, avoiding any jerking movements.\r\n3. Avoid using your shoulder or upper arm to lift the weight.', '{"image_male_start":"images/Forearms/wrist curl dumbbell.jpeg","video_url":"videos/Forearms/wrist curl dumbbell.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7f620f2a-df35-453f-af05-71d037c836aa'::uuid, 'Wrist extension barbell', 'Free Weights', 'strength', 'weight_reps', 'intermediate', '68ed06e5-fd1e-4198-8eea-6b4b13e3ede2'::uuid, E'1. Kneel on the floor in front of a bench, placing both forearms over the bench while holding a barbell with an overhand grip (palms facing down).\r\n2. Rest your wrists just off the edge of the bench, allowing the barbell to hang downward.\r\n3. Extend the barbell upward by flexing your wrists, lifting it as high as possible while keeping your forearms flat on the bench.\r\n4. Slowly lower the barbell back to the starting position, fully curling your wrists. Repeat for the desired number of repetitions.', E'1. Keep your forearms pressed firmly against the bench to isolate the wrist movement.\r\n2. Use a controlled motion to lift and lower the barbell, avoiding any jerking movements.\r\n3. Avoid using your shoulder or upper arm to lift the weight.', '{"image_male_start":"images/Forearms/Wrist extension barbell.jpeg","video_url":"videos/Forearms/Wrist extension barbell.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('7d45a25b-0db6-4b9b-a723-5cb3d975fb94'::uuid, 'Wrist extension dumbbell', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Kneel on the floor in front of a bench, placing both forearms over the bench while holding a dumbbell with an overhand grip (palms facing down) in each hand.\r\n2. Rest your wrists just off the edge of the bench, allowing the dumbbells to hang downward.\r\n3. Extend the dumbbells upward by flexing your wrists and lifting the weights as high as possible while keeping your forearms flat on the bench.\r\n4. Slowly lower the dumbbells back to the starting position, fully curling your wrists. Repeat for the desired number of repetitions.', E'1. Keep your forearms pressed firmly against the bench to isolate the wrist movement.\r\n2. Use a controlled motion to lift and lower the dumbbells, avoiding any jerking movements.\r\n3. Avoid using your shoulder or upper arm to lift the weight.', '{"image_male_start":"images/Forearms/wrist extension dumbbell.jpeg","video_url":"videos/Forearms/wrist extension dumbbell.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('faf775f6-55d8-4baf-8545-8e04138fcc69'::uuid, 'Zotman curl dumbbell simultaneous', 'Free Weights', 'strength', 'weight_reps', 'intermediate', 'bfdb4696-9395-413b-bf0f-675c7a90d3be'::uuid, E'1. Stand with your feet shoulder-width apart, holding a dumbbell in each hand with an underhand grip (palms facing forward) and arms hanging by your sides.\r\n2. Curl the dumbbells towards your shoulders by bending your elbows and keeping your upper arms stationary.\r\n3. At the top of the curl, rotate your wrists so that your palms face forward (overhand grip), and then lower the dumbbells back down to the starting position with control.\r\n4. Rotate your wrists back to the underhand grip once you reach the bottom of the movement. Repeat for the desired number of repetitions.', E'1. Avoid using momentum; focus on using your biceps and forearms to lift and lower the dumbbells.\r\n2. Keep your core engaged to maintain balance and stability.\r\n3. Ensure a smooth and controlled rotation of the wrists at the top of the movement.', '{}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercises (id, name, category, exercise_type, tracking_type, difficulty, equipment_id, instructions, tips, media_paths, sort_weight, source) VALUES ('feedca27-97de-41b8-a4eb-102d6131be20'::uuid, 'Zotman curls Resistance band simultaneous', 'Resistance', 'strength', 'weight_reps', 'intermediate', '0496ab82-eab1-4362-8dca-c3f5cd24f67f'::uuid, E'1. Stand with your feet shoulder-width apart, in the middle of a resistance band, holding the handles with an underhand grip (palms facing forward), arms hanging by your sides.\r\n2. Curl the handles towards your shoulders by bending your elbows and keeping your upper arms stationary.\r\n3. At the top of the curl, rotate your wrists so that your palms face forward (overhand grip), and then lower the handles back down to the starting position with control.\r\n4. Rotate your wrists back to the underhand grip once you reach the bottom of the movement. Repeat for the desired number of repetitions.', E'1. Avoid using momentum; focus on using your biceps and forearms to lift and lower the handles.\r\n2. Keep your core engaged to maintain balance and stability.\r\n3. Ensure a smooth and controlled rotation of the wrists at the top of the movement.', '{"image_male_start":"images/Biceps/zotman curls resistance band simultaneous.jpeg","video_url":"videos/Biceps/zotman curls resistance band simultaneous.mp4"}'::jsonb, 500, 'exercise_animatic') ON CONFLICT (id) DO NOTHING;
INSERT INTO training.exercise_muscles (exercise_id, muscle_group_id, role) VALUES ('00051401-a4c9-423e-aa6e-e26f387eb33b'::uuid, '1cc3ff12-e3bd-4ed2-a8ce-06ab03dbfc85'::uuid, 'secondary') ON CONFLICT DO NOTHING;
