INSERT INTO training.exercise_muscles (exercise_id, muscle_group_id, role) VALUES ('00051401-a4c9-423e-aa6e-e26f387eb33b'::uuid, 'f5138ea3-a800-461d-b398-885de815984d'::uuid, 'primary') ON CONFLICT DO NOTHING;
